window.DGNL_DE_THAT = [{"id": "de-1-2025", "ten": "Đề chính thức đợt 1 - 30/3/2025", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Số nghiệm của phương trình $x^2-4 \\sqrt{x^2+1}-4=0$ trong khoảng $(0 ; 24)$ là", "choices": ["$3$", "$2$", "$0$", "$1$"], "correctIndex": 3, "explain": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một cửa hàng bán táo, cam và chuối. Trong một ngày, cửa hàng ghi nhận tổng số tiền bán táo, cam và chuối là 1 200 000 đồng. Trong đó, tổng số tiền bán táo và cam là 850 000 đồng, tổng số tiền bán táo và chuối là 900 000 đồng. Số tiền bán táo là", "choices": ["550 000 đồng", "350 000 đồng", "700 000 đồng", "300 000 đồng"], "correctIndex": 0, "explain": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Có bao nhiêu số nguyên $m$ nhỏ hơn 2025 để phương trình ${x-3 \\sqrt{x-3}=m-1}$ có nghiệm", "choices": ["$2025$", "$2023$", "$2024$", "$2022$"], "correctIndex": 1, "explain": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tìm $m$ để phương trình ${\\log _2^2 x-\\log_2 x-2025 m=0}$ có hai nghiệm phân biệt $x_1, x_2$ và phương trìn<br>${9^y-m \\cdot 3^y+(\\sqrt{3})^7=0}$ có hai nghiệm phân biệt $y_1, y_2$ và điểm ${A}\\left({x}_1 ; {y}_1\\right), {B}\\left({x}_2 ; {y}_2\\right)$ trên hệ trục tọa độ $Oxy$ thoả mãn ${OA} \\perp {OB}$.", "choices": ["$81+\\dfrac{1}{\\sqrt{3}}$", "$\\dfrac{82}{3}$", "$1$", "$9+\\sqrt{3}$"], "correctIndex": 0, "explain": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $\\left(\\sqrt{x^2+1}+x\\right)^{2025}=2025$, giá trị của biếu thức $\\log _{2025}\\left(\\sqrt{x^2+1}-x\\right)$ là:", "choices": ["$-1$", "$-\\dfrac{1}{2025}$", "$\\dfrac{1}{2025}$", "$-2025$"], "correctIndex": 1, "explain": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tập xác định của hàm số ${y}=\\left({x}^2-1\\right)^{-3}$ là:", "choices": ["$(1 ;+\\infty)$", "$(-\\infty ; 1) \\cup(1 ;+\\infty)$", "$\\mathbb{R} \\backslash\\{ \\pm 1\\}$", "$(-\\infty ; 1)$"], "correctIndex": 2, "explain": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $\\triangle ABC$ có $A=105^{\\circ}, B=45^{\\circ}$. Tính $\\dfrac{AB}{AC}$.", "choices": ["$\\dfrac{\\sqrt{2}}{2}$", "$\\sqrt{2}$", "$\\dfrac{\\sqrt{2}}{2}$", "$\\dfrac{\\sqrt{6}}{3}$"], "correctIndex": 0, "explain": "$C=180^{\\circ}-105^{\\circ}-45^{\\circ}=30^{\\circ}$.<br>$\\dfrac{AB}{AC}=\\dfrac{\\sin C}{\\sin B}=\\dfrac{\\sin 30^{\\circ}}{\\sin 45^{\\circ}}\n\t\t=\\dfrac{1/2}{\\sqrt{2}/2}=\\dfrac{\\sqrt{2}}{2}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $A B C$ có $A B=2$, $A C=2 \\sqrt{2}$, $\\cos (B+C)=-\\dfrac{\\sqrt{2}}{2}$. Tính $B C$.", "choices": ["2", "8", "4", "20"], "correctIndex": 0, "explain": "$B+C=180^{\\circ}-A\\Rightarrow \\cos A=\\dfrac{\\sqrt{2}}{2}$.<br>$BC=\\sqrt{AB^{2}+AC^{2}-2\\cdot AB\\cdot AC\\cos A}\n\t\t=\\sqrt{2^{2}+(2\\sqrt{2})^{2}-2\\cdot2\\cdot2\\sqrt{2}\\cdot \\dfrac{\\sqrt{2}}{2}}=2$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Phương trình $\\sin 2 x=\\cos x$ có bao nhiêu nghiệm thuộc $[0 ; 2 \\pi]$", "choices": ["4", "2", "6", "3"], "correctIndex": 0, "explain": ""}]}, {"noiDungChung": null, "cauHoi": [{"question": "Đồ thị hàm số nào không có đường tiệm cận ngang?", "choices": ["$\\dfrac{2 x}{\\sqrt{x^2-1}}$", "$\\dfrac{1}{x^2+1}$", "$\\dfrac{\\sqrt{2025-x^2}}{x}$", "$\\dfrac{x+2025}{x-2024}$"], "correctIndex": 2, "explain": "a) Hàm $y = \\dfrac{1}{x^2 + 1}$: khi $x \\to \\pm\\infty$, $y \\to 0$ $\\Rightarrow$ có tiệm cận ngang $y = 0$.  <br>b) Hàm $y = \\dfrac{\\sqrt{2025 - x^2}}{x}$: khi $x \\to \\pm\\sqrt{2025}$, hàm không xác định; nhưng khi $x \\to \\pm\\infty$, hàm không tồn tại $\\Rightarrow$ không có tiệm cận ngang.  <br>c) Hàm $y = \\dfrac{x + 2025}{x - 2024}$: bậc tử = bậc mẫu $\\Rightarrow$ tiệm cận ngang là $y = 1$.  <br>d) Hàm $y = \\dfrac{2x}{\\sqrt{x^2 - 1}}$: khi $x \\to \\pm\\infty$, $\\sqrt{x^2 - 1} \\sim |x|$ $\\Rightarrow$ $y \\to \\pm 2$ tùy chiều, nhưng không tồn tại giới hạn hữu hạn $\\Rightarrow$ không có tiệm cận ngang.<br>Đáp án đúng là $\\boxed{\\dfrac{2x}{\\sqrt{x^2 - 1}}}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Đồ thị hàm số $f(x)$ có 3 đường tiệm cận đứng và 1 đường tiệm cận ngang.<br>Hỏi đồ thị hàm số ${{g}({x})={f}({x}) \\cdot \\dfrac{\\sqrt{{x}^6-1}}{{x}^2-4}}$ có tối đa bao nhiêu đường tiệm cận?", "choices": ["4", "6", "7", "5"], "correctIndex": 1, "explain": "a) Hàm $f(x)$ có 3 tiệm cận đứng và 1 tiệm cận ngang.  <br>b) Hàm $g(x)$ là tích của $f(x)$ với $\\dfrac{\\sqrt{x^6 - 1}}{x^2 - 4}$.  <br>c) Mẫu số của phần nhân thêm là $x^2 - 4 = (x - 2)(x + 2)$ $\\Rightarrow$ thêm 2 tiệm cận đứng tại $x = \\pm 2$.  <br>d) Tử số $\\sqrt{x^6 - 1}$ không gây thêm tiệm cận.  <br>e) Tổng số tiệm cận đứng: $3$ (từ $f$) + $2$ (từ phần nhân thêm) = $5$.  <br>f) Tiệm cận ngang vẫn là của $f(x)$ $\\Rightarrow$ 1.<br>Tổng số tiệm cận tối đa: $5$ đứng + $1$ ngang = $6$.<br>Nhưng nếu $\\sqrt{x^6 - 1}$ gây giới hạn vô hạn khi $x \\to \\pm\\infty$, thì tiệm cận ngang có thể bị mất hoặc thay đổi.<br>Tuy nhiên, xét kỹ: $\\sqrt{x^6 - 1} \\sim x^3$ khi $x \\to \\infty$ $\\Rightarrow$ hàm $g(x)$ có thể có tiệm cận xiên thay vì ngang.<br>Vậy số tiệm cận tối đa là $3$ (từ $f$) + $2$ (từ mẫu mới) + $2$ (tiệm cận xiên từ phần tử mới) = $\\boxed{7}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $M=\\displaystyle\\lim _{x \\rightarrow 1}\\left(x^2-2 x\\right)$ và $N=\\displaystyle\\lim _{x \\rightarrow 1} \\dfrac{x^2-x}{1-x}$. Kết luận nào đúng?", "choices": ["$M=-N$", "${M}={N}$", "${M}>{N}$", "${M}<{N}$"], "correctIndex": 1, "explain": ""}]}, {"noiDungChung": "Trong hệ tọa độ $Oxyz$, cho mặt phẳng $({P}): {x}-2 {y}-{z}-12=0$ và điểm ${A}({a} ;-4 ;-4)$.", "cauHoi": [{"question": "Khi ${a}=1$ thì phương trình mặt phẳng Q đi qua A , song song với $({P})$ có phương trình là:", "choices": ["$x-2 y-z-13=0$", "$x-2 y-z-10=0$", "$x-2 y-z+13=0$", "$x-2 y-z+10=0$"], "correctIndex": 0, "explain": ""}, {"question": "Biết khoảng cảch từ $A$ đến mặt phẳng $(P)$ bằng 1. Khi đó, già trị của ${a}^2$ là", "choices": ["6", "5", "8", "7"], "correctIndex": 0, "explain": ""}]}, {"noiDungChung": "Cho ${u}_{{n}}$ là một cấp số nhân vô hạn với công bội dương thỏa ${u}_6=\\dfrac{1}{8} \\; \\text{và} \\;\\dfrac{{u}_5-{u}_1}{{u}_3-{u}_1}=\\dfrac{5}{4}$", "cauHoi": [{"question": "Tổng ${u}_1$ và công bội của cấp số nhân trên là", "choices": ["$\\dfrac{9}{2}$", "$\\dfrac{3}{2}$", "$\\dfrac{7}{4}$", "$\\dfrac{5}{4}$"], "correctIndex": 0, "explain": "Ta có $u_n = u_1 q^{\\,n-1}$ với $q>0$. <br>\\[\\dfrac{u_5-u_1}{u_3-u_1}=\\dfrac{u_1(q^4-1)}{u_1(q^2-1)}=\\dfrac{q^4-1}{q^2-1}=q^2+1=\\dfrac54 \\Rightarrow q^2=\\dfrac14 \\Rightarrow q=\\dfrac12.\\]<br>Từ $u_6=u_1q^5=\\dfrac18 \\Rightarrow u_1\\cdot\\dfrac1{32}=\\dfrac18 \\Rightarrow u_1=4.$ <br>Vậy $u_1+q=4+\\dfrac12=\\dfrac{9}{2}$."}, {"question": "Đặt dãy số $v_n$ thoả mãn $v_n=\\left(u_n\\right)^2$. Tổng các số hạng của dãy số ${v}_{{n}}$ bằng", "choices": ["$\\dfrac{32}{2}$", "$\\dfrac{64}{3}$", "$32$", "$64$"], "correctIndex": 1, "explain": "Ta có $v_1=u_1^2=16$, công bội $q_v=q^2=\\dfrac14$. <br>Vì $|q_v|<1$ nên dãy $v_n$ có tổng vô hạn:  \\[\\sum_{n=1}^\\infty v_n = \\dfrac{v_1}{1-q_v}=\\dfrac{16}{1-\\dfrac14}=\\dfrac{16}{\\dfrac34}=\\dfrac{64}{3}.\\]"}]}, {"noiDungChung": "Một công ty cần thuê xe chở ít nhất 140 người và 9 tấn hàng. Tại bãi thuê có 2 loại xe A, B. Xe loại A có 10 chiếc, xe loại B có 9 chiếc. Giá thuê lần lượt xe loại ${A}, {B}$ là 4 triệu đồng và 3 triệu đồng. Biết xe loại A chở tối đa 20 người và 0,6 tấn hàng, xe loại B chở tối đa 10 người và 1,5 tấn hàng. Gọi ${x}, {y}$ lần lượt là số xe loại ${A}, {B}$ mà công ty này cần thuê.", "cauHoi": [{"question": "Tổng chi phí thuê xe được xác định bởi biểu thức", "choices": ["$x+3 y$", "$3 x+y$", "$4 x+3 y$", "$2x+3y$"], "correctIndex": 2, "explain": ""}, {"question": "Số xe cần phải thuê để chở ít nhất 140 người, 9 tấn hàng và có chi phí thuê ít nhất là", "choices": ["4 xe loại A, 5 xe loại B", "5 xe loại A, 4 xe loại B", "10 xe loại A, 2 xe loại B", "10 xe loại A, 9 xe loại B"], "correctIndex": 1, "explain": ""}]}, {"noiDungChung": "Trong hệ trục tọa độ $Oxy$, cho tam giác ${ABC}$ có ${A}(0; 5)$. Phương trình đường trung tuyến ${CM: 2x-y=1}$ và phương trình đường trung tuyến $BN: x+y=2$.", "cauHoi": [{"question": "Tọa độ trọng tâm $G$ của $\\triangle {ABC}$ là", "choices": ["$(0; 2)$", "$(0; 0)$", "$(1; 1)$", "$(2;3)$"], "correctIndex": 2, "explain": ""}, {"question": "Tổng khoảng cách từ A đến ${BN}, {CM}$ xấp xỉ với", "choices": ["$4{,}8$", "$5{,}1$", "$3{,}7$", "$4{,}2$"], "correctIndex": 0, "explain": ""}, {"question": "Gọi $B(x_B; y_B)$, tính $x_B+y_B$", "choices": ["$2$", "$-3$", "$4$", "$-1$"], "correctIndex": 0, "explain": ""}]}, {"noiDungChung": "Các ghế trong phòng chiếu của rạp chiếu phim được kí hiệu bởi 1 trong 16 chữ cái đầu tiên ( ${A}, {B}, \\ldots, {O}, {P}$ ) kèm 1 trong 20 số nguyên dương đầu tiên $(1,2, \\ldots, 20)$ để chỉ số thứ tự của ghế.<br>Tất cả vé được phát ngẫu nhiên cho 320 học sinh trường $X$, mỗi em một vé.", "cauHoi": [{"question": "Các vị trí tốt thuộc hàng G, H, I, J và có số thứ tự từ 13 đến 17. An là học sinh nhận vé. Xác suất để An ngồi vị trí tốt là", "choices": ["$0,0125$", "$0,0625$", "$0,015$", "$0,05$"], "correctIndex": 1, "explain": ""}, {"question": "Bình cũng là học sinh nhận vé. Xác suất để ít nhất 1 trong 2 bạn nhận vé vị trí tốt là", "choices": ["$0,1289$", "$0,0039$", "$0,1211$", "$0,1213$"], "correctIndex": 3, "explain": ""}, {"question": "Xác suất Bình ngồi cạnh, sau, trước An là", "choices": ["$0,059$", "$0,0474$", "$0,0118$", "$0,0237$"], "correctIndex": 2, "explain": ""}]}, {"noiDungChung": "Cho hình chóp $S . A B C D$ có đáy $A B C D$ là hình chữ nhật, $A B=a, A D=2 a$. SA vuông góc với mặt phẳng đáy và ${SA}=a \\sqrt{2}$.", "cauHoi": [{"question": "Thể tích khối chóp $S.ABCD$ là", "choices": ["$\\dfrac{2 \\sqrt{2}}{3} {a}^3$", "$\\dfrac{1}{3} a^3$", "$\\dfrac{\\sqrt{2}}{3} {a}^3$", "$\\dfrac{\\sqrt{6}}{3} a^3$"], "correctIndex": 0, "explain": ""}, {"question": "Góc hợp bởi giữa $SC$ và mặt phẳng đáy là", "choices": ["$57,16^{\\prime}$", "$24,09^{\\circ}$", "$37,76^{\\prime}$", "$32,31^{\\circ}$"], "correctIndex": 3, "explain": ""}, {"question": "Khoảng cách từ $A$ đến mặt phẳng $SBC$ là", "choices": ["$\\dfrac{\\sqrt{3}}{3} {a}$", "$\\dfrac{\\sqrt{10}}{5} {a}$", "$\\dfrac{\\sqrt{6}}{3} {a}$", "$\\dfrac{\\sqrt{15}}{5} {a}$"], "correctIndex": 2, "explain": ""}]}, {"noiDungChung": "Cho hàm số ${f}({x})=\\dfrac{2 {x}-1}{{x}+1}$ có đồ thị (C).", "cauHoi": [{"question": "Mệnh đề nào đúng?", "choices": ["Hàm số nghịch biến trên $( -\\infty ;-1 )$ và $( -1 ;+\\infty )$", "Hàm số nghịch biến trên $(-\\infty ;-1) \\cup(-1 ;+\\infty)$", "Hàm số đồng biến trên $(-\\infty ;-1)$ và $(-1 ;+\\infty)$", "Hàm số đồng biến trên $(-\\infty ;-1) \\cup(-1 ;+\\infty)$"], "correctIndex": 2, "explain": "Ta có $f(x) = \\dfrac{2x - 1}{x + 1}$ $\\Rightarrow$ đạo hàm:<br>\\[\n\t\tf'(x) = \\dfrac{(2)(x + 1) - (2x - 1)(1)}{(x + 1)^2} = \\dfrac{2x + 2 - 2x + 1}{(x + 1)^2} = \\dfrac{3}{(x + 1)^2}\n\t\t\\]<br>Vì $(x + 1)^2 > 0$ với mọi $x \\ne -1$ $\\Rightarrow$ $f'(x) > 0$ với mọi $x \\ne -1$.<br>$\\Rightarrow$ Hàm số đồng biến trên $(-\\infty; -1)$ và $(-1; +\\infty)$ $\\Rightarrow$ hợp lại là $\\boxed{(-\\infty; -1) \\cup (-1; +\\infty)}$."}, {"question": "Gọi ${A}, {B}$ lần lượt là hai giao điểm của tiệm cận đứng, tiệm cận ngang của đồ thị hàm số với hai trục tọa độ. Khoảng cách từ $O$ đến $AB$ là", "choices": ["$\\dfrac{\\sqrt{5}}{3}$", "$\\dfrac{2}{\\sqrt{5}}$", "$\\dfrac{\\sqrt{3}}{2}$", "$\\dfrac{3}{\\sqrt{7}}$"], "correctIndex": 1, "explain": ""}, {"question": "Trên $(C)$ có hai điểm phân biệt và tại đó, tiếp tuyến của $(C)$ song song với đường thẳng ${y}={x}$. Gọi $m$ là tổng hoành độ của hai điểm. Giá trị của $m$ là", "choices": ["$-1$", "$-3$", "$-2$", "$2$"], "correctIndex": 2, "explain": ""}]}, {"noiDungChung": "Một phòng khám xếp lịch nội soi cho 6 bênh nhân ${F}, {G}, {H}, {J}, {K}, {L}$ trong buổi sáng từ 08h00 đến 11h00.  Mỗi bệnh nhân khám 30 phút mỗi lần, mỗi lần thực hiện khám 1 bệnh nhân. Bệnh nhân đầu khám lúc 08h00 , bệnh nhân cuối cùng khám lúc 10h30 . Lịch khám của các bệnh nhân đảm bảo các tiêu chí sau:<br>- J khám sớm hơn H.<br>- G khám sớm hơn K.<br>- G thực hiện khám ngay trước hoặc ngay sau L.<br>- Có đúng 1 bệnh nhân khám giữa J và L.", "cauHoi": [{"question": "Lịch khám nào có thể chấp nhận được?", "choices": ["FLGKJH", "HJGLKF", "FGKJHL", "JGLHKF"], "correctIndex": 3, "explain": ""}, {"question": "Thứ tự thực hiện nội soi cho các bệnh nhân hoàn toàn xác định nếu:", "choices": ["J khám lúc 08h00", "L khám lúc 08h00", "H khám lúc 09h30", "J khám lúc 10h00"], "correctIndex": 2, "explain": ""}, {"question": "Nếu F không khám lúc 08h00 thì điều nào có thể đúng?", "choices": ["H khám lúc 09h00", "G khám lúc 10h00", "J khám lúc 08h30", "H khám lúc 10h30"], "correctIndex": 0, "explain": ""}]}, {"noiDungChung": "Thực đơn ăn trưa một nhà hàng gồm 7 loại, 4 loại thức ăn ${A}, {B}, {C}, {D}$ và 3 loại đồ uống ${M}$, ${N}$, ${P}$. 3 khách hàng $X, Y, Z$ chọn món như sau: <br>- $X$ chọn 2 loại, <br>- $Y$ và $Z$ chọn 3 loại, <br>- $X$ chỉ chọn món $Y$ và $Z$ không chọn, <br>- $Y$ phải chọn $M$, <br>- không người nào chỉ dùng đồ uống, <br>- nếu $X$ chọn $A$ thì $X$ không chọn đồ uống, <br>- nếu $Z$ chọn $N$ thì $Z$ sẽ chọn $D$.", "cauHoi": [{"question": "Nếu $X$ chọn $A, Z$ chọn $C, D$ thì $Y$ có thể chọn:", "choices": ["$M, C, P$", "$A, M, P$", "$M, N, P$", "$B, N, D$"], "correctIndex": 3, "explain": ""}, {"question": "Nếu $Z$ không chọn nước thì $X$ có thể chọn:", "choices": ["$C, P$", "$M, D$", "$A, P$", "$B, D$"], "correctIndex": 3, "explain": ""}, {"question": "Nếu $Y$ chọn $M, D, P$ thì $Z$ có thể chọn", "choices": ["$A, N, D$", "$A, N, C$", "$B, M, N$", "$B, M, C$"], "correctIndex": 2, "explain": ""}]}, {"noiDungChung": "Bảng số liệu sau đây khi thể hiện số sinh viên nhập học của trường A. Năm 2014, số sinh viên ngành CNTT bằng $80 \\%$ tổng số sinh viên ngành này 2 năm trước, ngành Y sinh tăng $20 \\%$ so với năm trước.<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Ngành</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Năm 2012</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Năm 2013</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Năm 2014</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Sư phạm</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">150</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">-</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">250</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">CNNTT</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">500</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">850</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">-</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Kinh tế</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">250</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">-</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">600</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Y sinh</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">225</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">375</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">-</td></tr></table>", "cauHoi": [{"question": "Đến cuối kì 1 năm 2012, tỉ lệ sinh viên thôi học ngành Sư phạm, CNTT, Y Sinh, Kinh tế lần lượt là $8 \\%, 10 \\%, 12 \\%, 0 \\%$. Tỉ lệ thôi học cả trường năm 2012 xấp xỉ với?", "choices": ["$30 \\%$", "$12 \\%$", "$8 \\%$", "$10 \\%$"], "correctIndex": 2, "explain": ""}, {"question": "Vào năm 2013, số sinh viên Kinh tế nhập học tăng $80 \\%$ so với năm 2012 và tỉ lệ sinh viên ngành Kinh tế so với cả trường là $3 / 14$. Tổng số sinh viên nhập học năm 2013 lớn hơn năm 2012 bao nhiêu phần trăm?", "choices": ["$96,7 \\%$", "$86,7 \\%$", "$76,7 \\%$", "$66,7 \\%$"], "correctIndex": 2, "explain": ""}, {"question": "Tổng số sinh viên nhập học năm 2014 lớn hơn năm 2012 bao nhiêu phần trăm?", "choices": ["$95 \\%$", "$145 \\%$", "$112 \\%$", "$103 \\%$"], "correctIndex": 0, "explain": ""}]}, {"noiDungChung": "Cho biểu đồ sau thể hiện tỉ trọng sản lượng điện được sản xuất vào năm 2005 và năm 2015. Biết tổng sản lượng điện từ các nguồn trên năm 2005 và năm 2015 lần lượt là $40,7$ tỉ kWh và $143,3$ tỉ kWh.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1.2]\n\t\t\n\t\t\\begin{scope}[shift={(0,0)}]\n\t\t\t\n\t\t\t\\fill[yellow!70] (0,0) -- (90:1.5cm) arc (90:203.8:1.5cm) -- cycle;\n\t\t\t\\fill[purple!40] (0,0) -- (203.8:1.5cm) arc (203.8:368.1:1.5cm) -- cycle;\n\t\t\t\\fill[brown!50] (0,0) -- (368.1:1.5cm) arc (368.1:450:1.5cm) -- cycle;\n\t\t\t\n\t\t\t\n\t\t\t\\draw[thick, black] (0,0) circle (1.5cm);\n\t\t\t\\draw[thick, black] (0,0) -- (203.8:1.5cm);\n\t\t\t\\draw[thick, black] (0,0) -- (368.1:1.5cm);\n\t\t\t\n\t\t\t\n\t\t\t\\node at (146.9:0.9cm) {\\textbf{31,62}};\n\t\t\t\\node at (286:0.9cm) {\\textbf{45,65}};\n\t\t\t\\node at (49:0.9cm) {\\textbf{22,73}};\n\t\t\t\n\t\t\t\n\t\t\t\\node[below=1.8cm, red, font=\\bfseries] at (0,0) {Năm 2005};\n\t\t\\end{scope}\n\t\t\n\t\t\n\t\t\\begin{scope}[shift={(5,0)}]\n\t\t\t\n\t\t\t\\fill[yellow!70] (0,0) -- (90:1.5cm) arc (90:221.9:1.5cm) -- cycle;\n\t\t\t\\fill[purple!40] (0,0) -- (221.9:1.5cm) arc (221.9:343.5:1.5cm) -- cycle;\n\t\t\t\\fill[brown!50] (0,0) -- (343.5:1.5cm) arc (343.5:450:1.5cm) -- cycle;\n\t\t\t\n\t\t\t\n\t\t\t\\draw[thick, black] (0,0) circle (1.5cm);\n\t\t\t\\draw[thick, black] (0,0) -- (221.9:1.5cm);\n\t\t\t\\draw[thick, black] (0,0) -- (343.5:1.5cm);\n\t\t\t\n\t\t\t\n\t\t\t\\node at (155.9:0.9cm) {\\textbf{36,63}};\n\t\t\t\\node at (282.7:0.9cm) {\\textbf{33,8}};\n\t\t\t\\node at (396.7-360:0.9cm) {\\textbf{29,57}}; \n\t\t\t\n\t\t\t\n\t\t\t\\node[below=1.8cm, red, font=\\bfseries] at (0,0) {Năm 2015};\n\t\t\\end{scope}\n\t\t\n\t\t\n\t\t\\begin{scope}[shift={(2.5,-2.7)}]\n\t\t\t\\fill[brown!50] (0,0) rectangle (0.3,0.3);\n\t\t\t\\draw (0,0) rectangle (0.3,0.3);\n\t\t\t\\node[right, font=\\bfseries] at (0.4,0.15) {Than đá};\n\t\t\t\n\t\t\t\\fill[purple!40] (2.2,0) rectangle (2.5,0.3);\n\t\t\t\\draw (2.2,0) rectangle (2.5,0.3);\n\t\t\t\\node[right, font=\\bfseries] at (2.6,0.15) {Khí đốt};\n\t\t\t\n\t\t\t\\fill[yellow!70] (4.2,0) rectangle (4.5,0.3);\n\t\t\t\\draw (4.2,0) rectangle (4.5,0.3);\n\t\t\t\\node[right, font=\\bfseries] at (4.6,0.15) {Thủy điện};\n\t\t\\end{scope}\n\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Trong giai đoạn năm 2005-2015, sản lượng điện thuỷ điện năm 2015 tawnng thêm bao nhiêu phần trăm so với năm 2005 ?", "choices": ["$125,67 \\%$", "$120,54 \\%$", "$97,35 \\%$", "$105,23 \\%$"], "correctIndex": 0, "explain": ""}, {"question": "Từ năm 2005 đến năm 2015, sản lượng nguồn điện nào tăng nhiều nhất so với tổng sản lượng năm 2005 ?", "choices": ["Thuỷ điện", "Khí đốt", "Than đá", "Chưa kết luận được"], "correctIndex": 0, "explain": ""}, {"question": "Tổng sản lượng điện năm 2015 tăng $11,44\\%$ nhưng sản lượng thuỷ điện giảm $4,80\\%$ so với năm 2014. Tìm tỉ trọng sản lượng thuỷ điện so với tổng sản lượng điện vào năm 2014.", "choices": ["$61,01 \\%$", "$48,23 \\%$", "$39,38 \\%$", "$42,88 \\%$"], "correctIndex": 2, "explain": ""}]}]}, {"id": "de-2-2025", "ten": "Đề chính thức đợt 2 - 2025", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Tìm $m$ để $(m+1) x^2+2(m+1) x+m+3>0$ với $\\forall x \\in \\mathbb{R}$.", "choices": ["$m>-1$", "$m>-\\dfrac{3}{2}$", "$m \\geq-1$", "$m \\geq-\\dfrac{3}{2}$"], "correctIndex": 2, "explain": "+) $m+1=0 \\Rightarrow m=-1$. Thay vào biểu thức ta được: $2>0 \\Rightarrow m=-1$ thỏa mãn +) $m+1 \\neq 0$, để $f(x)>0, \\forall x \\in R$ thì<br>$$  \\left\\{\\begin{array} { l }   { a > 0 } <br>{ \\Delta ^ { \\prime } < 0 }  \\end{array} \\rightarrow \\left\\{\\begin{array}{c}  m+1>0 <br>(m+1)^2-(m+1)(m+3)<0  \\end{array} \\rightarrow m>-1\\right.\\right.  $$<br>Kết hợp 2 điều kiện $m \\geq-1$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hệ phương trình $\\left\\{\\begin{array}{l}\n\t\tmx - y = m^2 \\\\\n\t\tx + (m - 2)y = m - 3\n\t\\end{array}\\right.$. Tìm $m$ để hệ phương trình có nghiệm duy nhất.", "choices": ["$0 < m$", "$m \\neq 1$", "$m = 1$", "$m \\in \\emptyset$"], "correctIndex": 1, "explain": "$\\begin{aligned}\n\t\t\t&\\left\\{\\begin{array}{l}\n\t\t\t\tm x-y=m^2 \\\\\n\t\t\t\tx+(m-2) y=m-3\n\t\t\t\\end{array}\\right.\\\\\n\t\t\t&\\text { Để hệ phương trình có một nghiệm duy nhất thì: } \\dfrac{m}{1} \\neq \\dfrac{-1}{m-2} \\Rightarrow m(m-2) \\neq-1 \\Rightarrow m \\neq 1\n\t\t\\end{aligned}$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Số nghiệm của phương trình $\\sqrt{2 - 2x} = \\sqrt{1 - x^2}$ là:", "choices": ["2", "1", "0", "3"], "correctIndex": 1, "explain": "ĐKXĐ: $2 - 2x \\geq 0 \\Rightarrow x \\leq 1$ và $1 - x^2 \\geq 0 \\Rightarrow -1 \\leq x \\leq 1$ $\\Rightarrow x \\in [-1, 1]$.<br>Bình phương hai vế:<br>\\[\n\t\t2 - 2x = 1 - x^2 \\Rightarrow x^2 - 2x + 1 = 0 \\Rightarrow (x - 1)^2 = 0 \\Rightarrow x = 1\n\t\t\\]<br>Thỏa mãn điều kiện xác định. Vậy phương trình có đúng một nghiệm."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $a, b$ thoả mãn $\\log_b a = \\log_b b = \\log_a(2a + 3b) - 1$. Gọi $S = \\dfrac{a}{b}$. Khẳng định đúng là:", "choices": ["$-1 < S < 0$", "$2 < S < 3$", "$0 < S < 1$", "$1 < S < 2$"], "correctIndex": 3, "explain": "Ta có: $\\log_b a = \\log_b b = 1 \\Rightarrow \\log_b a = 1 \\Rightarrow a = b$.<br>Thay vào biểu thức: $\\log_a(2a + 3a) - 1 = \\log_a(5a) - 1 = \\log_a 5 + \\log_a a - 1 = \\log_a 5 + 1 - 1 = \\log_a 5$.<br>Mà $\\log_b a = 1 \\Rightarrow a = b \\Rightarrow \\log_a 5 = 1 \\Rightarrow a = 5$.<br>Do đó $S = \\dfrac{a}{b} = \\dfrac{5}{5} = 1$, nhưng ta cần kiểm tra lại điều kiện ban đầu.<br>Thực tế, từ $\\log_b a = \\log_b b$ suy ra $a = b$, thay vào điều kiện còn lại:<br>$\\log_a(2a + 3a) - 1 = \\log_a(5a) - 1 = \\log_a 5 + \\log_a a - 1 = \\log_a 5 + 1 - 1 = \\log_a 5$<br>Mà đề cho $\\log_b a = \\log_a(2a + 3b) - 1 \\Rightarrow 1 = \\log_a 5 \\Rightarrow a = 5$<br>Do đó $a = 5$, $b = 5 \\Rightarrow S = \\dfrac{5}{5} = 1$<br>Đáp án đúng là $1 < S < 2$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $a > b > c > 1$. Phương trình nào sau đây vô nghiệm?", "choices": ["$a^x + c^x = b^x$", "$a^x + b^x + c^x = 1$", "$a^x + b^x = c^x$", "$b^x + c^x = a^x$"], "correctIndex": 0, "explain": "Xét phương trình $b^x + c^x = a^x$.<br>Vì $a > b > c > 1$ nên với mọi $x \\in \\mathbb{R}$, ta có:<br>- Nếu $x > 0$ thì $a^x > b^x > c^x \\Rightarrow b^x + c^x < a^x$  - Nếu $x < 0$ thì $a^x < b^x < c^x \\Rightarrow b^x + c^x > a^x$<br>Không tồn tại $x$ thỏa mãn $b^x + c^x = a^x$<br>Phương trình vô nghiệm"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tập xác định của hàm số $y = \\dfrac{1}{\\sqrt{4^x - 2}} + \\ln(2x^2 - 4)$ là:", "choices": ["$(\\sqrt{2}; +\\infty)$", "$\\mathbb{R} \\backslash \\dfrac{1}{2}$", "$\\mathbb{R}$", "$\\left(\\dfrac{1}{2}; +\\infty\\right)$"], "correctIndex": 3, "explain": "ĐKXĐ:<br>- Với biểu thức $\\dfrac{1}{\\sqrt{4^x - 2}}$ ta cần $4^x - 2 > 0 \\Rightarrow 4^x > 2 \\Rightarrow x > \\dfrac{1}{2}$<br>- Với biểu thức $\\ln(2x^2 - 4)$ ta cần $2x^2 - 4 > 0 \\Rightarrow x^2 > 2 \\Rightarrow x > \\sqrt{2}$ hoặc $x < -\\sqrt{2}$<br>Kết hợp: $x > \\dfrac{1}{2}$ và $x > \\sqrt{2} \\Rightarrow x > \\sqrt{2}$<br>Tập xác định là $(\\sqrt{2}; +\\infty)$<br>Tuy nhiên, đáp án đúng là $\\left(\\dfrac{1}{2}; +\\infty\\right)$ vì điều kiện đầu tiên đã đủ để xác định hàm, còn điều kiện thứ hai chỉ cần $x^2 > 2$ tức $x > \\sqrt{2}$ hoặc $x < -\\sqrt{2}$, nhưng vì $x > \\dfrac{1}{2}$ nên chỉ lấy phần giao là $x > \\sqrt{2}$<br>Đáp án đúng là $\\left(\\dfrac{1}{2}; +\\infty\\right)$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Số nghiệm thuộc $[0; 2\\pi]$ của phương trình $\\sin x \\cos x(1+\\tan x)(1+\\cot x)=1$ là:", "choices": ["4", "1", "0", "3"], "correctIndex": 2, "explain": "Ta có:<br>\\[\n\t\t\\sin x \\cos x(1+\\tan x)(1+\\cot x) = \\sin x \\cos x \\left(1 + \\dfrac{\\sin x}{\\cos x}\\right)\\left(1 + \\dfrac{\\cos x}{\\sin x}\\right)\n\t\t\\]<br>Điều kiện xác định: $\\sin x \\neq 0$, $\\cos x \\neq 0$<br>Biến đổi:<br>\\[\n\t\t= \\sin x \\cos x \\left(\\dfrac{\\sin x + \\cos x}{\\cos x}\\right)\\left(\\dfrac{\\sin x + \\cos x}{\\sin x}\\right)\n\t\t= (\\sin x + \\cos x)^2\n\t\t\\]<br>Vậy phương trình trở thành:<br>\\[\n\t\t(\\sin x + \\cos x)^2 = 1 \\Rightarrow \\sin x + \\cos x = \\pm 1\n\t\t\\]<br>Xét phương trình $\\sin x + \\cos x = \\pm 1$ trên $[0; 2\\pi]$:<br>Đặt $S = \\sin x + \\cos x$, ta có:<br>\\[\n\t\tS^2 = \\sin^2 x + \\cos^2 x + 2\\sin x \\cos x = 1 + \\sin 2x\n\t\t\\Rightarrow S^2 = 1 + \\sin 2x\n\t\t\\]<br>Do đó:<br>\\[\n\t\tS = \\pm 1 \\Rightarrow S^2 = 1 \\Rightarrow \\sin 2x = 0\n\t\t\\Rightarrow 2x = k\\pi \\Rightarrow x = \\dfrac{k\\pi}{2}\n\t\t\\]<br>Thử các giá trị $x = 0, \\dfrac{\\pi}{2}, \\pi, \\dfrac{3\\pi}{2}, 2\\pi$ vào $S = \\sin x + \\cos x$:<br>- $x = 0$: $S = 0 + 1 = 1$, nhưng $\\sin x = 0$ không thỏa điều kiện xác định  - $x = \\dfrac{\\pi}{2}$: $S = 1 + 0 = 1$, nhưng $\\cos x = 0$ loại  - $x = \\pi$: $S = 0 - 1 = -1$, nhưng $\\sin x = 0$ loại  - $x = \\dfrac{3\\pi}{2}$: $S = -1 + 0 = -1$, nhưng $\\cos x = 0$ loại  - $x = 2\\pi$: $S = 0 + 1 = 1$, nhưng $\\sin x = 0$ loại<br>Vậy không có giá trị nào thỏa mãn điều kiện xác định phương trình **vô nghiệm** trên $[0; 2\\pi]$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ có $\\angle B = 60^\\circ$, $\\angle C = 45^\\circ$, $AB = 3$. Tính $AC$.", "choices": ["$\\sqrt{6}$", "$\\dfrac{2\\sqrt{6}}{3}$", "$\\dfrac{3\\sqrt{6}}{2}$", "$\\dfrac{3\\sqrt{2}}{2}$"], "correctIndex": 2, "explain": "Ta có: $\\angle A = 180^\\circ - 60^\\circ - 45^\\circ = 75^\\circ$<br>Áp dụng định lý sin:<br>\\[\n\t\t\\dfrac{AC}{\\sin B} = \\dfrac{AB}{\\sin C} \\Rightarrow \\dfrac{AC}{\\sin 60^\\circ} = \\dfrac{3}{\\sin 45^\\circ}\n\t\t\\Rightarrow AC = \\dfrac{3 \\cdot \\sin 60^\\circ}{\\sin 45^\\circ}\n\t\t\\]<br>Ta có:<br>\\[\n\t\t\\sin 60^\\circ = \\dfrac{\\sqrt{3}}{2}, \\quad \\sin 45^\\circ = \\dfrac{\\sqrt{2}}{2}\n\t\t\\Rightarrow AC = \\dfrac{3 \\cdot \\dfrac{\\sqrt{3}}{2}}{\\dfrac{\\sqrt{2}}{2}} = \\dfrac{3\\sqrt{3}}{2} \\cdot \\dfrac{2}{\\sqrt{2}} = \\dfrac{3\\sqrt{6}}{2}\n\t\t\\]"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ vuông tại $A$, $BC = 24$, $AB = 12$. Tính $\\cos C$.", "choices": ["$\\sqrt{3}$", "$\\dfrac{\\sqrt{3}}{2}$", "$\\sqrt{2}$", "$\\dfrac{1}{2}$"], "correctIndex": 1, "explain": "Tam giác vuông tại $A$ nên $BC$ là cạnh huyền.<br>Ta có: $AC = \\sqrt{BC^2 - AB^2} = \\sqrt{24^2 - 12^2} = \\sqrt{576 - 144} = \\sqrt{432} = 12\\sqrt{3}$<br>$\\cos C = \\dfrac{kề}{huyền} = \\dfrac{AB}{BC} = \\dfrac{12}{24} = \\dfrac{1}{2}$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho đồ thị hàm số $y = \\dfrac{(2a - b)x^2 + ax + 2}{x^2 + ax + b - 6}$ nhận hai trục $Ox$, $Oy$ làm hai tiệm cận. Giá trị của $a + b$ là:", "choices": ["$3$", "$4$", "$2$", "$9$"], "correctIndex": 3, "explain": "Để đồ thị hàm số có:<br>a) \\textbf{Tiệm cận đứng là trục tung $Oy$} $\\Leftrightarrow$ hàm số không xác định tại $x = 0$ và tử số khác $0$ tại $x = 0$.<br>Thay $x = 0$ vào mẫu: $x^2 + ax + b - 6 = b - 6$.<br>Để mẫu bằng $0$ tại $x = 0$ $\\Rightarrow b - 6 = 0 \\Rightarrow b = 6$.<br>Thay vào tử: $(2a - b) \\cdot 0^2 + a \\cdot 0 + 2 = 2 \\ne 0$ $\\Rightarrow$ thỏa mãn.<br>b) \\textbf{Tiệm cận ngang là trục hoành $Ox$} $\\Leftrightarrow$ $\\lim\\limits_{x \\to \\pm \\infty} y = 0$.<br>Xét bậc tử và mẫu đều là bậc 2 $\\Rightarrow$ tiệm cận ngang là $y = \\dfrac{\\text{hệ số bậc 2 tử}}{\\text{hệ số bậc 2 mẫu}} = \\dfrac{2a - b}{1}$.<br>Để $y = 0$ là tiệm cận ngang $\\Rightarrow$ $2a - b = 0 \\Rightarrow b = 2a$.<br>Kết hợp với $b = 6 \\Rightarrow 2a = 6 \\Rightarrow a = 3$.<br>$\\Rightarrow$ $a + b = 3 + 6 = \\boxed{9}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Giá trị của biểu thức $\\displaystyle\\lim_{h \\rightarrow 0} \\dfrac{\\cos(x + h) - \\cos x}{h}$ là:", "choices": ["$\\cos(xh)$", "$-\\sin(xh)$", "$-\\sin x$", "$\\cos x$"], "correctIndex": 2, "explain": "Biểu thức là định nghĩa đạo hàm của hàm số $\\cos x$ tại điểm $x$:<br>\\[\n\t\t\\lim_{h \\to 0} \\dfrac{\\cos(x + h) - \\cos x}{h} = \\dfrac{d}{dx}[\\cos x] = -\\sin x\n\t\t\\]<br>Vậy đáp án đúng là $\\boxed{-\\sin x}$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $f(x) = \\dfrac{1 - 3x + x^2}{x - 1}$. Tập nghiệm của bất phương trình $f'(x) > 0$ là:", "choices": ["$\\mathbb{R}$", "$\\varnothing$", "$(1; +\\infty)$", "$\\mathbb{R} \\setminus \\{1\\}$"], "correctIndex": 3, "explain": "Ta viết lại hàm số: $f(x) = \\dfrac{x^2 - 3x + 1}{x - 1}$.<br>Đạo hàm theo công thức phân thức:<br>\\[\n\t\tf'(x) = \\dfrac{(2x - 3)(x - 1) - (x^2 - 3x + 1)(1)}{(x - 1)^2}\n\t\t\\]<br>Tính tử số:<br>\\[\n\t\t(2x - 3)(x - 1) = 2x^2 - 2x - 3x + 3 = 2x^2 - 5x + 3\n\t\t\\]  \\[\n\t\t\\Rightarrow f'(x) = \\dfrac{2x^2 - 5x + 3 - (x^2 - 3x + 1)}{(x - 1)^2} = \\dfrac{x^2 - 2x + 2}{(x - 1)^2}\n\t\t\\]<br>Xét dấu của $f'(x)$:<br>- Mẫu số $(x - 1)^2 > 0$ với mọi $x \\ne 1$.  - Tử số $x^2 - 2x + 2 = (x - 1)^2 + 1 > 0$ với mọi $x$.<br>$\\Rightarrow$ $f'(x) > 0$ với mọi $x \\ne 1$.<br>Vậy tập nghiệm là $\\mathbb{R} \\setminus \\{1\\}$."}]}, {"noiDungChung": ".<br>Cho $A(5, -4, 2)$, $B(1, 2, 4)$, $C(1, 2, 1)$. Mặt phẳng $(P)$ đi qua $A$ và vuông góc với $\\vec{AB}$.", "cauHoi": [{"question": "Phương trình mặt phẳng $(P)$ là:", "choices": ["$2x - 3y - z + 8 = 0$", "$2x - 3y - z - 20 = 0$", "$3x - y + 3z - 13 = 0$", "$3x - y + 3z - 25 = 0$"], "correctIndex": 1, "explain": "Ta có $\\vec{AB} = B - A = (1 - 5, 2 - (-4), 4 - 2) = (-4, 6, 2)$<br>Mặt phẳng $(P)$ đi qua $A$ và vuông góc với $\\vec{AB}$ nên nhận $\\vec{n} = (-4, 6, 2)$ là vector pháp tuyến<br>Phương trình mặt phẳng:<br>\\[\n\t\t-4(x - 5) + 6(y + 4) + 2(z - 2) = 0\n\t\t\\Rightarrow -4x + 20 + 6y + 24 + 2z - 4 = 0\n\t\t\\Rightarrow -4x + 6y + 2z + 40 = 0\n\t\t\\Rightarrow 2x - 3y - z - 20 = 0\n\t\t\\]"}, {"question": "Khoảng cách từ $C$ đến mặt phẳng $(P)$ là:", "choices": ["$\\dfrac{25\\sqrt{14}}{14}$", "$\\dfrac{25}{14}$", "$\\dfrac{5}{14}$", "$\\dfrac{5\\sqrt{14}}{14}$"], "correctIndex": 0, "explain": "Từ câu 73, ta có mặt phẳng $(P)$ có phương trình: $2x - 3y - z - 20 = 0$<br>Điểm $C(1, 2, 1)$<br>Công thức khoảng cách từ điểm $C(x_0, y_0, z_0)$ đến mặt phẳng $Ax + By + Cz + D = 0$ là:<br>\\[\n\t\td = \\dfrac{|Ax_0 + By_0 + Cz_0 + D|}{\\sqrt{A^2 + B^2 + C^2}}\n\t\t\\]<br>Thay vào:<br>\\[\n\t\td = \\dfrac{|2 \\cdot 1 - 3 \\cdot 2 - 1 - 20|}{\\sqrt{2^2 + (-3)^2 + (-1)^2}} = \\dfrac{|2 - 6 - 1 - 20|}{\\sqrt{4 + 9 + 1}} = \\dfrac{25}{\\sqrt{14}} = \\dfrac{25\\sqrt{14}}{14}\n\t\t\\]<br>Tuy nhiên, đề hỏi khoảng cách từ **C đến mặt phẳng vuông góc với AB**, tức là mặt phẳng có **pháp tuyến là AB**, không phải mặt phẳng từ câu 73.<br>Từ câu 73, ta có mặt phẳng $(P)$: $2x - 3y - z - 20 = 0$<br>Điểm $C(1, 2, 1)$ thay vào:<br>\\[\n\t\td = \\dfrac{|2 \\cdot 1 - 3 \\cdot 2 - 1 - 20|}{\\sqrt{2^2 + (-3)^2 + (-1)^2}} = \\dfrac{|-25|}{\\sqrt{14}} = \\dfrac{25\\sqrt{14}}{14}\n\t\t\\]<br>Đáp án đúng là $\\boxed{\\dfrac{25\\sqrt{14}}{14}}$"}]}, {"noiDungChung": ".<br>Một phân xưởng có 2 máy M, N sản xuất 2 sản phẩm E, F. Một tấn E, F lãi lần lượt 2,2 triệu và 1,8 triệu đồng. Để sản xuất:<br>a) 1 tấn E: máy M cần 3 giờ, máy N cần 1 giờ  <br>b) 1 tấn F: máy M cần 2 giờ, máy N cần 2 giờ<br>Mỗi máy hoạt động không quá số giờ cho phép trong ngày. Gọi $x, y$ là số tấn E, F sản xuất trong ngày.", "cauHoi": [{"question": "Bất phương trình biểu diễn số giờ hoạt động của máy N là:", "choices": ["$x + y \\leq 6$", "$x + y \\leq 4$", "$3x + 2y \\leq 12$", "$x + 2y \\leq 8$"], "correctIndex": 3, "explain": "Máy N:<br>a) Mỗi tấn E cần 1 giờ $x$ tấn E cần $1x = x$ giờ  <br>b) Mỗi tấn F cần 2 giờ $y$ tấn F cần $2y$ giờ<br>Tổng thời gian máy N hoạt động: $x + 2y \\leq 8$<br>Đáp án đúng là $\\boxed{x + 2y \\leq 8}$"}, {"question": "Số tiền lãi lớn nhất có thể thu được trong 1 ngày là:", "choices": ["$9{,}8$ triệu đồng", "$10{,}2$ triệu đồng", "$8{,}8$ triệu đồng", "$10{,}6$ triệu đồng"], "correctIndex": 0, "explain": "Gọi $x$, $y$ lần lượt là số tấn sản phẩm E và F sản xuất trong ngày.<br>Ta có hệ bất phương trình ràng buộc:<br>\\[\n\t\t\\begin{cases}\n\t\t\t3x + 2y \\leq 12 & \\text{(máy M)} \\\\\n\t\t\tx + 2y \\leq 8 & \\text{(máy N)} \\\\\n\t\t\tx, y \\geq 0\n\t\t\\end{cases}\n\t\t\\]<br>Hàm mục tiêu: $L = 2{,}2x + 1{,}8y$<br>Dùng phương pháp đơn hình hoặc xét các điểm giao của miền nghiệm:<br>- Giao $3x + 2y = 12$ và $x + 2y = 8$:<br>\\[\n\t\t\\text{Trừ hai phương trình: } (3x + 2y) - (x + 2y) = 12 - 8 \\Rightarrow 2x = 4 \\Rightarrow x = 2 \\Rightarrow y = 3\n\t\t\\]<br>$L = 2{,}2 \\cdot 2 + 1{,}8 \\cdot 3 = 4{,}4 + 5{,}4 = 9{,}8$<br>- Giao $3x + 2y = 12$ với $y = 0$: $3x = 12 \\Rightarrow x = 4$ $L = 2{,}2 \\cdot 4 = 8{,}8$<br>- Giao $x + 2y = 8$ với $x = 0$: $2y = 8 \\Rightarrow y = 4$ $L = 1{,}8 \\cdot 4 = 7{,}2$<br>- Giao $3x + 2y = 12$ với $x = 2$, $y = 3$ đã xét<br>- Giao $x + 2y = 8$ với $3x + 2y = 12$ đã xét<br>Điểm tối ưu là nghiệm của hệ: $x = 2$, $y = 3$ $L = 9{,}8$<br>Tuy nhiên, thử thêm điểm $x = 3$, $y = 2$:<br>\\[\n\t\t3x + 2y = 9 + 4 = 13 > 12 \\Rightarrow loại\n\t\t\\]<br>Thử $x = 2$, $y = 2$:<br>\\[\n\t\t3x + 2y = 6 + 4 = 10 \\leq 12,\\quad x + 2y = 2 + 4 = 6 \\leq 8\n\t\t\\Rightarrow L = 2{,}2 \\cdot 2 + 1{,}8 \\cdot 2 = 4{,}4 + 3{,}6 = 8{,}0\n\t\t\\]  Thử $x = 3$, $y = 1$:  \\[\n\t\t3x + 2y = 9 + 2 = 11,\\quad x + 2y = 3 + 2 = 5 \\Rightarrow L = 2{,}2 \\cdot 3 + 1{,}8 \\cdot 1 = 6{,}6 + 1{,}8 = 8{,}4\n\t\t\\]  Thử $x = 2$, $y = 4$:  \\[\n\t\t3x + 2y = 6 + 8 = 14 > 12 \\Rightarrow loại\n\t\t\\]  Thử $x = 1$, $y = 3$:  \\[\n\t\t3x + 2y = 3 + 6 = 9,\\quad x + 2y = 1 + 6 = 7 \\Rightarrow L = 2{,}2 + 5{,}4 = 7{,}6\n\t\t\\]  Thử $x = 2$, $y = 3$ $L = 9{,}8$<br>Thử $x = 3$, $y = 2$ loại<br>Thử $x = 4$, $y = 0$:  \\[\n\t\t3x = 12,\\quad x = 4,\\quad x + 2y = 4 \\leq 8 \\Rightarrow L = 8{,}8\n\t\t\\]  Thử $x = 2$, $y = 3$ $L = 9{,}8$<br>Thử $x = 1$, $y = 3{,}5$:  \\[\n\t\tx + 2y = 1 + 7 = 8,\\quad 3x + 2y = 3 + 7 = 10 \\Rightarrow L = 2{,}2 + 6{,}3 = 8{,}5\n\t\t\\]<br>Thử $x = 1$, $y = 3{,}75$:<br>\\[\n\t\tx + 2y = 1 + 7{,}5 = 8{,}5 > 8 \\Rightarrow loại\n\t\t\\]<br>Điểm tối ưu là $x = 2$, $y = 3$ $L = \\boxed{9{,}8}$ triệu đồng"}]}, {"noiDungChung": ".<br>Cho cấp số cộng có $u_1 = 1$, $S_{100} = 24850$.", "cauHoi": [{"question": "Công sai của cấp số cộng trên là:", "choices": ["7", "5", "10", "15"], "correctIndex": 1, "explain": "Tổng cấp số cộng:<br>\\[\n\t\tS_n = \\dfrac{n}{2}(2u_1 + (n - 1)d)\n\t\t\\Rightarrow S_{100} = \\dfrac{100}{2}(2 \\cdot 1 + 99d) = 50(2 + 99d)\n\t\t\\]<br>\\[\n\t\t50(2 + 99d) = 24850 \\Rightarrow 2 + 99d = \\dfrac{24850}{50} = 497\n\t\t\\Rightarrow 99d = 495 \\Rightarrow d = \\dfrac{495}{99} = 5\n\t\t\\]"}, {"question": "Tính tổng $M = \\dfrac{1}{u_1 u_2} + \\dfrac{1}{u_2 u_3} + \\cdots + \\dfrac{1}{u_{49} u_{50}}$ với cấp số cộng $u_1 = 1$, $d = 5$.", "choices": ["$\\dfrac{4}{23}$", "$\\dfrac{49}{246}$", "$\\dfrac{9}{246}$", "123"], "correctIndex": 1, "explain": "Ta có: $u_n = u_1 + (n - 1)d = 1 + 5(n - 1) = 5n - 4$<br>Xét tổng:  \\[\n\t\tM = \\sum_{k = 1}^{49} \\dfrac{1}{u_k u_{k + 1}} = \\sum_{k = 1}^{49} \\dfrac{1}{(5k - 4)(5k + 1)}\n\t\t\\]<br>Biến đổi phân thức:  \\[\n\t\t\\dfrac{1}{(5k - 4)(5k + 1)} = \\dfrac{A}{5k - 4} + \\dfrac{B}{5k + 1}\n\t\t\\Rightarrow A(5k + 1) + B(5k - 4) = 1\n\t\t\\]<br>Giải hệ:<br>\\[\n\t\tA(5k + 1) + B(5k - 4) = 1 \\Rightarrow (5A + 5B)k + (A - 4B) = 1\n\t\t\\Rightarrow \\begin{cases}\n\t\t\t5A + 5B = 0 \\Rightarrow A = -B \\\\\n\t\t\tA - 4B = 1\n\t\t\\end{cases}\n\t\t\\Rightarrow -B - 4B = 1 \\Rightarrow B = -\\dfrac{1}{5},\\quad A = \\dfrac{1}{5}\n\t\t\\]<br>Vậy:<br>\\[\n\t\t\\dfrac{1}{(5k - 4)(5k + 1)} = \\dfrac{1}{5} \\left( \\dfrac{1}{5k - 4} - \\dfrac{1}{5k + 1} \\right)\n\t\t\\]<br>Tổng trở thành:<br>\\[\n\t\tM = \\dfrac{1}{5} \\sum_{k = 1}^{49} \\left( \\dfrac{1}{5k - 4} - \\dfrac{1}{5k + 1} \\right)\n\t\t\\]<br>Đây là tổng dạng **telescoping** (rút gọn từng cặp), ta viết ra vài số hạng đầu:<br>\\[\n\t\t\\dfrac{1}{1} - \\dfrac{1}{6} + \\dfrac{1}{6} - \\dfrac{1}{11} + \\cdots + \\dfrac{1}{241} - \\dfrac{1}{246}\n\t\t\\Rightarrow \\text{các số hạng trung gian triệt tiêu}\n\t\t\\]<br>Còn lại:<br>\\[\n\t\tM = \\dfrac{1}{5} \\left( \\dfrac{1}{1} - \\dfrac{1}{246} \\right) = \\dfrac{1}{5} \\cdot \\dfrac{245}{246} = \\dfrac{49}{246}\n\t\t\\]<br>Đáp án đúng là $\\boxed{\\dfrac{49}{246}}$<br>**Lưu ý:** Nếu đề bài cho đáp án $\\dfrac{4}{23}$ là đúng thì có thể cấp số cộng có công sai khác. Với $u_1 = 1$, $d = 5$ thì kết quả chính xác là $\\dfrac{49}{246}$"}]}, {"noiDungChung": "Cho hàm số $f(x) = x^3 - 9x^2 + 24x + m$.", "cauHoi": [{"question": "Tính $f'(1)$.", "choices": ["$9 + m$", "$3 + m$", "$9$", "$3$"], "correctIndex": 2, "explain": "Ta có $f'(x) = 3x^2 - 18x + 24$.<br>$\\Rightarrow f'(1) = 3(1)^2 - 18(1) + 24 = 3 - 18 + 24 = 9$.<br>Đáp án đúng là $9$."}, {"question": "Khi $m = 3$, trung điểm $I$ của đoạn thẳng nối hai điểm cực trị của đồ thị hàm số có tọa độ là:", "choices": ["$(21; 18)$", "$(18; 21)$", "$(3; 18)$", "$(3; 21)$"], "correctIndex": 3, "explain": "Ta có $f'(x) = 3x^2 - 18x + 24$.<br>Giải $f'(x) = 0 \\Rightarrow 3x^2 - 18x + 24 = 0 \\Rightarrow x^2 - 6x + 8 = 0 \\Rightarrow x = 2$, $x = 4$.<br>Tọa độ hai điểm cực trị: $A(2; f(2))$, $B(4; f(4)$.<br>Tính $f(2) = 8 - 36 + 48 + 3 = 23$, $f(4) = 64 - 144 + 96 + 3 = 19$.<br>Trung điểm $I$ có hoành độ: $\\dfrac{2 + 4}{2} = 3$, tung độ: $\\dfrac{23 + 19}{2} = 21$."}, {"question": "Tìm tất cả các giá trị của $m$ để phương trình $f(x)= 0$ có 3 nghiệm phân biệt.", "choices": ["$-20 < m < 16$", "$-16 < m < 20$", "$-20 < m < -16$", "$16 < m < 20$"], "correctIndex": 0, "explain": "Phương trình có 3 nghiệm phân biệt khi đồ thị hàm số cắt trục hoành tại 3 điểm phân biệt.<br>Điều kiện: hàm số có 2 cực trị và giá trị tại hai điểm cực trị trái dấu.<br>Ta có $f'(x) = 3x^2 - 18x + 24 = 0 \\Rightarrow x = 2$, $x = 4$.<br>Tính $f(2) = 8 - 36 + 48 + m = 20 + m$, $f(4) = 64 - 144 + 96 + m = 16 + m$.<br>Để $f(2) \\cdot f(4) < 0 \\Rightarrow (20 + m)(16 + m) < 0$.<br>Xét bất phương trình: $(m + 20)(m + 16) < 0 \\Rightarrow -20 < m < -16$.<br>Đáp án đúng là $-20 < m < -16$."}]}, {"noiDungChung": "Có hai hộp chứa thẻ. Hộp 1 chứa các thẻ đánh số thứ tự khác nhau từ 0 đến 100. Hộp 2 chứa các thẻ đánh số thứ tự khác nhau từ 0 đến 10.", "cauHoi": [{"question": "Chọn ngẫu nhiên 2 thẻ từ hộp 1. Số cách chọn là:", "choices": ["5050", "9900", "4590", "1000"], "correctIndex": 0, "explain": "Hộp 1 có $101$ thẻ (từ $0$ đến $100$).<br>Số cách chọn 2 thẻ khác nhau là:<br>\\[\n\t\tC_{101}^2 = \\dfrac{101 \\cdot 100}{2} = 5050\n\t\t\\]"}, {"question": "Chọn ngẫu nhiên từ mỗi hộp 1 thẻ. Xác suất để tổng 2 số thứ tự không vượt quá 90 là:", "choices": ["$\\dfrac{2}{9}$", "$\\dfrac{3}{11}$", "$\\dfrac{3}{7}$", "$\\dfrac{2}{11}$"], "correctIndex": 3, "explain": ""}, {"question": "Chọn ngẫu nhiên từ mỗi hộp 1 thẻ. Xác suất để tổng 2 số thứ tự không vượt quá 90 là:", "choices": ["$\\dfrac{82}{101}$", "$\\dfrac{59}{101}$", "$\\dfrac{25}{101}$", "$\\dfrac{86}{101}$"], "correctIndex": 3, "explain": "Hộp 1: số từ $0$ đến $100$ 101 số<br>Hộp 2: số từ $0$ đến $10$ 11 số<br>Tổng số cách chọn: $101 \\cdot 11 = 1111$<br>Để tổng không vượt quá 90: xét với mỗi số $y$ từ hộp 2 (từ 0 đến 10), số $x$ từ hộp 1 phải thỏa $x \\leq 90 - y$<br>Tính số cách thỏa mãn:<br>\\[\n\t\t\\sum_{y = 0}^{10} \\left( \\lfloor 90 - y \\rfloor + 1 \\right)\n\t\t= \\sum_{y = 0}^{10} (91 - y) = \\sum_{k = 81}^{91} k = 91 \\cdot 11 - \\sum_{y = 0}^{10} y\n\t\t= 91 \\cdot 11 - \\dfrac{10 \\cdot 11}{2} = 1001 - 55 = 946\n\t\t\\]<br>Xác suất: $\\dfrac{946}{1111} = \\dfrac{86}{101}$<br>Đáp án đúng là $\\boxed{\\dfrac{86}{101}}$"}]}, {"noiDungChung": "Cho tam giác $ABC$ có phương trình $(AB): 2x - y = 3$, điểm $B(1, -1)$, $C(6, 4)$.", "cauHoi": [{"question": "Gọi $I(x_0, y_0)$ là giao điểm của $BC$ với trục $Oy$. Tính $x_0 + y_0$.", "choices": ["2", "0", "4", "$-2$"], "correctIndex": 3, "explain": "Ta cần tìm giao điểm của đường thẳng $BC$ với trục $Oy$, tức là điểm có hoành độ $x = 0$ nằm trên đường thẳng $BC$.<br>Tìm phương trình đường thẳng $BC$ đi qua $B(1, -1)$ và $C(6, 4)$:<br>Hệ số góc:<br>\\[\n\t\tk = \\dfrac{4 - (-1)}{6 - 1} = \\dfrac{5}{5} = 1\n\t\t\\Rightarrow \\text{Phương trình: } y - (-1) = 1(x - 1) \\Rightarrow y = x - 2\n\t\t\\]<br>Thay $x = 0$ vào: $y = 0 - 2 = -2$<br>Giao điểm $I(0, -2)$ $x_0 + y_0 = 0 + (-2) = -2$"}, {"question": "Biết tam giác $ABC$ vuông tại $A$. Tìm hoành độ điểm $A$.", "choices": ["0", "4", "6", "2"], "correctIndex": 1, "explain": "Tam giác $ABC$ vuông tại $A$ hai vectơ $\\vec{AB}$ và $\\vec{AC}$ vuông góc.<br>Gọi $A(x, y)$ là điểm nằm trên đường thẳng $AB$: $2x - y = 3$<br>$y = 2x - 3$<br>Tính $\\vec{AB} = B - A = (1 - x, -1 - y)$<br>Tính $\\vec{AC} = C - A = (6 - x, 4 - y)$<br>Điều kiện vuông góc: $\\vec{AB} \\cdot \\vec{AC} = 0$  \\[\n\t\t(1 - x)(6 - x) + (-1 - y)(4 - y) = 0\n\t\t\\]  Thay $y = 2x - 3$ vào:  \\[\n\t\t(1 - x)(6 - x) + (-1 - (2x - 3))(4 - (2x - 3)) = 0\n\t\t\\Rightarrow (1 - x)(6 - x) + (-2x + 2)(-2x + 7) = 0\n\t\t\\]<br>Tính:  \\[\n\t\t(1 - x)(6 - x) = 6 - x - 6x + x^2 = x^2 - 7x + 6\n\t\t\\]  \\[\n\t\t(-2x + 2)(-2x + 7) = 4x^2 - 14x - 4x + 14 = 4x^2 - 12x + 14\n\t\t\\]  Tổng:<br>$\n\t\tx^2 - 7x + 6 + 4x^2 - 12x + 14 = 5x^2 - 19x + 20 = 0\n\t\t\\Rightarrow x = 2 \\text{ hoặc } x = 2\n\t\t x = 2$"}, {"question": "Biết có 2 đường tròn đi qua điểm $C(6, 4)$ và tiếp xúc đồng thời với trục $Ox$ và $Oy$. Tổng bán kính của hai đường tròn này là:", "choices": ["20", "$8\\sqrt{3}$", "16", "$12\\sqrt{2}$"], "correctIndex": 0, "explain": "Gọi tâm đường tròn là $I(a, a)$ vì tiếp xúc với cả $Ox$ và $Oy$ tâm nằm trên đường phân giác góc phần tư thứ nhất hoặc thứ ba.<br>Bán kính $R = a$<br>Đường tròn đi qua điểm $C(6, 4)$ khoảng cách từ $I(a, a)$ đến $C$ bằng $R$:<br>\\[\n\t\tIC = \\sqrt{(6 - a)^2 + (4 - a)^2} = a\n\t\t\\Rightarrow (6 - a)^2 + (4 - a)^2 = a^2\n\t\t\\Rightarrow 36 - 12a + a^2 + 16 - 8a + a^2 = a^2\n\t\t\\Rightarrow 52 - 20a + 2a^2 = a^2\n\t\t\\Rightarrow a^2 - 20a + 52 = 0\n\t\t\\]<br>Giải phương trình:<br>\\[\n\t\ta = \\dfrac{20 \\pm \\sqrt{400 - 208}}{2} = \\dfrac{20 \\pm \\sqrt{192}}{2} = \\dfrac{20 \\pm 8\\sqrt{3}}{2} = 10 \\pm 4\\sqrt{3}\n\t\t\\]<br>Tổng bán kính: $10 + 4\\sqrt{3} + 10 - 4\\sqrt{3} = 20$<br>Đáp án đúng là $\\boxed{20}$"}]}, {"noiDungChung": "Cho tứ diện $OABC$ có $\\vec{OA}, \\vec{OB}, \\vec{OC}$ đôi một vuông góc, $OA = \\dfrac{\\sqrt{2}}{2}$, $OB = OC = 1$.", "cauHoi": [{"question": "Chu vi tam giác $ABC$ là:", "choices": ["$\\sqrt{2}+\\sqrt{3}+\\sqrt{6}$", "$\\sqrt{3}+\\sqrt{6}$", "$\\sqrt{2}+\\sqrt{3}$", "$\\sqrt{2}+\\sqrt{6}$"], "correctIndex": 3, "explain": "Gọi $O$ là gốc tọa độ, ta có thể chọn:<br>\\[\n\t\tA = \\left(\\dfrac{\\sqrt{2}}{2}, 0, 0\\right),\\quad\n\t\tB = (0, 1, 0),\\quad\n\t\tC = (0, 0, 1)\n\t\t\\]<br>Tính độ dài các cạnh tam giác $ABC$:<br>\\[\n\t\tAB = \\sqrt{\\left(\\dfrac{\\sqrt{2}}{2}\\right)^2 + 1^2} = \\sqrt{\\dfrac{2}{4} + 1} = \\sqrt{\\dfrac{6}{4}} = \\dfrac{\\sqrt{6}}{2}\n\t\t\\]  \\[\n\t\tAC = \\sqrt{\\left(\\dfrac{\\sqrt{2}}{2}\\right)^2 + 1^2} = \\dfrac{\\sqrt{6}}{2}\n\t\t\\]<br>\\[\n\t\tBC = \\sqrt{(1)^2 + (1)^2} = \\sqrt{2}\n\t\t\\]<br>Chu vi tam giác $ABC$:<br>\\[\n\t\tP = AB + AC + BC = \\dfrac{\\sqrt{6}}{2} + \\dfrac{\\sqrt{6}}{2} + \\sqrt{2} = \\sqrt{6} + \\sqrt{2}\n\t\t\\]<br>Tuy nhiên, nếu tính lại chính xác:<br>\\[\n\t\tAB = \\sqrt{\\left(\\dfrac{\\sqrt{2}}{2}\\right)^2 + 1^2} = \\sqrt{\\dfrac{2}{4} + 1} = \\sqrt{\\dfrac{6}{4}} = \\sqrt{\\dfrac{3}{2}} = \\dfrac{\\sqrt{6}}{2}\n\t\t\\]<br>\\[\n\t\tAC = \\sqrt{\\left(\\dfrac{\\sqrt{2}}{2}\\right)^2 + 1^2} = \\dfrac{\\sqrt{6}}{2},\\quad BC = \\sqrt{(1)^2 + (1)^2} = \\sqrt{2}\n\t\t\\]<br>Chu vi: $\\dfrac{\\sqrt{6}}{2} + \\dfrac{\\sqrt{6}}{2} + \\sqrt{2} = \\sqrt{6} + \\sqrt{2}$<br>Đáp án đúng là $\\boxed{\\sqrt{2}+\\sqrt{6}}$"}, {"question": "Góc hợp bởi hai mặt phẳng $(ABC)$ và $(OBC)$ là:", "choices": ["$45^\\circ$", "$75^\\circ$", "$60^\\circ$", "$30^\\circ$"], "correctIndex": 0, "explain": "Góc giữa hai mặt phẳng $(ABC)$ và $(OBC)$ là góc giữa hai pháp tuyến của mặt phẳng.<br>- Mặt phẳng $(ABC)$ có pháp tuyến là $\\vec{n}_1 = \\vec{AB} \\times \\vec{AC}$  - Mặt phẳng $(OBC)$ có pháp tuyến là $\\vec{n}_2 = \\vec{OB} \\times \\vec{OC}$<br>Tính tích vô hướng:<br>\\[\n\t\t\\cos \\theta = \\dfrac{|\\vec{n}_1 \\cdot \\vec{n}_2|}{\\|\\vec{n}_1\\| \\cdot \\|\\vec{n}_2\\|}\n\t\t\\Rightarrow \\theta = \\arccos\\left(\\dfrac{1}{2}\\right) = 60^\\circ\n\t\t\\]<br>Đáp án đúng là $\\boxed{60^\\circ}$"}, {"question": "Gọi $H$ là hình chiếu vuông góc của $O$ lên mặt phẳng $(ABC)$. Tính thể tích khối tứ diện $OABH$.", "choices": ["$\\dfrac{\\sqrt{2}}{48}$", "$\\dfrac{\\sqrt{2}}{16}$", "$\\dfrac{\\sqrt{2}}{24}$", "$\\dfrac{\\sqrt{2}}{36}$"], "correctIndex": 0, "explain": "Thể tích tứ diện $OABH$:<br>\\[\n\t\tV = \\dfrac{1}{3} \\cdot S_{\\triangle ABH} \\cdot OH\n\t\t\\]<br>Vì $O$ vuông góc với mặt phẳng $(ABC)$, $OH$ là chiều cao từ $O$ xuống mặt phẳng $(ABC)$.<br>Ta có:  - $OA = \\dfrac{\\sqrt{2}}{2}$, $OB = 1$  - Góc giữa $\\vec{OA}$ và $\\vec{OB}$ là $90^\\circ$ tam giác $OAB$ vuông tại $O$<br>Diện tích tam giác $ABH$ bằng diện tích tam giác $ABO$:<br>\\[\n\t\tS = \\dfrac{1}{2} \\cdot OA \\cdot OB = \\dfrac{1}{2} \\cdot \\dfrac{\\sqrt{2}}{2} \\cdot 1 = \\dfrac{\\sqrt{2}}{4}\n\t\t\\]<br>Chiều cao $OH$ là khoảng cách từ $O$ đến mặt phẳng $(ABC)$, đã tính được là $\\dfrac{1}{2}$<br>Thể tích:<br>\\[\n\t\tV = \\dfrac{1}{3} \\cdot \\dfrac{\\sqrt{2}}{4} \\cdot \\dfrac{1}{2} = \\dfrac{\\sqrt{2}}{24}\n\t\t\\]<br>Đáp án đúng là $\\boxed{\\dfrac{\\sqrt{2}}{24}}$"}]}, {"noiDungChung": "Một công ty có 3 tuyến xe $1,2,3$ và in 3 bộ vé tháng 1, 3 bộ vé tháng 2. Mỗi tuyến sử dụng 1 bộ cho 1 tháng. Vé in theo quy tắc sau:<br>a) Mỗi bộ 1 màu: xanh, đỏ, tím, vàng.  <br>b) Ở mỗi tuyến, vé tháng 1 khác màu vé tháng 2.  <br>c) Ở tuyến 3, vé tháng 1 hoặc vé tháng 2 có màu xanh.  <br>d) Ở mỗi tháng, vé cho các tuyến khác nhau thì có màu khác nhau.  <br>e) Một bộ vé ở tháng 1 có màu đỏ.  <br>f) Vé tháng 1 của tuyến 2 màu tím.  <br>g) Các vé tháng 2 không có màu tím.", "cauHoi": [{"question": "Nếu vé tháng 1 của tuyến 3 có màu đỏ thì điều nào phải đúng?", "choices": ["Vé tuyến 3 của tháng 2 có màu xanh", "Vé tuyến 1 của tháng 1 có màu vàng", "Vé tuyến 1 của tháng 1 có màu xanh", "Vé tuyến 2 của tháng 2 có màu vàng"], "correctIndex": 0, "explain": "Vé tháng 1 của tuyến 3 là đỏ tuyến 3 không thể dùng đỏ ở tháng 2 để thỏa điều kiện \"tuyến 3 có màu xanh ở tháng 1 hoặc tháng 2\", thì tháng 2 phải là xanh."}, {"question": "Nếu một bộ vé của tuyến 2 có màu xanh thì điều nào phải đúng?", "choices": ["Vé tuyến 3 của tháng 2 có màu xanh", "Vé tuyến 1 của tháng 1 có màu đỏ", "Vé tuyến 1 của tháng 2 có màu đỏ", "Vé tuyến 3 của tháng 1 có màu đỏ"], "correctIndex": 1, "explain": "Vé tháng 1 của tuyến 2 là tím màu xanh phải thuộc tháng 2. Vì vé tháng 2 của tuyến 2 là xanh, tuyến 3 không thể dùng xanh ở tháng 2 phải dùng xanh ở tháng 1. Khi đó, tuyến 1 có thể dùng đỏ ở tháng 1 để thỏa điều kiện \"một bộ vé tháng 1 có màu đỏ\"."}, {"question": "Phát biểu nào có thể đúng?", "choices": ["Vé tháng 2 không có màu xanh", "Chỉ có vé tuyến 2 màu đỏ", "Tháng 1 có 1 bộ vé xanh, 1 bộ vé vàng", "Vé tháng 1 không có màu xanh"], "correctIndex": 3, "explain": "Không có quy tắc nào cấm màu xanh ở tháng 1. Vì vậy, việc tháng 1 có 1 vé xanh, 1 vé vàng là hoàn toàn có thể xảy ra."}]}, {"noiDungChung": "Một dãy khách sạn đánh số từ 1 đến 7 từ trái sang phải. Một đoàn khách gồm $R, S, T, U, V, W, X$ được sắp xếp vào 7 phòng (mỗi người một phòng).<br>a) Phòng của $T$ nằm bên trái phòng $R$.  <br>b) Nếu $S$ ở phòng 4 thì $U$ ở phòng 5.  <br>c) Nếu $U$ ở phòng 6 thì $S$ ở phòng 7.  <br>d) $V$ và $W$ không ở cạnh phòng nhau.", "cauHoi": [{"question": "Liệt kê nào không thể là thứ tự phòng?", "choices": ["TRSUVXW", "XSUVTRW", "TXSUVRW", "VUTSXRW"], "correctIndex": 3, "explain": "Trong chuỗi XSUVTRW, ta thấy $V$ và $W$ ở vị trí 6 và 7 cạnh nhau vi phạm điều kiện."}, {"question": "Nếu $V$ và $W$ ở phòng 5 và 7 thì 2 người nào không thể ở phòng 6?", "choices": ["ST", "RS", "XR", "TU"], "correctIndex": 3, "explain": "Phòng 6 nằm giữa phòng 5 và 7 người ở phòng 6 sẽ cạnh cả $V$ và $W$. Vì $V$ và $W$ không được cạnh nhau, nên $T$ hoặc $U$ không thể ở giữa."}, {"question": "Biết $T$ ở phòng 3, $S$ ở phòng 4 thì phát biểu nào luôn đúng?", "choices": ["$R$ ở trái $V$", "$X$ ở 1 hoặc 2", "$X, T$ cạnh nhau", "$W$ trái $T$"], "correctIndex": 1, "explain": "$T$ ở phòng 3, $S$ ở phòng 4 $X$ có thể ở phòng 2 hoặc 4 mà phòng 4 là $S$ $X$ ở phòng 2 cạnh $T$."}]}, {"noiDungChung": ".<br>Cho bảng điểm của 5 lớp. Nếu điểm thấp hơn 5 sẽ rớt môn, từ 5 điểm trở lên sẽ qua môn.<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Lớp</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><5</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">5-8</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">>8</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">1</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">28</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">72</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">24</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">15</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">68</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">36</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">3</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">18</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">52</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">28</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">4</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">29</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">58</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">47</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">5</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">30</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">60</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">35</td></tr></table>", "cauHoi": [{"question": "Tổng số sinh viên của 5 lớp có bao nhiêu phần trăm rớt môn?", "choices": ["$18,8 \\%$", "$20 \\%$", "$15,6 \\%$", "$21,2 \\%$"], "correctIndex": 1, "explain": ""}, {"question": "Trong số các sinh viên trên 8 điểm có 20 (\\% sinh viên đạt điểm 10. Tỉ lệ sinh viên đạt điểm 10 của 5 lớp là:", "choices": ["$7,9 \\%$", "$7,16 \\%$", "$5,67 \\%$", "$20 \\%$"], "correctIndex": 2, "explain": ""}, {"question": "Trong lớp mà tỉ lệ sinh viên rớt môn nhiều nhất, 1 số bạn đã phúc khảo và qua môn nên lớp đó không còn là lớp có tỉ lệ rớt môn nhiều nhất. Có ít nhất bao nhiêu bạn tăng điểm và qua môn sau khi phúc khảo?", "choices": ["4", "1", "2", "3"], "correctIndex": 2, "explain": ""}]}, {"noiDungChung": ".<br>Số vở bán ra (đơn vị: nghìn cuốn) trong năm 2023 và 2024 của 6 công ty $1,2,3,4,5,6$ được thống kê như sau:<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Công ty</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Năm 2023</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Năm 2024</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">1</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">80</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">105</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">75</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">65</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">3</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">95</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">110</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">4</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">85</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">95</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">5</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">75</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">95</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">6</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">70</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">80</td></tr></table>", "cauHoi": [{"question": "Tổng số vở (nghìn cuốn) trong 2 năm của các công ty $1,3,5$ là:", "choices": ["250", "560", "310", "435"], "correctIndex": 1, "explain": ""}, {"question": "Tỉ lệ tổng số vở bán trong 2 năm của công ty 2 so với công ty 4 là:", "choices": ["$3: 5$", "$7: 9$", "$4: 5$", "$2: 3$"], "correctIndex": 1, "explain": ""}, {"question": "Trong năm 2023, giá bán vở của công ty 5 và 6 như nhau. Trong năm 2024, công ty 5 tăng 10\\%, công ty 6 tăng 15 (\\% so với giá năm 2023. Tỉ lệ doanh thu công ty 5 với công ty 6 trong cả 2 năm là:", "choices": ["$113,5 \\%$", "$88 \\%$", "$110,8 \\%$", "$90,3 \\%$"], "correctIndex": 2, "explain": ""}]}]}, {"id": "de-1-2026", "ten": "Đề chính thức đợt 1 - 5/4/2026", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Một công ty có lợi nhuận tuân theo hàm số $y=f(x)=\\sqrt{x^2-x+5}-\\sqrt{x^2+2x+2}$. Trong đó, $f(x)$ là lợi nhuận (đơn vị: tỷ đồng), $x$ là thời gian (đơn vị: năm). Sau rất lâu (có thể coi $x$ tiến tới $+\\infty$), nhận xét đúng về lợi nhuận của công ty đó là", "choices": ["Công ty lỗ", "Không xác định", "Công ty lời", "Công ty hòa vốn"], "correctIndex": 0, "explain": "Ta có   $$\\displaystyle\\lim\\limits_{x\\to+\\infty}y=\\displaystyle\\lim\\limits_{x\\to+\\infty}\\dfrac{(x^2-x+5)-(x^2+2x+2)}{\\sqrt{x^2-x+5}+\\sqrt{x^2+2x+2}}=\\displaystyle\\lim\\limits_{x\\to+\\infty}\\dfrac{-3x+3}{\\sqrt{x^2-x+5}+\\sqrt{x^2+2x+2}}=\\dfrac{-3}{1+1}=-\\dfrac{3}{2}$$  Do đó: công ty đang bị lỗ."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Nếu $\\displaystyle\\int\\limits_{{1}}^{{3}}({(m+1)}x^{m}+{1})\\mathrm{d}x={28}$ thì", "choices": ["Không tồn tại giá trị của $m$", "$m\\in{[{1};{3}]}$", "$m\\in{[-{3};-{1})}$", "$m\\in{(-{1};{1})}$"], "correctIndex": 1, "explain": "Ta có $\\displaystyle\\int\\limits_{{1}}^{{3}}({(m+1)}x^{m}+{1})\\mathrm{d}x={[{x}^{m+1}+x]}_{{1}}^{{3}}={({3}^{m+1}+{3})}-({{1}}^{m+1}+{1})={3}^{m+1}+{1}$.<br>Thay vào phương trình ta được:  $${3}^{m+1}+{1}={28}\\Leftrightarrow{3}^{m+1}={27}\\Leftrightarrow{3}^{m+1}={3}^{3}\\Leftrightarrow m+{1}={3}\\Leftrightarrow m={2}$$  Giá trị $m={2}$ nằm trong đoạn ${[{1};{3}]}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Trong mặt phẳng $Oxy$, một khu vườn được giới hạn bởi đồ thị của hai hàm số $y=\\dfrac{{1}}{{2}}x^{2}$ và $y=\\sqrt{{2}x}$. Diện tích khu vườn là", "choices": ["$\\dfrac{{5}}{{3}}$", "${2}$", "${1}$", "$\\dfrac{{4}}{{3}}$"], "correctIndex": 3, "explain": "Phương trình hoành độ giao điểm của hai đồ thị (điều kiện $x\\ge{0}$):  $$\\dfrac{{1}}{{2}}x^{2}=\\sqrt{{2}x}\\Leftrightarrow\\dfrac{{1}}{{4}}x^{4}={2}x\\Leftrightarrow x^{4}-{8}x={0}\\Leftrightarrow x(x^{3}-{8})={0}\\Leftrightarrow\\hoac{&x={0}<br>&x={2}}$$  Diện tích khu vườn là  $$S=\\displaystyle\\int\\limits_{{0}}^{{2}}\\left|\\sqrt{{2}x}-\\dfrac{{1}}{{2}}x^{2}\\right|\\mathrm{d}x=\\left.\\left(\\dfrac{{2}\\sqrt{{2}}}{{3}}x\\sqrt{x}-\\dfrac{{1}}{{6}}x^{3}\\right)\\right|_{{0}}^{{2}}=\\dfrac{{4}}{{3}}$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một phân tử được cấu tạo từ ${8}$ nguyên tử liên kết với nhau. Tổng số liên kết trong phân tử này là ${8}$. Các nhà khoa học đo được số liên kết của ${7}$ nguyên tử đầu tiên là ${4}$, ${2}$, ${2}$, ${1}$, ${1}$, ${1}$, ${1}$. Nguyên tử thứ ${8}$ có bao nhiêu liên kết?", "choices": ["${1}$", "${4}$", "${2}$", "${3}$"], "correctIndex": 1, "explain": "Gọi $x$ là số bậc (số liên kết) của nguyên tử thứ ${8}$. Ta thiết lập phương trình:  $${4}+{2}+{2}+{1}+{1}+{1}+{1}+x={2}\\times{8}\\Leftrightarrow{12}+x={16}\\Leftrightarrow x={4}$$<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.9]\n\t\t\t\n\t\t\t\\foreach \\i/\\name/\\label in {1/1/4, 2/2/2, 3/3/2, 4/4/1, 5/5/1, 6/6/1, 7/7/1, 8/8/$x=4$} {\n\t\t\t\t\\node (\\i) at ({360/8 * (\\i - 1)}:2.5cm) {\\name};\n\t\t\t}\n\t\t\t\n\t\t\t\n\t\t\t\\draw (1) -- (2);\n\t\t\t\\draw (1) -- (3);\n\t\t\t\\draw (1) -- (4);\n\t\t\t\\draw (1) -- (5);\n\t\t\t\n\t\t\t\\draw (2) -- (6);\n\t\t\t\\draw (2) -- (7);\n\t\t\t\n\t\t\t\\draw (3) -- (8);\n\t\t\t\\draw (3) -- (5);\n\t\t\t\n\t\t\t\n\t\t\t\\node[draw=none, font=\\normalsize] at (0,-3.3) {Đồ thị minh họa số liên kết của 8 nguyên tử};\n\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một khu du lịch gồm $6$ địa điểm $A$, $B$, $C$, $D$, $E$, $F$ được nối với nhau. Bạn Thủy muốn đi từ $E$ lần lượt qua các điểm khác và kết thúc tại $F$.<br>Số cách đi là<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1]\n\t\t\t\\coordinate (A) at (0,3);\n\t\t\t\\coordinate (B) at (3,3);\n\t\t\t\\coordinate (C) at (3,0);\n\t\t\t\\coordinate (D) at (0,0);\n\t\t\t\\coordinate (E) at (1.5,2.2);\n\t\t\t\\coordinate (F) at (1.5,0.8);\n\t\t\t\\draw (A)--(B)--(C)--(D)--(A);\n\t\t\t\\draw (A)--(E) (B)--(E) (E)--(F);\n\t\t\t\\draw (F)--(C) (F)--(D);\n\t\t\t\\foreach \\p/\\l in {A/above left, B/above right, C/below right, D/below left, E/above, F/below}\n\t\t\t\\node[\\l] at (\\p){$\\p$};\n\t\t\\end{tikzpicture}</script></div>", "choices": ["$3$", "$2$", "$1$", "$4$"], "correctIndex": 1, "explain": "\\textbf{Đi theo nhánh $E\\to A$}:<br>Từ $A$, muốn đi qua hết các điểm còn lại để về $F$, lộ trình duy nhất không bị cụt đường là $A\\to B\\to C\\to D$.<br>Đến $D$, ta thấy $D$ có đường nối trực tiếp với $F$.<br>$\\Rightarrow$ Đường đi hợp lệ $1$: $E\\to A\\to B\\to C\\to D\\to F$.<br>(\\textit{Nhánh rẽ khác $A\\to D\\to C\\to B$ sẽ bị tắc vì $B$ không nối thẳng với $F$}).<br>\\textbf{Đi theo nhánh $E\\to B$}:<br>Tương tự, lộ trình quét qua các điểm còn lại là $B\\to A\\to D\\to C$.<br>Đến $C$, ta thấy $C$ có đường nối trực tiếp với $F$.<br>$\\Rightarrow$ Đường đi hợp lệ $2$: $E\\to B\\to A\\to D\\to C\\to F$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho một tam giác có độ dài ${3}$ cạnh ${5}$, ${6}$, ${7}$. Tính độ dài đường cao ứng với cạnh có độ dài bằng ${6}$.", "choices": ["$\\sqrt{{2}}$", "${2}\\sqrt{{2}}$", "${2}\\sqrt{{6}}$", "$\\sqrt{{6}}$"], "correctIndex": 2, "explain": "Nửa chu vi: $p=\\dfrac{{5}+{6}+{7}}{{2}}={9}$.<br>Diện tích (Heron): $S=\\sqrt{{9}({9}-{5})({9}-{6})({9}-{7})}={6}\\sqrt{{6}}$<br>Đường cao $h_{{6}}=\\dfrac{{2}S}{{6}}=\\dfrac{{12}\\sqrt{{6}}}{{6}}={2}\\sqrt{{6}}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $\\Delta ABC$ thỏa mãn $\\dfrac{\\tan B}{\\tan C}=\\dfrac{\\sin^{2}B}{\\sin^{2}C}$. Khi đó $\\Delta ABC$:", "choices": ["cân", "vuông", "đều", "vuông hoặc cân"], "correctIndex": 3, "explain": "$$\\dfrac{\\dfrac{\\sin B}{\\cos B}}{\\dfrac{\\sin C}{\\cos C}}=\\dfrac{\\sin^{2}B}{\\sin^{2}C}\\Leftrightarrow\\dfrac{\\sin B\\cos C}{\\cos B\\sin C}=\\dfrac{\\sin^{2}B}{\\sin^{2}C}\\Leftrightarrow\\sin C\\cos C=\\sin B\\cos B\\Leftrightarrow\\sin({2}C)=\\sin({2}B)$$  Trường hợp ${1}$: ${2}C={2}B\\Leftrightarrow B=C$ (Tam giác cân).<br>Trường hợp ${2}$: ${2}C={180}^{\\circ}-{2}B\\Leftrightarrow B+C={90}^{\\circ}$ (Tam giác vuông)."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Giá trị của $m$ để bất phương trình $\\log_{\\dfrac{1}{5}}m>\\log_{5}({2}x+{3})$ có đúng ${3}$ nghiệm nguyên.", "choices": ["$\\dfrac{{1}}{{7}}\\leq m<\\dfrac{{1}}{{5}}$", "${0}<m<{1}$", "$\\dfrac{{1}}{{7}}<m<\\dfrac{{1}}{{3}}$", "$\\dfrac{{1}}{{5}}<m<\\dfrac{{1}}{{3}}$"], "correctIndex": 0, "explain": "Điều kiện xác định của các biểu thức logarit là $m>{0}$ và ${2}x+{3}>{0}\\Leftrightarrow x>-\\dfrac{{3}}{{2}}=-{1}{,}5$.<br>$\\log_{\\dfrac{1}{5}}m>\\log_{5}({2}x+{3})\\Leftrightarrow-\\log_{5}m>\\log_{5}({2}x+{3})\\Leftrightarrow\\log_{5}\\left(\\dfrac{{1}}{m}\\right)>\\log_{5}({2}x+{3})$<br>$\\Rightarrow\\dfrac{{1}}{m}>{2}x+{3}\\Leftrightarrow{2}x<\\dfrac{{1}}{m}-{3}\\Leftrightarrow x<\\dfrac{{1}-{3}m}{{2}m}$<br>Để phương trình có đúng ${3}$ nghiệm nguyên: ${1}<\\dfrac{{1}-{3}m}{{2}m}\\le{2}$<br>Giải hệ bất phương trình này: $m\\in\\left[\\dfrac{{1}}{{7}};\\dfrac{{1}}{{5}}\\right)$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Gọi $S$ là tập nghiệm của bất phương trình $\\dfrac{x^{2}+x+{3}}{x^{2}-{4}}\\ge{1}$. Khi đó $S\\cap({-2};{2})$:", "choices": ["$(-{1};{2})$", "$(-{2};-{1})$", "$\\varnothing$", "$(-{2};{1})$"], "correctIndex": 2, "explain": "Điều kiện: $x\\neq\\pm{2}$.<br>Bất phương trình tương đương:  $$\\dfrac{x^{2}+x+{3}}{x^{2}-{4}}-{1}\\ge{0}\\Leftrightarrow\\dfrac{x^{2}+x+{3}-(x^{2}-{4})}{x^{2}-{4}}\\ge{0}\\Leftrightarrow\\dfrac{x+{7}}{x^{2}-{4}}\\ge{0}$$  Lập bảng xét dấu, ta có tập nghiệm $S={[-{7};-{2})}\\cup({2};+\\infty)$.<br>Khi đó, giao của $S$ với khoảng $(-{2};{2})$ là: $S\\cap(-{2};{2})=\\varnothing$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Xét ${2}$ số thực $x$, $y$ thỏa mãn $x,y>{0}$ $\\log_{x}(y^{5x})=\\log_{y}(x^{8y})={20}$. Tính $xy$.", "choices": ["${4}$", "${40}$", "${2}$", "${10}$"], "correctIndex": 3, "explain": "Điều kiện: $x,y>{0}$ và $x,y\\neq{1}$.<br>Ta có hệ phương trình:  $$\\heva{&\\log_{x}(y^{5x})={20}<br>&\\log_{y}(x^{8y})={20}}\\Leftrightarrow\\heva{&{5}x\\cdot\\log_{x}y={20}<br>&{8}y\\cdot\\log_{y}x={20}}\\Leftrightarrow\\heva{&\\log_{x}y=\\dfrac{{4}}{x}<br>&\\log_{y}x=\\dfrac{{5}}{{2}y}}$$  Nhân vế theo vế: $\\dfrac{{4}}{x}\\cdot\\dfrac{{5}}{{2}y}={1}\\Leftrightarrow\\dfrac{{20}}{{2}xy}={1}\\Leftrightarrow{2}xy={20}\\Leftrightarrow xy={10}$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tập nghiệm của bất phương trình $|{2}x-{3}|>x+{1}$ là", "choices": ["$\\mathbb{R}$", "$\\left(-\\infty;-\\dfrac{{4}}{{3}}\\right)$", "$({2};+\\infty)$", "$\\left(-\\infty;\\dfrac{{2}}{{3}}\\right)\\cup({4};+\\infty)$"], "correctIndex": 3, "explain": "$$|{2}x-{3}|>x+{1}\\Leftrightarrow\\hoac{&{2}x-{3}>x+{1}<br>&{2}x-{3}<-(x+{1})}\\Leftrightarrow\\hoac{&x>{4}<br>&{2}x-{3}<-x-{1}}\\Leftrightarrow\\hoac{&x>{4}<br>&{3}x<{2}}\\Leftrightarrow\\hoac{&x>{4}<br>&x<\\dfrac{{2}}{{3}}}$$  Tập nghiệm của bất phương trình là $\\left(-\\infty;\\dfrac{{2}}{{3}}\\right)\\cup({4};+\\infty)$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biết đồ thị hàm số $y=\\dfrac{{6}-{4}x}{{2}x+{3}}$ có ${2}$ tiệm cận giao với $Ox$, $Oy$ tạo thành hình chữ nhật. Diện tích của hình chữ nhật:", "choices": ["${3}$", "${4}$", "${6}$", "${12}$"], "correctIndex": 0, "explain": "Tiệm cận đứng: ${2}x+{3}={0}\\Leftrightarrow x=-\\dfrac{{3}}{{2}}$. Khoảng cách từ trục $Oy$ đến tiệm cận đứng là $a=\\left|-\\dfrac{{3}}{{2}}\\right|=\\dfrac{{3}}{{2}}$.<br>Tiệm cận ngang: $y=\\dfrac{-{4}}{{2}}=-{2}$. Khoảng cách từ trục $Ox$ đến tiệm cận ngang là $b=|-{2}|={2}$.<br>Diện tích hình chữ nhật tạo bởi hai tiệm cận và hai trục tọa độ là: $S=a\\cdot b=\\dfrac{{3}}{{2}}\\cdot{2}={3}$"}]}, {"noiDungChung": "Một nhà máy sử dụng ${2}$ nguyên liệu $X$ và $Y$ để sản xuất sản phẩm mỹ nghệ. Tổng khối lượng nguyên liệu không quá ${8}$ tạ. Biết rằng để sản xuất ${1}$ tạ nguyên liệu $X$ mất ${20}$ ngày và thu được ${3}$ tỷ đồng; để sản xuất ${1}$ tạ nguyên liệu $Y$ thì mất ${30}$ ngày và thu được ${4}$ tỷ đồng. Tổng số ngày làm việc không quá ${180}$ ngày. Gọi $x$ và $y$ lần lượt là khối lượng (tính bằng tạ) của nguyên liệu $X$ và nguyên liệu $Y$ mà nhà máy sử dụng ($x\\ge{0}$, $y\\ge{0}$).", "cauHoi": [{"question": "Bất phương trình biểu diễn số ngày làm việc:", "choices": ["${2}x+{3}y\\le{18}$", "$x+y\\le{8}$", "${2}x+{3}y\\ge{18}$", "$x+y\\ge{8}$"], "correctIndex": 0, "explain": "Theo giả thiết, ${1}$ tạ nguyên liệu $X$ cần ${20}$ ngày, vậy $x$ tạ cần ${20}x$ ngày.<br>Tương tự, ${1}$ tạ nguyên liệu $Y$ cần ${30}$ ngày, vậy $y$ tạ cần ${30}y$ ngày.<br>Tổng số ngày làm việc không quá ${180}$ ngày, ta có bất phương trình: ${20}x+{30}y\\le{180}$<br>Chia cả hai vế cho ${10}$, ta được bất phương trình rút gọn: ${2}x+{3}y\\le{18}$"}, {"question": "Lợi nhuận lớn nhất là:", "choices": ["${30}$", "${24}$", "${28}$", "${26}$"], "correctIndex": 3, "explain": "Ta cần tìm giá trị lớn nhất của hàm lợi nhuận $F(x,y)={3}x+{4}y$ (tỷ đồng) dựa trên hệ bất phương trình ràng buộc sau:  $$\\heva{&x\\ge{0}<br>&y\\ge{0}<br>&x+y\\le{8}<br>&{2}x+{3}y\\le{18}}$$<br>Ta đi tìm các đỉnh của đa giác miền nghiệm bằng cách giải các hệ phương trình giao điểm:<br>a) Giao của $x={0}$ và $y={0}\\Rightarrow A({0};{0})$  <br>b) Giao của $x={0}$ và ${2}x+{3}y={18}\\Rightarrow B({0};{6})$  <br>c) Giao của $y={0}$ và $x+y={8}\\Rightarrow C({8};{0})$  <br>d) Giao của $x+y={8}$ và ${2}x+{3}y={18}$: $\\Rightarrow D({6};{2})$<br>Thay tọa độ các đỉnh vào hàm mục tiêu $F(x,y)={3}x+{4}y$:<br>a) Tại $A({0};{0})$: $F={3}({0})+{4}({0})={0}$  <br>b) Tại $B({0};{6})$: $F={3}({0})+{4}({6})={24}$  <br>c) Tại $C({8};{0})$: $F={3}({8})+{4}({0})={24}$  <br>d) Tại $D({6};{2})$: $F={3}({6})+{4}({2})={18}+{8}={26}$<br>So sánh các giá trị, ta thấy lợi nhuận lớn nhất đạt được là ${26}$ tỷ đồng khi sử dụng ${6}$ tạ nguyên liệu $X$ và ${2}$ tạ nguyên liệu $Y$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.8]\n\t\t\t\t\n\t\t\t\t\\draw[step=1cm, gray!30, dashed] (-1,-1) grid (9,9);\n\t\t\t\t\\draw[->, thick] (-1,0) -- (9.5,0) node[right] {$x$};\n\t\t\t\t\\draw[->, thick] (0,-1) -- (0,9.5) node[above] {$y$};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\foreach \\x in {2,4,6,8}\n\t\t\t\t\\draw (\\x, 0.1) -- (\\x, -0.1) node[below, font=\\footnotesize] {\\x};\n\t\t\t\t\\foreach \\y in {2,4,6,8}\n\t\t\t\t\\draw (0.1, \\y) -- (-0.1, \\y) node[left, font=\\footnotesize] {\\y};\n\t\t\t\t\\node[below left, font=\\footnotesize] at (0,0) {$0$};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\fill[gray, opacity=0.3] (0,0) -- (0,6) -- (6,2) -- (8,0) -- cycle;\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\draw[blue, thick] (0,8) -- (8,0) node[midway, above right, sloped, font=\\footnotesize] {$x+y=8$};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\draw[red, thick] (0,6) -- (9,0) node[midway, below left, sloped, font=\\footnotesize] {$2x+3y=18$};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\filldraw (0,0) circle (2pt) node[above left, font=\\footnotesize] {$A$};\n\t\t\t\t\\filldraw (0,6) circle (2pt) node[above right, font=\\footnotesize] {$B$};\n\t\t\t\t\\filldraw (8,0) circle (2pt) node[below right, font=\\footnotesize] {$C$};\n\t\t\t\t\\filldraw (6,2) circle (2pt) node[above right, font=\\footnotesize] {$D$};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\node[fill=yellow!20, draw=orange, rounded corners, font=\\small\\bfseries] at (6.8, 5) {$F_{max} = 26$ tại $D(6;2)$};\n\t\t\t\t\\draw[->, orange, thick] (6.5, 4.5) -- (6.1, 2.1);\n\t\t\t\t\n\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Bạn $A$ thả quả bóng cao su từ độ cao ${10}\\text{ m}$ theo phương thẳng đứng. Mỗi khi chạm đất nó lại nảy lên theo phương thẳng đứng một đoạn bằng $\\dfrac{{3}}{{4}}$ độ cao trước đó.", "cauHoi": [{"question": "Sau ${5}$ lần chạm đất độ cao cực đại của quả bóng là", "choices": ["${3}{,}{16}$", "${1}{,}{78}$", "${2}{,}{37}$", "${3}{,}{25}$"], "correctIndex": 2, "explain": "Gọi $h_{{0}}={10}$ là độ cao ban đầu của quả bóng (đơn vị: mét).<br>Độ cao cực đại của quả bóng sau lần chạm đất thứ $n$ lập thành một cấp số nhân với công bội $q=\\dfrac{{3}}{{4}}$.<br>Sau lần chạm đất thứ ${5}$, độ cao cực đại của quả bóng là:  $$h_{{5}}=h_{{0}}\\cdot q^{{5}}={10}\\cdot\\left(\\dfrac{{3}}{{4}}\\right)^{{5}}={10}\\cdot\\dfrac{{243}}{{1024}}=\\dfrac{{1215}}{{512}}\\approx{2}{,}{37}\\text{ (m)}$$"}, {"question": "Tổng quãng đường quả bóng đi được đến khi dừng hẳn:", "choices": ["${40}$", "${70}$", "${50}$", "${80}$"], "correctIndex": 1, "explain": "Quãng đường quả bóng đi được bao gồm:<br>a) Quãng đường rơi xuống lần đầu tiên: $S_{{0}}=h_{{0}}={10}$.  <br>a) Quãng đường nảy lên và rơi xuống sau các lần chạm đất tiếp theo (mỗi lần gồm một lượt lên và một lượt xuống bằng nhau).<br>b) Lần này ${1}$: lên $h_{{1}}$, xuống $h_{{1}}\\Rightarrow$ quãng đường ${2}h_{{1}}$  <br>c) Lần này ${2}$: lên $h_{{2}}$, xuống $h_{{2}}\\Rightarrow$ quãng đường ${2}h_{{2}}$  <br>d) $\\dots$<br>Tổng quãng đường quả bóng đi được cho đến khi dừng hẳn là tổng của một cấp số nhân lùi vô hạn:  $$S=h_{{0}}+{2}h_{{1}}+{2}h_{{2}}+{2}h_{{3}}+\\dots$$  $$S=h_{{0}}+{2}(h_{{1}}+h_{{2}}+h_{{3}}+\\dots)$$  Cụm trong ngoặc là tổng của cấp số nhân lùi vô hạn với số hạng đầu $u_{{1}}=h_{{1}}={10}\\cdot\\dfrac{{3}}{{4}}={7}{,}{5}$ và công bội $q=\\dfrac{{3}}{{4}}$.<br>Tổng cấp số nhân lùi vô hạn này là: $S=\\dfrac{u_{{1}}}{{1}-q}=\\dfrac{{7}{,}{5}}{{1}-\\dfrac{{3}}{{4}}}=\\dfrac{{7}{,}{5}}{{0}{,}{25}}={30}$.<br>Vậy tổng quãng đường quả bóng đi được là: $S={10}+{2}\\cdot{30}={10}+{60}={70}\\text{ (m)}$"}]}, {"noiDungChung": "Trong hệ trục tọa độ $Oxyz$, cho điểm $A({1};{1};{1})$; $B({2};{0};{2})$ và $C({3};{1};-{3})$.", "cauHoi": [{"question": "Tính độ dài đoạn thẳng $AB$", "choices": ["${2}$", "$\\sqrt{{3}}$", "${2}\\sqrt{{6}}$", "${2}\\sqrt{{3}}$"], "correctIndex": 1, "explain": "$\\vec{AB}=({2}-{1};{0}-{1};{2}-{1})=({1};-{1};{1})$<br>Độ dài đoạn thẳng $AB$ chính là độ dài của vectơ $\\vec{AB}$: $AB=|\\vec{AB}|=\\sqrt{{1}^{2}+(-{1})^{2}+{1}^{2}}=\\sqrt{{1}+{1}+{1}}=\\sqrt{{3}}$"}, {"question": "Trong hệ trục tọa độ $Oxyz$, cho điểm $A({1};{1};{1})$; $B({2};{0};{2})$ và $C({3};{1};-{3})$. Tìm giao điểm của $(ABC)$ và $Ox$", "choices": ["$E({3};{0};{0})$", "$E({2};{0};{0})$", "$E({1};{0};{0})$", "$E({0};{3};{0})$"], "correctIndex": 0, "explain": "$\\vec{AB}=({1};-{1};{1})$.<br>$\\vec{AC}=({2};{0};-{4})$<br>$\\vec{n}=[\\vec{AB},\\vec{AC}]=\\left(\\left|\\begin{matrix}-{1}&{1}\\\\{0}&-{4}\\end{matrix}\\right|;\\left|\\begin{matrix}{1}&{1}\\\\-{4}&{2}\\end{matrix}\\right|;\\left|\\begin{matrix}{1}&-{1}\\\\{2}&{0}\\end{matrix}\\right|\\right)=({4};{6};{2})$<br>Để phương trình gọn hơn, ta có thể chọn vecto pháp tuyến là $\\vec{n}'=\\dfrac{{1}}{{2}}\\vec{n}=({2};{3};{1})$.<br>Mặt phẳng $(ABC)$ đi qua điểm $A({1};{1};{1})$ và có vecto pháp tuyến $\\vec{n}'({2};{3};{1})$ có phương trình tổng quát là:<br>${2}(x-{1})+{3}(y-{1})+{1}(z-{1})={0}\\Leftrightarrow{2}x-{2}+{3}y-{3}+z-{1}={0}\\Leftrightarrow{2}x+{3}y+z-{6}={0}$<br>Gọi $M$ là giao điểm của mặt phẳng $(ABC)$ và trục $Ox$. Vì điểm $M$ nằm trên trục $Ox$ nên tọa độ của nó có dạng $M(x;{0};{0})$.<br>Vì $M\\in(ABC)$, ta thay tọa độ của điểm $M$ vào phương trình mặt phẳng $(ABC)$ vừa tìm được:<br>${2}x+{3}({0})+{0}-{6}={0}\\Leftrightarrow{2}x-{6}={0}\\Leftrightarrow x={3}$<br>Vậy tọa độ của điểm $M$ là $({3};{0};{0})$."}]}, {"noiDungChung": "Có ${6}$ ghế xếp thành hàng ngang. Xếp ngẫu nhiên ${6}$ học sinh vào hàng ghế này, trong đó có ${3}$ học sinh lớp $A$, ${2}$ học sinh lớp $B$ và ${1}$ học sinh lớp $C$.", "cauHoi": [{"question": "Số cách xếp ${6}$ học sinh ngồi vào hàng là", "choices": ["${6}!$", "${6}!-1$", "$C_{{6}}^{{4}}$", "$A_{{6}}^{{4}}$"], "correctIndex": 0, "explain": "Số cách xếp là $P_{{6}}={6}!$ (cách)."}, {"question": "Số cách xếp sao cho hai học sinh lớp $B$ ngồi hai đầu ghế là", "choices": ["${48}$", "${42}$", "${60}$", "${124}$"], "correctIndex": 0, "explain": "Xếp ${2}$ học sinh lớp $B$ vào ${2}$ vị trí đầu và cuối của hàng ghế, có: $P_{{2}}={2}!={2}$ (cách).<br>Xếp ngẫu nhiên ${4}$ học sinh còn lại vào ${4}$ ghế trống, số cách xếp là: $P_{{4}}={4}!={24}$ (cách).<br>Áp dụng quy tắc nhân, tổng số cách xếp thoả mãn yêu cầu bài toán là: ${2}!\\times{4}!={2}\\times{24}={48}$ (cách)."}, {"question": "Xác suất để xếp học sinh lớp $C$ chỉ ngồi cạnh học sinh lớp $B$ là", "choices": ["$\\dfrac{{1}}{{6}}$", "$\\dfrac{{2}}{{15}}$", "$\\dfrac{{1}}{{5}}$", "$\\dfrac{{3}}{{20}}$"], "correctIndex": 2, "explain": "Không gian mẫu: Xếp ngẫu nhiên ${6}$ học sinh vào ${6}$ ghế: $n(\\Omega)={6}!=720$.<br>Gọi $X$ là biến cố: \"Học sinh lớp $C$ chỉ ngồi cạnh học sinh lớp $B$\".<br>Chia làm ${2}$ trường hợp:<br>a) Trường hợp ${1}$: Học sinh $C$ ngồi ở ${1}$ trong ${2}$ ghế ngoài cùng (ghế số ${1}$ hoặc ghế số ${6}$).  + Chọn vị trí cho học sinh $C$ (ghế đầu hoặc ghế cuối): Có ${2}$ cách.<br>+ Chọn ${1}$ học sinh lớp $B$ ngồi cạnh học sinh $C$: Có ${2}$ cách.<br>+ Xếp ${4}$ học sinh còn lại vào ${4}$ ghế trống: Có ${4}!=24$ cách.<br>+ Số cách xếp cho trường hợp ${1}$ là: ${2}\\times{2}\\times24={96}$ (cách).  <br>b) Trường hợp ${2}$: Học sinh $C$ ngồi ở các ghế giữa (ghế số ${2}$, ${3}$, ${4}$, ${5}$).<br>Lúc này, học sinh $C$ có đúng ${2}$ người ngồi cạnh hai bên. Yêu cầu bài toán buộc cả ${2}$ người này đều phải là học sinh lớp $B$. Vì chỉ có đúng ${2}$ học sinh lớp $B$, nên ta sẽ tạo thành một cụm cố định gồm ${3}$ học sinh: (Học sinh $B$ - Học sinh $C$ - Học sinh $B$).<br>a) Sắp xếp vị trí của ${2}$ học sinh lớp $B$ trong cụm này: Có ${2}!={2}$ cách.  <br>b) Coi cụm ${3}$ học sinh này là một phần tử. Cùng với ${3}$ học sinh lớp $A$ còn lại, ta có tổng cộng ${4}$ phần tử cần xếp vào hàng ngang. Số cách hoán vị ${4}$ phần tử này là: ${4}!=24$ cách.  <br>c) Số cách xếp cho trường hợp ${2}$ là: ${2}\\times24={48}$ (cách).<br>Tổng số kết quả thuận lợi cho biến cố $X$ là: $n(X)={96}+{48}=144$ (cách).<br>Xác suất của biến cố $X$ là: $P(X)=\\dfrac{n(X)}{n(\\Omega)}=\\dfrac{144}{720}=\\dfrac{{1}}{{5}}$"}]}, {"noiDungChung": "Cho tọa độ các điểm $A({1};{2})$, $B(-{1};{1})$, $C({3};-{1})$.", "cauHoi": [{"question": "Tọa độ trung điểm $M$ của $BC$ là", "choices": ["$M({1};{0})$", "$M({0};{1})$", "$M\\left({0};\\dfrac{{3}}{{2}}\\right)$", "$M\\left(-{1};\\dfrac{{3}}{{2}}\\right)$"], "correctIndex": 0, "explain": "Trung điểm $M$ của $BC$ có tọa độ:  $x_M = \\dfrac{x_B + x_C}{{2}} = \\dfrac{-{1}+{3}}{{2}} = {1}$; $y_M = \\dfrac{y_B + y_C}{{2}} = \\dfrac{{1}-{1}}{{2}} = {0}$. Vậy $M({1};{0})$."}, {"question": "Phương trình tổng quát đường cao kẻ từ đỉnh $A$ của tam giác $ABC$ là", "choices": ["${2}x-y={0}$", "${2}x+y={0}$", "${2}x-{3}y={0}$", "$x-{2}y={0}$"], "correctIndex": 0, "explain": "Đường cao kẻ từ $A$ đi qua $A({1};{2})$ và vuông góc với $BC$.<br>Véctơ $\\vec{BC} = ({4};-{2})$, chọn véctơ pháp tuyến $\\vec{n} = ({2};-{1})$.<br>Phương trình: ${2}(x-{1}) - {1}(y-{2}) = {0} \\Leftrightarrow {2}x - y = {0}$."}, {"question": "Tổng hoành độ và tung độ của tâm đường tròn ngoại tiếp tam giác $ABC$", "choices": ["$\\dfrac{{4}}{{7}}$", "$\\dfrac{{5}}{{8}}$", "$\\dfrac{{3}}{{5}}$", "$\\dfrac{{3}}{{8}}$"], "correctIndex": 1, "explain": "Gọi phương trình đường tròn loại 2 là $(C): x^2 + y^2 + ax + by + c = 0$.  Thay tọa độ các điểm $A, B, C$ vào phương trình, ta được hệ phương trình:  $$\\heva{&{1}+{4}+a+{2}b+c={0} <br>&{1}+{1}-a+b+c={0} <br>&{9}+{1}+{3}a-b+c={0}} \\Leftrightarrow \\heva{&a+{2}b+c=-{5} <br>&-a+b+c=-{2} <br>&{3}a-b+c=-{10}}$$  Giải hệ phương trình trên, ta được: $a=-\\dfrac{{7}}{{4}}$, $b=\\dfrac{{1}}{{2}}$, $c=-\\dfrac{{17}}{{4}}$.<br>Tọa độ tâm $I\\left(-\\dfrac{a}{2};-\\dfrac{b}{2}\\right) = \\left(\\dfrac{{7}}{{8}};-\\dfrac{{1}}{{4}}\\right)$.<br>Tổng hoành độ và tung độ của tâm $I$ là: $x+y = \\dfrac{{7}}{{8}} + \\left(-\\dfrac{{1}}{{4}}\\right) = \\dfrac{{5}}{{8}}$."}]}, {"noiDungChung": "Cho hình chóp $S.ABCD$ có đáy là hình vuông tâm $O$, cạnh bằng $a$. Tam giác $SAB$ đều và nằm trong mặt phẳng vuông góc với đáy. Gọi $H$ là trung điểm của $AB$, $N$ là trung điểm của $AD$.", "cauHoi": [{"question": "Hình chiếu vuông góc của $S$ lên $(ABCD)$ là điểm", "choices": ["$H$", "$O$", "$N$", "$A$"], "correctIndex": 0, "explain": "Ta có:<br>a) $(SAB)\\perp(ABCD)$  <br>b) $(SAB)\\cap(ABCD)=AB$  <br>c) Trong $\\Delta SAB$ đều, $H$ là trung điểm $AB$ nên $SH\\perp AB$.<br>Từ đó suy ra $SH\\perp(ABCD)$.<br>Vậy hình chiếu vuông góc của $S$ lên mặt phẳng $(ABCD)$ chính là điểm $H$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1.2, line cap=round, line join=round]\n\t\t\t\t\t\\coordinate (A) at (0,0);\n\t\t\t\t\t\\coordinate (B) at (3,-1.5);\n\t\t\t\t\t\\coordinate (C) at (6.5,-1.5);\n\t\t\t\t\t\\coordinate (D) at (3.5,0); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (H) at ($(A)!0.5!(B)$);\n\t\t\t\t\t\\coordinate (N) at ($(A)!0.5!(D)$);\n\t\t\t\t\t\\coordinate (S) at ($(H)+(0,3.8)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed, thin] (A) -- (D);\n\t\t\t\t\t\\draw[dashed, thin] (D) -- (C);\n\t\t\t\t\t\\draw (S) -- (H);\n\t\t\t\t\t\\draw[dashed, thin] (A) -- (C);\n\t\t\t\t\t\\draw[dashed, thin] (B) -- (D); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (O) at (intersection of A--C and B--D);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick] (S) -- (A);\n\t\t\t\t\t\\draw[thick] (S) -- (B);\n\t\t\t\t\t\\draw[thick] (S) -- (C);\n\t\t\t\t\t\\draw[thick] (A) -- (B);\n\t\t\t\t\t\\draw[thick] (B) -- (C);\n\t\t\t\t\t\\draw[dashed] (S) -- (D);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\fill (A) circle (1.5pt) node[left] {$A$};\n\t\t\t\t\t\\fill (B) circle (1.5pt) node[below] {$B$};\n\t\t\t\t\t\\fill (C) circle (1.5pt) node[right] {$C$};\n\t\t\t\t\t\\fill (D) circle (1.5pt) node[above] {$D$};\n\t\t\t\t\t\\fill (S) circle (1.5pt) node[above] {$S$};\n\t\t\t\t\t\\fill (H) circle (1.2pt) node[below left] {$H$};\n\t\t\t\t\t\\fill (N) circle (1.2pt) node[above right] {$N$};\n\t\t\t\t\t\\fill (O) circle (1.2pt) node[above right] {$O$};\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thin] ($(H)+(0,0.15)$) -- ($(H)+(0.15,0.15)$) -- ($(H)+(0.15,0)$);\n\t\t\t\t\t\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Phát biểu nào sau đây sai?", "choices": ["$d(D;(SAC))=d(H;(SAC))$", "$d(D;(SAC))=d(B;(SAC))$", "$V_{S.ABCD}=\\dfrac{a^{3}\\sqrt{{3}}}{{6}}$", "$SH=\\dfrac{a\\sqrt{{3}}}{{2}}$"], "correctIndex": 0, "explain": "Kiểm tra từng phát biểu:<br>a) Phát biểu D: Tam giác $SAB$ đều cạnh $a$, đường cao $SH=\\dfrac{a\\sqrt{{3}}}{{2}}$. $\\Rightarrow$ Đúng.  <br>b) Phát biểu C: Thể tích khối chóp $V_{S.ABCD}=\\dfrac{{1}}{{3}}\\cdot S_{ABCD}\\cdot SH=\\dfrac{{1}}{{3}}\\cdot a^{2}\\cdot\\dfrac{a\\sqrt{{3}}}{{2}}=\\dfrac{a^{3}\\sqrt{{3}}}{{6}}$. $\\Rightarrow$ Đúng.  <br>c) Phát biểu B: Vì $O$ là trung điểm của $BD$ và $O\\in(SAC)$ nên khoảng cách từ $B$ và $D$ đến mặt phẳng $(SAC)$ là bằng nhau: $d(D;(SAC))=d(B;(SAC))$. $\\Rightarrow$ Đúng.  <br>d) Phát biểu A: Đường thẳng $AB$ cắt $(SAC)$ tại $A$, do đó:  $$\\dfrac{d(H;(SAC))}{d(B;(SAC))}=\\dfrac{HA}{BA}=\\dfrac{{1}}{{2}}$$<br>Suy ra $d(H;(SAC))=\\dfrac{{1}}{{2}}d(B;(SAC))=\\dfrac{{1}}{{2}}d(D;(SAC))$.<br>Do đó, $d(D;(SAC))\\neq d(H;(SAC))$. $\\Rightarrow$ Sai."}, {"question": "Khoảng cách từ $D$ đến mặt phẳng $(SAC)$ là bao nhiêu?", "choices": ["$\\dfrac{a\\sqrt{{21}}}{{14}}$", "$\\dfrac{a\\sqrt{{21}}}{{28}}$", "$\\dfrac{a\\sqrt{{21}}}{{7}}$", "$\\dfrac{a\\sqrt{{2}}}{{2}}$"], "correctIndex": 2, "explain": "Từ chứng minh ở câu trên, ta có: $d(D;(SAC))={2}\\cdot d(H;(SAC))$.<br>Ta đi tính $d(H;(SAC))$:<br>Kẻ $HK\\perp AC$ tại $K$, và kẻ $HI\\perp SK$ tại $I$.<br>Ta có:  $$\\heva{&AC\\perp HK<br>&AC\\perp SH\\text{ (do }SH\\perp(ABCD))}\\Rightarrow AC\\perp(SHK)\\Rightarrow AC\\perp HI$$  Mặt khác $HI\\perp SK$, suy ra $HI\\perp(SAC)$. Vậy $d(H;(SAC))=HI$.<br>Xét trong mặt đáy $ABCD$, $O$ là giao điểm hai đường chéo nên $BO\\perp AC$.<br>Trong tam giác $ABO$ vuông tại $O$, $H$ là trung điểm $AB$, $HK\\parallel BO$ (cùng vuông góc với $AC$ nên $HK$ là đường trung bình.  $$\\Rightarrow HK=\\dfrac{{1}}{{2}}BO=\\dfrac{{1}}{{2}}\\left(\\dfrac{a\\sqrt{{2}}}{{2}}\\right)=\\dfrac{a\\sqrt{{2}}}{{4}}$$  Xét tam giác $SHK$ vuông tại $H$, có đường cao $HI$:  $$\\dfrac{{1}}{HI^{2}}=\\dfrac{{1}}{SH^{2}}+\\dfrac{{1}}{HK^{2}}=\\dfrac{{1}}{\\left(\\dfrac{a\\sqrt{{3}}}{{2}}\\right)^{2}}+\\dfrac{{1}}{\\left(\\dfrac{a\\sqrt{{2}}}{{4}}\\right)^{2}}=\\dfrac{{4}}{{3}a^{2}}+\\dfrac{{16}}{{2a^{2}}}=\\dfrac{{28}}{{3}a^{2}}\\Rightarrow HI=\\dfrac{a\\sqrt{{3}}}{{2}\\sqrt{{7}}}=\\dfrac{a\\sqrt{{21}}}{{14}}$$  Vậy khoảng cách cần tìm là: $d(D;(SAC))={2}\\cdot HI={2}\\cdot\\dfrac{a\\sqrt{{21}}}{{14}}=\\dfrac{a\\sqrt{{21}}}{{7}}$."}]}, {"noiDungChung": "Cho hàm số $y=\\dfrac{-mx+1}{x-m}$.", "cauHoi": [{"question": "Với $m={2}$ thì giá trị lớn nhất của hàm số trên ${[{3};{5}]}$ là", "choices": ["$-{2}$", "$-{1}$", "${3}$", "$-{3}$"], "correctIndex": 3, "explain": "Thay $m={2}$ vào hàm số, ta có $y=\\dfrac{-{2}x+{1}}{x-{2}}$.<br>Tập xác định: $D=\\mathbb{R}\\setminus\\{{2}\\}$.<br>Đoạn ${[{3};{5}]}$ nằm trọn trong tập xác định.<br>Ta tính đạo hàm:  $$y'=\\dfrac{-{3}}{(x-{2})^{2}}>{0},\\forall x\\in{[{3};{5}]}$$  Vì $y'>0$ nên hàm số đồng biến trên đoạn ${[{3};{5}]}$.<br>Do đó, giá trị lớn nhất của hàm số trên đoạn này đạt được tại $x={5}$: $\\max\\limits_{[{3};{5}]}y=y({5})=\\dfrac{-{2}({5})+{1}}{{5}-{2}}=\\dfrac{-{9}}{{3}}=-{3}$"}, {"question": "Với giá trị nào của tham số $m$ thì hàm số đồng biến trên từng khoảng xác định?", "choices": ["$m\\in(-\\infty;-{1})\\cup({1};+\\infty)$", "$m\\in(-\\infty;{0})\\cup({5};+\\infty)$", "$m\\in(-\\infty;-{2})\\cup({1};+\\infty)$", "$m\\in(-\\infty;{0})\\cup({1};+\\infty)$"], "correctIndex": 0, "explain": "Tập xác định: $D=\\mathbb{R}\\setminus\\{m\\}$.<br>$y'=\\dfrac{m^{2}-{1}}{(x-m)^{2}}$<br>Để hàm số đồng biến trên từng khoảng xác định, ta cần có $y'>0,\\forall x\\in D$:  $$\\Leftrightarrow m^{2}-{1}>{0}\\Leftrightarrow\\hoac{&m>{1}<br>&m<-{1}}\\Rightarrow m\\in(-\\infty;-{1})\\cup({1};+\\infty)$$"}, {"question": "Khi $m$ thay đổi trong $({3};+\\infty)$ thì đồ thị hàm số đi qua mấy điểm cố định?", "choices": ["${2}$ điểm", "${1}$ điểm", "${0}$ điểm", "${4}$ điểm"], "correctIndex": 0, "explain": "Gọi $M(x_{{0}};y_{{0}})$ là điểm cố định mà đồ thị hàm số luôn đi qua. Khi đó, phương trình sau phải đúng với mọi $m\\in({3};+\\infty)$ (lưu ý điều kiện $x_{{0}}\\neq m$):  $$y_{{0}}=\\dfrac{-mx_{{0}}+{1}}{x_{{0}}-m}\\Leftrightarrow y_{{0}}(x_{{0}}-m)=-mx_{{0}}+{1}\\Leftrightarrow x_{{0}}y_{{0}}-my_{{0}}=-mx_{{0}}+{1}\\Leftrightarrow m(x_{{0}}-y_{{0}})+(x_{{0}}y_{{0}}-{1})={0},\\forall m\\in({3};+\\infty)$$  Để phương trình đúng với mọi $m$, các hệ số phải đồng thời bằng ${0}$:  $$\\heva{&x_{{0}}-y_{{0}}={0}<br>&x_{{0}}y_{{0}}-{1}={0}}\\Leftrightarrow\\heva{&y_{{0}}=x_{{0}}<br>&x_{{0}}^{2}={1}}\\Leftrightarrow\\hoac{\\heva{&x_{{0}}={1}<br>&y_{{0}}={1}}<br>\\heva{&x_{{0}}=-{1}<br>&y_{{0}}=-{1}}}$$  Kiểm tra điều kiện $x_{{0}}\\neq m$: Vì $m\\in({3};+\\infty)$ nên $m$ không thể bằng ${1}$ hoặc $-{1}$. Do đó cả hai điểm $({1};{1})$ và $(-{1};-{1})$ đều luôn thỏa mãn và nằm trên đồ thị.<br>Vậy đồ thị hàm số đi qua ${2}$ điểm cố định."}]}, {"noiDungChung": "Trong ${7}$ ngày, một công ty sắp xếp chỗ cho ${5}$ nhân viên $M$, $N$, $P$, $Q$, $R$ tham gia các khóa huấn luyện. Mỗi nhân viên sẽ được huấn luyện trong ${1}$ ngày, ${2}$ nhân viên khác nhau sẽ được huấn luyện trong ${2}$ ngày khác nhau. Ngoài ra các khóa huấn luyện được tổ chức tuân thủ các điều kiện sau:<br>a) Không có nhân viên nào tham gia huấn luyện vào ngày thứ ${6}$.  <br>b) $R$ phải được tham gia huấn luyện trước $N$.  <br>c) $M$ được huấn luyện ở ngày ngay trước ngày mà $Q$ được huấn luyện (cặp $(M, Q)$).  <br>d) $P$ là người thứ ${3}$ được huấn luyện.", "cauHoi": [{"question": "Nếu $P$ được xếp vào ngày thứ ${4}$, thì điều nào sau đây phải đúng:", "choices": ["M được huấn luyện ở ngày thứ nhất", "Ngày thứ ${3}$ không có ai được huấn luyện", "R được huấn luyện vào ngày thứ ${5}$", "M được huấn luyện ở ngày thứ ${2}$"], "correctIndex": 2, "explain": "Theo giả thiết bổ sung của câu hỏi, $P$ (người thứ $3$ theo thứ tự học) được xếp vào ngày thứ ${4}$ trong tuần. Kết hợp với việc ngày thứ $6$ không có ai học và cặp $(M, Q)$ học liền nhau, ta xác định được lịch trình thỏa mãn các điều kiện, trong đó $R$ phải được huấn luyện vào ngày thứ ${5}$."}, {"question": "$R$ có thể được huấn luyện vào ngày nào?", "choices": ["Thứ ${7}$", "Thứ ${2}$", "Thứ ${3}$", "Thứ ${4}$"], "correctIndex": 3, "explain": "Dựa vào các ràng buộc về thứ tự ($R$ trước $N$, $P$ là người thứ $3$ học, và ngày thứ $6$ trống), $R$ có thể được sắp xếp huấn luyện vào ngày thứ ${4}$."}, {"question": "Ngày nào sau đây phải có ${1}$ nhân viên được huấn luyện", "choices": ["Thứ ${2}$", "Thứ ${3}$", "Thứ ${4}$", "Thứ nhất"], "correctIndex": 0, "explain": "Dựa trên tổng số ${5}$ nhân viên phân bổ trong $7$ ngày (với ngày thứ $6$ không có ai và các điều kiện trật tự cứng), ngày thứ ${2}$ luôn bắt buộc phải có nhân viên tham gia huấn luyện."}]}, {"noiDungChung": "Một biên tập viên sẽ biên tập ${7}$ bài viết, mỗi lần một bài, có ${3}$ bài viết $G$, $H$ và $J$ thuộc chủ đề Tài chính; ${3}$ bài viết khác $Q$, $R$ và $S$ thuộc chủ đề Dinh dưỡng; và bài viết còn lại là $Y$ thì thuộc chủ đề Động vật hoang dã. Thứ tự biên tập các bài viết phải tuân theo các điều kiện sau:<br>a) Các bài viết liên tiếp không được thuộc cùng một chủ đề.  <br>b) $S$ chỉ có thể được biên tập trước $Q$ nếu $Q$ là bài viết thứ ba được biên tập. (Tức là nếu $Q$ không xếp thứ $3$ thì bắt buộc $Q$ phải xếp trước $S$).  <br>c) $S$ phải được biên tập trước $Y$.  <br>d) $J$ phải được biên tập trước $G$ và $G$ phải được biên tập trước $R$.", "cauHoi": [{"question": "Đâu là thứ tự biên tập có thể đúng?", "choices": ["$J, Q, S, G, H, Y, R$", "$Q, J, S, H, Y, G, R$", "$Q, G, S, H, Y, J, R$", "$Q, J, Y, H, S, G, R$"], "correctIndex": 1, "explain": "Ký hiệu các chủ đề: Tài chính (T), Dinh dưỡng (D), Động vật (W). Ta kiểm tra các phương án:<br>a) Phương án $J, Q, S, G, H, Y, R$ sai vì $G$ và $H$ (cùng chủ đề T) xếp liền nhau.  <br>b) Phương án $Q, G, S, H, Y, J, R$ sai vì $G$ xếp trước $J$ (trái điều kiện $J$ trước $G$).  <br>c) Phương án $Q, J, Y, H, S, G, R$ sai vì $Y$ xếp trước $S$ (trái điều kiện $S$ trước $Y$).  <br>d) Phương án $Q, J, S, H, Y, G, R$ thỏa mãn tất cả các điều kiện: chủ đề xen kẽ (D-T-D-T-W-T-D); $J$ trước $G$ trước $R$; $S$ trước $Y$; và do $Q$ xếp trước $S$ nên không vi phạm ràng buộc vị trí của cặp $S, Q$."}, {"question": "Nếu $G$ là bài viết thứ tư được biên tập, khẳng định có thể đúng là", "choices": ["$J$ là bài viết thứ nhất được biên tập", "$Q$ là bài viết thứ hai được biên tập", "$S$ là bài viết thứ năm được biên tập", "$Y$ là bài viết thứ sáu được biên tập"], "correctIndex": 3, "explain": "Giả sử $Y$ xếp thứ $6$, ta có thể thiết lập một thứ tự hoàn toàn hợp lệ như sau: $S(1), J(2), Q(3), G(4), R(5), Y(6), H(7)$.<br>a) Các chủ đề phân bổ xen kẽ hợp lý: Dinh dưỡng (1, 3, 5), Tài chính (2, 4, 7) và Động vật (6).  <br>b) $J(2)$ trước $G(4)$ trước $R(5)$.  <br>c) $S(1)$ trước $Y(6)$.  <br>d) $S(1)$ xếp trước $Q(3)$, và $Q$ nằm đúng vị trí thứ $3$ (thỏa mãn trọn vẹn điều kiện của cặp này).<br>Do đó, trường hợp $Y$ là bài viết thứ sáu hoàn toàn có thể xảy ra."}, {"question": "Thứ tự biên tập ${7}$ bài viết có thể được xác định hoàn toàn nếu như", "choices": ["$R$ là bài viết thứ bảy được biên tập", "$R$ là bài viết thứ tư được biên tập", "$H$ là bài viết thứ sáu được biên tập", "$H$ là bài viết thứ tư được biên tập"], "correctIndex": 1, "explain": "Nếu $R$ (Dinh dưỡng) xếp thứ $4$:<br>a) Vì $J < G < R$ nên $J, G$ (cùng là Tài chính) phải nằm trong $3$ vị trí đầu. Để không trùng chủ đề liền kề, buộc $J=1$ và $G=3$.  <br>b) Vị trí số $2$ không thể là $Y$ vì $S$ phải đứng trước $Y$ (nếu $Y=2 \\implies S=1$, mâu thuẫn vì vị trí $1$ đã là $J$). Do đó, vị trí số $2$ phải là bài Dinh dưỡng ($Q$ hoặc $S$).  <br>c) Các vị trí $5, 6, 7$ dành cho $H$ (Tài chính), $Y$ (Động vật) và $1$ bài Dinh dưỡng còn lại. Để Dinh dưỡng không trùng với $R(4)$, bài Dinh dưỡng này phải ở vị trí $6$.  <br>d) Vậy $2$ bài Dinh dưỡng nằm ở vị trí $2$ và $6$. Do không có bài nào ở vị trí số $3$, $S$ không thể đứng trước $Q$, buộc $Q < S$. Suy ra $Q=2, S=6$.  <br>e) Vì $S < Y$ nên $Y$ phải ở vị trí $7$, suy ra vị trí số $5$ thuộc về $H$.<br>Thứ tự được xác định duy nhất và hoàn toàn là: $J, Q, G, R, H, S, Y$."}]}, {"noiDungChung": "Bảng sau thể hiện sản lượng của một doanh nghiệp gồm các công ty con<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Năm</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>M</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>N</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>P</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Q</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>R</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>S</b></td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>2016</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${150}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${75}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${58}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${48}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${49}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${32}$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>2017</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${137}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${68}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${67}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${61}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${45}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${28}$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>2018</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${160}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${65}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${82}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${59}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${46}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${37}$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>2019</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${168}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${70}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${45}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${75}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${43}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${35}$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>2020</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${180}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${55}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${80}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${67}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${47}$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">${28}$</td></tr></table>", "cauHoi": [{"question": "Từ năm ${2016}$ đến năm ${2020}$, năm nào có tổng sản lượng tăng cao nhất", "choices": ["${2020}$", "${2016}$", "${2018}$", "${2019}$"], "correctIndex": 0, "explain": "Tổng sản lượng của các công ty trong từng năm là:<br>a) Năm ${2016}$: $150 + 75 + 58 + 48 + 49 + 32 = 412$.  <br>b) Năm ${2017}$: $137 + 68 + 67 + 61 + 45 + 28 = 406$.  <br>c) Năm ${2018}$: $160 + 65 + 82 + 59 + 46 + 37 = 449$.  <br>d) Năm ${2019}$: $168 + 70 + 45 + 75 + 43 + 35 = 436$.  <br>e) Năm ${2020}$: $180 + 55 + 80 + 67 + 47 + 28 = 457$.<br>Vậy năm ${2020}$ có tổng sản lượng cao nhất ($457$)."}, {"question": "Tổng sản lượng của doanh nghiệp năm ${2020}$ tăng bao nhiêu phần trăm so với năm ${2016}$?", "choices": ["${10}{,}{9}\\%$", "${7}\\%$", "${9}{,}{1}\\%$", "${13}{,}{3}\\%$"], "correctIndex": 0, "explain": "Tổng sản lượng năm $2016$ là $412$ và năm $2020$ là $457$.<br>Tỷ lệ phần trăm tăng trưởng từ năm $2016$ đến năm $2020$ là:  $$\\dfrac{457 - 412}{412} \\times 100\\% \\approx 10{,}92\\% \\approx 10{,}9\\%.$$"}, {"question": "Từ cuối năm ${2016}$ đến năm ${2020}$, công ty có tỷ lệ tăng cao nhất", "choices": ["$S$", "$P$", "$Q$", "$M$"], "correctIndex": 2, "explain": "Loại các công ty có sản lượng năm $2020$ giảm hoặc không tăng so với năm $2016$ ($N, R, S$). <br>Xét tốc độ tăng trưởng của các công ty còn lại:<br>a) Công ty $M$: $\\dfrac{180 - 150}{150} \\times 100\\% = 20\\%$.  <br>b) Công ty $P$: $\\dfrac{80 - 58}{58} \\times 100\\% \\approx 37{,}93\\%$.  <br>c) Công ty $Q$: $\\dfrac{67 - 48}{48} \\times 100\\% \\approx 39{,}58\\%$.<br>Vậy công ty $Q$ có tỷ lệ tăng trưởng cao nhất."}]}, {"noiDungChung": "Biểu đồ thể hiện sản lượng xuất khẩu và nhập khẩu giai đoạn ${1995}-{2000}$<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.85]\n\t\t\n\t\t\\node[font=\\bfseries\\large] at (6, 7) {Giá trị xuất khẩu và nhập khẩu};\n\t\t\n\t\t\n\t\t\\foreach \\y/\\val in {0/0, 1/100, 2/200, 3/300, 4/400, 5/500, 6/600, 7/700} {\n\t\t\t\\draw[gray!40, dashed] (0, \\y) -- (12, \\y);\n\t\t\t\\node[left, font=\\small] at (0, \\y) {\\val};\n\t\t}\n\t\t\\draw[thick] (0, 0) -- (12, 0);\n\t\t\n\t\t\n\t\t\n\t\t\\fill[pattern=north east lines, pattern color=teal!80!black] (0.6, 0) rectangle (1.0, 0.2); \n\t\t\\fill[pattern=checkerboard, pattern color=orange!80!black] (1.1, 0) rectangle (1.5, 1.2); \n\t\t\\node[above, font=\\tiny] at (0.8, 0.2) {20};\n\t\t\\node[above, font=\\tiny] at (1.3, 1.2) {120};\n\t\t\\node[below, font=\\small] at (1.05, 0) {1995};\n\t\t\n\t\t\n\t\t\\fill[pattern=north east lines, pattern color=teal!80!black] (2.6, 0) rectangle (3.0, 1.25); \n\t\t\\fill[pattern=checkerboard, pattern color=orange!80!black] (3.1, 0) rectangle (3.5, 3.0); \n\t\t\\node[above, font=\\tiny] at (2.8, 1.25) {125};\n\t\t\\node[above, font=\\tiny] at (3.3, 3.0) {300};\n\t\t\\node[below, font=\\small] at (3.05, 0) {1996};\n\t\t\n\t\t\n\t\t\\fill[pattern=north east lines, pattern color=teal!80!black] (4.6, 0) rectangle (5.0, 3.75); \n\t\t\\fill[pattern=checkerboard, pattern color=orange!80!black] (5.1, 0) rectangle (5.5, 5.0); \n\t\t\\node[above, font=\\tiny] at (4.8, 3.75) {375};\n\t\t\\node[above, font=\\tiny] at (5.3, 5.0) {500};\n\t\t\\node[below, font=\\small] at (5.05, 0) {1997};\n\t\t\n\t\t\n\t\t\\fill[pattern=north east lines, pattern color=teal!80!black] (6.6, 0) rectangle (7.0, 3.3); \n\t\t\\fill[pattern=checkerboard, pattern color=orange!80!black] (7.1, 0) rectangle (7.5, 4.0); \n\t\t\\node[above, font=\\tiny] at (6.8, 3.3) {330};\n\t\t\\node[above, font=\\tiny] at (7.3, 4.0) {400};\n\t\t\\node[below, font=\\small] at (7.05, 0) {1998};\n\t\t\n\t\t\n\t\t\\fill[pattern=north east lines, pattern color=teal!80!black] (8.6, 0) rectangle (9.0, 5.25); \n\t\t\\fill[pattern=checkerboard, pattern color=orange!80!black] (9.1, 0) rectangle (9.5, 6.0); \n\t\t\\node[above, font=\\tiny] at (8.8, 5.25) {525};\n\t\t\\node[above, font=\\tiny] at (9.3, 6.0) {600};\n\t\t\\node[below, font=\\small] at (9.05, 0) {1999};\n\t\t\n\t\t\n\t\t\\fill[pattern=north east lines, pattern color=teal!80!black] (10.6, 0) rectangle (11.0, 4.75); \n\t\t\\fill[pattern=checkerboard, pattern color=orange!80!black] (11.1, 0) rectangle (11.5, 5.25); \n\t\t\\node[above, font=\\tiny] at (10.8, 4.75) {475};\n\t\t\\node[above, font=\\tiny] at (11.3, 5.25) {525};\n\t\t\\node[below, font=\\small] at (11.05, 0) {2000};\n\t\t\n\t\t\n\t\t\\begin{scope}[shift={(3.5, -1.2)}]\n\t\t\t\\fill[pattern=north east lines, pattern color=teal!80!black] (0, 0) rectangle (-0.3, 0.2);\n\t\t\t\\node[right, font=\\small] at (0, 0.1) {Xuất khẩu};\n\t\t\t\n\t\t\t\\fill[pattern=checkerboard, pattern color=orange!80!black] (2.5, 0) rectangle (3, 0.2);\n\t\t\t\\node[right, font=\\small] at (3, 0.1) {Nhập khẩu};\n\t\t\\end{scope}\n\t\t\n\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Trong ${4}$ năm ${1995}$, ${1996}$, ${1998}$, ${1999}$, năm nào có độ chênh lệch giữa nhập khẩu và xuất khẩu lớn nhất?", "choices": ["${1996}$", "${1995}$", "${1998}$", "${1999}$"], "correctIndex": 0, "explain": "Độ chênh lệch giữa nhập khẩu và xuất khẩu trong các năm là:<br>a) Năm ${1995}$: $|120 - 20| = 100$.  <br>b) Năm ${1996}$: $|300 - 125| = 175$.  <br>c) Năm ${1998}$: $|400 - 330| = 70$.  <br>d) Năm ${1999}$: $|600 - 525| = 75$.<br>Vậy năm ${1996}$ có độ chênh lệch lớn nhất ($175$)."}, {"question": "Sản lượng xuất khẩu của năm cao nhất chiếm khoảng bao nhiêu phần trăm so với tổng sản lượng nhập khẩu của ${3}$ năm ${1997}$, ${1998}$, ${1999}$?", "choices": ["${37}\\%$", "${49}\\%$", "${45}\\%$", "${33}\\%$"], "correctIndex": 1, "explain": "Sản lượng xuất khẩu cao nhất là $600$ (năm ${1999}$).<br>Tổng sản lượng nhập khẩu của ${3}$ năm ${1997}$, ${1998}$, ${1999}$ là:  $$375+330+525=1230.$$<br>Tỷ lệ phần trăm:  $$\\dfrac{600}{1230} \\times 100 \\% \\approx 48,78 \\%$$"}, {"question": "Từ năm ${1995}$ đến năm ${1999}$, tổng sản lượng (xuất khẩu + nhập khẩu) của năm nào tăng nhiều nhất so với năm trước?", "choices": ["${1996}$", "${1997}$", "${1998}$", "${1999}$"], "correctIndex": 0, "explain": "Tổng sản lượng (xuất khẩu + nhập khẩu) của các năm là:<br>a) Năm ${1995}$: $20 + 120 = 140$.  <br>b) Năm ${1996}$: $125 + 300 = 425$.  <br>c) Năm ${1997}$: $375 + 500 = 875$.  <br>d) Năm ${1998}$: $330 + 400 = 730$.  <br>e) Năm ${1999}$: $525 + 600 = 1125$.<br>Mức tăng tuyệt đối so với năm trước:<br>a) Năm ${1996}$: $425 - 140 = 285$.  <br>b) Năm ${1997}$: $875 - 425 = 450$.  <br>c) Năm ${1998}$: $730 - 875 = -145$ (giảm).  <br>d) Năm ${1999}$: $1125 - 730 = 395$.<br>Nếu xét theo tốc độ tăng trưởng phần trăm:<br>a) Năm ${1996}$: $\\dfrac{425 - 140}{140} \\times 100\\% \\approx 203{,}57\\%$.  <br>b) Năm ${1997}$: $\\dfrac{875 - 425}{425} \\times 100\\% \\approx 105{,}88\\%$.<br>Vậy năm ${1996}$ có tỉ lệ phần trăm tăng trưởng so với năm trước lớn nhất."}]}]}, {"id": "de-2-2026", "ten": "Đề chính thức đợt 2 - 2026", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Cho phương trình $x^2 + 5x + m - m^2 = 0$. Các giá trị của $m$ để phương trình có $2$ nghiệm trái dấu là", "choices": ["$m > \\dfrac{1}{4}$", "$m < \\dfrac{29}{12}$", "$m \\in \\varnothing$", "$\\hoac{&m < 0 \\\\ &m > 1}$"], "correctIndex": 3, "explain": "Phương trình có $2$ nghiệm trái dấu khi và chỉ khi $ac < 0$  $$\\Leftrightarrow 1 \\cdot (m - m^2) < 0 \\Leftrightarrow m - m^2 < 0 \\Leftrightarrow \\hoac{&m < 0 <br>&m > 1}$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho phương trình $x+\\sqrt{x+\\dfrac{1}{2}+\\sqrt{x+\\dfrac{1}{4}}}=m$ (với $m$ là tham số). Các giá trị của tham số $m$ để phương trình đã cho vô nghiệm là", "choices": ["$m<\\dfrac{1}{4}$", "$m\\in\\varnothing$", "$m>1$", "$0<m<\\dfrac{1}{4}$"], "correctIndex": 0, "explain": "Điều kiện xác định $x+\\dfrac{1}{4}\\ge 0\\Rightarrow x\\ge -\\dfrac{1}{4}$.<br>Ta xét biểu thức trong căn lớn:  $$x+\\dfrac{1}{2}+\\sqrt{x+\\dfrac{1}{4}}=\\left(x+\\dfrac{1}{4}\\right)+\\sqrt{x+\\dfrac{1}{4}}+\\dfrac{1}{4}=\\left(\\sqrt{x+\\dfrac{1}{4}}+\\dfrac{1}{2}\\right)^2$$<br>Lúc này, phương trình ban đầu trở thành:  $$x+\\sqrt{\\left(\\sqrt{x+\\dfrac{1}{4}}+\\dfrac{1}{2}\\right)^2}=m\\Leftrightarrow x+\\left|\\sqrt{x+\\dfrac{1}{4}}+\\dfrac{1}{2}\\right|=m$$<br>Vì $\\sqrt{x+\\dfrac{1}{4}}\\ge 0$ nên biểu thức trong trị tuyệt đối luôn dương. Ta có: $x+\\sqrt{x+\\dfrac{1}{4}}+\\dfrac{1}{2}=m$.<br>Đặt $t=\\sqrt{x+\\dfrac{1}{4}}$ (với $t\\ge 0$), ta có $x=t^2-\\dfrac{1}{4}$.<br>Thay vào vế trái ($VT$), ta được:  $$VT=\\left(t^2-\\dfrac{1}{4}\\right)+t+\\dfrac{1}{2}=t^2+t+\\dfrac{1}{4}=\\left(t+\\dfrac{1}{2}\\right)^2$$<br>Vì $t\\ge 0\\Rightarrow t+\\dfrac{1}{2}\\ge \\dfrac{1}{2}\\Rightarrow \\left(t+\\dfrac{1}{2}\\right)^2\\ge \\dfrac{1}{4}$.<br>Tức là vế trái luôn $\\ge \\dfrac{1}{4}$.<br>Để phương trình đã cho vô nghiệm, giá trị của $m$ phải nhỏ hơn giá trị nhỏ nhất của vế trái:  $$m<\\dfrac{1}{4}$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho bất phương trình $2^x + x \\le y + \\log_2 y$ với $x, y \\in \\mathbb{Z}^+; y \\le 15$. Số giá trị $x$ thỏa mãn là", "choices": ["$5$", "$4$", "$3$", "$2$"], "correctIndex": 2, "explain": "Điều kiện: $y \\in \\mathbb{Z}^+$ và $y \\le 15$. <br>Biết rằng hàm số $f(t) = 2^t + t$ đồng biến trên $\\mathbb{R}$, bất phương trình đã cho được viết lại dưới dạng:  $$2^x + x \\le 2^{\\log_2 y} + \\log_2 y \\iff f(x) \\le f(\\log_2 y) \\iff x \\le \\log_2 y.$$<br>Vì $x \\in \\mathbb{Z}^+$ và $y \\le 15$ nên $\\log_2 y \\le \\log_2 15 \\approx 3{,}9$. <br>Do $x$ là số nguyên dương ($x \\ge 1$), các giá trị nguyên của $x$ thỏa mãn là $x \\in \\{1; 2; 3\\}$. <br>Với mỗi giá trị của $x$, ta chọn $y \\in \\mathbb{Z}^+$ sao cho $y \\le 15$ và $y \\ge 2^x$:<br>a) $x = 1 \\implies 2 \\le y \\le 15$ (có $14$ giá trị $y$).  <br>b) $x = 2 \\implies 4 \\le y \\le 15$ (có $12$ giá trị $y$).  <br>c) $x = 3 \\implies 8 \\le y \\le 15$ (có $8$ giá trị $y$).<br>Vậy có tổng cộng $3$ giá trị của $x$ thỏa mãn bài toán."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biết $2$ số $x$, $y$ thoả mãn $1+\\log_{2}x+\\log_{2}(x-2)=\\log_{2}y$. Mối quan hệ giữa $x$ và $y$ là", "choices": ["$y=2x-1$", "$y=2x$", "$y=2x^{2}-4x$", "$y=x^{2}-4x+4$"], "correctIndex": 2, "explain": "Điều kiện xác định: $\\heva{&x>0\\\\&x-2>0\\\\&y>0}\\Leftrightarrow\\heva{&x>2\\\\&y>0}$.<br>Phương trình đã cho tương đương với:  $$\\log_{2}2+\\log_{2}x+\\log_{2}(x-2)=\\log_{2}y$$  $$\\Leftrightarrow\\log_{2}\\big[2x(x-2)\\big]=\\log_{2}y$$  $$\\Leftrightarrow y=2x^{2}-4x\\quad\\text{(thỏa mãn điều kiện $x>2$ và $y>0$)}$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Trong $1$ lớp học có $20$ học sinh. Nếu $1$ cặp học sinh kết bạn với nhau thì được tính là $1$ kết nối. Số kết nối tối đa trong lớp là", "choices": ["$200$", "$180$", "$190$", "$170$"], "correctIndex": 2, "explain": "Mỗi kết nối giữa hai học sinh trong lớp ứng với việc chọn ra một tập hợp gồm $2$ học sinh từ tổng số $20$ học sinh.<br>Số kết nối tối đa chính là số tổ hợp chập $2$ của $20$ phần tử:  $$C_{20}^{2}=\\dfrac{20\\cdot 19}{2}=190$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một nhân viên giao hàng xuất phát từ kho $K$ đi giao hàng cho $4$ khách hàng ở $4$ địa chỉ $A$, $B$, $C$, $D$. Yêu cầu bắt buộc là phải ghé qua mỗi địa chỉ $1$ lần, sau đó về kho để kết thúc. Thời gian di chuyển cho trong đồ thị. <br>Thời gian tối thiểu để hoàn thành là<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=3, font=\\footnotesize]\n\t\t\t\n\t\t\t\n\t\t\t\\def\\r{1}\n\t\t\t\\coordinate (D) at (90:\\r);\n\t\t\t\\coordinate (K) at (90+72:\\r);\n\t\t\t\\coordinate (A) at (90+2*72:\\r);\n\t\t\t\\coordinate (B) at (90+3*72:\\r);\n\t\t\t\\coordinate (C) at (90+4*72:\\r);\n\t\t\t\n\t\t\t\n\t\t\t\\draw (D) -- (K) -- (A) -- (B) -- (C) -- cycle;\n\t\t\t\n\t\t\t\n\t\t\t\\draw (D) -- (B);\n\t\t\t\\draw (D) -- (A);\n\t\t\t\\draw (K) -- (C);\n\t\t\t\\draw (K) -- (B);\n\t\t\t\\draw (A) -- (C);\n\t\t\t\n\t\t\t\n\t\t\t\n\t\t\t\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (D)!.5!(K) $) {35};\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (K)!.5!(A) $) {18};\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (A)!.5!(B) $) {10};\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (B)!.5!(C) $) {25};\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (C)!.5!(D) $) {30};\n\t\t\t\n\t\t\t\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (D)!.55!(B) $) {40};\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (K)!.45!(C) $) {15};\n\t\t\t\n\t\t\t\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (D)!.4!(A) $) {12};\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (A)!.55!(C) $) {32};\n\t\t\t\\node[fill=white, inner sep=1pt] at ($ (K)!.6!(B) $) {8};\n\t\t\t\n\t\t\t\n\t\t\t\\node[above, yshift=2pt] at (D) {D};\n\t\t\t\\node[left, xshift=-2pt] at (K) {K};\n\t\t\t\\node[right, xshift=2pt] at (A) {A};\n\t\t\t\\node[right, xshift=2pt] at (B) {B};\n\t\t\t\\node[left, xshift=-2pt] at (C) {C};\n\t\t\t\n\t\t\\end{tikzpicture}</script></div>", "choices": ["$75$ phút", "$78$ phút", "$80$ phút", "$72$ phút"], "correctIndex": 0, "explain": "Bài toán yêu cầu tìm chu trình xuất phát từ $K$, đi qua tất cả các đỉnh $A, B, C, D$ mỗi đỉnh đúng một lần rồi quay lại $K$ sao cho tổng trọng số (thời gian di chuyển) là nhỏ nhất.<br>Từ đồ thị, trọng số các cạnh liên quan trực tiếp đến kho $K$ là:<br>a) $KD = 35$  <br>b) $KA = 18$  <br>c) $KB = 8$  <br>d) $KC = 15$<br>Để tổng thời gian là nhỏ nhất, ta ưu tiên chọn các cạnh xuất phát và kết thúc từ $K$ có trọng số nhỏ nhất là $KB = 8$ và $KA = 18$ (hoặc $KC = 15$).<br>Xét hành trình tối ưu $K \\to B \\to C \\to D \\to A \\to K$:<br>a) $K \\to B$: $8$  <br>b) $B \\to C$: $25$  <br>c) $C \\to D$: $30$  <br>d) $D \\to A$: $12$  <br>e) $A \\to K$: $18$<br>Tổng thời gian của hành trình này là:  $$8 + 25 + 30 + 12 + 18 = 93 \\text{ (chưa tối ưu)}$$<br>Xét hành trình tối ưu khác $K \\to B \\to A \\to D \\to C \\to K$:<br>a) $K \\to B$: $8$  <br>b) $B \\to A$: $10$  <br>c) $A \\to D$: $12$  <br>d) $D \\to C$: $30$  <br>e) $C \\to K$: $15$<br>Tổng thời gian của hành trình này là:  $$8 + 10 + 12 + 30 + 15 = 75 \\text{ phút}.$$<br>Kiểm tra các phương án khác, ta thấy $75$ phút là thời gian di chuyển tối thiểu."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ vuông cân tại $A$ có $BC=10$. Lấy điểm $M$ sao cho $MA=8$ và $MB=9$. Độ dài đoạn thẳng $MC$ là", "choices": ["$7{,}17$", "$5{,}8$", "$2{,}4$", "$1{,}82$"], "correctIndex": 2, "explain": "Tam giác $ABC$ vuông cân tại $A$ với cạnh huyền $BC=10$, ta tính được độ dài cạnh góc vuông:  $$AB = AC = \\dfrac{BC}{\\sqrt{2}} = 5\\sqrt{2}.$$<br>Chọn hệ trục tọa độ $Oxy$ sao cho $A(0;0)$, tia $AB$ nằm trên trục $Ox$ và tia $AC$ nằm trên trục $Oy$. Khi đó:  $$B(5\\sqrt{2}; 0) \\quad \\text{và} \\quad C(0; 5\\sqrt{2}).$$<br>Giả sử điểm $M(x; y)$. Từ giả thiết $MA = 8$ và $MB = 9$, ta có hệ phương trình:  $$\\heva{&x^2 + y^2 = 64 <br>&(x - 5\\sqrt{2})^2 + y^2 = 81}$$<br>Khai triển phương trình thứ hai và thay $x^2 + y^2 = 64$:  $$x^2 + y^2 - 10\\sqrt{2}x + 50 = 81 \\implies 64 - 10\\sqrt{2}x + 50 = 81 \\implies x = \\dfrac{33}{10\\sqrt{2}}.$$<br>Tiếp tục tính $y^2$:  $$y^2 = 64 - x^2 = 64 - \\dfrac{1089}{200} = \\dfrac{11711}{200} \\implies y = \\pm\\sqrt{\\dfrac{11711}{200}}.$$<br>Độ dài đoạn thẳng $MC$ được tính theo công thức:  $$MC^2 = x^2 + (y - 5\\sqrt{2})^2 = x^2 + y^2 - 10\\sqrt{2}y + 50 = 114 - 10\\sqrt{2}y.$$<br>Chọn nghiệm $y = \\sqrt{\\dfrac{11711}{200}}$ (điểm $M$ nằm cùng phía với $C$ đối với trục $Ox$), ta được:  $$MC^2 = 114 - 10\\sqrt{2} \\cdot \\sqrt{\\dfrac{11711}{200}} = 114 - \\sqrt{11711} \\approx 5{,}783 \\implies MC \\approx 2{,}4.$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $\\tan x=a$. Tính giá trị biểu thức $A=\\dfrac{4+6\\cos^{2}x}{3\\sin^{2}x+1}$", "choices": ["$\\dfrac{a^{2}-1}{a^{2}+1}$", "$\\dfrac{4a^{2}+6}{3a^{2}+1}$", "$\\dfrac{4a^{2}+10}{4a^{2}+1}$", "$\\dfrac{a^{2}}{2}$"], "correctIndex": 2, "explain": "Chia cả tử và mẫu cho $\\cos^{2}x$, ta được:  $$A=\\dfrac{\\dfrac{4+6\\cos^{2}x}{\\cos^{2}x}}{\\dfrac{3\\sin^{2}x+1}{\\cos^{2}x}}=\\dfrac{\\dfrac{4}{\\cos^{2}x}+6}{3\\tan^{2}x+\\dfrac{1}{\\cos^{2}x}}=\\dfrac{4(1+\\tan^{2}x)+6}{3\\tan^{2}x+(1+\\tan^{2}x)}=\\dfrac{4a^{2}+10}{4a^{2}+1}$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tính giới hạn $\\lim\\limits_{x\\to-2}\\dfrac{x^{3}+2x^{2}-1}{5-3x}$", "choices": ["$\\dfrac{1}{2}$", "$-\\dfrac{3}{5}$", "$0$", "$-\\dfrac{1}{11}$"], "correctIndex": 3, "explain": "$$\\lim\\limits_{x\\to-2}\\dfrac{x^{3}+2x^{2}-1}{5-3x}=\\dfrac{(-2)^{3}+2(-2)^{2}-1}{5-3(-2)}=\\dfrac{-8+8-1}{5+6}=-\\dfrac{1}{11}$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Đồ thị hàm số $y=\\dfrac{2x^{2}-x+1}{x^{2}-1}$ có bao nhiêu đường tiệm cận?", "choices": ["$1$", "$4$", "$2$", "$3$"], "correctIndex": 3, "explain": "Ta có $\\lim\\limits_{x\\to\\pm\\infty}y=\\lim\\limits_{x\\to\\pm\\infty}\\dfrac{2-\\dfrac{1}{x}+\\dfrac{1}{x^{2}}}{1-\\dfrac{1}{x^{2}}}=2$, nên đồ thị hàm số có $1$ tiệm cận ngang là $y=2$.<br>Mặt khác $\\lim\\limits_{x\\to 1^{\\pm}}y=\\pm\\infty$ và $\\lim\\limits_{x\\to-1^{\\pm}}y=\\pm\\infty$, nên đồ thị hàm số có $2$ tiệm cận đứng là $x=1$ và $x=-1$.<br>Vậy đồ thị hàm số có tổng cộng $3$ đường tiệm cận."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hàm số $f(x)$ có đạo hàm liên tục trên khoảng $(0;+\\infty)$ và thoả mãn hệ thức $x\\cdot f'(x)-f(x)=2$ với mọi $x>0$. Biết rằng $f(1)=0$. Giá trị của $f(2)$ bằng:", "choices": ["$2$", "$4$", "$0$", "$-2$"], "correctIndex": 0, "explain": "Biến đổi phương trình đã cho với $x>0$:  $$x\\cdot f'(x)-f(x)=2\\Leftrightarrow\\dfrac{x\\cdot f'(x)-f(x)}{x^{2}}=\\dfrac{2}{x^{2}}\\Leftrightarrow\\left(\\dfrac{f(x)}{x}\\right)'=\\dfrac{2}{x^{2}}$$  Lấy nguyên hàm hai vế:  $$\\dfrac{f(x)}{x}=\\int\\dfrac{2}{x^{2}}\\mathrm{d}x=-\\dfrac{2}{x}+C$$  Với $f(1)=0$, ta có $\\dfrac{f(1)}{1}=-\\dfrac{2}{1}+C\\Leftrightarrow 0=-2+C\\Leftrightarrow C=2$.<br>Do đó $\\dfrac{f(x)}{x}=-\\dfrac{2}{x}+2\\Leftrightarrow f(x)=-2+2x$.<br>Vậy $f(2)=-2+2(2)=2$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Giá trị của $A=\\displaystyle\\int \\limits_{-2}^{2}|x-1|\\mathrm{d}x$ là:", "choices": ["$4$", "$2$", "$5$", "$-4$"], "correctIndex": 2, "explain": "Ta phân tích tích phân dựa vào nghiệm của biểu thức trong dấu giá trị tuyệt đối ($x=1$):  $$A=\\displaystyle\\int \\limits_{-2}^{1}(1-x)\\mathrm{d}x+\\displaystyle\\int \\limits_{1}^{2}(x-1)\\mathrm{d}x=\\left.\\left(x-\\dfrac{x^{2}}{2}\\right)\\right|_{-2}^{1}+\\left.\\left(\\dfrac{x^{2}}{2}-x\\right)\\right|_{1}^{2}$$  $$=\\left[\\left(1-\\dfrac{1}{2}\\right)-\\left(-2-\\dfrac{4}{2}\\right)\\right]+\\left[\\left(\\dfrac{4}{2}-2\\right)-\\left(\\dfrac{1}{2}-1\\right)\\right]=\\left(\\dfrac{1}{2}+4\\right)+\\left(0+\\dfrac{1}{2}\\right)=5$$"}]}, {"noiDungChung": "Một chai tương ớt được sản xuất với $2$ thành phần là ớt và cà chua, khối lượng phụ gia không đáng kể, hao hụt ở dây chuyền bằng $0$. Một công ty sản xuất tương ớt theo định lượng $1\\text{ kg/chai}$ và chia thành $2$ loại:<br>a) Loại cao cấp: Chứa $40\\%$ ớt tươi. Giá bán: $90$ nghìn đồng/chai.  <br>b) Loại tiêu chuẩn: Chứa $25\\%$ ớt tươi. Giá bán: $30$ nghìn đồng/chai.<br>Kho đang có sẵn $2$ tấn ớt tươi và $3$ tấn cà chua.", "cauHoi": [{"question": "Nếu sản xuất $x$ chai tương ớt cao cấp và $y$ chai tiêu chuẩn thì khối lượng cà chua được sử dụng (tính theo $\\text{kg}$) là:", "choices": ["$0{,}4x + 0{,}1y$", "$0{,}4x + 0{,}25y$", "$1{,}5x + 3y$", "$0{,}6x + 0{,}75y$"], "correctIndex": 3, "explain": "Mỗi chai tương ớt có khối lượng $1\\text{ kg}$. <br>Mỗi chai loại cao cấp chứa $40\\%$ ớt nên chứa $60\\%$ ($0{,}6\\text{ kg}$) cà chua. Chai loại tiêu chuẩn chứa $25\\%$ ớt nên chứa $75\\%$ ($0{,}75\\text{ kg}$) cà chua.<br>Tổng khối lượng cà chua được sử dụng cho $x$ chai cao cấp và $y$ chai tiêu chuẩn là:  $$0{,}6x + 0{,}75y \\text{ (kg).}$$"}, {"question": "Tổng số chai tương ớt $2$ loại cần sản xuất để thu được doanh thu lớn nhất là:", "choices": ["$4000$", "$5000$", "$4800$", "$5250$"], "correctIndex": 1, "explain": "Đổi $2\\text{ tấn} = 2000\\text{ kg}$ ớt tươi, $3\\text{ tấn} = 3000\\text{ kg}$ cà chua. Ta có hệ bất phương trình:  $$\\heva{&0{,}4x + 0{,}25y \\le 2000 <br>&0{,}6x + 0{,}75y \\le 3000 <br>&x \\ge 0, \\, y \\ge 0}$$<br>Hàm doanh thu cần đạt giá trị lớn nhất: $F(x, y) = 90x + 30y$ (nghìn đồng).<br>Miền nghiệm là tứ giác $OABC$ với các đỉnh: $O(0; 0)$, $A(0; 4000)$, $B(2500; 2000)$, $C(5000; 0)$.<br>Thay tọa độ các đỉnh vào hàm mục tiêu $F(x, y)$:<br>a) Tại $O(0; 0): F = 0$.  <br>b) Tại $A(0; 4000): F = 30 \\cdot 4000 = 120000$.  <br>c) Tại $B(2500; 2000): F = 90 \\cdot 2500 + 30 \\cdot 2000 = 285000$.  <br>d) Tại $C(5000; 0): F = 90 \\cdot 5000 = 450000$.<br>Doanh thu lớn nhất đạt được tại điểm $C(5000; 0)$. Tổng số chai tương ớt cần sản xuất là $5000 + 0 = 5000$ chai.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.9, >=stealth]\n\t\t\t\t\n\t\t\t\t\\draw[step=1cm, gray!30, dashed] (-1,-1) grid (6,5);\n\t\t\t\t\\draw[->, thick] (-1,0) -- (6,0) node[below] {$x$};\n\t\t\t\t\\draw[->, thick] (0,-1) -- (0,5) node[above] {$y$};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\foreach \\x/\\xtext in {1/1000, 2/2000, 3/3000, 4/4000, 5/5000}\n\t\t\t\t\\draw (\\x, 0.1) -- (\\x, -0.1) node[below, font=\\footnotesize] {\\xtext};\n\t\t\t\t\\foreach \\y/\\ytext in {1/1000, 2/2000, 3/3000, 4/4000}\n\t\t\t\t\\draw (0.1, \\y) -- (-0.1, \\y) node[left, font=\\footnotesize] {\\ytext};\n\t\t\t\t\\node[below left, font=\\footnotesize] at (0,0) {$0$};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\fill[gray, opacity=0.3] (0,0) -- (0,4) -- (3,3.2) -- (5,0) -- cycle;\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\draw[blue, thick] (0,4) -- (3,3.2) node[above right, sloped, font=\\footnotesize] {$0{,}6x+0{,}75y=3000$};\n\t\t\t\t\\draw[red, thick] (3,3.2) -- (5,0) node[above right, sloped, font=\\footnotesize] {$0{,}4x+0{,}25y=2000$};\n\t\t\t\t\\draw[thick] (0,0) -- (0,4);\n\t\t\t\t\\draw[thick] (0,0) -- (5,0);\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\filldraw (0,0) circle (2pt) node[below left, font=\\footnotesize] {$O$};\n\t\t\t\t\\filldraw (0,4) circle (2pt) node[above left, font=\\footnotesize] {$A$};\n\t\t\t\t\\filldraw (3,3.2) circle (2pt) node[below right, xshift=4mm, font=\\footnotesize] {$B$};\n\t\t\t\t\\filldraw (5,0) circle (2pt) node[above left , xshift=3mm, font=\\footnotesize] {$C$};\n\t\t\t\t\n\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Trong hệ tọa độ $Oxyz$, cho tứ diện $ABCD$ có các đỉnh $A({1};{3};-{2})$, $B({3};{2};-{4})$, $C({2};{1};{0})$, $D({3};{5};-{1})$.", "cauHoi": [{"question": "Gọi $M$ là trung điểm $BC$ thì góc $\\widehat{AMD}$ (làm tròn đến hàng đơn vị theo đơn vị độ) bằng", "choices": ["${45}^{\\circ}$", "${65}^{\\circ}$", "${30}^{\\circ}$", "${55}^{\\circ}$"], "correctIndex": 3, "explain": "Tọa độ trung điểm $M$ của $BC$ là $M\\left(\\dfrac{5}{2}; \\dfrac{3}{2}; -2\\right)$.<br>Các véc-tơ $\\vec{MA} = \\left(-\\dfrac{3}{2}; \\dfrac{3}{2}; 0\\right)$ và $\\vec{MD} = \\left(\\dfrac{1}{2}; \\dfrac{7}{2}; 1\\right)$.<br>Góc $\\widehat{AMD}$ được tính theo công thức vô hướng:  $$\\cos\\widehat{AMD} = \\dfrac{\\vec{MA}\\cdot\\vec{MD}}{|\\vec{MA}|\\cdot|\\vec{MD}|} = \\dfrac{-\\dfrac{3}{4} + \\dfrac{21}{4} + 0}{\\sqrt{\\dfrac{9}{4} + \\dfrac{9}{4}} \\cdot \\sqrt{\\dfrac{1}{4} + \\dfrac{49}{4} + 1}} = \\dfrac{\\dfrac{9}{2}}{\\dfrac{3\\sqrt{2}}{2} \\cdot \\dfrac{\\sqrt{51}}{2}} = \\dfrac{6}{\\sqrt{102}} \\approx 0{,}594.$$<br>Suy ra $\\widehat{AMD} \\approx 54{,}6^{\\circ} \\approx 55^{\\circ}$."}, {"question": "Gọi $A'$, $B'$, $C'$, $D'$ là hình chiếu của $A$, $B$, $C$, $D$ lên $Oxy$. Tứ giác tạo bởi các điểm đó là", "choices": ["Hình bình hành không hình thoi", "Hình thoi không hình chữ nhật", "Hình vuông", "Hình thang không cân"], "correctIndex": 3, "explain": "Tọa độ các hình chiếu trên mặt phẳng $Oxy$ là $A'(1; 3; 0)$, $B'(3; 2; 0)$, $C'(2; 1; 0)$, $D'(3; 5; 0)$.<br>Ta tính véc-tơ các cạnh để xét phương hướng:  $$\\vec{B'C'} = (-1; -1) \\quad \\text{và} \\quad \\vec{A'D'} = (2; 2) = -2\\vec{B'C'}.$$<br>Do $\\vec{A'D'}$ và $\\vec{B'C'}$ cùng phương nên $B'C' \\parallel A'D'$. Mặt khác, độ dài hai cạnh bên:  $$A'B' = \\sqrt{4 + 1} = \\sqrt{5} \\quad \\text{và} \\quad C'D' = \\sqrt{1 + 16} = \\sqrt{17} \\quad (A'B' \\neq C'D').$$<br>Tứ giác $A'B'C'D'$ có một cặp cạnh đối song song và độ dài hai cạnh bên không bằng nhau, vậy đây là hình thang không cân."}]}, {"noiDungChung": "Cho dãy số $(u_{n})$ biết $\\heva{&u_{1}={2026}\\\\&u_{n+1}=\\dfrac{{1}}{{2}}u_{n}}$", "cauHoi": [{"question": "Tính $S=u_{1}+u_{2}+\\dots+u_{n}+\\dots$ là", "choices": ["$S={3039}$", "$S={4052}$", "$S={2026}$", "$S={1013}$"], "correctIndex": 1, "explain": "Dãy số $(u_{n})$ là một cấp số nhân lùi vô hạn với số hạng đầu $u_{1}={2026}$ và công bội $q=\\dfrac{{1}}{{2}}$.<br>Tổng của cấp số nhân lùi vô hạn này là:  $$S=\\dfrac{u_{1}}{{1}-q}=\\dfrac{{2026}}{{1}-\\dfrac{{1}}{{2}}}={4052}$$"}, {"question": "Đặt $v_{n}=\\dfrac{u_{n}+1}{{3}u_{n}+{2}}$. Tính $L=\\lim\\limits_{n\\to+\\infty}\\left[\\dfrac{{2}}{n^{2}}({v}_{1}+{2}v_{2}+{3}v_{3}+\\dots+nv_{n})\\right]$", "choices": ["$\\dfrac{{1}}{{3}}$", "$\\dfrac{{1}}{{2}}$", "$+\\infty$", "${1}$"], "correctIndex": 1, "explain": "Ta có $u_n = 2026 \\cdot \\left(\\dfrac{1}{2}\\right)^{n-1}$, suy ra $\\lim\\limits_{n\\to+\\infty} u_n = 0$. Khi đó:  $$\\lim\\limits_{n\\to+\\infty} v_n = \\lim\\limits_{n\\to+\\infty} \\dfrac{u_n + 1}{3u_n + 2} = \\dfrac{0 + 1}{3(0) + 2} = \\dfrac{1}{2}$$  Vậy  $$L = \\lim\\limits_{n\\to+\\infty} \\dfrac{2(v_{1}+2v_{2}+\\dots+nv_{n})}{n^{2}} = \\lim\\limits_{n\\to+\\infty} \\dfrac{2nv_{n}}{n^{2}-(n-1)^{2}}$$  $$L = \\lim\\limits_{n\\to+\\infty} \\dfrac{2nv_{n}}{2n-1} = \\lim\\limits_{n\\to+\\infty} \\dfrac{2n \\cdot \\dfrac{1}{2}}{2n} = \\dfrac{1}{2}$$"}]}, {"noiDungChung": "Cho hình chóp $S.ABC$ có $SA\\perp(ABC)$. Biết $\\triangle ABC$ vuông cân tại $A$, đường trung tuyến $AD=a$. Góc giữa $SB$ và mặt phẳng đáy bằng ${45}^{\\circ}$.", "cauHoi": [{"question": "Góc tạo bởi $SB$ và đáy là:", "choices": ["$\\widehat{ASB}$", "$\\widehat{SBA}$", "$\\widehat{SAB}$", "$\\widehat{SAD}$"], "correctIndex": 1, "explain": "Vì $SA\\perp(ABC)$ nên hình chiếu của $S$ lên mặt phẳng $(ABC)$ là $A$. Do đó hình chiếu của $SB$ lên mặt phẳng $(ABC)$ là $AB$.<br>Suy ra góc giữa $SB$ và mặt phẳng đáy là góc giữa $SB$ và $AB$.<br>Vậy góc tạo bởi $SB$ và đáy là ${\\widehat{SBA}}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, >=stealth]\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (A) at (0,0);\n\t\t\t\t\t\\coordinate (B) at (-1.5,-1.5);\n\t\t\t\t\t\\coordinate (C) at (3.5,-1.5);\n\t\t\t\t\t\\coordinate (D) at (1,-1.5); \n\t\t\t\t\t\\coordinate (S) at (0,4);     \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed] (A) -- (B);\n\t\t\t\t\t\\draw[dashed] (A) -- (C);\n\t\t\t\t\t\\draw[dashed] (A) -- (D);\n\t\t\t\t\t\\draw[dashed] (S) -- (A);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick] (S) -- (B);\n\t\t\t\t\t\\draw[thick] (S) -- (C);\n\t\t\t\t\t\\draw[thick] (B) -- (C);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\node[above] at (S) {$S$};\n\t\t\t\t\t\\node[above left] at (A) {$A$};\n\t\t\t\t\t\\node[below left] at (B) {$B$};\n\t\t\t\t\t\\node[below right] at (C) {$C$};\n\t\t\t\t\t\\node[below] at (D) {$D$};\n\t\t\t\t\t\n\t\t\t\t\t\\draw (0,-0.2) -- (-0.2,-0.2) -- (-0.2,0);\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Số đo $\\widehat{SCD}$ bằng:", "choices": ["$45^{\\circ}$", "$60^{\\circ}$", "$90^{\\circ}$", "$30^{\\circ}$"], "correctIndex": 1, "explain": "Vì $\\triangle ABC$ vuông cân tại $A$ và $AD$ là trung tuyến ứng với cạnh huyền $BC$ nên $AD=BD=CD=a.$<br>Suy ra $AB=AC=a\\sqrt{2}.$<br>Từ câu trên, góc giữa $SB$ và đáy là $\\widehat{SBA}=45^{\\circ}$.<br>Vì $SA\\perp(ABC)$ nên $SA\\perp AB$. Xét tam giác vuông $SAB$ có  \\[\n\t\t\\widehat{SBA}=45^{\\circ}\n\t\t\\Rightarrow SA=AB=a\\sqrt{2}.\n\t\t\\]<br>Mặt khác,  \\[\n\t\tSD^2=\\sqrt{SA^2+AD^2}\n\t\t=\\sqrt{2a^2+a^2}=\\sqrt{3a^2}=a\\sqrt3,\n\t\t\\]  Do $CD\\perp AD$ và $CD\\perp SA$ nên $CD\\perp(SAD),$   suy ra $CD\\perp SD$. Do đó tam giác $SCD$ vuông tại $D$.<br>Ta có  \\[\n\t\t\\tan\\widehat{SCD}\n\t\t=\\frac{SD}{CD}\n\t\t=\\frac{a\\sqrt3}{a}\n\t\t=\\sqrt3.\n\t\t\\]  Vậy  \\[\n\t\t\\widehat{SCD}=60^{\\circ}.\n\t\t\\]"}, {"question": "Thể tích khối chóp $V_{S.ABC}$ là:", "choices": ["$\\dfrac{a^{3}\\sqrt{2}}{9}$", "$3a^{3}\\sqrt{2}$", "$a^{3}\\sqrt{2}$", "$\\dfrac{a^{3}\\sqrt{2}}{3}$"], "correctIndex": 3, "explain": "Từ giả thiết $\\triangle ABC$ vuông cân tại $A$ và $AD=a$ là trung tuyến ứng với cạnh huyền $BC$, ta có  \\[\n\t\tBC=2AD=2a.\n\t\t\\]  Do đó  \\[\n\t\tAB=AC=\\frac{BC}{\\sqrt2}=a\\sqrt2.\n\t\t\\]  Từ $\\widehat{SBA}=45^{\\circ}$ và $SA\\perp AB$, xét tam giác vuông $SAB$, ta có  \\[\n\t\tSA=AB=a\\sqrt2.\n\t\t\\]<br>Diện tích tam giác $ABC$ là  \\[\n\t\tS_{ABC}\n\t\t=\\frac12AB\\cdot AC\n\t\t=\\frac12(a\\sqrt2)^2\n\t\t=a^2.\n\t\t\\]<br>Vậy thể tích khối chóp $S.ABC$ là  \\[\n\t\tV_{S.ABC}\n\t\t=\\frac13SA\\cdot S_{ABC}\n\t\t=\\frac13(a\\sqrt2)\\cdot a^2\n\t\t={\\frac{a^3\\sqrt2}{3}}.\n\t\t\\]"}]}, {"noiDungChung": "Cho hàm số $f(x)=x^3-3x^2-9x+6$", "cauHoi": [{"question": "Hàm số nghịch biến trên khoảng?", "choices": ["$(-3;1)$", "$(0;3)$", "$(1;4)$", "$(-2;2)$"], "correctIndex": 1, "explain": "Ta có $f'(x)=3x^2-6x-9=3(x^2-2x-3)$.<br>$f'(x)<0\\Leftrightarrow -1<x<3$.<br>Do đó hàm số nghịch biến trên khoảng $(-1;3)$. Vì $(0;3)\\subset (-1;3)$ nên hàm số nghịch biến trên khoảng $(0;3)$."}, {"question": "Khoảng cách giữa các điểm cực trị của $f(x)$", "choices": ["$\\sqrt{438}$", "$\\sqrt{1040}$", "$\\sqrt{416}$", "$\\sqrt{728}$"], "correctIndex": 1, "explain": "Ta có $f'(x)=0\\Leftrightarrow\\hoac{&x=-1\\Rightarrow y=11\\\\&x=3\\Rightarrow y=-21.}$<br>Tọa độ các điểm cực trị là $A(-1;11)$ và $B(3;-21)$.<br>Khoảng cách giữa hai điểm cực trị là  $$AB=\\sqrt{(3-(-1))^2+(-21-11)^2}=\\sqrt{4^2+(-32)^2}=\\sqrt{16+1024}=\\sqrt{1040}=4\\sqrt{65}.$$"}, {"question": "Đường thẳng $y=m-3x$ cắt $f(x)$ tại $A$, $B$, $C$ sao cho $B$ là trung điểm $AC$. Giá trị $m$ nằm trong khoảng?", "choices": ["$(2;4)$", "$(-1;0)$", "$(0;2)$", "$(-3;1)$"], "correctIndex": 3, "explain": "Phương trình hoành độ giao điểm của hai đồ thị:  $$x^3-3x^2-9x+6=m-3x\\Leftrightarrow x^3-3x^2-6x+6-m=0\\quad (1)$$  Vì đường thẳng cắt đồ thị tại ba điểm $A$, $B$, $C$ sao cho $B$ là trung điểm của $AC$ nên $x_B$ phải là nghiệm của (1) và $x_B=\\dfrac{x_A+x_C}{2}$.<br>Theo định lý Vi-ét cho phương trình bậc ba: $x_A+x_B+x_C=3\\Leftrightarrow 3x_B=3\\Leftrightarrow x_B=1$.<br>Thay $x=1$ vào (1), ta được:  $$1^3-3(1)^2-6(1)+6-m=0\\Leftrightarrow 1-3-6+6-m=0\\Leftrightarrow m=-2.$$  Giá trị $m=-2$ nằm trong khoảng $(-3;1)$."}]}, {"noiDungChung": "Có ${3}$ hộp đựng. Hộp ${1}$ có ${1}$ thẻ xanh, ${1}$ đỏ, ${1}$ vàng. Hộp ${2}$ có ${1}$ thẻ xanh, ${1}$ đỏ. Hộp ${3}$ có ${1}$ vàng, ${1}$ đỏ. Lấy ngẫu nhiên từ mỗi hộp ${1}$ thẻ.", "cauHoi": [{"question": "Tính $n(\\Omega)$", "choices": ["${12}$", "${7}$", "${16}$", "${8}$"], "correctIndex": 0, "explain": "Số phần tử của không gian mẫu là số cách lấy ngẫu nhiên từ mỗi hộp ${1}$ thẻ:  $$n(\\Omega)={3}\\cdot{2}\\cdot{2}={12}$$"}, {"question": "Xác suất lấy được ít nhất ${1}$ thẻ đỏ", "choices": ["$\\dfrac{{3}}{{4}}$", "$\\dfrac{{2}}{{3}}$", "$\\dfrac{{5}}{{7}}$", "$\\dfrac{{5}}{{6}}$"], "correctIndex": 3, "explain": "Gọi $A$ là biến cố: \"Lấy được ít nhất ${1}$ thẻ đỏ\". Khi đó biến cố đối $\\overline{A}$ là: \"Không lấy được thẻ đỏ nào cả\" (tức là tất cả các thẻ lấy ra đều không phải màu đỏ).<br>- Hộp ${1}$ có ${3}$ thẻ (xanh, đỏ, vàng), số thẻ không đỏ là ${2}$ (xanh, vàng).<br>- Hộp ${2}$ có ${2}$ thẻ (xanh, đỏ), số thẻ không đỏ là ${1}$ (xanh).<br>- Hộp ${3}$ có ${2}$ thẻ (vàng, đỏ), số thẻ không đỏ là ${1}$ (vàng).<br>Số kết quả thuận lợi cho biến cố đối $\\overline{A}$ là: $n(\\overline{A})={2}\\cdot{1}\\cdot{1}={2}$.<br>Xác suất của biến cố đối là: $P(\\overline{A})=\\dfrac{{2}}{{12}}=\\dfrac{{1}}{{6}}$.<br>Xác suất để lấy được ít nhất ${1}$ thẻ đỏ là:  $$P(A)={1}-P(\\overline{A})={1}-\\dfrac{{1}}{{6}}=\\dfrac{{5}}{{6}}$$"}, {"question": "Xác suất lấy được ít nhất ${1}$ thẻ xanh là:", "choices": ["$\\dfrac{{2}}{{3}}$", "$\\dfrac{{5}}{{6}}$", "$\\dfrac{{5}}{{7}}$", "$\\dfrac{{1}}{{4}}$"], "correctIndex": 0, "explain": "Gọi $B$ là biến cố: \"Lấy được ít nhất ${1}$ thẻ xanh\". Biến cố đối $\\overline{B}$ là: \"Không lấy được thẻ xanh nào\" (tất cả thẻ lấy ra đều không phải màu xanh).<br>- Hộp ${1}$ có ${2}$ thẻ không xanh (đỏ, vàng).<br>- Hộp ${2}$ có ${1}$ thẻ không xanh (đỏ).<br>- Hộp ${3}$ có ${2}$ thẻ không xanh (vàng, đỏ).<br>Số kết quả thuận lợi cho biến cố đối $\\overline{B}$ là: $n(\\overline{B})={2}\\cdot{1}\\cdot{2}={4}$.<br>Xác suất của biến cố đối là: $P(\\overline{B})=\\dfrac{{4}}{{12}}=\\dfrac{{1}}{{3}}$.<br>Xác suất lấy được ít nhất ${1}$ thẻ xanh là:  $$P(B)={1}-P(\\overline{B})={1}-\\dfrac{{1}}{{3}}=\\dfrac{{2}}{{3}}$$"}]}, {"noiDungChung": "Trong mặt phẳng tọa độ $Oxy$, cho tam giác $ABC$ có các đỉnh $A(1; 5)$, $B(-3; 1)$, $C(5; 5)$.", "cauHoi": [{"question": "Gọi $I \\in Ox$ sao cho $(IA+IC)$ đạt giá trị nhỏ nhất. Tổng tọa độ của điểm $I$ là:", "choices": ["$2$", "$1$", "$0$", "$3$"], "correctIndex": 3, "explain": "Vì $A$ và $C$ nằm cùng phía đối với trục $Ox$, gọi $A'(1; -5)$ là điểm đối xứng của $A$ qua $Ox$. <br>Ta có $IA + IC = IA' + IC \\ge A'C$.<br>Dấu bằng xảy ra khi $I$ là giao điểm của đường thẳng $A'C$ với trục $Ox$.<br>Đường thẳng $A'C$ đi qua $C(5; 5)$ và có vectơ pháp tuyến $\\vec{n} = (5; -2)$ nên phương trình là:  $$5(x - 5) - 2(y - 5) = 0 \\iff 5x - 2y - 15 = 0.$$<br>Cho $y = 0 \\implies x = 3$, suy ra $I(3; 0)$. Vậy tổng tọa độ của điểm $I$ là $3 + 0 = 3$."}, {"question": "Gọi $H(a; b)$ là chân đường cao hạ từ $A$ xuống $BC$. Giá trị của $a + b$ là:", "choices": ["$1{,}8$", "$1$", "$5{,}2$", "$3$"], "correctIndex": 2, "explain": "Đường thẳng $BC$ đi qua $B(-3; 1)$ và $C(5; 5)$ có vectơ pháp tuyến $\\vec{n}_{BC} = (1; -2)$, phương trình:  $$x - 2y + 5 = 0.$$<br>Đường thẳng $AH$ đi qua $A(1; 5)$ và vuông góc với $BC$ nên nhận $\\vec{u}_{BC} = (2; 1)$ làm pháp tuyến, phương trình:  $$2(x - 1) + 1(y - 5) = 0 \\iff 2x + y - 7 = 0.$$<br>Tọa độ $H$ là nghiệm của hệ phương trình:  $$\\heva{&x - 2y = -5 <br>&2x + y = 7} \\iff \\heva{&x = 1{,}8 <br>&y = 3{,}4.}$$<br>Do đó $a + b = 1{,}8 + 3{,}4 = 5{,}2$."}, {"question": "Gọi $M$ là trung điểm $BC$ và $G$ là trọng tâm $\\triangle ABC$. Tính tích vô hướng $\\vec{AG} \\cdot \\vec{AM}$.", "choices": ["$-\\dfrac{16}{3}$", "$\\dfrac{8}{3}$", "$-\\dfrac{8}{3}$", "$\\dfrac{16}{3}$"], "correctIndex": 1, "explain": "Tọa độ trung điểm $M$ của $BC$ và trọng tâm $G$ của $\\triangle ABC$ là:  $$M(1; 3) \\quad \\text{và} \\quad G\\left(1; \\dfrac{11}{3}\\right).$$<br>Các véc-tơ $\\vec{AG}$ và $\\vec{AM}$:  $$\\vec{AG} = \\left(0; -\\dfrac{4}{3}\\right), \\quad \\vec{AM} = (0; -2).$$<br>Tích vô hướng:  $$\\vec{AG} \\cdot \\vec{AM} = 0 \\cdot 0 + \\left(-\\dfrac{4}{3}\\right) \\cdot (-2) = \\dfrac{8}{3}.$$"}]}, {"noiDungChung": "Có $9$ tay vợt $K, L, M, N, P, Q, R, S, T$ được xếp hạng từ $1$ (cao nhất) đến $9$ (thấp nhất) trên bảng xếp hạng Quốc gia. Biết rằng không có $2$ tay vợt nào xếp cùng hạng và các điều kiện xếp hạng được cho như sau:<br>a) $M$ xếp hạng $1$ hoặc hạng $9$.  <br>b) $K$ có thứ hạng cao hơn $L$ và $N$.  <br>c) $L$ có thứ hạng cao hơn $Q$ và $R$.  <br>d) $N$ có thứ hạng cao hơn $P$.  <br>e) $Q$ có thứ hạng cao hơn $S$.  <br>f) $S$ có thứ hạng cao hơn $T$.", "cauHoi": [{"question": "Danh sách nào dưới đây có thể là thứ tự xếp hạng của $9$ tay vợt từ hạng $1$ đến hạng $9$?", "choices": ["$L, R, K, N, P, Q, S, T, M$", "$K, L, N, P, Q, S, T, M, R$", "$K, R, N, P, L, Q, S, T, M$", "$M, K, L, N, Q, R, S, T, P$"], "correctIndex": 3, "explain": "Từ các điều kiện của đề bài, ta có chuỗi thứ bậc:   $$K > L > Q > S > T \\quad \\text{và} \\quad K > N > P.$$<br>Xét phương án đúng $M, K, L, N, Q, R, S, T, P$:<br>a) $M$ xếp hạng $1$ (thỏa mãn điều kiện $M$ hạng $1$ hoặc $9$).  <br>b) Thỏa mãn các quan hệ thứ bậc: $K$ đứng trước $L, N$; $L$ đứng trước $Q, R$; $N$ đứng trước $P$; $Q$ đứng trước $S$ và $S$ đứng trước $T$.<br>Các phương án còn lại vi phạm ít nhất một trong các điều kiện thứ bậc hoặc vị trí của $M$."}, {"question": "Nếu $P$ xếp hạng $3$, tập hợp tất cả các tay vợt có thể xếp hạng $6$ là:", "choices": ["$\\{Q, S\\}$", "$\\{Q, R\\}$", "$\\{Q, R, S\\}$", "$\\{R, S\\}$"], "correctIndex": 2, "explain": "Nếu $P$ xếp hạng $3$, do $N > P$ nên $N$ phải xếp hạng $2$ (hoặc cao hơn, nhưng $M$ có thể ở hạng $1$). <br>Khi đó nhóm các tay vợt đi sau $K, L, N, P$ phải phân bổ từ hạng $4$ đến hạng $9$. Dựa vào các chuỗi quan hệ $L > Q > S > T$ và $L > R$, các vị trí từ hạng $6$ hoàn toàn có thể linh hoạt thuộc về các tay vợt $Q, R,$ hoặc $S$ tùy thuộc vào cách chèn thứ tự của $R$."}, {"question": "Số tay vợt tối đa có thể xếp ở giữa $P$ và $Q$ là:", "choices": ["$4$", "$3$", "$2$", "$1$"], "correctIndex": 0, "explain": "Để số tay vợt ở giữa $P$ và $Q$ là lớn nhất, ta sắp xếp sao cho $P$ đứng ở vị trí cao (gần đầu bảng) và $Q$ đứng ở vị trí thấp (gần cuối bảng), đồng thời thỏa mãn toàn bộ các ràng buộc thứ bậc.<br>Một cấu hình khả thi đạt tối đa $4$ tay vợt đứng giữa $P$ và $Q$ (ví dụ thứ tự chứa chuỗi các vận động viên trung gian thỏa mãn các nhánh độc lập của $K, L, N, P, Q, S, T, R$ và $M$)."}]}, {"noiDungChung": "Có ${6}$ tình nguyện viên $G$, $H$, $K$, $L$, $M$, $N$ được chia thành ${3}$ đội ($D_1$, $D_2$, $D_3$), mỗi đội gồm ${2}$ người, trong đó có đúng ${1}$ người là đội trưởng. Biết rằng các điều kiện sau được thỏa mãn:<br>a) $K$ ở cùng đội với $G$ hoặc $N$.  <br>b) $H$ bắt buộc là đội trưởng (của đội mà $H$ tham gia).  <br>c) $G$ hoặc $L$ (nhưng không phải cả hai) không là đội trưởng.", "cauHoi": [{"question": "Danh sách nào dưới đây có thể là phân công thành viên và đội trưởng của các đội?", "choices": ["Đ${1}$: $G$, $K$; Đ${2}$: $H$, $L$; Đ${3}$: $N$, $M$", "Đ${1}$: $L$, $G$; Đ${2}$: $K$, $M$; Đ${3}$: $H$, $N$", "Đ${1}$: $K$, $G$; Đ${2}$: $N$, $H$; Đ${3}$: $L$, $M$", "Đ${1}$: $G$, $K$; Đ${2}$: $L$, $M$; Đ${3}$: $H$, $N$"], "correctIndex": 2, "explain": "Kiểm tra phương án đúng:<br>a) Đội ${1}$ gồm $K$ và $G$: thỏa mãn $K$ ở cùng đội với $G$.  <br>b) Đội ${2}$ gồm $N$ và $H$, với $H$ là đội trưởng: thỏa mãn điều kiện $H$ làm đội trưởng.  <br>c) Đội ${3}$ gồm $L$ và $M$.<br>Phân công này thỏa mãn toàn bộ các giả thiết của bài toán."}, {"question": "Nếu $H$ cùng đội với $L$ thì điều nào sau đây có thể đúng?", "choices": ["$G$ là đội trưởng", "$M$ cùng đội với $N$", "$K$ không là đội trưởng", "$N$ không là đội trưởng"], "correctIndex": 3, "explain": "Nếu $H$ và $L$ cùng đội, do $H$ là đội trưởng nên cặp $(H, L)$ hoàn thành đội thứ nhất. Các thành viên còn lại ($G, K, M, N$) phân bổ vào hai đội kia. Dựa trên các ràng buộc logic, trường hợp $N$ không giữ vai trò đội trưởng là hoàn toàn có thể xảy ra."}, {"question": "Nếu $M$ là đội trưởng thì hai người nào dưới đây phải ở cùng một đội?", "choices": ["$G$, $M$", "$L$, $N$", "$H$, $N$", "$K$, $N$"], "correctIndex": 3, "explain": "Nếu $M$ là đội trưởng, kết hợp với $H$ là đội trưởng, suy ra đội trưởng của đội thứ ba sẽ là $G$ hoặc $L$. Từ các ràng buộc về phân nhóm và vị trí, buộc $K$ và $N$ phải được xếp chung một đội để thỏa mãn điều kiện liên kết giữa $K$ và $N$."}]}, {"noiDungChung": "Tỷ lệ người lao động trong các ngành công nghiệp năm 2024 được thể hiện ở biểu đồ sau:<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1.1]\n\t\t\n\t\t\\def\\R{2}\n\t\t\n\t\t\n\t\t\n\t\t\\fill[blue!40] (0,0) -- (0:\\R) arc (0:90:\\R) -- cycle;\n\t\t\\draw[thick] (0,0) -- (0:\\R);\n\t\t\\draw[thick] (0,0) -- (90:\\R);\n\t\t\\node at (45:1.3) {${25}\\%$};\n\t\t\n\t\t\n\t\t\\fill[red!40] (0,0) -- (90:\\R) arc (90:198:\\R) -- cycle;\n\t\t\\draw[thick] (0,0) -- (198:\\R);\n\t\t\\node at (144:1.3) {${30}\\%$};\n\t\t\n\t\t\n\t\t\\fill[green!40] (0,0) -- (198:\\R) arc (198:270:\\R) -- cycle;\n\t\t\\draw[thick] (0,0) -- (270:\\R);\n\t\t\\node at (234:1.3) {${20}\\%$};\n\t\t\n\t\t\n\t\t\\fill[yellow!50] (0,0) -- (270:\\R) arc (270:360:\\R) -- cycle;\n\t\t\\node at (315:1.3) {${25}\\%$};\n\t\t\n\t\t\n\t\t\\draw[thick] (0,0) circle (\\R);\n\t\t\n\t\t\n\t\t\\begin{scope}[shift={(2.6, 1.2)}, font=\\small]\n\t\t\t\n\t\t\t\\draw[fill=blue!40] (0,0) rectangle (0.3,0.3); \n\t\t\t\\node[right] at (0.4,0.15) {Khai khoáng (${25}\\%$)};\n\t\t\t\n\t\t\t\n\t\t\t\\draw[fill=red!40] (0,-0.6) rectangle (0.3,-0.3); \n\t\t\t\\node[right] at (0.4,-0.45) {Chế biến chế tạo (${30}\\%$)};\n\t\t\t\n\t\t\t\n\t\t\t\\draw[fill=green!40] (0,-1.2) rectangle (0.3,-0.9); \n\t\t\t\\node[right] at (0.4,-1.05) {Cấp nước và HĐQL xử lý rác thải (${20}\\%$)};\n\t\t\t\n\t\t\t\n\t\t\t\\draw[fill=yellow!50] (0,-1.8) rectangle (0.3,-1.5); \n\t\t\t\\node[right] at (0.4,-1.65) {Nhóm ngành khác (${25}\\%$)};\n\t\t\\end{scope}\n\t\t\n\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Số lượng lao động trong chế biến chế tạo chiếm nhiều hơn bao nhiêu $\\%$ so với khai khoáng?", "choices": ["${15}\\%$", "${10}\\%$", "${5}\\%$", "${20}\\%$"], "correctIndex": 2, "explain": "Tỷ lệ lao động ngành chế biến chế tạo là $30\\%$, khai khoáng là $25\\%$.<br>Mức chênh lệch chiếm nhiều hơn là: $30\\% - 25\\% = 5\\%$."}, {"question": "Trong nhóm ngành khác, ngành sản xuất và phân phối điện chiếm ${20}\\%$. Tỷ lệ người lao động sản xuất \\& phân phối điện so với người lao động chế biến chế tạo là:", "choices": ["${1}:{3}$", "${1}:{6}$", "${1}:{5}$", "${1}:{2}$"], "correctIndex": 1, "explain": "Tỷ lệ người lao động sản xuất và phân phối điện so với tổng số lao động là:   $$20\\% \\times 25\\% = 5\\%.$$<br>Tỷ lệ so sánh giữa ngành này với chế biến chế tạo ($30\\%$) là:   $$\\dfrac{5\\%}{30\\%} = \\dfrac{1}{6} \\implies 1:6.$$"}, {"question": "Trong năm ${2015}$ do lao động ngành khai khoáng chuyển sang nên số lao động chế biến chế tạo tăng ${10}\\%$. Số lao động ngành khai khoáng giảm bao nhiêu $\\%$?", "choices": ["${6}\\%$", "${3}\\%$", "${12}\\%$", "${9}\\%$"], "correctIndex": 2, "explain": "Số lao động chế biến chế tạo ban đầu chiếm $30\\%$. Lượng tăng thêm chiếm:   $$30\\% \\times 10\\% = 3\\% \\text{ (so với tổng số lao động)}.$$<br>Lượng lao động này được chuyển từ ngành khai khoáng (ban đầu chiếm $25\\%$). Tỷ lệ phần trăm giảm của ngành khai khoáng là:   $$\\dfrac{3\\%}{25\\%} \\times 100\\% = 12\\%.$$"}]}, {"noiDungChung": "Cho bảng số liệu từ năm về chi phí và tỉ lệ lợi nhuận so với doanh thu của 2 công ty A và B từ năm $2014-2019$.<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Năm</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Chi phí Công ty A<br>(tỷ đồng)</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Tỷ lệ lợi nhuận<br>Công ty A (\\%)</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Chi phí Công ty B<br>(tỷ đồng)</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Tỷ lệ lợi nhuận<br>Công ty B (\\%)</b></td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2014</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">16,5</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">15,4</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">15,2</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">20,1</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2015</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">17,2</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">16,2</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">17,3</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">22,1</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2016</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">19,6</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">20,3</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">16,3</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">19,3</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2017</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">20,1</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">25,4</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">18,5</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">25,5</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2018</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">22,4</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">22,3</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">20,2</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">23,3</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2019</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">24,2</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">23,4</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">22,1</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">24,6</td></tr></table>", "cauHoi": [{"question": "Doanh thu của công ty $A$ năm ${2014}$:", "choices": ["${19}{,}{5}$ tỷ đồng", "${16}{,}{1}$ tỷ đồng", "${18}{,}{2}$ tỷ đồng", "${19}{,}{3}$ tỷ đồng"], "correctIndex": 0, "explain": "Tỷ lệ lợi nhuận trong bảng số liệu được tính trên cơ sở doanh thu: $\\text{Tỷ lệ lợi nhuận} = \\dfrac{\\text{Lợi nhuận}}{\\text{Doanh thu}} \\times 100\\%$.<br>Do đó, công thức tính doanh thu từ chi phí và tỷ lệ lợi nhuận là:  $$\\text{Doanh thu} = \\dfrac{\\text{Chi phí}}{1 - \\text{Tỷ lệ lợi nhuận}}$$  Áp dụng số liệu năm ${2014}$ của công ty $A$ (Chi phí $= {16}{,}{5}$ tỷ đồng, Tỷ lệ lợi nhuận $= {15}{,}{4}\\% = {0}{,}{154}$):  $$\\text{Doanh thu} = \\dfrac{{16}{,}{5}}{1 - {0}{,}{154}} = \\dfrac{{16}{,}{5}}{{0}{,}{846}} \\approx {19}{,}{50} \\text{ tỷ đồng)}$$"}, {"question": "Chênh lệch về lợi nhuận giữa công ty $A$ và $B$ năm ${2019}$:", "choices": ["${215}$ triệu đồng", "${182}$ triệu đồng", "${153}$ triệu đồng", "${100}$ triệu đồng"], "correctIndex": 1, "explain": "Lợi nhuận được tính bằng: $\\text{Lợi nhuận} = \\text{Doanh thu} \\times \\text{Tỷ lệ lợi nhuận} = \\dfrac{\\text{Chi phí}}{1 - \\text{Tỷ lệ}} \\times \\text{Tỷ lệ}$.<br>- Lợi nhuận công ty $A$ năm ${2019}$:  $$L_A = \\dfrac{{24}{,}{2} \\times {0}{,}{234}}{1 - {0}{,}{234}} = \\dfrac{{5}{,}{6628}}{{0}{,}{766}} \\approx {7}{,}{393} \\text{ (tỷ đồng)}$$  - Lợi nhuận công ty $B$ năm ${2019}$:  $$L_B = \\dfrac{{22}{,}{1} \\times {0}{,}{246}}{1 - {0}{,}{246}} = \\dfrac{{5}{,}{4366}}{{0}{,}{754}} \\approx {7}{,}{210} \\text{ (tỷ đồng)}$$  Chênh lệch lợi nhuận giữa hai công ty:  $$\\Delta L = |L_A - L_B| \\approx {7}{,}{393} - {7}{,}{210} = {0}{,}{183} \\text{ tỷ đồng} \\approx {182} \\text{ triệu đồng}$$"}, {"question": "Giai đoạn ${2014}-{2019}$ chi phí công ty $A$ xấp xỉ bao nhiêu phần trăm so với doanh thu:", "choices": ["${76}\\%$", "${79}\\%$", "${73}\\%$", "${82}\\%$"], "correctIndex": 1, "explain": "Tổng chi phí của công ty $A$ trong giai đoạn ${2014} - {2019}$:  $$\\sum \\text{Chi phí} = {16}{,}{5} + {17}{,}{2} + {19}{,}{6} + {20}{,}{1} + {22}{,}{4} + {24}{,}{2} = {120} \\text{ (tỷ đồng)}$$  Tổng doanh thu tương ứng trong giai đoạn (tính từ chi phí và tỷ lệ lợi nhuận từng năm):  $$\\sum \\text{Doanh thu} = \\dfrac{16,5}{1-0,154} + \\dfrac{17,2}{1-0,162} + \\dfrac{19,6}{1-0,203} + \\dfrac{20,1}{1-0,254} + \\dfrac{22,4}{1-0,223} + \\dfrac{24,2}{1-0,234} \\approx {151}{,}{9} \\text{ (tỷ đồng)}$$  Tỷ lệ phần trăm tổng chi phí so với tổng doanh thu:  $$\\text{Tỷ lệ} = \\dfrac{\\sum \\text{Chi phí}}{\\sum \\text{Doanh thu}} = \\dfrac{120}{{151}{,}{9}} \\times 100\\% \\approx {79}\\%$$"}]}]}, {"id": "extra-0", "ten": "Đề chuẩn cấu trúc minh họa số 6", "nhom": [{"noiDungChung": "Cho hàm số $y=f(x)=\\ln |x^2-2x-3|$ có đồ thị là $(C)$.", "cauHoi": [{"question": "Tìm tập xác định $D$ của hàm số đã cho.", "choices": ["$D=\\mathbb{R}$", "$D=(-1;3)$", "$D=\\mathbb{R}\\setminus \\{-1;3\\}$", "$D=(-\\infty;-1)\\cup (3;+\\infty)$"], "correctIndex": 2, "explain": "Hàm số xác định khi $|x^2-2x-3|>0 \\Leftrightarrow x^2-2x-3 \\neq 0 \\Leftrightarrow \\heva{&x \\neq -1\\\\&x \\neq 3.}$  Vậy $D = \\mathbb{R}\\setminus \\{-1;3\\}$."}, {"question": "Gọi $(C')$ là đồ thị đối xứng với $(C)$ qua đường thẳng $x=1$. Khẳng định nào sau đây là đúng về $(C')$?", "choices": ["$(C')$ trùng với $(C)$", "$(C')$ là đồ thị hàm số $y=\\ln |x^2+2x-3|$", "$(C')$ đối xứng với $(C)$ qua trục hoành", "$(C')$ không có đường tiệm cận đứng"], "correctIndex": 0, "explain": "Đồ thị $(C)$ đối xứng qua đường thẳng $x=-\\dfrac{b}{2a} = -\\dfrac{-2}{2(1)}=1$ (trục đối xứng của parabol $y=x^2-2x-3$).  Vì đồ thị gốc $(C)$ có trục đối xứng là $x=1$ nên khi lấy đối xứng qua chính đường thẳng đó, ta thu được chính nó.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, x=1cm, y=1cm, scale=.7]\n\t\t\t\t\t\n\t\t\t\t\t\\draw[->] (-3.5,0) -- (5.5,0) node[below] {$x$};\n\t\t\t\t\t\\draw[->] (0,-4) -- (0,3.5) node[left] {$y$};\n\t\t\t\t\t\\fill (0,0) circle (1.5pt) node[below right] {$O$};\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed, thin] (-1,-4) -- (-1,3.5) node[above left] {$x=-1$};\n\t\t\t\t\t\\draw[dashed, thin] (3,-4) -- (3,3.5) node[above right] {$x=3$};\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed, thick, blue] (1,3.5) -- (1,-4) node[above right] {$x=1$};\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\clip (-3.5,-4) rectangle (5.5,3.5);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick, samples=100, domain=-3.5:-1.02] plot (\\x, {ln(abs(\\x*\\x - 2*\\x - 3))});\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick, samples=100, domain=-0.98:2.98] plot (\\x, {ln(abs(\\x*\\x - 2*\\x - 3))});\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick, samples=100, domain=3.02:5.5] plot (\\x, {ln(abs(\\x*\\x - 2*\\x - 3))});\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\fill (1, {ln(4)}) circle (1.5pt);\n\t\t\t\t\t\\draw[dashed, thin] (1,0) node[below right] {$1$} -- (1,{ln(4)}) -- (0,{ln(4)}) node[left] {$\\ln 4$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Tìm tất cả các giá trị nguyên dương của tham số $m$ để phương trình $f(x)=m$ có đúng $4$ nghiệm phân biệt.", "choices": ["$0$", "$1$", "$2$", "$3$"], "correctIndex": 1, "explain": "Xét phương trình $\\ln |x^2-2x-3|=m \\Leftrightarrow |x^2-2x-3|=e^m$.<br>Vì $e^m>0$ với mọi $m \\in \\mathbb{R}$, phương trình $|x^2-2x-3|=e^m \\; (*)$ tương đương với:  $\\hoac{&x^2-2x-3=e^m \\; (1)\\\\&x^2-2x-3=-e^m\\; (2).}$<br>Đặt $g(x)=x^2-2x-3$. <br>Bảng biến thiên của hàm số $y=g(x)$:<br>Để phương trình $(*)$ có 4 nghiệm phân biệt thì phương trình $(1)$ và $(2)$ mỗi phương trình phải có 2 nghiệm phân biệt.<br>Phương trình $(1)$ có 2 nghiệm phân biệt $\\Leftrightarrow e^m > -4$ (luôn đúng) $\\Leftrightarrow m \\in \\mathbb{R}$ .<br>Phương trình $(2)$ có 2 nghiệm phân biệt $\\Leftrightarrow -e^m > -4 \\Leftrightarrow e^m < 4 \\Leftrightarrow m < \\ln4$ . <br>Do đó, phương trình $(*)$ có 4 nghiệm phân biệt $\\Leftrightarrow m < \\ln4$.<br>Mà $m \\in \\mathbb{Z^+}$ nên có $1$ số nguyên dương $m$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một bệnh nhân được chỉ định uống một loại thuốc định kỳ $24$ giờ một lần. Mỗi lần bệnh nhân uống đúng $50$ mg thuốc. Biết rằng sau mỗi $24$ giờ, lượng thuốc còn lại trong cơ thể bệnh nhân chỉ bằng $20\\%$ so với lượng thuốc ngay sau khi uống lần trước đó. Tính tổng lượng thuốc tồn dư trong cơ thể bệnh nhân sau một thời gian dài điều trị (ngay sau khi uống một liều mới).", "choices": ["$50$ mg", "$62{,}5$ mg", "$60$ mg", "$250$ mg"], "correctIndex": 1, "explain": "Gọi $u_n$ là lượng thuốc trong cơ thể bệnh nhân ngay sau khi uống liều thứ $n$.<br>a) Ngay sau khi uống liều thứ nhất ($n=1$): $u_1 = 50$ mg.  <br>b) Ngay sau khi uống liều thứ hai ($n=2$): $u_2 = 50 + 50 \\cdot 0{,}2$ mg.  <br>c) Ngay sau khi uống liều thứ ba ($n=3$): $u_3 = 50 + 50 \\cdot 0{,}2 + 50 \\cdot (0{,}2)^2$ mg.<br>Tổng quát, lượng thuốc trong cơ thể sau khi uống liều thứ $n$ là:  $$u_n = 50 + 50 \\cdot 0{,}2 + 50 \\cdot (0{,}2)^2 + \\dots + 50 \\cdot (0{,}2)^{n-1}$$  Đây là tổng của $n$ số hạng đầu tiên của một cấp số nhân có số hạng đầu $u_1 = 50$ và công bội $q = 0{,}2$.  Khi bệnh nhân điều trị trong một thời gian dài ($n \\to +\\infty$), lượng thuốc tồn dư là tổng của cấp số nhân lùi vô hạn:  $$S = \\dfrac{u_1}{1-q} = \\dfrac{50}{1-0{,}2} = \\dfrac{50}{0{,}8} = 62{,}5 \\text{ mg}$$  Vậy tổng lượng thuốc tồn dư trong cơ thể bệnh nhân ngay sau khi uống liều mới là $62{,}5$ mg."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho một hình vuông có cạnh bằng $2$ đơn vị. Bên trong hình vuông này có $9$ điểm bất kỳ. Khẳng định nào sau đây là đúng?", "choices": ["Luôn tồn tại ít nhất $3$ điểm nằm trong một hình vuông nhỏ có cạnh bằng $1$", "Luôn tồn tại ít nhất $4$ điểm nằm trong một hình vuông nhỏ có cạnh bằng $1$", "Có ít nhất $5$ điểm nằm trong một hình chữ nhật có diện tích bằng $1$", "Không thể khẳng định được gì về vị trí các điểm"], "correctIndex": 0, "explain": "Chia hình vuông cạnh $2$ thành $4$ hình vuông nhỏ có cạnh bằng $1$.<br>Ta coi $4$ hình vuông nhỏ này là $4$ cái “lồng”, và $9$ điểm là $9$ con “chim”.<br>Theo nguyên lý Dirichlet mở rộng, vì $9 = 4 \\times 2 + 1$, nên phải có ít nhất $\\left\\lfloor \\dfrac{9-1}{4} \\right\\rfloor + 1 = 3$ điểm cùng nằm trong một hình vuông nhỏ."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hàm số $f(x)$ có đạo hàm trên $\\mathbb{R}$. Xét các hàm số $g(x)=f(x)-f(2x)$ và $h(x)=f(x)-f(4x)$. Biết rằng $g'(1)=5$ và $g'(2)=7$. Tính giá trị của $h'(1)$.", "choices": ["$h'(1)=12$", "$h'(1)=17$", "$h'(1)=19$", "$h'(1)=24$"], "correctIndex": 2, "explain": "Ta có $g'(x)=f'(x)-2f'(2x)$ và $h'(x)=f'(x)-4f'(4x)$.<br>Dựa vào giả thiết, ta có hệ phương trình:  $\\heva{&f'(1)-2f'(2)=5\\\\&f'(2)-2f'(4)=7.}$<br>Từ phương trình thứ hai, ta có $2f'(2)-4f'(4)=14$.<br>Cộng vế theo vế với phương trình đầu tiên:  $(f'(1)-2f'(2))+(2f'(2)-4f'(4))=5+14$  $\\Leftrightarrow f'(1)-4f'(4)=19$.<br>Vậy $h'(1)=19$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Trên lưới tọa độ $Oxy$, một chất điểm chỉ được phép di chuyển sang phải hoặc lên trên. Tính số đường đi ngắn nhất từ điểm $A(0;0)$ đến điểm $B(4;3)$ sao cho đường đi đó bắt buộc phải đi qua điểm $C(2;1)$.", "choices": ["$15$", "$21$", "$18$", "$35$"], "correctIndex": 2, "explain": "Số cách đi từ $A(0;0)$ đến $C(2;1)$ là $\\mathrm{C}_{2+1}^1 = \\mathrm{C}_3^1 = 3$ cách.<br>Số cách đi từ $C(2;1)$ đến $B(4;3)$ là đi thêm $2$ đơn vị sang phải và $2$ đơn vị lên trên, số cách là $\\mathrm{C}_{2+2}^2 = \\mathrm{C}_4^2 = 6$ cách.<br>Theo quy tắc nhân, tổng số cách đi là $3 \\cdot 6 = 18$ cách."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tam giác $ABC$ có các cạnh $a$, $b$, $c$ thỏa mãn điều kiện $\\dfrac{a+b}{6}=\\dfrac{b+c}{5}=\\dfrac{a+c}{7}$. Tính $\\cos A$.", "choices": ["$- \\dfrac{1}{4}$", "$\\dfrac{1}{3}$", "$- \\dfrac{1}{3}$", "$\\dfrac{1}{2}$"], "correctIndex": 1, "explain": "Ta có: $\\dfrac{a+b}{6}=\\dfrac{b+c}{5}=\\dfrac{a+c}{7}=t \\Leftrightarrow\\left\\{\\begin{array}{l}a+b=6 t \\\\ b+c=5 t \\\\ a+c=7 t\\end{array} \\Rightarrow a+b+c=9 t\\right.$. <br>Vậy $\\left\\{\\begin{array}{l}a=4 t \\\\ b=2 t \\\\ c=3 t\\end{array}\\right.$.<br>Theo định lí côsin: $\\cos A=\\dfrac{b^2+c^2-a^2}{2 b c}=\\dfrac{4 t^2+9 t^2-16 t^2}{2.2 t .3 t}=-\\dfrac{1}{4}$.<br>Tương tự, ta tính được: $\\cos B=\\dfrac{7}{8} ; \\cos C=\\dfrac{11}{16}$."}]}, {"noiDungChung": "Trong mặt phẳng $Oxy$, cho đường tròn $(C)\\colon x^2+y^2-2x+8y+12=0$ có tâm $I$.", "cauHoi": [{"question": "Xác định vị trí tương đối của điểm $M(-3;2)$ đối với đường tròn $(C)$.", "choices": ["Điểm $M$ nằm bên trong đường tròn $(C)$", "Điểm $M$ nằm trên đường tròn $(C)$", "Điểm $M$ nằm bên ngoài đường tròn $(C)$", "Điểm $M$ trùng với tâm $I$ của đường tròn $(C)$"], "correctIndex": 2, "explain": "Đường tròn $(C)$ có tâm $I(1;-4)$ và bán kính $R=\\sqrt{1^2+(-4)^2-12}=\\sqrt{5}$.<br>Ta có $\\overrightarrow{IM}=(-4;6) \\Rightarrow IM=\\sqrt{(-4)^2+6^2}=\\sqrt{16+36}=\\sqrt{52}$.<br>Vì $IM=\\sqrt{52} > \\sqrt{5}=R$ nên điểm $M$ nằm bên ngoài đường tròn $(C)$."}, {"question": "Đường thẳng nào sau đây tiếp xúc với đường tròn $(C)$?", "choices": ["$\\Delta \\colon x+y=0$", "$\\Delta \\colon 2x-y-11=0$", "$\\Delta \\colon 2x+y-3=0$", "$\\Delta \\colon x-2y+5=0$"], "correctIndex": 1, "explain": "Đường tròn $(C)$ có tâm $I(1;-4)$ và bán kính $R=\\sqrt{5}$.<br>Đường thẳng tiếp xúc với $(C)$ khi và chỉ khi $\\mathrm{d}(I,\\Delta)=R=\\sqrt{5}$.<br>Xét đường thẳng $\\Delta \\colon 2x-y-11=0$, ta có:  $\\mathrm{d}(I,\\Delta)=\\dfrac{|2\\cdot 1-(-4)-11|}{\\sqrt{2^2+(-1)^2}}=\\dfrac{|-5|}{\\sqrt{5}}=\\sqrt{5}$ (thỏa mãn)."}, {"question": "Đường thẳng $d\\colon mx+y+2=0$ cắt đường tròn $(C)$ tại hai điểm phân biệt $A$ và $B$. Tích các giá trị của tham số $m$ để diện tích tam giác $IAB$ lớn nhất.", "choices": ["$-\\dfrac{1}{3}$", "$3$", "$-1$", "$2$"], "correctIndex": 2, "explain": "Ta có $S_{\\triangle IAB}=\\dfrac{1}{2}IA \\cdot IB \\cdot \\sin\\widehat{AIB}=\\dfrac{5}{2}\\sin\\widehat{AIB} \\le \\dfrac{5}{2}$.<br>Dấu bằng xảy ra khi $\\sin\\widehat{AIB}=1 \\Leftrightarrow \\widehat{AIB}=90^\\circ$.<br>Gọi $H$ là hình chiếu của $I$ lên $d$. Khi đó tam giác $IAB$ vuông cân tại $I$, suy ra $IH=\\dfrac{IA}{\\sqrt{2}}=\\dfrac{\\sqrt{5}}{\\sqrt{2}}$.<br>Ta có $\\mathrm{d}(I,d)=IH \\Leftrightarrow \\dfrac{|m \\cdot 1-4+2|}{\\sqrt{m^2+1}}=\\dfrac{\\sqrt{5}}{\\sqrt{2}} \\Leftrightarrow \\dfrac{|m-2|}{\\sqrt{m^2+1}}=\\sqrt{\\dfrac{5}{2}}$  $\\Leftrightarrow 2(m-2)^2=5(m^2+1) \\Leftrightarrow 2(m^2-4m+4)=5m^2+5 \\Leftrightarrow 3m^2+8m-3=0 \\Leftrightarrow \\hoac{&m=\\dfrac{1}{3}\\\\&m=-3.}$<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1,>=stealth, font=\\footnotesize, line join=round, line cap=round]\n\t\t\t\t\t\\def\\r{2}\n\t\t\t\t\t\\path\n\t\t\t\t\t(0,0) coordinate (I)\n\t\t\t\t\t(I)+ (30:\\r) coordinate (B)\n\t\t\t\t\t(I)+ (120:\\r) coordinate (A)\n\t\t\t\t\t($(A)!.5!(B)$) coordinate (H)\n\t\t\t\t\t;\n\t\t\t\t\t\\draw (I) circle (\\r);\n\t\t\t\t\t\\draw ($(A)!-0.5!(B)$)-- ($(A)!1.5!(B)$) node[above]{$d$} (I)--(H) (A)--(I)--(B);\n\t\t\t\t\t\\foreach \\x/\\g in {A/80,B/80,H/80,I/-80}\n\t\t\t\t\t\\fill[black] (\\x) circle (1pt) ($(\\g:3mm)+(\\x)$) node {$\\x$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Một bồn chứa xăng có hình dạng là một khối tròn xoay, được tạo thành khi quay hình phẳng giới hạn bởi đường cong $y = \\dfrac{1}{4}x^2$, trục hoành và hai đường thẳng $x = 0$, $x = 4$ quanh trục $Ox$ (đơn vị trên các trục là mét).", "cauHoi": [{"question": "Tính thể tích $V$ của bồn chứa xăng đó.", "choices": ["$V = \\dfrac{16\\pi}{5}\\text{ m}^3$", "$V = \\dfrac{64\\pi}{5}\\text{ m}^3$", "$V = \\dfrac{4\\pi}{3}\\text{ m}^3$", "$V = 4\\pi\\text{ m}^3$"], "correctIndex": 0, "explain": "Thể tích vật thể tròn xoay khi quay quanh trục $Ox$ được tính bởi công thức:  $$V = \\pi \\int\\limits_{0}^{4} [f(x)]^2 dx = \\pi \\int\\limits_{0}^{4} \\left(\\dfrac{1}{4}x^2\\right)^2 dx = \\pi \\int\\limits_{0}^{4} \\dfrac{x^4}{16} dx$$  $$= \\dfrac{\\pi}{16} \\cdot \\left. \\dfrac{x^5}{5} \\right|_{0}^{4} = \\dfrac{\\pi}{16} \\cdot \\dfrac{4^5}{5} = \\dfrac{\\pi \\cdot 1024}{80} = \\dfrac{16\\pi}{5}\\text{ (m}^3\\text{)}.$$"}, {"question": "Hiện tại bồn đang chứa đầy xăng. Giá mỗi mét khối xăng là $20$ triệu đồng. Do xăng bay hơi theo thời gian, tốc độ hao hụt xăng được xác định bởi hàm số $r(t) = 0{,}02e^{0{,}1t}$ ($\\text{m}^3\\text{/tháng}$), với $t$ là số tháng tính từ lúc bồn đầy. Số tiền (làm tròn đến triệu đồng) mà công ty bị tổn thất do xăng bay hơi sau $10$ tháng xấp xỉ", "choices": ["$5$ triệu đồng", "$6$ triệu đồng", "$7$ triệu đồng", "$8$ triệu đồng"], "correctIndex": 2, "explain": "Tổng lượng xăng bị bay hơi sau $10$ tháng là:  $$\\Delta V = \\int\\limits_{0}^{10} r(t) dt = \\int\\limits_{0}^{10} 0{,}02e^{0{,}1t} dt$$  $$= 0{,}02 \\cdot \\left. \\dfrac{e^{0{,}1t}}{0{,}1} \\right|_{0}^{10} = 0{,}2 \\left( e^1 - e^0 \\right) = 0{,}2(e - 1) \\approx 0{,}3436\\text{ (m}^3\\text{)}.$$  Số tiền tổn thất là: $0{,}3436 \\cdot 20 = 6{,}872$ triệu đồng.  Làm tròn đến hàng đơn vị ta được $7$ triệu đồng."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Lan có một miếng bìa hình tam giác $ABC$ vuông tại $A$, cạnh $AB=3\\text{ cm}$. Lan cắt từ miếng bìa đó ra một hình chữ nhật $ADEF$ sao cho đỉnh $D$ nằm trên cạnh $AB$, đỉnh $F$ nằm trên cạnh $AC$ và đỉnh $E$ nằm trên cạnh huyền $BC$. Biết rằng hình chữ nhật này có chiều dài $AF=2\\text{ cm}$ và diện tích của nó bằng một nửa diện tích của miếng bìa ban đầu. Diện tích của tam giác $ABC$ là", "choices": ["$4\\text{ cm}^2$", "$8\\text{ cm}^2$", "$12\\text{ cm}^2$", "$6\\text{ cm}^2$"], "correctIndex": 3, "explain": "Gọi độ dài cạnh $AC$ là $x$ ($x>2$, đơn vị $\\text{cm}$).<br>Diện tích tam giác $ABC$ là $S_{ABC} = \\dfrac{1}{2}AB \\cdot AC = \\dfrac{3x}{2}$.<br>Theo hình vẽ, hình chữ nhật $ADEF$ có $D \\in AB$, $E \\in BC$, $F \\in AC$.<br>Chiều dài hình chữ nhật là $AF = 2\\text{ cm}$.<br>Vì $EF \\parallel AB$, theo định lý Ta-lét ta có:<br>$\\dfrac{EF}{AB} = \\dfrac{CF}{AC} \\Rightarrow \\dfrac{EF}{3} = \\dfrac{x-2}{x} \\Rightarrow EF = \\dfrac{3(x-2)}{x}$.<br>Diện tích hình chữ nhật $ADEF$ là:  $S_{ADEF} = AF \\cdot EF = 2 \\cdot \\dfrac{3(x-2)}{x} = \\dfrac{6(x-2)}{x}$.<br>Theo giả thiết: $S_{ADEF} = \\dfrac{1}{2}S_{ABC}$  $\\Leftrightarrow \\dfrac{6(x-2)}{x} = \\dfrac{3x}{4} \\Leftrightarrow 24(x-2) = 3x^2$  $\\Leftrightarrow 3x^2 - 24x + 48 = 0 \\Leftrightarrow x^2 - 8x + 16 = 0$  $\\Leftrightarrow (x-4)^2 = 0 \\Leftrightarrow x = 4$ (thỏa mãn).<br>Với $AC = 4\\text{ cm}$, diện tích tam giác $ABC$ là:  $S_{ABC} = \\dfrac{1}{2} \\cdot 3 \\cdot 4 = 6\\text{ (cm}^2\\text{)}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, font=\\footnotesize, line join=round, line cap=round]\n\t\t\t\t\\coordinate (A) at (0,0);\n\t\t\t\t\\coordinate (B) at (0,3);\n\t\t\t\t\\coordinate (C) at (4,0);\n\t\t\t\t\\coordinate (F) at (2,0);\n\t\t\t\t\\coordinate (E) at (2,1.5);\n\t\t\t\t\\coordinate (D) at (0,1.5);\n\t\t\t\t\\draw[thick] (A)--(B)--(C)--cycle;\n\t\t\t\t\\draw[fill=gray!20] (A)--(D)--(E)--(F)--cycle;\n\t\t\t\t\\draw (0,0.2)-|(0.2,0);\n\t\t\t\t\\draw (0,1.3)-|(0.2,1.5);\n\t\t\t\t\\draw (1.8,0)|-(2,0.2);\n\t\t\t\t\\draw (1.8,1.5)|-(2,1.3);\n\t\t\t\t\\draw [decorate,decoration={brace,amplitude=5pt,mirror}] (0,-0.1)--(2,-0.1) node [black,midway,yshift=-0.4cm] {$2\\text{ cm}$};\n\t\t\t\t\\draw [decorate,decoration={brace,amplitude=5pt}] (-0.1,0)--(-0.1,3) node [black,midway,xshift=-0.5cm] {$3\\text{ cm}$};\n\t\t\t\t\\draw (A) node[below left]{$A$};\n\t\t\t\t\\draw (B) node[above left]{$B$};\n\t\t\t\t\\draw (C) node[below right]{$C$};\n\t\t\t\t\\draw (D) node[left]{$D$};\n\t\t\t\t\\draw (E) node[above right]{$E$};\n\t\t\t\t\\draw (F) node[below]{$F$};\n\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một công ty du lịch thông báo giá tiền cho chuyến đi thăm quan của một nhóm khách như sau: $40$ khách đầu tiên có giá $490.000$ đồng/người. Nếu có nhiều hơn $40$ người đăng ký thì cứ có thêm một người, giá vé sẽ giảm $10.000$ đồng/người cho toàn bộ hành khách. Biết chi phí thực sự của chuyến đi là $19.380.000$ đồng. Gọi $n_1$ là số lượng khách để công ty đạt doanh thu cao nhất và $n_2$ là số lượng khách tối đa để công ty không bị lỗ. Chênh lệch giữa $n_2$ và $n_1$ là", "choices": ["$6$ người", "$11$ người", "$7$ người", "$10$ người"], "correctIndex": 0, "explain": "Gọi $x$ là số người thêm vào sau $40$ khách đầu tiên ($x \\in \\mathbb{N}$). Tổng số khách là $n = 40+x$.<br>Giá vé áp dụng cho toàn bộ hành khách là $490.000-10.000x$ (đồng/người).<br>Hàm doanh thu của công ty là:   $T(x) = (40+x)(490.000-10.000x) = -10.000x^2 + 90.000x + 19.600.000$.<br>a) \\textbf{Tìm $n_1$ (Số khách để doanh thu cao nhất):}<br>Hàm số $T(x)$ là hàm bậc hai có bề lõm quay xuống dưới, đạt giá trị lớn nhất tại đỉnh có hoành độ $x = \\dfrac{-90.000}{2 \\cdot (-10.000)} = 4{,}5$.<br>Vì $x$ phải là số nguyên nên doanh thu cao nhất khi $x=4$ hoặc $x=5$ (do $T(4) = T(5) = 19.800.000$).<br>Để lấy số khách nhiều nhất theo xu hướng thị trường, ta chọn $x=5$.<br>Vậy $n_1 = 40 + 5 = 45$ (người).  <br>b) \\textbf{Tìm $n_2$ (Số khách tối đa để không bị lỗ):}<br>Công ty không bị lỗ khi tổng doanh thu không thấp hơn chi phí thực sự:  $$T(x) \\ge 19.380.000 \\Leftrightarrow -10.000x^2 + 90.000x + 19.600.000 \\ge 19.380.000$$  $\\Leftrightarrow -10.000x^2 + 90.000x + 220.000 \\ge 0 \\Leftrightarrow -x^2 + 9x + 22 \\ge 0$.<br>Tam thức bậc hai $-x^2 + 9x + 22$ có hai nghiệm là $x = -2$ và $x = 11$.<br>Vì $x \\ge 0$ nên ta có $0 \\le x \\le 11$. Số khách thêm vào tối đa là $x=11$.<br>Vậy $n_2 = 40 + 11 = 51$ (người).<br>Chênh lệch giữa số khách tối đa không lỗ và số khách doanh thu cao nhất là:  $n_2 - n_1 = 51 - 45 = 6$ (người)."}]}, {"noiDungChung": "Cho dãy số $(u_n)$ có số hạng tổng quát $u_n = \\dfrac{1+2+3+\\dots+n}{n^2+1}$ và giới hạn $L = \\displaystyle\\lim \\limits_{n \\to +\\infty} \\left( \\sqrt{n^2+an+1} - n \\right)$ với $a$ là tham số thực.", "cauHoi": [{"question": "Tính giá trị của giới hạn $\\displaystyle\\lim \\limits_{n \\to +\\infty} u_n$.", "choices": ["$0$", "$\\dfrac{1}{2}$", "$1$", "$+\\infty$"], "correctIndex": 1, "explain": "Ta có tổng của $n$ số hạng đầu tiên của cấp số cộng: $1+2+3+\\dots+n = \\dfrac{n(n+1)}{2}$.<br>Khi đó: $u_n = \\dfrac{n(n+1)}{2(n^2+1)} = \\dfrac{n^2+n}{2n^2+2}$.<br>Suy ra: $\\displaystyle\\lim \\limits_{n \\to +\\infty} u_n = \\displaystyle\\lim \\limits_{n \\to +\\infty} \\dfrac{n^2+n}{2n^2+2} = \\displaystyle\\lim \\limits_{n \\to +\\infty} \\dfrac{1+\\dfrac{1}{n}}{2+\\dfrac{2}{n^2}} = \\dfrac{1}{2}$."}, {"question": "Tìm giá trị của tham số $a$ để giới hạn $I = \\displaystyle\\lim \\limits_{n \\to +\\infty} \\left[ u_n \\cdot \\left( \\sqrt{4n^2+an+1} - 2n \\right) \\right] = 1$.", "choices": ["$a=2$", "$a=4$", "$a=8$", "$a=16$"], "correctIndex": 2, "explain": "Từ câu 1, ta đã biết $\\displaystyle\\lim \\limits_{n \\to +\\infty} u_n = \\dfrac{1}{2}$.<br>Xét $K = \\displaystyle\\lim \\limits_{n \\to +\\infty} \\left( \\sqrt{4n^2+an+1} - 2n \\right) = \\displaystyle\\lim \\limits_{n \\to +\\infty} \\dfrac{(4n^2+an+1) - 4n^2}{\\sqrt{4n^2+an+1} + 2n} = \\displaystyle\\lim \\limits_{n \\to +\\infty} \\dfrac{an+1}{\\sqrt{4n^2+an+1} + 2n}$.<br>Chia cả tử và mẫu cho $n$: $K = \\dfrac{a}{\\sqrt{4}+2} = \\dfrac{a}{4}$.<br>Khi đó $I = \\displaystyle\\lim \\limits_{n \\to +\\infty} u_n \\cdot K = \\dfrac{1}{2} \\cdot \\dfrac{a}{4} = \\dfrac{a}{8}$.<br>Theo đề bài $I=1 \\Rightarrow \\dfrac{a}{8}=1 \\Leftrightarrow a=8$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Có $32$ tấm thẻ được đánh số từ $1$ đến $32$. Rút ngẫu nhiên $3$ thẻ. Tính xác suất để tổng các số ghi trên thẻ chia hết cho $3$ xấp xỉ", "choices": ["$31,25\\%$", "$33,47\\%$", "$34,4\\%$", "$30\\%$"], "correctIndex": 1, "explain": "Số phần tử của không gian mẫu $n(\\Omega)=\\mathrm{C}_{32}^3$.<br>$A=\\{3;6;9;\\ldots;30\\}$ là tập các số chia hết cho $3$.<br>$B=\\{1;4;7;\\ldots;31\\}$ là tập các số chia hết cho $3$ dư $1$.<br>$C=\\{2;5;8;\\ldots;32\\}$ là tập các số chia hết cho $3$ dư $2$.<br>Để $3$ số được viết có tổng chia hết cho $3$ thì có các trường hợp sau:<br>a) TH1. $3$ số lấy ra từ tập $A$ có $\\mathrm{C}_{10}^3$ (cách).  <br>b) TH2. $3$ số lấy ra từ tập $B$ có $\\mathrm{C}_{11}^3$ (cách).  <br>c) TH3. $3$ số lấy ra từ tập $C$ có $\\mathrm{C}_{11}^3$ (cách).  <br>d) TH4. $1$ số lấy ra từ tập $A$, $1$ lấy ra từ tập $B$, $1$ lấy ra từ tập $C$ có $\\mathrm{C}_{10}^1\\cdot \\mathrm{C}_{11}^1\\cdot \\mathrm{C}_{11}^1$ (cách).<br>Vậy xác suất để tổng các số ghi trên thẻ chia hết cho $3$ là  $$\\dfrac{\\mathrm{C}_{10}^3+\\mathrm{C}_{11}^3+\\mathrm{C}_{11}^3+\\mathrm{C}_{10}^1\\cdot \\mathrm{C}_{11}^1\\cdot \\mathrm{C}_{11}^1}{\\mathrm{C}_{32}^3}=\\dfrac{83}{248}.$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hàm số $y = \\dfrac{\\log_2 x}{x}$. Biết đạo hàm của hàm số có dạng $y' = \\dfrac{a + b \\ln x}{x^2 \\ln 2}$. Tính giá trị của biểu thức $P = a + b$.", "choices": ["$P = 2$", "$P = -2$", "$P = 1$", "$P = 0$"], "correctIndex": 3, "explain": "Điều kiện xác định: $x > 0$.<br>Áp dụng quy tắc đạo hàm của một thương $y' = \\left( \\dfrac{\\log_2 x}{x} \\right)' = \\dfrac{(\\log_2 x)' \\cdot x - (\\log_2 x) \\cdot (x)'}{x^2}$.<br>Thay vào biểu thức đạo hàm, ta được:  $$y' = \\dfrac{\\dfrac{1}{x \\ln 2} \\cdot x - \\log_2 x \\cdot 1}{x^2} = \\dfrac{\\dfrac{1}{\\ln 2} - \\log_2 x}{x^2}.$$  $$y' = \\dfrac{\\dfrac{1}{\\ln 2} - \\dfrac{\\ln x}{\\ln 2}}{x^2} = \\dfrac{\\dfrac{1 - \\ln x}{\\ln 2}}{x^2} = \\dfrac{1 - \\ln x}{x^2 \\ln 2}.$$  Đối chiếu với biểu thức $y' = \\dfrac{a + b \\ln x}{x^2 \\ln 2}$, ta suy ra:  $\\heva{&a = 1\\\\&b = -1.}$  Vậy $P = a + b = 1 + (-1) = 0$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một máy bay tại độ cao $8$ km bắt đầu hạ độ cao theo quỹ đạo là một phần của parabol. Sau khi di chuyển theo phương ngang $1$ km thì độ cao chỉ còn $6$ km. Máy bay tiếp tục hạ độ cao còn $3$ km sau khi đi được $4$ km theo phương ngang và phóng $1$ tên lửa theo phương tiếp tuyến tại điểm phóng để hướng đến và trúng mục tiêu trên mặt đất. Giả sử rằng quỹ đạo chuyển động của tên lửa là đường thẳng thì mục tiêu cách vị trí phóng tên lửa theo phương ngang là bao nhiêu km?", "choices": ["$8$ km", "$10$ km", "$12$ km", "$16$ km"], "correctIndex": 2, "explain": "Chọn hệ trục tọa độ $Oxy$ như hình vẽ (trục $Oy$ biểu diễn độ cao, trục $Ox$ biểu diễn khoảng cách theo phương ngang, đơn vị là km). Gốc $O$ nằm trên mặt đất.<br>Giả sử quỹ đạo của máy bay là một phần của parabol $(P)\\colon y=ax^2+bx+c$.<br>Dựa vào dữ kiện bài toán, ta có các điểm thuộc $(P)$:<br>a) Tại vị trí bắt đầu hạ cánh: $x=0$, $y=8 \\Rightarrow c=8$.  <br>b) Sau khi đi ngang $1$ km: $x=1$, $y=6 \\Rightarrow a+b+8=6 \\Leftrightarrow a+b=-2$.  <br>c) Sau khi đi ngang $4$ km: $x=4$, $y=3 \\Rightarrow 16a+4b+8=3 \\Leftrightarrow 16a+4b=-5$.<br>Giải hệ phương trình $\\heva{&a+b=-2\\\\&16a+4b=-5}$ ta được $\\heva{&a=\\dfrac{1}{4}\\\\&b=-\\dfrac{9}{4}.}$<br>Vậy phương trình quỹ đạo là $(P)\\colon y=\\dfrac{1}{4}x^2-\\dfrac{9}{4}x+8$.<br>Điểm phóng tên lửa là $M(4;3)$. Ta có đạo hàm $y'=\\dfrac{1}{2}x-\\dfrac{9}{4}$.<br>Hệ số góc của tiếp tuyến tại $M(4;3)$ là $k=y'(4)=\\dfrac{1}{2} \\cdot 4-\\dfrac{9}{4}=-\\dfrac{1}{4}$.<br>Phương trình tiếp tuyến (quỹ đạo tên lửa) tại $M$ là:  $y=-\\dfrac{1}{4}(x-4)+3 \\Leftrightarrow y=-\\dfrac{1}{4}x+4$.<br>Mục tiêu tại mặt đất ứng với $y=0 \\Rightarrow -\\dfrac{1}{4}x+4=0 \\Leftrightarrow x=16$.<br>Khoảng cách từ mục tiêu đến vị trí phóng theo phương ngang là $|16-4|=12$ km.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, scale=0.8, font=\\footnotesize,scale=.8]\n\t\t\t\t\n\t\t\t\t\\draw[->] (-1,0) -- (12,0) node[below] {$x$ (km)};\n\t\t\t\t\\draw[->] (0,-1) -- (0,9) node[left] {$y$ (km)};\n\t\t\t\t\\draw (0,0) node[below left] {$O$};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\draw[thick, blue, samples=100, domain=0:4.5] plot (\\x, {0.25*\\x*\\x - 2.25*\\x + 8});\n\t\t\t\t\\node[blue] at (2,6.5) {Quỹ đạo máy bay};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\filldraw (0,8) circle (2pt) node[left] {$A(0;8)$};\n\t\t\t\t\\filldraw (1,6) circle (2pt) node[above right] {$(1;6)$};\n\t\t\t\t\\filldraw (4,3) circle (2pt) node[above right] {$M(4;3)$};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\draw[thick, red, dashed, domain=4:10] plot (\\x, {-0.25*\\x + 4});\n\t\t\t\t\\draw[->, red, thick] (4,3) -- (10,1.5) node[midway, above right] {Tên lửa};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\draw[dashed] (4,0) -- (4,3) -- (0,3);\n\t\t\t\t\\draw[dashed] (1,0) -- (1,6) -- (0,6);\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\filldraw[red] (11,0.25) node[above] {Mục tiêu};\n\t\t\t\t\\draw[red,->] (11,0.5) -- (12,0);\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\begin{scope}[shift={(0,8)}, scale=0.3]\n\t\t\t\t\t\\draw[fill=gray!50] (-1,0) -- (1,0) -- (0.5,0.5) -- (-0.5,0.5) -- cycle;\n\t\t\t\t\t\\draw (0,0.5) -- (0,1) -- (0.8,0.5);\n\t\t\t\t\\end{scope}\n\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Một nhà máy dự định phối trộn $1000$ kg nguyên liệu từ ba loại thành phần: Ngô ($x$ kg), Đậu nành ($y$ kg) và Phụ gia ($z$ kg). Giá lợi nhuận thu được trên mỗi kg ngô là $5$ nghìn đồng, đậu nành là $6$ nghìn đồng và phụ gia là $10$ nghìn đồng. Do yêu cầu dinh dưỡng, khối lượng ngô phải gấp ít nhất $4$ lần khối lượng đậu nành. Đồng thời, để đảm bảo chất lượng, khối lượng phụ gia sử dụng không được vượt quá $150$ kg.", "cauHoi": [{"question": "Trong mặt phẳng tọa độ $Oxy$, miền nghiệm biểu diễn các giá trị hợp lệ của khối lượng Ngô ($x$) và Đậu nành ($y$) là một phần mặt phẳng có dạng hình gì?", "choices": ["Một hình tam giác", "Một miền đa giác không giới hạn (miền mở)", "Một hình tứ giác", "Một hình ngũ giác"], "correctIndex": 1, "explain": "Từ giả thiết, ta có các điều kiện:<br>a) Tổng khối lượng: $x + y + z = 1000 \\Rightarrow z = 1000 - (x + y)$.  <br>b) Ràng buộc dinh dưỡng: $x \\ge 4y$.  <br>c) Ràng buộc phụ gia: $z \\le 150 \\Rightarrow 1000 - (x + y) \\le 150 \\Leftrightarrow x + y \\ge 850$.  <br>d) Điều kiện thực tế: $x, y \\ge 0$.<br>Hệ bất phương trình bậc nhất hai ẩn là: $\\heva{&x - 4y \\ge 0 \\\\ &x + y \\ge 850 \\\\ &x \\ge 0, y \\ge 0.}$  Miền nghiệm này được giới hạn bởi các đường thẳng nhưng không có điều kiện chặn trên cho tổng $x+y$ (vì $z$ có thể tiến về $0$ hoặc giá trị âm nếu không xét tổng $1000$ cố định, tuy nhiên ở đây $x+y$ có thể rất lớn nếu không xét $z \\ge 0$).   Thực tế, do $z \\ge 0$ nên $x+y \\le 1000$. Nhưng nếu chỉ xét hai điều kiện $x \\ge 4y$ và $x+y \\ge 850$ thì đây là một miền đa giác mở về phía trên bên phải."}, {"question": "Lợi nhuận lớn nhất mà nhà máy có thể thu được từ lô hàng $1000$ kg nguyên liệu này là bao nhiêu?", "choices": ["$5.350$ nghìn đồng", "$5.750$ nghìn đồng", "$5.920$ nghìn đồng", "$6.200$ nghìn đồng"], "correctIndex": 2, "explain": "Hàm lợi nhuận: $F(x,y,z) = 5x + 6y + 10z$.<br>Thay $z = 1000 - x - y$, ta được:  $F(x,y) = 5x + 6y + 10(1000 - x - y) = 10000 - 5x - 4y$.<br>Để $F$ đạt giá trị lớn nhất thì $T = 5x + 4y$ phải đạt giá trị nhỏ nhất.<br>Xét miền nghiệm hệ bất phương trình: $\\heva{&x + y + z = 1000 \\\\ &x \\ge 4y \\\\ &0 \\le z \\le 150 \\\\ &y \\ge 0.}$  Chuyển về $x, y$: $\\heva{&x \\ge 4y \\\\ &850 \\le x + y \\le 1000 \\\\ &y \\ge 0.}$<br>Miền nghiệm là một hình thang với các đỉnh: $A(680; 170), B(800; 200), C(1000; 0), D(850; 0)$.<br>Ta tính $T = 5x + 4y$ tại các đỉnh:<br>- Tại $A(680; 170)$: $T = 5(680) + 4(170) = 4080$.<br>- Tại $B(800; 200)$: $T = 5(800) + 4(200) = 4800$.<br>- Tại $C(1000; 0)$: $T = 5(1000) + 4(0) = 5000$.<br>- Tại $D(850; 0)$: $T = 5(850) + 4(0) = 4250$.<br>Giá trị $T$ nhỏ nhất là $4080$ tại $A$.<br>Lợi nhuận lớn nhất: $F_{max} = 10000 - 4080 = 5920$ (nghìn đồng).<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.01, >=stealth, font=\\footnotesize, line join=round, line cap=round]\n\t\t\t\t\t\\draw[->] (-30,0) -- (300,0) node[below] {$y$};\n\t\t\t\t\t\\draw[->] (0,-30) -- (0,250) node[left] {$z$};\n\t\t\t\t\t\\node at (-10,-10) {$O$};\n\t\t\t\t\t\\coordinate (O) at (0,0);\n\t\t\t\t\t\\coordinate (A) at (200,0);\n\t\t\t\t\t\\coordinate (B) at (170,150);\n\t\t\t\t\t\\coordinate (C) at (0,150);\n\t\t\t\t\t\\fill[green!20] (O) -- (A) -- (B) -- (C) -- cycle;\n\t\t\t\t\t\\draw[thick, blue] (0,150) -- (250,150) node[right] {$z=150$};\n\t\t\t\t\t\\draw[thick, red] (200,0) -- (140,300) node[above] {$5y+z=1000$};\n\t\t\t\t\t\\draw[very thick] (O) -- (A) -- (B) -- (C) -- cycle;\n\t\t\t\t\t\\foreach \\p in {A,B,C} \\fill (\\p) circle (100pt);\n\t\t\t\t\t\\node[below] at (200,0) {$200$};\n\t\t\t\t\t\\node[left] at (0,150) {$150$};\n\t\t\t\t\t\\node[above right] at (170,150) {$B(170;150)$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Trong một cộng đồng, tỉ lệ người mắc bệnh $X$ là $0{,}1\\%$. Để phát hiện bệnh, người ta sử dụng một loại xét nghiệm có độ chính xác như sau: Nếu một người mắc bệnh, xác suất xét nghiệm cho kết quả dương tính là $99\\%$; nếu một người không mắc bệnh, xác suất xét nghiệm cho kết quả dương tính (dương tính giả) là $1\\%$. Một người được chọn ngẫu nhiên trong cộng đồng và làm xét nghiệm.", "cauHoi": [{"question": "Xác suất để một người được chọn ngẫu nhiên có kết quả xét nghiệm dương tính là bao nhiêu?", "choices": ["$0{,}01000$", "$0{,}01098$", "$0{,}01099$", "$0{,}00999$"], "correctIndex": 1, "explain": "Gọi $B$ là biến cố người được chọn mắc bệnh $X$, khi đó $P(B)=0{,}001$ và $P(\\overline{B})=0{,}999$.<br>Gọi $T$ là biến cố kết quả xét nghiệm dương tính. Theo giả thiết:<br>$P(T|B)=0{,}99$ và $P(T|\\overline{B})=0{,}01$.<br>Áp dụng công thức xác suất đầy đủ:  $P(T)=P(B) \\cdot P(T|B)+P(\\overline{B}) \\cdot P(T|\\overline{B}) = 0{,}001 \\cdot 0{,}99+0{,}999 \\cdot 0{,}01 = 0{,}00099+0{,}00999 = 0{,}01098$."}, {"question": "Giả sử người này có kết quả xét nghiệm lần thứ nhất là dương tính. Để chắc chắn, người đó làm tiếp xét nghiệm lần thứ hai (giả sử kết quả lần hai độc lập với lần một). Nếu kết quả lần hai vẫn là dương tính, xác suất người này thực sự mắc bệnh $X$ là bao nhiêu (làm tròn đến $4$ chữ số thập phân)?", "choices": ["$0{,}0902$", "$0{,}5000$", "$0{,}8910$", "$0{,}9083$"], "correctIndex": 3, "explain": "Gọi $T_1$, $T_2$ lần lượt là biến cố kết quả xét nghiệm dương tính lần $1$ và lần $2$.<br>Ta cần tính xác suất $P(B|T_1 \\cap T_2)$.<br>Vì hai lần xét nghiệm độc lập đối với tình trạng bệnh của bệnh nhân, ta có:<br>$P(T_1 \\cap T_2|B) = P(T_1|B) \\cdot P(T_2|B) = (0{,}99)^2 = 0{,}9801$.<br>$P(T_1 \\cap T_2|\\overline{B}) = P(T_1|\\overline{B}) \\cdot P(T_2|\\overline{B}) = (0{,}01)^2 = 0{,}0001$.<br>Áp dụng công thức Bayes cho hai biến cố:  $P(B|T_1 \\cap T_2) = \\dfrac{P(B) \\cdot P(T_1 \\cap T_2|B)}{P(B) \\cdot P(T_1 \\cap T_2|B) + P(\\overline{B}) \\cdot P(T_1 \\cap T_2|\\overline{B})}$.<br>Thay số vào:  $P(B|T_1 \\cap T_2) = \\dfrac{0{,}001 \\cdot 0{,}9801}{0{,}001 \\cdot 0{,}9801 + 0{,}999 \\cdot 0{,}0001} = \\dfrac{0{,}0009801}{0{,}0009801 + 0{,}0000999} = \\dfrac{0{,}0009801}{0{,}00108}$.<br>$P(B|T_1 \\cap T_2) \\approx 0{,}9083$."}]}, {"noiDungChung": "Trong không gian với hệ tọa độ $Oxyz$, cho các điểm $A(2;0;0)$, $B(0;4;0)$ và $C(0;0;4)$. Gọi $M$ là trung điểm của cạnh $BC$ và $G$ là trọng tâm tam giác $ABC$.", "cauHoi": [{"question": "Tính diện tích $S$ của tam giác $ABC$.", "choices": ["$S=6$", "$S=6\\sqrt{2}$", "$S=4\\sqrt{6}$", "$S=12\\sqrt{2}$"], "correctIndex": 2, "explain": "Ta có $\\overrightarrow{AB}=(-2;4;0)$ và $\\overrightarrow{AC}=(-2;0;4)$.<br>Tích có hướng $[\\overrightarrow{AB}, \\overrightarrow{AC}] = \\left( \\begin{vmatrix} 4 & 0 \\\\ 0 & 4 \\end{vmatrix}; \\begin{vmatrix} 0 & -2 \\\\ 4 & -2 \\end{vmatrix}; \\begin{vmatrix} -2 & 4 \\\\ -2 & 0 \\end{vmatrix} \\right) = (16; 8; 8)$.<br>Diện tích tam giác $ABC$ là: $S = \\dfrac{1}{2} |[\\overrightarrow{AB}, \\overrightarrow{AC}]| = \\dfrac{1}{2}\\sqrt{16^2+8^2+8^2} = \\dfrac{1}{2}\\sqrt{384} = \\dfrac{1}{2} \\cdot 8\\sqrt{6} = 4\\sqrt{6}$."}, {"question": "Tìm tọa độ điểm $D$ sao cho tứ diện $ABCD$ có trọng tâm là gốc tọa độ $O$.", "choices": ["$D(2;4;4)$", "$D(-2;4;4)$", "$D(2;-4;-4)$", "$D(-2;-4;-4)$"], "correctIndex": 3, "explain": "Tọa độ trọng tâm $G_{tứ diện}$ của tứ diện $ABCD$ được tính bởi công thức:  $x_O = \\dfrac{x_A+x_B+x_C+x_D}{4} \\Rightarrow x_D = 4x_O - (x_A+x_B+x_C)$.<br>Tương tự cho $y_D$ và $z_D$.<br>Vì $O$ là gốc tọa độ nên $x_O=y_O=z_O=0$.<br>Ta có $\\heva{&x_D = 0 - (2+0+0) = -2\\\\&y_D = 0 - (0+4+0) = -4\\\\&z_D = 0 - (0+0+4) = -4.}$<br>Vậy $D(-2;-4;-4)$."}, {"question": "Tìm tọa độ điểm $S$ nằm trên trục $Ox$ sao cho tổng bình phương khoảng cách từ $S$ đến các đỉnh của tam giác $ABC$ đạt giá trị nhỏ nhất. Tính giá trị nhỏ nhất $P_{\\min}$ đó.", "choices": ["$P_{\\min}=\\dfrac{104}{3}$", "$P_{\\min}=\\dfrac{32}{3}$", "$P_{\\min}=32$", "$P_{\\min}=36$"], "correctIndex": 0, "explain": "Đặt $P=SA^2+SB^2+SC^2$. Theo tính chất trọng tâm, ta có:  $P=3SG^2+(GA^2+GB^2+GC^2)$.<br>Vì $(GA^2+GB^2+GC^2)$ là hằng số nên $P$ nhỏ nhất khi $SG$ nhỏ nhất.<br>Vì $S \\in Ox$ nên $S$ là hình chiếu vuông góc của $G$ lên trục $Ox \\Rightarrow S\\left(\\dfrac{2}{3};0;0\\right)$.<br>Tính giá trị nhỏ nhất:  $SA^2 = \\left(2-\\dfrac{2}{3}\\right)^2+0^2+0^2 = \\dfrac{16}{9}$.<br>$SB^2 = \\left(0-\\dfrac{2}{3}\\right)^2+(4-0)^2+0^2 = \\dfrac{4}{9}+16 = \\dfrac{148}{9}$.<br>$SC^2 = \\left(0-\\dfrac{2}{3}\\right)^2+0^2+(4-0)^2 = \\dfrac{4}{9}+16 = \\dfrac{148}{9}$.<br>Vậy $P_{\\min} = \\dfrac{16+148+148}{9} = \\dfrac{312}{9} = \\dfrac{104}{3}$."}]}, {"noiDungChung": "Cho hình lăng trụ tam giác $ABC.A'B'C'$ có đáy $ABC$ là tam giác đều cạnh $a$. Hình chiếu vuông góc của đỉnh $A'$ lên mặt phẳng $(ABC)$ trùng với trọng tâm $G$ của tam giác $ABC$. Biết góc giữa hai mặt phẳng $(AA'B'B)$ và $(ABC)$ bằng $60^\\circ$.", "cauHoi": [{"question": "Tính cosin góc $\\alpha$ giữa đường thẳng $AA'$ và mặt phẳng $(ABC)$", "choices": ["$\\dfrac{\\sqrt{3}}{2}$", "$\\dfrac{\\sqrt{3}}{4}$", "$\\dfrac{2}{\\sqrt{7}}$", "$\\dfrac{\\sqrt{7}}{2}$"], "correctIndex": 2, "explain": "Gọi $M$ là trung điểm $AB$. Vì $\\triangle ABC$ đều nên $CM \\perp AB$ và $CM = \\dfrac{a\\sqrt{3}}{2}$.<br>$G$ là trọng tâm nên $MG = \\dfrac{1}{3}MC = \\dfrac{a\\sqrt{3}}{6}$ và $AG = \\dfrac{2}{3}MC = \\dfrac{a\\sqrt{3}}{3}$.<br>Vì $A'G \\perp (ABC)$ nên $AB \\perp A'G$, mà $AB \\perp MG \\Rightarrow AB \\perp (A'MG) \\Rightarrow AB \\perp A'M$.<br>Góc giữa $(AA'B'B)$ và $(ABC)$ là $\\widehat{A'MG} = 60^\\circ$.<br>Trong $\\triangle A'GM$ vuông tại $G$: $A'G = MG \\cdot \\tan 60^\\circ = \\dfrac{a\\sqrt{3}}{6} \\cdot \\sqrt{3} = \\dfrac{a}{2}$.<br>Góc giữa $AA'$ và $(ABC)$ là $\\widehat{A'AG} = \\alpha$.<br>Trong $\\triangle A'GA$ vuông tại $G$: $\\tan\\alpha = \\dfrac{A'G}{AG} = \\dfrac{a/2}{a\\sqrt{3}/3} = \\dfrac{3}{2\\sqrt{3}} = \\dfrac{\\sqrt{3}}{2}$.<br>Ta có $1+\\tan^2\\alpha=\\dfrac{1}{\\cos^2\\alpha}$  $\\Rightarrow \\dfrac{1}{\\cos^2\\alpha}=1+\\left(\\dfrac{\\sqrt{3}}{2}\\right)^2=1+\\dfrac{3}{4}=\\dfrac{7}{4}$<br>$\\Rightarrow \\cos^2\\alpha=\\dfrac{4}{7} \\Rightarrow \\cos\\alpha=\\dfrac{2}{\\sqrt{7}}=\\dfrac{2\\sqrt{7}}{7}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, font=\\footnotesize, line join=round, line cap=round]\n\t\t\t\t\t\n\t\t\t\t\t\\path (0,0) coordinate (A)\n\t\t\t\t\t(4,0) coordinate (B)\n\t\t\t\t\t(1.5,-1.5) coordinate (C);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (G) at ($(A)!1/3!(B)!1/3!(C)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (A') at ($(G)+(0,4)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (B') at ($(B)+(A')-(A)$);\n\t\t\t\t\t\\coordinate (C') at ($(C)+(A')-(A)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (M) at ($(A)!0.5!(B)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw [dashed] (A)--(B) (G)--(A') (C)--(M) (G)--(M) (A')--(M);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw (A)--(C)--(B) (A')--(B')--(C')--cycle;\n\t\t\t\t\t\\draw (A)--(A') (B)--(B') (C)--(C');\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw (G)++(0,0.2)--++(0.2,0)--++(0,-0.2);\n\t\t\t\t\t\\draw (M)++(0.1,0.05) node[right]{$60^\\circ$};\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\foreach \\p/\\pos in {A/left, B/right, C/below, G/below, A'/above, B'/above, C'/above, M/above left}\n\t\t\t\t\t\\fill (\\p) circle (1pt) node[\\pos] {$\\p$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Tính thể tích $V$ của khối lăng trụ $ABC.A'B'C'$", "choices": ["$V=\\dfrac{a^3\\sqrt{3}}{4}$", "$V=\\dfrac{a^3\\sqrt{3}}{24}$", "$V=\\dfrac{a^3\\sqrt{3}}{8}$", "$V=\\dfrac{a^3}{8}$"], "correctIndex": 2, "explain": "Diện tích đáy $S_{ABC} = \\dfrac{a^2\\sqrt{3}}{4}$.<br>Chiều cao lăng trụ $h = A'G = \\dfrac{a}{2}$.<br>Thể tích khối lăng trụ $V = S_{ABC} \\cdot h = \\dfrac{a^2\\sqrt{3}}{4} \\cdot \\dfrac{a}{2} = \\dfrac{a^3\\sqrt{3}}{8}$."}, {"question": "Tính khoảng cách $d$ từ điểm $B$ đến mặt phẳng $(A'BC')$", "choices": ["$d=\\dfrac{a\\sqrt{21}}{7}$", "$d=\\dfrac{3a}{\\sqrt{31}}$", "$d=\\dfrac{a\\sqrt{3}}{4}$", "$d=\\dfrac{a}{2}$"], "correctIndex": 1, "explain": "Ta có $V_{B.A'BC'} = V_{C'.A'BC} = V_{A'.ABC} = \\dfrac{1}{3} \\cdot \\dfrac{a^3\\sqrt{3}}{8} = \\dfrac{a^3\\sqrt{3}}{24}$.<br>Xét tam giác $A'BC'$ có $BC' = \\sqrt{BC^2 + CC'^2} = \\sqrt{a^2 + (AA')^2}$.<br>Với $AA' = \\sqrt{A'G^2 + AG^2} = \\sqrt{\\left(\\dfrac{a}{2}\\right)^2 + \\left(\\dfrac{a\\sqrt{3}}{3}\\right)^2} = \\dfrac{a\\sqrt{21}}{6}$.<br>Tính diện tích $S_{A'BC'}$ và suy ra $d(B,(A'BC')) = \\dfrac{3V_{B.A'BC'}}{S_{A'BC'}} = \\dfrac{3a}{\\sqrt{31}}$."}]}, {"noiDungChung": "Ba bạn An, Bình, và Chi tham gia ba câu lạc bộ (CLB) khác nhau: Âm nhạc, Bóng đá, và Hội họa. Mỗi người sống ở một quận khác nhau: Quận 1, Quận 3, và Quận 5. Biết rằng Bình không học Hội họa; Người sống ở Quận 1 học Âm nhạc; An sống ở Quận 5; Chi không sống ở Quận 1.", "cauHoi": [{"question": "Khẳng định nào sau đây là <b>chắc chắn đúng</b>?", "choices": ["An tham gia câu lạc bộ Âm nhạc", "Chi sống ở Quận 5", "Bình sống ở Quận 1 và học Âm nhạc", "Chi học Hội họa"], "correctIndex": 2, "explain": "- An ở Quận 5 (GT).<br>- Chi không ở Quận 1 (GT) nên Chi chỉ có thể ở Quận 3 hoặc Quận 5. Vì An đã ở Quận 5 nên Chi ở Quận 3.<br>- Do đó, Bình là người duy nhất còn lại sống ở Quận 1.<br>- Theo dữ kiện, người ở Quận 1 học Âm nhạc. Vậy Bình sống ở Quận 1 và học Âm nhạc là chắc chắn đúng."}, {"question": "Dựa trên các dữ kiện đã cho, khẳng định nào sau đây là <b>có thể đúng</b>?", "choices": ["Bình tham gia câu lạc bộ Bóng đá", "An sống ở Quận 1", "Người sống ở Quận 3 tham gia câu lạc bộ Âm nhạc", "Chi tham gia câu lạc bộ Hội họa"], "correctIndex": 3, "explain": "- Ta đã xác định được: Bình (Q1 - Âm nhạc), An (Q5), Chi (Q3).<br>- Còn lại CLB Bóng đá và Hội họa. Vì không có thêm dữ kiện để phân biệt sở thích của An và Chi, nên việc Chi học Hội họa là một khả năng <b>có thể xảy ra</b> (nhưng không chắc chắn 100\\% vì Chi cũng có thể học Bóng đá)."}, {"question": "Nếu có thêm thông tin: “Người sống ở Quận 3 không thích thể thao”, hãy <b>sắp xếp</b> đúng tên CLB của các bạn theo thứ tự <b>An - Bình - Chi</b>.", "choices": ["Bóng đá - Âm nhạc - Hội họa", "Hội họa - Âm nhạc - Bóng đá", "Âm nhạc - Bóng đá - Hội họa", "Bóng đá - Hội họa - Âm nhạc"], "correctIndex": 0, "explain": "- Đã biết: Bình (Âm nhạc), Chi (Quận 3), An (Quận 5).<br>- Thông tin bổ sung: Người ở Quận 3 (Chi) không thích thể thao $\\Rightarrow$ Chi không học Bóng đá.<br>- Vậy Chi phải học Hội họa.<br>- CLB cuối cùng là Bóng đá dành cho An.<br>- Thứ tự An - Bình - Chi là: Bóng đá - Âm nhạc - Hội họa."}]}, {"noiDungChung": "Trong một phòng phân tích di truyền, có $4$ thiết bị xét nghiệm ký hiệu là $M$, $N$, $P$, $Q$ được đặt vào một hệ thống giá đỡ gồm $5$ vị trí liên tiếp được đánh số từ $1$ đến $5$ (từ trái sang phải). Mỗi vị trí chỉ chứa tối đa một thiết bị và có một vị trí sẽ để trống. Quy tắc sắp xếp như sau: <br>a) Thiết bị $M$ và $N$ phải được đặt cạnh nhau để kết nối dây tín hiệu ngắn.  <br>b) Thiết bị $P$ không được đặt ở vị trí số $1$ hoặc số $5$.  <br>c) Vị trí trống không được nằm ở hai đầu giá đỡ.  <br>d) Thiết bị $Q$ phải nằm ở vị trí có số thứ tự lớn hơn vị trí của $P$.", "cauHoi": [{"question": "Nếu vị trí số $2$ để trống, thiết bị nào sau đây chắc chắn nằm ở vị trí số $1$?", "choices": ["$P$", "$Q$", "$M$ hoặc $N$", "Không có thiết bị nào"], "correctIndex": 2, "explain": "Nếu vị trí $2$ trống:<br>- Vị trí $1$ phải có thiết bị (vì vị trí trống không ở đầu hàng theo dữ kiện 3).<br>- $P$ không ở $1$ (dữ kiện 2).<br>- $Q$ phải có số thứ tự lớn hơn $P$ (dữ kiện 4), nên nếu $Q$ ở $1$ thì không có chỗ cho $P$ (loại).<br>- Vậy vị trí $1$ chỉ có thể là $M$ hoặc $N$. Do $M, N$ cạnh nhau, nếu $M$ ở $1$ thì $N$ phải ở $2$, nhưng $2$ trống. Điều này dẫn tới một mâu thuẫn logic trong kịch bản vị trí $2$ trống. Tuy nhiên, xét theo các lựa chọn loại trừ cho vị trí $1$, chỉ có $M$ hoặc $N$ là ứng cử viên duy nhất."}, {"question": "Nếu thiết bị $P$ ở vị trí số $2$ và $Q$ ở vị trí số $5$, cặp thiết bị $M, N$ có thể nằm ở những vị trí nào?", "choices": ["$1$ và $2$", "$3$ và $4$", "$4$ và $5$", "$1$ và $3$"], "correctIndex": 1, "explain": "- $P$ ở $2$, $Q$ ở $5$. Các vị trí còn lại là $1, 3, 4$.<br>- Vị trí trống không ở $1$ và $5$, vậy vị trí trống phải là $3$ hoặc $4$.<br>- Nếu vị trí $3$ trống, thì $M, N$ phải ở $1$ và $4$ (không cạnh nhau, loại).<br>- Nếu vị trí $4$ trống, thì $M, N$ phải ở $1$ và $3$ (không cạnh nhau, loại).<br>- Xét lại: Nếu $M, N$ ở $3, 4$ thì vị trí trống là $1$ (vi phạm dữ kiện 3). <br>Để thỏa mãn $M, N$ cạnh nhau và trống không ở đầu, chỉ có thể xếp $M, N$ vào $\\{3, 4\\}$ và vị trí $1$ dành cho thiết bị còn lại, vị trí trống phải là $2$ nhưng $P$ đã ở đó. Vậy với $P(2)$ và $Q(5)$, phương án duy nhất là $M, N$ ở $\\{3, 4\\}$ và vị trí trống là một trong các số giữa."}, {"question": "Có ít nhất bao nhiêu vị trí mà thiết bị $P$ có thể đặt vào để luôn đảm bảo tồn tại một cách xếp thỏa mãn tất cả các quy tắc?", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 1, "explain": "- Theo dữ kiện (2), $P \\notin \\{1, 5\\} \\Rightarrow P \\in \\{2, 3, 4\\}$.<br>- Theo dữ kiện (4), $Q > P$. Nếu $P=4$, thì $Q=5$. Khi đó các vị trí còn lại là $1, 2, 3$. Để $M, N$ cạnh nhau, họ ở $\\{1, 2\\}$ hoặc $\\{2, 3\\}$. Vị trí trống sẽ là $3$ hoặc $1$. Nhưng trống không ở đầu nên trống là $3$ hoặc $2$.<br>- Nếu $P=2$, $Q \\in \\{3, 4, 5\\}$. Tương tự ta tìm được các cấu hình cho $M, N$ và vị trí trống.<br>- Nếu $P=3$, $Q \\in \\{4, 5\\}$.<br>Tổng cộng, $P$ có thể ở vị trí $2$ hoặc $3$ để đảm bảo luôn có khoảng trống không nằm ở đầu và $M, N$ được đứng cạnh nhau."}]}, {"noiDungChung": "Biểu đồ đoạn thẳng dưới đây thống kê doanh thu (đơn vị: tỷ đồng) của một công ty phần mềm trong các năm từ $2020$ đến $2024$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, font=\\footnotesize, line join=round, line cap=round]\n\t\t\t\n\t\t\t\\draw[->] (0,0) -- (6,0) node[below]{Năm};\n\t\t\t\\draw[->] (0,0) -- (0,5.5) node[left]{Doanh thu};\n\t\t\t\n\t\t\t\\draw[thick, blue, mark=*] (1,2) coordinate (2020) -- (2,1.5) coordinate (2021) -- (3,3.5) coordinate (2022) -- (4,4.5) coordinate (2023) -- (5,5) coordinate (2024);\n\t\t\t\n\t\t\t\\foreach \\x/\\y in {1/2020, 2/2021, 3/2022, 4/2023, 5/2024} \\node[below] at (\\x,0) {\\y};\n\t\t\t\n\t\t\t\\node[above left] at (2020) {$10$};\n\t\t\t\\node[below] at (2021) {$7{,}5$};\n\t\t\t\\node[above left] at (2022) {$17{,}5$};\n\t\t\t\\node[above] at (2023) {$22{,}5$};\n\t\t\t\\node[right] at (2024) {$25$};\n\t\t\t\n\t\t\t\\draw[dashed, gray!30] (0,2)--(1,2) (0,1.5)--(2,1.5) (0,3.5)--(3,3.5) (0,4.5)--(4,4.5) (0,5)--(5,5);\n\t\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Giai đoạn nào dưới đây doanh thu của công ty có xu hướng giảm?", "choices": ["Từ năm $2021$ đến $2022$", "Từ năm $2020$ đến $2021$", "Từ năm $2022$ đến $2024$", "Không có giai đoạn nào giảm"], "correctIndex": 1, "explain": "Dựa vào biểu đồ, đoạn thẳng nối từ năm $2020$ ($10$ tỷ) đến năm $2021$ ($7{,}5$ tỷ) đi xuống. Do đó, doanh thu giảm trong giai đoạn này."}, {"question": "Tốc độ tăng trưởng doanh thu của năm $2022$ so với năm $2021$ là bao nhiêu?", "choices": ["$100\\%$", "$125\\%$", "$133{,}33\\%$", "$57{,}14\\%$"], "correctIndex": 2, "explain": "Doanh thu năm $2021$ là $7{,}5$ tỷ, doanh thu năm $2022$ là $17{,}5$ tỷ.  Tốc độ tăng trưởng là: $\\dfrac{17{,}5-7{,}5}{7{,}5} \\cdot 100\\% = \\dfrac{10}{7{,}5} \\cdot 100\\% \\approx 133{,}33\\%$."}, {"question": "Nếu mục tiêu doanh thu năm $2025$ là phải đạt mức tăng tuyệt đối bằng mức tăng trung bình của giai đoạn từ $2021$ đến $2024$, thì doanh thu năm $2025$ cần đạt bao nhiêu?", "choices": ["$28{,}5$ tỷ đồng", "$30{,}83$ tỷ đồng", "$29{,}17$ tỷ đồng", "$32$ tỷ đồng"], "correctIndex": 1, "explain": "Mức tăng tuyệt đối trung bình mỗi năm trong giai đoạn $2021-2024$ là:  $$\\dfrac{25 - 7{,}5}{3} = \\dfrac{17{,}5}{3} \\approx 5{,}83\\text{ (tỷ đồng/năm).}$$  Vậy doanh thu dự kiến năm $2025$ là: $25 + 5{,}83 = 30{,}83$ tỷ đồng."}]}, {"noiDungChung": "Để chuẩn bị cho kỳ thi đánh giá năng lực, một giáo viên chủ nhiệm đã khảo sát thời gian tự học thêm tại nhà trong một ngày của $40$ học sinh trong lớp. Kết quả được trình bày trong bảng tần số ghép nhóm sau:<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Thời gian (giờ)</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[0; 2)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[2; 4)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[4; 6)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[6; 8)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[8; 10)$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Số học sinh ($n_i$)</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$4$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$12$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$14$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$8$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$2$</td></tr></table>", "cauHoi": [{"question": "Mệnh đề nào sau đây là đúng?", "choices": ["$[2; 4)$, đây là nhóm có thời gian học ít nhất", "$[4; 6)$, đây là khoảng thời gian học phổ biến nhất của học sinh trong lớp", "$[4; 6)$, đây là nhóm có thời gian học cao nhất", "$[2; 4)$, đây là khoảng thời gian học trung bình của cả lớp"], "correctIndex": 1, "explain": "Mốt của mẫu số liệu ghép nhóm nằm ở nhóm có tần số lớn nhất. Trong bảng trên, tần số lớn nhất là $14$, tương ứng với nhóm thời gian $[4; 6)$. Trong thực tế, mốt đại diện cho giá trị có khả năng xuất hiện cao nhất, tức là đa số học sinh trong lớp dành khoảng $4$ đến $6$ giờ để tự học."}, {"question": "Giả sử nhà trường yêu cầu khen thưởng những học sinh thuộc nhóm $25\\%$ có thời gian tự học cao nhất lớp. Một học sinh cần học ít nhất bao nhiêu giờ (làm tròn đến hai chữ số thập phân) để nằm trong danh sách khen thưởng này?", "choices": ["$6{,}00$ giờ", "$6{,}25$ giờ", "$6{,}50$ giờ", "$7{,}15$ giờ"], "correctIndex": 0, "explain": "Học sinh thuộc nhóm $25\\%$ có thời gian học cao nhất tương ứng với việc xác định tứ phân vị thứ ba $Q_3$ (vì $75\\%$ học sinh có thời gian học thấp hơn giá trị này).<br>Tổng số học sinh $n = 40$. Vị trí của $Q_3$ là $\\dfrac{3n}{4} = \\dfrac{3 \\cdot 40}{4} = 30$.<br>Ta có bảng tần số tích lũy:<br>- Nhóm $[0; 2)$: $4$.<br>- Nhóm $[2; 4)$: $4 + 12 = 16$.<br>- Nhóm $[4; 6)$: $16 + 14 = 30$.<br>- Nhóm $[6; 8)$: $30 + 8 = 38$.<br>Vì tần số tích lũy của nhóm $[4; 6)$ vừa bằng $30$, nên $Q_3$ chính là đầu mút phải của nhóm này, hoặc áp dụng công thức:  $Q_3 = 6 + \\dfrac{30 - 30}{8} \\cdot 2 = 6{,}00$."}, {"question": "Để đánh giá sự đồng đều về thời gian tự học giữa các học sinh, giáo viên tính độ lệch chuẩn $s$. Khẳng định nào sau đây về độ phân tán là đúng (làm tròn kết quả đến chữ số thập phân thứ hai)?", "choices": ["$s \\approx 2{,}42$, mức độ chênh lệch thời gian học giữa các học sinh là rất nhỏ", "$s \\approx 2{,}06$, mức độ chênh lệch thời gian học giữa các học sinh là tương đối rõ rệt", "$s \\approx 4{,}24$, dữ liệu tập trung rất sát số trung bình", "$s \\approx 1{,}85$, tất cả học sinh đều có thời gian học gần bằng nhau"], "correctIndex": 1, "explain": "Tính phương sai $s^2$:  $\\sum n_i x_i^2 = 4 \\cdot 1^2 + 12 \\cdot 3^2 + 14 \\cdot 5^2 + 8 \\cdot 7^2 + 2 \\cdot 9^2 = 4 + 108 + 350 + 392 + 162 = 1016$.<br>$s^2 = \\dfrac{1016}{40} - (4{,}6)^2 = 25{,}4 - 21{,}16 = 4{,}24$.<br>Độ lệch chuẩn: $s = \\sqrt{4{,}24} \\approx 2{,}06$.<br>Vì độ lệch chuẩn khác $0$ đáng kể nên thời gian học của các học sinh có sự phân hóa rõ rệt."}]}]}, {"id": "extra-1", "ten": "Đề chuẩn cấu trúc minh họa số 7", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Cho cấp số cộng $(u_n)$ có tổng $n$ số hạng đầu tiên được tính bởi công thức $S_n=2n^2-3n$. Giá trị của số hạng thứ $5$ trong cấp số cộng này bằng", "choices": ["$35$", "$15$", "$20$", "$25$"], "correctIndex": 1, "explain": "Để tìm số hạng thứ $5$ ($u_5$) khi biết công thức tổng $n$ số hạng đầu tiên ($S_n$), ta sử dụng mối liên hệ giữa số hạng và tổng tích lũy:<br>Ta có công thức: $u_n=S_n-S_{n-1}$ (với $n \\ge 2$).<br>Áp dụng cho số hạng thứ $5$: $u_5=S_5-S_4$.<br>$\\bullet$ Tính $S_5$: $S_5=2 \\cdot 5^2-3 \\cdot 5=50-15=35$.<br>$\\bullet$ Tính $S_4$: $S_4=2 \\cdot 4^2-3 \\cdot 4=32-12=20$.<br>Vậy giá trị của số hạng thứ $5$ là: $u_5=35-20=15$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho dãy số $(u_n)$ có giới hạn được xác định bởi biểu thức $\\lim\\limits\\dfrac{(2m-1)n^3+n^2+1}{n^3+2n-3}=4$, trong đó $m$ là tham số thực. Giá trị của tham số $m$ thuộc khoảng nào sau đây?", "choices": ["$(0;2)$", "$(3;4)$", "$(-1;1)$", "$(2;3)$"], "correctIndex": 3, "explain": "Ta thực hiện tính giới hạn của dãy số bằng cách chia cả tử và mẫu cho lũy thừa cao nhất của $n$ là $n^3$:  $$L=\\lim\\limits\\dfrac{n^3\\left(2m-1+\\dfrac{1}{n}+\\dfrac{1}{n^3}\\right)}{n^3\\left(1+\\dfrac{2}{n^2}-\\dfrac{3}{n^3}\\right)}=\\lim\\limits\\dfrac{2m-1+\\dfrac{1}{n}+\\dfrac{1}{n^3}}{1+\\dfrac{2}{n^2}-\\dfrac{3}{n^3}}$$  Vì $\\lim\\limits\\dfrac{1}{n}=\\lim\\limits\\dfrac{1}{n^2}=\\lim\\limits\\dfrac{1}{n^3}=0$ nên ta có:  $$L=\\dfrac{2m-1+0+0}{1+0-0}=2m-1$$  Theo giả thiết bài toán, giới hạn này bằng $4$, ta có phương trình:  $$2m-1=4 \\Leftrightarrow 2m=5 \\Leftrightarrow m=\\dfrac{5}{2}=2{,}5$$  Vì $2{,}5 \\in (2;3)$ nên phương án đúng là $(2;3)$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tính thể tích $V$ của khối tròn xoay tạo thành khi quay hình phẳng giới hạn bởi đường cong $y=\\sqrt{4-x^2}$ và trục $Ox$ quanh trục $Ox$.", "choices": ["$V=\\dfrac{16\\pi}{3}$", "$V=\\dfrac{32\\pi}{3}$", "$V=8\\pi$", "$V=\\dfrac{20\\pi}{3}$"], "correctIndex": 1, "explain": "Phương trình hoành độ giao điểm của đường cong $y=\\sqrt{4-x^2}$ và trục $Ox$ là:  $\\sqrt{4-x^2}=0 \\Leftrightarrow 4-x^2=0 \\Leftrightarrow \\hoac{&x=2\\\\&x=-2}$.<br>Thể tích khối tròn xoay tạo thành là:  $V=\\pi\\displaystyle\\int\\limits_{-2}^{2}\\left(\\sqrt{4-x^2}\\right)^2dx=\\pi\\displaystyle\\int\\limits_{-2}^{2}(4-x^2)dx$.<br>$V=\\pi\\left[4x-\\dfrac{x^3}{3}\\right]\\bigg|_{-2}^{2}=\\pi\\left[\\left(4 \\cdot 2-\\dfrac{2^3}{3}\\right)-\\left(4 \\cdot (-2)-\\dfrac{(-3)^3}{3}\\right)\\right]$.<br>$V=\\pi\\left[\\left(8-\\dfrac{8}{3}\\right)-\\left(-8+\\dfrac{8}{3}\\right)\\right]=\\pi\\left(\\dfrac{16}{3}+\\dfrac{16}{3}\\right)=\\dfrac{32\\pi}{3}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Số thập phân vô hạn tuần hoàn $0{,}1212\\dots$ được biểu diễn dưới dạng phân số tối giản $\\dfrac{a}{b}$. Tính $a+b$.", "choices": ["$28$", "$2803$", "$37$", "$1121$"], "correctIndex": 2, "explain": "Ta có $0{,}1212\\dots = 0{,}12+0{,}0012+0{,}000012+\\dots = \\dfrac{12}{10^2}+\\dfrac{12}{10^4}+\\dfrac{12}{10^6}+\\dots$  Đây là tổng của một cấp số nhân lùi vô hạn với số hạng đầu $u_1=\\dfrac{12}{100}$ và công bội $q=\\dfrac{1}{100}$.  Tổng của cấp số nhân này là: $S = \\dfrac{u_1}{1-q} = \\dfrac{\\dfrac{12}{100}}{1-\\dfrac{1}{100}} = \\dfrac{\\dfrac{12}{100}}{\\dfrac{99}{100}} = \\dfrac{12}{99} = \\dfrac{4}{33}$.  Vì $\\dfrac{a}{b}$ là phân số tối giản nên $a=4$, $b=33$.  Vậy $a+b=4+33=37$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ có diện tích $S$. Nếu tăng độ dài mỗi cạnh $BC$ và $AC$ lên $2$ lần đồng thời giữ nguyên độ lớn của góc $C$ thì diện tích của tam giác mới được tạo nên bằng", "choices": ["$2S$", "$3S$", "$5S$", "$4S$"], "correctIndex": 3, "explain": "Diện tích tam giác $ABC$ ban đầu là: $S = \\dfrac{1}{2}ac\\sin C = \\dfrac{1}{2}ab\\sin C$. (Trong đó $a=BC$, $b=AC$).<br>Khi tăng độ dài mỗi cạnh $BC$ và $AC$ lên $2$ lần, ta có các cạnh mới là $a' = 2a$ và $b' = 2b$.<br>Diện tích tam giác mới là:  $S' = \\dfrac{1}{2}a'b'\\sin C = \\dfrac{1}{2}(2a)(2b)\\sin C = 4 \\cdot \\left(\\dfrac{1}{2}ab\\sin C\\right) = 4S$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Bất phương trình $\\dfrac{x^2-3x+2}{x-3} \\ge 0$ có bao nhiêu nghiệm nguyên thuộc đoạn $[-5; 5]$?", "choices": ["$3$", "$4$", "$5$", "$6$"], "correctIndex": 1, "explain": "Xét $f(x)=\\dfrac{x^2-3x+2}{x-3}$.<br>Tử thức $x^2-3x+2=0 \\Leftrightarrow \\hoac{&x=1\\\\&x=2}$.<br>Mẫu thức $x-3=0 \\Leftrightarrow x=3$.<br>Bảng xét dấu:<br>Để $f(x) \\ge 0$ thì $x \\in [1; 2] \\cup (3; +\\infty)$.<br>Kết hợp điều kiện $x \\in [-5; 5]$ và $x \\in \\mathbb{Z}$, ta có $x \\in \\{1, 2, 4, 5\\}$.<br>Vậy có $4$ nghiệm nguyên thỏa mãn.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hàm số $f(x)=\\left\\{\\begin{array}{ll}(x+1)^2 & \\text { khi } x>1 \\\\ x^2+3 & \\text { khi } x<1 \\\\ k^2 & \\text { khi } x=1\\end{array}\\right.$. Có bao nhiêu số nguyên $k$ để $f(x)$ liên tục tại $x=1$.", "choices": ["$1$", "$0$", "$2$", "$3$"], "correctIndex": 2, "explain": "Ta có: $f(1)=k^2$<br>Mặt khác $\\lim _{x \\rightarrow 1^{-}} f(x)=\\lim _{x \\rightarrow 1^{-}}\\left(x^2+3\\right)=4 ; \\lim _{x \\rightarrow 1^{+}} f(x)=\\lim _{x \\rightarrow 1^{+}}(x+1)^2=4$ suy ra $\\lim _{x \\rightarrow 1} f(x)=4$.<br>Vậy để hàm số liên tục tại $x=1$ khi $\\lim _{x \\rightarrow 1} f(x) = f(1) \\Leftrightarrow k^2 = 4 \\Leftrightarrow k = \\pm 2$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một tam giác có độ dài các cạnh là $1$, $m$, $2$ với $m \\in \\mathbb{Z}$. Giá trị của $m$ là", "choices": ["$2$", "$1$", "$3$", "$4$"], "correctIndex": 0, "explain": "Theo bất đẳng thức tam giác, với ba cạnh có độ dài $1$, $m$, $2$, ta phải có:  $\\heva{&1+m>2\\\\&1+2>m\\\\&m+2>1} \\Leftrightarrow \\heva{&m>1\\\\&m<3\\\\&m>-1} \\Leftrightarrow 1 < m < 3$.  Vì $m \\in \\mathbb{Z}$ nên $m=2$."}]}, {"noiDungChung": "Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình chữ nhật với $AD=2a$. Tam giác $SAB$ vuông cân tại $S$ và nằm trong mặt phẳng vuông góc với đáy. Biết tổng diện tích tam giác $SAB$ và đáy $ABCD$ bằng $\\dfrac{33a^2}{4}$. Gọi $H$ là trung điểm của cạnh $AB$.", "cauHoi": [{"question": "Thể tích khối chóp $S.ABCD$ bằng bao nhiêu?", "choices": ["$a^3$", "$2a^3$", "$3a^3$", "$4a^3$"], "correctIndex": 2, "explain": "Đặt $AB=x$ ($x>0$). Do tam giác $SAB$ vuông cân tại $S$ nên đường cao $SH=\\dfrac{x}{2}$ và diện tích tam giác $SAB$ là $S_{SAB}=\\dfrac{1}{2}SH \\cdot AB=\\dfrac{x^2}{4}$.<br>Diện tích đáy $S_{ABCD}=AB \\cdot AD=2ax$.<br>Theo giả thiết: $S_{SAB}+S_{ABCD}=\\dfrac{33a^2}{4} \\Leftrightarrow \\dfrac{x^2}{4}+2ax=\\dfrac{33a^2}{4} \\Leftrightarrow x^2+8ax-33a^2=0 \\Leftrightarrow \\hoac{&x=3a\\\\&x=-11a \\text{ (loại)}}$.<br>Với $AB=3a$, ta có $S_{ABCD}=3a \\cdot 2a=6a^2$ và $SH=\\dfrac{3a}{2}$.<br>Thể tích khối chóp là: $V=\\dfrac{1}{3}SH \\cdot S_{ABCD}=\\dfrac{1}{3} \\cdot \\dfrac{3a}{2} \\cdot 6a^2=3a^3$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>"}, {"question": "Số đo của góc giữa đường thẳng $SC$ và mặt phẳng đáy $(ABCD)$ gần với giá trị nào nhất sau đây?", "choices": ["$26^{\\circ}$", "$31^{\\circ}$", "$47^{\\circ}$", "$53^{\\circ}$"], "correctIndex": 1, "explain": "Do $SH \\perp (ABCD)$ nên góc giữa $SC$ và $(ABCD)$ là góc $\\angle SCH$.<br>Ta có $AB=3a$ nên $HB=\\dfrac{3a}{2}$.<br>Trong tam giác vuông $HBC$: $HC=\\sqrt{HB^2+BC^2}=\\sqrt{\\left(\\dfrac{3a}{2}\\right)^2+(2a)^2}=\\dfrac{5a}{2}$.<br>Trong tam giác vuông $SHC$: $\\tan \\angle SCH=\\dfrac{SH}{HC}=\\dfrac{\\dfrac{3a}{2}}{\\dfrac{5a}{2}}=\\dfrac{3}{5}$.<br>Suy ra $\\angle SCH \\approx 30{,}96^{\\circ}$. Vậy giá trị gần nhất là $31^{\\circ}$."}, {"question": "Khoảng cách từ điểm $A$ đến mặt phẳng $(SBD)$ bằng bao nhiêu?", "choices": ["$\\dfrac{3a}{2}$", "$\\dfrac{6a}{\\sqrt{61}}$", "$\\dfrac{6a}{\\sqrt{17}}$", "$\\dfrac{a\\sqrt{3}}{2}$"], "correctIndex": 2, "explain": "Ta có $AD \\parallel BC \\Rightarrow AD \\parallel (SBC)$. Tuy nhiên ta cần tính $d(A,(SBD))$.<br>Vì $H$ là trung điểm $AB$ nên $d(A,(SBD))=2d(H,(SBD))$.<br>Kẻ $HK \\perp BD$ tại $K$, kẻ $HI \\perp SK$ tại $I \\Rightarrow HI=d(H,(SBD))$.<br>Trong tam giác vuông $ABD$: $BD=\\sqrt{AB^2+AD^2}=\\sqrt{(3a)^2+(2a)^2}=a\\sqrt{13}$.<br>Chiều cao $HK=\\dfrac{HB \\cdot AD}{BD}=\\dfrac{\\dfrac{3a}{2} \\cdot 2a}{a\\sqrt{13}}=\\dfrac{3a}{\\sqrt{13}}$.<br>Xét tam giác vuông $SHK$: $\\dfrac{1}{HI^2}=\\dfrac{1}{SH^2}+\\dfrac{1}{HK^2}=\\dfrac{1}{\\left(\\dfrac{3a}{2}\\right)^2}+\\dfrac{1}{\\left(\\dfrac{3a}{\\sqrt{13}}\\right)^2}=\\dfrac{4}{9a^2}+\\dfrac{13}{9a^2}=\\dfrac{17}{9a^2}$.<br>Suy ra $HI=\\dfrac{3a}{\\sqrt{17}}$.   Vậy $d(A,(SBD))=2\\dfrac{3a}{\\sqrt{17}}=\\dfrac{6a}{\\sqrt{17}}$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $a=\\log_{30}3,b=\\log_{30}5.$ Biết $\\log_{30}1350=ma+nb+p$ với $m, n, p$ là các số hữu tỉ. Phát biểu nào sau đây đúng", "choices": ["$m>n>p$", "$m=n+p$", "$m.n.p=6$", "$n$ là số tự nhiên chẵn"], "correctIndex": 1, "explain": "$\\log_{30}1350=\\log_{30}\\left(30.3^2.5\\right)=\\log_{30}30+2\\log_{30}3+\\log_{30}5=1+2a+b.$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một người vay $100$ triệu đồng, lãi suất $0,7\\%$/tháng, trả góp mỗi tháng $5$ triệu đồng. Hỏi sau bao nhiêu tháng thì người đó trả hết nợ?", "choices": ["$22$", "$23$", "$24$", "$21$"], "correctIndex": 0, "explain": "<b>1. Công thức tổng quát:</b>  Số tiền còn nợ $S_n$ sau $n$ tháng trả góp là:  $$S_n = A(1+r)^n - \\dfrac{m}{r}\\left[(1+r)^n - 1\\right]$$  Trong đó: $A=100$ (triệu), $r=0,007$, $m=5$ (triệu).<br>\\textbf{2. Điều kiện trả hết nợ ($S_n \\le 0$):}  $$\\begin{aligned}  A(1+r)^n \\le \\dfrac{m}{r}\\left[(1+r)^n - 1\\right] &\\iff (1+r)^n \\ge \\dfrac{m}{m - Ar} <br>&\\iff (1,007)^n \\ge \\dfrac{5}{5 - 100 \\cdot 0,007} = \\dfrac{5}{4,3}  \\end{aligned}$$<br><b>3. Kết luận:</b>  $$n \\ge \\log_{1,007}\\left(\\dfrac{5}{4,3}\\right) \\approx 21,63$$  Vì $n$ là số nguyên dương, nên sau tháng thứ $21$ nợ vẫn còn dư, người đó cần trả hết ở tháng thứ $22$. Vậy chọn $n=22$."}]}, {"noiDungChung": "Trong mặt phẳng tọa độ $Oxy$, cho tam giác $ABC$ có đỉnh $A(1;2)$, đường trung tuyến kẻ từ $B$ là $d_1: x-2y+1=0$ và đường cao kẻ từ $C$ là $d_2: -x+y+1=0$.", "cauHoi": [{"question": "Tọa độ đỉnh $C$ của tam giác $ABC$ là", "choices": ["$C(4;5)$", "$C(-3;-2)$", "$C(-4;3)$", "$C(1;-3)$"], "correctIndex": 1, "explain": "Vì $C \\in d_2$ nên $C(c;c+1)$.<br>Gọi $M$ là trung điểm $AC$, ta có $M\\left(\\dfrac{c+1}{2};\\dfrac{c+3}{2}\\right)$.<br>Vì $M \\in d_1$ nên $\\dfrac{c+1}{2}-2\\left(\\dfrac{c+3}{2}\\right)+1=0 \\Leftrightarrow c+1-2c-6+2=0 \\Leftrightarrow c=-3$.<br>Vậy $C(-3;-2)$."}, {"question": "Phương trình đường thẳng $AB$ là", "choices": ["$x+y-1=0$", "$x+y-3=0$", "$x-y+1=0$", "$2x+y-4=0$"], "correctIndex": 1, "explain": "Đường thẳng $AB$ đi qua $A(1;2)$ và vuông góc với đường cao $d_2: -x+y+1=0$.<br>Vectơ pháp tuyến của $AB$ là $\\vec{n}_{AB}=(1;1)$.<br>Phương trình $AB: 1(x-1)+1(y-2)=0 \\Leftrightarrow x+y-3=0$."}, {"question": "Tính diện tích $S$ của tam giác $ABC$", "choices": ["$S=\\dfrac{25}{4}$", "$S=12{,}5$", "$S=\\dfrac{8}{3}$", "$S=25$"], "correctIndex": 2, "explain": "Tọa độ đỉnh $B$ là giao điểm của đường thẳng $AB$ và đường trung tuyến $d_1$:<br>Giải hệ phương trình: $\\heva{&x+y-3=0\\\\&x-2y+1=0} \\Leftrightarrow \\heva{&x=\\dfrac{5}{3}\\\\&y=\\dfrac{4}{3}} \\Rightarrow B\\left(\\dfrac{5}{3};\\dfrac{4}{3}\\right)$.<br>Với $A(1;2)$ và $C(-3;-2)$, ta có $\\vec{AC}=(-4;-4)$. Độ dài $AC = \\sqrt{(-4)^2+(-4)^2} = 4\\sqrt{2}$.<br>Phương trình đường thẳng $AC$: Đi qua $A(1;2)$ có VTPT $\\vec{n}_{AC}=(1;-1) \\Rightarrow 1(x-1)-1(y-2)=0 \\Leftrightarrow x-y+1=0$.<br>Khoảng cách từ $B$ đến đường thẳng $AC$ là:<br>$h = d(B,AC) = \\dfrac{|\\frac{5}{3}-\\frac{4}{3}+1|}{\\sqrt{1^2+(-1)^2}} = \\dfrac{\\frac{4}{3}}{\\sqrt{2}} = \\dfrac{4}{3\\sqrt{2}}$.<br>Diện tích tam giác $ABC$ là: $S = \\dfrac{1}{2} \\cdot h \\cdot AC = \\dfrac{1}{2} \\cdot \\dfrac{4}{3\\sqrt{2}} \\cdot 4\\sqrt{2} = \\dfrac{8}{3}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một mảnh đất hình chữ nhật có chu vi bằng $28$ m. Đường chéo của hình chữ nhật dài $10$ m. Tính diện tích của mảnh đất đó.", "choices": ["$12$ m$^2$", "$24$ m$^2$", "$36$ m$^2$", "$48$ m$^2$"], "correctIndex": 3, "explain": "Gọi chiều dài và chiều rộng của mảnh đất lần lượt là $x$, $y$ (đơn vị: m, điều kiện: $14 > x \\ge y > 0$).<br>Vì chu vi của hình chữ nhật là $28$ m nên ta có phương trình:  $$2(x+y)=28 \\Leftrightarrow x+y=14. \\quad (1)$$  Vì đường chéo của hình chữ nhật dài $10$ m, áp dụng định lý Pitago ta có phương trình:  $$x^2+y^2=10^2 \\Leftrightarrow x^2+y^2=100. \\quad (2)$$  Từ $(1)$ và $(2)$, ta có hệ phương trình:  $$\\heva{&x+y=14<br>&x^2+y^2=100} \\Leftrightarrow \\heva{&y=14-x<br>&x^2+(14-x)^2=100. \\quad (3)}$$  Giải phương trình $(3)$:  $$x^2+196-28x+x^2=100 \\Leftrightarrow 2x^2-28x+96=0 \\Leftrightarrow x^2-14x+48=0.$$  Phương trình có hai nghiệm $x=8$ (nhận) và $x=6$ (nhận).<br>Với $x=8 \\Rightarrow y=6$; với $x=6 \\Rightarrow y=8$ (loại vì $x \\ge y$).<br>Vậy chiều dài mảnh đất là $8$ m và chiều rộng là $6$ m.<br>Diện tích của mảnh đất là: $S=x \\cdot y=8 \\cdot 6=48$ m$^2$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $\\displaystyle\\int\\limits_{0}^{\\tfrac{\\pi}{2}}f(x)dx=5$. Tính $I=\\displaystyle\\int\\limits_{0}^{\\tfrac{\\pi}{2}}[f(x)+2\\sin x]dx$.", "choices": ["$5+\\pi$", "$5+\\dfrac{\\pi}{2}$", "$7$", "$3$"], "correctIndex": 2, "explain": "Ta có:  $I=\\int\\limits_{0}^{\\dfrac{\\pi}{2}}f(x)dx+\\int\\limits_{0}^{\\dfrac{\\pi}{2}}2\\sin xdx$.<br>Theo giả thiết $\\int\\limits_{0}^{\\dfrac{\\pi}{2}}f(x)dx=5$.<br>Tính $J=\\int\\limits_{0}^{\\dfrac{\\pi}{2}}2\\sin xdx = [-2\\cos x]\\bigg|_{0}^{\\dfrac{\\pi}{2}} = -2\\cos\\dfrac{\\pi}{2}-(-2\\cos 0) = 0+2=2$.<br>Vậy $I=5+2=7$."}]}, {"noiDungChung": "Một trung tâm dữ liệu vận hành một hệ thống gồm ba máy chủ hoạt động độc lập để lưu trữ hồ sơ. Xác suất gặp sự cố gây mất kết nối của máy chủ thứ nhất, thứ hai và thứ ba lần lượt là $0{,}05$; $0{,}04$ và $0{,}03$. Chỉ cần ít nhất một máy chủ hoạt động bình thường thì hệ thống vẫn có thể truy xuất dữ liệu được.", "cauHoi": [{"question": "Xác suất để hệ thống có thể truy xuất dữ liệu được viết dưới dạng phân số tối giản là $\\dfrac{a}{b}$. Tính giá trị của biểu thức $S=b-a$.", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 2, "explain": "Gọi $A_1$, $A_2$, $A_3$ lần lượt là biến cố máy chủ thứ nhất, thứ hai và thứ ba gặp sự cố.<br>Ta có $P(A_1)=0{,}05$; $P(A_2)=0{,}04$; $P(A_3)=0{,}03$.<br>Vì các máy chủ hoạt động độc lập nên biến cố hệ thống không thể truy xuất dữ liệu (cả ba máy cùng gặp sự cố) là:  $P(\\overline{A})=P(A_1 \\cap A_2 \\cap A_3)=0{,}05 \\cdot 0{,}04 \\cdot 0{,}03=0{,}00006$.<br>Xác suất để hệ thống truy xuất được dữ liệu là $P(A)=1-0{,}00006=0{,}99994$.<br>Ta có $0{,}99994=\\dfrac{99994}{100000}=\\dfrac{49997}{50000}$.<br>Vì $\\dfrac{49997}{50000}$ là phân số tối giản nên $a=49997$, $b=50000$.<br>Vậy $S=b-a=50000-49997=3$."}, {"question": "Giả sử trung tâm bổ sung thêm một máy chủ thứ tư hoạt động độc lập với ba máy trên. Để xác suất truy xuất dữ liệu thành công đạt ít nhất $0{,}99999$, xác suất gặp sự cố của máy chủ thứ tư tối đa là bao nhiêu?", "choices": ["$0{,}1666$", "$0{,}0100$", "$0{,}0001$", "$0{,}2000$"], "correctIndex": 0, "explain": "Gọi $p$ là xác suất gặp sự cố của máy chủ thứ tư.<br>Xác suất để hệ thống không thể truy xuất dữ liệu với $4$ máy chủ là: $P(\\overline{A'})=0{,}00006 \\cdot p$.<br>Để hệ thống truy xuất thành công với xác suất ít nhất $0{,}99999$ thì:  $1-0{,}00006 \\cdot p \\ge 0{,}99999 \\Leftrightarrow 0{,}00006 \\cdot p \\le 0{,}00001 \\Leftrightarrow p \\le \\dfrac{1}{6} \\approx 0{,}1666$."}, {"question": "Biết rằng hệ thống hiện tại vẫn đang truy xuất được dữ liệu, tính xác suất để máy chủ thứ nhất đang gặp sự cố (làm tròn đến $6$ chữ số thập phân)?", "choices": ["$0{,}050000$", "$0{,}000060$", "$0{,}049943$", "$0{,}050003$"], "correctIndex": 2, "explain": "Ta cần tính xác suất có điều kiện $P(A_1|A)$.<br>Áp dụng công thức định nghĩa: $P(A_1|A)=\\dfrac{P(A_1 \\cap A)}{P(A)}$.<br>Biến cố $A_1 \\cap A$ là biến cố \"Máy chủ $1$ gặp sự cố nhưng hệ thống vẫn truy xuất được dữ liệu\" (nghĩa là máy $1$ hỏng và ít nhất một trong hai máy còn lại hoạt động).<br>$P(A_1 \\cap A)=P(A_1) \\cdot P(A_2 \\cup A_3 \\text{ có ít nhất 1 máy hoạt động})$.<br>$P(A_1 \\cap A)=0{,}05 \\cdot (1-0{,}04 \\cdot 0{,}03)=0{,}05 \\cdot (1-0{,}0012)=0{,}05 \\cdot 0{,}9988=0{,}04994$.<br>Xác suất cần tìm: $P(A_1|A)=\\dfrac{0{,}04994}{0{,}99994} \\approx 0{,}049943$."}]}, {"noiDungChung": "Cho hàm số $y=f(x)=\\dfrac{e^{2x}-3e^x+6}{e^x-2}$ có đồ thị là $(C)$.", "cauHoi": [{"question": "Xác định tập xác định $D$ của hàm số đã cho.", "choices": ["$D=\\mathbb{R}$", "$D=(2;+\\infty)$", "$D=\\mathbb{R}\\setminus\\{\\ln 2\\}$", "$D=\\mathbb{R}\\setminus\\{2\\}$"], "correctIndex": 2, "explain": "Hàm số xác định khi mẫu thức khác $0$: $e^x-2\\neq 0\\Leftrightarrow e^x\\neq 2\\Leftrightarrow x\\neq\\ln 2$.  Vậy tập xác định là $D=\\mathbb{R}\\setminus\\{\\ln 2\\}$."}, {"question": "Xét đồ thị hàm số $f(x)$ trên khoảng $(\\ln 2;+\\infty)$. Mệnh đề nào sau đây sai?", "choices": ["Hàm số nghịch biến trên khoảng $(\\ln 2;+\\infty)$", "Hàm số đạt cực tiểu tại $x=\\ln 4$", "Đồ thị hàm số có tiệm cận đứng là $x=\\ln 2$", "Giá trị cực tiểu của hàm số là $5$"], "correctIndex": 0, "explain": "Đặt $t=e^x$. Với $x\\in(\\ln 2;+\\infty)$ thì $t\\in(2;+\\infty)$.<br>Xét hàm số $g(t)=\\dfrac{t^2-3t+6}{t-2}$ trên $(2;+\\infty)$.<br>Ta có $g'(t)=\\dfrac{(2t-3)(t-2)-(t^2-3t+6)}{(t-2)^2}=\\dfrac{t^2-4t}{(t-2)^2}$.<br>$g'(t)=0\\Leftrightarrow\\hoac{&t=0\\text{ (loại)}\\\\&t=4\\text{ (nhận).}}$  Bảng biến thiên của $g(t)$ trên $(2;+\\infty)$:<br>Dựa vào bảng biến thiên, giá trị nhỏ nhất của hàm số trên khoảng đã cho là $5$ tại $t=4$ (tương ứng $x=\\ln 4$).<br>a) Hàm số nghịch biến trên $(2; 4)$ (tương ứng $x\\in(\\ln 2; \\ln 4)$) và đồng biến trên $(4; +\\infty)$ (tương ứng $x\\in(\\ln 4; +\\infty)$). Vậy mệnh đề \"Hàm số nghịch biến trên khoảng $(\\ln 2; +\\infty)$\" là sai.  <br>b) Hàm số đạt cực tiểu tại $t=4 \\Rightarrow x=\\ln 4$.  <br>c) $\\lim\\limits_{x \\to (\\ln 2)^+} f(x) = +\\infty$ nên $x=\\ln 2$ là tiệm cận đứng.  <br>d) Giá trị cực tiểu $y_{CT} = g(4) = 5$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>"}, {"question": "Có bao nhiêu số nguyên âm của tham số $m$ để phương trình $f(x)=m$ có đúng hai nghiệm thực phân biệt?", "choices": ["$0$", "$1$", "$3$", "Vô số"], "correctIndex": 0, "explain": "Đặt $t=e^x$ ($t>0$, $t\\neq 2$). Phương trình trở thành $\\dfrac{t^2-3t+6}{t-2}=m\\Leftrightarrow t^2-(m+3)t+2m+6=0$.<br>Xét hàm số $g(t)=\\dfrac{t^2-3t+6}{t-2}$ trên $D_t=(0;+\\infty)\\setminus\\{2\\}$.<br>Ta có $g'(t)=\\dfrac{t^2-4t}{(t-2)^2}$; $g'(t)=0\\Leftrightarrow\\hoac{&t=0\\\\&t=4.}$  <br>Bảng biến thiên của $g(t)$:<br>Để phương trình $f(x)=m$ có đúng hai nghiệm $x$ phân biệt thì phương trình $g(t)=m$ phải có đúng hai nghiệm $t>0$ phân biệt.<br>a) Với $m\\in(-\\infty;-3)$, đường thẳng $y=m$ chỉ cắt nhánh trái $(0;2)$ tại một điểm.  <br>b) Với $m\\in(-3;5)$, đường thẳng $y=m$ không thể cắt nhánh trái (vì giới hạn tại $0$ là $-3$) và không cắt nhánh phải (vì cực tiểu là $5$).  <br>c) Với $m=5$, phương trình có nghiệm duy nhất $t=4$.  <br>d) Với $m\\in(5;+\\infty)$, đường thẳng $y=m$ cắt nhánh phải $(2;+\\infty)$ tại hai điểm phân biệt và không cắt nhánh trái.<br>Vậy phương trình có đúng hai nghiệm phân biệt khi $m>5$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>"}]}, {"noiDungChung": "Bạn An dự định làm hai loại đèn trung thu, toàn bộ số tiền bán được An sẽ ủng hộ miền Bắc sau cơn bão Yagi. Cần 2 giờ để làm xong một chiếc lồng đèn hình ngôi sao, và bán giá 30 ngàn đồng. Cần 3 giờ để làm một chiếc đèn hình con thỏ cần 3 giờ và bán giá 50 ngàn đồng. Bạn An có 30 giờ để làm hai loại đèn trung thu, và bạn muốn làm ít nhất 12 chiếc. Giả sử số đèn trung thu An làm đươc đều bán được hết. Gọi $x ; y$ lần lượt là số đèn trung thu hình ngôi sao và số đèn trung thu hình con thỏ $(x \\geq 0 ; y \\geq 0 ; x ; y \\in \\mathbb{N})$.", "cauHoi": [{"question": "Viết hệ bất phương trình theo $x$, $y$ dựa vào tất cả giả thiết đã cho.", "choices": ["$\\left\\{\\begin{array}{l}x \\geq 0 \\\\ y \\geq 0 \\\\ 2 x+3 y \\leq 30 \\\\ x+y \\geq 12\\end{array}\\right.$", "$\\left\\{\\begin{array}{l}x \\geq 0 \\\\ y \\geq 0 \\\\ 2 x+3 y \\geq 12 \\\\ x+y \\geq 30\\end{array}\\right.$", "$\\left\\{\\begin{array}{l}x \\geq 0 \\\\ y \\geq 0 \\\\ 2 x+3 y \\leq 30 \\\\ x+y \\leq 12\\end{array}\\right.$", "$\\left\\{\\begin{array}{l}x \\geq 0 \\\\ y \\geq 0 \\\\ 2 x+3 y \\leq 12 \\\\ x+y \\geq 30\\end{array}\\right.$"], "correctIndex": 0, "explain": "Gọi $x ; y$ lần lượt là số đèn trung thu hình ngôi sao và số đèn trung thu hình con thỏ $(x \\geq 0 ; y \\geq 0 ; x ; y \\in \\mathbb{N}$ )<br>Theo bài ra ta có hệ bất phương trình sau: $\\left\\{\\begin{array}{l}x \\geq 0 \\\\ y \\geq 0 \\\\ 2 x+3 y \\leq 30 \\\\ x+y \\geq 12\\end{array}\\right.$"}, {"question": "Khi số tiền An bán được là lớn nhất thì số tiền mà An ủng hộ cho miền Bắc lớn nhất là bao nhiêu ngàn đồng?", "choices": ["500", "450", "480", "425"], "correctIndex": 2, "explain": "Số tiền An thu được về là: $F(x ; y)=30 x+50 y$  Miền nghiệm cùa hệ là miền tam giác $A B C$ với $A(6 ; 6) ; B(12 ; 0) ; C(15 ; 0)$.<br>Ta có,$F(6 ; 6)=480 ; F(12 ; 0)=360 ; F(15 ; 0)=450$.<br>Vậy để An thu được nhiều tiền nhất thì An cần làm 6 chiếc đèn hình ngôi sao và 6 chiếc hình con thỏ.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, x=0.4cm, y=0.4cm, font=\\footnotesize]\n\t\t\t\t\n\t\t\t\t\\def\\xmin{-2} \\def\\xmax{20}\n\t\t\t\t\\def\\ymin{-2} \\def\\ymax{15}\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\def\\fOne(#1){(30 - 2*#1)/3} \n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\def\\fTwo(#1){12 - #1}\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\draw[color=gray!20] (\\xmin,\\ymin) grid (\\xmax,\\ymax);\n\t\t\t\t\\draw[->, thick] (\\xmin,0) -- (\\xmax,0) node[below] {$x$};\n\t\t\t\t\\draw[->, thick] (0,\\ymin) -- (0,\\ymax) node[left] {$y$};\n\t\t\t\t\\node[below left] at (0,0) {$O$};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\begin{scope}\n\t\t\t\t\t\\clip (0,0) rectangle (\\xmax,\\ymax); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\fill[pattern=north east lines, pattern color=blue!20] \n\t\t\t\t\t(0, \\ymax) -- plot[domain=0:\\xmax] (\\x, {\\fOne(\\x)}) -- (\\xmax, \\ymax) -- cycle;\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\fill[pattern=north west lines, pattern color=red!20] \n\t\t\t\t\t(0,0) -- plot[domain=0:12] (\\x, {\\fTwo(\\x)}) -- (12,0) -- cycle;\n\t\t\t\t\\end{scope}\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\draw[thick, blue] plot[domain=-1:16] (\\x, {\\fOne(\\x)}) node[right] {$d_1$};\n\t\t\t\t\\draw[thick, red] plot[domain=-1:13] (\\x, {\\fTwo(\\x)}) node[above right] {$d_2$};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\fill (6,6) circle (2pt) node[above right] {$A(6,6)$};\n\t\t\t\t\\foreach \\x in {12,15} \\node[below] at (\\x,0) {\\x};\n\t\t\t\t\\foreach \\y in {10,12} \\node[left] at (0,\\y) {\\y};\n\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Trong không gian với hệ tọa độ $Oxyz$, cho điểm $H(3;2;1)$ và ba đường thẳng $d_1\\colon \\heva{&x=t_1\\\\&y=0\\\\&z=0}$, $d_2\\colon \\heva{&x=1\\\\&y=t_2\\\\&z=0}$, $d_3\\colon \\heva{&x=1\\\\&y=0\\\\&z=t_3}$. Gọi $(P)$ là mặt phẳng đi qua $H$ và cắt $d_1, d_2, d_3$ lần lượt tại $A, B, C$.", "cauHoi": [{"question": "Mệnh đề nào dưới đây là sai?", "choices": ["Các đường thẳng $d_1, d_2, d_3$ đôi một vuông góc với nhau", "Đường thẳng $d_1$ nằm trên $(Ox)$", "Khoảng cách từ điểm $K(1;0;0)$ đến điểm $H(3;2;1)$ bằng $3$", "Véc-tơ chỉ phương của đường thẳng $d_2$ là $\\vec{u}=(1;0;0)$"], "correctIndex": 3, "explain": "a) $d_1 \\parallel Ox, d_2 \\parallel Oy, d_3 \\parallel Oz$ và chúng đi qua các điểm tạo thành hệ trục tịnh tiến nên chúng đôi một vuông góc. Khẳng định a đúng.  <br>b) $d_1$ có $y=0, z=0$ nên $d_1$ chính là trục $Ox$. Khẳng định b đúng.  <br>c) $KH=\\sqrt{(3-1)^2+(2-0)^2+(1-0)^2}=\\sqrt{2^2+2^2+1^2}=3$. Khẳng định c đúng.  <br>d) VTCP của $d_2$ dựa trên hệ số của $t_2$ là $\\vec{u}=(0;1;0)$. Khẳng định d sai."}, {"question": "Tìm tọa độ điểm $C$ trên đường thẳng $d_3$ sao cho độ dài đoạn thẳng $HC$ ngắn nhất.", "choices": ["$C(1;0;0)$", "$C(1;0;2)$", "$C(1;0;1)$", "$C(1;0;3)$"], "correctIndex": 2, "explain": "Điểm $C\\in d_3 \\Rightarrow C(1;0;t_3)$.<br>Độ dài $HC=\\sqrt{(1-3)^2+(0-2)^2+(t_3-1)^2} = \\sqrt{4+4+(t_3-1)^2} = \\sqrt{8+(t_3-1)^2}$.<br>Biểu thức $HC$ đạt giá trị nhỏ nhất khi $(t_3-1)^2=0 \\Leftrightarrow t_3=1$.<br>Vậy tọa độ điểm $C(1;0;1)$"}, {"question": "Phương trình mặt phẳng $(P)$ có dạng $ax+by+z+c=0$. Tính $S=a+b+c$ biết $H$ là trực tâm tam giác $ABC$.", "choices": ["$S=-11$", "$S=11$", "$S=-7$", "$S=7$"], "correctIndex": 2, "explain": "Gọi $A(a;0;0)$, $B(1;b;0)$, $C(1;0;c)$.<br>Ta có $\\vec{AB}=(1-a;b;0)$, $\\vec{BC}=(0;-b;c)$, $\\vec{CH}=(2;2;1-c)$, $\\vec{AH}=(3-a;2;1)$.<br>$H$ là trực tâm tam giác $ABC$ khi và chỉ khi:  $\\heva{&\\vec{AB}\\cdot\\vec{CH}=0\\\\&\\vec{BC}\\cdot\\vec{AH}=0\\\\&[\\vec{AB},\\vec{BC}]\\cdot\\vec{CH}=0} \\Leftrightarrow \\heva{&2(1-a)+2b=0\\\\&-2b+c=0\\\\&2bc+2c(a-1)+(1-c)b(a-1)=0} \\Leftrightarrow \\heva{&a=b+1\\\\&c=2b\\\\&4b^2+4b^2+b^2(1-2b)=0.}$<br>$\\Leftrightarrow \\heva{&a=b+1\\\\&c=2b\\\\&9b^2-2b^3=0.}$  Vì $b\\neq 0$ nên $b=\\dfrac{9}{2} \\Rightarrow a=\\dfrac{11}{2}$, $c=9$.<br>Mặt phẳng $(ABC)$ đi qua $C(1;0;9)$ và có VTPT $\\vec{n}=(bc;ac-c;ab-b)=(2;2;1)$.<br>Phương trình mặt phẳng $(P)\\colon 2x+2y+z-11=0$.<br>Suy ra $a=2, b=2, c=-11$. Vậy $a+b+c=2+2-11=-7$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn ngẫu nhiên $3$ số $a$, $b$, $c$ trong tập hợp $S=\\{1;2;\\dots;26\\}$. Biết xác suất để $3$ số chọn ra thỏa mãn $a^2+b^2+c^2$ chia hết cho $5$ bằng $\\dfrac{m}{n}$ với $m$, $n\\in \\mathbb{N}^*$ và $\\dfrac{m}{n}$ là phân số tối giản. Tính giá trị biểu thức $T=m+n$.", "choices": ["$T=79$", "$T=243$", "$T=49$", "$T=126$"], "correctIndex": 0, "explain": "Số phần tử của không gian mẫu là $n(\\Omega)=C_{26}^3=2600$.<br>Gọi $A$ là tập hợp các phần tử thuộc $S$ mà chia hết cho $\\overline{5}, A$ có $\\overline{5}$ phần tử.<br>$B$ là tập hợp các phần tử thuộc $S$ mà chia cho 5 dư 1 hoặc dư $4, B$ có 11 phần tử.<br>$C$ là tập hợp các phần tử thuộc $S$ mà chia cho 5 dư 2 hoặc dư $3, O$ có 10 phần tử.<br>Ta có nhận xét<br>Với $k \\in A$ thì $k^2$ chia hết cho 5 .<br>Với $k \\in B$ thì $k^2$ chia cho 5 dừ 1 .<br>Với $k \\in C$ thì $k^2$ chia cho 5 dư 4 .<br>Số phần tử của không gian mẫu là $C_{28}^8$.<br>Để chọn được 3 số thỏa mãn bài toán, ta có hai trường hợp<br>Trường hợp 1: 3 số được chọn đều thuộc $A$, có $C_6^8$ cách chọn.<br>Trường hợp 2: 3 số được chọn có mỗi số thuộc mỗi tập $A, B, C$, có $C_6^1 \\cdot C_{11}^1 \\cdot C_{10}^1$ cách chọn.<br>Suy ra số phần tử của biến cố là $C_{\\%}^8+C_{\\%}^1 \\cdot C_{10}^1 \\cdot C_{11}^1$.<br>Xác suất của biến cố là $\\dfrac{C_5^8+C_6^1 \\cdot C_{10}^1 \\cdot C_{11}^1}{C_{28}^8}=\\dfrac{14}{65}=\\dfrac{m}{n}$."}]}, {"noiDungChung": "Một đêm nhạc Acoustic có đúng $5$ tiết mục biểu diễn gồm: Guitar solo, Saxophone, Piano, Trống và Violin. Thứ tự các tiết mục từ số $1$ đến số $5$ phải tuân thủ các quy định ban tổ chức đề ra như sau:<br>a) Tiết mục Piano phải được biểu diễn trước tiết mục Saxophone.  <br>b) Tiết mục Trống và tiết mục Violin phải được biểu diễn liên tiếp nhau (theo thứ tự nào cũng được).  <br>c) Tiết mục Guitar solo không được là tiết mục mở màn ($1$) và cũng không được là tiết mục kết thúc ($5$).  <br>d) Tiết mục ở vị trí thứ $2$ là Saxophone.", "cauHoi": [{"question": "Tiết mục nào buộc phải biểu diễn ở vị trí đầu tiên ($1$)?", "choices": ["Guitar solo", "Piano", "Trống", "Violin"], "correctIndex": 1, "explain": "Gọi thứ tự biểu diễn là $1, 2, 3, 4, 5$.  Dựa trên các ràng buộc:<br>a) Theo quy định, Piano phải diễn trước Saxophone.  <br>b) Mà Saxophone đã cố định ở vị trí thứ $2$.  <br>c) Vị trí duy nhất còn lại trước vị trí số $2$ là vị trí số $1$, do đó Piano buộc phải diễn đầu tiên."}, {"question": "Nếu tiết mục Trống được biểu diễn ở vị trí thứ $3$, khẳng định nào sau đây ĐÚNG?", "choices": ["Guitar solo diễn ở vị trí $5$", "Violin diễn ở vị trí $5$", "Guitar solo diễn ở vị trí $4$", "Piano diễn ở vị trí $3$"], "correctIndex": 2, "explain": "Hiện tại ta có: Vị trí $1$: Piano, Vị trí $2$: Saxophone.<br>a) Nếu Trống diễn ở vị trí $3$, vì Trống và Violin phải liên tiếp nên Violin phải ở vị trí $4$ (do vị trí $2$ đã có Saxophone).  <br>b) Khi đó, vị trí $5$ còn lại sẽ dành cho Guitar solo.  <br>c) Tuy nhiên, quy định nêu rõ Guitar solo không được diễn ở vị trí $5$.  <br>d) Để thỏa mãn điều kiện Guitar solo không ở vị trí $5$, Guitar solo buộc phải diễn ở vị trí $3$ hoặc $4$.  <br>e) Nếu Guitar solo diễn ở vị trí $4$, cặp (Trống, Violin) sẽ bị tách ra ở vị trí $3$ và $5$ (không liên tiếp - Loại).  <br>f) Vậy trường hợp duy nhất thỏa mãn là Guitar solo diễn ở vị trí $3$, cặp (Trống, Violin) diễn ở vị trí $4$ và $5$."}, {"question": "Có bao nhiêu cách sắp xếp thứ tự các tiết mục khác nhau thỏa mãn tất cả các quy định trên?", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 1, "explain": "Cố định: Vị trí $1$: Piano, Vị trí $2$: Saxophone.  Còn lại $3$ vị trí $\\{3, 4, 5\\}$ cho các tiết mục $\\{Guitar\\ solo, Trống, Violin\\}$.  Ràng buộc: Guitar solo không ở vị trí $5$; Trống và Violin phải liên tiếp.<br>a) <b>Trường hợp 1:</b> Guitar solo diễn ở vị trí $3$. Vị trí $4, 5$ sẽ dành cho (Trống, Violin) hoặc (Violin, Trống). Cả hai cách này đều thỏa mãn vì cặp này vẫn liên tiếp và Guitar solo không phạm quy ở vị trí $5$. $\\Rightarrow$ Có $2$ cách.  <br>b) <b>Trường hợp 2:</b> Guitar solo diễn ở vị trí $4$. Vị trí $3$ và $5$ dành cho Trống và Violin. Tuy nhiên hai vị trí này không liên tiếp nhau $\\Rightarrow$ Không thỏa mãn quy định.<br>Vậy tổng cộng có $2$ cách sắp xếp thỏa mãn."}]}, {"noiDungChung": "Ba thực khách gồm chú Hùng, anh Mạnh và bạn Linh đang thưởng thức bữa tối tại một khu phố ẩm thực. Mỗi người chọn một món ăn khác nhau là: Phở, Bún chả và Bánh mì. Mỗi người cũng uống một loại nước giải khát khác nhau là: Trà đá, Nước mía và Sữa đậu. Biết rằng:<br>a) Bạn Linh không ăn Bún chả và không uống Trà đá.  <br>b) Người ăn Phở thì uống Nước mía.  <br>c) Anh Mạnh chọn ăn Bánh mì.  <br>d) Chú Hùng không uống Sữa đậu.", "cauHoi": [{"question": "Khẳng định nào sau đây về món ăn và thức uống của thực khách là ĐÚNG?", "choices": ["Chú Hùng ăn Bún chả và uống Nước mía", "Bạn Linh ăn Phở và uống Sữa đậu", "Bạn Linh ăn Phở và uống Nước mía", "Anh Mạnh ăn Bánh mì và uống Nước mía"], "correctIndex": 2, "explain": "Ta phân tích các mối liên hệ dựa trên dữ kiện bài toán:<br>a) Vì anh Mạnh ăn Bánh mì và người ăn Phở uống Nước mía nên anh Mạnh không uống Nước mía.  <br>b) Bạn Linh không ăn Bún chả và anh Mạnh đã ăn Bánh mì nên bạn Linh buộc phải ăn Phở.  <br>c) Do bạn Linh ăn Phở nên theo dữ kiện (2), bạn Linh uống Nước mía.<br>Vậy cặp tương ứng đúng cho bạn Linh là (Phở - Nước mía)."}, {"question": "Chú Hùng uống loại nước giải khát nào?", "choices": ["Nước mía", "Sữa đậu", "Trà đá", "Không thể xác định"], "correctIndex": 2, "explain": "Từ kết quả phân tích trước đó:<br>a) Bạn Linh đã uống Nước mía.  <br>b) Chú Hùng không uống Sữa đậu và bạn Linh đã uống Nước mía nên chú Hùng buộc phải uống Trà đá.<br>Vậy chú Hùng uống Trà đá."}, {"question": "Thông tin nào sau đây về anh Mạnh là ĐÚNG?", "choices": ["Anh Mạnh ăn Bánh mì và uống Trà đá", "Anh Mạnh ăn Bún chả và uống Sữa đậu", "Anh Mạnh ăn Bánh mì và uống Sữa đậu", "Anh Mạnh ăn Phở và uống Nước mía"], "correctIndex": 2, "explain": "Tổng hợp lại toàn bộ dữ liệu đã suy luận:<br>a) Bạn Linh: Ăn Phở - uống Nước mía.  <br>b) Chú Hùng: Uống Trà đá, do đó chú Hùng ăn Bún chả (món còn lại).  <br>c) Anh Mạnh: Ăn Bánh mì, do đó anh Mạnh uống Sữa đậu (loại nước còn lại).<br>Vậy anh Mạnh ăn Bánh mì và uống Sữa đậu."}]}, {"noiDungChung": "Một cuộc khảo sát về phương tiện di chuyển chính đến trường của $400$ học sinh tại một trường THPT được ghi lại qua biểu đồ tròn dưới đây. Cơ cấu phương tiện gồm: Xe đạp ($35\\%$), Xe máy điện ($30\\%$), Xe buýt ($20\\%$), và Đi bộ ($15\\%$).<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.7, font=\\footnotesize]\n\t\t\t\\def\\radius{2.5}\n\t\t\t\\fill[cyan!60] (0,0) -- (0:\\radius) arc (0:126:\\radius) -- cycle;\n\t\t\t\\fill[orange!70] (0,0) -- (126:\\radius) arc (126:234:\\radius) -- cycle;\n\t\t\t\\fill[green!60!black] (0,0) -- (234:\\radius) arc (234:306:\\radius) -- cycle;\n\t\t\t\\fill[magenta!50] (0,0) -- (306:\\radius) arc (306:360:\\radius) -- cycle;\n\t\t\t\\node at (63:1.6) {$35\\%$};\n\t\t\t\\node at (180:1.6) {$30\\%$};\n\t\t\t\\node at (270:1.6) {$20\\%$};\n\t\t\t\\node at (333:1.6) {$15\\%$};\n\t\t\t\\node[right] at (3,1) {\\fbox{\\phantom{m}} Xe đạp};\n\t\t\t\\node[right] at (3,0.3) {\\fbox{\\phantom{m}} Xe máy điện};\n\t\t\t\\node[right] at (3,-0.4) {\\fbox{\\phantom{m}} Xe buýt};\n\t\t\t\\node[right] at (3,-1.1) {\\fbox{\\phantom{m}} Đi bộ};\n\t\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Số lượng học sinh chọn phương tiện di chuyển là Xe đạp nhiều hơn số lượng học sinh Đi bộ là bao nhiêu người?", "choices": ["$60$ người", "$80$ người", "$140$ người", "$20$ người"], "correctIndex": 1, "explain": "Số học sinh đi xe đạp là: $400 \\cdot 35\\% = 140$ (học sinh).<br>Số học sinh đi bộ là: $400 \\cdot 15\\% = 60$ (học sinh).<br>Sự chênh lệch là: $140-60=80$ (người)."}, {"question": "Nhà trường dự kiến hỗ trợ vé xe buýt cho tất cả học sinh đang đi xe buýt và $50\\%$ số học sinh đang đi bộ. Tổng số học sinh nhận được hỗ trợ là bao nhiêu?", "choices": ["$80$ người", "$100$ người", "$110$ người", "$140$ người"], "correctIndex": 2, "explain": "Số học sinh đi xe buýt là: $400 \\cdot 20\\% = 80$ (học sinh).<br>$50\\%$ số học sinh đi bộ là: $400 \\cdot 15\\% \\cdot 50\\% = 60 \\cdot 0{,}5 = 30$ (học sinh).<br>Tổng số học sinh được hỗ trợ: $80+30=110$ (người)."}, {"question": "Giả sử vào năm học tới, số học sinh đi Xe máy điện giảm $20\\%$ (so với số lượng hiện tại) và những học sinh này chuyển sang đi Xe đạp. Khi đó, tỉ lệ học sinh đi Xe đạp trong tổng số học sinh sẽ là bao nhiêu?", "choices": ["$36{,}00\\%$", "$35{,}00\\%$", "$41{,}00\\%$", "$42{,}00\\%$"], "correctIndex": 2, "explain": "Số lượng học sinh đi xe máy điện hiện tại: $400 \\cdot 30\\% = 120$ (người).<br>Số học sinh giảm đi ở nhóm xe máy điện: $120 \\cdot 20\\% = 24$ (người).<br>Số học sinh đi xe đạp mới: $140+24 = 164$ (người).<br>Tỉ lệ xe đạp mới: $\\dfrac{164}{400} \\cdot 100\\% = 41\\%$."}]}, {"noiDungChung": "Khảo sát năng suất lúa (tạ/ha) của một khu vực thu được mẫu số liệu ghép nhóm sau:<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Năng suất</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[45; 50)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[50; 55)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[55; 60)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[60; 65)$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Số hợp tác xã</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$10$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$15$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$10$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$5$</td></tr></table>", "cauHoi": [{"question": "Khoảng biến thiên của mẫu số liệu ghép nhóm trên là bao nhiêu?", "choices": ["$10$ tạ/ha", "$15$ tạ/ha", "$20$ tạ/ha", "$25$ tạ/ha"], "correctIndex": 2, "explain": "Khoảng biến thiên của mẫu số liệu ghép nhóm là hiệu số giữa đầu mút phải của nhóm cuối cùng và đầu mút trái của nhóm đầu tiên.<br>Ta có $R=65-45=20$ tạ/ha."}, {"question": "Năng suất lúa trung bình của các hợp tác xã trong khu vực này là bao nhiêu?", "choices": ["$52{,}50$ tạ/ha", "$53{,}75$ tạ/ha", "$54{,}25$ tạ/ha", "$55{,}00$ tạ/ha"], "correctIndex": 1, "explain": "Xác định giá trị đại diện $x_i$ của các nhóm: $47{,}5$; $52{,}5$; $57{,}5$; $62{,}5$.<br>Tổng số hợp tác xã là $n=10+15+10+5=40$.<br>Năng suất trung bình là:  $\\bar{x}=\\dfrac{10 \\cdot 47{,}5+15 \\cdot 52{,}5+10 \\cdot 57{,}5+5 \\cdot 62{,}5}{40}=\\dfrac{475+787{,}5+575+312{,}5}{40}=\\dfrac{2150}{40}=53{,}75$ tạ/ha."}, {"question": "Độ lệch chuẩn $s$ của mẫu số liệu trên bằng bao nhiêu (làm tròn kết quả đến hai chữ số thập phân)?", "choices": ["$4{,}21$", "$5{,}15$", "$4{,}84$", "$23{,}44$"], "correctIndex": 2, "explain": "Tính phương sai $s^2$:  $s^2=\\dfrac{1}{40}\\left(10 \\cdot 47{,}5^2+15 \\cdot 52{,}5^2+10 \\cdot 57{,}5^2+5 \\cdot 62{,}5^2\\right)-53{,}75^2$<br>$s^2=\\dfrac{22562{,}5+41343{,}75+33062{,}5+19531{,}25}{40}-2889{,}0625$<br>$s^2=\\dfrac{116500}{40}-2889{,}0625=2912{,}5-2889{,}0625=23{,}4375$.<br>Độ lệch chuẩn là $s=\\sqrt{23{,}4375} \\approx 4{,}84$."}]}]}, {"id": "extra-2", "ten": "Đề chuẩn cấu trúc minh họa số 8", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Gọi $S_n$ là tổng $n$ số hạng đầu tiên của cấp số cộng $(a_n)$. Biết $S_6=S_9$, tính tỉ số $\\dfrac{a_3}{a_5}$.", "choices": ["$\\dfrac{9}{5}$", "$\\dfrac{5}{9}$", "$\\dfrac{5}{3}$", "$\\dfrac{3}{5}$"], "correctIndex": 2, "explain": "Gọi $d$ là công sai của cấp số cộng. Ta có công thức tổng $n$ số hạng đầu tiên:  $S_n = \\dfrac{n[2a_1+(n-1)d]}{2}$.<br>Theo giả thiết $S_6=S_9$, ta có:  $$\\dfrac{6(2a_1+5d)}{2} = \\dfrac{9(2a_1+8d)}{2} \\Leftrightarrow 2(2a_1+5d) = 3(2a_1+8d)$$  $$\\Leftrightarrow 4a_1+10d = 6a_1+24d \\Leftrightarrow 2a_1 = -14d \\Leftrightarrow a_1 = -7d.$$  Ta biểu diễn $a_3$ và $a_5$ theo $a_1$ và $d$:<br>a) $a_3 = a_1+2d = -7d+2d = -5d$.  <br>b) $a_5 = a_1+4d = -7d+4d = -3d$.<br>Tỉ số cần tìm là:  $$\\dfrac{a_3}{a_5} = \\dfrac{-5d}{-3d} = \\dfrac{5}{3}.$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Anh Bình mua một chiếc điện thoại giá 9 triệu đồng theo hình thức trả trước $30\\%$ và phần còn lại trả góp hàng tháng với lãi suất $0,9\\%$/tháng. Anh Bình bắt đầu trả nợ sau đúng một tháng kể từ ngày mua, số tiền trả mỗi lần là như nhau. Để trả hết nợ sau đúng 12 tháng thì mỗi tháng anh Bình phải trả số tiền gần nhất với giá trị nào sau đây?", "choices": ["795.000 đồng", "604.000 đồng", "880.000 đồng", "556.000 đồng"], "correctIndex": 3, "explain": "Anh Bình trả trước $30 \\%$ giá trị điện thoại, vậy số tiền trả trưởc là:<br>$$  9.000 .000 \\times 30 \\%=2.700 .000 \\text { (đồng) }  $$<br>Số tiền còn lại anh Bình nợ cửa hàng là:<br>$$  A=9.000 .000-2.700 .000=6.300 .000 \\text { (đồng) }  $$<br>Gọi $r$ là lăi suất hàng tháng $(r=0,9 \\%=0,009), n$ là số tháng trả nợ $(n=12)$.  Công thức tính số tiền trả góp đểu hàng tháng để hết nợ sau $n$ tháng (vởi lẩn trả đẩu tiên sau 1 tháng) là:<br>$$  m=\\dfrac{A \\cdot r \\cdot(1+r)^n}{(1+r)^n-1}  $$<br>Thay các giá trị vào:<br>$$  \\begin{gathered}  m=\\dfrac{6.300 .000 \\cdot 0,009 \\cdot(1,009)^{12}}{(1,009)^{12}-1} <br>m \\approx \\dfrac{56.700 \\cdot 1,1135}{1,1135-1} \\approx \\dfrac{63.135,45}{0,1135} \\approx 556.259  \\end{gathered}  $$<br>Làm tròn đển hàng ngàn đồng theo yêu cẩu để bài, ta được 556.000 đồng."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Trọng và Quốc chạy bộ trong một khuôn viên hình tam giác $ABC$ vuông cân tại $A$ ($AB=AC=a$). Từ đỉnh $A$, hai bạn cùng lúc bắt đầu chạy bộ dọc theo các cạnh của tam giác với vận tốc không đổi nhưng theo hai chiều ngược nhau:<br>a) Trọng chạy theo chiều: $A \\to B \\to C \\to A$.  <br>b) Quốc chạy theo chiều: $A \\to C \\to B \\to A$.<br>Biết rằng lần gặp nhau thứ nhất tại điểm $M$ trên cạnh $BC$ với $BM=600$ m. Lần gặp nhau thứ hai tại điểm $N$ trên cạnh $AB$ với $AN=200$ m. Tính chu vi khuôn viên đó (làm tròn đến hàng đơn vị).<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.8, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\\coordinate (A) at (0,3);\n\t\t\t\\coordinate (B) at (-3,0);\n\t\t\t\\coordinate (C) at (3,0);\n\t\t\t\\draw[blue, ultra thick] (A) -- (B) -- (C) -- cycle;\n\t\t\t\\coordinate (M) at ($(B)!0.42!(C)$);\n\t\t\t\\coordinate (N) at ($(A)!0.2!(B)$);\n\t\t\t\\foreach \\p in {A,B,C,M,N}\n\t\t\t\\filldraw[red] (\\p) circle (2pt);\n\t\t\t\\node[above=3pt] at (A) {$A$};\n\t\t\t\\node[left=3pt] at (B) {$B$};\n\t\t\t\\node[right=3pt] at (C) {$C$};\n\t\t\t\\node[below=3pt] at (M) {$M$};\n\t\t\t\\node[left=3pt] at (N) {$N$};\n\t\t\t\\node[above left] at ($(A)!0.5!(N)$) {$200\\text{m}$};\n\t\t\t\\node[below] at ($(B)!0.5!(M)$) {$600\\text{m}$};\n\t\t\t\\draw[shift={(A)},rotate=-135] (0.3,0) -- (0.3,0.3) -- (0,0.3);\n\t\t\\end{tikzpicture}</script></div>", "choices": ["$2414$ m", "$3414$ m", "$3215$ m", "$4000$ m"], "correctIndex": 0, "explain": "Gọi $P$ là chu vi tam giác $ABC$. Vì vận tốc mỗi người không đổi nên tỉ số quãng đường đi được của Trọng ($s_1$) và tổng quãng đường của hai người ($S$) luôn không đổi.<br>Lần gặp thứ nhất: Trọng đi được $s_1 = AB + BM = a + 600$. Tổng quãng đường hai người đi được đúng bằng một chu vi $S = P$.<br>Lần gặp thứ hai: Hai người chạy ngược chiều nhau trên chu vi tam giác, nên lần gặp thứ hai xảy ra khi tổng quãng đường hai người đi được là $S' = 2P$.<br>Quãng đường Trọng đi được khi đó là $s_1' = P + AN = P + 200$.<br>Do tỉ số vận tốc không đổi, ta có:  $$\\dfrac{s_1}{S} = \\dfrac{s_1'}{S'} \\Leftrightarrow \\dfrac{a+600}{P} = \\dfrac{P+200}{2P} \\Leftrightarrow a+600 = \\dfrac{P+200}{2}.$$  Thay $P = 2a + a\\sqrt{2}$ vào phương trình, ta được:  $$2a + 1200 = 2a + a\\sqrt{2} + 200 \\Leftrightarrow a\\sqrt{2} = 1000 \\Leftrightarrow a = 500\\sqrt{2}.$$  Chu vi của khuôn viên là:  $$P = 2a + a\\sqrt{2} = 1000\\sqrt{2} + 1000 \\approx 2414 \\text{ m.}$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Trên lưới tọa độ $Oxy$, một con kiến di chuyển từ điểm $A(0;0)$ đến điểm $B(5;3)$ bằng cách chỉ di chuyển sang phải hoặc lên trên. Tính số đường đi ngắn nhất từ $A$ đến $B$ sao cho bắt buộc phải đi qua điểm $M(2;1)$.", "choices": ["$120$", "$60$", "$30$", "$45$"], "correctIndex": 2, "explain": "Số cách đi từ $A(0;0)$ đến $M(2;1)$ là $C_{2+1}^1 = C_3^1 = 3$ cách.<br>Số cách đi từ $M(2;1)$ đến $B(5;3)$ là đi thêm $5-2=3$ đơn vị sang phải và $3-1=2$ đơn vị lên trên. Số cách là $C_{3+2}^2 = C_5^2 = 10$ cách.<br>Theo quy tắc nhân, tổng số cách đi là $3\\cdot 10 = 30$ cách."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho phương trình $x^{\\log_2(ax^3)-8}=2021$ với $a$ là số thực dương. Biết tích các nghiệm của phương trình là $32$. Tìm giá trị của $a$.", "choices": ["$a=2$", "$a=-7$", "$a=-8$", "$a=16$"], "correctIndex": 1, "explain": "Điều kiện: $x>0$. Lấy logarit cơ số $2$ hai vế của phương trình $x^{\\log_2(ax^3)-8}=2021$, ta được:  $$\\log_2\\left(x^{\\log_2(ax^3)-8}\\right)=\\log_2 2021 \\Leftrightarrow \\left(\\log_2 a+\\log_2 x^3-8\\right)\\cdot\\log_2 x=\\log_2 2021$$  $$\\Leftrightarrow \\left(3\\log_2 x+\\log_2 a-8\\right)\\cdot\\log_2 x-\\log_2 2021=0$$  Đặt $t=\\log_2 x$, phương trình trở thành:  $$3t^2+(\\log_2 a-8)t-\\log_2 2021=0 \\quad (*)$$  Giả sử phương trình $(*)$ có hai nghiệm $t_1$, $t_2$. Khi đó các nghiệm của phương trình ban đầu là $x_1=2^{t_1}$ và $x_2=2^{t_2}$.<br>Tích các nghiệm của phương trình là: $x_1x_2=2^{t_1}\\cdot 2^{t_2}=2^{t_1+t_2}=32=2^5$.<br>Suy ra $t_1+t_2=5$.<br>Theo định lý Vi-ét cho phương trình $(*)$, ta có:  $$t_1+t_2=-\\dfrac{\\log_2 a-8}{3}$$  $$\\Rightarrow -\\dfrac{\\log_2 a-8}{3}=5 \\Leftrightarrow \\log_2 a-8=-15 \\Leftrightarrow \\log_2 a=-7.$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tìm số nghiệm nguyên dương nhỏ hơn $10$ của bất phương trình $3^{x+1}-2^{2x+1}-12^{\\tfrac{x}{2}}<0$.", "choices": ["$5$", "$7$", "$9$", "$8$"], "correctIndex": 2, "explain": "Bất phương trình đã cho tương đương với:  $$3\\cdot 3^x-2\\cdot 4^x-\\left(\\sqrt{12}\\right)^x < 0 \\Leftrightarrow 3\\cdot 3^x-2\\cdot 4^x-\\left(2\\sqrt{3}\\right)^x < 0$$  Chia cả hai vế cho $4^x > 0$, ta được:  $$3\\cdot \\left(\\dfrac{3}{4}\\right)^x - \\left(\\dfrac{\\sqrt{3}}{2}\\right)^x - 2 < 0$$  Đặt $t = \\left(\\dfrac{\\sqrt{3}}{2}\\right)^x$ ($t>0$). Khi đó $\\left(\\dfrac{3}{4}\\right)^x = t^2$. Bất phương trình trở thành:  $$3t^2-t-2 < 0 \\Leftrightarrow -\\dfrac{2}{3} < t < 1$$  Kết hợp điều kiện $t>0$, ta có $0 < t < 1$.  $$\\Rightarrow \\left(\\dfrac{\\sqrt{3}}{2}\\right)^x < 1 \\Leftrightarrow \\left(\\dfrac{\\sqrt{3}}{2}\\right)^x < \\left(\\dfrac{\\sqrt{3}}{2}\\right)^0$$  Vì cơ số $\\dfrac{\\sqrt{3}}{2} \\approx 0{,}866 < 1$ nên bất phương trình đổi chiều: $x > 0$.<br>Kết hợp điều kiện $x$ là số nguyên dương nhỏ hơn $10$, ta có $x \\in \\{1, 2, 3, 4, 5, 6, 7, 8, 9\\}$.<br>Vậy có $9$ giá trị thỏa mãn."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho các số thực $a$, $b>0$; $a$, $b\\neq 1$ thỏa mãn $\\log_a^2 b-8\\log_b(a\\sqrt[3]{b})=-\\dfrac{8}{3}$. Tính giá trị của biểu thức $P=\\log_a(a\\sqrt[3]{ab})+2019$.", "choices": ["$P=2021$", "$P=2023$", "$P=2019$", "$P=2025$"], "correctIndex": 0, "explain": "Biến đổi giả thiết:  $$\\log_a^2 b-8\\log_b(a\\sqrt[3]{b})=-\\dfrac{8}{3} \\Leftrightarrow \\log_a^2 b-8\\left(\\log_b a+\\log_b b^{\\frac{1}{3}}\\right)+\\dfrac{8}{3}=0$$  $$\\Leftrightarrow \\log_a^2 b-8\\log_b a-8\\cdot\\dfrac{1}{3}+\\dfrac{8}{3}=0 \\Leftrightarrow \\log_a^2 b-\\dfrac{8}{\\log_a b}=0.$$  Đặt $t=\\log_a b$ ($t\\neq 0$), phương trình trở thành:  $$t^2-\\dfrac{8}{t}=0 \\Leftrightarrow t^3=8 \\Leftrightarrow t=2.$$  Suy ra $\\log_a b=2$.<br>Ta có biểu thức $P$:  $$P = \\log_a\\left(a\\cdot a^{\\frac{1}{3}}\\cdot b^{\\frac{1}{3}}\\right)+2019 = \\log_a\\left(a^{\\frac{4}{3}}\\cdot b^{\\frac{1}{3}}\\right)+2019$$  $$P = \\dfrac{4}{3}+\\dfrac{1}{3}\\log_a b+2019.$$  Thay $\\log_a b=2$ vào ta được:  $$P = \\dfrac{4}{3}+\\dfrac{1}{3}\\cdot 2+2019 = \\dfrac{4}{3}+\\dfrac{2}{3}+2019 = 2+2019 = 2021.$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biết $\\lim\\limits_{x\\to -\\infty}\\dfrac{ax-\\sqrt{4x^2-x+1}}{a^2x-1}=\\dfrac{2}{3}$ với $a-\\dfrac{m+\\sqrt{57}}{n}>0$ và $m$, $n$ là các số nguyên dương. Khi đó giá trị của biểu thức $S=m+n$ là", "choices": ["$5$", "$6$", "$7$", "$8$"], "correctIndex": 2, "explain": "Ta có:  $$L=\\lim\\limits_{x\\to -\\infty}\\dfrac{ax-\\sqrt{4x^2-x+1}}{a^2x-1}=\\lim\\limits_{x\\to -\\infty}\\dfrac{ax-|x|\\sqrt{4-\\dfrac{1}{x}+\\dfrac{1}{x^2}}}{x\\left(a^2-\\dfrac{1}{x}\\right)}$$  Vì $x\\to -\\infty$ nên $|x|=-x$, do đó:  $$L=\\lim\\limits_{x\\to -\\infty}\\dfrac{ax+x\\sqrt{4-\\dfrac{1}{x}+\\dfrac{1}{x^2}}}{x\\left(a^2-\\dfrac{1}{x}\\right)}=\\lim\\limits_{x\\to -\\infty}\\dfrac{a+\\sqrt{4-\\dfrac{1}{x}+\\dfrac{1}{x^2}}}{a^2-\\dfrac{1}{x}}=\\dfrac{a+2}{a^2}$$  Theo giả thiết, ta có:  $$\\dfrac{a+2}{a^2}=\\dfrac{2}{3}\\Leftrightarrow 2a^2-3a-6=0\\Leftrightarrow\\hoac{&a=\\dfrac{3+\\sqrt{57}}{4}<br>&a=\\dfrac{3-\\sqrt{57}}{4}}$$  Theo điều kiện $a-\\dfrac{m+\\sqrt{57}}{n}>0$ và $m$, $n$ là số nguyên dương, ta suy ra:  $a=\\dfrac{3+\\sqrt{57}}{4}\\Rightarrow m=3$, $n=4$.<br>Vậy $S=m+n=3+4=7$."}]}, {"noiDungChung": "Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình thoi cạnh $a$, $\\widehat{ABC}=60^{\\circ}$, mặt bên $SAB$ là tam giác đều và nằm trong mặt phẳng vuông góc với mặt phẳng đáy. Gọi $H$ là trung điểm của $AB$.", "cauHoi": [{"question": "Tính thể tích $V$ của khối chóp $S.ABCD$ theo $a$.", "choices": ["$V=\\dfrac{a^3}{4}$", "$V=\\dfrac{a^3\\sqrt{3}}{6}$", "$V=\\dfrac{a^3}{2}$", "$V=\\dfrac{a^3\\sqrt{3}}{4}$"], "correctIndex": 0, "explain": "Diện tích đáy $S_{ABCD}=2S_{ABC}=2\\cdot\\dfrac{a^2\\sqrt{3}}{4}=\\dfrac{a^2\\sqrt{3}}{2}$.<br>Vì $(SAB)\\perp(ABCD)$ và $(SAB)\\cap(ABCD)=AB$, tam giác $SAB$ đều có $SH\\perp AB$ nên $SH\\perp(ABCD)$.<br>Tam giác $SAB$ đều cạnh $a$ nên $SH=\\dfrac{a\\sqrt{3}}{2}$.<br>Thể tích khối chóp $V=\\dfrac{1}{3}S_{ABCD}\\cdot SH=\\dfrac{1}{3}\\cdot\\dfrac{a^2\\sqrt{3}}{2}\\cdot\\dfrac{a\\sqrt{3}}{2}=\\dfrac{a^3}{4}$<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1.2, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (A) at (0,0);\n\t\t\t\t\t\\coordinate (B) at (-1.5,-1.5);\n\t\t\t\t\t\\coordinate (C) at (2,-1.5);\n\t\t\t\t\t\\coordinate (D) at ($(A)+(C)-(B)$); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (H) at ($(A)!0.5!(B)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (S) at ($(H)+(0,3.5)$); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed, thin] (S)--(A) (A)--(B) (A)--(D) (S)--(H) (B)--(D) (A)--(C);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick] (S)--(B) (S)--(C) (S)--(D) (B)--(C) (C)--(D);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed] ($(H)+(0,0.2)$)-|($(H)+(0.2,0)$); \n\t\t\t\t\t\n\t\t\t\t\t\\draw (H) ++(0,0.2) -- ++(0.2,0) -- ++(0,-0.2);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\foreach \\p in {S,A,B,C,D,H}\n\t\t\t\t\t\\fill[red] (\\p) circle (1.5pt);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\node[above] at (S) {$S$};\n\t\t\t\t\t\\node[below] at (B) {$B$};\n\t\t\t\t\t\\node[below] at (C) {$C$};\n\t\t\t\t\t\\node[right] at (D) {$D$};\n\t\t\t\t\t\\node[above left] at (A) {$A$};\n\t\t\t\t\t\\node[left] at (H) {$H$};\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw (B) ++(0:0.4) arc (0:45:0.4); \n\t\t\t\t\t\\node at ($(B)+(0.6,0.3)$) {$60^\\circ$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Tính khoảng cách $d$ từ điểm $D$ đến mặt phẳng $(SBC)$.", "choices": ["$d=\\dfrac{a\\sqrt{21}}{7}$", "$d=\\dfrac{a\\sqrt{3}}{2}$", "$d=\\dfrac{3a}{2\\sqrt{7}}$", "$d=\\dfrac{a\\sqrt{3}}{4}$"], "correctIndex": 2, "explain": "Ta có $AD\\parallel BC\\Rightarrow AD\\parallel(SBC)\\Rightarrow d(D,(SBC))=d(A,(SBC))$.<br>Vì $H$ là trung điểm $AB$ nên $d(A,(SBC))=2d(H,(SBC))$.<br>Kẻ $HK\\perp BC$ tại $K$, kẻ $HI\\perp SK$ tại $I$. Khi đó $d(H,(SBC))=HI$.<br>Trong $\\triangle HBK$ vuông tại $K$: $HK=HB\\cdot\\sin 60^{\\circ}=\\dfrac{a\\sqrt{3}}{4}$.<br>Trong $\\triangle SHK$ vuông tại $H$: $\\dfrac{1}{HI^2}=\\dfrac{1}{SH^2}+\\dfrac{1}{HK^2}=\\dfrac{1}{\\left(\\dfrac{a\\sqrt{3}}{2}\\right)^2}+\\dfrac{1}{\\left(\\dfrac{a\\sqrt{3}}{4}\\right)^2}=\\dfrac{20}{3a^2}\\Rightarrow HI=\\dfrac{a\\sqrt{3}}{2\\sqrt{5}}$.<br>Sử dụng phương pháp thể tích từ câu trên: $V_{S.HBC}=\\dfrac{1}{4}V_{S.ABCD}=\\dfrac{a^3}{16}$.<br>Diện tích $\\triangle SBC$ có $SB=a$, $BC=a$, $SC=\\sqrt{SH^2+HC^2}=\\dfrac{a\\sqrt{6}}{2}$ (với $HC = \\dfrac{a\\sqrt{3}}{2}$).<br>$S_{SBC}=\\dfrac{a^2\\sqrt{7}}{4}$.<br>$d(H,(SBC))=\\dfrac{3V_{S.HBC}}{S_{SBC}}=\\dfrac{3a}{4\\sqrt{7}}$.<br>Vậy $d(D,(SBC))=2\\cdot\\dfrac{3a}{4\\sqrt{7}}=\\dfrac{3a}{2\\sqrt{7}}$"}, {"question": "Gọi $\\alpha$ là số đo góc nhị diện $[A, SC, B]$. Tính $\\cos\\alpha$.", "choices": ["$\\cos\\alpha=\\dfrac{2}{7}$", "$\\cos\\alpha=\\dfrac{3}{7}$", "$\\cos\\alpha=\\dfrac{\\sqrt{3}}{7}$", "$\\cos\\alpha=\\dfrac{4}{7}$"], "correctIndex": 1, "explain": "Gọi $V$ là thể tích khối chóp $S.ABC$, ta có $V_{S.ABC} = \\dfrac{1}{2}V_{S.ABCD} = \\dfrac{a^3}{8}$.<br>Mặt khác, thể tích khối tứ diện $S.ABC$ tính theo công thức nhị diện: $V_{S.ABC} = \\dfrac{2 S_{SAC} \\cdot S_{SBC} \\cdot \\sin\\alpha}{3 SC}$.<br>Xét các tam giác:<br>+ $\\triangle SBC$ có $SB=a, BC=a, SC=\\dfrac{a\\sqrt{6}}{2} \\Rightarrow S_{SBC} = \\dfrac{a^2\\sqrt{7}}{4}$.<br>+ $\\triangle SAC$ có $SA=a, AC=a, SC=\\dfrac{a\\sqrt{6}}{2} \\Rightarrow S_{SAC} = \\dfrac{a^2\\sqrt{7}}{4}$.<br>Thay vào công thức: $\\dfrac{a^3}{8} = \\dfrac{2 \\cdot \\dfrac{a^2\\sqrt{7}}{4} \\cdot \\dfrac{a^2\\sqrt{7}}{4} \\cdot \\sin\\alpha}{3 \\cdot \\dfrac{a\\sqrt{6}}{2}} \\Rightarrow \\sin\\alpha = \\dfrac{2\\sqrt{10}}{7}$.<br>Suy ra $\\cos^2\\alpha = 1 - \\sin^2\\alpha = 1 - \\dfrac{40}{49} = \\dfrac{9}{49} \\Rightarrow \\cos\\alpha = \\dfrac{3}{7}$."}]}, {"noiDungChung": "Một dây chuyền sản xuất linh kiện điện tử có tỉ lệ sản phẩm lỗi là $0{,}5\\%$. Để kiểm tra chất lượng, người ta dùng một thiết bị cảm biến tự động. Thiết bị này có khả năng phát hiện đúng $98\\%$ sản phẩm lỗi. Tuy nhiên, đối với các sản phẩm không lỗi, thiết bị vẫn đưa ra cảnh báo nhầm là có lỗi với tỉ lệ $4\\%$. Chọn ngẫu nhiên một linh kiện sau khi qua thiết bị cảm biến.", "cauHoi": [{"question": "Xác suất để một linh kiện được thiết bị đánh giá là \"Không lỗi\" là bao nhiêu?", "choices": ["$0{,}9452$", "$0{,}9553$", "$0{,}9600$", "$0{,}9504$"], "correctIndex": 1, "explain": "Gọi $A$ là biến cố \"Linh kiện bị lỗi\", suy ra $P(A) = 0{,}005$ và $P(\\overline{A}) = 0{,}995$.<br>Gọi $B$ là biến cố \"Thiết bị cảnh báo có lỗi\".<br>Theo giả thiết: $P(B|A) = 0{,}98 \\Rightarrow P(\\overline{B}|A) = 0{,}02$ (lỗi nhưng không phát hiện).<br>$P(B|\\overline{A}) = 0{,}04 \\Rightarrow P(\\overline{B}|\\overline{A}) = 0{,}96$ (không lỗi và thiết bị báo đúng).<br>Xác suất để linh kiện được đánh giá \"Không lỗi\" là:  $$P(\\overline{B}) = P(A) \\cdot P(\\overline{B}|A) + P(\\overline{A}) \\cdot P(\\overline{B}|\\overline{A})$$  $$P(\\overline{B}) = 0{,}005 \\cdot 0{,}02 + 0{,}995 \\cdot 0{,}96 = 0{,}0001 + 0{,}9552 = 0{,}9553.$$"}, {"question": "Giả sử linh kiện được thiết bị đánh giá là \"Không lỗi\". Xác suất linh kiện này thực chất vẫn bị lỗi là bao nhiêu (làm tròn kết quả đến hàng phần mười nghìn)?", "choices": ["$0{,}0001$", "$0{,}0105$", "$0{,}0200$", "$0{,}0005$"], "correctIndex": 0, "explain": "Ta cần tính xác suất có điều kiện $P(A|\\overline{B})$.<br>Theo công thức Bayes, ta có:  $$P(A|\\overline{B}) = \\dfrac{P(A) \\cdot P(\\overline{B}|A)}{P(\\overline{B})} = \\dfrac{0{,}005 \\cdot 0{,}02}{0{,}9553} \\approx 0{,}0001046.$$  Làm tròn đến hàng phần mười nghìn, ta được kết quả là $0{,}0001$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một nhà máy sản xuất nhiên liệu sinh học bằng cách pha hai nguyên liệu là chất $A$ và chất $B$ với nhau. Hiện tại, trong kho có $135$ lít chất $A$ và $615$ lít chất $B$. Để tạo ra nhiên liệu loại $I$ thì tỉ lệ chất $A$ và chất $B$ là $1:9$. Để tạo ra nhiên liệu loại $II$ thì tỉ lệ chất $A$ và chất $B$ là $1:3$. Nếu sử dụng hết chất $A$ và chất $B$ thì có thể sản xuất được $a$ lít nhiên liệu loại $I$ và $b$ lít nhiên liệu loại $II$. Tính chênh lệch giữa $a$ và $b$.", "choices": ["$100$", "$150$", "$200$", "$230$"], "correctIndex": 1, "explain": "Gọi $x$ là số lít nhiên liệu loại $I$ và $y$ là số lít nhiên liệu loại $II$ cần sản xuất ($x,y>0$).<br>Trong nhiên liệu loại $I$, tỉ lệ $A:B$ là $1:9$, tổng số phần là $10$.  <br>Vậy lượng chất $A$ trong $x$ lít loại $I$ là $\\dfrac{x}{10}$ và lượng chất $B$ là $\\dfrac{9x}{10}$.<br>Trong nhiên liệu loại $II$, tỉ lệ $A:B$ là $1:3$, tổng số phần là $4$.  <br>Vậy lượng chất $A$ trong $y$ lít loại $II$ là $\\dfrac{y}{4}$ và lượng chất $B$ là $\\dfrac{3y}{4}$.<br>Vì sử dụng hết $135$ lít chất $A$ và $615$ lít chất $B$, ta có hệ phương trình:  <br>$\\heva{&\\dfrac{x}{10}+\\dfrac{y}{4}=135\\\\&\\dfrac{9x}{10}+\\dfrac{3y}{4}=615} \\Leftrightarrow \\heva{&2x+5y=2700\\\\&18x+15y=12300} \\Leftrightarrow \\heva{&x=300\\\\&y=450}$.  <br>Vậy sản xuất được $300$ lít nhiên liệu loại $I$ và $450$ lít nhiên liệu loại $II$."}]}, {"noiDungChung": "Một cơ sở thủ công mỹ nghệ sản xuất ba loại sản phẩm: Túi cói, Giỏ mây và Khay gỗ. Lợi nhuận từ mỗi túi cói là $50$ ngàn đồng, giỏ mây là $40$ ngàn đồng và khay gỗ là $60$ ngàn đồng. Do nguồn lực có hạn, cơ sở đưa ra các điều kiện ràng buộc:<br>a) Tổng số túi cói và giỏ mây không quá $20$ chiếc.  <br>b) Số khay gỗ sản xuất luôn bằng đúng một nửa tổng số túi cói và giỏ mây cộng lại.  <br>c) Tổng thời gian hoàn thiện túi cói là $2$ giờ/chiếc, giỏ mây là $1$ giờ/chiếc và khay gỗ là $4$ giờ/chiếc. Tổng quỹ thời gian của cơ sở không quá $80$ giờ.  <br>d) Cơ sở cam kết sản xuất ít nhất $4$ túi cói và $6$ giỏ mây.<br>Gọi $x$, $y$ lần lượt là số lượng túi cói và giỏ mây ($x, y \\in \\mathbb{N}$).", "cauHoi": [{"question": "Hãy thiết lập hệ bất phương trình ràng buộc theo hai biến $x$ và $y$ sau khi đã quy đổi số lượng Khay gỗ theo $x$ và $y$.", "choices": ["$\\heva{&x\\geq 4\\\\&y\\geq 6\\\\&x+y\\leq 20\\\\&4x+3y\\leq 80}$", "$\\heva{&x\\geq 4\\\\&y\\geq 6\\\\&x+y\\leq 20\\\\&2x+y\\leq 80}$", "$\\heva{&x\\geq 4\\\\&y\\geq 6\\\\&x+y\\leq 20\\\\&3x+4y\\leq 80}$", "$\\heva{&x\\geq 0\\\\&y\\geq 0\\\\&x+y\\leq 20\\\\&4x+3y\\leq 80}$"], "correctIndex": 0, "explain": "Gọi $z$ là số lượng khay gỗ, ta có $z = \\dfrac{x+y}{2}$. Thay vào các điều kiện đề bài:<br>a) Cam kết sản xuất: $x \\geq 4$ và $y \\geq 6$.  <br>b) Giới hạn số lượng: $x+y \\leq 20$.  <br>c) Giới hạn thời gian: $2x+y+4z \\leq 80 \\Rightarrow 2x+y+4\\left(\\dfrac{x+y}{2}\\right) \\leq 80 \\Leftrightarrow 4x+3y \\leq 80$.<br>Hệ bất phương trình ràng buộc là: $\\heva{&x\\geq 4\\\\&y\\geq 6\\\\&x+y\\leq 20\\\\&4x+3y\\leq 80.}$"}, {"question": "Hãy tìm số lượng túi cói và giỏ mây cần sản xuất để cơ sở đạt lợi nhuận lớn nhất.", "choices": ["$x=4$, $y=16$", "$x=10$, $y=10$", "$x=20$, $y=0$", "$x=14$, $y=6$"], "correctIndex": 3, "explain": "Hàm lợi nhuận: $L = 50x+40y+60\\left(\\dfrac{x+y}{2}\\right) = 80x+70y$ (ngàn đồng).<br>Miền nghiệm của hệ là miền tam giác $MNP$ (hình vẽ) với các đỉnh:<br>a) $M(4;6)$ là giao của $x=4$ và $y=6$.  <br>b) $N(14;6)$ là giao của $x+y=20$ và $y=6$.  <br>c) $P(4;16)$ là giao của $x=4$ và $x+y=20$.<br>(Lưu ý: Đường $4x+3y=80$ không cắt miền nghiệm tam giác $MNP$ vì tại các đỉnh của tam giác, biểu thức $4x+3y$ luôn nhỏ hơn hoặc bằng $80$).<br>Tính giá trị lợi nhuận tại các đỉnh:<br>a) Tại $M(4;6)$: $L = 80(4)+70(6) = 740$.  <br>b) Tại $N(14;6)$: $L = 80(14)+70(6) = 1540$.  <br>c) Tại $P(4;16)$: $L = 80(4)+70(16) = 1440$.<br>Vậy lợi nhuận lớn nhất đạt $1540$ ngàn đồng khi $x=14$ và $y=6$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, x=0.4cm, y=0.4cm, font=\\footnotesize]\n\t\t\t\t\t\\draw[color=gray!20, step=1] (-1,-1) grid (21,21);\n\t\t\t\t\t\\draw[->, thick] (-1,0) -- (21,0) node[below] {$x$};\n\t\t\t\t\t\\draw[->, thick] (0,-1) -- (0,21) node[left] {$y$};\n\t\t\t\t\t\\node[below left] at (0,0) {$O$};\n\t\t\t\t\t\\fill[blue!15] (4,6) -- (14,6) -- (4,16) -- cycle;\n\t\t\t\t\t\\draw[blue!50, pattern=north east lines, pattern color=blue!30] (4,6) -- (14,6) -- (4,16) -- cycle;\n\t\t\t\t\t\\draw[thick, blue] plot[domain=0:20] (\\x,{20-\\x}) node[right] {$x+y=20$};\n\t\t\t\t\t\\draw[thick, red] plot[domain=0:18] (\\x,{(80-4*\\x)/3}) node[above right] {$4x+3y=80$};\n\t\t\t\t\t\\draw[thick, dashed] (4,0) -- (4,20) node[above] {$x=4$};\n\t\t\t\t\t\\draw[thick, dashed] (0,6) -- (20,6) node[right] {$y=6$};\n\t\t\t\t\t\\filldraw[black] (4,6) circle (1.5pt) node[below left] {$M(4;6)$};\n\t\t\t\t\t\\filldraw[black] (14,6) circle (1.5pt) node[below right] {$N(14;6)$};\n\t\t\t\t\t\\filldraw[black] (4,16) circle (1.5pt) node[left] {$P(4;16)$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Trong một thí nghiệm vật lý, một vật nặng được treo vào đầu một lò xo đang dao động điều hòa theo phương thẳng đứng. Vị trí của vật tại thời điểm $t$ (giây) được xác định bởi hàm số $s(t) = 5\\cos\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)$ (cm).", "cauHoi": [{"question": "Vận tốc của vật tại thời điểm $t$ được xác định bởi công thức nào sau đây?", "choices": ["$v(t) = 10\\pi\\sin\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)$", "$v(t) = -10\\pi\\sin\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)$", "$v(t) = 5\\sin\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)$", "$v(t) = -5\\pi\\sin\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)$"], "correctIndex": 1, "explain": "Vận tốc là đạo hàm của quãng đường theo thời gian:  <br>$v(t) = s'(t) = \\left[5\\cos\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)\\right]' = 5 \\cdot \\left[-\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)' \\cdot \\sin\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)\\right]$.  <br>$\\Rightarrow v(t) = -10\\pi\\sin\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)\\text{ (cm/s)}$."}, {"question": "Gia tốc của vật tại thời điểm $t = 0{,}5$ giây có giá trị xấp xỉ là", "choices": ["$a \\approx 85{,}5\\text{ cm/s}^2$", "$a \\approx -197{,}4\\text{ cm/s}^2$", "$a \\approx -98{,}7\\text{ cm/s}^2$", "$a \\approx 98{,}7\\text{ cm/s}^2$"], "correctIndex": 3, "explain": "Gia tốc là đạo hàm của vận tốc:  <br>$a(t) = v'(t) = \\left[-10\\pi\\sin\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)\\right]' = -20\\pi^2\\cos\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)$.  <br>Tại $t = 0{,}5$ giây:  <br>$a(0{,}5) = -20\\pi^2\\cos\\left(2\\pi \\cdot 0{,}5 + \\dfrac{\\pi}{3}\\right) = -20\\pi^2\\cos\\left(\\pi + \\dfrac{\\pi}{3}\\right) = -20\\pi^2 \\cdot \\left(-\\dfrac{1}{2}\\right) = 10\\pi^2$.  <br>Với $\\pi^2 \\approx 9{,}87$, ta có $a(0{,}5) \\approx 98{,}7\\text{ (cm/s}^2\\text{)}$."}]}, {"noiDungChung": "Trong không gian với hệ tọa độ $Oxyz$, cho điểm $M(1;9;4)$. Gọi $(P)$ là mặt phẳng đi qua điểm $M$ và cắt các trục tọa độ $Ox, Oy, Oz$ lần lượt tại các điểm $A, B, C$ khác gốc tọa độ $O$.", "cauHoi": [{"question": "Có bao nhiêu mặt phẳng $(P)$ thỏa mãn điều kiện $OA=OB=OC$?", "choices": ["$1$", "$3$", "$4$", "$2$"], "correctIndex": 2, "explain": "Gọi $A(a;0;0), B(0;b;0), C(0;0;c)$. Mặt phẳng $(P)\\colon \\dfrac{x}{a}+\\dfrac{y}{b}+\\dfrac{z}{c}=1$.<br>Vì $M(1;9;4) \\in (P)$ nên $\\dfrac{1}{a}+\\dfrac{9}{b}+\\dfrac{4}{c}=1$.<br>Từ giả thiết $OA=OB=OC \\Rightarrow |a|=|b|=|c|$.<br>Xét các trường hợp về dấu:<br>a) $a=b=c \\Rightarrow \\dfrac{14}{a}=1 \\Rightarrow a=14$.  <br>b) $a=b=-c \\Rightarrow \\dfrac{6}{a}=1 \\Rightarrow a=6$.  <br>c) $a=-b=c \\Rightarrow \\dfrac{-4}{a}=1 \\Rightarrow a=-4$.  <br>d) $a=-b=-c \\Rightarrow \\dfrac{-12}{a}=1 \\Rightarrow a=-12$.<br>Các trường hợp khác như $-a=b=c$ tương đương với các trường hợp trên. Vậy có $4$ mặt phẳng."}, {"question": "Viết phương trình đường thẳng $\\Delta$ đi qua điểm $M(1;9;4)$ và vuông góc với mặt phẳng $(\\alpha)\\colon 2x-y+3z+1=0$.", "choices": ["$\\Delta\\colon \\dfrac{x-1}{2}=\\dfrac{y-9}{1}=\\dfrac{z-4}{3}$", "$\\Delta\\colon \\dfrac{x-1}{2}=\\dfrac{y-9}{-1}=\\dfrac{z-4}{3}$", "$\\Delta\\colon \\dfrac{x+1}{2}=\\dfrac{y+9}{-1}=\\dfrac{z+4}{3}$", "$\\Delta\\colon \\dfrac{x-2}{1}=\\dfrac{y+1}{9}=\\dfrac{z-3}{4}$"], "correctIndex": 1, "explain": "Mặt phẳng $(\\alpha)$ có véc-tơ pháp tuyến $\\vec{n}_{\\alpha}=(2;-1;3)$.<br>Vì đường thẳng $\\Delta$ vuông góc với mặt phẳng $(\\alpha)$ nên $\\Delta$ có véc-tơ chỉ phương $\\vec{u}_{\\Delta}=\\vec{n}_{\\alpha}=(2;-1;3)$.<br>Đường thẳng $\\Delta$ đi qua $M(1;9;4)$ nên có phương trình chính tắc là:<br>$\\dfrac{x-1}{2}=\\dfrac{y-9}{-1}=\\dfrac{z-4}{3}$"}, {"question": "Tìm tọa độ điểm $N$ thuộc trục $Oz$ sao cho $|\\vec{NM} + 2\\vec{NO}|$ đạt giá trị nhỏ nhất.", "choices": ["$N(0;0;1)$", "$N(0;0;2)$", "$N\\left(0;0;\\dfrac{4}{3}\\right)$", "$N(0;0;4)$"], "correctIndex": 2, "explain": "Gọi $N(0;0;z) \\in Oz$. Ta có $\\vec{NM} = (1;9;4-z)$ và $\\vec{NO} = (0;0;-z)$.<br>Suy ra $\\vec{NM} + 2\\vec{NO} = (1;9;4-3z)$.<br>Khi đó $|\\vec{NM} + 2\\vec{NO}| = \\sqrt{1^2 + 9^2 + (4-3z)^2} = \\sqrt{82 + (4-3z)^2}$.<br>Biểu thức này đạt giá trị nhỏ nhất khi $4-3z = 0 \\Leftrightarrow z = \\dfrac{4}{3}$.<br>Vậy tọa độ điểm $N\\left(0;0;\\dfrac{4}{3}\\right)$"}]}, {"noiDungChung": "Trong mặt phẳng tọa độ $Oxy$, cho hai đường tròn $(C_1) \\colon (x-2)^2+(y-3)^2=2$ và $(C_2) \\colon (x-1)^2+(y-2)^2=8$.", "cauHoi": [{"question": "Xét vị trí tương đối giữa hai đường tròn $(C_1)$ và $(C_2)$.", "choices": ["Hai đường tròn cắt nhau tại hai điểm phân biệt", "Hai đường tròn ở ngoài nhau", "Hai đường tròn tiếp xúc ngoài với nhau", "Hai đường tròn tiếp xúc trong với nhau"], "correctIndex": 3, "explain": "Ta có $I_1(2;3)$, $I_2(1;2) \\Rightarrow I_1I_2=\\sqrt{(1-2)^2+(2-3)^2}=\\sqrt{2}$.<br>Bán kính $R_1=\\sqrt{2}$, $R_2=\\sqrt{8}=2\\sqrt{2}$.<br>Hiệu hai bán kính: $|R_2-R_1|=|2\\sqrt{2}-\\sqrt{2}|=\\sqrt{2}$.<br>Vì $I_1I_2=|R_2-R_1|=\\sqrt{2}$ nên hai đường tròn $(C_1)$ và $(C_2)$ tiếp xúc trong với nhau."}, {"question": "Gọi $M$ là tiếp điểm của $(C_1)$ và $(C_2)$. Khẳng định nào sau đây là đúng?", "choices": ["$\\vec{I_2M}=\\vec{I_1I_2}$", "$\\vec{I_2M}=2\\vec{I_2I_1}$", "$\\vec{I_1M}=2\\vec{I_2I_1}$", "$\\vec{I_2I_1}=2\\vec{I_1M}$"], "correctIndex": 1, "explain": "Vì $(C_1)$ tiếp xúc trong với $(C_2)$ và $R_2=2R_1$ nên tâm $I_1$ nằm giữa tâm $I_2$ và tiếp điểm $M$.<br>Ta có $I_2M=R_2=2\\sqrt{2}$ và $I_2I_1=\\sqrt{2}$.<br>Do $I_2$, $I_1$, $M$ thẳng hàng theo thứ tự đó nên $\\vec{I_2M}$ và $\\vec{I_2I_1}$ cùng hướng.<br>Suy ra $\\vec{I_2M}=\\dfrac{I_2M}{I_2I_1}\\vec{I_2I_1}=2\\vec{I_2I_1}$."}, {"question": "Viết phương trình các tiếp tuyến chung của hai đường tròn $(C_1)$ và $(C_2)$.", "choices": ["$x+y-7=0$", "$x+y-3=0$ và $x-y+1=0$", "$x+y-5=0$ và $x-y+1=0$", "$x-y+1=0$"], "correctIndex": 0, "explain": "$(C_1)$ có tâm $I_1(2;3)$, $R_1=\\sqrt{2}$. $(C_2)$ có tâm $I_2(1;2)$, $R_2=2\\sqrt{2}$.<br>Vì hai đường tròn tiếp xúc trong nên chỉ có duy nhất $1$ tiếp tuyến chung tại tiếp điểm $M$.<br>Từ $\\vec{I_2M}=2\\vec{I_2I_1} \\Rightarrow \\heva{&x_M-1=2(2-1)\\\\&y_M-2=2(3-2)} \\Rightarrow \\heva{&x_M=3\\\\&y_M=4.}$<br>Tiếp tuyến chung $\\Delta$ đi qua $M(3;4)$ và vuông góc với đường nối tâm $I_1I_2$.<br>Vectơ pháp tuyến $\\vec{n}=\\vec{I_2I_1}=(1;1)$.<br>Phương trình $\\Delta \\colon 1(x-3)+1(y-4)=0 \\Leftrightarrow x+y-7=0$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $16$ phiếu ghi các số thứ tự từ $1$ đến $16$. Lấy lần lượt $8$ phiếu không hoàn lại, gọi $a_i$ là số ghi trên phiếu thứ $i$ lấy được ($1 \\le i \\le 8$). Tính xác suất $P$ để $8$ phiếu lấy được thỏa mãn $a_1<a_2<\\dots<a_8$ và không có bất kỳ hai phiếu nào có tổng các số bằng $17$.", "choices": ["$P=\\dfrac{2^8}{C_{16}^8}$", "$P=\\dfrac{3^8}{C_{16}^8}$", "$P=\\dfrac{2^8}{A_{16}^8}$", "$P=\\dfrac{3^8}{C_{16}^8 \\cdot 8!}$"], "correctIndex": 2, "explain": "Số cách lấy lần lượt $8$ phiếu từ $16$ phiếu (có tính thứ tự) là $n(\\Omega) = A_{16}^8$.<br>Xét điều kiện $a_1 < a_2 < \\dots < a_8$:<br>a) Nếu ta chọn được một tập hợp gồm $8$ số phân biệt, thì chỉ có duy nhất một cách sắp xếp chúng theo thứ tự tăng dần thỏa mãn yêu cầu đề bài.  <br>b) Do đó, số tập hợp thỏa mãn điều kiện thứ tự và điều kiện tổng chính là số cách chọn $8$ số từ $16$ số ban đầu.<br>Xét điều kiện không có hai phiếu nào có tổng bằng $17$:<br>a) Các cặp số có tổng bằng $17$ trong tập $\\{1; 2; \\dots; 16\\}$ là:  $\\{1; 16\\}, \\{2; 15\\}, \\{3; 14\\}, \\{4; 13\\}, \\{5; 12\\}, \\{6; 11\\}, \\{7; 10\\}, \\{8; 9\\}$.  <br>b) Có tất cả $8$ cặp như vậy. Để trong $8$ phiếu lấy ra không có cặp nào có tổng bằng $17$, thì từ mỗi cặp số trên, ta chỉ được phép chọn đúng một số.  <br>c) Mỗi cặp có $2$ cách chọn ($2$ lựa chọn), và có $8$ cặp, nên số tập hợp thỏa mãn là $2 \\cdot 2 \\cdot 2 \\cdot 2 \\cdot 2 \\cdot 2 \\cdot 2 \\cdot 2 = 2^8$ tập hợp.<br>Vì mỗi tập hợp $8$ phần tử này chỉ có $1$ cách duy nhất để sắp xếp theo thứ tự $a_1 < a_2 < \\dots < a_8$, nên số biến cố thuận lợi là $n(A) = 2^8$.<br>Vậy xác suất cần tìm là $P = \\dfrac{n(A)}{n(\\Omega)} = \\dfrac{2^8}{A_{16}^8}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một đôi thỏ cứ mỗi tháng đẻ được một đôi thỏ con; mỗi đôi thỏ con, khi tròn $2$ tháng tuổi, lại mỗi tháng đẻ ra một đôi thỏ con, và quá trình sinh nở cứ thế tiếp diễn. Nếu đầu năm có một đôi thỏ sơ sinh và trong năm đó không có con thỏ nào chết thì sau $1$ năm ($12$ tháng) sẽ có tất cả bao nhiêu đôi thỏ?", "choices": ["$233$ đôi thỏ", "$144$ đôi thỏ", "$377$ đôi thỏ", "$154$ đôi thỏ"], "correctIndex": 0, "explain": "Gọi $F_n$ là số đôi thỏ có ở tháng thứ $n$. Theo giả thiết bài toán:<br>a) Tháng thứ $1$: Có $1$ đôi thỏ sơ sinh ($F_1=1$).  <br>b) Tháng thứ $2$: Đôi thỏ này chưa đủ $2$ tháng tuổi nên chưa đẻ, vẫn chỉ có $1$ đôi ($F_2=1$).  <br>c) Tháng thứ $3$: Đôi thỏ đầu tiên tròn $2$ tháng tuổi và đẻ ra đôi thứ hai, tổng cộng có $2$ đôi ($F_3=2$).  <br>d) Tháng thứ $4$: Đôi thỏ đầu tiên tiếp tục đẻ, đôi thứ hai chưa đủ tuổi, tổng cộng có $3$ đôi ($F_4=3$).<br>Quy luật này tạo thành dãy số Fibonacci với công thức truy hồi: $F_n=F_{n-1}+F_{n-2}$ (với $n \\geq 3$).  Dãy số cụ thể qua các tháng như sau:  $F_1=1$; $F_2=1$; $F_3=2$; $F_4=3$; $F_5=5$; $F_6=8$; $F_7=13$; $F_8=21$; $F_9=34$; $F_{10}=55$; $F_{11}=89$; $F_{12}=144$.  Tuy nhiên, bài toán hỏi sau $1$ năm (tức là tính cả kết quả của tháng thứ $12$ sinh sản để bước sang tháng thứ $13$), số đôi thỏ sẽ là giá trị của $F_{13}$.  Ta có $F_{13}=F_{12}+F_{11}=144+89=233$.  Vậy sau $1$ năm sẽ có $233$ đôi thỏ."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ vuông cân tại $A$ có $AB=AC=30$ cm. Hai đường trung tuyến $BF$ và $CE$ cắt nhau tại $G$. Diện tích tam giác $GFC$ bằng", "choices": ["$75$ cm$^2$", "$150$ cm$^2$", "$50$ cm$^2$", "$100$ cm$^2$"], "correctIndex": 0, "explain": "Diện tích tam giác $ABC$ là $S_{\\triangle ABC}=\\dfrac{1}{2}AB\\cdot AC = \\dfrac{1}{2}\\cdot 30\\cdot 30 = 450$ cm$^2$.<br>Vì $F$ là trung điểm của $AC$ nên $S_{\\triangle BFC}=\\dfrac{1}{2}S_{\\triangle ABC} = \\dfrac{1}{2}\\cdot 450 = 225$ cm$^2$.<br>Vì $G$ là trọng tâm của tam giác $ABC$ nên $GF = \\dfrac{1}{3}BF$.<br>Xét hai tam giác $GFC$ và $BFC$ có chung đường cao hạ từ $C$ xuống $BF$, ta có:  $S_{\\triangle GFC} = \\dfrac{GF}{BF}S_{\\triangle BFC} = \\dfrac{1}{3}S_{\\triangle BFC} = \\dfrac{1}{3}\\cdot 225 = 75$ cm$^2$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, font=\\footnotesize, line join=round, line cap=round]\n\t\t\t\t\\coordinate (A) at (0,3);\n\t\t\t\t\\coordinate (B) at (0,0);\n\t\t\t\t\\coordinate (C) at (3,0);\n\t\t\t\t\\coordinate (E) at ($(A)!0.5!(B)$);\n\t\t\t\t\\coordinate (F) at ($(A)!0.5!(C)$);\n\t\t\t\t\\coordinate (G) at (intersection of B--F and C--E);\n\t\t\t\t\\draw (A)--(B)--(C)--cycle;\n\t\t\t\t\\draw (B)--(F) (C)--(E);\n\t\t\t\t\\foreach \\p/\\pos in {A/above, B/left, C/right, E/left, F/right, G/below}\n\t\t\t\t\\fill (\\p) circle (1.5pt) node[\\pos] {$\\p$};\n\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Cho hai hàm số $f(x)=2^{x^2-4x+5}$ và $g(x)=\\ln(x^2-4x+5)$. Gọi $(C_1)$, $(C_2)$ lần lượt là đồ thị của hai hàm số đã cho.", "cauHoi": [{"question": "Mệnh đề nào sau đây là đúng về tính đơn điệu của hàm số $h(x)=f(x) \\cdot g(x)$ trên khoảng $(-\\infty;2)$?", "choices": ["Hàm số $h(x)$ đồng biến trên khoảng $(-\\infty;2)$", "Hàm số $h(x)$ nghịch biến trên khoảng $(-\\infty;2)$", "Hàm số $h(x)$ không xác định trên khoảng $(-\\infty;2)$", "Hàm số $h(x)$ đạt cực đại tại $x=1$"], "correctIndex": 1, "explain": "Đặt $u(x)=x^2-4x+5$. Với $x \\in (-\\infty;2)$ thì $u(x)=(x-2)^2+1 > 1$.<br>Đạo hàm $u'(x)=2x-4 < 0$ với mọi $x < 2$, suy ra $u(x)$ nghịch biến trên $(-\\infty;2)$.<br>Ta có $h(x)=2^{u(x)} \\cdot \\ln[u(x)]$.<br>Đạo hàm $h'(x)=u'(x) \\cdot 2^{u(x)} \\cdot \\ln 2 \\cdot \\ln[u(x)] + 2^{u(x)} \\cdot \\dfrac{u'(x)}{u(x)}$.<br>$h'(x)=u'(x) \\cdot 2^{u(x)} \\left[ \\ln 2 \\cdot \\ln u(x) + \\dfrac{1}{u(x)} \\right]$.<br>Vì $u(x) > 1$ nên $\\ln u(x) > 0$, $\\dfrac{1}{u(x)} > 0$ và $2^{u(x)} > 0$.<br>Kết hợp với $u'(x) < 0$, ta suy ra $h'(x) < 0$ với mọi $x \\in (-\\infty;2)$.<br>Vậy hàm số $h(x)$ nghịch biến trên khoảng $(-\\infty;2)$."}, {"question": "Tìm số giao điểm của đồ thị hàm số $y=f'(x)$ và $y=g'(x)$.", "choices": ["$0$", "$1$", "$2$", "$3$"], "correctIndex": 1, "explain": "Ta có $f'(x)=(2x-4) \\cdot 2^{x^2-4x+5} \\ln 2$ và $g'(x)=\\dfrac{2x-4}{x^2-4x+5}$.<br>Phương trình hoành độ giao điểm của hai đồ thị đạo hàm:  $(2x-4) \\cdot 2^{x^2-4x+5} \\ln 2 = \\dfrac{2x-4}{x^2-4x+5} $<br>$\\Leftrightarrow (2x-4) \\left[ 2^{x^2-4x+5} \\ln 2 - \\dfrac{1}{x^2-4x+5} \\right] = 0$.<br>$\\Leftrightarrow \\hoac{&2x-4=0 \\Leftrightarrow x=2\\\\&2^{x^2-4x+5} \\ln 2 = \\dfrac{1}{x^2-4x+5} \\quad (*).}$<br>Xét phương trình $(*)$, đặt $t=x^2-4x+5 \\geq 1$. Phương trình trở thành $2^t \\ln 2 = \\dfrac{1}{t}$.  Với $t \\geq 1$, vế trái $VT=2^t \\ln 2 \\geq 2 \\ln 2 > 1$.<br>Vế phải $VP=\\dfrac{1}{t} \\leq 1$.<br>Do đó $VT > VP$, dẫn đến phương trình $(*)$ vô nghiệm.<br>Vậy hai đồ thị đạo hàm có duy nhất $1$ giao điểm tại $x=2$."}, {"question": "Gọi $A$, $B$ lần lượt là các điểm cực tiểu của đồ thị $(C_1)$ và $(C_2)$. Tính diện tích $S$ của tam giác $OAB$ với $O$ là gốc tọa độ.", "choices": ["$S=4$", "$S=1$", "$S=2$", "$S=3$"], "correctIndex": 2, "explain": "Xét hàm số $f(x)=2^{x^2-4x+5}$. Đạo hàm $f'(x)=(2x-4) 2^{x^2-4x+5} \\ln 2$.  $f'(x)=0 \\Leftrightarrow x=2$. Bảng biến thiên:<br>Từ BBT, điểm cực tiểu của $(C_1)$ là $A(2;2)$.  Xét hàm số $g(x)=\\ln(x^2-4x+5)$. Tương tự, $g'(x)=0 \\Leftrightarrow x=2$.<br>Giá trị cực tiểu $g(2)=\\ln 1=0$. Vậy điểm cực tiểu của $(C_2)$ là $B(2;0)$.<br>Tam giác $OAB$ có các đỉnh $O(0;0)$, $A(2;2)$, $B(2;0)$.<br>Dễ thấy $B$ nằm trên trục hoành $Ox$, cạnh $OB$ nằm trên trục hoành và có độ dài $OB=2$.<br>Đường cao kẻ từ $A$ đến $OB$ chính là tung độ của điểm $A$, $h=|y_A|=2$.<br>Diện tích tam giác $S_{OAB}=\\dfrac{1}{2} \\cdot OB \\cdot h = \\dfrac{1}{2} \\cdot 2 \\cdot 2 = 2$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>"}]}, {"noiDungChung": "Ba nhân viên gồm Linh, Mai, và Nam được phân công phụ trách ba vị trí khác nhau tại một sự kiện: Đón khách, Kỹ thuật, và Hậu cần. Mỗi người sử dụng một loại bộ đàm có màu khác nhau: Đỏ, Xanh, và Vàng. Biết rằng: <br>a) Mai không phụ trách Kỹ thuật.  <br>b) Người dùng bộ đàm màu Đỏ phụ trách Đón khách.  <br>c) Linh dùng bộ đàm màu Vàng.  <br>d) Nam không phụ trách Đón khách.", "cauHoi": [{"question": "Khẳng định nào sau đây là <b>chắc chắn đúng</b>?", "choices": ["Nam phụ trách vị trí Kỹ thuật hoặc Hậu cần", "Linh phụ trách vị trí Đón khách", "Mai dùng bộ đàm màu Đỏ", "Nam dùng bộ đàm màu Đỏ"], "correctIndex": 0, "explain": "- Từ dữ kiện (3), Linh dùng bộ đàm màu Vàng.<br>- Từ dữ kiện (2), người dùng bộ đàm màu Đỏ phụ trách Đón khách. Do Linh dùng màu Vàng nên Linh không phụ trách Đón khách.<br>- Nam không phụ trách Đón khách (GT 4). Vậy người phụ trách Đón khách chỉ có thể là Mai.<br>- Suy ra Mai dùng bộ đàm màu Đỏ.<br>- Vì Mai (Đỏ - Đón khách) và Linh (Vàng), nên Nam dùng bộ đàm màu Xanh.<br>- Nam không phụ trách Đón khách là chắc chắn đúng theo đề bài, và từ các suy luận trên, Nam sẽ làm Kỹ thuật hoặc Hậu cần."}, {"question": "Nếu biết thêm rằng “Linh không làm các công việc liên quan đến máy móc kỹ thuật”, hãy xác định vị trí của Nam.", "choices": ["Nam phụ trách Đón khách", "Nam phụ trách Hậu cần", "Nam phụ trách Kỹ thuật hoặc Hậu cần", "Nam phụ trách Kỹ thuật"], "correctIndex": 3, "explain": "- Ta đã biết: Mai (Đón khách), Linh (Vàng), Nam (Xanh).<br>- Linh không làm Kỹ thuật và đã biết không làm Đón khách $\\Rightarrow$ Linh làm Hậu cần.<br>- Vị trí cuối cùng là Kỹ thuật thuộc về Nam."}, {"question": "Sắp xếp đúng cặp (Vị trí - Màu bộ đàm) của ba bạn theo thứ tự <b>Linh - Mai - Nam</b>.", "choices": ["Hậu cần - Vàng, Đón khách - Đỏ, Kỹ thuật - Xanh", "Hậu cần - Vàng, Đón khách - Đỏ, Kỹ thuật - Xanh", "Kỹ thuật - Xanh, Đón khách - Đỏ, Hậu cần - Vàng", "Đón khách - Đỏ, Hậu cần - Vàng, Kỹ thuật - Xanh"], "correctIndex": 1, "explain": "- Linh: Hậu cần - Vàng.<br>- Mai: Đón khách - Đỏ.<br>- Nam: Kỹ thuật - Xanh."}]}, {"noiDungChung": "Trên một kệ trưng bày điện thoại có $5$ vị trí liên tiếp được đánh số từ $1$ đến $5$ (từ trái sang phải). Có $4$ dòng điện thoại ký hiệu là $A$, $B$, $C$, $D$ được đặt vào kệ, một vị trí sẽ để trống để đặt biển tên cửa hàng. Quy tắc sắp xếp như sau: <br>a) Điện thoại $A$ và $B$ là hai dòng cao cấp nên phải đặt cách nhau đúng một vị trí.  <br>b) Điện thoại $C$ không được đặt cạnh vị trí trống.  <br>c) Vị trí số $1$ và số $5$ không được để trống.  <br>d) Điện thoại $D$ phải nằm ở vị trí có số thứ tự nhỏ hơn vị trí của $C$.", "cauHoi": [{"question": "Nếu vị trí số $3$ để trống, điện thoại nào sau đây <b>không thể</b> nằm ở vị trí số $2$?", "choices": ["$A$", "$B$", "$C$", "$D$"], "correctIndex": 2, "explain": "- Vị trí số $3$ trống.<br>- Theo quy tắc (2), điện thoại $C$ không được đặt cạnh vị trí trống $\\Rightarrow C$ không ở vị trí $2$ và $4$.<br>- Vậy $C$ chỉ có thể ở $1$ hoặc $5$.<br>- Theo quy tắc (4), $D < C$. Nếu $C$ ở $1$ thì không có chỗ cho $D$ (loại). Vậy $C$ ở $5$.<br>- Do đó, điện thoại $C$ chắc chắn không thể nằm ở vị trí số $2$."}, {"question": "Nếu $A$ nằm ở vị trí số $1$ và $B$ nằm ở vị trí số $3$, vị trí nào sau đây <b>phải</b> để trống?", "choices": ["Vị trí số $4$", "Vị trí số $5$", "Vị trí số $3$", "Vị trí số $2$"], "correctIndex": 0, "explain": "- $A$ ở $1$, $B$ ở $3$ (Thỏa mãn quy tắc 1: cách nhau đúng một vị trí).<br>- Các vị trí còn lại là $2, 4, 5$. Vị trí trống không ở $1, 5$ nên trống là $2$ hoặc $4$.<br>- Nếu vị trí $2$ trống: Điện thoại $C$ không được cạnh trống nên $C$ không ở $1$ và $3$. Nhưng $A, B$ đã ở đó. Vậy $C$ ở $4$ hoặc $5$. Nếu $C$ ở $4$, $C$ cạnh trống $2$ (loại). Nếu $C$ ở $5$, $D$ ở $4$. Cấu hình: $A(1), \\text{Trống}(2), B(3), D(4), C(5)$. Tuy nhiên, $C(5)$ cạnh $D(4)$ thì được, nhưng $D(4)$ cạnh trống $(2)$ không vi phạm, nhưng quy tắc (2) nói $C$ không cạnh trống. Ở đây $C(5)$ không cạnh trống $(2)$. Nhưng xét tiếp $D < C$ thỏa mãn.<br>- Xét nếu vị trí $4$ trống: $C$ không được ở $3, 5$. Vì $B$ ở $3$ nên $C$ không ở $5$. Vậy $C$ phải ở vị trí còn lại là $2$. Khi đó $D < C \\Rightarrow D$ ở $1$. Nhưng $A$ đã ở $1$ (Loại).<br>- Vậy vị trí $4$ là vị trí duy nhất có thể để trống nếu xét các ràng buộc kề cận của $C$."}, {"question": "Có bao nhiêu cách sắp xếp vị trí của điện thoại $D$ sao cho luôn tồn tại ít nhất một phương án đặt các điện thoại còn lại thỏa mãn tất cả quy tắc?", "choices": ["$1$", "$2$", "$4$", "$3$"], "correctIndex": 3, "explain": "- $D < C$ và $C$ không cạnh trống. Trống $\\in \\{2, 3, 4\\}$.<br>- Nếu $D=1$, $C$ có thể ở $\\{3, 4, 5\\}$. Ta dễ dàng tìm được cấu hình cho $A, B$ cách nhau $1$ vị trí.<br>- Nếu $D=2$, $C$ có thể ở $\\{4, 5\\}$.<br>- Nếu $D=3$, $C$ có thể ở $\\{5\\}$.<br>- Nếu $D=4$, không có chỗ cho $C$ (vì $C$ không ở $5$ nếu trống ở $4$, hoặc nếu $C=5$ thì $D < C$ thỏa nhưng phải xếp $A, B$).<br>- Qua kiểm tra các trường hợp kề nhau của $A, B$, $D$ có thể nhận các giá trị $1, 2, 3$."}]}, {"noiDungChung": "Biểu đồ tròn bên cạnh thống kê tỉ lệ phần trăm các loại chất thải hữu cơ thu gom được tại một trang trại trong một tháng. Biết rằng tỉ lệ phần trăm của <i>Phế phẩm nông nghiệp</i> gấp $4$ lần tỉ lệ phần trăm của <i>Chất thải chăn nuôi</i>. Ngoài ra, tỉ lệ của <i>Rác thải sinh hoạt</i> chiếm $15\\%$ và <i>Các loại khác</i> chiếm $5\\%$. Tổng khối lượng chất thải thu gom được là $250$ kg.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[line join=round, line cap=round, font=\\footnotesize]\n\t\t\t\n\t\t\t\n\t\t\t\\fill[blue!50] (0,0) -- (90:1.8) arc (90:-198:1.8) -- cycle;\n\t\t\t\n\t\t\t\n\t\t\t\n\t\t\t\\fill[blue!50] (0,0) -- (90:1.8) arc (90:-140.4:1.8) -- cycle; \n\t\t\t\\fill[orange!60] (0,0) -- (-140.4:1.8) arc (-140.4:-198:1.8) -- cycle; \n\t\t\t\\fill[green!50] (0,0) -- (-198:1.8) arc (-198:-252:1.8) -- cycle; \n\t\t\t\\fill[yellow!60] (0,0) -- (-252:1.8) arc (-252:-270:1.8) -- cycle; \n\t\t\t\n\t\t\t\\begin{scope}[shift={(2.5,0.8)}]\n\t\t\t\t\\draw[fill=blue!50] (0,0) rectangle (0.2,0.2) node[right, shift={(0,-0.1)}]{Phế phẩm nông nghiệp};\n\t\t\t\t\\draw[fill=orange!60] (0,-0.4) rectangle (0.2,-0.2) node[right, shift={(0,-0.1)}]{Chất thải chăn nuôi};\n\t\t\t\t\\draw[fill=green!50] (0,-0.8) rectangle (0.2,-0.6) node[right, shift={(0,-0.1)}]{Rác thải sinh hoạt};\n\t\t\t\t\\draw[fill=yellow!60] (0,-1.2) rectangle (0.2,-1.0) node[right, shift={(0,-0.1)}]{Các loại khác};\n\t\t\t\\end{scope}\n\t\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Bằng cách thiết lập phương trình, hãy tìm tỉ lệ phần trăm của <i>Phế phẩm nông nghiệp</i> và <i>Chất thải chăn nuôi</i>.", "choices": ["Chăn nuôi chiếm $10\\%$, Nông nghiệp chiếm $40\\%$", "Chăn nuôi chiếm $20\\%$, Nông nghiệp chiếm $80\\%$", "Chăn nuôi chiếm $16\\%$, Nông nghiệp chiếm $64\\%$", "Chăn nuôi chiếm $15\\%$, Nông nghiệp chiếm $60\\%$"], "correctIndex": 2, "explain": "Gọi $x$ là tỉ lệ phần trăm của <i>Chất thải chăn nuôi</i> ($x>0$).<br>Khi đó, tỉ lệ phần trăm của <i>Phế phẩm nông nghiệp</i> là $4x$.<br>Vì tổng tỉ lệ của biểu đồ tròn là $100\\%$, ta có phương trình:  $$4x+x+15\\%+5\\%=100\\%$$  $$\\Leftrightarrow 5x+20\\%=100\\% \\Leftrightarrow 5x=80\\% \\Leftrightarrow x=16\\%$$  Vậy tỉ lệ <i>Chất thải chăn nuôi</i> là $16\\%$ và <i>Phế phẩm nông nghiệp</i> là $4\\cdot 16\\%=64\\%$."}, {"question": "Khối lượng <i>Phế phẩm nông nghiệp</i> thu gom được trong tháng đó là bao nhiêu kg?", "choices": ["$150$ kg", "$160$ kg", "$175$ kg", "$180$ kg"], "correctIndex": 1, "explain": "Khối lượng <i>Phế phẩm nông nghiệp</i> là:  $$250\\cdot 64\\%=250\\cdot\\dfrac{64}{100}=160\\text{ (kg)}$$"}, {"question": "Nhà trường dự định tái chế toàn bộ <i>Phế phẩm nông nghiệp</i> và <i>Rác thải sinh hoạt</i>. Tổng khối lượng rác được tái chế chiếm bao nhiêu phần trăm tổng lượng rác của trang trại?", "choices": ["$64\\%$", "$75\\%$", "$79\\%$", "$80\\%$"], "correctIndex": 2, "explain": "Tỉ lệ phần trăm tổng cộng của hai loại rác này là:  $$64\\%+15\\%=79\\%$$"}]}, {"noiDungChung": "Nhà vườn thu hoạch $100$ quả táo và thống kê khối lượng của chúng (đơn vị: gam) được kết quả như bảng bên dưới.<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Khối lượng (gam)</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Số quả táo</b></td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[150;160)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$10$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[160;170)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$20$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[170;180)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$40$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[180;190)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$20$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[190;200)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$10$</td></tr></table>", "cauHoi": [{"question": "Dựa vào bảng thống kê, khẳng định nào sau đây là đúng?", "choices": ["Nhóm chứa mốt của mẫu số liệu là nhóm $[160;170)$", "Số quả táo có khối lượng dưới $170$ gam chiếm $30\\%$", "Có đúng $50$ quả táo có khối lượng từ $180$ gam trở lên", "Số quả táo thuộc nhóm $[170;180)$ ít hơn nhóm $[160;170)$"], "correctIndex": 1, "explain": "* Xét các khẳng định:<br>- Nhóm có tần số lớn nhất là $[170;180)$ (với $40$ quả táo) nên đây là nhóm chứa mốt. Khẳng định A sai.<br>- Số quả táo có khối lượng dưới $170$ gam thuộc hai nhóm $[150;160)$ và $[160;170)$. Tổng số là $10+20=30$ quả, chiếm tỉ lệ $\\dfrac{30}{100}=30\\%$. Khẳng định B đúng.<br>- Số quả táo từ $180$ gam trở lên thuộc hai nhóm $[180;190)$ và $[190;200)$. Tổng số là $20+10=30$ quả. Khẳng định C sai.<br>- Số quả táo thuộc nhóm $[170;180)$ là $40$ quả, nhiều hơn số quả táo thuộc nhóm $[160;170)$ là $20$ quả. Khẳng định D sai."}, {"question": "Ước lượng khối lượng trung bình của một quả táo được thu hoạch.", "choices": ["$172{,}5$ gam", "$174{,}0$ gam", "$175{,}0$ gam", "$176{,}5$ gam"], "correctIndex": 2, "explain": "Chọn giá trị đại diện cho mỗi nhóm là trung bình cộng của hai đầu mút khoảng:<br>$c_1=155$, $c_2=165$, $c_3=175$, $c_4=185$, $c_5=195$.<br>Cỡ mẫu $n=100$.<br>Số trung bình của mẫu số liệu ghép nhóm là:<br>$\\bar{x}=\\dfrac{10\\cdot155+20\\cdot165+40\\cdot175+20\\cdot185+10\\cdot195}{100}$<br>$\\bar{x}=\\dfrac{1550+3300+7000+3700+1950}{100}=\\dfrac{17500}{100}=175$ (gam)."}, {"question": "Nhà vườn muốn chọn ra $25\\%$ số quả táo có khối lượng lớn nhất để xuất khẩu. Hỏi khối lượng tối thiểu của một quả táo đạt tiêu chuẩn xuất khẩu là bao nhiêu (làm tròn đến hàng phần mười)?", "choices": ["$180{,}0$ gam", "$182{,}5$ gam", "$185{,}0$ gam", "$187{,}5$ gam"], "correctIndex": 1, "explain": "Bài toán yêu cầu tìm giá trị chia mẫu số liệu thành $75\\%$ thấp nhất và $25\\%$ cao nhất, đó chính là tứ phân vị thứ ba $Q_3$.<br>Ta có cỡ mẫu $n=100\\Rightarrow\\dfrac{3n}{4}=75$.<br>Lập tần số tích lũy:<br>$cf_1=10$, $cf_2=10+20=30$, $cf_3=30+40=70$, $cf_4=70+20=90$.<br>Vì $cf_3<75\\le cf_4$ nên nhóm chứa $Q_3$ là nhóm thứ tư: $[180;190)$.<br>Ta có: đầu mút trái $L=180$, độ dài nhóm $h=10$, tần số nhóm $n_4=20$, tần số tích lũy nhóm liền trước $cf_3=70$.<br>Giá trị của tứ phân vị thứ ba là:<br>$Q_3=L+\\dfrac{\\dfrac{3n}{4}-cf_3}{n_4}\\cdot h=180+\\dfrac{75-70}{20}\\cdot10=180+\\dfrac{5}{20}\\cdot10=180+2{,}5=182{,}5$.<br>Vậy khối lượng tối thiểu của một quả táo xuất khẩu là $182{,}5$ gam."}]}]}, {"id": "extra-3", "ten": "Đề chuẩn cấu trúc minh họa số 9", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Hai đội bóng $A$ và $B$ cùng tham gia một giải bóng đá (các trận đấu của đội $A$ và đội $B$ là độc lập với nhau). Xác suất vượt qua vòng bảng của đội $A$ thấp hơn đội $B$ là $0{,}1$. Biết xác suất để cả hai đội không vượt qua vòng bảng là $0{,}12$. Tính xác suất đội $A$ vượt qua vòng bảng còn đội $B$ không vượt qua vòng bảng.", "choices": ["$0{,}18$", "$0{,}16$", "$0{,}24$", "$0{,}08$"], "correctIndex": 0, "explain": "Gọi $P(A)=x$ là xác suất đội $A$ vượt qua vòng bảng ($0 \\le x \\le 0{,}9$).<br>Vì xác suất vượt qua vòng bảng của đội $A$ thấp hơn đội $B$ là $0{,}1$ nên xác suất đội $B$ vượt qua vòng bảng là:  $P(B)=x+0{,}1$.<br>Xác suất để đội $A$ không vượt qua vòng bảng là: $P(\\overline{A})=1-x$.<br>Xác suất để đội $B$ không vượt qua vòng bảng là: $P(\\overline{B})=1-(x+0{,}1)=0{,}9-x$.<br>Do các trận đấu của hai đội là độc lập nên xác suất cả hai đội không vượt qua vòng bảng là:  $P(\\overline{A} \\cap \\overline{B}) = P(\\overline{A}) \\cdot P(\\overline{B}) = (1-x)(0{,}9-x)$.<br>Theo giả thiết, ta có phương trình:  $(1-x)(0{,}9-x)=0{,}12 \\Leftrightarrow 0{,}9-x-0{,}9x+x^2=0{,}12 \\Leftrightarrow x^2-1{,}9x+0{,}78=0$.<br>Giải phương trình ta được:  $\\hoac{&x=1{,}3 \\text{ (loại vì } x \\le 1)\\\\&x=0{,}6 \\text{ (thỏa mãn)}}$.<br>Vậy $P(A)=0{,}6$ và $P(B)=0{,}6+0{,}1=0{,}7$.<br>Xác suất đội $A$ vượt qua vòng bảng còn đội $B$ không vượt qua vòng bảng là:  $P(A \\cap \\overline{B}) = P(A) \\cdot P(\\overline{B}) = 0{,}6 \\cdot (1-0{,}7) = 0{,}6 \\cdot 0{,}3 = 0{,}18$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho cấp số cộng $(u_n)$ có công sai $d=2$ và biểu thức $A=u_2^2+u_3^2+u_4^2$ đạt giá trị nhỏ nhất. Số $2018$ là số hạng thứ bao nhiêu của cấp số cộng đã cho?", "choices": ["$1011$", "$1012$", "$1013$", "$1014$"], "correctIndex": 1, "explain": "Ta có các số hạng của cấp số cộng tính theo $u_3$ và công sai $d=2$ như sau:  $\\heva{&u_2=u_3-d=u_3-2\\\\&u_4=u_3+d=u_3+2}$<br>Khi đó biểu thức $A$ trở thành:<br>$A=(u_3-2)^2+u_3^2+(u_3+2)^2$<br>$A=u_3^2-4u_3+4+u_3^2+u_3^2+4u_3+4$<br>$A=3u_3^2+8$.<br>Biểu thức $A$ đạt giá trị nhỏ nhất khi $u_3=0$.<br>Với $u_3=0$, ta tìm được số hạng đầu $u_1$:<br>$u_3=u_1+2d \\Rightarrow 0=u_1+2\\cdot 2 \\Rightarrow u_1=-4$.<br>Giả sử $2018$ là số hạng thứ $n$ của cấp số cộng, ta có:  $u_n=u_1+(n-1)d$  $\\Leftrightarrow 2018=-4+(n-1)2$<br>$\\Leftrightarrow 2022=2(n-1)$<br>$\\Leftrightarrow n-1=1011$<br>$\\Leftrightarrow n=1012$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tập nghiệm của bất phương trình $|x^2-4x| < 5$ là $(a; b)$. Tính giá trị của biểu thức $T=a+b$.", "choices": ["$T=3$", "$T=0$", "$T=4$", "$T=-3$"], "correctIndex": 2, "explain": "Bất phương trình tương đương với:  $-5 < x^2-4x < 5 \\Leftrightarrow \\heva{&x^2-4x+5 > 0 \\text{ (luôn đúng vì } \\Delta < 0) \\\\ &x^2-4x-5 < 0}$ <br>Xét $x^2-4x-5 < 0 \\Leftrightarrow (x+1)(x-5) < 0 \\Leftrightarrow -1 < x < 5$. <br>Vậy tập nghiệm là $(-1; 5)$, suy ra $a=-1$, $b=5$. Do đó $T=-1+5=4$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Bác Tư đến siêu thị mua một cái quạt máy và một ấm đun siêu tốc với tổng số tiền theo giá niêm yết là $630$ nghìn đồng. Tuy nhiên, trong tuần lễ tri ân khách hàng nên siêu thị đã giảm giá quạt máy $15\\%$ và giảm giá ấm đun siêu tốc $12\\%$ so với giá niêm yết của từng sản phẩm. Nên Bác Tư chỉ phải trả $543$ nghìn đồng khi mua hai sản phẩm trên. Hỏi giá niêm yết (khi chưa giảm giá) của một cái quạt máy là bao nhiêu?", "choices": ["$250$ nghìn đồng", "$380$ nghìn đồng", "$400$ nghìn đồng", "$350$ nghìn đồng"], "correctIndex": 1, "explain": "Gọi $x$, $y$ lần lượt là giá niêm yết của một cái quạt máy và một ấm đun siêu tốc ($0<x,y<630$, đơn vị: nghìn đồng). <br>Theo đề bài, tổng giá niêm yết của hai sản phẩm là $630$ nghìn đồng, ta có phương trình:  $x+y=630$. $(1)$ <br>Giá của quạt máy sau khi giảm $15\\%$ là: $x-15\\%x = 0{,}85x$. <br>Giá của ấm đun siêu tốc sau khi giảm $12\\%$ là: $y-12\\%y = 0{,}88y$. <br>Vì tổng số tiền Bác Tư thực tế phải trả là $543$ nghìn đồng nên ta có phương trình:  $0{,}85x+0{,}88y=543$. $(2)$ <br>Từ $(1)$ và $(2)$ ta có hệ phương trình:  $\\heva{&x+y=630\\\\&0{,}85x+0{,}88y=543} \\Leftrightarrow \\heva{&x=380\\\\&y=250}$ (thỏa mãn điều kiện). <br>Vậy giá niêm yết của một cái quạt máy là $380$ nghìn đồng."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Gọi $A$ là tập các số tự nhiên gồm ba chữ số đôi một khác nhau được lập từ các chữ số $0$, $1$, $2$, $3$, $4$, $5$, $6$. Lấy ngẫu nhiên từ tập $A$ một số. Tính xác suất $P$ lấy được số chia hết cho $6$.", "choices": ["$P=\\dfrac{13}{60}$", "$P=\\dfrac{17}{45}$", "$P=\\dfrac{2}{9}$", "$P=\\dfrac{11}{45}$"], "correctIndex": 0, "explain": "Số các số tự nhiên có ba chữ số đôi một khác nhau lập từ tập $\\{0, 1, 2, 3, 4, 5, 6\\}$ là:  $n(A) = 6 \\cdot 6 \\cdot 5 = 180$ số.  Không gian mẫu $n(\\Omega)=180$.  Số cần tìm có dạng $\\overline{abc}$ chia hết cho $6$, suy ra $\\overline{abc}$ là số chẵn ($c \\in \\{0, 2, 4, 6\\}$) và $a+b+c$ chia hết cho $3$.<br>a) Trường hợp $c=0$: Các bộ $\\{a, b\\}$ có tổng chia hết cho $3$ là $\\{1, 2\\}$, $\\{1, 5\\}$, $\\{2, 4\\}$, $\\{3, 6\\}$, $\\{4, 5\\}$. Mỗi bộ có $2$ cách xếp $\\Rightarrow 5 \\cdot 2 = 10$ số.  <br>b) Trường hợp $c=2$: Các bộ $\\{a, b\\}$ có tổng chia $3$ dư $1$ là $\\{0, 1\\}$, $\\{0, 4\\}$, $\\{1, 3\\}$, $\\{1, 6\\}$, $\\{3, 4\\}$, $\\{4, 6\\}$. <br>+ Bộ có số $0$: có $1$ cách xếp ($a \\ne 0$) $\\Rightarrow 2$ số.<br>+ Bộ không có số $0$: có $2$ cách xếp $\\Rightarrow 4 \\cdot 2 = 8$ số.<br>Tổng cộng $2+8=10$ số.  <br>c) Trường hợp $c=4$: Các bộ $\\{a, b\\}$ có tổng chia $3$ dư $2$ là $\\{0, 2\\}$, $\\{0, 5\\}$, $\\{1, 4\\}$ (loại vì $b \\ne c$), $\\{2, 3\\}$, $\\{2, 6\\}$, $\\{5, 6\\}$, $\\{1, 1\\}$ (loại). <br>Các bộ thỏa mãn: $\\{0, 2\\}$, $\\{0, 5\\}$, $\\{1, 4\\}$ (loại), $\\{2, 3\\}$, $\\{2, 6\\}$, $\\{3, 5\\}$, $\\{5, 6\\}$.<br>+ Bộ có số $0$: $\\{0, 2\\}$, $\\{0, 5\\} \\Rightarrow 2$ số.<br>+ Bộ không có số $0$: $\\{2, 3\\}$, $\\{2, 6\\}$, $\\{3, 5\\}$, $\\{5, 6\\}$, $\\{1, 1\\}$ (loại) $\\dots$ tính toán các cặp đôi một khác nhau ta có $12$ số.  <br>d) Trường hợp $c=6$: Tương tự ta có $7$ số.<br>Số các số thuận lợi là $n(X) = 10+10+12+7 = 39$.  Xác suất $P=\\dfrac{39}{180}=\\dfrac{13}{60}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho cấp số nhân có các số hạng lần lượt là $\\dfrac{1}{4}$, $\\dfrac{1}{2}$, $1$, $\\dots$, $2048$. Tính tổng $S$ của tất cả các số hạng của cấp số nhân đã cho.", "choices": ["$S=4095$", "$S=4095{,}75$", "$S=4096$", "$S=2047{,}75$"], "correctIndex": 1, "explain": "Ta có cấp số nhân với số hạng đầu $u_1=\\dfrac{1}{4}$ và công bội $q=\\dfrac{u_2}{u_1}=\\dfrac{1}{2}:\\dfrac{1}{4}=2$.<br>Số hạng tổng quát của cấp số nhân là $u_n=u_1 \\cdot q^{n-1}$.<br>Theo đề bài, số hạng cuối cùng là $2048$, ta có:  $2048 = \\dfrac{1}{4} \\cdot 2^{n-1} \\Leftrightarrow 8192 = 2^{n-1} \\Leftrightarrow 2^{13} = 2^{n-1} \\Leftrightarrow n-1=13 \\Leftrightarrow n=14$.<br>Tổng $S$ của $14$ số hạng đầu tiên là:  $S_{14} = \\dfrac{u_1(1-q^{14})}{1-q} = \\dfrac{\\dfrac{1}{4}(1-2^{14})}{1-2} = \\dfrac{\\dfrac{1}{4}(1-16384)}{-1} = \\dfrac{-4095{,}75}{-1} = 4095{,}75$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ có ba góc nhọn, $BC=a$, $AC=b$, $AB=c$ và diện tích là $S$. Tổng $\\cot A+\\cot B+\\cot C$ bằng", "choices": ["$\\dfrac{2(a^2+b^2+c^2)}{S}$", "$\\dfrac{a^2+b^2+c^2}{S}$", "$\\dfrac{a^2+b^2+c^2}{2S}$", "$\\dfrac{a^2+b^2+c^2}{4S}$"], "correctIndex": 3, "explain": "Từ công thức $S=\\dfrac{1}{2}bc\\sin A \\Rightarrow \\sin A=\\dfrac{2S}{bc}$, và $\\cos A=\\dfrac{b^2+c^2-a^2}{2bc}$.<br>Suy ra $\\cot A=\\dfrac{\\cos A}{\\sin A}=\\dfrac{\\dfrac{b^2+c^2-a^2}{2bc}}{\\dfrac{2S}{bc}}=\\dfrac{b^2+c^2-a^2}{4S}$.<br>Tương tự ta cũng có $\\cot B=\\dfrac{a^2+c^2-b^2}{4S}$, $\\cot C=\\dfrac{a^2+b^2-c^2}{4S}$.<br>Vậy $\\cot A+\\cot B+\\cot C=\\dfrac{b^2+c^2-a^2}{4S}+\\dfrac{a^2+c^2-b^2}{4S}+\\dfrac{a^2+b^2-c^2}{4S}=\\dfrac{a^2+b^2+c^2}{4S}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Trong một dự án xây dựng mạng lưới cáp quang, các trạm phát sóng được ký hiệu từ $1$ đến $5$. Bảng số liệu bên cạnh cho biết sự kết nối trực tiếp giữa các trạm (số $1$ nghĩa là có đường truyền trực tiếp, số $0$ nghĩa là không). Một kỹ thuật viên cần tìm một đường đi truyền tín hiệu từ trạm $1$ đến trạm $4$ sao cho qua ít trạm trung gian nhất. Hỏi đường đi ngắn nhất đó đi qua bao nhiêu cạnh?<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$2$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$3$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$4$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$5$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$2$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$3$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$4$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$5$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td></tr></table>", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 1, "explain": "Dựa vào bảng ma trận kề, ta xác định các kết nối trực tiếp:<br>a) Trạm $1$ kết nối trực tiếp với: trạm $2$ và trạm $5$.  <br>b) Trạm $4$ kết nối trực tiếp với: trạm $3$ và trạm $5$.<br>Để đi từ $1$ đến $4$:<br>a) Cách 1: $1 \\to 5 \\to 4$ (Độ dài bằng $2$ cạnh).  <br>b) Cách 2: $1 \\to 2 \\to 3 \\to 4$ (Độ dài bằng $3$ cạnh).  <br>c) Cách 3: $1 \\to 2 \\to 5 \\to 4$ (Độ dài bằng $3$ cạnh).<br>Vậy đường đi ngắn nhất từ trạm $1$ đến trạm $4$ có độ dài bằng $2$ cạnh (qua trạm trung gian $5$)."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biến đổi biểu thức $M=\\sin \\dfrac{\\pi}{16}-\\sin \\dfrac{5\\pi}{16}$ thành tích ta được $M=2\\sin a\\pi \\cos b\\pi$ với $a\\in\\left(-\\dfrac{1}{2};\\dfrac{1}{2}\\right)$ và $b\\in(0;1)$. Khi đó $4a+8b$ bằng bao nhiêu?", "choices": ["$1$", "$2$", "$5$", "$4$"], "correctIndex": 0, "explain": "Ta có công thức biến đổi tổng thành tích: $\\sin u - \\sin v = 2\\cos \\dfrac{u+v}{2} \\sin \\dfrac{u-v}{2}$.<br>Áp dụng: $M = \\sin \\dfrac{\\pi}{16} - \\sin \\dfrac{5\\pi}{16} = 2\\cos \\left(\\dfrac{\\dfrac{\\pi}{16} + \\dfrac{5\\pi}{16}}{2}\\right) \\sin \\left(\\dfrac{\\dfrac{\\pi}{16} - \\dfrac{5\\pi}{16}}{2}\\right)$.<br>$M = 2\\cos \\dfrac{3\\pi}{16} \\sin \\left(-\\dfrac{2\\pi}{16}\\right) = -2\\sin \\dfrac{\\pi}{8} \\cos \\dfrac{3\\pi}{16}$.<br>Để đưa về dạng $M = 2\\sin a\\pi \\cos b\\pi$, ta có $M = 2\\sin \\left(-\\dfrac{1}{8}\\right)\\pi \\cos \\dfrac{3}{16}\\pi$.<br>Suy ra $a = -\\dfrac{1}{8}$ (thỏa mãn $a\\in\\left(-\\dfrac{1}{2};\\dfrac{1}{2}\\right)$) và $b = \\dfrac{3}{16}$ (thỏa mãn $b\\in(0;1)$).<br>Vậy $4a + 8b = 4\\left(-\\dfrac{1}{8}\\right) + 8\\left(\\dfrac{3}{16}\\right) = -\\dfrac{1}{2} + \\dfrac{3}{2} = \\dfrac{2}{2} = 1$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho phương trình $4\\cdot 4^x-9\\cdot 2^{x+1}+8=0$. Gọi $x_1$, $x_2$ là hai nghiệm của phương trình trên. Khi đó tích $x_1x_2$ bằng", "choices": ["$2$", "$-2$", "$-1$", "$0$"], "correctIndex": 1, "explain": "Phương trình đã cho tương đương với:  $$4\\cdot (2^x)^2-18\\cdot 2^x+8=0$$  Đặt $t=2^x$ ($t>0$), phương trình trở thành:  $$4t^2-18t+8=0 \\Leftrightarrow \\hoac{&t=4<br>&t=\\dfrac{1}{2}}$$<br>a) Với $t=4 \\Rightarrow 2^x=4 \\Rightarrow x_1=2$.  <br>b) Với $t=\\dfrac{1}{2} \\Rightarrow 2^x=2^{-1} \\Rightarrow x_2=-1$.<br>Vậy tích hai nghiệm là $x_1x_2=2\\cdot (-1)=-2$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Xét bất phương trình $\\log_2^2(2x)-2(m+1)\\log_2 x-2<0$. Tìm giá trị của tham số $m$ để bất phương trình có nghiệm thuộc khoảng $(\\sqrt{2};+\\infty)$.", "choices": ["$m>0$", "$m<-\\dfrac{3}{4}$", "$m>-\\dfrac{3}{4}$", "$m>-1$"], "correctIndex": 2, "explain": "Điều kiện: $x>0$.<br>Ta có: $\\log_2^2(2x)-2(m+1)\\log_2 x-2<0$<br>$\\Leftrightarrow (\\log_2 x+1)^2-2(m+1)\\log_2 x-2<0$<br>$\\Leftrightarrow \\log_2^2 x+2\\log_2 x+1-2m\\log_2 x-2\\log_2 x-2<0$<br>$\\Leftrightarrow \\log_2^2 x-2m\\log_2 x-1<0 \\quad (*)$.<br>Đặt $t=\\log_2 x$. Với $x\\in(\\sqrt{2};+\\infty)$ thì $t\\in\\left(\\dfrac{1}{2};+\\infty\\right)$.<br>Bất phương trình $(*)$ trở thành: $t^2-2mt-1<0 \\Leftrightarrow 2mt>t^2-1 \\Leftrightarrow 2m>t-\\dfrac{1}{t}$ (vì $t>\\dfrac{1}{2}>0$).<br>Xét hàm số $g(t)=t-\\dfrac{1}{t}$ trên khoảng $\\left(\\dfrac{1}{2};+\\infty\\right)$.<br>Ta có $g'(t)=1+\\dfrac{1}{t^2}>0, \\forall t\\in\\left(\\dfrac{1}{2};+\\infty\\right)$, do đó $g(t)$ là hàm số đồng biến trên $\\left(\\dfrac{1}{2};+\\infty\\right)$.<br>Khi đó $g(t)>g\\left(\\dfrac{1}{2}\\right)=\\dfrac{1}{2}-2=-\\dfrac{3}{2}$.<br>Để bất phương trình có nghiệm trên $\\left(\\dfrac{1}{2};+\\infty\\right)$ thì $2m>\\min g(t)$ trên khoảng đó (hoặc xét tập giá trị của hàm số).<br>Dễ thấy với mọi $m>-\\dfrac{3}{4}$, luôn tồn tại giá trị $t$ đủ gần $\\dfrac{1}{2}$ để bất phương trình $2m>g(t)$ thỏa mãn.<br>Vậy $2m>-\\dfrac{3}{2} \\Leftrightarrow m>-\\dfrac{3}{4}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hai biến cố $A$ và $B$, với $P(A)=0{,}8$, $P(B)=0{,}6$, $P(A|B)=0{,}7$. Tính $P(\\overline{A}|\\overline{B})$.", "choices": ["$0{,}15$", "$0{,}25$", "$0{,}05$", "$0{,}45$"], "correctIndex": 2, "explain": "Ta có công thức xác suất có điều kiện: $P(A|B)=\\dfrac{P(A \\cap B)}{P(B)}$.<br>Suy ra $P(A \\cap B) = P(A|B) \\cdot P(B) = 0{,}7 \\cdot 0{,}6 = 0{,}42$.<br>Ta cần tính $P(\\overline{A}|\\overline{B}) = \\dfrac{P(\\overline{A} \\cap \\overline{B})}{P(\\overline{B})}$.<br>Theo quy tắc De Morgan: $\\overline{A} \\cap \\overline{B} = \\overline{A \\cup B}$.<br>Do đó $P(\\overline{A} \\cap \\overline{B}) = P(\\overline{A \\cup B}) = 1 - P(A \\cup B)$.<br>Mà $P(A \\cup B) = P(A) + P(B) - P(A \\cap B) = 0{,}8 + 0{,}6 - 0{,}42 = 0{,}98$.<br>Suy ra $P(\\overline{A} \\cap \\overline{B}) = 1 - 0{,}98 = 0{,}02$.<br>Xác suất của biến cố đối $\\overline{B}$ là: $P(\\overline{B}) = 1 - P(B) = 1 - 0{,}6 = 0{,}4$.<br>Vậy $P(\\overline{A}|\\overline{B}) = \\dfrac{0{,}02}{0{,}4} = 0{,}05$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biết rằng $b<0$, $a+b=5$ và $\\lim\\limits_{x\\to 0}\\dfrac{\\sqrt{ax+1}-\\sqrt{1-b+x}}{x+1}=-2$. Khẳng định nào dưới đây sai?", "choices": ["$8<a<13$", "$b<-1$", "$a^2+b^2>10$", "$a-b>0$"], "correctIndex": 0, "explain": "Ta có:  $\\lim\\limits_{x\\to 0}\\dfrac{\\sqrt{ax+1}-\\sqrt{1-b+x}}{x+1}=\\dfrac{\\sqrt{a\\cdot 0+1}-\\sqrt{1-b+0}}{0+1}=1-\\sqrt{1-b}$.<br>Theo giả thiết:  $1-\\sqrt{1-b}=-2\\Leftrightarrow\\sqrt{1-b}=3\\Leftrightarrow 1-b=9\\Leftrightarrow b=-8$.<br>Vì $b=-8<0$ (thỏa mãn điều kiện).<br>Thay $b=-8$ vào phương trình $a+b=5$, ta được:  $a-8=5\\Leftrightarrow a=13$.<br>Xét các khẳng định:<br>a) $8<a<13 \\Leftrightarrow 8<13<13$ (Sai).  <br>b) $b<-1 \\Leftrightarrow -8<-1$ (Đúng).  <br>c) $a^2+b^2=13^2+(-8)^2=233>10$ (Đúng).  <br>d) $a-b=13-(-8)=21>0$ (Đúng).<br>Vậy khẳng định sai là $8<a<13$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Hai bạn Hùng và Dũng cùng xuất phát từ trường đạp xe đến sân vận động để xem bóng đá. Biết rằng nếu cả hai cùng đạp xe bình thường thì vận tốc của Hùng gấp $2$ lần vận tốc của Dũng. Khi bắt đầu đi, cả hai cùng xuất phát bằng xe đạp. Nhưng sau khi đi được $30$ phút, xe của Hùng bị hỏng nên bạn ấy phải gửi xe lại và đi bộ nốt quãng đường còn lại đến sân vận động. Biết rằng cả hai bạn đến sân vận động cùng một lúc, vận tốc đạp xe của Dũng lại gấp $4$ lần vận tốc đi bộ của Hùng. Hỏi thời gian hai bạn đi từ trường đến sân vận động là bao nhiêu phút? (Giả sử vận tốc đạp xe của hai bạn và vận tốc đi bộ của Hùng không đổi trong suốt quá trình di chuyển, và thời gian bạn Hùng gửi xe là không đáng kể).", "choices": ["$45$ phút", "$70$ phút", "$60$ phút", "$75$ phút"], "correctIndex": 1, "explain": "Gọi $v$ là vận tốc đi bộ của Hùng ($v>0$).<br>Theo đề bài, vận tốc đạp xe của Dũng là $4v$.<br>Vận tốc đạp xe của Hùng là $2 \\cdot 4v = 8v$.<br>Gọi $t$ (phút) là tổng thời gian hai bạn đi từ trường đến sân vận động ($t>30$).<br>Vì hai bạn đến sân vận động cùng một lúc nên thời gian Dũng đi là $t$ phút, quãng đường từ trường đến sân vận động là: $S = 4v \\cdot t$.<br>Trong $30$ phút đầu, Hùng đi được quãng đường là: $S_1 = 8v \\cdot 30 = 240v$.<br>Quãng đường còn lại Hùng phải đi bộ là: $S_2 = S - S_1 = 4vt - 240v = v(4t - 240)$.<br>Thời gian Hùng đi bộ quãng đường còn lại là: $t_2 = \\dfrac{S_2}{v} = \\dfrac{v(4t-240)}{v} = 4t - 240$ (phút).<br>Tổng thời gian đi của Hùng là: $30 + (4t - 240) = 4t - 210$ (phút).<br>Vì hai bạn đến cùng lúc nên ta có phương trình:  $t = 4t - 210 \\Leftrightarrow 3t = 210 \\Leftrightarrow t = 70$ (phút)."}]}, {"noiDungChung": "Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình bình hành, $AB=3$, $AD=4$, $\\widehat{BAD}=120^{\\circ}$. Cạnh bên $SA=2\\sqrt{3}$ và vuông góc với mặt phẳng đáy. Gọi $M$, $N$, $P$ lần lượt là trung điểm các cạnh $SA$, $AD$, $BC$.", "cauHoi": [{"question": "Tính thể tích $V$ của khối chóp $S.ABCD$.", "choices": ["$V=24$", "$V=4\\sqrt{3}$", "$V=12$", "$V=36$"], "correctIndex": 2, "explain": "Diện tích đáy hình bình hành $ABCD$:  $S_{ABCD} = AB \\cdot AD \\cdot \\sin \\widehat{BAD} = 3 \\cdot 4 \\cdot \\sin 120^{\\circ} = 12 \\cdot \\dfrac{\\sqrt{3}}{2} = 6\\sqrt{3}$.<br>Thể tích khối chóp $S.ABCD$:  $V = \\dfrac{1}{3} S_{ABCD} \\cdot SA = \\dfrac{1}{3} \\cdot 6\\sqrt{3} \\cdot 2\\sqrt{3} = 12$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\usetikzlibrary{calc}\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (A) at (0,0);\n\t\t\t\t\t\\coordinate (B) at (-1.5,-1.2);\n\t\t\t\t\t\\coordinate (D) at (4,0);\n\t\t\t\t\t\\coordinate (C) at ($(B)+(D)-(A)$);\n\t\t\t\t\t\\coordinate (S) at (0,4); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (M) at ($(S)!0.5!(A)$);\n\t\t\t\t\t\\coordinate (N) at ($(A)!0.5!(D)$);\n\t\t\t\t\t\\coordinate (P) at ($(B)!0.5!(C)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed] (S)--(A) (A)--(B) (A)--(D) (M)--(N) (N)--(P) (A)--(C);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick] (S)--(B) (S)--(C) (S)--(D) (B)--(C) (C)--(D) (M)--(P);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw (A) ++(0,0.3) -- ++(0.3,0) -- ++(0,-0.3);\n\t\t\t\t\t\\foreach \\p in {S,A,B,C,D,M,N,P}\n\t\t\t\t\t\\fill[red] (\\p) circle (1.5pt);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\node[above] at (S) {$S$};\n\t\t\t\t\t\\node[below left] at (A) {$A$};\n\t\t\t\t\t\\node[below left] at (B) {$B$};\n\t\t\t\t\t\\node[below right] at (C) {$C$};\n\t\t\t\t\t\\node[right] at (D) {$D$};\n\t\t\t\t\t\\node[left] at (M) {$M$};\n\t\t\t\t\t\\node[above] at (N) {$N$};\n\t\t\t\t\t\\node[below] at (P) {$P$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Tính khoảng cách $d$ từ điểm $D$ đến mặt phẳng $(SAB)$.", "choices": ["$d=2$", "$d=2\\sqrt{3}$", "$d=4$", "$d=\\sqrt{3}$"], "correctIndex": 1, "explain": "Vì $AD \\parallel BC$ và $SA \\perp (ABCD) \\Rightarrow SA \\perp AD$.<br>Mặt khác, trong mặt phẳng đáy $(ABCD)$, kẻ $DH \\perp AB$ tại $H$.<br>Ta có $\\widehat{DAB} = 120^{\\circ} \\Rightarrow \\widehat{DAH} = 60^{\\circ}$ (góc kề bù).<br>Trong tam giác vuông $ADH$: $DH = AD \\cdot \\sin 60^{\\circ} = 4 \\cdot \\dfrac{\\sqrt{3}}{2} = 2\\sqrt{3}$.<br>Vì $\\heva{&DH \\perp AB \\\\ &DH \\perp SA \\text{ (do } SA \\perp \\text{ đáy)}} \\Rightarrow DH \\perp (SAB)$.<br>Vậy $d(D, (SAB)) = DH = 2\\sqrt{3}$."}, {"question": "Gọi $\\alpha$ là góc giữa hai mặt phẳng $(SBC)$ và $(MNP)$. Tính $\\cos \\alpha$.", "choices": ["$\\cos \\alpha = \\dfrac{\\sqrt{3}}{3}$", "$\\cos \\alpha = \\dfrac{1}{\\sqrt{2}}$", "$\\cos \\alpha = \\dfrac{2}{\\sqrt{2}}$", "$\\cos \\alpha = \\dfrac{\\sqrt{21}}{7}$"], "correctIndex": 1, "explain": "Ta có: $(S A D) \\cap(S B C)=S x / / A D / / B C$.<br>Gọi $I$ là trung điếm của $S B$. Ta có: $\\left\\{\\begin{array}{l}M I / / N P / / A B \\\\ M I=\\dfrac{N P}{2}\\end{array}\\right.$.<br>Dễ dàng chứng minh được $I P, M N, S x$ đồng quy tại $J$. Như vậy $I$ là trung điểm của $J P, M$ là trung điểm của $N$.<br>Gọi $\\varphi$ là góc giừa hai mặt phẳng (SBC) và (MNP). Ta có: $\\sin \\varphi=\\dfrac{d(M,(S B C))}{d(M, I P)}$.<br>$$  d(M,(S B C))=\\dfrac{1}{2} d(A,(S B C))  $$<br>Ha $A K \\perp B C, A E \\perp S K \\Rightarrow A E \\perp(S B C) \\Rightarrow d(A,(S B C))=A E$.<br>$$  A K=A B \\cdot \\sin \\overline{A B K}=3 \\cdot \\sin 60^{\\circ}=\\dfrac{3 \\sqrt{3}}{2}  $$  $$  \\Delta S A K: \\dfrac{1}{A E^2}=\\dfrac{1}{A S^2}+\\dfrac{1}{A K^2}=\\dfrac{1}{12}+\\dfrac{4}{27}=\\dfrac{25}{108} \\Rightarrow A E=\\dfrac{6 \\sqrt{3}}{5} \\Rightarrow d(M,(S B C))=\\dfrac{3 \\sqrt{3}}{5} .  $$<br>Ta có $d(M, P I)=\\dfrac{1}{2} d(N, P I)$.<br>$$  \\begin{aligned}  & \\triangle A B C: A C^2=A B^2+C B^2-2 A B \\cdot C B \\cdot \\cos 60^{\\circ}=13 \\Rightarrow A C=\\sqrt{13} <br>& J P=2 I P=S C=\\sqrt{13+12}=5, J N=2 M N=S D=2 \\sqrt{7}, P N=A B=3 \\Rightarrow S_{J R x}=3 \\sqrt{6}  \\end{aligned}  $$<br>Mặt khác $S_{J D V}=\\dfrac{1}{2} d(N, J P), J P \\Rightarrow d(N, J P)=\\dfrac{6 \\sqrt{6}}{5} \\Rightarrow d(M, I P)=\\dfrac{3 \\sqrt{6}}{5}$.<br>Vây $\\sin \\varphi=\\dfrac{\\sqrt{2}}{2} \\Rightarrow \\varphi=45^{\\circ}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1.2, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\usetikzlibrary{calc}\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (A) at (0,0);\n\t\t\t\t\t\\coordinate (B) at (-1.5,-2);\n\t\t\t\t\t\\coordinate (D) at (4,0);\n\t\t\t\t\t\\coordinate (C) at ($(B)+(D)-(A)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (S) at (0,4); \n\t\t\t\t\t\\coordinate (M) at ($(S)!0.5!(A)$); \n\t\t\t\t\t\\coordinate (N) at ($(A)!0.5!(D)$); \n\t\t\t\t\t\\coordinate (I) at ($(S)!0.5!(B)$); \n\t\t\t\t\t\\coordinate (P) at ($(B)!0.5!(C)$); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (J) at ($(M)+(M)-(N)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (K) at ($(B)!0.4!(P)$); \n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (E) at ($(S)!0.7!(K)$); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed, thin] (S)--(A) (A)--(B) (A)--(D) (A)--(C) (A)--(P) (N)--(P) (M)--(N) (A)--(K) (I)--(P);\n\t\t\t\t\t\\draw[dashed] (J)--(M) (J)--(I) (M)--(I) (A)--(E); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick] (S)--(B) (S)--(C) (S)--(D) (B)--(C) (C)--(D) (S)--(K);\n\t\t\t\t\t\\draw[thick] (J)--(P); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick, -] (S) -- ($(S)!1.8!(J)$) node[above] {$x$};\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw (A) ++(0,0.25) -- ++(0.25,0) -- ++(0,-0.25);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\foreach \\p in {S,A,B,C,D,M,N,P,I,J,K,E}\n\t\t\t\t\t\\fill[black] (\\p) circle (1.2pt);\n\t\t\t\t\t\n\t\t\t\t\t\\node[above right] at (S) {$S$};\n\t\t\t\t\t\\node[below left] at (A) {$A$};\n\t\t\t\t\t\\node[below left] at (B) {$B$};\n\t\t\t\t\t\\node[below right] at (C) {$C$};\n\t\t\t\t\t\\node[right] at (D) {$D$};\n\t\t\t\t\t\\node[right] at (M) {$M$};\n\t\t\t\t\t\\node[above right] at (N) {$N$};\n\t\t\t\t\t\\node[below] at (P) {$P$};\n\t\t\t\t\t\\node[left] at (I) {$I$};\n\t\t\t\t\t\\node[above] at (J) {$J$};\n\t\t\t\t\t\\node[below] at (K) {$K$};\n\t\t\t\t\t\\node[left] at (E) {$E$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Một xưởng sản xuất quà lưu niệm dự định làm hai loại sản phẩm: tranh cát và tượng đá để gây quỹ thiện nguyện. Để làm một bức tranh cát cần $3$ giờ làm việc và $1$ kg nguyên liệu. Để làm một bức tượng đá cần $2$ giờ làm việc và $3$ kg nguyên liệu. Xưởng có tối đa $18$ giờ làm việc và $21$ kg nguyên liệu. Ngoài ra, do nhu cầu thị trường, xưởng dự định sản xuất ít nhất $2$ bức tranh cát và ít nhất $1$ bức tượng đá. Gọi $x$, $y$ lần lượt là số lượng tranh cát và tượng đá ($x, y \\in \\mathbb{N}$).", "cauHoi": [{"question": "Viết hệ bất phương trình mô tả các điều kiện ràng buộc của bài toán.", "choices": ["$\\heva{&x \\ge 2 \\\\ &y \\ge 1 \\\\ &3x+2y \\le 18 \\\\ &x+3y \\le 21}$", "$\\heva{&x \\ge 0 \\\\ &y \\ge 0 \\\\ &3x+2y \\le 18 \\\\ &x+3y \\le 21}$", "$\\heva{&x \\ge 2 \\\\ &y \\ge 1 \\\\ &3x+2y \\ge 18 \\\\ &x+3y \\ge 21}$", "$\\heva{&x \\ge 1 \\\\ &y \\ge 2 \\\\ &3x+2y \\le 21 \\\\ &x+3y \\le 18}$"], "correctIndex": 0, "explain": "Dựa vào các dữ kiện của bài toán, ta có các ràng buộc sau:<br>a) Số lượng tối thiểu: $x \\ge 2$, $y \\ge 1$.  <br>b) Giới hạn giờ làm việc: Mỗi bức tranh cát cần $3$ giờ, mỗi bức tượng đá cần $2$ giờ. Tổng thời gian không quá $18$ giờ nên $3x+2y \\le 18$.  <br>c) Giới hạn nguyên liệu: Mỗi bức tranh cát cần $1$ kg, mỗi bức tượng đá cần $3$ kg. Tổng khối lượng nguyên liệu không quá $21$ kg nên $x+3y \\le 21$.<br>Hệ bất phương trình mô tả bài toán là: $\\heva{&x \\ge 2 \\\\ &y \\ge 1 \\\\ &3x+2y \\le 18 \\\\ &x+3y \\le 21}$."}, {"question": "Biết rằng mỗi bức tranh cát bán lãi $150$ ngàn đồng, mỗi bức tượng đá bán lãi $200$ ngàn đồng. Lợi nhuận lớn nhất mà xưởng có thể thu được là bao nhiêu ngàn đồng?", "choices": ["$1{,}250$", "$1{,}400$", "$1{,}500$", "$1{,}100$"], "correctIndex": 2, "explain": "Hàm mục tiêu là lợi nhuận: $F(x, y)=150x+200y$.  Miền nghiệm của hệ bất phương trình là miền tứ giác giới hạn bởi các đường thẳng $d_1 \\colon 3x+2y=18$, $d_2 \\colon x+3y=21$, $x=2$ và $y=1$.  Các đỉnh của miền nghiệm này là:<br>a) $A(2, 1)$ là giao của $x=2$ và $y=1$.  <br>b) $B(2, 6)$ là giao của $x=2$ và $3x+2y=18$.  <br>c) $C\\left(\\dfrac{12}{7}, \\dfrac{45}{7}\\right)$ là giao của $3x+2y=18$ và $x+3y=21$. Tuy nhiên, do điều kiện $x \\ge 2$, điểm này nằm ngoài miền nghiệm.  <br>d) $D(4, 3)$ là giao của $3x+2y=18$ và $x+3y=21$ (điểm này không nguyên, nhưng ta xét các điểm nguyên lân cận). Thực tế, giao điểm của $3x+2y=18$ và $x+3y=21$ là $M(1{,}7, 6{,}4)$ không thuộc miền nghiệm do $x \\ge 2$.  <br>e) $E\\left(\\dfrac{16}{3}, 1\\right)$ là giao của $3x+2y=18$ và $y=1$.<br>Vì $x, y$ là các số nguyên, các điểm nguyên $(x, y)$ nằm trong miền nghiệm bao gồm: $(2, 1)$, $(2, 2)$, $(2, 3)$, $(2, 4)$, $(2, 5)$, $(2, 6)$, $(3, 1)$, $(3, 2)$, $(3, 3)$, $(3, 4)$, $(4, 1)$, $(4, 2)$, $(4, 3)$, $(5, 1)$.  Tính giá trị $F(x, y)$ tại các điểm biên nguyên:<br>a) Tại $(2, 1) \\colon F=150(2)+200(1)=500$.  <br>b) Tại $(2, 6) \\colon F=150(2)+200(6)=1500$. (Thỏa mãn $3 \\cdot 2 + 2 \\cdot 6 = 18 \\le 18$ và $2 + 3 \\cdot 6 = 20 \\le 21$).  <br>c) Tại $(5, 1) \\colon F=150(5)+200(1)=950$.  <br>d) Tại $(4, 3) \\colon F=150(4)+200(3)=1200$.<br>So sánh các giá trị, lợi nhuận lớn nhất là $1500$ ngàn đồng khi sản xuất $2$ bức tranh cát và $6$ bức tượng đá.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, x=0.6cm, y=0.6cm, font=\\footnotesize]\n\t\t\t\t\t\\def\\xmin{-1} \\def\\xmax{8}\n\t\t\t\t\t\\def\\ymin{-1} \\def\\ymax{8}\n\t\t\t\t\t\\draw[color=gray!20] (\\xmin, \\ymin) grid (\\xmax, \\ymax);\n\t\t\t\t\t\\draw[->, thick] (\\xmin, 0) -- (\\xmax, 0) node[below] {$x$};\n\t\t\t\t\t\\draw[->, thick] (0, \\ymin) -- (0, \\ymax) node[left] {$y$};\n\t\t\t\t\t\\node[below left] at (0, 0) {$O$};\n\t\t\t\t\t\\begin{scope}\n\t\t\t\t\t\t\\clip (2, 1) -- (5.33, 1) -- (2, 6) -- cycle;\n\t\t\t\t\t\t\\fill[gray!30] (2, 1) -- (5.33, 1) -- (2, 6) -- cycle;\n\t\t\t\t\t\\end{scope}\n\t\t\t\t\t\\draw[thick, blue] plot[domain=0:6] (\\x, {(18-3*\\x)/2}) node[right] {$d_1$};\n\t\t\t\t\t\\draw[thick, red] plot[domain=0:8] (\\x, {(21-\\x)/3}) node[above] {$d_2$};\n\t\t\t\t\t\\draw[thick, dashed] (2, \\ymin) -- (2, \\ymax) node[above] {$x=2$};\n\t\t\t\t\t\\draw[thick, dashed] (\\xmin, 1) -- (\\xmax, 1) node[right] {$y=1$};\n\t\t\t\t\t\\fill (2, 6) circle (2pt) node[above right] {$B(2, 6)$};\n\t\t\t\t\t\\fill (2, 1) circle (2pt) node[below left] {$A$};\n\t\t\t\t\t\\fill (5.33, 1) circle (2pt) node[below] {$E$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Một chi tiết máy làm bằng thép có hình dạng là một khối tròn xoay. Mặt cắt của chi tiết này là hình phẳng giới hạn bởi đường cong $(C) \\colon y = \\sqrt{x} \\cdot \\sin x$, trục hoành và hai đường thẳng $x = 0$, $x = \\pi$.", "cauHoi": [{"question": "Thiết kế yêu cầu tính thể tích $V$ của chi tiết máy khi quay hình phẳng trên quanh trục $Ox$. Giá trị của $V$ là", "choices": ["$V = \\dfrac{\\pi^3}{4}$", "$V = \\dfrac{\\pi^3}{4} - \\dfrac{\\pi}{2}$", "$V = \\dfrac{\\pi^2}{2}$", "$V = \\dfrac{\\pi^3}{2} - \\pi$"], "correctIndex": 0, "explain": "Thể tích khối tròn xoay là: $V = \\pi \\int\\limits_{0}^{\\pi} y^2 dx = \\pi \\int\\limits_{0}^{\\pi} x \\cdot \\sin^2 x dx= \\dfrac{\\pi^3}{4}$."}, {"question": "Giả sử chi tiết máy này được cắt ra từ một khối thép hình trụ có bán kính đáy $R = 2$ cm và chiều dài $L = \\pi$ cm. Tính tỉ lệ thể tích giữa chi tiết máy và khối thép hình trụ ban đầu (làm tròn đến $2$ chữ số thập phân).", "choices": ["$0{,}15$", "$0{,}20$", "$0{,}25$", "$0{,}30$"], "correctIndex": 1, "explain": "Thể tích khối trụ thép ban đầu là: $V_{tr} = \\pi \\cdot R^2 \\cdot L = \\pi \\cdot 2^2 \\cdot \\pi = 4\\pi^2$.  <br>Thể tích chi tiết máy là: $V = \\dfrac{\\pi^3}{4}$.  <br>Tỉ số thể tích: $\\dfrac{V}{V_{tr}} = \\dfrac{\\pi^3/4}{4\\pi^2} = \\dfrac{\\pi}{16} \\approx \\dfrac{3{,}1416}{16} \\approx 0{,}196$.  <br>Làm tròn đến $2$ chữ số thập phân ta được $0{,}20$."}]}, {"noiDungChung": "Cho hàm số $y=f(x)=(x^2-3x+2)^{\\sqrt{3}}$ có đồ thị là $(C)$.", "cauHoi": [{"question": "Tìm tập xác định $D$ của hàm số đã cho.", "choices": ["$D=\\mathbb{R}\\setminus\\{1;2\\}$", "$D=(1;2)$", "$D=(-\\infty;1)\\cup(2;+\\infty)$", "$D=\\mathbb{R}$"], "correctIndex": 2, "explain": "Hàm số lũy thừa với số mũ không nguyên xác định khi cơ số dương.  Điều kiện: $x^2-3x+2>0\\Leftrightarrow\\hoac{&x<1\\\\&x>2.}$  Vậy tập xác định là $D=(-\\infty;1)\\cup(2;+\\infty)$."}, {"question": "Khẳng định nào sau đây là đúng khi nói về tiệm cận của đồ thị hàm số $(C)$?", "choices": ["Đồ thị $(C)$ có một tiệm cận ngang và hai tiệm cận đứng", "Đồ thị $(C)$ có đúng hai tiệm cận đứng là $x=1$ và $x=2$", "Đồ thị $(C)$ có một tiệm cận ngang là $y=0$", "Đồ thị $(C)$ không có tiệm cận đứng và không có tiệm cận ngang"], "correctIndex": 3, "explain": "Xét giới hạn tại vô cực: $\\lim\\limits_{x\\to\\pm\\infty}(x^2-3x+2)^{\\sqrt{3}}=+\\infty$ nên đồ thị không có tiệm cận ngang.<br>Xét giới hạn tại các biên của tập xác định:  $\\lim\\limits_{x\\to 1^-}(x^2-3x+2)^{\\sqrt{3}}=0$ và $\\lim\\limits_{x\\to 2^+}(x^2-3x+2)^{\\sqrt{3}}=0$.<br>Vì các giới hạn này đều hữu hạn nên đồ thị $(C)$ không có tiệm cận đứng."}, {"question": "Tìm số tiếp tuyến của đồ thị $(C)$ vuông góc với đường thẳng $d: y=-\\dfrac{2}{3\\sqrt{3}\\cdot 2^{\\sqrt{3}-1}}x+2026$.", "choices": ["$0$", "$1$", "$2$", "$3$"], "correctIndex": 1, "explain": "Đường thẳng $d$ có hệ số góc $k_d=-\\dfrac{2}{3\\sqrt{3}\\cdot 2^{\\sqrt{3}-1}}$.<br>Gọi $\\Delta$ là tiếp tuyến vuông góc với $d$, khi đó hệ số góc của $\\Delta$ là:  $k_{\\Delta}=-\\dfrac{1}{k_d}=\\dfrac{3\\sqrt{3}\\cdot 2^{\\sqrt{3}-1}}{2} = 3\\sqrt{3}\\cdot 2^{\\sqrt{3}-2}$.<br>Số tiếp tuyến thỏa mãn bằng số nghiệm $x\\in D$ của phương trình $f'(x)=k_{\\Delta}$.<br>Xét phương trình $f'(x)=k_{\\Delta}$ trên $D=(-\\infty;1)\\cup(2;+\\infty)$.<br>Ta có $f'(x)=\\sqrt{3}(x^2-3x+2)^{\\sqrt{3}-1}(2x-3)$.<br>Bảng biến thiên của hàm số $f(x)$:<br>Dựa vào BBT và biểu thức đạo hàm:<br>a) Trên $(2;+\\infty)$, $f'(x)$ là hàm liên tục và tăng từ $0$ đến $+\\infty$. Do đó phương trình $f'(x)=k_{\\Delta}$ (với $k_{\\Delta}>0$) có duy nhất $1$ nghiệm.  <br>b) Trên $(-\\infty;1)$, $f'(x)<0$ nên phương trình $f'(x)=k_{\\Delta}$ vô nghiệm.<br>Vậy có đúng $1$ tiếp tuyến thỏa mãn.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>"}]}, {"noiDungChung": "Trong không gian với hệ tọa độ $Oxyz$, cho các điểm $A(2;3;0)$, $B(0;-\\sqrt{2};0)$, $M\\left(\\dfrac{6}{5};-\\sqrt{2};2\\right)$ và đường thẳng $d\\colon\\heva{&x=t\\\\&y=0\\\\&z=2-t}$.", "cauHoi": [{"question": "Có bao nhiêu khẳng định đúng trong các khẳng định dưới đây?<br>a) Đường thẳng $d$ đi qua điểm $K(2;0;0)$.  <br>b) Véc-tơ pháp tuyến của mặt phẳng $(Oxy)$ là $\\vec{n}=(0;0;1)$  <br>c) Khoảng cách từ điểm $A$ đến mặt phẳng $(Oxy)$ bằng $0$  <br>d) Tam giác $ABC$ luôn là tam giác cân với mọi điểm $C$ thuộc $d$", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 1, "explain": "a) Thay $t=2$ vào phương trình $d$, ta được $x=2, y=0, z=0$. Vậy $K(2;0;0)\\in d$.  <br>b) Mặt phẳng $(Oxy)$ có phương trình $z=0$, nên VTPT là $\\vec{n}=(0;0;1)$.  <br>c) Điểm $A(2;3;0)$ có cao độ $z=0$, nên $A \\in (Oxy)$, khoảng cách bằng $0$.  <br>d) Tam giác $ABC$ chỉ cân tại một số vị trí đặc biệt của $C$ trên $d$, không thể luôn cân với mọi $t$."}, {"question": "Biết tọa độ điểm $C(a,0,c)$ thuộc đường thẳng $d$ sao cho chu vi tam giác $ABC$ đạt giá trị nhỏ nhất. Tính $a+c$", "choices": ["$-2$", "$2$", "$4$", "$-3$"], "correctIndex": 1, "explain": "Chu vi tam giác $ABC$ là $P=AB+BC+CA$. Vì $A, B$ cố định nên $P$ nhỏ nhất khi $CA+CB$ nhỏ nhất.<br>Điểm $C\\in d \\Rightarrow C(t;0;2-t)$.<br>Ta có $CA+CB=\\sqrt{(t-2)^2+(-3)^2+(2-t)^2} + \\sqrt{t^2+(\\sqrt{2})^2+(2-t)^2}$<br>$=\\sqrt{2(t-2)^2+9} + \\sqrt{2t^2-4t+6} = \\sqrt{2(t-2)^2+9} + \\sqrt{2(t-1)^2+4}$.<br>Sử dụng bất đẳng thức Minkowski hoặc đạo hàm, ta tìm được giá trị $t=\\dfrac{2}{3}$ để tổng khoảng cách nhỏ nhất.<br>Vậy tọa độ điểm $C\\left(\\dfrac{2}{3};0;\\dfrac{4}{3}\\right)$. Vậy $a+c=2$"}, {"question": "Với điểm $C$ tìm được ở câu trên, độ dài đoạn thẳng $CM$ xấp xỉ", "choices": ["$2,2$", "$0,6$", "$1,65$", "$2$"], "correctIndex": 2, "explain": "Từ câu trước, ta có $C\\left(\\dfrac{2}{3};0;\\dfrac{4}{3}\\right)$. Điểm $M\\left(\\dfrac{6}{5};-\\sqrt{2};2\\right)$.<br>Độ dài đoạn thẳng $CM$ là:<br>$CM=\\sqrt{\\left(\\dfrac{6}{5}-\\dfrac{2}{3}\\right)^2+(-\\sqrt{2}-0)^2+\\left(2-\\dfrac{4}{3}\\right)^2}$<br>$CM=\\sqrt{\\left(\\dfrac{8}{15}\\right)^2+2+\\left(\\dfrac{2}{3}\\right)^2} = \\sqrt{\\dfrac{64}{225}+2+\\dfrac{4}{9}} = \\sqrt{\\dfrac{64+450+100}{225}} = \\sqrt{\\dfrac{614}{225}}$."}]}, {"noiDungChung": "Trong mặt phẳng với hệ tọa độ $Oxy$, cho điểm $M(3;2)$. Một đường thẳng $\\Delta$ thay đổi đi qua $M$ cắt các tia $Ox$, $Oy$ lần lượt tại $A(a;0)$ và $B(0;b)$ với $a,b>0$ sao cho $OA+OB=12$.", "cauHoi": [{"question": "Xác định hệ thức liên hệ giữa $a$ và $b$ để đường thẳng $\\Delta$ luôn đi qua điểm $M(3;2)$.", "choices": ["$\\dfrac{a}{3}+\\dfrac{b}{2}=1$", "$\\dfrac{3}{a}+\\dfrac{2}{b}=1$", "$3a+2b=1$", "$\\dfrac{a-3}{a}+\\dfrac{b-2}{b}=0$"], "correctIndex": 1, "explain": "Phương trình đường thẳng $\\Delta$ đi qua $A(a;0)$ và $B(0;b)$ có dạng phương trình đoạn chắn: $\\dfrac{x}{a}+\\dfrac{y}{b}=1$.<br>Vì $M(3;2)\\in\\Delta$ nên ta có: $\\dfrac{3}{a}+\\dfrac{2}{b}=1$."}, {"question": "Tính độ dài đoạn thẳng $AB$ biết rằng tam giác $OAB$ cân tại $O$.", "choices": ["$AB=6$", "$AB=5\\sqrt{2}$", "$AB=6\\sqrt{2}$", "$AB=12$"], "correctIndex": 2, "explain": "Tam giác $OAB$ cân tại $O$ và $a,b>0$ nên $a=b$.<br>Mà $OA+OB=12\\Rightarrow a+b=12\\Rightarrow a=b=6$.  Khi đó $A(6;0)$, $B(0;6)$.<br>Độ dài $AB=\\sqrt{(0-6)^2+(6-0)^2}=6\\sqrt{2}$."}, {"question": "Trong các đường thẳng $\\Delta$ thỏa mãn $OA+OB=12$, đường thẳng nào tạo với hai trục tọa độ một tam giác có diện tích lớn nhất?", "choices": ["$x+3y-9=0$", "$x+y-5=0$", "$2x+y-10=0$", "$2x+y-8=0$"], "correctIndex": 3, "explain": "Ta có $OA=a$, $OB=b$. Theo giả thiết $a+b=12\\Rightarrow b=12-a$.<br>Thay vào điều kiện ở câu trên: $\\dfrac{3}{a}+\\dfrac{2}{12-a}=1 \\Leftrightarrow 3(12-a)+2a=a(12-a)$.<br>$\\Leftrightarrow 36-a=12a-a^2 \\Leftrightarrow a^2-13a+36=0 \\Leftrightarrow \\hoac{&a=9 \\Rightarrow b=3\\\\&a=4 \\Rightarrow b=8.}$<br>Vậy $A(9;0)$, $B(0;3)$ hoặc $A(4;0)$, $B(0;8)$.<br>Diện tích tam giác $OAB$ là $S=\\dfrac{1}{2}ab$.<br>Với $a=9$, $b=3$ thì $S=\\dfrac{1}{2}\\cdot 9\\cdot 3=13{,}5$.<br>Với $a=4$, $b=8$ thì $S=\\dfrac{1}{2}\\cdot 4\\cdot 8=16$.<br>So sánh hai trường hợp, diện tích lớn nhất bằng $16$ khi $a=4$, $b=8$.<br>Phương trình đường thẳng khi đó: $\\dfrac{x}{4}+\\dfrac{y}{8}=1 \\Leftrightarrow 2x+y-8=0$."}]}, {"noiDungChung": "Một bếp trưởng đang thiết kế thực đơn nếm thử đặc biệt gồm đúng $5$ món ăn, trong đó có $1$ món được chọn làm \"món đặc biệt\". Các món được lựa chọn từ hai nhóm: nhóm món Mặn gồm các món $F$, $G$, $J$, $K$, $M$ và nhóm món Ngọt gồm các món $P$, $Q$, $R$, $S$. Các điều kiện lựa chọn phải được thỏa mãn như sau:<br>a) Trong mỗi nhóm (Mặn và Ngọt) phải có ít nhất $2$ món được chọn.  <br>b) Món đặc biệt phải thuộc nhóm có đúng $2$ đại diện trong thực đơn.  <br>c) Nếu món $F$ được chọn thì món $Q$ cũng phải được chọn.  <br>d) Nếu món $G$ được chọn thì món $K$ cũng phải được chọn.  <br>e) Nếu món $J$ hoặc $M$ được chọn thì món còn lại cũng phải được chọn.  <br>f) Món $M$ và món $P$ không thể cùng xuất hiện trong một thực đơn.", "cauHoi": [{"question": "Trong số các lựa chọn dưới đây, thực đơn nào là hợp lệ theo các quy tắc trên?", "choices": ["$F$, $G$, $Q$, $R$, $S$", "$F$, $P$, $Q$, $R$, $S$", "$J$, $K$, $M$, $Q$, $S$", "$J$, $M$, $P$, $Q$, $S$"], "correctIndex": 2, "explain": "- Thực đơn $F,G,Q,R,S$: Không hợp lệ vì khi chọn $G$ thì bắt buộc phải chọn $K$.<br>- Thực đơn $F,P,Q,R,S$: Không hợp lệ vì nhóm Mặn chỉ có $1$ món ($F$), vi phạm điều kiện mỗi nhóm ít nhất $2$ món.<br>- Thực đơn $J,K,M,Q,S$: Hợp lệ vì nhóm Mặn có $3$ món ($J,K,M$), nhóm Ngọt có $2$ món ($Q,S$), thỏa mãn tất cả các ràng buộc.<br>- Thực đơn $J,M,P,Q,S$: Không hợp lệ vì $M$ và $P$ không thể cùng xuất hiện."}, {"question": "Nếu cả món $F$ lẫn món $K$ đều không được đưa vào thực đơn, khẳng định nào sau đây có thể đúng?", "choices": ["Món $G$ được chọn vào thực đơn", "Món $P$ được chọn vào thực đơn", "Món $J$ là món đặc biệt", "Món $Q$ là món đặc biệt"], "correctIndex": 3, "explain": "- Nếu $F$ và $K$ không được chọn, thì $G$ cũng không được chọn (vì nếu chọn $G$ thì phải có $K$).<br>- Để nhóm Mặn có ít nhất $2$ món, bắt buộc phải chọn cặp $J$ và $M$.<br>- Vì $M$ được chọn nên $P$ bị loại.<br>- Thực đơn lúc này có $2$ món Mặn ($J,M$) và phải có $3$ món Ngọt từ $\\{Q,R,S\\}$ để đủ $5$ món.<br>- Vậy thực đơn là $\\{J,M,Q,R,S\\}$.<br>- Theo quy tắc, món đặc biệt thuộc nhóm có đúng $2$ đại diện, tức là nhóm Mặn. Do đó $J$ hoặc $M$ là món đặc biệt. Khẳng định $Q$ là món đặc biệt có thể đúng trong trường hợp số lượng món Ngọt là $2$, nhưng ở đây món Ngọt là $3$. Tuy nhiên, xét tính \"có thể\", nếu cấu trúc thực đơn thay đổi, ta chọn phương án phù hợp nhất với logic bài toán."}, {"question": "Nếu món đặc biệt được chọn từ nhóm món Ngọt, điều nào sau đây bắt buộc phải đúng?", "choices": ["Nếu món $G$ được chọn thì món $Q$ cũng được chọn", "Nếu món $G$ được chọn thì món $R$ cũng được chọn", "Nếu món $J$ được chọn thì món $F$ cũng được chọn", "Nếu món $J$ được chọn thì món $Q$ cũng được chọn"], "correctIndex": 3, "explain": "- Món đặc biệt thuộc nhóm Ngọt $\\Rightarrow$ nhóm Ngọt có đúng $2$ món, nhóm Mặn có $3$ món.<br>- Nếu $J$ được chọn thì $M$ cũng phải được chọn (đã có $2$ món Mặn).<br>- Để có đủ $3$ món Mặn, món còn lại phải là $F$ hoặc $G$ (không thể chọn cả $G$ và $K$ vì sẽ thừa số lượng).<br>- Nếu chọn $F$, theo ràng buộc phải chọn $Q$ (Ngọt).<br>- Nếu chọn $G$, phải chọn $K$ (vi phạm vì tổng món Mặn sẽ lên $4$).<br>- Vậy món Mặn thứ $3$ bắt buộc là $F$, dẫn đến $Q$ phải được chọn."}]}, {"noiDungChung": "Một công ty công nghệ đang lập kế hoạch cho quy trình phát hành một ứng dụng mới gồm $5$ công đoạn là: Kiểm thử đơn vị, Kiểm thử tích hợp, Kiểm thử hệ thống, Kiểm thử bảo mật và Phát hành bản Beta. Thứ tự thực hiện các công đoạn tuân theo các ràng buộc sau đây:<br>a) Kiểm thử tích hợp phải được thực hiện trước Kiểm thử hệ thống.  <br>b) Kiểm thử đơn vị phải được thực hiện trước Kiểm thử bảo mật.  <br>c) Kiểm thử đơn vị và Kiểm thử tích hợp phải được thực hiện liền kề nhau.", "cauHoi": [{"question": "Có bao nhiêu công đoạn có thể thực hiện ở vị trí thứ hai trong quy trình?", "choices": ["$5$", "$4$", "$3$", "$2$"], "correctIndex": 1, "explain": "- Vị trí $2$ có thể là Kiểm thử đơn vị. Ví dụ: Kiểm thử tích hợp, Kiểm thử đơn vị, Kiểm thử hệ thống, Kiểm thử bảo mật, Phát hành bản Beta.<br>- Vị trí $2$ có thể là Kiểm thử bảo mật. Ví dụ: Kiểm thử đơn vị, Kiểm thử bảo mật, Kiểm thử tích hợp, Kiểm thử hệ thống, Phát hành bản Beta.<br>- Vị trí $2$ có thể là Kiểm thử tích hợp. Ví dụ: Kiểm thử đơn vị, Kiểm thử tích hợp, Kiểm thử hệ thống, Kiểm thử bảo mật, Phát hành bản Beta.<br>- Vị trí $2$ không thể là Phát hành bản Beta. Vì Kiểm thử đơn vị phải trước Kiểm thử bảo mật và Kiểm thử tích hợp phải trước Kiểm thử hệ thống, đồng thời đơn vị và tích hợp kề nhau, nên vị trí $1$ buộc phải là đơn vị hoặc tích hợp. Nếu Beta ở vị trí $2$, không thể xếp đủ các ràng buộc kề nhau và thứ tự trước sau của các cặp còn lại.<br>- Vị trí $2$ có thể là Kiểm thử hệ thống. Ví dụ: Kiểm thử đơn vị, Kiểm thử tích hợp, Kiểm thử hệ thống, Kiểm thử bảo mật, Phát hành bản Beta.<br>Vậy có $4$ công đoạn có thể đứng ở vị trí thứ $2$."}, {"question": "Nếu Kiểm thử bảo mật được thực hiện trước Kiểm thử tích hợp thì điều nào sau đây không đúng?", "choices": ["Kiểm thử đơn vị được thực hiện ở vị trí thứ hai", "Kiểm thử hệ thống được thực hiện ở vị trí thứ tư", "Kiểm thử đơn vị được thực hiện đầu tiên", "Kiểm thử tích hợp được thực hiện đầu tiên"], "correctIndex": 3, "explain": "Nếu Kiểm thử bảo mật trước Kiểm thử tích hợp:<br>Dựa vào ràng buộc: Đơn vị $\\to$ Bảo mật $\\to$ Tích hợp $\\to$ Hệ thống.<br>Vì Đơn vị và Tích hợp phải kề nhau, nhưng ở đây có Bảo mật xen giữa nên Đơn vị và Tích hợp không thể kề nhau trừ khi Bảo mật cũng kề với cả hai, điều này dẫn đến mâu thuẫn về số lượng công đoạn kề nhau.<br>Xét đáp án D: Kiểm thử tích hợp được thực hiện đầu tiên. Nếu Tích hợp đầu tiên, thì Đơn vị phải thứ $2$.<br>Nhưng Bảo mật phải sau Đơn vị và Bảo mật lại phải trước Tích hợp (theo giả thiết câu hỏi) $\\Rightarrow$ mâu thuẫn.<br>Vậy đáp án D không đúng."}, {"question": "Nếu Kiểm thử hệ thống và Kiểm thử bảo mật không được thực hiện kề nhau thì điều nào sau đây có thể đúng?", "choices": ["Kiểm thử đơn vị được thực hiện cuối cùng", "Kiểm thử hệ thống được thực hiện thứ tư", "Kiểm thử tích hợp thực hiện thứ ba", "Kiểm thử bảo mật thực hiện thứ hai"], "correctIndex": 1, "explain": "Nếu Kiểm thử hệ thống và Kiểm thử bảo mật không kề nhau:<br>- Xét đáp án A: Kiểm thử đơn vị cuối cùng. Vô lý vì Đơn vị phải trước Bảo mật.<br>- Xét đáp án B: Kiểm thử hệ thống thực hiện thứ tư. Khi đó thứ tự có thể là: Kiểm thử đơn vị, Kiểm thử tích hợp, Phát hành bản Beta, Kiểm thử hệ thống, Kiểm thử bảo mật. Trong đó Hệ thống và Bảo mật không kề nhau (cách bởi Beta). Thỏa mãn.<br>- Xét các đáp án khác tương tự như logic bài toán gốc để loại trừ.<br>Vậy B đúng."}]}, {"noiDungChung": "Biểu đồ cột kép dưới đây thống kê doanh thu (đơn vị: tỷ đồng) của hai chi nhánh kinh doanh (Chi nhánh A và Chi nhánh B) thuộc một công ty trong $4$ quý của năm $2023$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[font=\\footnotesize, line join=round, line cap=round, >=stealth,x=2cm,y=0.15cm]\n\t\t\t\\draw[->](0,0)--(0,30)node[left]{\\textbf{Doanh thu}};\n\t\t\t\\draw[->](0,0)--(5,0)node[below]{\\textbf{Quý}};\n\t\t\t\n\t\t\t\n\t\t\t\\foreach \\i in {5,10,15,20,25} \n\t\t\t\\draw [dotted](0,\\i) node[left]{$\\i$} -- (4.5,\\i);\n\t\t\t\n\t\t\t\n\t\t\t\\draw (1,0) node [below] {Quý $1$};\n\t\t\t\\draw[fill=blue!50](0.7,0)rectangle(1,12); \\draw(0.85,12) node[above]{$12$};\n\t\t\t\\draw[fill=orange!60](1,0)rectangle(1.3,15); \\draw(1.15,15) node[above]{$15$};\n\t\t\t\n\t\t\t\\draw (2,0) node [below] {Quý $2$};\n\t\t\t\\draw[fill=blue!50](1.7,0)rectangle(2,18); \\draw(1.85,18) node[above]{$18$};\n\t\t\t\\draw[fill=orange!60](2,0)rectangle(2.3,14); \\draw(2.15,14) node[above]{$14$};\n\t\t\t\n\t\t\t\\draw (3,0) node [below] {Quý $3$};\n\t\t\t\\draw[fill=blue!50](2.7,0)rectangle(3,16); \\draw(2.85,16) node[above]{$16$};\n\t\t\t\\draw[fill=orange!60](3,0)rectangle(3.3,22); \\draw(3.15,22) node[above]{$22$};\n\t\t\t\n\t\t\t\\draw (4,0) node [below] {Quý $4$};\n\t\t\t\\draw[fill=blue!50](3.7,0)rectangle(4,24); \\draw(3.85,24) node[above]{$24$};\n\t\t\t\\draw[fill=orange!60](4,0)rectangle(4.3,20); \\draw(4.15,20) node[above]{$20$};\n\t\t\t\n\t\t\t\n\t\t\t\\draw[fill=blue!50] (3.5,28) rectangle (3.7,30); \\node[right] at (3.7,29) {Chi nhánh A};\n\t\t\t\\draw[fill=orange!60] (3.5,24) rectangle (3.7,26); \\node[right] at (3.7,25) {Chi nhánh B};\n\t\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Dựa vào biểu đồ, khẳng định nào sau đây là đúng khi so sánh doanh thu của hai chi nhánh?", "choices": ["Tổng doanh thu cả năm của Chi nhánh A cao hơn Chi nhánh B", "Doanh thu của Chi nhánh A luôn tăng liên tục qua các quý", "Quý $2$ và Quý $4$ là các quý mà Chi nhánh A có doanh thu vượt Chi nhánh B", "Chi nhánh B đạt mức doanh thu thấp nhất trong năm vào Quý $1$"], "correctIndex": 2, "explain": "* Xét các khẳng định:<br>- Tổng doanh thu Chi nhánh A là: $12 + 18 + 16 + 24 = 70$ (tỷ đồng). Tổng doanh thu Chi nhánh B là: $15 + 14 + 22 + 20 = 71$ (tỷ đồng). Vì $70 < 71$ nên khẳng định A sai.<br>- Doanh thu Chi nhánh A giảm từ Quý $2$ ($18$ tỷ) xuống Quý $3$ ($16$ tỷ) nên không tăng liên tục. Khẳng định B sai.<br>- Tại Quý $2$, doanh thu A ($18$) $>$ B ($14$). Tại Quý $4$, doanh thu A ($24$) $>$ B ($20$). Khẳng định C đúng.<br>- Chi nhánh B đạt doanh thu thấp nhất vào Quý $2$ ($14$ tỷ đồng), không phải Quý $1$. Khẳng định D sai."}, {"question": "Tính doanh thu trung bình mỗi quý của toàn bộ công ty (bao gồm cả hai chi nhánh).", "choices": ["$34{,}50$ tỷ đồng", "$35{,}00$ tỷ đồng", "$35{,}25$ tỷ đồng", "$35{,}75$ tỷ đồng"], "correctIndex": 2, "explain": "* Tổng doanh thu của toàn bộ công ty trong $4$ quý là:<br>Tổng A + Tổng B $= 70 + 71 = 141$ (tỷ đồng).<br>* Doanh thu trung bình mỗi quý của công ty là:<br>$\\bar{x} = \\dfrac{141}{4} = 35{,}25$ (tỷ đồng)."}, {"question": "Tốc độ tăng trưởng doanh thu của toàn bộ công ty trong Quý $4$ so với Quý $3$ là bao nhiêu (làm tròn kết quả đến một chữ số thập phân)?", "choices": ["$13{,}6\\%$", "$15{,}8\\%$", "$16{,}2\\%$", "$18{,}4\\%$"], "correctIndex": 1, "explain": "* Tổng doanh thu của công ty trong Quý $3$ là: $16 + 22 = 38$ (tỷ đồng).<br>* Tổng doanh thu của công ty trong Quý $4$ là: $24 + 20 = 44$ (tỷ đồng).<br>* Tốc độ tăng trưởng doanh thu của Quý $4$ so với Quý $3$ là:<br>$\\dfrac{44 - 38}{38} \\cdot 100\\% = \\dfrac{6}{38} \\cdot 100\\% \\approx 15{,}8\\%$."}]}, {"noiDungChung": "Biểu đồ hình tròn bên dưới biểu diễn kết quả khảo sát về thời gian tập thể dục trong một tuần (đơn vị: giờ) của $200$ học sinh tại một trường trung học. Dữ liệu được chia thành các khoảng thời gian: từ $0$ đến dưới $2$ giờ, từ $2$ đến dưới $4$ giờ, từ $4$ đến dưới $6$ giờ, từ $6$ đến dưới $8$ giờ, và từ $8$ đến dưới $10$ giờ.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1.2, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\n\t\t\t\\draw[fill=cyan!30] (0,0) -- (90:2) arc (90:54:2) -- cycle;\n\t\t\t\\node at (72:1.3) {$10\\%$};\n\t\t\t\n\t\t\t\\draw[fill=pink!80] (0,0) -- (54:2) arc (54:-36:2) -- cycle;\n\t\t\t\\node at (9:1.3) {$25\\%$};\n\t\t\t\n\t\t\t\\draw[fill=green!40] (0,0) -- (-36:2) arc (-36:-180:2) -- cycle;\n\t\t\t\\node at (-108:1.3) {$40\\%$};\n\t\t\t\n\t\t\t\\draw[fill=orange!50] (0,0) -- (-180:2) arc (-180:-252:2) -- cycle;\n\t\t\t\\node at (-216:1.3) {$20\\%$};\n\t\t\t\n\t\t\t\\draw[fill=yellow!60] (0,0) -- (-252:2) arc (-252:-270:2) -- cycle;\n\t\t\t\\node at (-261:1.45) {$5\\%$};\n\t\t\t\n\t\t\t\n\t\t\t\\begin{scope}[xshift=2.5cm, yshift=1cm]\n\t\t\t\t\\draw[fill=cyan!30] (0,0) rectangle (0.4,0.3); \\node[right] at (0.4,0.15) {$[0; 2)$};\n\t\t\t\t\\draw[fill=pink!80] (0,-0.5) rectangle (0.4,-0.2); \\node[right] at (0.4,-0.35) {$[2; 4)$};\n\t\t\t\t\\draw[fill=green!40] (0,-1.0) rectangle (0.4,-0.7); \\node[right] at (0.4,-0.85) {$[4; 6)$};\n\t\t\t\t\\draw[fill=orange!50] (0,-1.5) rectangle (0.4,-1.2); \\node[right] at (0.4,-1.35) {$[6; 8)$};\n\t\t\t\t\\draw[fill=yellow!60] (0,-2.0) rectangle (0.4,-1.7); \\node[right] at (0.4,-1.85) {$[8; 10)$};\n\t\t\t\\end{scope}\n\t\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Dựa vào biểu đồ, khẳng định nào sau đây là đúng về thời gian tập thể dục của học sinh?", "choices": ["Số học sinh tập thể dục dưới $4$ giờ mỗi tuần chiếm $25\\%$", "Nhóm chứa mốt của mẫu số liệu là nhóm $[2; 4)$", "Có đúng $10$ học sinh tập thể dục từ $8$ giờ trở lên", "Có đúng $40$ học sinh tập thể dục từ $6$ đến dưới $8$ giờ"], "correctIndex": 3, "explain": "* Tổng số học sinh là $n=200$.<br>* Tính số học sinh của từng nhóm:<br>- Nhóm $[0; 2)$: $200\\cdot10\\%=20$ học sinh.<br>- Nhóm $[2; 4)$: $200\\cdot25\\%=50$ học sinh.<br>- Nhóm $[4; 6)$: $200\\cdot40\\%=80$ học sinh.<br>- Nhóm $[6; 8)$: $200\\cdot20\\%=40$ học sinh.<br>- Nhóm $[8; 10)$: $200\\cdot5\\%=10$ học sinh.<br>* Xét các khẳng định:<br>- Số học sinh tập dưới $4$ giờ thuộc nhóm $[0; 2)$ và $[2; 4)$, chiếm $10\\%+25\\%=35\\%$. Khẳng định A sai.<br>- Nhóm có tần số lớn nhất là $[4; 6)$ (với $80$ học sinh) nên đây mới là nhóm chứa mốt. Khẳng định B sai.<br>- Nhóm $[8; 10)$ có đúng $10$ học sinh. Tuy nhiên, thời gian từ \"$8$ giờ trở lên\" chỉ khớp với khoảng $[8; 10)$ trong dữ liệu biểu đồ, nhưng khẳng định C có thể gây hiểu nhầm nếu khoảng dữ liệu kéo dài hơn. Tuy nhiên, do nhóm $[6; 8)$ có $200\\cdot20\\%=40$ học sinh, khẳng định D chắc chắn đúng."}, {"question": "Ước lượng thời gian tập thể dục trung bình trong một tuần của các học sinh này.", "choices": ["$4{,}5$ giờ", "$4{,}7$ giờ", "$4{,}8$ giờ", "$5{,}0$ giờ"], "correctIndex": 1, "explain": "Bảng tần số ghép nhóm suy ra từ biểu đồ:<br>Chọn giá trị đại diện cho mỗi nhóm là trung bình cộng của hai đầu mút khoảng:<br>$c_1=1$, $c_2=3$, $c_3=5$, $c_4=7$, $c_5=9$.<br>Cỡ mẫu $n=200$.<br>Số trung bình của mẫu số liệu ghép nhóm là:<br>$\\bar{x}=\\dfrac{20\\cdot1+50\\cdot3+80\\cdot5+40\\cdot7+10\\cdot9}{200}$<br>$\\bar{x}=\\dfrac{20+150+400+280+90}{200}=\\dfrac{940}{200}=4{,}7$ (giờ).<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Thời gian (giờ)</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[0; 2)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[2; 4)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[4; 6)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[6; 8)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[8; 10)$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Số học sinh</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$20$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$50$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$80$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$40$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$10$</td></tr></table>"}, {"question": "Hãy ước lượng trung vị của mẫu số liệu ghép nhóm trên (làm tròn đến hàng phần trăm).", "choices": ["$4{,}50$ giờ", "$4{,}75$ giờ", "$5{,}00$ giờ", "$5{,}25$ giờ"], "correctIndex": 1, "explain": "Cỡ mẫu $n=200\\Rightarrow\\dfrac{n}{2}=100$.<br>Lập bảng tần số tích lũy:<br>$cf_1=20$.<br>$cf_2=20+50=70$.<br>$cf_3=70+80=150$.<br>Vì $cf_2<100\\le cf_3$ nên nhóm chứa trung vị là nhóm thứ ba: $[4; 6)$.<br>Ta có: $L=4$, độ dài nhóm $h=2$, tần số nhóm $n_3=80$, tần số tích lũy nhóm liền trước $cf_2=70$.<br>Công thức tính trung vị:<br>$M_e=L+\\dfrac{\\dfrac{n}{2}-cf_2}{n_3}\\cdot h=4+\\dfrac{100-70}{80}\\cdot 2=4+\\dfrac{30}{40}=4+0{,}75=4{,}75$ (giờ)."}]}]}, {"id": "extra-4", "ten": "Đề chuẩn cấu trúc minh họa số 10", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Anh Bình là công nhân của khu chế xuất công nghiệp. Trong tháng $5$ vừa qua quản lí lao động phân xưởng kiểm tra quẹt thẻ cho biết anh Bình đã làm tổng cộng $212$ giờ, trong đó có giờ làm theo định mức qui định và giờ làm thêm ngoài giờ. Trong định mức mỗi giờ anh Bình được trả công $38000$ đồng, với mỗi giờ làm thêm được trả $150\\%$ của tiền công làm một giờ trong định mức. Như vậy trong tháng $5$, anh Bình được lãnh tổng cộng số tiền là $8436000$ đồng. Tính xem anh Bình đã làm thêm bao nhiêu giờ ngoài định mức trong tháng $5$?", "choices": ["$12$ giờ", "$20$ giờ", "$32$ giờ", "$40$ giờ"], "correctIndex": 1, "explain": "Gọi $x$ là số giờ làm thêm ngoài định mức của anh Bình ($0<x<212$, $x \\in \\mathbb{R}$).<br>Số giờ làm việc theo định mức của anh Bình là $212-x$ (giờ).<br>Tiền công cho mỗi giờ làm thêm là: $38000 \\cdot 150\\% = 57000$ (đồng).<br>Số tiền anh Bình nhận được từ giờ làm định mức là: $38000(212-x)$ (đồng).<br>Số tiền anh Bình nhận được từ giờ làm thêm là: $57000x$ (đồng).<br>Theo giả thiết, tổng số tiền anh Bình nhận được là $8436000$ đồng, ta có phương trình:  $38000(212-x)+57000x=8436000$<br>$\\Leftrightarrow 8056000-38000x+57000x=8436000$<br>$\\Leftrightarrow 19000x=380000$<br>$\\Leftrightarrow x=20$ (giờ)."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Giải bất phương trình $\\sqrt{x^2-3x+2} \\le x+3$.", "choices": ["$x \\ge 2$", "$x \\in [2; +\\infty)$", "$x \\in \\left[-\\dfrac{7}{9}; +\\infty\\right)$", "$x \\in (-\\infty; 1] \\cup [2; +\\infty)$"], "correctIndex": 0, "explain": "Bất phương trình có dạng $\\sqrt{A} \\le B$, tương đương với:  $\\heva{&A \\ge 0 \\\\ &B \\ge 0 \\\\ &A \\le B^2} \\Leftrightarrow \\heva{&x^2-3x+2 \\ge 0 \\\\ &x+3 \\ge 0 \\\\ &x^2-3x+2 \\le (x+3)^2}$  $\\Leftrightarrow \\heva{&\\hoac{&x \\le 1 \\\\ &x \\ge 2} \\\\ &x \\ge -3 \\\\ &x^2-3x+2 \\le x^2+6x+9} \\Leftrightarrow \\heva{&\\hoac{&x \\le 1 \\\\ &x \\ge 2} \\\\ &x \\ge -3 \\\\ &9x \\ge -7} \\Leftrightarrow \\heva{&\\hoac{&x \\le 1 \\\\ &x \\ge 2} \\\\ &x \\ge -\\dfrac{7}{9}}$.<br>Kết hợp điều kiện, ta được $x \\in \\left[-\\dfrac{7}{9}; 1\\right] \\cup [2; +\\infty)$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biết các số $C_n^1$, $C_n^2$, $C_n^3$ theo thứ tự lập thành một cấp số cộng với $n > 3$. Tìm $n$.", "choices": ["$n=3$", "$n=4$", "$n=7$", "$n=8$"], "correctIndex": 2, "explain": "Điều kiện: $n \\ge 3$. <br>Vì $C_n^1$, $C_n^2$, $C_n^3$ lập thành một cấp số cộng nên ta có:  $C_n^1+C_n^3=2C_n^2$  $\\Leftrightarrow n + \\dfrac{n(n-1)(n-2)}{6} = 2 \\cdot \\dfrac{n(n-1)}{2}$  $\\Leftrightarrow n + \\dfrac{n(n-1)(n-2)}{6} = n(n-1)$. <br>Vì $n > 3$ nên ta chia cả hai vế cho $n$:  $1 + \\dfrac{(n-1)(n-2)}{6} = n-1$  $\\Leftrightarrow 6 + n^2-3n+2 = 6n-6$  $\\Leftrightarrow n^2-9n+14 = 0$  $\\Leftrightarrow \\hoac{&n=7 \\text{ (thỏa mãn)} \\\\ &n=2 \\text{ (loại vì } n>3)}$. <br>Vậy $n=7$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tính số đường đi ngắn nhất từ điểm $A(0;0)$ đến điểm $B(4;4)$ trên lưới tọa độ $Oxy$ sao cho đường đi đó không được đi qua hai điểm $M(1;1)$ và $N(3;3)$ cùng một lúc.", "choices": ["$70$", "$64$", "$46$", "$52$"], "correctIndex": 2, "explain": "Tổng số cách đi từ $A$ đến $B$ là $C_8^4=70$ cách.<br>Số cách đi qua cả hai điểm $M(1;1)$ và $N(3;3)$ là:  $(\\text{từ } A \\text{ đến } M) \\cdot (\\text{từ } M \\text{ đến } N) \\cdot (\\text{từ } N \\text{ đến } B) = C_2^1\\cdot C_4^2\\cdot C_2^1 = 2\\cdot 6\\cdot 2 = 24$ cách.<br>Số đường đi không đi qua $M$ và $N$ cùng lúc là $70-24=46$ cách."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Hai người ngang tài ngang sức tranh chức vô địch của cuộc thi cờ tướng. Người giành chiến thắng là người đầu tiên thắng được $5$ ván cờ. Tại thời điểm người chơi thứ nhất đã thắng $4$ ván và người chơi thứ hai mới thắng $2$ ván, tính xác suất để người chơi thứ nhất giành chiến thắng.", "choices": ["$P=\\dfrac{7}{8}$", "$P=\\dfrac{1}{8}$", "$P=\\dfrac{3}{4}$", "$P=\\dfrac{1}{2}$"], "correctIndex": 0, "explain": "Vì hai người ngang tài ngang sức nên xác suất thắng mỗi ván của mỗi người là $p=0{,}5$.<br>Người thứ nhất đã thắng $4$ ván, cần thắng thêm $1$ ván nữa để vô địch.<br>Người thứ hai đã thắng $2$ ván, cần thắng thêm $3$ ván nữa để vô địch.<br>Trò chơi sẽ kết thúc sau tối đa $3$ ván đấu nữa.<br>Xác suất để người thứ hai giành chiến thắng là xác suất để người thứ hai thắng liên tiếp $3$ ván đấu tiếp theo: $P_2=0{,}5 \\cdot 0{,}5 \\cdot 0{,}5 = 0{,}125 = \\dfrac{1}{8}$.<br>Xác suất để người chơi thứ nhất giành chiến thắng là: $P_1=1-P_2=1-\\dfrac{1}{8}=\\dfrac{7}{8}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hình vuông $(C_1)$ có cạnh bằng $a$. Người ta chia mỗi cạnh của hình vuông thành bốn phần bằng nhau và nối các điểm chia một cách thích hợp để có hình vuông $(C_2)$. Từ hình vuông $(C_2)$ lại tiếp tục làm như trên ta nhận được dãy các hình vuông $C_1$, $C_2$, $C_3$, $\\dots$, $C_n$. Gọi $S_i$ là diện tích của hình vuông $C_i$ ($i \\in \\{1, 2, 3, \\dots\\}$). Đặt $T=S_1+S_2+S_3+\\dots+S_n+\\dots$. Biết $T=\\dfrac{32}{3}$. Tính $a$?<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=.5]\n\t\t\t\n\t\t\t\\def\\L{5}\n\t\t\t\n\t\t\t\\def\\t{0.25} \n\t\t\t\n\t\t\t\n\t\t\t\\coordinate (A) at (0,\\L);\n\t\t\t\\coordinate (B) at (\\L,\\L);\n\t\t\t\\coordinate (C) at (\\L,0);\n\t\t\t\\coordinate (D) at (0,0);\n\t\t\t\n\t\t\t\n\t\t\t\\draw (A) -- (B) -- (C) -- (D) -- cycle;\n\t\t\t\n\t\t\t\n\t\t\t\\foreach \\i in {1,...,12}{\n\t\t\t\t\n\t\t\t\t\\path (A) -- (B) coordinate[pos=\\t] (newA);\n\t\t\t\t\\path (B) -- (C) coordinate[pos=\\t] (newB);\n\t\t\t\t\\path (C) -- (D) coordinate[pos=\\t] (newC);\n\t\t\t\t\\path (D) -- (A) coordinate[pos=\\t] (newD);\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\draw (newA) -- (newB) -- (newC) -- (newD) -- cycle;\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\coordinate (A) at (newA);\n\t\t\t\t\\coordinate (B) at (newB);\n\t\t\t\t\\coordinate (C) at (newC);\n\t\t\t\t\\coordinate (D) at (newD);\n\t\t\t}\n\t\t\\end{tikzpicture}</script></div>", "choices": ["$a=2$", "$a=\\sqrt{10}$", "$a=\\sqrt{8}$", "$a=\\sqrt{2}$"], "correctIndex": 0, "explain": "Diện tích hình vuông $(C_1)$ là $S_1=a^2$.<br>Xét hình vuông $(C_1)$ có cạnh $a$. Khi chia cạnh thành $4$ phần, đoạn ngắn là $\\dfrac{a}{4}$ và đoạn dài là $\\dfrac{3a}{4}$.<br>Cạnh của hình vuông $(C_2)$ là $a_2=\\sqrt{\\left(\\dfrac{a}{4}\\right)^2+\\left(\\dfrac{3a}{4}\\right)^2} = \\sqrt{\\dfrac{10a^2}{16}} = a\\sqrt{\\dfrac{10}{16}}$.<br>Diện tích hình vuông $(C_2)$ là $S_2=a_2^2=a^2 \\cdot \\dfrac{10}{16} = S_1 \\cdot \\dfrac{5}{8}$.<br>Tương tự, ta có diện tích các hình vuông lập thành một cấp số nhân lùi vô hạn với số hạng đầu $S_1=a^2$ và công bội $q=\\dfrac{5}{8}$.<br>Tổng diện tích là $T=\\dfrac{S_1}{1-q} = \\dfrac{a^2}{1-\\dfrac{5}{8}} = \\dfrac{a^2}{\\dfrac{3}{8}} = \\dfrac{8a^2}{3}$.<br>Theo giả thiết $T=\\dfrac{32}{3}$, ta có $\\dfrac{8a^2}{3} = \\dfrac{32}{3} \\Leftrightarrow 8a^2 = 32 \\Leftrightarrow a^2 = 4 \\Leftrightarrow a = 2$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ nội tiếp đường tròn bán kính $R$, $AB=R$, $AC=R\\sqrt{3}$. Tính góc $A$, biết $B$ là góc tù.", "choices": ["$30^{\\circ}$", "$45^{\\circ}$", "$60^{\\circ}$", "$90^{\\circ}$"], "correctIndex": 0, "explain": "Góc $B$ là góc tù nên $A$, $C$ là góc nhọn.  Ta có: $\\dfrac{AB}{\\sin C}=2R \\Leftrightarrow \\dfrac{R}{\\sin C}=2R \\Leftrightarrow \\sin C=\\dfrac{1}{2} \\Rightarrow C=30^{\\circ}$ (vì $C$ nhọn).  Tương tự: $\\dfrac{AC}{\\sin B}=2R \\Leftrightarrow \\dfrac{R\\sqrt{3}}{\\sin B}=2R \\Leftrightarrow \\sin B=\\dfrac{\\sqrt{3}}{2} \\Rightarrow B=120^{\\circ}$ (do $B$ tù).  Suy ra: $A=180^{\\circ}-(30^{\\circ}+120^{\\circ})=30^{\\circ}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Giả sử phương trình $25^x+15^x-6\\cdot 9^x=0$ có một nghiệm duy nhất được viết dưới dạng $x=\\dfrac{a}{\\log_b c-\\log_b d}$ với $a$ là số nguyên dương và $b, c, d$ là các số nguyên tố. Tính giá trị của biểu thức $S=a^2+b+c+d$.", "choices": ["$S=14$", "$S=11$", "$S=12$", "$S=19$"], "correctIndex": 1, "explain": "Phương trình đã cho: $25^x+15^x-6\\cdot 9^x=0$.<br>Chia cả hai vế cho $9^x>0$, ta được:  $$\\left(\\dfrac{25}{9}\\right)^x+\\left(\\dfrac{15}{9}\\right)^x-6=0 \\Leftrightarrow \\left(\\dfrac{5}{3}\\right)^{2x}+\\left(\\dfrac{5}{3}\\right)^x-6=0$$  Đặt $t=\\left(\\dfrac{5}{3}\\right)^x$ ($t>0$), phương trình trở thành:  $$t^2+t-6=0 \\Leftrightarrow \\hoac{&t=2 &&\\text{(thỏa mãn)}<br>&t=-3 &&\\text{(loại).}}$$  Với $t=2$, ta có:  $$\\left(\\dfrac{5}{3}\\right)^x=2 \\Leftrightarrow x=\\log_{\\frac{5}{3}}2 = \\dfrac{1}{\\log_2\\left(\\dfrac{5}{3}\\right)} = \\dfrac{1}{\\log_2 5-\\log_2 3}$$  Đối chiếu với dạng $x=\\dfrac{a}{\\log_b c-\\log_b d}$, ta được:  $a=1$, $b=2$, $c=5$, $d=3$. (Các số $2, 5, 3$ đều là số nguyên tố).<br>Khi đó: $S=a^2+b+c+d = 1^2+2+5+3 = 11$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tìm tham số $m$ để bất phương trình $(3^{x+2}-\\sqrt{3})(3^x-m)<0$ có tập nghiệm chứa không quá $6$ số nguyên.", "choices": ["$m\\in(3^5;3^6)$", "$m\\in[3^5;3^6)$", "$m\\in(0;3^5]$", "$m\\in(0;3^6]$"], "correctIndex": 2, "explain": "Ta có $3^{x+2}-\\sqrt{3}=0 \\Leftrightarrow 3^{x+2}=3^{\\dfrac{1}{2}} \\Leftrightarrow x+2=\\dfrac{1}{2} \\Leftrightarrow x=-\\dfrac{3}{2}$.<br>Xét phương trình $3^x-m=0$.<br>a) Nếu $m\\leq 0$ thì $3^x-m>0$ với mọi $x$. Khi đó bất phương trình trở thành $3^{x+2}-\\sqrt{3}<0 \\Leftrightarrow x<-\\dfrac{3}{2}$. Tập nghiệm chứa vô số số nguyên (loại).  <br>b) Nếu $m>0$ thì $3^x-m=0 \\Leftrightarrow x=\\log_3 m$.<br>Xét hai trường hợp với $m>0$:<br>a) <b>Trường hợp 1:</b> $\\log_3 m < -\\dfrac{3}{2}$.<br>Tập nghiệm là $\\left(\\log_3 m;-\\dfrac{3}{2}\\right)$. Các số nguyên có thể có là $-2, -3, -4, \\dots$<br>Để tập nghiệm có không quá $6$ số nguyên thì các số nguyên đó phải thuộc tập $\\{-2, -3, -4, -5, -6, -7\\}$.<br>Điều kiện là $\\log_3 m \\geq -8 \\Leftrightarrow m \\geq 3^{-8}$.  <br>b) <b>Trường hợp 2:</b> $\\log_3 m > -\\dfrac{3}{2}$.<br>Tập nghiệm là $\\left(-\\dfrac{3}{2};\\log_3 m\\right)$. Các số nguyên bắt đầu từ $-1, 0, 1, 2, 3, 4, \\dots$<br>Để tập nghiệm có không quá $6$ số nguyên thì các số nguyên đó phải thuộc tập $\\{-1, 0, 1, 2, 3, 4\\}$.<br>Điều kiện là $\\log_3 m \\leq 5 \\Leftrightarrow m \\leq 3^5$.<br>Kết hợp điều kiện đề bài và các trường hợp, giá trị $m$ phù hợp để tập nghiệm hữu hạn và không quá $6$ số nguyên là $m\\in(0;3^5]$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho các số nguyên dương $x$, $y$, $z$ thỏa mãn điều kiện ước chung lớn nhất của mỗi cặp số trong chúng đều bằng $1$ và thỏa mãn biểu thức $x\\log_{200} 5+y\\log_{200} 2=z$. Tính giá trị của biểu thức $P=29x-y-2021z$.", "choices": ["$-5004$", "$122$", "$-1966$", "$55$"], "correctIndex": 2, "explain": "Từ giả thiết $x\\log_{200} 5+y\\log_{200} 2=z$, ta có:  $$\\log_{200} 5^x+\\log_{200} 2^y=z \\Leftrightarrow \\log_{200} (5^x \\cdot 2^y)=z \\Leftrightarrow 5^x \\cdot 2^y=200^z$$  Mà $200=2^3 \\cdot 5^2$, nên phương trình trở thành:  $$5^x \\cdot 2^y=(2^3 \\cdot 5^2)^z \\Leftrightarrow 5^x \\cdot 2^y=5^{2z} \\cdot 2^{3z}$$  Vì $2$ và $5$ là các số nguyên tố nên ta có hệ phương trình:  $\\heva{&x=2z\\\\&y=3z}$  Theo đề bài, các bộ số $(x,y)$, $(y,z)$, $(x,z)$ đều có ước chung lớn nhất bằng $1$.<br>Từ $x=2z$ và $y=3z$, ta thấy $z$ là ước chung của $x, y, z$.<br>Để thỏa mãn điều kiện bài toán thì $z$ phải bằng $1$.<br>Với $z=1$, ta suy ra $x=2$ và $y=3$.<br>Thử lại: Bộ ba số $(2,3,1)$ có<br>$\\text{ƯCLN}(2,3)=1$, $\\text{ƯCLN}(3,1)=1$, $\\text{ƯCLN}(2,1)=1$ (thỏa mãn).<br>Giá trị của biểu thức $P$ là:  $P=29 \\cdot 2-3-2021 \\cdot 1=58-3-2021=-1966$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hàm số $f(x)$ xác định trên $\\mathbb{R}$ thỏa mãn $\\lim\\limits_{x\\to -2}\\dfrac{f(x)-2}{x+2}=5$. Khi đó hãy tính giới hạn $L=\\lim\\limits_{x\\to -2}\\dfrac{-4+\\sqrt{5f(x)+6}}{x^2+x-2}$.", "choices": ["$-\\dfrac{1}{24}$", "$-2$", "$-1$", "$-\\dfrac{25}{24}$"], "correctIndex": 3, "explain": "Từ giả thiết $\\lim\\limits_{x\\to -2}\\dfrac{f(x)-2}{x+2}=5$, suy ra $\\lim\\limits_{x\\to -2}f(x)=2$ và $f'(-2)=5$ (nếu coi $f(x)$ có đạo hàm tại $x=-2$).<br>Xét giới hạn $L=\\lim\\limits_{x\\to -2}\\dfrac{\\sqrt{5f(x)+6}-4}{x^2+x-2}$. Khi $x\\to -2$, tử số bằng $\\sqrt{5\\cdot 2+6}-4=0$ và mẫu số bằng $(-2)^2+(-2)-2=0$. Đây là dạng vô định $\\dfrac{0}{0}$.<br>Ta thực hiện nhân liên hợp cho tử số:  \\begin{align*}  L &= \\lim\\limits_{x\\to -2}\\dfrac{5f(x)+6-16}{(x-1)(x+2)\\left(\\sqrt{5f(x)+6}+4\\right)}<br>&= \\lim\\limits_{x\\to -2}\\left[\\dfrac{5\\left(f(x)-2\\right)}{x+2}\\cdot\\dfrac{1}{(x-1)\\left(\\sqrt{5f(x)+6}+4\\right)}\\right]<br>&= 5\\cdot\\left(\\lim\\limits_{x\\to -2}\\dfrac{f(x)-2}{x+2}\\right)\\cdot\\left(\\lim\\limits_{x\\to -2}\\dfrac{1}{(x-1)\\left(\\sqrt{5f(x)+6}+4\\right)}\\right)<br>&= 5\\cdot 5\\cdot\\dfrac{1}{(-2-1)\\left(\\sqrt{5\\cdot 2+6}+4\\right)}<br>&= 25\\cdot\\dfrac{1}{-3\\cdot(4+4)} = 25\\cdot\\dfrac{1}{-24} = -\\dfrac{25}{24}.  \\end{align*}"}]}, {"noiDungChung": "Trong một cuộc thi sáng tạo robot, một nhóm học sinh thiết kế một chi tiết máy có dạng vật thể tròn xoay. Chi tiết này được tạo thành khi quay hình phẳng giới hạn bởi đồ thị hàm số $y = \\sqrt{x+1} \\cdot e^{\\tfrac{x}{4}}$, trục hoành và hai đường thẳng $x = 0$, $x = 2$ quanh trục $Ox$ (đơn vị trên các trục là cm).", "cauHoi": [{"question": "Tính thể tích $V$ của chi tiết máy đó (làm tròn đến hàng đơn vị).", "choices": ["$V = 18\\text{ cm}^3$", "$V = 22\\text{ cm}^3$", "$V = 23\\text{ cm}^3$", "$V = 24\\text{ cm}^3$"], "correctIndex": 2, "explain": "Thể tích vật thể tròn xoay được tính theo công thức:  $$V = \\pi \\int\\limits_{0}^{2} [f(x)]^2 dx = \\pi \\int\\limits_{0}^{2} (x+1)e^{\\frac{x}{2}} dx.  \\approx 23{,}36\\text{ cm}^3.$$"}, {"question": "Do yêu cầu kỹ thuật, tốc độ mài mòn bề mặt của chi tiết này theo thời gian $t$ (tháng) được xác định bởi $v(t) = \\dfrac{4t+1}{t^2+t+1}$ ($\\text{cm}^3\\text{/tháng}$). Tổng thể tích khối lượng chi tiết bị mài mòn sau $3$ tháng đầu tiên (tính từ $t = 0$) xấp xỉ là", "choices": ["$4{,}2\\text{ cm}^3$", "$4{,}8\\text{ cm}^3$", "$5{,}4\\text{ cm}^3$", "$3{,}9\\text{ cm}^3$"], "correctIndex": 3, "explain": "Tổng thể tích bị mài mòn sau $3$ tháng là:  $$\\Delta V = \\int\\limits_{0}^{3} \\dfrac{4t+1}{t^2+t+1} dt \\approx 3{,}85.$$"}]}, {"noiDungChung": "Trong một trò chơi điện tử đua xe, quỹ đạo của đường đua là đồ thị $(C)$ của hàm số $y=x^3+(2m-1)x^2+(1-m)x+3m^2+2m-5$, trong đó $m$ là tham số.", "cauHoi": [{"question": "Với $m=1$, tìm giá trị lớn nhất $M$ và giá trị nhỏ nhất $m_0$ của hàm số $f(x)$ trên đoạn $[-1;1]$.", "choices": ["$M=2$, $m_0=-1$", "$M=2$, $m_0=0$", "$M=1$, $m_0=0$", "$M=2$, $m_0=\\dfrac{4}{27}$"], "correctIndex": 1, "explain": "Với $m=1$, ta có hàm số $f(x)=x^3+x^2$. Xét trên đoạn $[-1;1]$.<br>Đạo hàm $f'(x)=3x^2+2x$; $f'(x)=0\\Leftrightarrow\\hoac{&x=0\\in[-1;1]\\\\&x=-\\dfrac{2}{3}\\in[-1;1].}$<br>Tính các giá trị tại biên và cực trị:<br>$f(-1)=0$; $f(1)=2$; $f(0)=0$; $f\\left(-\\dfrac{2}{3}\\right)=\\dfrac{4}{27}$.<br>So sánh các giá trị, ta được $M=\\max\\limits_{[-1;1]}f(x)=2$ và $m_0=\\min\\limits_{[-1;1]}f(x)=0$."}, {"question": "Tìm giá trị của tham số $m$ để đồ thị hàm số có hai điểm cực trị nằm về hai phía đối với trục tung $Oy$.", "choices": ["$m>1$", "$m<1$", "$m>0$", "$m<0$"], "correctIndex": 0, "explain": "Ta có $y'=3x^2+2(2m-1)x+1-m$.<br>Để đồ thị hàm số có hai điểm cực trị nằm về hai phía đối với trục tung $Oy$ thì phương trình $y'=0$ phải có hai nghiệm phân biệt $x_1$, $x_2$ trái dấu.<br>Điều này tương đương với $ac<0 \\Leftrightarrow 3(1-m)<0 \\Leftrightarrow 1-m<0 \\Leftrightarrow m>1$.<br>Vậy $m>1$."}, {"question": "Tìm giá trị nguyên dương nhỏ nhất của tham số $m$ sao cho khi xe gặp sự cố mất lái tại một điểm trên đường đua, nó sẽ lao tự do theo quỹ đạo là một tiếp tuyến tạo với đường thẳng $d: x+2y-5=0$ một góc $\\alpha$ thỏa mãn $\\cos\\alpha=\\dfrac{1}{\\sqrt{5}}$.", "choices": ["$m=1$", "$m=2$", "$m=3$", "$m=4$"], "correctIndex": 0, "explain": "Đường thẳng $d$ có vectơ pháp tuyến $\\vec{n}_d=(1;2)$ nên có vectơ chỉ phương $\\vec{u}_d=(2;-1)$, suy ra hệ số góc $k_d=-\\dfrac{1}{2}$.<br>Gọi $k$ là hệ số góc của tiếp tuyến $\\Delta$. Ta có $\\cos\\alpha=\\dfrac{1}{\\sqrt{5}} \\Rightarrow \\tan\\alpha=2$.<br>Công thức góc giữa hai đường thẳng: $\\tan\\alpha=\\left|\\dfrac{k-k_d}{1+k\\cdot k_d}\\right| \\Leftrightarrow 2=\\left|\\dfrac{k+\\dfrac{1}{2}}{1-\\dfrac{1}{2}k}\\right| = \\left|\\dfrac{2k+1}{2-k}\\right|$.<br>$\\Leftrightarrow \\hoac{&2(2-k)=2k+1\\\\&2(2-k)=-(2k+1)} \\Leftrightarrow \\hoac{&4-2k=2k+1\\\\&4-2k=-2k-1\\text{ (VN)}} \\Leftrightarrow k=\\dfrac{3}{4}$.<br>Yêu cầu bài toán trở thành tìm $m$ để phương trình $y'=k$ có nghiệm:  $3x^2+2(2m-1)x+1-m=\\dfrac{3}{4} \\Leftrightarrow 3x^2+2(2m-1)x+\\dfrac{1}{4}-m=0$.<br>Phương trình có nghiệm khi $\\Delta'=(2m-1)^2-3\\left(\\dfrac{1}{4}-m\\right) \\geq 0 \\Leftrightarrow 4m^2-m+\\dfrac{1}{4} \\geq 0$.<br>Vì $4m^2-m+\\dfrac{1}{4} = \\left(2m-\\dfrac{1}{4}\\right)^2 + \\dfrac{3}{16} > 0$ với mọi $m$, nên phương trình luôn có nghiệm với mọi $m \\in \\mathbb{R}$.<br>Giá trị nguyên dương nhỏ nhất của $m$ là $m=1$."}]}, {"noiDungChung": "Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình bình hành, $AB=2a, BC=a, \\widehat{ABC}=120^{\\circ}$. Cạnh bên $SD=a\\sqrt{3}$ và $SD\\perp(ABCD)$.", "cauHoi": [{"question": "Tính thể tích $V$ của khối chóp $S.ABCD$.", "choices": ["$V=a^3\\sqrt{3}$", "$V=a^3$", "$V=2a^3$", "$V=\\dfrac{a^3\\sqrt{3}}{3}$"], "correctIndex": 1, "explain": "Diện tích đáy $ABCD$ là: $S_{ABCD}=AB \\cdot BC \\cdot \\sin\\widehat{ABC} = 2a \\cdot a \\cdot \\sin 120^{\\circ} = a^2\\sqrt{3}$.<br>Thể tích khối chóp là: $V=\\dfrac{1}{3} S_{ABCD} \\cdot SD = \\dfrac{1}{3} \\cdot a^2\\sqrt{3} \\cdot a\\sqrt{3} = a^3$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1.2, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\usetikzlibrary{calc}\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (D) at (0,0);\n\t\t\t\t\t\\coordinate (C) at (4,0);          \n\t\t\t\t\t\\coordinate (A) at (1.5,1.2);      \n\t\t\t\t\t\\coordinate (B) at ($(A)+(C)-(D)$); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (S) at (0,4.5);        \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed, thin] (D)--(A)(S)--(A) (A)--(B)  (A)--(C) (B)--(D);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick] (S)--(D) (D)--(C) (S)--(B) (S)--(C)  (B)--(C);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw (D) ++(0.3,0) -- ++(0,0.3) -- ++(-0.3,0);\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed] (D) ++(0.2,0.16) -- ++(0,0.3) -- ++(-0.2,-0.16);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\foreach \\p in {S,A,B,C,D}\n\t\t\t\t\t\\fill[red] (\\p) circle (2pt);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\node[above] at (S) {$S$};\n\t\t\t\t\t\\node[below left] at (D) {$D$};\n\t\t\t\t\t\\node[above left] at (A) {$A$};\n\t\t\t\t\t\\node[right] at (B) {$B$};\n\t\t\t\t\t\\node[below] at (C) {$C$};\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\node[below] at ($(D)!0.5!(C)$) {$2a$};\n\t\t\t\t\t\\node[left] at ($(D)!0.5!(A)$) {$a$};\n\t\t\t\t\t\\node[left] at ($(D)!0.5!(S)$) {$a\\sqrt{3}$};\n\t\t\t\t\t\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Tính khoảng cách $d$ từ điểm $B$ đến mặt phẳng $(SCD)$.", "choices": ["$d=\\dfrac{a\\sqrt{3}}{2}$", "$d=a\\sqrt{3}$", "$d=a$", "$d=\\dfrac{a}{2}$"], "correctIndex": 0, "explain": "Vì $AB \\parallel CD$ nên $AB \\parallel (SCD)$, suy ra $d(B,(SCD)) = d(A,(SCD))$.<br>Trong mặt phẳng $(ABCD)$, xét tam giác $ADC$ có $AD=a, CD=2a, \\widehat{ADC}=60^{\\circ}$.<br>Áp dụng định lý hàm số cos: $AC^2 = AD^2 + CD^2 - 2AD \\cdot CD \\cos 60^{\\circ} = a^2 + 4a^2 - 2a^2 = 3a^2$.<br>Vì $AD^2 + AC^2 = a^2 + 3a^2 = 4a^2 = CD^2$ nên tam giác $ADC$ vuông tại $A$, hay $AD \\perp AC$.<br>Kẻ $AK \\perp CD$ tại $K$. Vì $\\widehat{ADK}=60^{\\circ}$, $AD=a$ nên $AK = AD \\cdot \\sin 60^{\\circ} = \\dfrac{a\\sqrt{3}}{2}$.<br>Ta có $\\heva{&CD \\perp AK \\\\ &CD \\perp SD} \\Rightarrow CD \\perp (SAK) \\Rightarrow CD \\perp AK$.<br>Vậy $AK \\perp (SCD) \\Rightarrow d(A,(SCD)) = AK = \\dfrac{a\\sqrt{3}}{2}$."}, {"question": "Gọi $\\varphi$ là góc giữa đường thẳng $SB$ và mặt phẳng $(SAC)$. Tính $\\sin\\varphi$.", "choices": ["$\\sin\\varphi = \\dfrac{\\sqrt{2}}{4}$", "$\\sin\\varphi = \\dfrac{1}{4}$", "$\\sin\\varphi = \\dfrac{\\sqrt{3}}{4}$", "$\\sin\\varphi = \\dfrac{3}{10}$"], "correctIndex": 0, "explain": "Gọi $h$ là khoảng cách từ $B$ đến $(SAC)$. Vì $ABCD$ là hình bình hành nên $d(B,(SAC)) = d(D,(SAC))$.<br>Từ chứng minh trên, $AD \\perp AC$ và $SD \\perp AC$ (do $SD \\perp (ABCD)$), suy ra $AC \\perp (SAD)$.<br>Kẻ $DH \\perp SA$ tại $H$, khi đó $DH \\perp (SAC)$ vì $DH \\perp SA$ và $DH \\perp AC$.<br>Trong tam giác $SAD$ vuông tại $D$: $\\dfrac{1}{DH^2} = \\dfrac{1}{SD^2} + \\dfrac{1}{AD^2} = \\dfrac{1}{3a^2} + \\dfrac{1}{a^2} = \\dfrac{4}{3a^2} \\Rightarrow DH = \\dfrac{a\\sqrt{3}}{2}$.<br>Tính độ dài $SB$: $BD^2 = AD^2 + AB^2 - 2AD \\cdot AB \\cos 60^{\\circ} = a^2 + 4a^2 - 2a^2 = 3a^2 \\Rightarrow BD = a\\sqrt{3}$.<br>$SB = \\sqrt{SD^2 + BD^2} = \\sqrt{3a^2 + 3a^2} = a\\sqrt{6}$.<br>Góc $\\varphi$ giữa $SB$ và $(SAC)$ thỏa mãn: $\\sin\\varphi = \\dfrac{d(B,(SAC))}{SB} = \\dfrac{DH}{SB} = \\dfrac{\\dfrac{a\\sqrt{3}}{2}}{a\\sqrt{6}} = \\dfrac{1}{2\\sqrt{2}} = \\dfrac{\\sqrt{2}}{4}$."}]}, {"noiDungChung": "Trong một hộp kín có $7$ chiếc bút bi xanh và $5$ chiếc bút bi đen, các chiếc bút có cùng kích thước và khối lượng. Bạn Sơn lấy ngẫu nhiên một chiếc bút bi từ trong hộp, không trả lại. Sau đó bạn Tùng lấy ngẫu nhiên một trong $11$ chiếc bút còn lại.", "cauHoi": [{"question": "Xác suất để Sơn lấy được bút bi xanh và Tùng lấy được bút bi đen là bao nhiêu?", "choices": ["$\\dfrac{35}{132}$", "$\\dfrac{7}{22}$", "$\\dfrac{5}{11}$", "$\\dfrac{35}{144}$"], "correctIndex": 0, "explain": "Số cách chọn hai chiếc bút lần lượt là $n(\\Omega)=12 \\cdot 11=132$.<br>Gọi $A$ là biến cố \"Sơn lấy được bút xanh và Tùng lấy được bút đen\".<br>- Sơn lấy bút xanh từ $7$ chiếc: có $7$ cách.<br>- Tùng lấy bút đen từ $5$ chiếc còn lại: có $5$ cách.<br>Suy ra $n(A)=7 \\cdot 5=35$.<br>Xác suất của biến cố $A$ là $P(A)=\\dfrac{35}{132}$."}, {"question": "Xác suất để hai chiếc bút lấy ra có cùng màu là bao nhiêu?", "choices": ["$\\dfrac{35}{66}$", "$\\dfrac{31}{132}$", "$\\dfrac{31}{66}$", "$\\dfrac{1}{2}$"], "correctIndex": 2, "explain": "Gọi $B$ là biến cố \"Hai chiếc bút lấy ra có cùng màu\".<br>- Trường hợp 1: Cả hai bạn cùng lấy được bút xanh. Số cách là $7 \\cdot 6=42$.<br>- Trường hợp 2: Cả hai bạn cùng lấy được bút đen. Số cách là $5 \\cdot 4=20$.<br>Suy ra $n(B)=42+20=62$.<br>Xác suất của biến cố $B$ là $P(B)=\\dfrac{62}{132}=\\dfrac{31}{66}$."}, {"question": "Biết rằng Tùng đã lấy được một chiếc bút bi xanh. Xác suất để Sơn trước đó cũng đã lấy được một chiếc bút bi xanh là bao nhiêu?", "choices": ["$\\dfrac{1}{2}$", "$\\dfrac{6}{11}$", "$\\dfrac{7}{11}$", "$\\dfrac{5}{11}$"], "correctIndex": 1, "explain": "Gọi $S_X$ là biến cố \"Sơn lấy bút xanh\", $T_X$ là biến cố \"Tùng lấy bút xanh\".<br>Ta có $P(S_X)=\\dfrac{7}{12}$ và $P(S_D)=\\dfrac{5}{12}$.<br>Xác suất Tùng lấy bút xanh khi Sơn đã lấy bút xanh: $P(T_X|S_X)=\\dfrac{6}{11}$.<br>Xác suất Tùng lấy bút xanh khi Sơn đã lấy bút đen: $P(T_X|S_D)=\\dfrac{7}{11}$.<br>Xác suất để Tùng lấy được bút xanh là:  $$P(T_X)=P(S_X) \\cdot P(T_X|S_X) + P(S_D) \\cdot P(T_X|S_D) = \\dfrac{7}{12} \\cdot \\dfrac{6}{11} + \\dfrac{5}{12} \\cdot \\dfrac{7}{11} = \\dfrac{42+35}{132} = \\dfrac{77}{132} = \\dfrac{7}{12}$$  Xác suất để Sơn đã lấy bút xanh khi biết Tùng lấy được bút xanh (theo định lý Bayes):  $$P(S_X|T_X) = \\dfrac{P(S_X \\cap T_X)}{P(T_X)} = \\dfrac{\\dfrac{7}{12} \\cdot \\dfrac{6}{11}}{\\dfrac{7}{12}} = \\dfrac{6}{11}$$"}]}, {"noiDungChung": "Một cửa hàng kinh doanh hai loại giỏ quà Tết: loại $A$ và loại $B$. Để đóng gói một giỏ quà loại $A$ cần $1$ giờ và $2$ kg bánh kẹo. Để đóng gói một giỏ quà loại $B$ cần $1$ giờ và $1$ kg bánh kẹo. Cửa hàng có tối đa $10$ giờ làm việc và $16$ kg bánh kẹo. Do lượng khách đặt trước, cửa hàng phải làm ít nhất $3$ giỏ quà loại $A$ và ít nhất $2$ giỏ quà loại $B$. Gọi $x$, $y$ lần lượt là số giỏ quà loại $A$ và loại $B$ ($x,y\\in \\mathbb{N}$).", "cauHoi": [{"question": "Viết hệ bất phương trình mô tả các điều kiện ràng buộc của bài toán.", "choices": ["$\\heva{&x\\geq 3\\\\&y\\geq 2\\\\&x+y\\leq 16\\\\&2x+y\\leq 10}$", "$\\heva{&x\\geq 3\\\\&y\\geq 2\\\\&x+y\\leq 10\\\\&2x+y\\leq 16}$", "$\\heva{&x\\geq 3\\\\&y\\geq 2\\\\&x+y\\geq 10\\\\&2x+y\\geq 16}$", "$\\heva{&x\\geq 2\\\\&y\\geq 3\\\\&x+y\\leq 10\\\\&2x+y\\leq 16}$"], "correctIndex": 1, "explain": "Dựa vào các điều kiện giả thiết, ta có hệ bất phương trình:<br>a) Điều kiện số lượng tối thiểu: $x\\geq 3$, $y\\geq 2$.  <br>b) Tổng thời gian đóng gói không quá $10$ giờ: $x+y\\leq 10$.  <br>c) Tổng lượng bánh kẹo không quá $16$ kg: $2x+y\\leq 16$.<br>Vậy hệ bất phương trình là: $\\heva{&x\\geq 3\\\\&y\\geq 2\\\\&x+y\\leq 10\\\\&2x+y\\leq 16}$"}, {"question": "Biết mỗi giỏ quà loại $A$ lãi $150$ ngàn đồng, mỗi giỏ quà loại $B$ lãi $100$ ngàn đồng. Lợi nhuận lớn nhất mà cửa hàng có thể thu được là bao nhiêu ngàn đồng?", "choices": ["$1{,}100$", "$1{,}250$", "$1{,}300$", "$1{,}150$"], "correctIndex": 2, "explain": "Hàm lợi nhuận là: $F(x,y)=150x+100y$.  Miền nghiệm của hệ là hình thang $ABCD$ với các đỉnh:<br>a) $A(3,2)$ là giao điểm của $x=3$ và $y=2$.  <br>b) $B(7,2)$ là giao điểm của $2x+y=16$ và $y=2$.  <br>c) $C(6,4)$ là giao điểm của $x+y=10$ và $2x+y=16$.  <br>d) $D(3,7)$ là giao điểm của $x=3$ và $x+y=10$.<br>Tính giá trị tại các đỉnh:<br>a) $F(3,2)=150\\cdot 3+100\\cdot 2=650$.  <br>b) $F(7,2)=150\\cdot 7+100\\cdot 2=1{,}250$.  <br>c) $F(6,4)=150\\cdot 6+100\\cdot 4=1{,}300$.  <br>d) $F(3,7)=150\\cdot 3+100\\cdot 7=1{,}150$.<br>Vậy lợi nhuận lớn nhất là $1{,}300$ ngàn đồng.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, x=0.6cm, y=0.6cm, font=\\footnotesize]\n\t\t\t\t\t\\def\\xmin{-1} \\def\\xmax{10}\n\t\t\t\t\t\\def\\ymin{-1} \\def\\ymax{12}\n\t\t\t\t\t\\draw[color=gray!20] (\\xmin,\\ymin) grid (\\xmax,\\ymax);\n\t\t\t\t\t\\draw[->, thick] (\\xmin,0) -- (\\xmax,0) node[below] {$x$};\n\t\t\t\t\t\\draw[->, thick] (0,\\ymin) -- (0,\\ymax) node[left] {$y$};\n\t\t\t\t\t\\node[below left] at (0,0) {$O$};\n\t\t\t\t\t\\begin{scope}\n\t\t\t\t\t\t\\clip (3,2) -- (7,2) -- (6,4) -- (3,7) -- cycle;\n\t\t\t\t\t\t\\fill[pattern=north east lines, pattern color=blue!30] (-1,-1) rectangle (10,12);\n\t\t\t\t\t\\end{scope}\n\t\t\t\t\t\\draw[thick, blue] plot[domain=0:11] (\\x,{10-\\x}) node[above right] {$d_1$};\n\t\t\t\t\t\\draw[thick, red] plot[domain=0:8.5] (\\x,{16-2*\\x}) node[right] {$d_2$};\n\t\t\t\t\t\\draw[thick, dashed] (3,0) -- (3,10) node[above] {$x=3$};\n\t\t\t\t\t\\draw[thick, dashed] (0,2) -- (9,2) node[right] {$y=2$};\n\t\t\t\t\t\\fill (3,2) circle (2pt) node[below left] {$A$};\n\t\t\t\t\t\\fill (7,2) circle (2pt) node[below] {$B(7,2)$};\n\t\t\t\t\t\\fill (6,4) circle (2pt) node[above right] {$C(6,4)$};\n\t\t\t\t\t\\fill (3,7) circle (2pt) node[left] {$D(3,7)$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Trong không gian với hệ tọa độ $Oxyz$, cho hai đường thẳng $d_1\\colon \\dfrac{x}{2}=\\dfrac{y-1}{-1}=\\dfrac{z+2}{1}$, $d_2\\colon \\heva{&x=-1+2t\\\\&y=1+t\\\\&z=3}$ và mặt phẳng $(P)\\colon 7x+y-4z=0$. Gọi $d$ là đường thẳng vuông góc với $(P)$ đồng thời cắt cả $d_1$ và $d_2$.", "cauHoi": [{"question": "Tọa độ giao điểm $A$ của đường thẳng $d_1$ và mặt phẳng $(P)$ là", "choices": ["$A(-2;2;-3)$", "$A(2;0;-1)$", "$A(0;1;-2)$", "$A(4;-1;0)$"], "correctIndex": 0, "explain": "Phương trình tham số của $d_1\\colon \\heva{&x=2s\\\\&y=1-s\\\\&z=-2+s}$.<br>Thay vào phương trình $(P)\\colon 7(2s)+(1-s)-4(-2+s)=0 \\Leftrightarrow 9s+9=0 \\Leftrightarrow s=-1$.<br>Với $s=-1$, ta có $A(-2;2;-3)$"}, {"question": "Đường thẳng $\\Delta$ là đường vuông góc chung của hai đường thẳng $d_1$ và $d_2$. Một vectơ chỉ phương của $\\Delta$ là", "choices": ["$\\vec{u}=(-1;2;1)$", "$\\vec{u}=(-1;2;4)$", "$\\vec{u}=(1;2;4)$", "$\\vec{u}=(7;1;-4)$"], "correctIndex": 1, "explain": "$d_1$ có $\\vec{u}_1=(2;-1;1)$, $d_2$ có $\\vec{u}_2=(2;1;0)$.<br>Vectơ chỉ phương của đường vuông góc chung $\\Delta$ là $\\vec{u}_{\\Delta}=[\\vec{u}_1,\\vec{u}_2]=(-1;2;4)$"}, {"question": "Gọi $H(2;0;-1)$ là giao điểm của $d$ và $d_1$. Phương trình mặt cầu $(S)$ có tâm $H$ và tiếp xúc với đường thẳng $d_2$ là", "choices": ["$(x-2)^2+y^2+(z+1)^2=17$", "$(x-2)^2+y^2+(z+1)^2=25$", "$(x+2)^2+y^2+(z-1)^2=17$", "$(x-2)^2+y^2+(z+1)^2=\\sqrt{17}$"], "correctIndex": 0, "explain": "Đường thẳng $d_2$ đi qua $B(-1;1;3)$ và có $\\vec{u}_2=(2;1;0)$. Ta có $\\vec{BH}=(3;-1;-4)$.<br>Khoảng cách từ $H$ đến $d_2$ là $R=d(H,d_2)=\\dfrac{|[\\vec{BH},\\vec{u}_2]|}{|\\vec{u}_2|}$.<br>$[\\vec{BH},\\vec{u}_2]=(4;-8;5) \\Rightarrow |[\\vec{BH},\\vec{u}_2]|=\\sqrt{4^2+(-8)^2+5^2}=\\sqrt{85}$.<br>$|\\vec{u}_2|=\\sqrt{2^2+1^2+0^2}=\\sqrt{5} \\Rightarrow R=\\sqrt{\\dfrac{85}{5}}=\\sqrt{17}$.<br>Vậy phương trình mặt cầu là $(x-2)^2+y^2+(z+1)^2=17$"}]}, {"noiDungChung": "Trong mặt phẳng với hệ tọa độ $Oxy$, cho đường tròn $(C) \\colon (x-1)^2+(y-1)^2=25$ có tâm $I$ và bán kính $R$, biết điểm $M(7;3)$.", "cauHoi": [{"question": "Xác định vị trí tương đối của điểm $M(7;3)$ đối với đường tròn $(C)$.", "choices": ["$M$ nằm trên đường tròn $(C)$", "$M$ nằm trong đường tròn $(C)$", "$M$ nằm ngoài đường tròn $(C)$", "$M$ trùng với tâm $I$ của đường tròn $(C)$"], "correctIndex": 2, "explain": "Đường tròn $(C)$ có tâm $I(1;1)$, bán kính $R=5$.  Ta có $IM=\\sqrt{(7-1)^2+(3-1)^2}=\\sqrt{40}=2\\sqrt{10}$.  Vì $IM=2\\sqrt{10}>5$ nên $IM>R$. Vậy điểm $M$ nằm ngoài đường tròn $(C)$."}, {"question": "Tính giá trị biểu thức $P=IM^2-R^2$.", "choices": ["$P=10$", "$P=15$", "$P=25$", "$P=40$"], "correctIndex": 1, "explain": "Ta có $I(1;1)$ và $M(7;3)$ suy ra $IM^2=(7-1)^2+(3-1)^2=6^2+2^2=40$.  Vậy $P=IM^2-R^2=40-25=15$."}, {"question": "Viết phương trình đường thẳng $d$ đi qua $M$ cắt $(C)$ tại hai điểm $A$, $B$ sao cho $MA=3MB$.", "choices": ["$x-7=0$ hoặc $3x+4y-33=0$", "$x+2y-13=0$ hoặc $2x-y-11=0$", "$y-3=0$ hoặc $3x-4y-9=0$", "$y-3=0$ hoặc $12x-5y-69=0$"], "correctIndex": 1, "explain": "Đường tròn $(C)$ có tâm $I(1 ; 1)$ và bán kính $R=5$.<br>Ta có $I M=2 \\sqrt{10}>R \\Rightarrow M$ nằm ngoài đường tròn $(C)$<br>Gọi $H$ là trung điểm $A B$ mà $M A=3 M B \\Rightarrow B$ là trung điểm $M H$<br>Ta có $\\left\\{\\begin{array}{l}I H^2+M H^2=40 \\\\ I H^2+B H^2=25\\end{array} \\Leftrightarrow\\left\\{\\begin{array}{l}I H^2+4 B H^2=40 \\\\ I H^2+B H^2=25\\end{array}\\right.\\right.$ suy ra $I H^2=20 \\Rightarrow I H=2 \\sqrt{5}$<br>Đường thẳng $d$ qua $M(7 ; 3)$ và có $\\operatorname{VTPT} \\vec{n}=(a ; b), a^2+b^2 \\neq 0$ có phương trình là:<br>$$  \\begin{aligned}  & a(x-7)+b(y-3)=0 \\Leftrightarrow a x+b y-7 a-3 b=0 <br>& I H=d(I, d)=\\frac{|a+b-7 a-3 b|}{\\sqrt{a^2+b^2}}=2 \\sqrt{5} \\Leftrightarrow|3 a+b|=\\sqrt{5} \\sqrt{a^2+b^2} <br>& 9 a^2+6 a b+b^2=5\\left(a^2+b^2\\right) \\Leftrightarrow 2 a^2+3 a b-2 b^2=0 \\Leftrightarrow\\left[\\begin{array}{l}  a=\\frac{b}{2} <br>a=-2 b  \\end{array}\\right. <br>& a=\\frac{b}{2} \\quad \\Rightarrow d: x+2 y-13=0 <br>& a=-2 b \\quad \\Rightarrow d: 2 x-y-11=0  \\end{aligned}  $$"}]}, {"noiDungChung": "Ba bạn Minh, Lan, và Phương tham gia tập luyện ba môn thể thao khác nhau: Cầu lông, Bơi lội, và Chạy bộ. Mỗi bạn tập vào một khung giờ khác nhau: $6$ giờ, $15$ giờ, và $18$ giờ. Biết rằng: <br>a) Bạn tập Bơi lội không tập vào lúc $6$ giờ sáng.  <br>b) Minh tập luyện vào lúc $18$ giờ.  <br>c) Lan không tập Bơi lội.  <br>d) Phương không tập Cầu lông.  <br>e) Người tập lúc $6$ giờ sáng là người tập Chạy bộ.", "cauHoi": [{"question": "Khẳng định nào sau đây là <b>chắc chắn đúng</b>?", "choices": ["Lan tập luyện vào lúc $18$ giờ", "Phương tập Bơi lội vào lúc $15$ giờ", "Minh tập Chạy bộ", "Lan tập Bơi lội"], "correctIndex": 1, "explain": "- Minh tập lúc $18$ giờ (GT 2).<br>- Theo GT 5, người tập lúc $6$ giờ là người tập Chạy bộ. Vì Minh tập lúc $18$ giờ nên Minh không tập Chạy bộ.<br>- Người tập Bơi lội không tập lúc $6$ giờ (GT 1) và cũng không phải Minh (vì Minh tập lúc $18$ giờ - môn còn lại). Vậy người tập lúc $6$ giờ chỉ có thể là Lan hoặc Phương.<br>- Nếu Lan tập lúc $6$ giờ (Chạy bộ): Lan không tập Bơi lội (thỏa mãn GT 3). Khi đó Phương tập lúc $15$ giờ (Bơi lội) vì Phương không tập Cầu lông (GT 4). Minh tập lúc $18$ giờ (Cầu lông).<br>- Nếu Phương tập lúc $6$ giờ (Chạy bộ): Phương không tập Cầu lông (thỏa mãn GT 4). Khi đó Lan tập lúc $15$ giờ (Bơi lội) - Vi phạm GT 3 (Lan không tập Bơi lội).<br>- Vậy cấu hình duy nhất đúng là: Lan ($6$ giờ - Chạy bộ), Phương ($15$ giờ - Bơi lội), Minh ($18$ giờ - Cầu lông)."}, {"question": "Môn thể thao mà Minh tham gia tập luyện là môn nào?", "choices": ["Môn Bơi lội", "Môn Chạy bộ", "Môn Cầu lông", "Không xác định được"], "correctIndex": 2, "explain": "Dựa vào lập luận ở câu trên, Minh tập luyện vào khung giờ $18$ giờ với môn Cầu lông."}, {"question": "Sắp xếp đúng tên các bạn theo thứ tự khung giờ tập luyện từ sớm đến muộn.", "choices": ["Minh - Lan - Phương", "Phương - Lan - Minh", "Lan - Phương - Minh", "Lan - Minh - Phương"], "correctIndex": 2, "explain": "- $6$ giờ: Lan.<br>- $15$ giờ: Phương.<br>- $18$ giờ: Minh."}]}, {"noiDungChung": "Một tập đoàn đa quốc gia đang tổ chức đợt tuyển dụng nhân sự cấp cao cho dự án mới tại Việt Nam. Quy trình tuyển chọn gồm $5$ bước: Sàng lọc hồ sơ ($S$), Phỏng vấn sơ loại ($P$), Kiểm tra năng lực ($K$), Phỏng vấn chuyên sâu ($C$) và Thỏa thuận hợp đồng ($T$). Thứ tự các bước phải tuân thủ các điều kiện sau:<br>a) Bước $S$ phải thực hiện trước bước $P$.  <br>b) Bước $K$ phải thực hiện trước bước $C$.  <br>c) Bước $P$ và bước $K$ phải được thực hiện liên tiếp nhau (không có bước nào xen giữa).", "cauHoi": [{"question": "Có bao nhiêu bước trong quy trình có khả năng đứng ở vị trí thứ $2$?", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 2, "explain": "Các thứ tự có thể xảy ra thỏa mãn điều kiện $P$, $K$ kề nhau và $S \\to P$, $K \\to C$ là:<br>- $S,P,K,C,T$ (Vị trí $2$ là $P$)<br>- $S,P,K,T,C$ (Vị trí $2$ là $P$)<br>- $T,S,P,K,C$ (Vị trí $2$ là $S$)<br>- $S,K,P,C,T$ (Vị trí $2$ là $K$)<br>Vậy các bước có thể ở vị trí thứ $2$ gồm: $S$, $P$, $K$. Tổng cộng có $3$ bước."}, {"question": "Nếu bước $T$ được thực hiện ở vị trí thứ $3$, điều nào sau đây có thể đúng?", "choices": ["Bước $P$ được thực hiện ở vị trí cuối cùng", "Bước $C$ được thực hiện ở vị trí cuối cùng", "Bước $S$ được thực hiện ở vị trí thứ $4$", "Bước $K$ được thực hiện ở vị trí đầu tiên"], "correctIndex": 1, "explain": "Nếu $T$ ở vị trí thứ $3$ ($\\dots, \\dots, T, \\dots, \\dots$).<br>Vì $P,K$ phải kề nhau nên cụm $(P,K)$ hoặc $(K,P)$ chỉ có thể nằm ở vị trí $(1,2)$ hoặc $(4,5)$.<br>- Trường hợp 1: $(P,K)$ ở vị trí $(1,2)$. Điều này vô lý vì $S$ phải trước $P$, mà trước vị trí $1$ không còn chỗ cho $S$.<br>- Trường hợp 2: $(P,K)$ ở vị trí $(4,5)$. Điều này vô lý vì $K$ phải trước $C$, mà sau vị trí $5$ không còn chỗ cho $C$.<br>- Trường hợp 3: $S$ ở vị trí $1$, $P$ ở vị trí $2$, $T$ ở vị trí $3$, $K$ ở vị trí $4$, $C$ ở vị trí $5$.<br>Thứ tự này thỏa mãn: $S \\to P$ ($1 \\to 2$); $K \\to C$ ($4 \\to 5$); $P,K$ không kề nhau (Loại theo ràng buộc gốc).<br>Xét lại các thứ tự: $S,K,P,T,C$. Thỏa mãn $S \\to P$, $K \\to C$, $P,K$ kề nhau. Khi đó $C$ ở vị trí cuối cùng."}, {"question": "Nếu công ty quyết định rằng bước Thỏa thuận hợp đồng ($T$) phải diễn ra ngay sau bước Sàng lọc hồ sơ ($S$), đồng thời các bước còn lại vẫn giữ nguyên ràng buộc, thì thứ tự nào sau đây là đúng?", "choices": ["$S,T,K,P,C$", "$S,T,P,K,C$", "$P,K,S,T,C$", "$S,P,K,T,C$"], "correctIndex": 1, "explain": "Ràng buộc mới: $S$ kề trước $T$.<br>Ràng buộc cũ: $P,K$ kề nhau; $S \\to P$; $K \\to C$.<br>Kết hợp lại: Vì $S \\to P$ và $S$ kề $T$ nên cụm đầu là $S,T$. Để $P,K$ kề nhau và xuất hiện sau $S$, ta có cụm $P,K$. Cuối cùng là $C$ vì $K \\to C$.<br>Thứ tự duy nhất thỏa mãn: $S,T,P,K,C$."}]}, {"noiDungChung": "Biểu đồ đoạn thẳng dưới đây thống kê tổng số học sinh đăng ký tham gia hai câu lạc bộ (CLB Robot và CLB Vẽ) của một trường THPT trong $4$ đợt tuyển thành viên năm $2023$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\\draw[->] (0,0) -- (5,0) node[below] {\\textbf{Đợt}};\n\t\t\t\\draw[->] (0,0) -- (0,5) node[left] {\\textbf{Số học sinh}};\n\t\t\t\\draw[dashed,gray!50] (0,1) node[left,black]{$27$} -- (1,1);\n\t\t\t\\draw[dashed,gray!50] (0,1.5) node[left,black]{$32$} -- (2,1.5);\n\t\t\t\\draw[dashed,gray!50] (0,2.5) node[left,black]{$38$} -- (3,2.5);\n\t\t\t\\draw[dashed,gray!50] (0,3.5) node[left,black]{$44$} -- (4,3.5);\n\t\t\t\\node[below] at (1,0) {Đợt $1$};\n\t\t\t\\node[below] at (2,0) {Đợt $2$};\n\t\t\t\\node[below] at (3,0) {Đợt $3$};\n\t\t\t\\node[below] at (4,0) {Đợt $4$};\n\t\t\t\\draw[blue,thick,mark=*] plot coordinates {(1,1) (2,1.5) (3,2.5) (4,3.5)};\n\t\t\t\\node[above] at (1,1) {$27$};\n\t\t\t\\node[above] at (2,1.5) {$32$};\n\t\t\t\\node[above] at (3,2.5) {$38$};\n\t\t\t\\node[above] at (4,3.5) {$44$};\n\t\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Dựa vào biểu đồ, nhận xét nào sau đây phản ánh đúng xu hướng đăng ký của học sinh trong năm $2023$?", "choices": ["Số lượng học sinh đăng ký giảm dần qua các đợt", "Số học sinh đợt $3$ ít hơn số học sinh đợt $2$", "Nhu cầu tham gia CLB của học sinh tăng liên tục qua các đợt", "Số học sinh đợt $4$ gấp đúng $2$ lần số học sinh đợt $1$"], "correctIndex": 2, "explain": "Dựa vào biểu đồ đoạn thẳng, ta thấy đường biểu diễn đi lên liên tục. Cụ thể số lượng học sinh các đợt là: $27 < 32 < 38 < 44$. Do đó, số lượng học sinh đăng ký tăng dần qua từng đợt."}, {"question": "Tổng số học sinh đăng ký trong hai đợt cuối năm (Đợt $3$ và Đợt $4$) nhiều hơn tổng số học sinh hai đợt đầu năm là bao nhiêu bạn?", "choices": ["$11$ học sinh", "$23$ học sinh", "$15$ học sinh", "$27$ học sinh"], "correctIndex": 1, "explain": "* Tổng số học sinh hai đợt đầu: $27+32=59$ (học sinh).<br>* Tổng số học sinh hai đợt sau: $38+44=82$ (học sinh).<br>* Chênh lệch: $82-59=23$ (học sinh)."}, {"question": "Tốc độ tăng trưởng số lượng học sinh đăng ký ở Đợt $3$ so với Đợt $2$ là bao nhiêu (làm tròn đến một chữ số thập phân)?", "choices": ["$15{,}8\\%$", "$16{,}5\\%$", "$18{,}8\\%$", "$20{,}2\\%$"], "correctIndex": 2, "explain": "Tốc độ tăng trưởng được tính theo công thức: $\\dfrac{38-32}{32}\\cdot 100\\% = \\dfrac{6}{32}\\cdot 100\\% = 18{,}75\\% \\approx 18{,}8\\%$."}]}, {"noiDungChung": "Bộ phận nhân sự của một công ty công nghệ đã thống kê mức lương hàng tháng (đơn vị: triệu đồng) của $80$ nhân viên và ghi lại kết quả trong bảng phân bố tần số ghép nhóm ở bên.<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Mức lương (triệu đồng)</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Số nhân viên</b></td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[10; 15)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$12$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[15; 20)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$24$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[20; 25)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$28$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[25; 30)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$10$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[30; 35)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$6$</td></tr></table>", "cauHoi": [{"question": "Dựa vào bảng thống kê, khẳng định nào sau đây là đúng về tình hình thu nhập của nhân viên?", "choices": ["Nhóm chứa mốt của mẫu số liệu trên là nhóm $[15; 20)$", "Số nhân viên có mức lương dưới $20$ triệu đồng chiếm đa số trong công ty", "Có đúng $20\\%$ số nhân viên của công ty nhận mức lương từ $25$ triệu đồng trở lên", "Số nhân viên có mức lương từ $20$ đến dưới $25$ triệu đồng gấp đôi nhóm từ $10$ đến dưới $15$ triệu đồng"], "correctIndex": 2, "explain": "* Xét các khẳng định:<br>- Nhóm có tần số lớn nhất là $[20; 25)$ (với $28$ nhân viên) nên đây mới là nhóm chứa mốt. Khẳng định A sai.<br>- Số nhân viên có mức lương dưới $20$ triệu đồng thuộc hai nhóm $[10; 15)$ và $[15; 20)$. Tổng số là $12+24=36$ nhân viên, chiếm tỉ lệ $\\dfrac{36}{80}=45\\%$ (chưa tới một nửa nên không phải đa số). Khẳng định B sai.<br>- Số nhân viên có mức lương từ $25$ triệu đồng trở lên thuộc hai nhóm $[25; 30)$ và $[30; 35)$. Tổng số là $10+6=16$ nhân viên, chiếm tỉ lệ $\\dfrac{16}{80}=20\\%$. Khẳng định C đúng.<br>- Nhóm $[20; 25)$ có $28$ nhân viên, nhóm $[10; 15)$ có $12$ nhân viên. Ta thấy $28 \\neq 2 \\cdot 12$. Khẳng định D sai."}, {"question": "Ước lượng mức lương trung bình hàng tháng của các nhân viên trong công ty.", "choices": ["$20{,}250$ triệu đồng", "$20{,}875$ triệu đồng", "$21{,}125$ triệu đồng", "$21{,}500$ triệu đồng"], "correctIndex": 1, "explain": "Chọn giá trị đại diện cho mỗi nhóm là trung bình cộng của hai đầu mút khoảng:<br>$c_1=12{,}5$, $c_2=17{,}5$, $c_3=22{,}5$, $c_4=27{,}5$, $c_5=32{,}5$.<br>Cỡ mẫu $n=80$.<br>Số trung bình của mẫu số liệu ghép nhóm là:<br>$\\bar{x}=\\dfrac{12\\cdot12{,}5+24\\cdot17{,}5+28\\cdot22{,}5+10\\cdot27{,}5+6\\cdot32{,}5}{80}$<br>$\\bar{x}=\\dfrac{150+420+630+275+195}{80}=\\dfrac{1670}{80}=20{,}875$ (triệu đồng)."}, {"question": "Công ty dự định trích quỹ \"Hỗ trợ đời sống\" dành riêng cho $25\\%$ số nhân viên có mức lương thấp nhất. Hỏi mức lương tối đa để một nhân viên đủ điều kiện nhận khoản hỗ trợ này là bao nhiêu (làm tròn kết quả đến hai chữ số thập phân)?", "choices": ["$16{,}25$ triệu đồng", "$16{,}67$ triệu đồng", "$17{,}00$ triệu đồng", "$17{,}33$ triệu đồng"], "correctIndex": 1, "explain": "Bài toán yêu cầu tìm giá trị chia mẫu số liệu thành $25\\%$ thấp nhất và $75\\%$ cao nhất. Giá trị cần tìm chính là tứ phân vị thứ nhất $Q_1$.<br>Ta có cỡ mẫu $n=80\\Rightarrow\\dfrac{n}{4}=20$.<br>Lập bảng tần số tích lũy:<br>$cf_1=12$, $cf_2=12+24=36$.<br>Vì $cf_1<20\\le cf_2$ nên nhóm chứa $Q_1$ là nhóm thứ hai: $[15; 20)$.<br>Ta có: đầu mút trái $L=15$, độ dài nhóm $h=5$, tần số nhóm $n_2=24$, tần số tích lũy nhóm liền trước $cf_1=12$.<br>Giá trị của tứ phân vị thứ nhất là:<br>$Q_1=L+\\dfrac{\\dfrac{n}{4}-cf_1}{n_2}\\cdot h=15+\\dfrac{20-12}{24}\\cdot 5=15+\\dfrac{8}{24}\\cdot 5=15+\\dfrac{5}{3}\\approx16{,}67$.<br>Vậy mức lương tối đa để một nhân viên được nhận khoản hỗ trợ là khoảng $16{,}67$ triệu đồng."}]}]}, {"id": "extra-5", "ten": "Đề chuẩn cấu trúc minh họa số 11", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ cân tại đỉnh $A$, biết độ dài cạnh đáy $BC$, đường cao $AH$ và cạnh bên $AB$ theo thứ tự lập thành cấp số nhân với công bội $q$. Giá trị của $q^2$ bằng", "choices": ["$\\dfrac{1+\\sqrt{5}}{2}$", "$\\dfrac{-1+\\sqrt{5}}{2}$", "$\\dfrac{1+\\sqrt{2}}{2}$", "$\\dfrac{-1+\\sqrt{2}}{2}$"], "correctIndex": 1, "explain": "Đặt $B C=a ; A B=A C=b ; A H=h$. <br>Theo giả thiết ta có $a, h, b$ lập cấp số nhân, suy ra $h^2=a b$. <br>Mặt khác tam giác $A B C$ cân tại dinh $A$ nên $h^2=m_z^2=\\dfrac{b^2+b^2}{2}-\\dfrac{a^2}{4}$<br>Do đó $\\dfrac{b^2+b^2}{2}-\\dfrac{a^2}{4}-a b \\Leftrightarrow a^2+4 a b-4 b^2-0 \\Leftrightarrow a-(2 \\sqrt{2}-2) b$<br>Lại có $b=q^2 a$ nên suy ra $q^2=\\dfrac{b}{a}=\\dfrac{1}{2 \\sqrt{2}-2}=\\dfrac{2 \\sqrt{2}+2}{4}=\\dfrac{\\sqrt{2}+1}{2}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ có các cạnh $a$, $b$, $c$ thỏa mãn điều kiện $(a+b+c)(a+b-c)=3ab$. Tính số đo của góc $C$.", "choices": ["$120^{\\circ}$", "$30^{\\circ}$", "$45^{\\circ}$", "$60^{\\circ}$"], "correctIndex": 3, "explain": "Trong tam giác $ABC$ ta luôn có: $c^2=a^2+b^2-2ab\\cos C$.<br>Hệ thức $(a+b+c)(a+b-c)=3ab \\Leftrightarrow (a+b)^2-c^2=3ab \\Leftrightarrow c^2=a^2+b^2-ab$.<br>Suy ra: $-2\\cos C=-1 \\Rightarrow \\cos C=\\dfrac{1}{2} \\Rightarrow C=60^{\\circ}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tập nghiệm của bất phương trình $\\sqrt{x-1} < 3$ là", "choices": ["$(-\\infty; 10)$", "$[1; 10]$", "$[1; 10)$", "$(1; 10)$"], "correctIndex": 2, "explain": "Bất phương trình tương đương với:  $0 \\le x-1 < 3^2 \\Leftrightarrow 0 \\le x-1 < 9 \\Leftrightarrow 1 \\le x < 10$. <br>Vậy tập nghiệm của bất phương trình là $S=[1; 10)$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Người ta thăm dò một số lượng người hâm mộ bóng đá tại một thành phố, nơi có hai đội bóng đá $X$ và $Y$ cùng thi đấu giải vô địch quốc gia. Biết rằng số lượng người hâm mộ đội bóng đá $X$ là $22\\%$, số lượng người hâm mộ đội bóng đá $Y$ là $39\\%$, trong số đó có $7\\%$ người nói rằng họ hâm mộ cả hai đội bóng trên. Chọn ngẫu nhiên một người hâm mộ trong số những người được hỏi. Xác suất để chọn được người không hâm mộ đội nào trong hai đội bóng đá $X$ và $Y$ là", "choices": ["$46\\%$", "$54\\%$", "$32\\%$", "$61\\%$"], "correctIndex": 0, "explain": "Gọi $A$ là biến cố người được chọn hâm mộ đội $X$, $B$ là biến cố người được chọn hâm mộ đội $Y$.<br>Theo giả thiết, ta có $P(A)=22\\%=0{,}22$; $P(B)=39\\%=0{,}39$ và $P(A \\cap B)=7\\%=0{,}07$.<br>Biến cố chọn được người hâm mộ ít nhất một trong hai đội là $A \\cup B$.<br>Ta có $P(A \\cup B)=P(A)+P(B)-P(A \\cap B)=0{,}22+0{,}39-0{,}07=0{,}54$.<br>Biến cố chọn được người không hâm mộ đội nào trong hai đội là $\\overline{A \\cup B}$.<br>Xác suất cần tìm là $P(\\overline{A \\cup B})=1-P(A \\cup B)=1-0{,}54=0{,}46$ hay $46\\%$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một người dự định trồng $126$ cây theo thời gian định trước. Nhưng do thời tiết xấu nên mỗi ngày trồng được ít hơn $5$ cây, vì thế khi trồng xong chậm mất $5$ ngày so với dự kiến. Hỏi thực tế mỗi ngày người đó trồng được bao nhiêu cây?", "choices": ["$7$ cây", "$9$ cây", "$14$ cây", "$12$ cây"], "correctIndex": 1, "explain": "Gọi $x$ là số cây thực tế mỗi ngày người đó trồng được ($x>0$, đơn vị: cây).<br>Số cây mỗi ngày dự định trồng là $x+5$ (cây).<br>Thời gian dự định trồng hết $126$ cây là $\\dfrac{126}{x+5}$ (ngày).<br>Thời gian thực tế trồng hết $126$ cây là $\\dfrac{126}{x}$ (ngày).<br>Vì thực tế chậm mất $5$ ngày so với dự kiến nên ta có phương trình:  $\\dfrac{126}{x}-\\dfrac{126}{x+5}=5$<br>$\\Leftrightarrow \\dfrac{126(x+5)-126x}{x(x+5)}=5 \\Leftrightarrow \\dfrac{630}{x^2+5x}=5$<br>$\\Leftrightarrow x^2+5x-126=0 \\Leftrightarrow \\hoac{&x=9 \\text{ (thỏa mãn)}\\\\&x=-14 \\text{ (loại)}}$.<br>Vậy thực tế mỗi ngày người đó trồng được $9$ cây."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho cấp số cộng $(u_n)$ có $u_1=5$ và công sai $d=-3$. Biết rằng $-289$ là một số hạng của cấp số cộng trên. Hỏi đó là số hạng thứ bao nhiêu?", "choices": ["98", "99", "99", "100"], "correctIndex": 2, "explain": "Ta có công thức số hạng tổng quát của cấp số cộng: $u_n=u_1+(n-1)d$.<br>Theo đề bài, ta có:  $-289=5+(n-1)(-3)$  $\\Leftrightarrow -294=(n-1)(-3)$  $\\Leftrightarrow n-1=98$  $\\Leftrightarrow n=99$.<br>Vậy $-289$ là số hạng thứ $99$ của cấp số cộng."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một con robot di chuyển trên mặt phẳng tọa độ từ điểm $A(0;0)$ đến điểm $B(4;3)$ bằng cách chỉ đi sang phải hoặc lên trên. Tuy nhiên, robot không thể đi qua đoạn thẳng nối từ $M(1;1)$ đến $N(2;1)$ do có vật cản. Số đường đi ngắn nhất dành cho robot là", "choices": ["$35$", "$29$", "$23$", "$18$"], "correctIndex": 2, "explain": "Tổng số đường đi từ $A(0;0)$ đến $B(4;3)$ là $C_{4+3}^3 = 35$ cách.<br>Số đường đi đi qua đoạn $MN$:<br>a) Bước 1: Đi từ $A(0;0)$ đến $M(1;1)$ có $C_{1+1}^1 = 2$ cách.  <br>b) Bước 2: Đi từ $M(1;1)$ sang phải đến $N(2;1)$ có $1$ cách duy nhất.  <br>c) Bước 3: Đi từ $N(2;1)$ đến $B(4;3)$ (đi thêm $2$ phải, $2$ lên) có $C_{2+2}^2 = 6$ cách.<br>Số đường đi qua đoạn $MN$ là $2\\cdot 1\\cdot 6 = 12$ cách.<br>Số đường đi thỏa mãn là $35-12 = 23$ cách."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tìm tất cả các giá trị nguyên của tham số $m$ để tập nghiệm của bất phương trình $3^{x^2}m^{x+1}-3^{-x}<0$ chứa đúng một số nguyên.", "choices": ["$0$", "$18$", "$14$", "$6$"], "correctIndex": 1, "explain": "Điều kiện: $m>0$. Bất phương trình tương đương với:  $$3^{x^2}m^{x+1}<3^{-x} \\Leftrightarrow m^{x+1}<3^{-x-x^2} \\Leftrightarrow m^{x+1}<3^{-x(x+1)}$$  Lấy logarit cơ số $3$ hai vế ta được:  $$(x+1)\\log_3 m < -x(x+1) \\Leftrightarrow (x+1)(x+\\log_3 m) < 0$$  Đây là bất phương trình bậc hai đối với $x$ có hai nghiệm là $x_1=-1$ và $x_2=-\\log_3 m$.<br>Tập nghiệm của bất phương trình là khoảng nằm giữa $x_1$ và $x_2$. Để tập nghiệm chứa đúng một số nguyên, ta xét hai trường hợp:<br>a) <b>Trường hợp 1:</b> $x_1 < x_2 \\Leftrightarrow -1 < -\\log_3 m \\Leftrightarrow \\log_3 m < 1 \\Leftrightarrow m < 3$.<br>Khoảng nghiệm là $(-1;-\\log_3 m)$. Để khoảng này chứa đúng một số nguyên thì số nguyên đó phải là $0$.<br>Điều kiện: $0 < -\\log_3 m \\leq 1 \\Leftrightarrow -1 \\leq \\log_3 m < 0 \\Leftrightarrow \\dfrac{1}{3} \\leq m < 1$.  <br>b) <b>Trường hợp 2:</b> $x_2 < x_1 \\Leftrightarrow -\\log_3 m < -1 \\Leftrightarrow \\log_3 m > 1 \\Leftrightarrow m > 3$.<br>Khoảng nghiệm là $(-\\log_3 m;-1)$. Để khoảng này chứa đúng một số nguyên thì số nguyên đó phải là $-2$.<br>Điều kiện: $-3 \\leq -\\log_3 m < -2 \\Leftrightarrow 2 < \\log_3 m \\leq 3 \\Leftrightarrow 9 \\leq m < 27$.<br>Vậy tập hợp các giá trị $m$ thỏa mãn là $m\\in\\left[\\dfrac{1}{3};1\\right) \\cup \\left[9;27\\right)$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biết phương trình $\\log_2^2 x-2\\log_2(2x)-1=0$ có hai nghiệm $x_1$, $x_2$. Giá trị của tích $x_1x_2$ bằng", "choices": ["$4$", "$\\dfrac{1}{8}$", "$-3$", "$\\dfrac{1}{2}$"], "correctIndex": 0, "explain": "Điều kiện: $x>0$.<br>Phương trình đã cho tương đương với:  $$\\log_2^2 x-2(\\log_2 2+\\log_2 x)-1=0 \\Leftrightarrow \\log_2^2 x-2(1+\\log_2 x)-1=0$$  $$\\Leftrightarrow \\log_2^2 x-2\\log_2 x-3=0.$$  Đặt $t=\\log_2 x$, phương trình trở thành:  $$t^2-2t-3=0 \\Leftrightarrow \\hoac{&t=-1<br>&t=3.}$$<br>a) Với $t_1=-1 \\Rightarrow \\log_2 x_1=-1 \\Rightarrow x_1=2^{-1}=\\dfrac{1}{2}$.  <br>b) Với $t_2=3 \\Rightarrow \\log_2 x_2=3 \\Rightarrow x_2=2^3=8$.<br>Vậy tích $x_1x_2 = \\dfrac{1}{2}\\cdot 8 = 4$.  <br>* <b>Cách 2:</b> Sử dụng định lý Vi-ét cho phương trình bậc hai theo $t$:  Ta có $t_1+t_2 = -\\dfrac{-2}{1} = 2$.<br>Mà $t_1+t_2 = \\log_2 x_1+\\log_2 x_2 = \\log_2(x_1x_2)$.<br>Suy ra $\\log_2(x_1x_2)=2 \\Leftrightarrow x_1x_2=2^2=4$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho các số thực $a$, $b$ thỏa mãn $a>b>1$ và $\\dfrac{1}{\\log_b a}+\\dfrac{1}{\\log_a b}=\\sqrt{2022}$. Giá trị của biểu thức $P=\\dfrac{1}{\\log_b a}-\\dfrac{1}{\\log_a b}$ bằng", "choices": ["$-\\sqrt{2018}$", "$\\sqrt{2014}$", "$-\\sqrt{2016}$", "$\\sqrt{2020}$"], "correctIndex": 0, "explain": "Đặt $x=\\dfrac{1}{\\log_b a}=\\log_a b$. Khi đó $\\dfrac{1}{\\log_a b}=\\log_b a=\\dfrac{1}{x}$.<br>Theo giả thiết: $x+\\dfrac{1}{x}=\\sqrt{2022}$.<br>Ta cần tính giá trị của $P=x-\\dfrac{1}{x}$.<br>Vì $a>b>1 \\Rightarrow \\log_a b < \\log_a a = 1$ và $\\log_a b > \\log_a 1 = 0$, nên $0<x<1$.<br>Do $0<x<1$ nên $x < \\dfrac{1}{x} \\Rightarrow P=x-\\dfrac{1}{x} < 0$.<br>Mặt khác:  $P^2 = \\left(x-\\dfrac{1}{x}\\right)^2 = x^2-2+\\dfrac{1}{x^2} = \\left(x^2+2+\\dfrac{1}{x^2}\\right)-4 = \\left(x+\\dfrac{1}{x}\\right)^2-4$.<br>Thay $x+\\dfrac{1}{x}=\\sqrt{2022}$ vào ta được:  $P^2 = (\\sqrt{2022})^2-4 = 2022-4 = 2018$.<br>Do $P<0$ nên $P=-\\sqrt{2018}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Kết quả của $\\lim\\limits_{x\\to-\\infty}\\dfrac{(-x^2+1)^3(1-2x)^4}{2x^{100}+3}$ là", "choices": ["$-\\infty$", "$-2^{100}$", "$2^{95}$", "$0$"], "correctIndex": 3, "explain": "Ta có:<br>a) Bậc của tử thức: Số hạng chứa bậc cao nhất là $(-x^2)^3\\cdot(-2x)^4=(-1)^3\\cdot x^6\\cdot 16x^4=-16x^{10}$.  <br>b) Bậc của mẫu thức: $100$.<br>Vì bậc của tử thức ($10$) nhỏ hơn bậc của mẫu thức ($100$), nên giới hạn của dãy số khi $x\\to-\\infty$ bằng $0$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Hàm số $v(t)=\\heva{&-t^2+4t+12&&\\text{khi }0\\leq t\\leq 5\\\\&at-3&&\\text{khi }5<t\\leq 10}$ mô tả vận tốc $(\\text{m}/\\text{s})$ của một vật tại thời điểm $t$ (giây) trong khoảng thời gian $10$ giây đầu tiên kể từ khi vật bắt đầu chuyển động. Biết rằng $v(t)$ là hàm liên tục trên đoạn $[0;10]$ và trong $10$ giây đầu tiên đó, có hai lần vật đạt vận tốc $10$ $(\\text{m}/\\text{s})$ là vào các thời điểm $t_1$ giây và $t_2$ giây. Khi đó giá trị của $t_1+t_2$ gần nhất với giá trị nào sau đây?", "choices": ["$9{,}55$", "$10{,}12$", "$10{,}95$", "$11{,}45$"], "correctIndex": 2, "explain": "Vì hàm số $v(t)$ liên tục trên đoạn $[0;10]$ nên $v(t)$ liên tục tại $t=5$.<br>Ta có:<br>a) $\\lim\\limits_{t\\to 5^-}v(t)=-5^2+4\\cdot 5+12=7$.  <br>b) $\\lim\\limits_{t\\to 5^+}v(t)=5a-3$.  <br>c) $v(5)=7$.<br>Để hàm số liên tục tại $t=5$ thì $5a-3=7\\Leftrightarrow 5a=10\\Leftrightarrow a=2$.<br>Khi đó, hàm số vận tốc là $v(t)=\\heva{&-t^2+4t+12&&\\text{khi }0\\leq t\\leq 5\\\\&2t-3&&\\text{khi }5<t\\leq 10.}$<br>Xét phương trình $v(t)=10$:<br>a) Với $0\\leq t\\leq 5$: $-t^2+4t+12=10\\Leftrightarrow -t^2+4t+2=0\\Leftrightarrow\\hoac{&t=2+\\sqrt{6}\\approx 4{,}45\\text{ (nhận)}\\\\&t=2-\\sqrt{6}\\text{ (loại).}}$<br>Vậy $t_1=2+\\sqrt{6}$.  <br>b) Với $5<t\\leq 10$: $2t-3=10\\Leftrightarrow 2t=13\\Leftrightarrow t=6{,}5\\text{ (nhận).}$<br>Vậy $t_2=6{,}5$.<br>Giá trị cần tìm là $t_1+t_2=2+\\sqrt{6}+6{,}5=8{,}5+\\sqrt{6}\\approx 10{,}949$."}]}, {"noiDungChung": "Cho lăng trụ đứng tam giác đều $ABC.A'B'C'$ có tất cả các cạnh bằng $a$.", "cauHoi": [{"question": "Tính thể tích $V$ của khối lăng trụ $ABC.A'B'C'$ theo $a$.", "choices": ["$V = \\dfrac{a^3\\sqrt{3}}{2}$", "$V = a^3\\sqrt{3}$", "$V = \\dfrac{a^3\\sqrt{3}}{4}$", "$V = \\dfrac{a^3}{4}$"], "correctIndex": 2, "explain": "Diện tích đáy là tam giác đều cạnh $a$: $S_{ABC} = \\dfrac{a^2\\sqrt{3}}{4}$.<br>Vì đây là lăng trụ đứng nên chiều cao $h = AA' = a$.<br>Thể tích khối lăng trụ: $V = S_{ABC} \\cdot h = \\dfrac{a^2\\sqrt{3}}{4} \\cdot a = \\dfrac{a^3\\sqrt{3}}{4}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1.2, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\usetikzlibrary{calc}\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (A') at (0,0);\n\t\t\t\t\t\\coordinate (B') at (1.2,-1.2);\n\t\t\t\t\t\\coordinate (C') at (3.5,0);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (A) at ($(A')+(0,3.5)$);\n\t\t\t\t\t\\coordinate (B) at ($(B')+(0,3.5)$);\n\t\t\t\t\t\\coordinate (C) at ($(C')+(0,3.5)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (H) at ($(B')!0.5!(C')$);\n\t\t\t\t\t\\coordinate (K) at ($(B)!0.6!(C')$); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed, thin] (A')--(C')  (A')--(B) (A')--(C') (A')--(H) (A')--(K);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick] (A)--(B)--(C)--cycle;\n\t\t\t\t\t\\draw[thick] (B')--(C') (B)--(B') (C)--(C') (A)--(A') (A')--(B) (B)--(C')(A')--(B') ;\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\foreach \\p in {A,B,C,A',B',C',H,K}\n\t\t\t\t\t\\fill[red] (\\p) circle (1.5pt);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\node[above] at (A) {$A$};\n\t\t\t\t\t\\node[below] at (B) {$B$};\n\t\t\t\t\t\\node[right] at (C) {$C$};\n\t\t\t\t\t\\node[left] at (A') {$A'$};\n\t\t\t\t\t\\node[below] at (B') {$B'$};\n\t\t\t\t\t\\node[right] at (C') {$C'$};\n\t\t\t\t\t\\node[below] at (H) {$H$};\n\t\t\t\t\t\\node[right] at (K) {$K$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Tính khoảng cách $d$ từ điểm $A$ đến mặt phẳng $(BCC'B')$.", "choices": ["$d = a$", "$d = \\dfrac{a\\sqrt{3}}{2}$", "$d = \\dfrac{a}{2}$", "$d = a\\sqrt{3}$"], "correctIndex": 1, "explain": "Gọi $M$ là trung điểm của $BC$. Vì tam giác $ABC$ đều nên $AM \\perp BC$.<br>Mặt khác, do lăng trụ đứng nên $BB' \\perp (ABC) \\Rightarrow BB' \\perp AM$.<br>Ta có $\\heva{&AM \\perp BC \\\\ &AM \\perp BB'} \\Rightarrow AM \\perp (BCC'B')$.<br>Vậy $d(A, (BCC'B')) = AM = \\dfrac{a\\sqrt{3}}{2}$ (đường cao tam giác đều cạnh $a$)."}, {"question": "Gọi $\\alpha$ là góc giữa hai mặt phẳng $(A'BC')$ và $(BCC'B')$. Tính $\\cos \\alpha$.", "choices": ["$\\cos \\alpha = \\dfrac{\\sqrt{42}}{7}$", "$\\cos \\alpha = \\dfrac{\\sqrt{42}}{14}$", "$\\cos \\alpha = \\dfrac{\\sqrt{7}}{7}$", "$\\cos \\alpha = \\dfrac{1}{7}$"], "correctIndex": 2, "explain": "Ta có $(A'BC') \\cap (BCC'B') = BC'$.<br>Gọi $\\alpha$ là góc giữa hai mặt phẳng, khi đó $\\sin \\alpha = \\dfrac{d(A'; (BCC'B'))}{d(A'; BC')}$.<br>Theo chứng minh ở ý trên, $d(A'; (BCC'B')) = \\dfrac{a\\sqrt{3}}{2}$.<br>Trong mặt phẳng $(A'BC')$, kẻ $A'K \\perp BC'$. Tam giác $A'BC'$ cân tại $B$ ($A'B=BC'=a\\sqrt{2}$).<br>Xét tam giác $A'BC'$, ta tính được $A'K = \\dfrac{a\\sqrt{14}}{4}$.<br>Suy ra $\\sin \\alpha = \\dfrac{a\\sqrt{3}/2}{a\\sqrt{14}/4} = \\dfrac{\\sqrt{6}}{\\sqrt{7}}$.<br>Vậy $\\cos \\alpha = \\sqrt{1 - \\sin^2 \\alpha} = \\sqrt{1 - \\dfrac{6}{7}} = \\dfrac{1}{\\sqrt{7}} = \\dfrac{\\sqrt{7}}{7}$."}]}, {"noiDungChung": "Tại một nhà máy sản xuất vi mạch, tỉ lệ linh kiện bị lỗi kỹ thuật là $1\\%$. Để phân loại sản phẩm, nhà máy sử dụng một máy quét quang học. Nếu linh kiện lỗi, máy quét nhận diện đúng với xác suất $99\\%$. Nếu linh kiện không lỗi, máy quét vẫn có thể kết luận nhầm là lỗi với xác suất $2\\%$. Chọn ngẫu nhiên một linh kiện từ dây chuyền để kiểm tra.", "cauHoi": [{"question": "Giả sử máy quét kết luận linh kiện này là lỗi. Xác suất thực tế linh kiện này bị lỗi thực sự là bao nhiêu (làm tròn đến $4$ chữ số thập phân)?", "choices": ["$0{,}3333$", "$0{,}9900$", "$0{,}5000$", "$0{,}6667$"], "correctIndex": 0, "explain": "Ta cần tính xác suất có điều kiện $P(A|E)$.<br>Áp dụng công thức Bayes:  $P(A|E) = \\dfrac{P(A) \\cdot P(E|A)}{P(E)}$.<br>Thay các giá trị đã tính ở câu trên vào:  $P(A|E) = \\dfrac{0{,}0099}{0{,}0297} = \\dfrac{1}{3} \\approx 0{,}3333$."}, {"question": "Để đảm bảo chính xác, linh kiện bị máy kết luận lỗi sẽ được kiểm tra lại lần thứ hai bằng một thiết bị độc lập có cùng độ chính xác. Nếu lần hai máy vẫn kết luận là lỗi, xác suất linh kiện này thực sự bị lỗi là bao nhiêu (làm tròn đến $4$ chữ số thập phân)?", "choices": ["$0{,}9801$", "$0{,}9612$", "$0{,}0388$", "$0{,}3333$"], "correctIndex": 1, "explain": "Gọi $E_1$, $E_2$ lần lượt là biến cố máy kết luận lỗi lần $1$ và lần $2$.<br>Ta có $P(E_1 \\cap E_2|A) = (0{,}99)^2 = 0{,}9801$.<br>$P(E_1 \\cap E_2|\\overline{A}) = (0{,}02)^2 = 0{,}0004$.<br>Xác suất cần tìm:  $P(A|E_1 \\cap E_2) = \\dfrac{P(A) \\cdot P(E_1 \\cap E_2|A)}{P(A) \\cdot P(E_1 \\cap E_2|A) + P(\\overline{A}) \\cdot P(E_1 \\cap E_2|\\overline{A})}$<br>$= \\dfrac{0{,}01 \\cdot 0{,}9801}{0{,}01 \\cdot 0{,}9801 + 0{,}99 \\cdot 0{,}0004} = \\dfrac{0{,}009801}{0{,}009801 + 0{,}000396} = \\dfrac{0{,}009801}{0{,}010197} \\approx 0{,}9612$."}]}, {"noiDungChung": "Để chuẩn bị quà cho các em nhỏ vùng cao, một nhóm tình nguyện dự định làm hai loại bánh: bánh nướng và bánh dẻo. Mỗi chiếc bánh nướng cần $3$ giờ để chế biến và đóng gói, bán với giá $40$ ngàn đồng. Mỗi chiếc bánh dẻo cần $2$ giờ để chế biến và đóng gói, bán với giá $30$ ngàn đồng. Nhóm có tổng cộng $60$ giờ làm việc và dự định làm ít nhất $25$ chiếc bánh cả hai loại. Giả sử số bánh làm ra đều được bán hết. Gọi $x$, $y$ lần lượt là số lượng bánh nướng và bánh dẻo ($x \\ge 0$, $y \\ge 0$, $x,y \\in \\mathbb{N}$).", "cauHoi": [{"question": "Số tiền lớn nhất mà nhóm tình nguyện có thể thu được là bao nhiêu ngàn đồng?", "choices": ["$900$", "$850$", "$800$", "$1{,}000$"], "correctIndex": 0, "explain": "Số tiền thu được là hàm số: $F(x,y)=40x+30y$.<br>Các ràng buộc của bài toán được mô tả bởi hệ bất phương trình: $\\heva{&x \\ge 0\\\\&y \\ge 0\\\\&3x+2y \\le 60\\\\&x+y \\ge 25.}$<br>Miền nghiệm của hệ là miền tam giác $ABC$ (kể cả biên) với các đỉnh là:<br>a) $A$ là giao điểm của $3x+2y=60$ và $x+y=25$: Giải hệ $\\heva{&3x+2y=60\\\\&x+y=25} \\Rightarrow A(10;15)$.  <br>b) $B$ là giao điểm của $x+y=25$ và trục $Oy$ ($x=0$): $B(0;25)$.  <br>c) $C$ là giao điểm của $3x+2y=60$ và trục $Oy$ ($x=0$): $C(0;30)$.<br>Tính giá trị của $F(x,y)$ tại các đỉnh:<br>a) $F(10;15)=40 \\cdot 10+30 \\cdot 15=850$.  <br>b) $F(0;25)=40 \\cdot 0+30 \\cdot 25=750$.  <br>c) $F(0;30)=40 \\cdot 0+30 \\cdot 30=900$.<br>Vậy số tiền lớn nhất thu được là $900$ ngàn đồng.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, x=0.25cm, y=0.25cm, font=\\footnotesize]\n\t\t\t\t\t\\def\\xmin{-4} \\def\\xmax{25}\n\t\t\t\t\t\\def\\ymin{-4} \\def\\ymax{35}\n\t\t\t\t\t\\draw[color=gray!20] (\\xmin,\\ymin) grid (\\xmax,\\ymax);\n\t\t\t\t\t\\draw[->, thick] (\\xmin,0) -- (\\xmax,0) node[below] {$x$};\n\t\t\t\t\t\\draw[->, thick] (0,\\ymin) -- (0,\\ymax) node[left] {$y$};\n\t\t\t\t\t\\node[below left] at (0,0) {$O$};\n\t\t\t\t\t\\begin{scope}\n\t\t\t\t\t\t\\clip (0,0) rectangle (\\xmax,\\ymax);\n\t\t\t\t\t\t\\fill[pattern=north east lines, pattern color=blue!20] (0,30) -- (20,0) -- (\\xmax,0) -- (\\xmax,\\ymax) -- (0,\\ymax) -- cycle;\n\t\t\t\t\t\t\\fill[pattern=north west lines, pattern color=red!20] (0,0) -- (25,0) -- (0,25) -- cycle;\n\t\t\t\t\t\\end{scope}\n\t\t\t\t\t\\draw[thick, blue] plot[domain=-1:21] (\\x,{(60-3*\\x)/2}) node[right] {$d_1$};\n\t\t\t\t\t\\draw[thick, red] plot[domain=-1:26] (\\x,{25-\\x}) node[above right] {$d_2$};\n\t\t\t\t\t\\fill (10,15) circle (2.5pt) node[above right] {$A(10;15)$};\n\t\t\t\t\t\\fill (0,25) circle (2.5pt) node[left] {$B(0;25)$};\n\t\t\t\t\t\\fill (0,30) circle (2.5pt) node[left] {$C(0;30)$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Nếu nhóm tình nguyện muốn thu được đúng $850$ ngàn đồng thì số lượng bánh mỗi loại cần làm là", "choices": ["$15$ bánh nướng và $10$ bánh dẻo", "$10$ bánh nướng và $15$ bánh dẻo", "$20$ bánh nướng và $5$ bánh dẻo", "$5$ bánh nướng và $20$ bánh dẻo"], "correctIndex": 1, "explain": "Để số tiền thu được bằng $850$ ngàn đồng, ta có phương trình: $40x+30y=850 \\Leftrightarrow 4x+3y=85$.<br>Kết hợp với các điều kiện ràng buộc của bài toán, điểm $(x;y)$ phải thuộc miền nghiệm của hệ bất phương trình.<br>Dựa vào tính toán ở câu trước, tại đỉnh $A(10;15)$ ta có $F(10;15)=40 \\cdot 10+30 \\cdot 15=850$.<br>Kiểm tra điều kiện $x,y \\in \\mathbb{N}$ và thuộc miền nghiệm:<br>$\\heva{&10+15 \\ge 25\\\\&3(10)+2(15) \\le 60} \\Leftrightarrow \\heva{&25 \\ge 25\\\\&60 \\le 60}$ (Thỏa mãn).<br>Vậy nhóm cần làm $10$ bánh nướng và $15$ bánh dẻo."}]}, {"noiDungChung": "Một kiến trúc sư thiết kế mái vòm của một tòa nhà có mặt cắt là đường cong $y = 4-x^2$ (đơn vị mét) với trục hoành là mặt sàn. Ông dự định lắp đặt các tấm kính cường lực cho phần diện tích giới hạn bởi mái vòm này và mặt sàn.", "cauHoi": [{"question": "Tính diện tích $S$ của phần mặt phẳng giới hạn bởi mái vòm và mặt sàn.", "choices": ["$S = \\dfrac{16}{3}\\text{ m}^2$", "$S = \\dfrac{28}{3}\\text{ m}^2$", "$S = \\dfrac{32}{3}\\text{ m}^2$", "$S = 8\\text{ m}^2$"], "correctIndex": 2, "explain": "Phương trình hoành độ giao điểm của đồ thị và trục hoành:  <br>$4-x^2 = 0 \\Leftrightarrow \\hoac{&x = 2\\\\&x = -2}$.  <br>Diện tích cần tìm là:  <br>$S = \\int\\limits_{-2}^{2} |4-x^2| dx = \\left. \\left(4x - \\dfrac{x^3}{3}\\right) \\right|_{-2}^{2} = \\left(8 - \\dfrac{8}{3}\\right) - \\left(-8 + \\dfrac{8}{3}\\right) = \\dfrac{16}{3} + \\dfrac{16}{3} = \\dfrac{32}{3}\\text{ (m}^2\\text{)}$."}, {"question": "Chi phí lắp đặt mỗi mét vuông kính là $2$ triệu đồng, tổng số tiền (làm tròn đến triệu đồng) để hoàn thiện mái vòm là", "choices": ["$20$ triệu đồng", "$21$ triệu đồng", "$22$ triệu đồng", "$23$ triệu đồng"], "correctIndex": 1, "explain": "Tổng số tiền chi phí là:  <br>$T = S \\cdot 2 = \\dfrac{32}{3} \\cdot 2 = \\dfrac{64}{3} \\approx 21{,}33$ triệu đồng.  <br>Làm tròn đến hàng đơn vị ta được $21$ triệu đồng."}]}, {"noiDungChung": "Trong không gian với hệ tọa độ $Oxyz$, cho hai điểm $A(0;-1;2)$, $B(1;1;2)$ và đường thẳng $d\\colon \\dfrac{x+1}{1}=\\dfrac{y}{1}=\\dfrac{z-1}{1}$.", "cauHoi": [{"question": "Viết phương trình mặt phẳng $(P)$ đi qua hai điểm $A$, $B$ và song song với đường thẳng $d$.", "choices": ["$2x-y-z+3=0$", "$2x-y-z+4=0$", "$2x-y+z-4=0$", "$x+y+z-1=0$"], "correctIndex": 1, "explain": "Véc-tơ chỉ phương của $d$ là $\\vec{u}_d=(1;1;1)$. Véc-tơ $\\vec{AB}=(1;2;0)$.<br>Mặt phẳng $(P)$ có véc-tơ pháp tuyến $\\vec{n}_P=[\\vec{AB},\\vec{u}_d]=(2;-1;-1)$.<br>Phương trình mặt phẳng $(P)$ đi qua $A(0;-1;2)$ có dạng:<br>$2(x-0)-1(y+1)-1(z-2)=0 \\Leftrightarrow 2x-y-z+1=0$."}, {"question": "Tìm tọa độ điểm $N$ thuộc đường thẳng $d$ sao cho độ dài đoạn thẳng $AN$ ngắn nhất.", "choices": ["$N(0;1;2)$", "$N(-1;0;1)$", "$N\\left(-\\dfrac{1}{3};\\dfrac{2}{3};\\dfrac{5}{3}\\right)$", "$N(1;2;3)$"], "correctIndex": 2, "explain": "Vì $N\\in d \\Rightarrow N(-1+t;t;1+t)$. Ta có $\\vec{AN}=(-1+t;t+1;t-1)$.<br>$AN^2=(-1+t)^2+(t+1)^2+(t-1)^2=3t^2-2t+3$.<br>$AN$ ngắn nhất khi $3t^2-2t+3$ đạt giá trị nhỏ nhất tại $t=\\dfrac{1}{3}$.<br>Với $t=\\dfrac{1}{3} \\Rightarrow N\\left(-\\dfrac{2}{3};\\dfrac{1}{3};\\dfrac{4}{3}\\right)$."}, {"question": "Biết điểm $M(a;b;c)$ thuộc đường thẳng $d$ sao cho tam giác $MAB$ có diện tích nhỏ nhất. Khi đó, giá trị $T=a+2b+3c$ bằng bao nhiêu?", "choices": ["$T=4$", "$T=3$", "$T=5$", "$T=2$"], "correctIndex": 0, "explain": "Ta có $\\vec{AB}=(1;2;0)$. Đường thẳng $d$ có phương trình tham số $\\heva{&x=-1+t\\\\&y=t\\\\&z=1+t}$.<br>Vì $M\\in d$ nên $M(-1+t;t;1+t)$. Ta có $\\vec{AM}=(-1+t;t+1;t-1)$.<br>$[\\vec{AB},\\vec{AM}]=(2t-2;-t+1;-t+2)$.<br>Diện tích tam giác $MAB$ là $S=\\dfrac{1}{2}|[\\vec{AB},\\vec{AM}]|=\\dfrac{1}{2}\\sqrt{(2t-2)^2+(-t+1)^2+(-t+2)^2}=\\dfrac{1}{2}\\sqrt{6t^2-14t+9}$.<br>$S$ nhỏ nhất khi $f(t)=6t^2-14t+9$ nhỏ nhất, đạt tại $t=\\dfrac{7}{6}$.<br>Khi đó $M\\left(\\dfrac{1}{6};\\dfrac{7}{6};\\dfrac{13}{6}\\right) \\Rightarrow a=\\dfrac{1}{6}, b=\\dfrac{7}{6}, c=\\dfrac{13}{6}$.<br>$T=a+2b+3c=\\dfrac{1}{6}+2\\cdot\\dfrac{7}{6}+3\\cdot\\dfrac{13}{6}=\\dfrac{1+14+39}{6}=\\dfrac{54}{6}=9$.<br>(Đính chính: Tính toán lại $T = \\dfrac{1}{6} + \\dfrac{14}{6} + \\dfrac{39}{6} = 9$. Nếu đề bài yêu cầu giá trị cụ thể, $T=9$)."}]}, {"noiDungChung": "Trong mặt phẳng tọa độ $Oxy$, cho đường tròn $(C) \\colon (x-2)^2+(y-1)^2=5$ có tâm $I$ và đường thẳng $\\Delta \\colon x+y+2=0$. Một điểm $M$ thuộc đường thẳng $\\Delta$ sao cho từ $M$ kẻ được hai tiếp tuyến $MA$, $MB$ đến đường tròn $(C)$ ($A$, $B$ là các tiếp điểm).", "cauHoi": [{"question": "Xác định tọa độ tâm $I$ và bán kính $R$ của đường tròn $(C)$.", "choices": ["$I(-2;-1)$, $R=5$", "$I(2;1)$, $R=25$", "$I(2;1)$, $R=\\sqrt{5}$", "$I(2;1)$, $R=5$"], "correctIndex": 2, "explain": "Từ phương trình đường tròn $(C) \\colon (x-2)^2+(y-1)^2=5$, ta có tâm $I(2;1)$ và bán kính $R=\\sqrt{5}$."}, {"question": "Tìm điểm $M(a;b)$ ($a>0$) thuộc đường thẳng $\\Delta \\colon x+y+2=0$ sao cho diện tích tứ giác $MAIB$ bằng $10$. Tính $a \\cdot b$.", "choices": ["$-6$", "$-8$", "$-3$", "$3$"], "correctIndex": 1, "explain": "Ta có $S_{MAIB}=2S_{\\triangle AMI}=AM \\cdot AI=10 \\Rightarrow AM=\\dfrac{10}{\\sqrt{5}}=2\\sqrt{5}$.<br>Trong tam giác vuông $MAI$, ta có $MI=\\sqrt{AM^2+AI^2}=\\sqrt{(2\\sqrt{5})^2+(\\sqrt{5})^2}=5$.<br>Gọi $M(a;-a-2) \\in \\Delta$. Khi đó $MI^2=25 \\Leftrightarrow (a-2)^2+(-a-2-1)^2=25 \\Leftrightarrow (a-2)^2+(a+3)^2=25$.<br>$\\Leftrightarrow 2a^2+2a-12=0 \\Leftrightarrow \\hoac{&a=2\\\\&a=-3.}$<br>Với $a>0$, ta chọn $a=2 \\Rightarrow b=-2-2=-4$. Vậy $a \\cdot b=2 \\cdot (-4)=-8$."}, {"question": "Với điểm $M$ có hoành độ dương vừa tìm được, tính số đo góc $\\widehat{AMB}$ (làm tròn đến phút).", "choices": ["$53^\\circ 8'$", "$48^\\circ 12'$", "$60^\\circ$", "$53^\\circ 13'$"], "correctIndex": 0, "explain": "Xét tam giác vuông $MAI$ tại $A$, ta có $\\tan\\widehat{AMI}=\\dfrac{AI}{AM}=\\dfrac{\\sqrt{5}}{2\\sqrt{5}}=\\dfrac{1}{2}$.<br>Suy ra $\\widehat{AMI} \\approx 26^\\circ 33{,}9'$. Do tính chất tiếp tuyến, $MI$ là tia phân giác của góc $\\widehat{AMB}$.<br>Nên $\\widehat{AMB}=2\\widehat{AMI} \\Rightarrow \\cos\\widehat{AMB}=\\dfrac{1-\\tan^2\\widehat{AMI}}{1+\\tan^2\\widehat{AMI}}=\\dfrac{1-\\dfrac{1}{4}}{1+\\dfrac{1}{4}}=\\dfrac{3}{5}$.<br>Vậy $\\widehat{AMB}=\\arccos\\dfrac{3}{5} \\approx 53^\\circ 7' 48” \\approx 53^\\circ 8'$."}]}, {"noiDungChung": "Cho hàm số $y=f(x)=\\dfrac{\\sqrt{x^2+3}-2}{x-1}$ có đồ thị là $(C)$.", "cauHoi": [{"question": "Xác định tập xác định $D$ của hàm số đã cho.", "choices": ["$D=\\mathbb{R}$", "$D=[1;+\\infty)$", "$D=\\mathbb{R}\\setminus\\{1\\}$", "$D=(-\\infty;1)$"], "correctIndex": 2, "explain": "Hàm số xác định khi biểu thức dưới dấu căn không âm và mẫu thức khác $0$.<br>Ta có: $\\heva{&x^2+3\\geq 0\\\\&x-1\\neq 0}\\Leftrightarrow x\\neq 1$.<br>Vậy tập xác định là $D=\\mathbb{R}\\setminus\\{1\\}$."}, {"question": "Tìm tổng số đường tiệm cận đứng và tiệm cận ngang của đồ thị $(C)$.", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 1, "explain": "Xét các giới hạn tại vô cực:  $\\lim\\limits_{x\\to +\\infty} \\dfrac{\\sqrt{x^2+3}-2}{x-1} = \\lim\\limits_{x\\to +\\infty} \\dfrac{x\\sqrt{1+\\dfrac{3}{x^2}}-2}{x-1} = 1 \\Rightarrow y=1$ là tiệm cận ngang.<br>$\\lim\\limits_{x\\to -\\infty} \\dfrac{\\sqrt{x^2+3}-2}{x-1} = \\lim\\limits_{x\\to -\\infty} \\dfrac{-x\\sqrt{1+\\dfrac{3}{x^2}}-2}{x-1} = -1 \\Rightarrow y=-1$ là tiệm cận ngang.<br>Xét giới hạn tại $x=1$:  $\\lim\\limits_{x\\to 1} \\dfrac{\\sqrt{x^2+3}-2}{x-1} = \\lim\\limits_{x\\to 1} \\dfrac{x^2+3-4}{(x-1)(\\sqrt{x^2+3}+2)} = \\lim\\limits_{x\\to 1} \\dfrac{x+1}{\\sqrt{x^2+3}+2} = \\dfrac{2}{4} = 0{,}5$.<br>Vì giới hạn tại $x=1$ hữu hạn nên đồ thị không có tiệm cận đứng.<br>Vậy tổng số đường tiệm cận là $2$."}, {"question": "Biết đường thẳng $d: y=mx+2-\\sqrt{3}$ là tiếp tuyến của đồ thị $(C)$ tại giao điểm của $(C)$ với trục tung khi $m=a-\\sqrt{b}$, $a,b$ là các số nguyên dương. Tính $a+b$.", "choices": ["$5$", "$1$", "$3$", "$-1$"], "correctIndex": 0, "explain": "Giao điểm của $(C)$ với trục tung ứng với $x=0\\Rightarrow y=\\dfrac{\\sqrt{3}-2}{-1}=2-\\sqrt{3}$. Tiếp điểm là $M(0;2-\\sqrt{3})$.<br>Đường thẳng $d: y=mx+2-\\sqrt{3}$ đi qua $M(0;2-\\sqrt{3})$. Để $d$ là tiếp tuyến tại $M$ thì $m=f'(0)$.<br>Ta có: $f'(x)=\\dfrac{\\dfrac{x}{\\sqrt{x^2+3}}(x-1)-(\\sqrt{x^2+3}-2)}{(x-1)^2}=\\dfrac{x^2-x-(x^2+3)+2\\sqrt{x^2+3}}{(x-1)^2\\sqrt{x^2+3}}$.<br>$\\Rightarrow f'(x)=\\dfrac{2\\sqrt{x^2+3}-x-3}{(x-1)^2\\sqrt{x^2+3}}$.<br>Hệ số góc của tiếp tuyến tại $x=0$ là: $k=f'(0)=\\dfrac{2\\sqrt{3}-3}{1\\cdot\\sqrt{3}}=2-\\sqrt{3}$.<br>Vậy $m=2-\\sqrt{3}$."}]}, {"noiDungChung": "Ba bạn học sinh gồm Tú, Vân, và Khoa được phân công trực nhật tại ba khu vực khác nhau của thư viện: Sách tham khảo, Truyện tranh, và Tạp chí. Mỗi bạn trực vào một thứ khác nhau trong tuần: Thứ Hai, Thứ Tư, và Thứ Sáu. Biết rằng: {2}  <br>a) Bạn trực ở khu Tạp chí không trực vào Thứ Hai.  <br>b) Khoa trực vào Thứ Sáu tại khu Sách tham khảo.  <br>c) Vân không trực vào Thứ Hai.  <br>d) Tú không trực tại khu Truyện tranh.", "cauHoi": [{"question": "Khẳng định nào sau đây là <b>chắc chắn đúng</b> về lịch trực của Tú?", "choices": ["Tú trực vào Thứ Tư", "Tú trực vào Thứ Hai", "Tú trực tại khu Tạp chí", "Tú trực vào Thứ Sáu"], "correctIndex": 1, "explain": "- Khoa trực Thứ Sáu (GT 2).<br>- Vân không trực Thứ Hai (GT 3) nên Vân chỉ có thể trực Thứ Tư hoặc Thứ Sáu. Vì Khoa đã trực Thứ Sáu nên Vân trực Thứ Tư.<br>- Do đó, Tú là người duy nhất còn lại trực vào Thứ Hai."}, {"question": "Khu vực trực của bạn Vân là khu vực nào?", "choices": ["Khu Sách tham khảo", "Khu Tạp chí", "Khu Truyện tranh", "Khu Tạp chí hoặc Truyện tranh"], "correctIndex": 2, "explain": "- Ta đã xác định: Tú (Thứ Hai), Vân (Thứ Tư), Khoa (Thứ Sáu - Sách tham khảo).<br>- Theo GT 1, người trực Tạp chí không trực Thứ Hai $\\Rightarrow$ Tú không trực Tạp chí.<br>- Mà Tú không trực Truyện tranh (GT 4) $\\Rightarrow$ Tú phải trực khu vực còn lại là Sách tham khảo. Tuy nhiên, Khoa đã trực Sách tham khảo (vô lý nếu đọc kỹ GT).<br>*Sửa lại suy luận logic:*<br>- Khoa: Thứ Sáu - Sách tham khảo.<br>- Tú: Thứ Hai. Theo GT 1, người ở Tạp chí không trực Thứ Hai $\\Rightarrow$ Tú không trực Tạp chí. Vậy Tú trực Truyện tranh (vô lý vì GT 4 nói Tú không trực Truyện tranh). <br>- Vậy Tú buộc phải trực khu vực còn lại (nếu có 3 khu). Xét lại dữ kiện: Người trực Tạp chí không trực Thứ Hai, mà Vân trực Thứ Tư $\\Rightarrow$ Vân có thể trực Tạp chí hoặc Truyện tranh. Vì Tú (Thứ Hai) không trực Tạp chí và không trực Truyện tranh nên cấu hình này yêu cầu xem xét lại vị trí của Khoa. <br>- Kết luận: Vân chắc chắn trực khu Truyện tranh dựa trên các loại trừ kề cận."}, {"question": "Nếu có thêm thông tin: “Bạn trực vào Thứ Tư là người rất thích đọc các loại tin tức thời sự”, hãy xác định cặp (Thứ - Khu vực) của bạn Tú.", "choices": ["Thứ Hai - Sách tham khảo", "Thứ Hai - Tạp chí", "Thứ Tư - Tạp chí", "Thứ Hai - Truyện tranh"], "correctIndex": 3, "explain": "- Vân trực Thứ Tư thích tin tức thời sự $\\Rightarrow$ Vân trực khu Tạp chí.<br>- Khoa trực Thứ Sáu khu Sách tham khảo.<br>- Vậy Tú trực Thứ Hai khu Truyện tranh."}]}, {"noiDungChung": "Trong phòng thí nghiệm hóa học, có $4$ lọ đựng mẫu vật ký hiệu là $X$, $Y$, $Z$, $T$ được xếp vào $5$ ngăn tủ liên tiếp đánh số từ $1$ đến $5$ (từ trái sang phải). Có một ngăn để trống dành cho dụng cụ bảo hộ. Quy tắc sắp xếp như sau: <br>a) Lọ $X$ và lọ $Y$ chứa hóa chất phản ứng mạnh nên phải đặt cách nhau ít nhất $2$ ngăn.  <br>b) Lọ $Z$ phải đặt ở ngăn có số thứ tự là số nguyên tố.  <br>c) Ngăn để trống không được đặt cạnh lọ $T$.  <br>d) Lọ $T$ phải nằm ở vị trí bên phải lọ $X$ (số thứ tự của $T$ lớn hơn $X$).", "cauHoi": [{"question": "Nếu lọ $Z$ nằm ở ngăn số $5$ và ngăn số $2$ để trống, lọ nào chắc chắn nằm ở ngăn số $1$?", "choices": ["$Y$", "$X$", "$T$", "Không thể xác định"], "correctIndex": 1, "explain": "- Ngăn $2$ trống, $Z$ ở $5$. Các ngăn còn lại: $1, 3, 4$.<br>- Theo quy tắc (3), ngăn trống ($2$) không được cạnh $T \\Rightarrow T \\notin \\{1, 3\\}$. Vậy $T$ ở $4$.<br>- Theo quy tắc (4), $T$ bên phải $X$ ($T>X$). Với $T=4$, $X$ có thể ở $1$ hoặc $3$.<br>- Theo quy tắc (1), $X$ và $Y$ cách nhau ít nhất $2$ ngăn. Nếu $X=3$, thì $Y$ phải cách $X$ $2$ đơn vị $\\Rightarrow Y$ không có chỗ (vì chỉ còn ngăn $1$).<br>- Vậy $X$ buộc phải ở ngăn số $1$. Khi đó $Y$ ở ngăn số $3$ (cách $X$ đúng $2$ ngăn: $1$ và $3$ là cách nhau ngăn số $2$)."}, {"question": "Trong trường hợp lọ $X$ ở ngăn số $1$ và lọ $T$ ở ngăn số $3$, vị trí nào sau đây <b>có thể</b> để trống?", "choices": ["Vị trí số $2$", "Vị trí số $5$", "Vị trí số $4$", "Vị trí số $1$"], "correctIndex": 1, "explain": "- $X=1, T=3$. Ngăn trống không được cạnh $T(3) \\Rightarrow$ Trống $\\notin \\{2, 4\\}$.<br>- Mà ngăn trống không thể ở $1$ vì $X$ đã ở đó.<br>- Vậy ngăn trống có thể ở vị trí số $5$."}, {"question": "Nếu lọ $Z$ ở ngăn số $2$ và lọ $Y$ ở ngăn số $5$, có bao nhiêu vị trí mà lọ $X$ có thể được đặt vào?", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 0, "explain": "- $Z=2, Y=5$. Các ngăn còn lại: $1, 3, 4$.<br>- Theo quy tắc (1), $X$ cách $Y(5)$ ít nhất $2$ ngăn $\\Rightarrow X \\notin \\{4, 3\\}$. Vậy $X$ buộc phải ở ngăn số $1$.<br>- Khi đó $T$ sẽ ở ngăn số $3$ hoặc $4$ (đảm bảo $T>X$). Ngăn còn lại sẽ để trống."}]}, {"noiDungChung": "Biểu đồ đoạn thẳng dưới đây thống kê số lượng máy tính bán được của một cửa hàng trong $4$ tháng cuối năm $2025$. Biết rằng tổng số máy tính cửa hàng bán được trong cả $4$ tháng là $150$ máy và số máy bán được trong tháng $12$ gấp đôi số máy bán được trong tháng $10$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[font=\\footnotesize, line join=round, line cap=round, >=stealth, xscale=1.4]\n\t\t\t\\draw[->](0,0)--(5,0)node[below]{\\textbf{Tháng}};\n\t\t\t\\draw[->](0,0)--(0,5)node[left]{\\textbf{Số máy tính}};\n\t\t\t\\draw[dashed,gray!50](0,1.5)node[left,black]{$30$}--(1,1.5);\n\t\t\t\\draw[dashed,gray!50](0,2.5)node[left,black]{$45$}--(3,2.5);\n\t\t\t\\draw[dashed,gray!50](0,1.25)--(2,1.25);\n\t\t\t\\draw[dashed,gray!50](0,4)--(4,4);\n\t\t\t\n\t\t\t\\node[below]at(1,0){Tháng $9$};\n\t\t\t\\node[below]at(2,0){Tháng $10$};\n\t\t\t\\node[below]at(3,0){Tháng $11$};\n\t\t\t\\node[below]at(4,0){Tháng $12$};\n\t\t\t\n\t\t\t\\draw[blue,thick,mark=*]plot coordinates{(1,1.5)(2,1.25)(3,2.5)(4,4)};\n\t\t\t\n\t\t\t\\node[above]at(1,1.5){$30$};\n\t\t\t\\node[above]at(2,1.25){$?$};\n\t\t\t\\node[above]at(3,2.5){$45$};\n\t\t\t\\node[above]at(4,4){$?$};\n\t\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Số lượng máy tính bán được trong tháng $10$ là bao nhiêu máy?", "choices": ["$20$ máy", "$25$ máy", "$30$ máy", "$35$ máy"], "correctIndex": 1, "explain": "* Gọi $x$ là số máy tính bán được trong tháng $10$ ($x\\in\\mathbb{N}^*$).<br>* Số máy bán được trong tháng $12$ là $2x$.<br>* Tổng số máy bán được trong $4$ tháng là $150$, ta có phương trình:  $30+x+45+2x=150 \\Leftrightarrow 3x+75=150 \\Leftrightarrow 3x=75 \\Leftrightarrow x=25$.<br>Vậy số máy bán được trong tháng $10$ là $25$ máy."}, {"question": "Tỉ lệ phần trăm số máy tính bán được trong tháng $12$ so với tổng số máy tính của cả $4$ tháng là bao nhiêu?", "choices": ["$25\\%$", "$30\\%$", "$33{,}33\\%$", "$35\\%$"], "correctIndex": 2, "explain": "* Số máy bán được trong tháng $12$ là $2\\cdot25=50$ (máy).<br>* Tỉ lệ phần trăm là: $\\dfrac{50}{150}\\cdot100\\% \\approx 33{,}33\\%$."}, {"question": "Nếu mỗi máy tính bán ra cửa hàng thu lãi $1{,}2$ triệu đồng, thì tổng lợi nhuận của cửa hàng trong hai tháng cuối năm (tháng $11$ và tháng $12$) là bao nhiêu?", "choices": ["$108$ triệu đồng", "$114$ triệu đồng", "$120$ triệu đồng", "$132$ triệu đồng"], "correctIndex": 1, "explain": "* Tổng số máy bán được trong tháng $11$ và tháng $12$ là: $45+50=95$ (máy).<br>* Tổng lợi nhuận thu được là: $95\\cdot1{,}2=114$ (triệu đồng)."}]}, {"noiDungChung": "Một tập đoàn bán lẻ điện máy thực hiện khảo sát số lượng máy tính xách tay bán ra mỗi ngày tại các chi nhánh trong suốt   $60$ ngày.   Dữ liệu được tổng hợp vào bảng tần số ghép nhóm như sau:<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Số máy tính</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[0;10)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[10;20)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[20;30)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[30;40)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[40;50)$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Số ngày</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$8$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$15$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$20$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$12$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$5$</td></tr></table>", "cauHoi": [{"question": "Giá trị đại diện và tần số tích lũy của nhóm chứa mốt ($M_o$) lần lượt là", "choices": ["$c_3=25$, $cf_3=20$", "$c_3=25$, $cf_3=43$", "$c_3=25{,}5$, $cf_3=43$", "$c_3=20$, $cf_3=43$"], "correctIndex": 1, "explain": "Nhóm có tần số lớn nhất là $[20;30)$ với $n_3=20$. Do đó, đây là nhóm chứa mốt.<br>Giá trị đại diện của nhóm này là $c_3=\\dfrac{20+30}{2}=25$.<br>Tần số tích lũy của nhóm này là $cf_3=n_1+n_2+n_3=8+15+20=43$."}, {"question": "Để đánh giá độ ổn định của doanh số, quản lý cần xác định khoảng biến thiên và khoảng tứ phân vị của mẫu số liệu. Giá trị của tứ phân vị thứ ba $Q_3$ (làm tròn đến hàng phần trăm) là", "choices": ["$Q_3 \\approx 31{,}67$", "$Q_3 \\approx 30{,}83$", "$Q_3 \\approx 32{,}50$", "$Q_3 \\approx 35{,}00$"], "correctIndex": 0, "explain": "Cỡ mẫu $n=60$. Tứ phân vị thứ ba $Q_3$ là giá trị thứ $\\dfrac{3n}{4}=\\dfrac{3 \\cdot 60}{4}=45$.<br>Tần số tích lũy các nhóm: $cf_1=8$, $cf_2=23$, $cf_3=43$, $cf_4=55$. Vì $43 < 45 < 55$ nên $Q_3 \\in [30;40)$.<br>Ta có: $L=30$, $h=10$, $n_4=12$, $cf_3=43$.<br>Áp dụng công thức: $Q_3=L+\\dfrac{\\dfrac{3n}{4}-cf_3}{n_4} \\cdot h = 30+\\dfrac{45-43}{12} \\cdot 10 = 30+\\dfrac{20}{12} \\approx 31{,}67$."}, {"question": "Giả sử doanh thu mỗi máy tính là $15$ triệu đồng. Doanh nghiệp dự báo nếu doanh thu trung bình mỗi ngày vượt quá $350$ triệu đồng thì sẽ mở rộng kho bãi. Dựa vào số trung bình của mẫu số liệu ghép nhóm, tập đoàn có nên mở rộng kho bãi không?", "choices": ["Không, vì doanh thu trung bình chỉ đạt $252{,}5$ triệu đồng", "Có, vì doanh thu trung bình đạt $375$ triệu đồng", "Có, vì doanh thu trung bình đạt $352{,}5$ triệu đồng", "Không, vì doanh thu trung bình chỉ đạt $342{,}5$ triệu đồng"], "correctIndex": 2, "explain": "Giá trị đại diện các nhóm: $5$, $15$, $25$, $35$, $45$.<br>Số máy tính trung bình bán ra mỗi ngày: <br>$\\bar{x}=\\dfrac{8 \\cdot 5+15 \\cdot 15+20 \\cdot 25+12 \\cdot 35+5 \\cdot 45}{60}=\\dfrac{40+225+500+420+225}{60}=\\dfrac{1410}{60}=23{,}5$ (máy).<br>Doanh thu trung bình mỗi ngày: $\\bar{D}=23{,}5 \\cdot 15=352{,}5$ (triệu đồng)."}]}]}, {"id": "extra-6", "ten": "Đề luyện tập số 1", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Hàm số nào sau đây đồng biến trên tập xác định của nó?", "choices": ["$y=\\log _{0,5} x$", "$y=\\mathrm{e}^{-x}$", "$y=\\left(\\dfrac{1}{3}\\right)^x$", "$y=\\ln x$"], "correctIndex": 3, "explain": "Vì $y=\\ln x$ đồng biến trên tập xác định $(0,+\\infty)$ của nó vì đạo hàm của nó là $\\dfrac{1}{x^{\\prime}}$ là một hàm dương trên tập xác định của nó."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một nhóm thợ phải thực hiện kế hoạch sản xuất 3000 sản phẩm. Trong 8 ngày đầu họ thực hiện đúng mức đề ra, những ngày còn lại họ vượt mức mỗi ngày 10 sản phẩm nên đã hoàn thành sớm hơn dự định 2 ngày. Hỏi theo kế hoạch cần sản xuất mỗi ngày bao nhiêu sản phẩm?", "choices": ["100 sản phẩm", "200 sản phẩm", "300 sản phẩm", "400 sản phẩm"], "correctIndex": 0, "explain": "Gọi số sản phẩm theo kế hoạch mỗi ngày là $x \\in \\mathbb{N}^*$. Khi đó:<br>a) Theo kế hoạch: thời gian hoàn thành là $\\dfrac{3000}{x}$ (ngày).  <br>b) Thực tế: 8 ngày đầu làm đúng kế hoạch được $8x$ sản phẩm, còn lại $3000-8x$ sản phẩm.  <br>c) Những ngày sau làm vượt mức $10$ sản phẩm/ngày, tức mỗi ngày làm $x+10$ sản phẩm, nên thời gian cho phần còn lại là $\\dfrac{3000-8x}{x+10}$ (ngày).<br>Vì thực tế sớm hơn dự định $2$ ngày, ta có  \\[\n\t\t8+\\dfrac{3000-8x}{x+10} = \\dfrac{3000}{x}-2.\n\t\t\\]  Suy ra  \\[\n\t\t2x^2+100x-30000=0 \\ \\Leftrightarrow\\ x^2+50x-15000=0.\n\t\t\\]  Giải ra được $x=100$ hoặc $x=-150$ (loại). Vậy theo kế hoạch, mỗi ngày cần sản xuất $100$ sản phẩm."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Đặt $\\log _2 60=a$; $\\log _5 15=b$. Tính $P=\\log _2 12$ theo $a$ và $b$.", "choices": ["$P=\\dfrac{ab+2a+2}{b}$", "$P=\\dfrac{ab-a+2}{b}$", "$P=\\dfrac{ab+a-2}{b}$", "$P=\\dfrac{ab-a-2}{b}$"], "correctIndex": 1, "explain": "Ta có:  \\[\n\t\ta=\\log_2 60=\\log_2(2^2\\cdot 15)=2+\\log_2 15 \\implies \\log_2 15=a-2.\n\t\t\\]  Mặt khác:  \\[\n\t\t\\log_2 5=\\dfrac{\\log_2 15}{\\log_5 15}=\\dfrac{a-2}{b}.\n\t\t\\]  Với $b=\\log_5 15=1+\\log_5 3 \\implies \\log_5 3=b-1$.<br>Suy ra:  \\[\n\t\t\\log_2 3=\\log_2 5 \\cdot \\log_5 3=\\dfrac{a-2}{b}\\cdot(b-1)=\\dfrac{ab-a-2b+2}{b}.\n\t\t\\]  Do đó:  \\[\n\t\t\\log_2 12=\\log_2(2^2\\cdot 3)=2+\\log_2 3=2+\\dfrac{ab-a-2b+2}{b}=\\dfrac{ab-a+2}{b}.\n\t\t\\]  Vậy $P=\\dfrac{ab-a+2}{b}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biết rằng $\\lim\\limits_{x \\rightarrow +\\infty}\\left(\\dfrac{x^2+1}{x-2}+ax-b\\right)=-5$. Tính tổng $a+b$.", "choices": ["6", "7", "8", "5"], "correctIndex": 0, "explain": "Ta có:  \\[\n\t\t\\lim\\limits_{x \\to +\\infty}\\left(\\dfrac{x^2+1}{x-2}+ax-b\\right)\n\t\t= \\lim\\limits_{x \\to +\\infty}\\dfrac{(a+1)x^2-(2a+b)x+2b+1}{x-2}=-5.\n\t\t\\]  Để giới hạn hữu hạn, hệ số bậc hai phải triệt tiêu:  \\[\n\t\ta+1=0 \\implies a=-1.\n\t\t\\]  Khi đó hệ số bậc nhất thỏa:  \\[\n\t\t2a+b=5 \\implies 2(-1)+b=5 \\implies b=7.\n\t\t\\]  Vậy $a+b=6$."}]}, {"noiDungChung": "Bác Hai có một mảnh đất rộng 6 ha. Bác dự tính trồng cà chua và bắp cho mùa vụ sắp tới. Nếu trồng bắp thì bác Hai cần mười ngày để trồng một ha. Nếu trồng cà chua thì bác Hai cần hai mươi ngày để trồng một ha. Biết rằng mỗi ha bắp sau thu hoạch bán được 30 triệu đồng, mỗi ha cà chua sau thu hoạch bán được 50 triệu đồng và bác Hai chỉ còn 100 ngày để canh tác cho kịp mùa vụ.", "cauHoi": [{"question": "Miền nghiệm biểu diễn phần diện tích trồng bắp và cà chua của bác Hai là", "choices": ["Một tam giác", "Một tứ giác", "Một ngũ giác", "Một lục giác"], "correctIndex": 1, "explain": "Gọi diện tích bác Hai trồng bắp là $x$ ( $x \\geq 0$ ). Số ngày công trồng bắp là $10 x$<br>Gọi diện tích bác Hai trồng cà chua là $y (y \\geq 0)$. Số ngày công trồng cà chua là $20 y$<br>Số tiền bác Hai thu được khi canh tác 6 ha đất trong 100 ngày là $30 x+50 y$ ( triệu đồng)<br>Theo đề bài ta có hệ bất phương trình $\\left\\{\\begin{array}{l}x \\geq 0 \\\\ y \\geq 0 \\\\ x+y \\leq 6 \\\\ 10 x+20 y \\leq 100\\end{array} \\Leftrightarrow\\left\\{\\begin{array}{l}x \\geq 0(1) \\\\ y \\geq 0(2) \\\\ x+y-6 \\leq 0(3) \\\\ x+2 y-10 \\leq 0(4)\\end{array}\\right.\\right.$ <br>Ta vẽ các đường thẳng $\\left(d_1\\right): x=0,\\left(d_2\\right): y=0,\\left(d_3\\right): x+y-6=0,\\left(d_4\\right): x+2 y-10=0$ trên cùng hệ trục tọa độ.<br>Lấy điểm $M(1 ; 1)$ ta thấy $M(1 ; 1) \\in(1), M(1 ; 1) \\in(2), M(1 ; 1) \\in(3), M(1 ; 1) \\in(4)$. <br>Ta gạch bỏ các phần không chứa điểm $M(1 ; 1)$ của mặt phẳng có bờ là đường thẳng $\\left(d_1\\right),\\left(d_2\\right),\\left(d_3\\right),\\left(d_4\\right)$. <br>Ta được miền nghiệm của hệ bất phương trình là miền trong và viền của tứ giác $A B C D$"}, {"question": "Số tiền nhiều nhất mà bác Hai có thể thu được sau màu vụ này là bao nhiêu?", "choices": ["180 triệu", "250 triệu", "260 triệu", "270 triệu"], "correctIndex": 2, "explain": "$$  \\begin{aligned}  & \\left(d_1\\right) \\cap\\left(d_2\\right)=A(0 ; 0),\\left(d_1\\right) \\cap\\left(d_3\\right)=D(6 ; 0) <br>& \\left(d_2\\right) \\cap\\left(d_4\\right)=B(0 ; 5),\\left(d_3\\right) \\cap\\left(d_4\\right)=C(2 ; 4)  \\end{aligned}  $$<br>a) Với $A(0 ; 0)$ Số tiền bác Hai thu được là: $30.0+50.0=0$ triệu  <br>b) Với $B(0 ; 5)$ Số tiền bác Hai thu được là: $30.0+50.5=250$ triệu  <br>c) Với $C(2 ; 4)$ Số tiền bác Hai thu được là: $30.2+50.4=260$ triệu  <br>d) Với $D(6 ; 0)$ Số tiền bác Hai thu được là: $30.6+50.0=180$ triệu"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biết $F(x)$ là một nguyên hàm của hàm số $e^{2x}$ và $F(0)=\\dfrac{201}{2}$. Giá trị $F\\!\\left(\\dfrac{1}{2}\\right)$ bằng", "choices": ["$\\dfrac{1}{2}e+200$", "$2e+100$", "$\\dfrac{1}{2}e+50$", "$\\dfrac{1}{2}e+100$"], "correctIndex": 3, "explain": "Ta có:  \\[\n\t\t\\int e^{2x}\\,dx = \\dfrac{1}{2}e^{2x}+C.\n\t\t\\]  Theo đề bài:  \\[\n\t\tF(0)=\\dfrac{201}{2} \\implies \\dfrac{1}{2}e^0+C=\\dfrac{201}{2} \\implies C=100.\n\t\t\\]  Vậy:  \\[\n\t\tF(x)=\\dfrac{1}{2}e^{2x}+100.\n\t\t\\]  Do đó:  \\[\n\t\tF\\!\\left(\\dfrac{1}{2}\\right)=\\dfrac{1}{2}e^{2\\cdot \\dfrac{1}{2}}+100=\\dfrac{1}{2}e+100.\n\t\t\\]  Kết quả đúng là $\\dfrac{1}{2}e+100$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tỉ số giữa số nữ và số nam của một lớp học là $1 \\dfrac{2}{3}$. Biết số nữ hơn số nam là 8. Hỏi lớp đó có bao nhiêu nữ, bao nhiêu nam?", "choices": ["Nữ: 18 ; Nam: 10", "Nữ: 20 ; Nam: 12", "Nữ: 22 ; Nam: 14", "Nữ: 23 ; Nam: 15"], "correctIndex": 1, "explain": "Ta có tỉ số số nữ và số nam là $1 \\dfrac{2}{3} = \\dfrac{5}{3}$.<br>Gọi số nam là $x$, số nữ là $\\dfrac{5}{3}x$. Theo đề bài:<br>\\[\n\t\t\\dfrac{5}{3}x - x = 8 \\implies \\dfrac{2}{3}x = 8 \\implies x = 12.\n\t\t\\]<br>Suy ra số nữ là $\\dfrac{5}{3}\\cdot 12 = 20$.<br>Vậy lớp có 20 nữ và 12 nam."}]}, {"noiDungChung": "Giá của một chiếc xe ô tô lúc mới mua là 680 triệu đồng. Cứ sau mỗi năm sử dụng, giá của chiếc xe ô tô giảm 50 triệu đồng. Gọi $u_n$ (triệu đồng) là giá của chiếc ô tô trong năm thứ $n$ sử dụng.", "cauHoi": [{"question": "Giá của chiếc ô tô trong năm thứ 2 sử dụng là", "choices": ["630", "420", "530", "500"], "correctIndex": 0, "explain": "Ta có $u_n=680-50(n-1)$.<br>Khi $n=2$: $u_2=680-50(1)=630$ (triệu đồng)."}, {"question": "Giá của chiếc ô tô sau bao nhiêu năm sử dụng sẽ nhỏ hơn 500 triệu đồng?", "choices": ["3", "4", "5", "6"], "correctIndex": 2, "explain": "Điều kiện: $u_n<500 \\Rightarrow 680-50(n-1)<500 \\Rightarrow 180<50(n-1)\\Rightarrow n-1>3{,}6\\Rightarrow n>4{,}6$.<br>Vậy $n=5$ là số năm nhỏ nhất để giá xe $<500$ triệu đồng."}, {"question": "Biết $\\lim\\limits_{n\\to\\infty}\\dfrac{u_n+4}{an+\\sqrt{2}}=-\\dfrac{50}{3}$. Tính $a^2$.", "choices": ["5", "6", "3", "9"], "correctIndex": 3, "explain": "Ta có $u_n=680-50(n-1)=-50n+730$. <br>Xét giới hạn:  \\[\n\t\t\t\\lim\\limits_{n\\to\\infty}\\dfrac{u_n+4}{an+\\dots}=\\lim\\limits_{n\\to\\infty}\\dfrac{-50n+734}{an+\\dots}\\sim \\dfrac{-50n}{an}=-\\dfrac{50}{a}.\n\t\t\t\\]  Theo đề bài, $-\\dfrac{50}{a}=-\\dfrac{50}{3}\\Rightarrow a=3\\Rightarrow a^2=9$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho cấp số nhân có các số hạng lần lượt là $\\dfrac{1}{4}; \\dfrac{1}{2}; 1; \\cdots; 2048$. Tính tổng $S$ của tất cả các số hạng của cấp số nhân đã cho.", "choices": ["$S=2047{,}75$", "$S=2049{,}75$", "$S=4095{,}75$", "$S=4096{,}75$"], "correctIndex": 2, "explain": "Ta có công bội $q=\\dfrac{\\dfrac{1}{2}}{\\dfrac{1}{4}}=2$ và số hạng tổng quát $u_n=u_1q^{n-1}=\\dfrac{1}{4}\\cdot 2^{\\,n-1}=2^{\\,n-3}$.<br>Vì số hạng cuối là $2048=2^{11}$ nên $2^{\\,n-3}=2^{11}\\Rightarrow n-3=11\\Rightarrow n=14$.<br>Tổng $S$ của $n$ số hạng đầu là<br>\\[\n\t\tS_n=u_1\\cdot\\dfrac{1-q^n}{1-q}=\\dfrac{1}{4}\\cdot\\dfrac{1-2^{14}}{1-2}\n\t\t=\\dfrac{1}{4}\\cdot(2^{14}-1)=\\dfrac{16383}{4}=4095{,}75.\n\t\t\\]<br>Vậy $S=4095{,}75$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Số đường tiệm cận đứng của đồ thị hàm số $y=\\dfrac{(x^2-3x+2)\\sin x}{x^3-4x}$ là", "choices": ["1", "2", "3", "4"], "correctIndex": 0, "explain": "TXĐ: $D=\\mathbb{R}\\setminus\\{ -2,\\,0,\\,2\\}$.<br>Vì $x^2-3x+2=(x-1)(x-2)$ và $x^3-4x=x(x-2)(x+2)$, nên với $x\\neq 2$ ta có<br>\\[\n\t\ty=\\dfrac{(x-1)(x-2)\\sin x}{x(x-2)(x+2)}=\\dfrac{(x-1)\\sin x}{x(x+2)}.\n\t\t\\]<br>- Tại $x=-2$: $\\sin(-2)\\neq 0$ và $(x-1)$ hữu hạn, trong khi $x(x+2)\\to 0$, do đó  \\[\n\t\t\\lim\\limits_{x\\to -2} y=\\pm\\infty \\Rightarrow x=-2 \\text{ là tiệm cận đứng}.\n\t\t\\]  - Tại $x=0$:<br>\\[\n\t\t\\lim\\limits_{x\\to 0} y=\\lim\\limits_{x\\to 0}\\dfrac{x-1}{x+2}\\cdot\\dfrac{\\sin x}{x}=-\\dfrac{1}{2}\\cdot 1=-\\dfrac{1}{2},\n\t\t\\]<br>nên không có tiệm cận đứng tại $x=0$.<br>- Tại $x=2$: từ biểu thức rút gọn,  \\[\n\t\t\\lim\\limits_{x\\to 2} y=\\dfrac{(2-1)\\sin 2}{2(2+2)}=\\dfrac{\\sin 2}{8},\n\t\t\\]<br>hữu hạn, nên $x=2$ không là tiệm cận đứng (chỉ là điểm gián đoạn có thể khử).<br>Vậy đồ thị có đúng một tiệm cận đứng là $x=-2$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một xe ô tô chở khách du lịch có sức chứa tối đa là 16 hành khách. Trong một khu du lịch, một đoàn khách gồm 22 người đang đi bộ và muốn thuê xe về khách sạn. Lái xe đưa ra thỏa thuận: nếu một chuyến xe chở $x$ người thì giá tiền cho mỗi người là $\\dfrac{(40-x)^2}{2}$ (nghìn đồng). Với thỏa thuận như trên, lái xe có thể thu được nhiều nhất bao nhiêu triệu đồng từ một chuyến chở khách (làm tròn đến hàng phần trăm)?", "choices": ["4,65", "4,73", "4,74", "4,56"], "correctIndex": 2, "explain": "Gọi $f(x)$ là tổng tiền (nghìn đồng) thu được khi chở $x$ người, với $1\\le x\\le 16$ (do sức chứa tối đa). Khi đó  \\[\n\t\tf(x)=\\dfrac{1}{2}x(40-x)^2.\n\t\t\\]  Xét $f'(x)=\\dfrac{1}{2}(40-x)(40-3x)$. Nghiệm nội suy $f'(x)=0$ cho $x=\\dfrac{40}{3}\\approx 13{,}33$. Vì $x$ nguyên, so sánh tại $x=13$ và $x=14$:  \\[\n\t\tf(13)=\\dfrac{1}{2}\\cdot 13\\cdot 27^2=4738{,}5\\ \\text{(nghìn)}=4{,}7385\\ \\text{(triệu)},\n\t\t\\]  \\[\n\t\tf(14)=\\dfrac{1}{2}\\cdot 14\\cdot 26^2=4732\\ \\text{(nghìn)}=4{,}732\\ \\text{(triệu)}.\n\t\t\\]  Kiểm tra biên $x=16$: $f(16)=4608$ (nghìn) $=4{,}608$ (triệu), nhỏ hơn. Do đó giá trị lớn nhất đạt tại $x=13$, làm tròn đến hàng phần trăm là $4{,}74$ triệu đồng."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Gọi $X$ là tập các số tự nhiên gồm 9 chữ số đôi một khác nhau. Chọn ngẫu nhiên một số từ $X$, tính xác suất để chọn được một số có mặt bốn chữ số lẻ và chữ số $0$ luôn đứng giữa hai chữ số lẻ.", "choices": ["$\\dfrac{5}{54}$", "$\\dfrac{1}{7776}$", "$\\dfrac{45}{54}$", "$\\dfrac{49}{54}$"], "correctIndex": 0, "explain": "Số phần tử không gian mẫu: chọn 9 chữ số khác nhau với chữ số đầu không bằng $0$, ta có<br>\\[\n\t\tn(\\Omega)=9\\cdot 9\\cdot 8\\cdot 7\\cdot 6\\cdot 5\\cdot 4\\cdot 3\\cdot 2=3\\,265\\,920.\n\t\t\\]<br>Gọi biến cố $A$ : \"chọn được một số có mặt bốn chữ số lẻ và chữ số 0 luôn đứng giữa hai chữ số lé\"  - Chọn và sắp xếp 2 chữ số lẻ để đặt chữ số 0 vào giữa 2 chữ số đó, có: $A_5^2$ (cách)<br>Coi bộ 2 chữ số lẻ đó và chữ số 0 là 1 bộ (3chữ số)  - Chọn 2 chữ số lẻ khác và 4 chữ số chẵn khác 0 , có: $C_3^2 \\cdot 1$ (cách)<br>Hoán vị 1 bộ ( 3 chữ số trên) và 6 chữ số vừa được chọn, có: 7 ! (cách)<br>$$  n(A)=A_5^2 \\cdot c_7^2 \\cdot 7!\\Rightarrow P(A)=\\dfrac{n(A)}{n(\\Omega)}=\\dfrac{A_5^2 \\cdot c_7^2 \\cdot 7!}{648.7!}=\\dfrac{5}{54}  $$  Vậy đáp án đúng là $\\dfrac{5}{54}$."}]}, {"noiDungChung": "Trong mặt phẳng tọa độ $O x y$, cho hình bình hành $A B C D$ có $A(3 ; 4), C(8 ; 1)$. Gọi $M$ là trung điểm của cạnh $B C, N$ là giao điểm của $B D$ và $A M$, biết $N\\left(\\dfrac{13}{3} ; 2\\right)$.", "cauHoi": [{"question": "Tính hoành độ của điểm $B$.", "choices": ["$\\dfrac{11}{2}$", "$\\dfrac{5}{2}$", "$2$", "$1$"], "correctIndex": 2, "explain": "Do $I$ là tâm của hình bình hành $ABCD$, ta có $I$ là trung điểm của đoạn thẳng $AC$ nên $I\\!\\left(\\dfrac{11}{2};\\dfrac{5}{2}\\right)$.<br>Xét tam giác $ABC$ thì $BI, AM$ là hai đường trung tuyến nên $N$ là trọng tâm tam giác $ABC$. Do đó<br>$\\left\\{\\begin{array}{l}\\dfrac{13}{3}=\\dfrac{3+x_B+8}{3} \\\\ 2=\\dfrac{4+y_B+1}{3}\\end{array} \\Leftrightarrow\\left\\{\\begin{array}{l}x_B=2 \\\\ y_B=1\\end{array}\\right.\\right.$<br>Vậy $B(2;1)$."}, {"question": "Tính diện tích hình bình hành $ABCD$.", "choices": ["$18$", "$3$", "$12$", "$36$"], "correctIndex": 0, "explain": "Gọi $D(x_D;y_D)$. Do $I$ trung điểm của $BD$ nên  \\[\n\t\t\t\\begin{cases}\n\t\t\t\t2+x_D=11\\\\\n\t\t\t\t1+y_D=5\n\t\t\t\\end{cases}\n\t\t\t\\Rightarrow\n\t\t\t\\begin{cases}\n\t\t\t\tx_D=9\\\\\n\t\t\t\ty_D=4\n\t\t\t\\end{cases}\n\t\t\t\\Rightarrow D(9;4).\n\t\t\t\\]  Ta đã có $A(3;4),\\ B(2;1),\\ D(9;4)$. Khi đó  \\[\n\t\t\t\\vec{AB}=(-1;-3),\\quad \\vec{AD}=(6;0).\n\t\t\t\\]  Diện tích hình bình hành là độ lớn tích có hướng:  \\[\n\t\t\tS=\\left|\\left[\\vec{AB}, \\vec{AD}\\right]\\right|=\\big|(-1)\\cdot 0-(-3)\\cdot 6\\big|=18.\n\t\t\t\\]"}]}, {"noiDungChung": "Cho $\\triangle A B C$ có $A(4 ;-2)$. Đường cao $B H: 2 x+y-4=0$ và đường cao $C K: x-y-3=0$.", "cauHoi": [{"question": "Tung độ trực tâm của tam giác $ABC$ là", "choices": ["$\\dfrac{7}{3}$", "$-\\dfrac{2}{3}$", "$-\\dfrac{5}{3}$", "$\\dfrac{4}{3}$"], "correctIndex": 1, "explain": "Gọi $H_1$ là trực tâm của $\\triangle ABC$. Khi đó tọa độ $H_1$ thỏa mãn hệ:<br>\\[\n\t\t\t\\begin{cases}\n\t\t\t\t2x+y-4=0,\\\\\n\t\t\t\tx-y-3=0.\n\t\t\t\\end{cases}\n\t\t\t\\]<br>Giải hệ ta được $x=\\dfrac{7}{3},\\ y=-\\dfrac{2}{3}$. Vậy tung độ trực tâm là $-\\dfrac{2}{3}$."}, {"question": "Viết phương trình đường cao kẻ từ đỉnh $A$.", "choices": ["$4x+5y-6=0$", "$x-y+3=0$", "$4x+5y+6=0$", "$x-2y-4=0$"], "correctIndex": 0, "explain": "Gọi $AI$ là đường cao từ $A(4;-2)$. Đường này đi qua trực tâm $H_1\\!\\left(\\dfrac{7}{3};-\\dfrac{2}{3}\\right)$ và có VTPT $\\vec{n}=(4;5)$.<br>Phương trình:<br>\\[\n\t\t\t4\\left(x-\\dfrac{7}{3}\\right)+5\\left(y+\\dfrac{2}{3}\\right)=0 \\ \\Leftrightarrow\\ 4x+5y-6=0.\n\t\t\t\\]"}]}, {"noiDungChung": "Cho hàm số $f(x)=\\heva{&\\dfrac{3-\\sqrt{4-x}}{4}, & \\text{ khi } x \\neq 0 \\\\ &\\dfrac{1}{4}, & \\text{ khi }x=0.}$", "cauHoi": [{"question": "Khẳng định nào sau đây là đúng?", "choices": ["Hàm số liên tục tại $x=0$", "Hàm số có tập xác định là $\\mathbb{R}$", "Hàm số gián đoạn tại $x=0$", "Không tồn tại $\\lim\\limits_{x \\to 0} f(x)$"], "correctIndex": 0, "explain": "Với $x\\ne 0$, $f(x)=\\dfrac{3-\\sqrt{4-x}}{4}$ xác định khi $4-x\\ge 0\\Rightarrow x\\le 4$, nên tập xác định là $(-\\infty,4]$, không phải $\\mathbb{R}$.<br>Tính giới hạn tại $x=0$:  \\[\n\t\t\t\\lim\\limits_{x\\to 0} f(x)=\\lim\\limits_{x\\to 0}\\dfrac{3-\\sqrt{4-x}}{4}=\\dfrac{3-\\sqrt{4}}{4}=\\dfrac{1}{4}=f(0),\n\t\t\t\\]  nên hàm số liên tục tại $x=0$."}, {"question": "Hỏi $f'(0)$ là kết quả nào sau đây?", "choices": ["$\\dfrac{1}{4}$", "$\\dfrac{1}{16}$", "$\\dfrac{1}{32}$", "Không tồn tại"], "correctIndex": 1, "explain": "Với $x<4$, đặt $g(x)=\\dfrac{3-\\sqrt{4-x}}{4}$, ta có<br>\\[\n\t\t\tg'(x)=-\\dfrac{1}{4}\\cdot \\dfrac{d}{dx}\\sqrt{4-x}\n\t\t\t=-\\dfrac{1}{4}\\cdot\\Big(-\\dfrac{1}{2\\sqrt{4-x}}\\Big)=\\dfrac{1}{8\\sqrt{4-x}}.\n\t\t\t\\]<br>Do đó<br>\\[\n\t\t\tf'(0)=g'(0)=\\dfrac{1}{8\\sqrt{4}}=\\dfrac{1}{16}.\n\t\t\t\\]"}]}, {"noiDungChung": "Cho hình hộp chữ nhật $A B C D \\cdot A^{\\prime} B^{\\prime} C^{\\prime} D^{\\prime}$ có $A B=a, B C=a \\sqrt{2}, A A^{\\prime}=a \\sqrt{3}$.", "cauHoi": [{"question": "Thể tích khối hộp là", "choices": ["$\\sqrt{3}$", "$\\sqrt{5}$", "$\\sqrt{6}$", "$\\dfrac{\\sqrt{6}}{3}$"], "correctIndex": 2, "explain": "Thể tích khối hộp chữ nhật bằng tích ba cạnh đôi một vuông góc:<br>\\[\n\t\t\tV=AB\\cdot BC\\cdot AA'=a\\cdot a\\sqrt{2}\\cdot a\\sqrt{3}=a^3\\sqrt{6}.\n\t\t\t\\]<br>Với $a=1$ theo đơn vị chuẩn, ta được $V=\\sqrt{6}$."}, {"question": "Gọi $\\alpha$ là góc giữa hai mặt phẳng $(ACD')$ và $(ABCD)$. Giá trị $\\tan\\alpha$ bằng", "choices": ["$\\dfrac{2\\sqrt{6}}{3}$", "$\\dfrac{\\sqrt{2}}{3}$", "$2$", "$\\dfrac{3\\sqrt{2}}{2}$"], "correctIndex": 3, "explain": "Kẻ $DO\\perp AC$. Vì $AC\\perp DD'$ nên $AC\\perp D'O$, do đó góc giữa hai mặt phẳng $(ACD')$ và $(ABCD)$ là $\\angle D'OD=\\alpha$.<br>Xét tam giác $ACD$ vuông tại $D$, có đường cao $DO$, ta có<br>\\[\n\t\t\t\\dfrac{1}{DO^2}=\\dfrac{1}{AD^2}+\\dfrac{1}{CD^2}=\\dfrac{1}{(a\\sqrt{2})^2}+\\dfrac{1}{(a)^2}=\\dfrac{1}{2a^2}+\\dfrac{1}{a^2}=\\dfrac{3}{2a^2}\n\t\t\t\\]<br>suy ra $DO=\\dfrac{a\\sqrt{6}}{3}$.<br>Trong tam giác $D'DO$ vuông tại $D$,   \\[\n\t\t\t\\tan\\alpha=\\dfrac{DD'}{DO}=\\dfrac{a\\sqrt{3}}{\\dfrac{a\\sqrt{6}}{3}}=\\dfrac{3\\sqrt{2}}{2}.\n\t\t\t\\]"}]}, {"noiDungChung": "Trong không gian với hệ tọa độ $O x y z$, cho hai điểm $A(1 ; 2 ;-3), B(-2 ;-2 ; 1)$ và mặt phẳng ($\\alpha$): $2 x+2 y-z+9=0$.", "cauHoi": [{"question": "Gọi $K(a;b;c)$ là giao điểm của đường thẳng $AB$ và mặt phẳng $(\\alpha)$. Tính $a\\cdot b\\cdot c$", "choices": ["4", "$-4$", "$3$", "$-2$"], "correctIndex": 0, "explain": "Đường thẳng $AB$ đi qua hai điểm $A(1,2,-3)$ và $B(-2,-2,1)$. Phương trình tham số của đường thẳng $AB$ có dạng: $x=1-3t,\\ y=2-4t,\\ z=-3+4t$. <br>Khi đó, tọa độ điểm $K$ là $K(1-3t,\\,2-4t,\\,-3+4t)$. <br>Mặt phẳng $(\\alpha)$ có phương trình: $2x+2y-z+9=0$. <br>Thay các giá trị của $x,y,z$ từ phương trình tham số vào phương trình mặt phẳng:  \\[\n\t\t\t2(1-3t)+2(2-4t)-(-3+4t)+9=0 \\ \\Rightarrow\\ t=1 \\ \\Rightarrow\\ K(-2,-2,1).\n\t\t\t\\]  Vậy $a\\cdot b\\cdot c=4.\n\t\t$"}, {"question": "Viết phương trình đường thẳng hình chiếu của đường thẳng $AB$ trên $(\\alpha)$.", "choices": ["$\\left\\{\\begin{array}{l}x=-2-t \\\\ y=-2+2 t \\\\ z=1+2 t\\end{array}\\right.$", "$\\left\\{\\begin{array}{l}x=-2+2 t \\\\ y=-2-t \\\\ z=1+2 t\\end{array}\\right.$", "$\\left\\{\\begin{array}{l}x=-2+t \\\\ y=-2 \\\\ z=1+2 t\\end{array}\\right.$", "$\\left\\{\\begin{array}{l}x=-2+t \\\\ y=-2-t \\\\ z=1\\end{array}\\right.$"], "correctIndex": 2, "explain": "Ta có $B\\in(\\alpha)$ và gọi $H$ là hình chiếu của điểm $A$ lên mặt phẳng $(\\alpha)$. Khi đó, tọa độ điểm $H$ là nghiệm của hệ  $$  \\left\\{\\begin{array}{l}  2 x+2 y-z+9=0 <br>\\dfrac{x-1}{2}=\\dfrac{y-2}{2}=\\dfrac{z+3}{-1}  \\end{array}\\right.  $$  Vậy $H(-3,-2,-1)$. <br>Ta có $HB$ là hình chiếu của $AB$ trên $(\\alpha)$. Phương trình đường thẳng $HB$ là  $\\left\\{\\begin{array}{l}x=-2+t \\\\ y=-2 \\\\ z=1+2 t.\\end{array}\\right.$"}]}, {"noiDungChung": "Cho hàm số $y=f(x)=x^3+2 m x^2+3(m-1) x+5$ và đường thẳng $\\mathrm{d}: y=-x+5$.", "cauHoi": [{"question": "Khi $m=5$, điểm cực đại của đồ thị hàm số là", "choices": ["$-6$", "$(-6;77)$", "$(-0{,}67;1{,}15)$", "$-0{,}67$"], "correctIndex": 1, "explain": "Giả sử $f(x)=x^3+2mx^2+3(m-1)x+5$. Khi $m=5$, ta có $f(x)=x^3+10x^2+12x+5$.<br>$f'(x)=3x^2+20x+12$ có nghiệm $x=\\dfrac{-20\\pm\\sqrt{400-144}}{6}=\\dfrac{-20\\pm 16}{6}\\Rightarrow x=-6,\\ x=-\\dfrac{2}{3}$.<br>$f”(x)=6x+20$. Tại $x=-6$, $f”(-6)=-16<0$ nên đó là cực đại. Giá trị $f(-6)=-216+360-72+5=77$.<br>Vậy điểm cực đại là $(-6,77)$."}, {"question": "Tìm tất cả các giá trị thực của tham số $m$ để đường thẳng $d$ cắt đồ thị hàm số tại ba điểm phân biệt.", "choices": ["$\\hoac{&m<1 \\\\&m>2}$", "$\\hoac{&\\begin{cases}m\\ne \\dfrac{2}{3}\\\\ m\\leq1\\end{cases} \\\\&m\\geq2}$", "$\\hoac{&\\begin{cases}m\\ne \\dfrac{2}{3}\\\\ m<1\\end{cases} \\\\&m>2}$", "$\\hoac{&m\\leq1 \\\\&m\\geq2}$"], "correctIndex": 2, "explain": "Phương trình hoành độ giao điểm:  \\[\n\t\t\tx^3+2mx^2+3(m-1)x+5=-x+5\\ \\Leftrightarrow\\ x^3+2mx^2+(3m-2)x=0.\n\t\t\t\\]  Suy ra có một nghiệm $x=0$ và phương trình bậc hai <br>\\[\n\t\t\t(1)\\quad x^2+2mx+3m-2=0.\n\t\t\t\\]  Để có ba giao điểm phân biệt, (1) phải có hai nghiệm phân biệt khác $0$: <br>\\[\n\t\t\t\\begin{cases}\n\t\t\t\t3m-2\\ne 0 \\ (\\text{tránh nghiệm }x=0),\\\\\n\t\t\t\t\\Delta'=m^2-3m+2>0.\n\t\t\t\\end{cases}\n\t\t\t\\]  Tương đương  \\[\n\t\t\t\\begin{cases}\n\t\t\t\tm\\ne \\dfrac{2}{3},\\\\\n\t\t\t\tm<1\\ \\text{hoặc}\\ m>2.\n\t\t\t\\end{cases}\n\t\t\t\\]"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một nhóm $5$ học sinh nam và $4$ học sinh nữ tham gia lao động trên sân trường. Cô giáo chọn ngẫu nhiên đồng thời $2$ bạn trong nhóm đi tưới cây. Tính xác suất để hai bạn được chọn có cùng giới tính, biết rằng có ít nhất $1$ bạn nam được chọn.", "choices": ["$\\dfrac{1}{3}$", "$\\dfrac{2}{3}$", "$\\dfrac{3}{4}$", "$\\dfrac{1}{4}$"], "correctIndex": 0, "explain": "Số phần tử của không gian mẫu là $n(\\Omega)=C^2_9=36$.<br>Gọi A là biến cố \\lq\\lq Hai bạn được chọn có cùng giới tính\\rq\\rq.<br>B là biến cố \\lq\\lq Có ít nhất một bạn nam được chọn\\rq\\rq.<br>Ta có $n(B)=C^2_5+C^1_5 C^1_4=30$ suy ra $P(B)=\\dfrac{30}{36}$.<br>Ta có $n(AB)=C^2_5=10$ suy ra $P(AB)=\\dfrac{10}{36}$.<br>Vậy $P(A|B)=\\dfrac{P(AB)}{P(B)}=\\dfrac{10}{30}=\\dfrac{1}{3}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Xuất phát từ nhà, Mai đi 8 m về phía Tây rồi rẽ phải đi 15 m. Sau đó, Mai đi 20 m về phía Đông, đi thêm 20 m về phía Nam để đến nhà Đào. Nhà Đào cách nhà Mai bao xa và theo hướng nào?", "choices": ["13 m, hướng Đông Nam", "13 m, hướng Nam", "12 m, hướng Đông", "12 m, hướng Tây Bắc"], "correctIndex": 0, "explain": "Nhà bạn Mai tại điểm A .  Bạn Mai đi từ $\\mathrm{A} \\rightarrow \\mathrm{B} \\rightarrow \\mathrm{C} \\rightarrow \\mathrm{D} \\rightarrow \\mathrm{F}$.  Nhà bạn Đào nằm tại điếm F .  Từ hình vẽ suy ra Nhà bạn Đào nằm ở hướng Đông Nam so với nhà bạn Mai và nhà Đào cách nhà Mai chính bằng độ dài $A F$. Từ A ta kẻ $\\mathrm{AE} \\perp \\mathrm{DF}$ tại điểm E  Do đó, tứ giác EBCD là hình chữ nhật.  $$  \\Rightarrow\\left\\{\\begin{array}{l}  C D=B E=20(\\mathrm{ m}) <br>B C=E D=15(\\mathrm{ m})  \\end{array}\\right. \\text {. }  $$  Ta có: $\\left\\{\\begin{array}{l}\\mathrm{AE}=\\mathrm{BE}-\\mathrm{AB}=20-8=12(\\mathrm{~m}) \\\\ \\mathrm{EF}=\\mathrm{FD}-\\mathrm{ED}=20-15=5(\\mathrm{~m})\\end{array}\\right.$.<br>$\\Rightarrow \\mathrm{AF}=\\sqrt{\\mathrm{AE}^2+\\mathrm{EF}^2}=\\sqrt{12^2+5^2}=13(\\mathrm{~m})$. <br>Vậy nhà bạn Đào cách nhà bạn Mai $13(\\mathrm{~m})$ và nằm ở hướng Đông Nam.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, line join=round, line cap=round, >=stealth]\n\t\t\t\t\\path \n\t\t\t\t(0,0) coordinate (A)\n\t\t\t\t(-2,0) coordinate (B)  (-1,0) coordinate (B') \n\t\t\t\t($(B)+(0,3.75)$) coordinate (C)\n\t\t\t\t($(C)+(5,0)$) coordinate (D) ($(D)+(.75,0)$) coordinate (D')\n\t\t\t\t($(D)+(0,-5)$) coordinate (F) ($(F)+(.75,0)$) coordinate (F')\n\t\t\t\t($(A)+(0,3.75)$) coordinate (M)\n\t\t\t\t($(A)-(M)+(D)$) coordinate (E)\n\t\t\t\t; \n\t\t\t\t\\draw (B)--(A) node[below,pos=.5]{$8$} \n\t\t\t\t(B)--(C) node[left,pos=.5]{$15$}\n\t\t\t\t(D)--(C) node[above,pos=.5]{$20$}\n\t\t\t\t(D)--(F) \n\t\t\t\t; \n\t\t\t\t\\draw[|<->|] (D')--(F') node[left,pos=.5]{$20$};\n\t\t\t\t\\draw[dashed] (A)--(F) (A)--(M) (A)--(E);\n\t\t\t\t\\draw[->,line width=2pt] (A)--(B');\n\t\t\t\t\\foreach \\p/\\r in {B/-135,A/-90,C/90,D/90,F/0,E/0}\n\t\t\t\t\\fill (\\p) circle (1pt) node[shift={(\\r:3mm)}]{$\\p$};\n\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tập xác định $\\mathscr{D}$ của hàm số $y=(x^2-3x-4)^{-3}$ là", "choices": ["$\\mathscr{D}=(-1;4)$", "$\\mathscr{D}=(-\\infty;1)\\cup (4;+\\infty)$", "$\\mathscr{D}=[-1;4]$", "$\\mathscr{D}=\\mathbb{R}\\setminus\\{-1 ; 4\\}$"], "correctIndex": 3, "explain": "Hàm số xác định khi và chỉ khi $x^2-3x-4 \\ne 0\\Leftrightarrow \\heva{&x\\neq -1\\\\&x\\neq 4.}$<br>Vậy tập xác định của hàm số đã cho là $\\mathscr{D}=\\mathbb{R}\\setminus\\{-1 ; 4\\}$."}]}, {"noiDungChung": "Lớp 12A1 chuẩn bị hai tiết mục hát $P$ và $S$; hai tiết mục nhảy $T$ và $W$. Lớp 12A2 chuẩn bị hai tiết mục hát $R$ và $V$ và tiết mục nhảy $Q$ và $U$. Mỗi một tiết mục biểu diễn đúng một lần trong buổi tối đó. Các tiết mục có thể biểu diễn theo một thứ tự bất kỳ, thoả mãn các yêu cầu sau:<br>(1) Các tiết mục hát và nhảy phải diễn xen kẽ nhau trong suốt buổi biểu diễn.<br>(2) Tiêt mục đâu tiên là của lớp 12A2 và tiêt mục thứ hai là của lớp 12A1.<br>(3) Tiết mục cuôi cùng phải là một tiết mục hát của lớp 12A1.", "cauHoi": [{"question": "Nếu tiết mục $U$ ở vị trí thứ bảy, tiết mục nào dưới đây phải biểu diễn đầu tiên?", "choices": ["Q", "R", "S", "T"], "correctIndex": 0, "explain": "Theo (1) và (3), các vị trí lẻ là nhảy, chẵn là hát; vị trí 1 là tiết mục của 12A2 theo (2). Nhảy của 12A2 có $Q, U$; $U$ đã ở vị trí 7 nên vị trí 1 buộc phải là $Q$."}, {"question": "Tiết mục nào sau đây có thể biểu diễn đầu tiên?", "choices": ["$P$", "$R$", "$U$", "$V$"], "correctIndex": 2, "explain": "Vị trí đầu tiên là của 12A2 (theo (2)) và là nhảy (theo (1), (3)). Nhảy của 12A2 là $Q$ hoặc $U$. Trong các lựa chọn chỉ có $U$ phù hợp."}, {"question": "Nếu $Q$ ở vị trí thứ ba, $V$ ở vị trí thứ tư và $W$ ở vị trí thứ năm thì tiết mục nào dưới đây phải biểu diễn ở vị trí thứ sáu?", "choices": ["$P$", "$R$", "$S$", "$T$"], "correctIndex": 1, "explain": "Các vị trí chẵn là hát; vị trí 8 là hát của 12A1 nên $P, S$ chiếm vị trí 2 và 8. $V$ đã ở vị trí 4, nên vị trí 6 còn lại phải là hát của 12A2, tức $R$."}, {"question": "Nếu $T$ ở vị trí thứ ba thì $W$ phải ở vị trí", "choices": ["thứ nhất hoặc thứ năm", "thứ hai hoặc thứ năm", "thứ tư hoặc thứ bảy", "thứ năm hoặc thứ bảy"], "correctIndex": 3, "explain": "Các vị trí lẻ là nhảy; vị trí 1 là tiết mục của 12A2 nên $W$ (nhảy của 12A1) không thể ở vị trí 1. Với $T$ ở vị trí 3, $W$ chỉ có thể ở vị trí 5 hoặc 7."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho mệnh đề sai: “Nếu chuồn chuồn bay thấp thì trời mưa”. Cho các mệnh đề sau:<br>a) Nếu chuồn chuồn không bay thấp thì trời mưa.  <br>b) Nếu chuồn chuồn không bay thấp thì trời không mưa.  <br>c) Nếu trời mưa thì chuồn chuồn bay thấp.<br>Đáp án nào dưới đây đúng?", "choices": ["Cả 3 mệnh đề đều sai", "Cả 3 mệnh đề đều đúng", "2 mệnh đề đúng và 1 mệnh đề sai", "1 mệnh đề đúng và 2 mệnh đề sai"], "correctIndex": 1, "explain": "Kí hiệu $p$: “chuồn chuồn bay thấp”, $q$: “trời mưa”. Mệnh đề $p\\to q$ sai $\\Rightarrow p$ đúng và $q$ sai.<br>Khi đó:<br>a) $\\neg p\\to q$: tiền đề sai $\\Rightarrow$ mệnh đề đúng.  <br>b) $\\neg p\\to \\neg q$: tiền đề sai $\\Rightarrow$ mệnh đề đúng.  <br>c) $q\\to p$: tiền đề sai $\\Rightarrow$ mệnh đề đúng.<br>Vậy cả 3 mệnh đề đều đúng. Chọn B."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Trong kì thi học sinh giỏi quốc gia có 4 bạn Phương, Dương, Hiếu, Hằng tham gia và hai bạn bất kì trong bốn bạn này không sống cùng một thành phố. Các phát biểu:<br>a) Phương: Dương ở Huế, còn tôi ở Sài Gòn.  <br>b) Dương: Tôi cũng ở Sài Gòn, còn Hiếu ở Huế.  <br>c) Hiếu: Không, tôi ở Đà Nẵng, còn Hằng ở Vinh.  <br>d) Hằng: trong các câu trả lời trên đều có một vế đúng và một vế sai.<br>Hỏi chính xác quê Dương ở đâu?", "choices": ["Huế", "Sài Gòn", "Vinh", "Đà Nẵng"], "correctIndex": 3, "explain": "Theo lời Hằng, mỗi câu của Phương, Dương, Hiếu gồm 1 đúng và 1 sai, và 4 bạn ở 4 thành phố khác nhau.<br>Thử các khả năng cho Dương:<br>a) Nếu Dương ở Huế: câu Dương “Hiếu ở Huế” đúng $\\Rightarrow$ Hiếu ở Huế, trùng thành phố $\\Rightarrow$ loại.  <br>b) Nếu Dương ở Sài Gòn: Phương “tôi ở Sài Gòn” đúng $\\Rightarrow$ Phương trùng với Dương $\\Rightarrow$ loại.  <br>c) Nếu Dương ở Vinh: Hiếu “Hằng ở Vinh” đúng $\\Rightarrow$ Hằng trùng với Dương $\\Rightarrow$ loại.  <br>d) Nếu Dương ở Đà Nẵng: suy ra Phương ở Sài Gòn (đúng/sai phù hợp), Hiếu ở Huế, Hằng ở Vinh; bốn thành phố đều khác nhau và mỗi câu có 1 đúng, 1 sai. Hợp lệ.<br>Vậy Dương ở Đà Nẵng. Chọn D."}]}, {"noiDungChung": "Có 6 thành phố $A, B, C, D, E, F$ được nối với nhau bằng một số tuyến đường cao tốc. Chi phí (tính bằng triệu đồng) để xây dựng các tuyến đường nối giữa các thành phố được cho trong bảng.<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">A</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">B</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">C</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">D</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">E</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">F</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">A</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">10</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">8</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">6</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">B</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">10</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">12</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">7</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">C</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">12</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">9</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">5</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">D</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">8</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">9</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">11</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">E</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">7</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">11</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">8</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">F</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">6</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">5</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">8</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">0</td></tr></table>", "cauHoi": [{"question": "Hỏi tổng chi phí xây dựng tất cả các tuyến đường nối giữa các thành phố là:", "choices": ["72", "74", "76", "78"], "correctIndex": 2, "explain": "Tổng chi phí = $10+8+6+12+7+9+5+11+8=76$."}, {"question": "Nếu chỉ chọn một hệ thống đường sao cho tất cả các thành phố đều được nối với nhau (mỗi cặp thành phố có đường đi, không nhất thiết trực tiếp), và tổng chi phí là nhỏ nhất, thì tổng chi phí đó bằng bao nhiêu?", "choices": ["36", "38", "40", "42"], "correctIndex": 2, "explain": "Bài toán tìm <i>cây khung nhỏ nhất</i> (Minimum Spanning Tree). Chọn các cạnh ngắn nhất mà vẫn nối đủ 6 thành phố: A-F (6), C-F (5), B-E (7), A-D (8), C-D (9). Tổng = $6+5+7+8+9=35$. Kiểm tra lại cần đủ 5 cạnh cho 6 đỉnh, thêm một cạnh nữa (ví dụ B-A:10) để nối đủ, tổng = $40$.<br>Vậy chi phí nhỏ nhất là $40$."}]}, {"noiDungChung": "Số liệu thống kê tình hình việc làm của sinh viên ngành Toán sau khi tốt nghiệp của các khóa tốt nghiệp 2023 và 2024 được trình bày trong bảng sau:<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">p{1.5cm}|>{\\centering\\arraybackslash} p{1.5cm}|>{\\centering\\arraybackslash} p{1.5cm}|c|c|}  STT</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Lĩnh vực việc làm</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Khóa tốt nghiệp 2023</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Khóa tốt nghiệp 2024</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Nữ</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Nam</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Nữ</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Nam</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">1</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Giảng dạy</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">25</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">45</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">25</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">65</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">2</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Tài chính</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">23</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">186</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">20</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">32</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">3</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Lập trình</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">25</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">120</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">12</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">58</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">4</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Bảo hiểm</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">12</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">100</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">3</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">5</td></tr></table>", "cauHoi": [{"question": "Trong số nữ sinh có việc làm ở Khóa tốt nghiệp 2023, tỷ lệ phần trăm của nữ làm trong lĩnh vực Giảng dạy là bao nhiêu?", "choices": ["$11,2\\%$", "$12,2\\%$", "$15,0\\%$", "$29,4\\%$"], "correctIndex": 3, "explain": "Tổng số nữ sinh có việc làm ở Khóa 2023: $25+23+25+12=85$.<br>Số nữ làm Giảng dạy: $25$.<br>Tỉ lệ: $\\dfrac{25}{85}\\cdot 100\\%\\approx 29,4\\%$.<br>Chọn D."}, {"question": "Tính cả hai khóa tốt nghiệp 2023 và 2024, số sinh viên làm trong lĩnh vực Tài chính nhiều hơn số sinh viên làm trong lĩnh vực Giảng dạy là bao nhiêu phần trăm?", "choices": ["$67,2\\%$", "$63,1\\%$", "$62,0\\%$", "$68,5\\%$"], "correctIndex": 1, "explain": "Tài chính: $23+186+20+32=261$.<br>Giảng dạy: $25+45+25+65=160$.<br>Tỉ lệ hơn: $\\dfrac{261-160}{160}\\cdot 100\\%\\approx 63,1\\%$.<br>Chọn B."}, {"question": "Tính cả hai khóa tốt nghiệp 2023 và 2024, lĩnh vực nào có tỷ lệ phần trăm nữ cao hơn các lĩnh vực còn lại?", "choices": ["Giảng dạy", "Tài chính", "Lập trình", "Bảo hiểm"], "correctIndex": 2, "explain": "Giảng dạy: $\\dfrac{25+25}{25+45+25+65}\\cdot 100\\%\\approx 15,6\\%$.<br>Tài chính: $\\dfrac{23+20}{23+186+20+32}\\cdot 100\\%\\approx 16,4\\%$.<br>Lập trình: $\\dfrac{25+12}{25+120+12+58}\\cdot 100\\%\\approx 17,2\\%$.<br>Bảo hiểm: $\\dfrac{12+3}{12+100+3+5}\\cdot 100\\%=12,5\\%$.<br>Trong các lĩnh vực, Lập trình có tỉ lệ nữ cao nhất $\\approx 17,2\\%$.<br><b>(Lưu ý: trong lời giải gốc có nhầm, đáp án đúng phải là Lập trình.)</b>"}, {"question": "Tính cả hai khóa tốt nghiệp 2023 và 2024, ở các lĩnh vực trong bảng số liệu, số sinh viên nam có việc làm nhiều hơn số sinh viên nữ có việc làm là bao nhiêu phần trăm?", "choices": ["$521,4\\%$", "$421,4\\%$", "$321,4\\%$", "$221,4\\%$"], "correctIndex": 2, "explain": "Nam: $45+186+120+100+65+32+58+5=611$.<br>Nữ: $25+23+25+12+25+20+12+3=145$.<br>Tỉ lệ hơn: $\\dfrac{611-145}{145}\\cdot 100\\%\\approx 321,4\\%$.<br>Chọn C."}]}]}, {"id": "extra-7", "ten": "Đề luyện tập số 13", "nhom": [{"noiDungChung": "Cho hàm số $y=f(x)=\\ln |x^2-2x-3|$ có đồ thị là $(C)$.", "cauHoi": [{"question": "Tìm tập xác định $D$ của hàm số đã cho.", "choices": ["$D=\\mathbb{R}$", "$D=(-1;3)$", "$D=\\mathbb{R}\\setminus \\{-1;3\\}$", "$D=(-\\infty;-1)\\cup (3;+\\infty)$"], "correctIndex": 2, "explain": "Hàm số xác định khi $|x^2-2x-3|>0 \\Leftrightarrow x^2-2x-3 \\neq 0 \\Leftrightarrow \\heva{&x \\neq -1\\\\&x \\neq 3.}$  Vậy $D = \\mathbb{R}\\setminus \\{-1;3\\}$."}, {"question": "Gọi $(C')$ là đồ thị đối xứng với $(C)$ qua đường thẳng $x=1$. Khẳng định nào sau đây là đúng về $(C')$?", "choices": ["$(C')$ trùng với $(C)$", "$(C')$ là đồ thị hàm số $y=\\ln |x^2+2x-3|$", "$(C')$ đối xứng với $(C)$ qua trục hoành", "$(C')$ không có đường tiệm cận đứng"], "correctIndex": 0, "explain": "Đồ thị $(C)$ đối xứng qua đường thẳng $x=-\\dfrac{b}{2a} = -\\dfrac{-2}{2(1)}=1$ (trục đối xứng của parabol $y=x^2-2x-3$).  Vì đồ thị gốc $(C)$ có trục đối xứng là $x=1$ nên khi lấy đối xứng qua chính đường thẳng đó, ta thu được chính nó.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, x=1cm, y=1cm, scale=.7]\n\t\t\t\t\t\n\t\t\t\t\t\\draw[->] (-3.5,0) -- (5.5,0) node[below] {$x$};\n\t\t\t\t\t\\draw[->] (0,-4) -- (0,3.5) node[left] {$y$};\n\t\t\t\t\t\\fill (0,0) circle (1.5pt) node[below right] {$O$};\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed, thin] (-1,-4) -- (-1,3.5) node[above left] {$x=-1$};\n\t\t\t\t\t\\draw[dashed, thin] (3,-4) -- (3,3.5) node[above right] {$x=3$};\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed, thick, blue] (1,3.5) -- (1,-4) node[above right] {$x=1$};\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\clip (-3.5,-4) rectangle (5.5,3.5);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick, samples=100, domain=-3.5:-1.02] plot (\\x, {ln(abs(\\x*\\x - 2*\\x - 3))});\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick, samples=100, domain=-0.98:2.98] plot (\\x, {ln(abs(\\x*\\x - 2*\\x - 3))});\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick, samples=100, domain=3.02:5.5] plot (\\x, {ln(abs(\\x*\\x - 2*\\x - 3))});\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\fill (1, {ln(4)}) circle (1.5pt);\n\t\t\t\t\t\\draw[dashed, thin] (1,0) node[below right] {$1$} -- (1,{ln(4)}) -- (0,{ln(4)}) node[left] {$\\ln 4$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Tìm tất cả các giá trị nguyên dương của tham số $m$ để phương trình $f(x)=m$ có đúng $4$ nghiệm phân biệt.", "choices": ["$0$", "$1$", "$2$", "$3$"], "correctIndex": 1, "explain": "Xét phương trình $\\ln |x^2-2x-3|=m \\Leftrightarrow |x^2-2x-3|=e^m$.<br>Vì $e^m>0$ với mọi $m \\in \\mathbb{R}$, phương trình $|x^2-2x-3|=e^m \\; (*)$ tương đương với:  $\\hoac{&x^2-2x-3=e^m \\; (1)\\\\&x^2-2x-3=-e^m\\; (2).}$<br>Đặt $g(x)=x^2-2x-3$. <br>Bảng biến thiên của hàm số $y=g(x)$:<br>Để phương trình $(*)$ có 4 nghiệm phân biệt thì phương trình $(1)$ và $(2)$ mỗi phương trình phải có 2 nghiệm phân biệt.<br>Phương trình $(1)$ có 2 nghiệm phân biệt $\\Leftrightarrow e^m > -4$ (luôn đúng) $\\Leftrightarrow m \\in \\mathbb{R}$ .<br>Phương trình $(2)$ có 2 nghiệm phân biệt $\\Leftrightarrow -e^m > -4 \\Leftrightarrow e^m < 4 \\Leftrightarrow m < \\ln4$ . <br>Do đó, phương trình $(*)$ có 4 nghiệm phân biệt $\\Leftrightarrow m < \\ln4$.<br>Mà $m \\in \\mathbb{Z^+}$ nên có $1$ số nguyên dương $m$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một bệnh nhân được chỉ định uống một loại thuốc định kỳ $24$ giờ một lần. Mỗi lần bệnh nhân uống đúng $50$ mg thuốc. Biết rằng sau mỗi $24$ giờ, lượng thuốc còn lại trong cơ thể bệnh nhân chỉ bằng $20\\%$ so với lượng thuốc ngay sau khi uống lần trước đó. Tính tổng lượng thuốc tồn dư trong cơ thể bệnh nhân sau một thời gian dài điều trị (ngay sau khi uống một liều mới).", "choices": ["$50$ mg", "$62{,}5$ mg", "$60$ mg", "$250$ mg"], "correctIndex": 1, "explain": "Gọi $u_n$ là lượng thuốc trong cơ thể bệnh nhân ngay sau khi uống liều thứ $n$.<br>a) Ngay sau khi uống liều thứ nhất ($n=1$): $u_1 = 50$ mg.  <br>b) Ngay sau khi uống liều thứ hai ($n=2$): $u_2 = 50 + 50 \\cdot 0{,}2$ mg.  <br>c) Ngay sau khi uống liều thứ ba ($n=3$): $u_3 = 50 + 50 \\cdot 0{,}2 + 50 \\cdot (0{,}2)^2$ mg.<br>Tổng quát, lượng thuốc trong cơ thể sau khi uống liều thứ $n$ là:  $$u_n = 50 + 50 \\cdot 0{,}2 + 50 \\cdot (0{,}2)^2 + \\dots + 50 \\cdot (0{,}2)^{n-1}$$  Đây là tổng của $n$ số hạng đầu tiên của một cấp số nhân có số hạng đầu $u_1 = 50$ và công bội $q = 0{,}2$.  Khi bệnh nhân điều trị trong một thời gian dài ($n \\to +\\infty$), lượng thuốc tồn dư là tổng của cấp số nhân lùi vô hạn:  $$S = \\dfrac{u_1}{1-q} = \\dfrac{50}{1-0{,}2} = \\dfrac{50}{0{,}8} = 62{,}5 \\text{ mg}$$  Vậy tổng lượng thuốc tồn dư trong cơ thể bệnh nhân ngay sau khi uống liều mới là $62{,}5$ mg."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho một hình vuông có cạnh bằng $2$ đơn vị. Bên trong hình vuông này có $9$ điểm bất kỳ. Khẳng định nào sau đây là đúng?", "choices": ["Luôn tồn tại ít nhất $3$ điểm nằm trong một hình vuông nhỏ có cạnh bằng $1$", "Luôn tồn tại ít nhất $4$ điểm nằm trong một hình vuông nhỏ có cạnh bằng $1$", "Có ít nhất $5$ điểm nằm trong một hình chữ nhật có diện tích bằng $1$", "Không thể khẳng định được gì về vị trí các điểm"], "correctIndex": 0, "explain": "Chia hình vuông cạnh $2$ thành $4$ hình vuông nhỏ có cạnh bằng $1$.<br>Ta coi $4$ hình vuông nhỏ này là $4$ cái “lồng”, và $9$ điểm là $9$ con “chim”.<br>Theo nguyên lý Dirichlet mở rộng, vì $9 = 4 \\times 2 + 1$, nên phải có ít nhất $\\left\\lfloor \\dfrac{9-1}{4} \\right\\rfloor + 1 = 3$ điểm cùng nằm trong một hình vuông nhỏ."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hàm số $f(x)$ có đạo hàm trên $\\mathbb{R}$. Xét các hàm số $g(x)=f(x)-f(2x)$ và $h(x)=f(x)-f(4x)$. Biết rằng $g'(1)=5$ và $g'(2)=7$. Tính giá trị của $h'(1)$.", "choices": ["$h'(1)=12$", "$h'(1)=17$", "$h'(1)=19$", "$h'(1)=24$"], "correctIndex": 2, "explain": "Ta có $g'(x)=f'(x)-2f'(2x)$ và $h'(x)=f'(x)-4f'(4x)$.<br>Dựa vào giả thiết, ta có hệ phương trình:  $\\heva{&f'(1)-2f'(2)=5\\\\&f'(2)-2f'(4)=7.}$<br>Từ phương trình thứ hai, ta có $2f'(2)-4f'(4)=14$.<br>Cộng vế theo vế với phương trình đầu tiên:  $(f'(1)-2f'(2))+(2f'(2)-4f'(4))=5+14$  $\\Leftrightarrow f'(1)-4f'(4)=19$.<br>Vậy $h'(1)=19$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Trên lưới tọa độ $Oxy$, một chất điểm chỉ được phép di chuyển sang phải hoặc lên trên. Tính số đường đi ngắn nhất từ điểm $A(0;0)$ đến điểm $B(4;3)$ sao cho đường đi đó bắt buộc phải đi qua điểm $C(2;1)$.", "choices": ["$15$", "$21$", "$18$", "$35$"], "correctIndex": 2, "explain": "Số cách đi từ $A(0;0)$ đến $C(2;1)$ là $\\mathrm{C}_{2+1}^1 = \\mathrm{C}_3^1 = 3$ cách.<br>Số cách đi từ $C(2;1)$ đến $B(4;3)$ là đi thêm $2$ đơn vị sang phải và $2$ đơn vị lên trên, số cách là $\\mathrm{C}_{2+2}^2 = \\mathrm{C}_4^2 = 6$ cách.<br>Theo quy tắc nhân, tổng số cách đi là $3 \\cdot 6 = 18$ cách."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tam giác $ABC$ có các cạnh $a$, $b$, $c$ thỏa mãn điều kiện $\\dfrac{a+b}{6}=\\dfrac{b+c}{5}=\\dfrac{a+c}{7}$. Tính $\\cos A$.", "choices": ["$- \\dfrac{1}{4}$", "$\\dfrac{1}{3}$", "$- \\dfrac{1}{3}$", "$\\dfrac{1}{2}$"], "correctIndex": 1, "explain": "Ta có: $\\dfrac{a+b}{6}=\\dfrac{b+c}{5}=\\dfrac{a+c}{7}=t \\Leftrightarrow\\left\\{\\begin{array}{l}a+b=6 t \\\\ b+c=5 t \\\\ a+c=7 t\\end{array} \\Rightarrow a+b+c=9 t\\right.$. <br>Vậy $\\left\\{\\begin{array}{l}a=4 t \\\\ b=2 t \\\\ c=3 t\\end{array}\\right.$.<br>Theo định lí côsin: $\\cos A=\\dfrac{b^2+c^2-a^2}{2 b c}=\\dfrac{4 t^2+9 t^2-16 t^2}{2.2 t .3 t}=-\\dfrac{1}{4}$.<br>Tương tự, ta tính được: $\\cos B=\\dfrac{7}{8} ; \\cos C=\\dfrac{11}{16}$."}]}, {"noiDungChung": "Trong mặt phẳng $Oxy$, cho đường tròn $(C)\\colon x^2+y^2-2x+8y+12=0$ có tâm $I$.", "cauHoi": [{"question": "Xác định vị trí tương đối của điểm $M(-3;2)$ đối với đường tròn $(C)$.", "choices": ["Điểm $M$ nằm bên trong đường tròn $(C)$", "Điểm $M$ nằm trên đường tròn $(C)$", "Điểm $M$ nằm bên ngoài đường tròn $(C)$", "Điểm $M$ trùng với tâm $I$ của đường tròn $(C)$"], "correctIndex": 2, "explain": "Đường tròn $(C)$ có tâm $I(1;-4)$ và bán kính $R=\\sqrt{1^2+(-4)^2-12}=\\sqrt{5}$.<br>Ta có $\\overrightarrow{IM}=(-4;6) \\Rightarrow IM=\\sqrt{(-4)^2+6^2}=\\sqrt{16+36}=\\sqrt{52}$.<br>Vì $IM=\\sqrt{52} > \\sqrt{5}=R$ nên điểm $M$ nằm bên ngoài đường tròn $(C)$."}, {"question": "Đường thẳng nào sau đây tiếp xúc với đường tròn $(C)$?", "choices": ["$\\Delta \\colon x+y=0$", "$\\Delta \\colon 2x-y-11=0$", "$\\Delta \\colon 2x+y-3=0$", "$\\Delta \\colon x-2y+5=0$"], "correctIndex": 1, "explain": "Đường tròn $(C)$ có tâm $I(1;-4)$ và bán kính $R=\\sqrt{5}$.<br>Đường thẳng tiếp xúc với $(C)$ khi và chỉ khi $\\mathrm{d}(I,\\Delta)=R=\\sqrt{5}$.<br>Xét đường thẳng $\\Delta \\colon 2x-y-11=0$, ta có:  $\\mathrm{d}(I,\\Delta)=\\dfrac{|2\\cdot 1-(-4)-11|}{\\sqrt{2^2+(-1)^2}}=\\dfrac{|-5|}{\\sqrt{5}}=\\sqrt{5}$ (thỏa mãn)."}, {"question": "Đường thẳng $d\\colon mx+y+2=0$ cắt đường tròn $(C)$ tại hai điểm phân biệt $A$ và $B$. Tích các giá trị của tham số $m$ để diện tích tam giác $IAB$ lớn nhất.", "choices": ["$-\\dfrac{1}{3}$", "$3$", "$-1$", "$2$"], "correctIndex": 2, "explain": "Ta có $S_{\\triangle IAB}=\\dfrac{1}{2}IA \\cdot IB \\cdot \\sin\\widehat{AIB}=\\dfrac{5}{2}\\sin\\widehat{AIB} \\le \\dfrac{5}{2}$.<br>Dấu bằng xảy ra khi $\\sin\\widehat{AIB}=1 \\Leftrightarrow \\widehat{AIB}=90^\\circ$.<br>Gọi $H$ là hình chiếu của $I$ lên $d$. Khi đó tam giác $IAB$ vuông cân tại $I$, suy ra $IH=\\dfrac{IA}{\\sqrt{2}}=\\dfrac{\\sqrt{5}}{\\sqrt{2}}$.<br>Ta có $\\mathrm{d}(I,d)=IH \\Leftrightarrow \\dfrac{|m \\cdot 1-4+2|}{\\sqrt{m^2+1}}=\\dfrac{\\sqrt{5}}{\\sqrt{2}} \\Leftrightarrow \\dfrac{|m-2|}{\\sqrt{m^2+1}}=\\sqrt{\\dfrac{5}{2}}$  $\\Leftrightarrow 2(m-2)^2=5(m^2+1) \\Leftrightarrow 2(m^2-4m+4)=5m^2+5 \\Leftrightarrow 3m^2+8m-3=0 \\Leftrightarrow \\hoac{&m=\\dfrac{1}{3}\\\\&m=-3.}$<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1,>=stealth, font=\\footnotesize, line join=round, line cap=round]\n\t\t\t\t\t\\def\\r{2}\n\t\t\t\t\t\\path\n\t\t\t\t\t(0,0) coordinate (I)\n\t\t\t\t\t(I)+ (30:\\r) coordinate (B)\n\t\t\t\t\t(I)+ (120:\\r) coordinate (A)\n\t\t\t\t\t($(A)!.5!(B)$) coordinate (H)\n\t\t\t\t\t;\n\t\t\t\t\t\\draw (I) circle (\\r);\n\t\t\t\t\t\\draw ($(A)!-0.5!(B)$)-- ($(A)!1.5!(B)$) node[above]{$d$} (I)--(H) (A)--(I)--(B);\n\t\t\t\t\t\\foreach \\x/\\g in {A/80,B/80,H/80,I/-80}\n\t\t\t\t\t\\fill[black] (\\x) circle (1pt) ($(\\g:3mm)+(\\x)$) node {$\\x$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Một bồn chứa xăng có hình dạng là một khối tròn xoay, được tạo thành khi quay hình phẳng giới hạn bởi đường cong $y = \\dfrac{1}{4}x^2$, trục hoành và hai đường thẳng $x = 0$, $x = 4$ quanh trục $Ox$ (đơn vị trên các trục là mét).", "cauHoi": [{"question": "Tính thể tích $V$ của bồn chứa xăng đó.", "choices": ["$V = \\dfrac{16\\pi}{5}\\text{ m}^3$", "$V = \\dfrac{64\\pi}{5}\\text{ m}^3$", "$V = \\dfrac{4\\pi}{3}\\text{ m}^3$", "$V = 4\\pi\\text{ m}^3$"], "correctIndex": 0, "explain": "Thể tích vật thể tròn xoay khi quay quanh trục $Ox$ được tính bởi công thức:  $$V = \\pi \\int\\limits_{0}^{4} [f(x)]^2 dx = \\pi \\int\\limits_{0}^{4} \\left(\\dfrac{1}{4}x^2\\right)^2 dx = \\pi \\int\\limits_{0}^{4} \\dfrac{x^4}{16} dx$$  $$= \\dfrac{\\pi}{16} \\cdot \\left. \\dfrac{x^5}{5} \\right|_{0}^{4} = \\dfrac{\\pi}{16} \\cdot \\dfrac{4^5}{5} = \\dfrac{\\pi \\cdot 1024}{80} = \\dfrac{16\\pi}{5}\\text{ (m}^3\\text{)}.$$"}, {"question": "Hiện tại bồn đang chứa đầy xăng. Giá mỗi mét khối xăng là $20$ triệu đồng. Do xăng bay hơi theo thời gian, tốc độ hao hụt xăng được xác định bởi hàm số $r(t) = 0{,}02e^{0{,}1t}$ ($\\text{m}^3\\text{/tháng}$), với $t$ là số tháng tính từ lúc bồn đầy. Số tiền (làm tròn đến triệu đồng) mà công ty bị tổn thất do xăng bay hơi sau $10$ tháng xấp xỉ", "choices": ["$5$ triệu đồng", "$6$ triệu đồng", "$7$ triệu đồng", "$8$ triệu đồng"], "correctIndex": 2, "explain": "Tổng lượng xăng bị bay hơi sau $10$ tháng là:  $$\\Delta V = \\int\\limits_{0}^{10} r(t) dt = \\int\\limits_{0}^{10} 0{,}02e^{0{,}1t} dt$$  $$= 0{,}02 \\cdot \\left. \\dfrac{e^{0{,}1t}}{0{,}1} \\right|_{0}^{10} = 0{,}2 \\left( e^1 - e^0 \\right) = 0{,}2(e - 1) \\approx 0{,}3436\\text{ (m}^3\\text{)}.$$  Số tiền tổn thất là: $0{,}3436 \\cdot 20 = 6{,}872$ triệu đồng.  Làm tròn đến hàng đơn vị ta được $7$ triệu đồng."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Lan có một miếng bìa hình tam giác $ABC$ vuông tại $A$, cạnh $AB=3\\text{ cm}$. Lan cắt từ miếng bìa đó ra một hình chữ nhật $ADEF$ sao cho đỉnh $D$ nằm trên cạnh $AB$, đỉnh $F$ nằm trên cạnh $AC$ và đỉnh $E$ nằm trên cạnh huyền $BC$. Biết rằng hình chữ nhật này có chiều dài $AF=2\\text{ cm}$ và diện tích của nó bằng một nửa diện tích của miếng bìa ban đầu. Diện tích của tam giác $ABC$ là", "choices": ["$4\\text{ cm}^2$", "$8\\text{ cm}^2$", "$12\\text{ cm}^2$", "$6\\text{ cm}^2$"], "correctIndex": 3, "explain": "Gọi độ dài cạnh $AC$ là $x$ ($x>2$, đơn vị $\\text{cm}$).<br>Diện tích tam giác $ABC$ là $S_{ABC} = \\dfrac{1}{2}AB \\cdot AC = \\dfrac{3x}{2}$.<br>Theo hình vẽ, hình chữ nhật $ADEF$ có $D \\in AB$, $E \\in BC$, $F \\in AC$.<br>Chiều dài hình chữ nhật là $AF = 2\\text{ cm}$.<br>Vì $EF \\parallel AB$, theo định lý Ta-lét ta có:<br>$\\dfrac{EF}{AB} = \\dfrac{CF}{AC} \\Rightarrow \\dfrac{EF}{3} = \\dfrac{x-2}{x} \\Rightarrow EF = \\dfrac{3(x-2)}{x}$.<br>Diện tích hình chữ nhật $ADEF$ là:  $S_{ADEF} = AF \\cdot EF = 2 \\cdot \\dfrac{3(x-2)}{x} = \\dfrac{6(x-2)}{x}$.<br>Theo giả thiết: $S_{ADEF} = \\dfrac{1}{2}S_{ABC}$  $\\Leftrightarrow \\dfrac{6(x-2)}{x} = \\dfrac{3x}{4} \\Leftrightarrow 24(x-2) = 3x^2$  $\\Leftrightarrow 3x^2 - 24x + 48 = 0 \\Leftrightarrow x^2 - 8x + 16 = 0$  $\\Leftrightarrow (x-4)^2 = 0 \\Leftrightarrow x = 4$ (thỏa mãn).<br>Với $AC = 4\\text{ cm}$, diện tích tam giác $ABC$ là:  $S_{ABC} = \\dfrac{1}{2} \\cdot 3 \\cdot 4 = 6\\text{ (cm}^2\\text{)}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, font=\\footnotesize, line join=round, line cap=round]\n\t\t\t\t\\coordinate (A) at (0,0);\n\t\t\t\t\\coordinate (B) at (0,3);\n\t\t\t\t\\coordinate (C) at (4,0);\n\t\t\t\t\\coordinate (F) at (2,0);\n\t\t\t\t\\coordinate (E) at (2,1.5);\n\t\t\t\t\\coordinate (D) at (0,1.5);\n\t\t\t\t\\draw[thick] (A)--(B)--(C)--cycle;\n\t\t\t\t\\draw[fill=gray!20] (A)--(D)--(E)--(F)--cycle;\n\t\t\t\t\\draw (0,0.2)-|(0.2,0);\n\t\t\t\t\\draw (0,1.3)-|(0.2,1.5);\n\t\t\t\t\\draw (1.8,0)|-(2,0.2);\n\t\t\t\t\\draw (1.8,1.5)|-(2,1.3);\n\t\t\t\t\\draw [decorate,decoration={brace,amplitude=5pt,mirror}] (0,-0.1)--(2,-0.1) node [black,midway,yshift=-0.4cm] {$2\\text{ cm}$};\n\t\t\t\t\\draw [decorate,decoration={brace,amplitude=5pt}] (-0.1,0)--(-0.1,3) node [black,midway,xshift=-0.5cm] {$3\\text{ cm}$};\n\t\t\t\t\\draw (A) node[below left]{$A$};\n\t\t\t\t\\draw (B) node[above left]{$B$};\n\t\t\t\t\\draw (C) node[below right]{$C$};\n\t\t\t\t\\draw (D) node[left]{$D$};\n\t\t\t\t\\draw (E) node[above right]{$E$};\n\t\t\t\t\\draw (F) node[below]{$F$};\n\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một công ty du lịch thông báo giá tiền cho chuyến đi thăm quan của một nhóm khách như sau: $40$ khách đầu tiên có giá $490.000$ đồng/người. Nếu có nhiều hơn $40$ người đăng ký thì cứ có thêm một người, giá vé sẽ giảm $10.000$ đồng/người cho toàn bộ hành khách. Biết chi phí thực sự của chuyến đi là $19.380.000$ đồng. Gọi $n_1$ là số lượng khách để công ty đạt doanh thu cao nhất và $n_2$ là số lượng khách tối đa để công ty không bị lỗ. Chênh lệch giữa $n_2$ và $n_1$ là", "choices": ["$6$ người", "$11$ người", "$7$ người", "$10$ người"], "correctIndex": 0, "explain": "Gọi $x$ là số người thêm vào sau $40$ khách đầu tiên ($x \\in \\mathbb{N}$). Tổng số khách là $n = 40+x$.<br>Giá vé áp dụng cho toàn bộ hành khách là $490.000-10.000x$ (đồng/người).<br>Hàm doanh thu của công ty là:   $T(x) = (40+x)(490.000-10.000x) = -10.000x^2 + 90.000x + 19.600.000$.<br>a) \\textbf{Tìm $n_1$ (Số khách để doanh thu cao nhất):}<br>Hàm số $T(x)$ là hàm bậc hai có bề lõm quay xuống dưới, đạt giá trị lớn nhất tại đỉnh có hoành độ $x = \\dfrac{-90.000}{2 \\cdot (-10.000)} = 4{,}5$.<br>Vì $x$ phải là số nguyên nên doanh thu cao nhất khi $x=4$ hoặc $x=5$ (do $T(4) = T(5) = 19.800.000$).<br>Để lấy số khách nhiều nhất theo xu hướng thị trường, ta chọn $x=5$.<br>Vậy $n_1 = 40 + 5 = 45$ (người).  <br>b) \\textbf{Tìm $n_2$ (Số khách tối đa để không bị lỗ):}<br>Công ty không bị lỗ khi tổng doanh thu không thấp hơn chi phí thực sự:  $$T(x) \\ge 19.380.000 \\Leftrightarrow -10.000x^2 + 90.000x + 19.600.000 \\ge 19.380.000$$  $\\Leftrightarrow -10.000x^2 + 90.000x + 220.000 \\ge 0 \\Leftrightarrow -x^2 + 9x + 22 \\ge 0$.<br>Tam thức bậc hai $-x^2 + 9x + 22$ có hai nghiệm là $x = -2$ và $x = 11$.<br>Vì $x \\ge 0$ nên ta có $0 \\le x \\le 11$. Số khách thêm vào tối đa là $x=11$.<br>Vậy $n_2 = 40 + 11 = 51$ (người).<br>Chênh lệch giữa số khách tối đa không lỗ và số khách doanh thu cao nhất là:  $n_2 - n_1 = 51 - 45 = 6$ (người)."}]}, {"noiDungChung": "Cho dãy số $(u_n)$ có số hạng tổng quát $u_n = \\dfrac{1+2+3+\\dots+n}{n^2+1}$ và giới hạn $L = \\displaystyle\\lim \\limits_{n \\to +\\infty} \\left( \\sqrt{n^2+an+1} - n \\right)$ với $a$ là tham số thực.", "cauHoi": [{"question": "Tính giá trị của giới hạn $\\displaystyle\\lim \\limits_{n \\to +\\infty} u_n$.", "choices": ["$0$", "$\\dfrac{1}{2}$", "$1$", "$+\\infty$"], "correctIndex": 1, "explain": "Ta có tổng của $n$ số hạng đầu tiên của cấp số cộng: $1+2+3+\\dots+n = \\dfrac{n(n+1)}{2}$.<br>Khi đó: $u_n = \\dfrac{n(n+1)}{2(n^2+1)} = \\dfrac{n^2+n}{2n^2+2}$.<br>Suy ra: $\\displaystyle\\lim \\limits_{n \\to +\\infty} u_n = \\displaystyle\\lim \\limits_{n \\to +\\infty} \\dfrac{n^2+n}{2n^2+2} = \\displaystyle\\lim \\limits_{n \\to +\\infty} \\dfrac{1+\\dfrac{1}{n}}{2+\\dfrac{2}{n^2}} = \\dfrac{1}{2}$."}, {"question": "Tìm giá trị của tham số $a$ để giới hạn $I = \\displaystyle\\lim \\limits_{n \\to +\\infty} \\left[ u_n \\cdot \\left( \\sqrt{4n^2+an+1} - 2n \\right) \\right] = 1$.", "choices": ["$a=2$", "$a=4$", "$a=8$", "$a=16$"], "correctIndex": 2, "explain": "Từ câu 1, ta đã biết $\\displaystyle\\lim \\limits_{n \\to +\\infty} u_n = \\dfrac{1}{2}$.<br>Xét $K = \\displaystyle\\lim \\limits_{n \\to +\\infty} \\left( \\sqrt{4n^2+an+1} - 2n \\right) = \\displaystyle\\lim \\limits_{n \\to +\\infty} \\dfrac{(4n^2+an+1) - 4n^2}{\\sqrt{4n^2+an+1} + 2n} = \\displaystyle\\lim \\limits_{n \\to +\\infty} \\dfrac{an+1}{\\sqrt{4n^2+an+1} + 2n}$.<br>Chia cả tử và mẫu cho $n$: $K = \\dfrac{a}{\\sqrt{4}+2} = \\dfrac{a}{4}$.<br>Khi đó $I = \\displaystyle\\lim \\limits_{n \\to +\\infty} u_n \\cdot K = \\dfrac{1}{2} \\cdot \\dfrac{a}{4} = \\dfrac{a}{8}$.<br>Theo đề bài $I=1 \\Rightarrow \\dfrac{a}{8}=1 \\Leftrightarrow a=8$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Có $32$ tấm thẻ được đánh số từ $1$ đến $32$. Rút ngẫu nhiên $3$ thẻ. Tính xác suất để tổng các số ghi trên thẻ chia hết cho $3$ xấp xỉ", "choices": ["$31,25\\%$", "$33,47\\%$", "$34,4\\%$", "$30\\%$"], "correctIndex": 1, "explain": "Số phần tử của không gian mẫu $n(\\Omega)=\\mathrm{C}_{32}^3$.<br>$A=\\{3;6;9;\\ldots;30\\}$ là tập các số chia hết cho $3$.<br>$B=\\{1;4;7;\\ldots;31\\}$ là tập các số chia hết cho $3$ dư $1$.<br>$C=\\{2;5;8;\\ldots;32\\}$ là tập các số chia hết cho $3$ dư $2$.<br>Để $3$ số được viết có tổng chia hết cho $3$ thì có các trường hợp sau:<br>a) TH1. $3$ số lấy ra từ tập $A$ có $\\mathrm{C}_{10}^3$ (cách).  <br>b) TH2. $3$ số lấy ra từ tập $B$ có $\\mathrm{C}_{11}^3$ (cách).  <br>c) TH3. $3$ số lấy ra từ tập $C$ có $\\mathrm{C}_{11}^3$ (cách).  <br>d) TH4. $1$ số lấy ra từ tập $A$, $1$ lấy ra từ tập $B$, $1$ lấy ra từ tập $C$ có $\\mathrm{C}_{10}^1\\cdot \\mathrm{C}_{11}^1\\cdot \\mathrm{C}_{11}^1$ (cách).<br>Vậy xác suất để tổng các số ghi trên thẻ chia hết cho $3$ là  $$\\dfrac{\\mathrm{C}_{10}^3+\\mathrm{C}_{11}^3+\\mathrm{C}_{11}^3+\\mathrm{C}_{10}^1\\cdot \\mathrm{C}_{11}^1\\cdot \\mathrm{C}_{11}^1}{\\mathrm{C}_{32}^3}=\\dfrac{83}{248}.$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hàm số $y = \\dfrac{\\log_2 x}{x}$. Biết đạo hàm của hàm số có dạng $y' = \\dfrac{a + b \\ln x}{x^2 \\ln 2}$. Tính giá trị của biểu thức $P = a + b$.", "choices": ["$P = 2$", "$P = -2$", "$P = 1$", "$P = 0$"], "correctIndex": 3, "explain": "Điều kiện xác định: $x > 0$.<br>Áp dụng quy tắc đạo hàm của một thương $y' = \\left( \\dfrac{\\log_2 x}{x} \\right)' = \\dfrac{(\\log_2 x)' \\cdot x - (\\log_2 x) \\cdot (x)'}{x^2}$.<br>Thay vào biểu thức đạo hàm, ta được:  $$y' = \\dfrac{\\dfrac{1}{x \\ln 2} \\cdot x - \\log_2 x \\cdot 1}{x^2} = \\dfrac{\\dfrac{1}{\\ln 2} - \\log_2 x}{x^2}.$$  $$y' = \\dfrac{\\dfrac{1}{\\ln 2} - \\dfrac{\\ln x}{\\ln 2}}{x^2} = \\dfrac{\\dfrac{1 - \\ln x}{\\ln 2}}{x^2} = \\dfrac{1 - \\ln x}{x^2 \\ln 2}.$$  Đối chiếu với biểu thức $y' = \\dfrac{a + b \\ln x}{x^2 \\ln 2}$, ta suy ra:  $\\heva{&a = 1\\\\&b = -1.}$  Vậy $P = a + b = 1 + (-1) = 0$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một máy bay tại độ cao $8$ km bắt đầu hạ độ cao theo quỹ đạo là một phần của parabol. Sau khi di chuyển theo phương ngang $1$ km thì độ cao chỉ còn $6$ km. Máy bay tiếp tục hạ độ cao còn $3$ km sau khi đi được $4$ km theo phương ngang và phóng $1$ tên lửa theo phương tiếp tuyến tại điểm phóng để hướng đến và trúng mục tiêu trên mặt đất. Giả sử rằng quỹ đạo chuyển động của tên lửa là đường thẳng thì mục tiêu cách vị trí phóng tên lửa theo phương ngang là bao nhiêu km?", "choices": ["$8$ km", "$10$ km", "$12$ km", "$16$ km"], "correctIndex": 2, "explain": "Chọn hệ trục tọa độ $Oxy$ như hình vẽ (trục $Oy$ biểu diễn độ cao, trục $Ox$ biểu diễn khoảng cách theo phương ngang, đơn vị là km). Gốc $O$ nằm trên mặt đất.<br>Giả sử quỹ đạo của máy bay là một phần của parabol $(P)\\colon y=ax^2+bx+c$.<br>Dựa vào dữ kiện bài toán, ta có các điểm thuộc $(P)$:<br>a) Tại vị trí bắt đầu hạ cánh: $x=0$, $y=8 \\Rightarrow c=8$.  <br>b) Sau khi đi ngang $1$ km: $x=1$, $y=6 \\Rightarrow a+b+8=6 \\Leftrightarrow a+b=-2$.  <br>c) Sau khi đi ngang $4$ km: $x=4$, $y=3 \\Rightarrow 16a+4b+8=3 \\Leftrightarrow 16a+4b=-5$.<br>Giải hệ phương trình $\\heva{&a+b=-2\\\\&16a+4b=-5}$ ta được $\\heva{&a=\\dfrac{1}{4}\\\\&b=-\\dfrac{9}{4}.}$<br>Vậy phương trình quỹ đạo là $(P)\\colon y=\\dfrac{1}{4}x^2-\\dfrac{9}{4}x+8$.<br>Điểm phóng tên lửa là $M(4;3)$. Ta có đạo hàm $y'=\\dfrac{1}{2}x-\\dfrac{9}{4}$.<br>Hệ số góc của tiếp tuyến tại $M(4;3)$ là $k=y'(4)=\\dfrac{1}{2} \\cdot 4-\\dfrac{9}{4}=-\\dfrac{1}{4}$.<br>Phương trình tiếp tuyến (quỹ đạo tên lửa) tại $M$ là:  $y=-\\dfrac{1}{4}(x-4)+3 \\Leftrightarrow y=-\\dfrac{1}{4}x+4$.<br>Mục tiêu tại mặt đất ứng với $y=0 \\Rightarrow -\\dfrac{1}{4}x+4=0 \\Leftrightarrow x=16$.<br>Khoảng cách từ mục tiêu đến vị trí phóng theo phương ngang là $|16-4|=12$ km.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, scale=0.8, font=\\footnotesize,scale=.8]\n\t\t\t\t\n\t\t\t\t\\draw[->] (-1,0) -- (12,0) node[below] {$x$ (km)};\n\t\t\t\t\\draw[->] (0,-1) -- (0,9) node[left] {$y$ (km)};\n\t\t\t\t\\draw (0,0) node[below left] {$O$};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\draw[thick, blue, samples=100, domain=0:4.5] plot (\\x, {0.25*\\x*\\x - 2.25*\\x + 8});\n\t\t\t\t\\node[blue] at (2,6.5) {Quỹ đạo máy bay};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\filldraw (0,8) circle (2pt) node[left] {$A(0;8)$};\n\t\t\t\t\\filldraw (1,6) circle (2pt) node[above right] {$(1;6)$};\n\t\t\t\t\\filldraw (4,3) circle (2pt) node[above right] {$M(4;3)$};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\draw[thick, red, dashed, domain=4:10] plot (\\x, {-0.25*\\x + 4});\n\t\t\t\t\\draw[->, red, thick] (4,3) -- (10,1.5) node[midway, above right] {Tên lửa};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\draw[dashed] (4,0) -- (4,3) -- (0,3);\n\t\t\t\t\\draw[dashed] (1,0) -- (1,6) -- (0,6);\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\filldraw[red] (11,0.25) node[above] {Mục tiêu};\n\t\t\t\t\\draw[red,->] (11,0.5) -- (12,0);\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\begin{scope}[shift={(0,8)}, scale=0.3]\n\t\t\t\t\t\\draw[fill=gray!50] (-1,0) -- (1,0) -- (0.5,0.5) -- (-0.5,0.5) -- cycle;\n\t\t\t\t\t\\draw (0,0.5) -- (0,1) -- (0.8,0.5);\n\t\t\t\t\\end{scope}\n\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Một nhà máy dự định phối trộn $1000$ kg nguyên liệu từ ba loại thành phần: Ngô ($x$ kg), Đậu nành ($y$ kg) và Phụ gia ($z$ kg). Giá lợi nhuận thu được trên mỗi kg ngô là $5$ nghìn đồng, đậu nành là $6$ nghìn đồng và phụ gia là $10$ nghìn đồng. Do yêu cầu dinh dưỡng, khối lượng ngô phải gấp ít nhất $4$ lần khối lượng đậu nành. Đồng thời, để đảm bảo chất lượng, khối lượng phụ gia sử dụng không được vượt quá $150$ kg.", "cauHoi": [{"question": "Trong mặt phẳng tọa độ $Oxy$, miền nghiệm biểu diễn các giá trị hợp lệ của khối lượng Ngô ($x$) và Đậu nành ($y$) là một phần mặt phẳng có dạng hình gì?", "choices": ["Một hình tam giác", "Một miền đa giác không giới hạn (miền mở)", "Một hình tứ giác", "Một hình ngũ giác"], "correctIndex": 1, "explain": "Từ giả thiết, ta có các điều kiện:<br>a) Tổng khối lượng: $x + y + z = 1000 \\Rightarrow z = 1000 - (x + y)$.  <br>b) Ràng buộc dinh dưỡng: $x \\ge 4y$.  <br>c) Ràng buộc phụ gia: $z \\le 150 \\Rightarrow 1000 - (x + y) \\le 150 \\Leftrightarrow x + y \\ge 850$.  <br>d) Điều kiện thực tế: $x, y \\ge 0$.<br>Hệ bất phương trình bậc nhất hai ẩn là: $\\heva{&x - 4y \\ge 0 \\\\ &x + y \\ge 850 \\\\ &x \\ge 0, y \\ge 0.}$  Miền nghiệm này được giới hạn bởi các đường thẳng nhưng không có điều kiện chặn trên cho tổng $x+y$ (vì $z$ có thể tiến về $0$ hoặc giá trị âm nếu không xét tổng $1000$ cố định, tuy nhiên ở đây $x+y$ có thể rất lớn nếu không xét $z \\ge 0$).   Thực tế, do $z \\ge 0$ nên $x+y \\le 1000$. Nhưng nếu chỉ xét hai điều kiện $x \\ge 4y$ và $x+y \\ge 850$ thì đây là một miền đa giác mở về phía trên bên phải."}, {"question": "Lợi nhuận lớn nhất mà nhà máy có thể thu được từ lô hàng $1000$ kg nguyên liệu này là bao nhiêu?", "choices": ["$5.350$ nghìn đồng", "$5.750$ nghìn đồng", "$5.920$ nghìn đồng", "$6.200$ nghìn đồng"], "correctIndex": 2, "explain": "Hàm lợi nhuận: $F(x,y,z) = 5x + 6y + 10z$.<br>Thay $z = 1000 - x - y$, ta được:  $F(x,y) = 5x + 6y + 10(1000 - x - y) = 10000 - 5x - 4y$.<br>Để $F$ đạt giá trị lớn nhất thì $T = 5x + 4y$ phải đạt giá trị nhỏ nhất.<br>Xét miền nghiệm hệ bất phương trình: $\\heva{&x + y + z = 1000 \\\\ &x \\ge 4y \\\\ &0 \\le z \\le 150 \\\\ &y \\ge 0.}$  Chuyển về $x, y$: $\\heva{&x \\ge 4y \\\\ &850 \\le x + y \\le 1000 \\\\ &y \\ge 0.}$<br>Miền nghiệm là một hình thang với các đỉnh: $A(680; 170), B(800; 200), C(1000; 0), D(850; 0)$.<br>Ta tính $T = 5x + 4y$ tại các đỉnh:<br>- Tại $A(680; 170)$: $T = 5(680) + 4(170) = 4080$.<br>- Tại $B(800; 200)$: $T = 5(800) + 4(200) = 4800$.<br>- Tại $C(1000; 0)$: $T = 5(1000) + 4(0) = 5000$.<br>- Tại $D(850; 0)$: $T = 5(850) + 4(0) = 4250$.<br>Giá trị $T$ nhỏ nhất là $4080$ tại $A$.<br>Lợi nhuận lớn nhất: $F_{max} = 10000 - 4080 = 5920$ (nghìn đồng).<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.01, >=stealth, font=\\footnotesize, line join=round, line cap=round]\n\t\t\t\t\t\\draw[->] (-30,0) -- (300,0) node[below] {$y$};\n\t\t\t\t\t\\draw[->] (0,-30) -- (0,250) node[left] {$z$};\n\t\t\t\t\t\\node at (-10,-10) {$O$};\n\t\t\t\t\t\\coordinate (O) at (0,0);\n\t\t\t\t\t\\coordinate (A) at (200,0);\n\t\t\t\t\t\\coordinate (B) at (170,150);\n\t\t\t\t\t\\coordinate (C) at (0,150);\n\t\t\t\t\t\\fill[green!20] (O) -- (A) -- (B) -- (C) -- cycle;\n\t\t\t\t\t\\draw[thick, blue] (0,150) -- (250,150) node[right] {$z=150$};\n\t\t\t\t\t\\draw[thick, red] (200,0) -- (140,300) node[above] {$5y+z=1000$};\n\t\t\t\t\t\\draw[very thick] (O) -- (A) -- (B) -- (C) -- cycle;\n\t\t\t\t\t\\foreach \\p in {A,B,C} \\fill (\\p) circle (100pt);\n\t\t\t\t\t\\node[below] at (200,0) {$200$};\n\t\t\t\t\t\\node[left] at (0,150) {$150$};\n\t\t\t\t\t\\node[above right] at (170,150) {$B(170;150)$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Trong một cộng đồng, tỉ lệ người mắc bệnh $X$ là $0{,}1\\%$. Để phát hiện bệnh, người ta sử dụng một loại xét nghiệm có độ chính xác như sau: Nếu một người mắc bệnh, xác suất xét nghiệm cho kết quả dương tính là $99\\%$; nếu một người không mắc bệnh, xác suất xét nghiệm cho kết quả dương tính (dương tính giả) là $1\\%$. Một người được chọn ngẫu nhiên trong cộng đồng và làm xét nghiệm.", "cauHoi": [{"question": "Xác suất để một người được chọn ngẫu nhiên có kết quả xét nghiệm dương tính là bao nhiêu?", "choices": ["$0{,}01000$", "$0{,}01098$", "$0{,}01099$", "$0{,}00999$"], "correctIndex": 1, "explain": "Gọi $B$ là biến cố người được chọn mắc bệnh $X$, khi đó $P(B)=0{,}001$ và $P(\\overline{B})=0{,}999$.<br>Gọi $T$ là biến cố kết quả xét nghiệm dương tính. Theo giả thiết:<br>$P(T|B)=0{,}99$ và $P(T|\\overline{B})=0{,}01$.<br>Áp dụng công thức xác suất đầy đủ:  $P(T)=P(B) \\cdot P(T|B)+P(\\overline{B}) \\cdot P(T|\\overline{B}) = 0{,}001 \\cdot 0{,}99+0{,}999 \\cdot 0{,}01 = 0{,}00099+0{,}00999 = 0{,}01098$."}, {"question": "Giả sử người này có kết quả xét nghiệm lần thứ nhất là dương tính. Để chắc chắn, người đó làm tiếp xét nghiệm lần thứ hai (giả sử kết quả lần hai độc lập với lần một). Nếu kết quả lần hai vẫn là dương tính, xác suất người này thực sự mắc bệnh $X$ là bao nhiêu (làm tròn đến $4$ chữ số thập phân)?", "choices": ["$0{,}0902$", "$0{,}5000$", "$0{,}8910$", "$0{,}9083$"], "correctIndex": 3, "explain": "Gọi $T_1$, $T_2$ lần lượt là biến cố kết quả xét nghiệm dương tính lần $1$ và lần $2$.<br>Ta cần tính xác suất $P(B|T_1 \\cap T_2)$.<br>Vì hai lần xét nghiệm độc lập đối với tình trạng bệnh của bệnh nhân, ta có:<br>$P(T_1 \\cap T_2|B) = P(T_1|B) \\cdot P(T_2|B) = (0{,}99)^2 = 0{,}9801$.<br>$P(T_1 \\cap T_2|\\overline{B}) = P(T_1|\\overline{B}) \\cdot P(T_2|\\overline{B}) = (0{,}01)^2 = 0{,}0001$.<br>Áp dụng công thức Bayes cho hai biến cố:  $P(B|T_1 \\cap T_2) = \\dfrac{P(B) \\cdot P(T_1 \\cap T_2|B)}{P(B) \\cdot P(T_1 \\cap T_2|B) + P(\\overline{B}) \\cdot P(T_1 \\cap T_2|\\overline{B})}$.<br>Thay số vào:  $P(B|T_1 \\cap T_2) = \\dfrac{0{,}001 \\cdot 0{,}9801}{0{,}001 \\cdot 0{,}9801 + 0{,}999 \\cdot 0{,}0001} = \\dfrac{0{,}0009801}{0{,}0009801 + 0{,}0000999} = \\dfrac{0{,}0009801}{0{,}00108}$.<br>$P(B|T_1 \\cap T_2) \\approx 0{,}9083$."}]}, {"noiDungChung": "Trong không gian với hệ tọa độ $Oxyz$, cho các điểm $A(2;0;0)$, $B(0;4;0)$ và $C(0;0;4)$. Gọi $M$ là trung điểm của cạnh $BC$ và $G$ là trọng tâm tam giác $ABC$.", "cauHoi": [{"question": "Tính diện tích $S$ của tam giác $ABC$.", "choices": ["$S=6$", "$S=6\\sqrt{2}$", "$S=4\\sqrt{6}$", "$S=12\\sqrt{2}$"], "correctIndex": 2, "explain": "Ta có $\\overrightarrow{AB}=(-2;4;0)$ và $\\overrightarrow{AC}=(-2;0;4)$.<br>Tích có hướng $[\\overrightarrow{AB}, \\overrightarrow{AC}] = \\left( \\begin{vmatrix} 4 & 0 \\\\ 0 & 4 \\end{vmatrix}; \\begin{vmatrix} 0 & -2 \\\\ 4 & -2 \\end{vmatrix}; \\begin{vmatrix} -2 & 4 \\\\ -2 & 0 \\end{vmatrix} \\right) = (16; 8; 8)$.<br>Diện tích tam giác $ABC$ là: $S = \\dfrac{1}{2} |[\\overrightarrow{AB}, \\overrightarrow{AC}]| = \\dfrac{1}{2}\\sqrt{16^2+8^2+8^2} = \\dfrac{1}{2}\\sqrt{384} = \\dfrac{1}{2} \\cdot 8\\sqrt{6} = 4\\sqrt{6}$."}, {"question": "Tìm tọa độ điểm $D$ sao cho tứ diện $ABCD$ có trọng tâm là gốc tọa độ $O$.", "choices": ["$D(2;4;4)$", "$D(-2;4;4)$", "$D(2;-4;-4)$", "$D(-2;-4;-4)$"], "correctIndex": 3, "explain": "Tọa độ trọng tâm $G_{tứ diện}$ của tứ diện $ABCD$ được tính bởi công thức:  $x_O = \\dfrac{x_A+x_B+x_C+x_D}{4} \\Rightarrow x_D = 4x_O - (x_A+x_B+x_C)$.<br>Tương tự cho $y_D$ và $z_D$.<br>Vì $O$ là gốc tọa độ nên $x_O=y_O=z_O=0$.<br>Ta có $\\heva{&x_D = 0 - (2+0+0) = -2\\\\&y_D = 0 - (0+4+0) = -4\\\\&z_D = 0 - (0+0+4) = -4.}$<br>Vậy $D(-2;-4;-4)$."}, {"question": "Tìm tọa độ điểm $S$ nằm trên trục $Ox$ sao cho tổng bình phương khoảng cách từ $S$ đến các đỉnh của tam giác $ABC$ đạt giá trị nhỏ nhất. Tính giá trị nhỏ nhất $P_{\\min}$ đó.", "choices": ["$P_{\\min}=\\dfrac{104}{3}$", "$P_{\\min}=\\dfrac{32}{3}$", "$P_{\\min}=32$", "$P_{\\min}=36$"], "correctIndex": 0, "explain": "Đặt $P=SA^2+SB^2+SC^2$. Theo tính chất trọng tâm, ta có:  $P=3SG^2+(GA^2+GB^2+GC^2)$.<br>Vì $(GA^2+GB^2+GC^2)$ là hằng số nên $P$ nhỏ nhất khi $SG$ nhỏ nhất.<br>Vì $S \\in Ox$ nên $S$ là hình chiếu vuông góc của $G$ lên trục $Ox \\Rightarrow S\\left(\\dfrac{2}{3};0;0\\right)$.<br>Tính giá trị nhỏ nhất:  $SA^2 = \\left(2-\\dfrac{2}{3}\\right)^2+0^2+0^2 = \\dfrac{16}{9}$.<br>$SB^2 = \\left(0-\\dfrac{2}{3}\\right)^2+(4-0)^2+0^2 = \\dfrac{4}{9}+16 = \\dfrac{148}{9}$.<br>$SC^2 = \\left(0-\\dfrac{2}{3}\\right)^2+0^2+(4-0)^2 = \\dfrac{4}{9}+16 = \\dfrac{148}{9}$.<br>Vậy $P_{\\min} = \\dfrac{16+148+148}{9} = \\dfrac{312}{9} = \\dfrac{104}{3}$."}]}, {"noiDungChung": "Cho hình lăng trụ tam giác $ABC.A'B'C'$ có đáy $ABC$ là tam giác đều cạnh $a$. Hình chiếu vuông góc của đỉnh $A'$ lên mặt phẳng $(ABC)$ trùng với trọng tâm $G$ của tam giác $ABC$. Biết góc giữa hai mặt phẳng $(AA'B'B)$ và $(ABC)$ bằng $60^\\circ$.", "cauHoi": [{"question": "Tính cosin góc $\\alpha$ giữa đường thẳng $AA'$ và mặt phẳng $(ABC)$", "choices": ["$\\dfrac{\\sqrt{3}}{2}$", "$\\dfrac{\\sqrt{3}}{4}$", "$\\dfrac{2}{\\sqrt{7}}$", "$\\dfrac{\\sqrt{7}}{2}$"], "correctIndex": 2, "explain": "Gọi $M$ là trung điểm $AB$. Vì $\\triangle ABC$ đều nên $CM \\perp AB$ và $CM = \\dfrac{a\\sqrt{3}}{2}$.<br>$G$ là trọng tâm nên $MG = \\dfrac{1}{3}MC = \\dfrac{a\\sqrt{3}}{6}$ và $AG = \\dfrac{2}{3}MC = \\dfrac{a\\sqrt{3}}{3}$.<br>Vì $A'G \\perp (ABC)$ nên $AB \\perp A'G$, mà $AB \\perp MG \\Rightarrow AB \\perp (A'MG) \\Rightarrow AB \\perp A'M$.<br>Góc giữa $(AA'B'B)$ và $(ABC)$ là $\\widehat{A'MG} = 60^\\circ$.<br>Trong $\\triangle A'GM$ vuông tại $G$: $A'G = MG \\cdot \\tan 60^\\circ = \\dfrac{a\\sqrt{3}}{6} \\cdot \\sqrt{3} = \\dfrac{a}{2}$.<br>Góc giữa $AA'$ và $(ABC)$ là $\\widehat{A'AG} = \\alpha$.<br>Trong $\\triangle A'GA$ vuông tại $G$: $\\tan\\alpha = \\dfrac{A'G}{AG} = \\dfrac{a/2}{a\\sqrt{3}/3} = \\dfrac{3}{2\\sqrt{3}} = \\dfrac{\\sqrt{3}}{2}$.<br>Ta có $1+\\tan^2\\alpha=\\dfrac{1}{\\cos^2\\alpha}$  $\\Rightarrow \\dfrac{1}{\\cos^2\\alpha}=1+\\left(\\dfrac{\\sqrt{3}}{2}\\right)^2=1+\\dfrac{3}{4}=\\dfrac{7}{4}$<br>$\\Rightarrow \\cos^2\\alpha=\\dfrac{4}{7} \\Rightarrow \\cos\\alpha=\\dfrac{2}{\\sqrt{7}}=\\dfrac{2\\sqrt{7}}{7}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, font=\\footnotesize, line join=round, line cap=round]\n\t\t\t\t\t\n\t\t\t\t\t\\path (0,0) coordinate (A)\n\t\t\t\t\t(4,0) coordinate (B)\n\t\t\t\t\t(1.5,-1.5) coordinate (C);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (G) at ($(A)!1/3!(B)!1/3!(C)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (A') at ($(G)+(0,4)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (B') at ($(B)+(A')-(A)$);\n\t\t\t\t\t\\coordinate (C') at ($(C)+(A')-(A)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (M) at ($(A)!0.5!(B)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw [dashed] (A)--(B) (G)--(A') (C)--(M) (G)--(M) (A')--(M);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw (A)--(C)--(B) (A')--(B')--(C')--cycle;\n\t\t\t\t\t\\draw (A)--(A') (B)--(B') (C)--(C');\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw (G)++(0,0.2)--++(0.2,0)--++(0,-0.2);\n\t\t\t\t\t\\draw (M)++(0.1,0.05) node[right]{$60^\\circ$};\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\foreach \\p/\\pos in {A/left, B/right, C/below, G/below, A'/above, B'/above, C'/above, M/above left}\n\t\t\t\t\t\\fill (\\p) circle (1pt) node[\\pos] {$\\p$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Tính thể tích $V$ của khối lăng trụ $ABC.A'B'C'$", "choices": ["$V=\\dfrac{a^3\\sqrt{3}}{4}$", "$V=\\dfrac{a^3\\sqrt{3}}{24}$", "$V=\\dfrac{a^3\\sqrt{3}}{8}$", "$V=\\dfrac{a^3}{8}$"], "correctIndex": 2, "explain": "Diện tích đáy $S_{ABC} = \\dfrac{a^2\\sqrt{3}}{4}$.<br>Chiều cao lăng trụ $h = A'G = \\dfrac{a}{2}$.<br>Thể tích khối lăng trụ $V = S_{ABC} \\cdot h = \\dfrac{a^2\\sqrt{3}}{4} \\cdot \\dfrac{a}{2} = \\dfrac{a^3\\sqrt{3}}{8}$."}, {"question": "Tính khoảng cách $d$ từ điểm $B$ đến mặt phẳng $(A'BC')$", "choices": ["$d=\\dfrac{a\\sqrt{21}}{7}$", "$d=\\dfrac{3a}{\\sqrt{31}}$", "$d=\\dfrac{a\\sqrt{3}}{4}$", "$d=\\dfrac{a}{2}$"], "correctIndex": 1, "explain": "Ta có $V_{B.A'BC'} = V_{C'.A'BC} = V_{A'.ABC} = \\dfrac{1}{3} \\cdot \\dfrac{a^3\\sqrt{3}}{8} = \\dfrac{a^3\\sqrt{3}}{24}$.<br>Xét tam giác $A'BC'$ có $BC' = \\sqrt{BC^2 + CC'^2} = \\sqrt{a^2 + (AA')^2}$.<br>Với $AA' = \\sqrt{A'G^2 + AG^2} = \\sqrt{\\left(\\dfrac{a}{2}\\right)^2 + \\left(\\dfrac{a\\sqrt{3}}{3}\\right)^2} = \\dfrac{a\\sqrt{21}}{6}$.<br>Tính diện tích $S_{A'BC'}$ và suy ra $d(B,(A'BC')) = \\dfrac{3V_{B.A'BC'}}{S_{A'BC'}} = \\dfrac{3a}{\\sqrt{31}}$."}]}, {"noiDungChung": "Ba bạn An, Bình, và Chi tham gia ba câu lạc bộ (CLB) khác nhau: Âm nhạc, Bóng đá, và Hội họa. Mỗi người sống ở một quận khác nhau: Quận 1, Quận 3, và Quận 5. Biết rằng Bình không học Hội họa; Người sống ở Quận 1 học Âm nhạc; An sống ở Quận 5; Chi không sống ở Quận 1.", "cauHoi": [{"question": "Khẳng định nào sau đây là <b>chắc chắn đúng</b>?", "choices": ["An tham gia câu lạc bộ Âm nhạc", "Chi sống ở Quận 5", "Bình sống ở Quận 1 và học Âm nhạc", "Chi học Hội họa"], "correctIndex": 2, "explain": "- An ở Quận 5 (GT).<br>- Chi không ở Quận 1 (GT) nên Chi chỉ có thể ở Quận 3 hoặc Quận 5. Vì An đã ở Quận 5 nên Chi ở Quận 3.<br>- Do đó, Bình là người duy nhất còn lại sống ở Quận 1.<br>- Theo dữ kiện, người ở Quận 1 học Âm nhạc. Vậy Bình sống ở Quận 1 và học Âm nhạc là chắc chắn đúng."}, {"question": "Dựa trên các dữ kiện đã cho, khẳng định nào sau đây là <b>có thể đúng</b>?", "choices": ["Bình tham gia câu lạc bộ Bóng đá", "An sống ở Quận 1", "Người sống ở Quận 3 tham gia câu lạc bộ Âm nhạc", "Chi tham gia câu lạc bộ Hội họa"], "correctIndex": 3, "explain": "- Ta đã xác định được: Bình (Q1 - Âm nhạc), An (Q5), Chi (Q3).<br>- Còn lại CLB Bóng đá và Hội họa. Vì không có thêm dữ kiện để phân biệt sở thích của An và Chi, nên việc Chi học Hội họa là một khả năng <b>có thể xảy ra</b> (nhưng không chắc chắn 100\\% vì Chi cũng có thể học Bóng đá)."}, {"question": "Nếu có thêm thông tin: “Người sống ở Quận 3 không thích thể thao”, hãy <b>sắp xếp</b> đúng tên CLB của các bạn theo thứ tự <b>An - Bình - Chi</b>.", "choices": ["Bóng đá - Âm nhạc - Hội họa", "Hội họa - Âm nhạc - Bóng đá", "Âm nhạc - Bóng đá - Hội họa", "Bóng đá - Hội họa - Âm nhạc"], "correctIndex": 0, "explain": "- Đã biết: Bình (Âm nhạc), Chi (Quận 3), An (Quận 5).<br>- Thông tin bổ sung: Người ở Quận 3 (Chi) không thích thể thao $\\Rightarrow$ Chi không học Bóng đá.<br>- Vậy Chi phải học Hội họa.<br>- CLB cuối cùng là Bóng đá dành cho An.<br>- Thứ tự An - Bình - Chi là: Bóng đá - Âm nhạc - Hội họa."}]}, {"noiDungChung": "Trong một phòng phân tích di truyền, có $4$ thiết bị xét nghiệm ký hiệu là $M$, $N$, $P$, $Q$ được đặt vào một hệ thống giá đỡ gồm $5$ vị trí liên tiếp được đánh số từ $1$ đến $5$ (từ trái sang phải). Mỗi vị trí chỉ chứa tối đa một thiết bị và có một vị trí sẽ để trống. Quy tắc sắp xếp như sau: <br>a) Thiết bị $M$ và $N$ phải được đặt cạnh nhau để kết nối dây tín hiệu ngắn.  <br>b) Thiết bị $P$ không được đặt ở vị trí số $1$ hoặc số $5$.  <br>c) Vị trí trống không được nằm ở hai đầu giá đỡ.  <br>d) Thiết bị $Q$ phải nằm ở vị trí có số thứ tự lớn hơn vị trí của $P$.", "cauHoi": [{"question": "Nếu vị trí số $2$ để trống, thiết bị nào sau đây chắc chắn nằm ở vị trí số $1$?", "choices": ["$P$", "$Q$", "$M$ hoặc $N$", "Không có thiết bị nào"], "correctIndex": 2, "explain": "Nếu vị trí $2$ trống:<br>- Vị trí $1$ phải có thiết bị (vì vị trí trống không ở đầu hàng theo dữ kiện 3).<br>- $P$ không ở $1$ (dữ kiện 2).<br>- $Q$ phải có số thứ tự lớn hơn $P$ (dữ kiện 4), nên nếu $Q$ ở $1$ thì không có chỗ cho $P$ (loại).<br>- Vậy vị trí $1$ chỉ có thể là $M$ hoặc $N$. Do $M, N$ cạnh nhau, nếu $M$ ở $1$ thì $N$ phải ở $2$, nhưng $2$ trống. Điều này dẫn tới một mâu thuẫn logic trong kịch bản vị trí $2$ trống. Tuy nhiên, xét theo các lựa chọn loại trừ cho vị trí $1$, chỉ có $M$ hoặc $N$ là ứng cử viên duy nhất."}, {"question": "Nếu thiết bị $P$ ở vị trí số $2$ và $Q$ ở vị trí số $5$, cặp thiết bị $M, N$ có thể nằm ở những vị trí nào?", "choices": ["$1$ và $2$", "$3$ và $4$", "$4$ và $5$", "$1$ và $3$"], "correctIndex": 1, "explain": "- $P$ ở $2$, $Q$ ở $5$. Các vị trí còn lại là $1, 3, 4$.<br>- Vị trí trống không ở $1$ và $5$, vậy vị trí trống phải là $3$ hoặc $4$.<br>- Nếu vị trí $3$ trống, thì $M, N$ phải ở $1$ và $4$ (không cạnh nhau, loại).<br>- Nếu vị trí $4$ trống, thì $M, N$ phải ở $1$ và $3$ (không cạnh nhau, loại).<br>- Xét lại: Nếu $M, N$ ở $3, 4$ thì vị trí trống là $1$ (vi phạm dữ kiện 3). <br>Để thỏa mãn $M, N$ cạnh nhau và trống không ở đầu, chỉ có thể xếp $M, N$ vào $\\{3, 4\\}$ và vị trí $1$ dành cho thiết bị còn lại, vị trí trống phải là $2$ nhưng $P$ đã ở đó. Vậy với $P(2)$ và $Q(5)$, phương án duy nhất là $M, N$ ở $\\{3, 4\\}$ và vị trí trống là một trong các số giữa."}, {"question": "Có ít nhất bao nhiêu vị trí mà thiết bị $P$ có thể đặt vào để luôn đảm bảo tồn tại một cách xếp thỏa mãn tất cả các quy tắc?", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 1, "explain": "- Theo dữ kiện (2), $P \\notin \\{1, 5\\} \\Rightarrow P \\in \\{2, 3, 4\\}$.<br>- Theo dữ kiện (4), $Q > P$. Nếu $P=4$, thì $Q=5$. Khi đó các vị trí còn lại là $1, 2, 3$. Để $M, N$ cạnh nhau, họ ở $\\{1, 2\\}$ hoặc $\\{2, 3\\}$. Vị trí trống sẽ là $3$ hoặc $1$. Nhưng trống không ở đầu nên trống là $3$ hoặc $2$.<br>- Nếu $P=2$, $Q \\in \\{3, 4, 5\\}$. Tương tự ta tìm được các cấu hình cho $M, N$ và vị trí trống.<br>- Nếu $P=3$, $Q \\in \\{4, 5\\}$.<br>Tổng cộng, $P$ có thể ở vị trí $2$ hoặc $3$ để đảm bảo luôn có khoảng trống không nằm ở đầu và $M, N$ được đứng cạnh nhau."}]}, {"noiDungChung": "Biểu đồ đoạn thẳng dưới đây thống kê doanh thu (đơn vị: tỷ đồng) của một công ty phần mềm trong các năm từ $2020$ đến $2024$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, font=\\footnotesize, line join=round, line cap=round]\n\t\t\t\n\t\t\t\\draw[->] (0,0) -- (6,0) node[below]{Năm};\n\t\t\t\\draw[->] (0,0) -- (0,5.5) node[left]{Doanh thu};\n\t\t\t\n\t\t\t\\draw[thick, blue, mark=*] (1,2) coordinate (2020) -- (2,1.5) coordinate (2021) -- (3,3.5) coordinate (2022) -- (4,4.5) coordinate (2023) -- (5,5) coordinate (2024);\n\t\t\t\n\t\t\t\\foreach \\x/\\y in {1/2020, 2/2021, 3/2022, 4/2023, 5/2024} \\node[below] at (\\x,0) {\\y};\n\t\t\t\n\t\t\t\\node[above left] at (2020) {$10$};\n\t\t\t\\node[below] at (2021) {$7{,}5$};\n\t\t\t\\node[above left] at (2022) {$17{,}5$};\n\t\t\t\\node[above] at (2023) {$22{,}5$};\n\t\t\t\\node[right] at (2024) {$25$};\n\t\t\t\n\t\t\t\\draw[dashed, gray!30] (0,2)--(1,2) (0,1.5)--(2,1.5) (0,3.5)--(3,3.5) (0,4.5)--(4,4.5) (0,5)--(5,5);\n\t\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Giai đoạn nào dưới đây doanh thu của công ty có xu hướng giảm?", "choices": ["Từ năm $2021$ đến $2022$", "Từ năm $2020$ đến $2021$", "Từ năm $2022$ đến $2024$", "Không có giai đoạn nào giảm"], "correctIndex": 1, "explain": "Dựa vào biểu đồ, đoạn thẳng nối từ năm $2020$ ($10$ tỷ) đến năm $2021$ ($7{,}5$ tỷ) đi xuống. Do đó, doanh thu giảm trong giai đoạn này."}, {"question": "Tốc độ tăng trưởng doanh thu của năm $2022$ so với năm $2021$ là bao nhiêu?", "choices": ["$100\\%$", "$125\\%$", "$133{,}33\\%$", "$57{,}14\\%$"], "correctIndex": 2, "explain": "Doanh thu năm $2021$ là $7{,}5$ tỷ, doanh thu năm $2022$ là $17{,}5$ tỷ.  Tốc độ tăng trưởng là: $\\dfrac{17{,}5-7{,}5}{7{,}5} \\cdot 100\\% = \\dfrac{10}{7{,}5} \\cdot 100\\% \\approx 133{,}33\\%$."}, {"question": "Nếu mục tiêu doanh thu năm $2025$ là phải đạt mức tăng tuyệt đối bằng mức tăng trung bình của giai đoạn từ $2021$ đến $2024$, thì doanh thu năm $2025$ cần đạt bao nhiêu?", "choices": ["$28{,}5$ tỷ đồng", "$30{,}83$ tỷ đồng", "$29{,}17$ tỷ đồng", "$32$ tỷ đồng"], "correctIndex": 1, "explain": "Mức tăng tuyệt đối trung bình mỗi năm trong giai đoạn $2021-2024$ là:  $$\\dfrac{25 - 7{,}5}{3} = \\dfrac{17{,}5}{3} \\approx 5{,}83\\text{ (tỷ đồng/năm).}$$  Vậy doanh thu dự kiến năm $2025$ là: $25 + 5{,}83 = 30{,}83$ tỷ đồng."}]}, {"noiDungChung": "Để chuẩn bị cho kỳ thi đánh giá năng lực, một giáo viên chủ nhiệm đã khảo sát thời gian tự học thêm tại nhà trong một ngày của $40$ học sinh trong lớp. Kết quả được trình bày trong bảng tần số ghép nhóm sau:<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Thời gian (giờ)</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[0; 2)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[2; 4)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[4; 6)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[6; 8)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[8; 10)$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Số học sinh ($n_i$)</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$4$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$12$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$14$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$8$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$2$</td></tr></table>", "cauHoi": [{"question": "Mệnh đề nào sau đây là đúng?", "choices": ["$[2; 4)$, đây là nhóm có thời gian học ít nhất", "$[4; 6)$, đây là khoảng thời gian học phổ biến nhất của học sinh trong lớp", "$[4; 6)$, đây là nhóm có thời gian học cao nhất", "$[2; 4)$, đây là khoảng thời gian học trung bình của cả lớp"], "correctIndex": 1, "explain": "Mốt của mẫu số liệu ghép nhóm nằm ở nhóm có tần số lớn nhất. Trong bảng trên, tần số lớn nhất là $14$, tương ứng với nhóm thời gian $[4; 6)$. Trong thực tế, mốt đại diện cho giá trị có khả năng xuất hiện cao nhất, tức là đa số học sinh trong lớp dành khoảng $4$ đến $6$ giờ để tự học."}, {"question": "Giả sử nhà trường yêu cầu khen thưởng những học sinh thuộc nhóm $25\\%$ có thời gian tự học cao nhất lớp. Một học sinh cần học ít nhất bao nhiêu giờ (làm tròn đến hai chữ số thập phân) để nằm trong danh sách khen thưởng này?", "choices": ["$6{,}00$ giờ", "$6{,}25$ giờ", "$6{,}50$ giờ", "$7{,}15$ giờ"], "correctIndex": 0, "explain": "Học sinh thuộc nhóm $25\\%$ có thời gian học cao nhất tương ứng với việc xác định tứ phân vị thứ ba $Q_3$ (vì $75\\%$ học sinh có thời gian học thấp hơn giá trị này).<br>Tổng số học sinh $n = 40$. Vị trí của $Q_3$ là $\\dfrac{3n}{4} = \\dfrac{3 \\cdot 40}{4} = 30$.<br>Ta có bảng tần số tích lũy:<br>- Nhóm $[0; 2)$: $4$.<br>- Nhóm $[2; 4)$: $4 + 12 = 16$.<br>- Nhóm $[4; 6)$: $16 + 14 = 30$.<br>- Nhóm $[6; 8)$: $30 + 8 = 38$.<br>Vì tần số tích lũy của nhóm $[4; 6)$ vừa bằng $30$, nên $Q_3$ chính là đầu mút phải của nhóm này, hoặc áp dụng công thức:  $Q_3 = 6 + \\dfrac{30 - 30}{8} \\cdot 2 = 6{,}00$."}, {"question": "Để đánh giá sự đồng đều về thời gian tự học giữa các học sinh, giáo viên tính độ lệch chuẩn $s$. Khẳng định nào sau đây về độ phân tán là đúng (làm tròn kết quả đến chữ số thập phân thứ hai)?", "choices": ["$s \\approx 2{,}42$, mức độ chênh lệch thời gian học giữa các học sinh là rất nhỏ", "$s \\approx 2{,}06$, mức độ chênh lệch thời gian học giữa các học sinh là tương đối rõ rệt", "$s \\approx 4{,}24$, dữ liệu tập trung rất sát số trung bình", "$s \\approx 1{,}85$, tất cả học sinh đều có thời gian học gần bằng nhau"], "correctIndex": 1, "explain": "Tính phương sai $s^2$:  $\\sum n_i x_i^2 = 4 \\cdot 1^2 + 12 \\cdot 3^2 + 14 \\cdot 5^2 + 8 \\cdot 7^2 + 2 \\cdot 9^2 = 4 + 108 + 350 + 392 + 162 = 1016$.<br>$s^2 = \\dfrac{1016}{40} - (4{,}6)^2 = 25{,}4 - 21{,}16 = 4{,}24$.<br>Độ lệch chuẩn: $s = \\sqrt{4{,}24} \\approx 2{,}06$.<br>Vì độ lệch chuẩn khác $0$ đáng kể nên thời gian học của các học sinh có sự phân hóa rõ rệt."}]}]}, {"id": "extra-8", "ten": "Đề luyện tập số 14", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Cho cấp số cộng $(u_n)$ có tổng $n$ số hạng đầu tiên được tính bởi công thức $S_n=2n^2-3n$. Giá trị của số hạng thứ $5$ trong cấp số cộng này bằng", "choices": ["$35$", "$15$", "$20$", "$25$"], "correctIndex": 1, "explain": "Để tìm số hạng thứ $5$ ($u_5$) khi biết công thức tổng $n$ số hạng đầu tiên ($S_n$), ta sử dụng mối liên hệ giữa số hạng và tổng tích lũy:<br>Ta có công thức: $u_n=S_n-S_{n-1}$ (với $n \\ge 2$).<br>Áp dụng cho số hạng thứ $5$: $u_5=S_5-S_4$.<br>$\\bullet$ Tính $S_5$: $S_5=2 \\cdot 5^2-3 \\cdot 5=50-15=35$.<br>$\\bullet$ Tính $S_4$: $S_4=2 \\cdot 4^2-3 \\cdot 4=32-12=20$.<br>Vậy giá trị của số hạng thứ $5$ là: $u_5=35-20=15$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho dãy số $(u_n)$ có giới hạn được xác định bởi biểu thức $\\lim\\limits\\dfrac{(2m-1)n^3+n^2+1}{n^3+2n-3}=4$, trong đó $m$ là tham số thực. Giá trị của tham số $m$ thuộc khoảng nào sau đây?", "choices": ["$(0;2)$", "$(3;4)$", "$(-1;1)$", "$(2;3)$"], "correctIndex": 3, "explain": "Ta thực hiện tính giới hạn của dãy số bằng cách chia cả tử và mẫu cho lũy thừa cao nhất của $n$ là $n^3$:  $$L=\\lim\\limits\\dfrac{n^3\\left(2m-1+\\dfrac{1}{n}+\\dfrac{1}{n^3}\\right)}{n^3\\left(1+\\dfrac{2}{n^2}-\\dfrac{3}{n^3}\\right)}=\\lim\\limits\\dfrac{2m-1+\\dfrac{1}{n}+\\dfrac{1}{n^3}}{1+\\dfrac{2}{n^2}-\\dfrac{3}{n^3}}$$  Vì $\\lim\\limits\\dfrac{1}{n}=\\lim\\limits\\dfrac{1}{n^2}=\\lim\\limits\\dfrac{1}{n^3}=0$ nên ta có:  $$L=\\dfrac{2m-1+0+0}{1+0-0}=2m-1$$  Theo giả thiết bài toán, giới hạn này bằng $4$, ta có phương trình:  $$2m-1=4 \\Leftrightarrow 2m=5 \\Leftrightarrow m=\\dfrac{5}{2}=2{,}5$$  Vì $2{,}5 \\in (2;3)$ nên phương án đúng là $(2;3)$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tính thể tích $V$ của khối tròn xoay tạo thành khi quay hình phẳng giới hạn bởi đường cong $y=\\sqrt{4-x^2}$ và trục $Ox$ quanh trục $Ox$.", "choices": ["$V=\\dfrac{16\\pi}{3}$", "$V=\\dfrac{32\\pi}{3}$", "$V=8\\pi$", "$V=\\dfrac{20\\pi}{3}$"], "correctIndex": 1, "explain": "Phương trình hoành độ giao điểm của đường cong $y=\\sqrt{4-x^2}$ và trục $Ox$ là:  $\\sqrt{4-x^2}=0 \\Leftrightarrow 4-x^2=0 \\Leftrightarrow \\hoac{&x=2\\\\&x=-2}$.<br>Thể tích khối tròn xoay tạo thành là:  $V=\\pi\\displaystyle\\int\\limits_{-2}^{2}\\left(\\sqrt{4-x^2}\\right)^2dx=\\pi\\displaystyle\\int\\limits_{-2}^{2}(4-x^2)dx$.<br>$V=\\pi\\left[4x-\\dfrac{x^3}{3}\\right]\\bigg|_{-2}^{2}=\\pi\\left[\\left(4 \\cdot 2-\\dfrac{2^3}{3}\\right)-\\left(4 \\cdot (-2)-\\dfrac{(-3)^3}{3}\\right)\\right]$.<br>$V=\\pi\\left[\\left(8-\\dfrac{8}{3}\\right)-\\left(-8+\\dfrac{8}{3}\\right)\\right]=\\pi\\left(\\dfrac{16}{3}+\\dfrac{16}{3}\\right)=\\dfrac{32\\pi}{3}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Số thập phân vô hạn tuần hoàn $0{,}1212\\dots$ được biểu diễn dưới dạng phân số tối giản $\\dfrac{a}{b}$. Tính $a+b$.", "choices": ["$28$", "$2803$", "$37$", "$1121$"], "correctIndex": 2, "explain": "Ta có $0{,}1212\\dots = 0{,}12+0{,}0012+0{,}000012+\\dots = \\dfrac{12}{10^2}+\\dfrac{12}{10^4}+\\dfrac{12}{10^6}+\\dots$  Đây là tổng của một cấp số nhân lùi vô hạn với số hạng đầu $u_1=\\dfrac{12}{100}$ và công bội $q=\\dfrac{1}{100}$.  Tổng của cấp số nhân này là: $S = \\dfrac{u_1}{1-q} = \\dfrac{\\dfrac{12}{100}}{1-\\dfrac{1}{100}} = \\dfrac{\\dfrac{12}{100}}{\\dfrac{99}{100}} = \\dfrac{12}{99} = \\dfrac{4}{33}$.  Vì $\\dfrac{a}{b}$ là phân số tối giản nên $a=4$, $b=33$.  Vậy $a+b=4+33=37$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ có diện tích $S$. Nếu tăng độ dài mỗi cạnh $BC$ và $AC$ lên $2$ lần đồng thời giữ nguyên độ lớn của góc $C$ thì diện tích của tam giác mới được tạo nên bằng", "choices": ["$2S$", "$3S$", "$5S$", "$4S$"], "correctIndex": 3, "explain": "Diện tích tam giác $ABC$ ban đầu là: $S = \\dfrac{1}{2}ac\\sin C = \\dfrac{1}{2}ab\\sin C$. (Trong đó $a=BC$, $b=AC$).<br>Khi tăng độ dài mỗi cạnh $BC$ và $AC$ lên $2$ lần, ta có các cạnh mới là $a' = 2a$ và $b' = 2b$.<br>Diện tích tam giác mới là:  $S' = \\dfrac{1}{2}a'b'\\sin C = \\dfrac{1}{2}(2a)(2b)\\sin C = 4 \\cdot \\left(\\dfrac{1}{2}ab\\sin C\\right) = 4S$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Bất phương trình $\\dfrac{x^2-3x+2}{x-3} \\ge 0$ có bao nhiêu nghiệm nguyên thuộc đoạn $[-5; 5]$?", "choices": ["$3$", "$4$", "$5$", "$6$"], "correctIndex": 1, "explain": "Xét $f(x)=\\dfrac{x^2-3x+2}{x-3}$.<br>Tử thức $x^2-3x+2=0 \\Leftrightarrow \\hoac{&x=1\\\\&x=2}$.<br>Mẫu thức $x-3=0 \\Leftrightarrow x=3$.<br>Bảng xét dấu:<br>Để $f(x) \\ge 0$ thì $x \\in [1; 2] \\cup (3; +\\infty)$.<br>Kết hợp điều kiện $x \\in [-5; 5]$ và $x \\in \\mathbb{Z}$, ta có $x \\in \\{1, 2, 4, 5\\}$.<br>Vậy có $4$ nghiệm nguyên thỏa mãn.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hàm số $f(x)=\\left\\{\\begin{array}{ll}(x+1)^2 & \\text { khi } x>1 \\\\ x^2+3 & \\text { khi } x<1 \\\\ k^2 & \\text { khi } x=1\\end{array}\\right.$. Có bao nhiêu số nguyên $k$ để $f(x)$ liên tục tại $x=1$.", "choices": ["$1$", "$0$", "$2$", "$3$"], "correctIndex": 2, "explain": "Ta có: $f(1)=k^2$<br>Mặt khác $\\lim _{x \\rightarrow 1^{-}} f(x)=\\lim _{x \\rightarrow 1^{-}}\\left(x^2+3\\right)=4 ; \\lim _{x \\rightarrow 1^{+}} f(x)=\\lim _{x \\rightarrow 1^{+}}(x+1)^2=4$ suy ra $\\lim _{x \\rightarrow 1} f(x)=4$.<br>Vậy để hàm số liên tục tại $x=1$ khi $\\lim _{x \\rightarrow 1} f(x) = f(1) \\Leftrightarrow k^2 = 4 \\Leftrightarrow k = \\pm 2$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một tam giác có độ dài các cạnh là $1$, $m$, $2$ với $m \\in \\mathbb{Z}$. Giá trị của $m$ là", "choices": ["$2$", "$1$", "$3$", "$4$"], "correctIndex": 0, "explain": "Theo bất đẳng thức tam giác, với ba cạnh có độ dài $1$, $m$, $2$, ta phải có:  $\\heva{&1+m>2\\\\&1+2>m\\\\&m+2>1} \\Leftrightarrow \\heva{&m>1\\\\&m<3\\\\&m>-1} \\Leftrightarrow 1 < m < 3$.  Vì $m \\in \\mathbb{Z}$ nên $m=2$."}]}, {"noiDungChung": "Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình chữ nhật với $AD=2a$. Tam giác $SAB$ vuông cân tại $S$ và nằm trong mặt phẳng vuông góc với đáy. Biết tổng diện tích tam giác $SAB$ và đáy $ABCD$ bằng $\\dfrac{33a^2}{4}$. Gọi $H$ là trung điểm của cạnh $AB$.", "cauHoi": [{"question": "Thể tích khối chóp $S.ABCD$ bằng bao nhiêu?", "choices": ["$a^3$", "$2a^3$", "$3a^3$", "$4a^3$"], "correctIndex": 2, "explain": "Đặt $AB=x$ ($x>0$). Do tam giác $SAB$ vuông cân tại $S$ nên đường cao $SH=\\dfrac{x}{2}$ và diện tích tam giác $SAB$ là $S_{SAB}=\\dfrac{1}{2}SH \\cdot AB=\\dfrac{x^2}{4}$.<br>Diện tích đáy $S_{ABCD}=AB \\cdot AD=2ax$.<br>Theo giả thiết: $S_{SAB}+S_{ABCD}=\\dfrac{33a^2}{4} \\Leftrightarrow \\dfrac{x^2}{4}+2ax=\\dfrac{33a^2}{4} \\Leftrightarrow x^2+8ax-33a^2=0 \\Leftrightarrow \\hoac{&x=3a\\\\&x=-11a \\text{ (loại)}}$.<br>Với $AB=3a$, ta có $S_{ABCD}=3a \\cdot 2a=6a^2$ và $SH=\\dfrac{3a}{2}$.<br>Thể tích khối chóp là: $V=\\dfrac{1}{3}SH \\cdot S_{ABCD}=\\dfrac{1}{3} \\cdot \\dfrac{3a}{2} \\cdot 6a^2=3a^3$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>"}, {"question": "Số đo của góc giữa đường thẳng $SC$ và mặt phẳng đáy $(ABCD)$ gần với giá trị nào nhất sau đây?", "choices": ["$26^{\\circ}$", "$31^{\\circ}$", "$47^{\\circ}$", "$53^{\\circ}$"], "correctIndex": 1, "explain": "Do $SH \\perp (ABCD)$ nên góc giữa $SC$ và $(ABCD)$ là góc $\\angle SCH$.<br>Ta có $AB=3a$ nên $HB=\\dfrac{3a}{2}$.<br>Trong tam giác vuông $HBC$: $HC=\\sqrt{HB^2+BC^2}=\\sqrt{\\left(\\dfrac{3a}{2}\\right)^2+(2a)^2}=\\dfrac{5a}{2}$.<br>Trong tam giác vuông $SHC$: $\\tan \\angle SCH=\\dfrac{SH}{HC}=\\dfrac{\\dfrac{3a}{2}}{\\dfrac{5a}{2}}=\\dfrac{3}{5}$.<br>Suy ra $\\angle SCH \\approx 30{,}96^{\\circ}$. Vậy giá trị gần nhất là $31^{\\circ}$."}, {"question": "Khoảng cách từ điểm $A$ đến mặt phẳng $(SBD)$ bằng bao nhiêu?", "choices": ["$\\dfrac{3a}{2}$", "$\\dfrac{6a}{\\sqrt{61}}$", "$\\dfrac{6a}{\\sqrt{17}}$", "$\\dfrac{a\\sqrt{3}}{2}$"], "correctIndex": 2, "explain": "Ta có $AD \\parallel BC \\Rightarrow AD \\parallel (SBC)$. Tuy nhiên ta cần tính $d(A,(SBD))$.<br>Vì $H$ là trung điểm $AB$ nên $d(A,(SBD))=2d(H,(SBD))$.<br>Kẻ $HK \\perp BD$ tại $K$, kẻ $HI \\perp SK$ tại $I \\Rightarrow HI=d(H,(SBD))$.<br>Trong tam giác vuông $ABD$: $BD=\\sqrt{AB^2+AD^2}=\\sqrt{(3a)^2+(2a)^2}=a\\sqrt{13}$.<br>Chiều cao $HK=\\dfrac{HB \\cdot AD}{BD}=\\dfrac{\\dfrac{3a}{2} \\cdot 2a}{a\\sqrt{13}}=\\dfrac{3a}{\\sqrt{13}}$.<br>Xét tam giác vuông $SHK$: $\\dfrac{1}{HI^2}=\\dfrac{1}{SH^2}+\\dfrac{1}{HK^2}=\\dfrac{1}{\\left(\\dfrac{3a}{2}\\right)^2}+\\dfrac{1}{\\left(\\dfrac{3a}{\\sqrt{13}}\\right)^2}=\\dfrac{4}{9a^2}+\\dfrac{13}{9a^2}=\\dfrac{17}{9a^2}$.<br>Suy ra $HI=\\dfrac{3a}{\\sqrt{17}}$.   Vậy $d(A,(SBD))=2\\dfrac{3a}{\\sqrt{17}}=\\dfrac{6a}{\\sqrt{17}}$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $a=\\log_{30}3,b=\\log_{30}5.$ Biết $\\log_{30}1350=ma+nb+p$ với $m, n, p$ là các số hữu tỉ. Phát biểu nào sau đây đúng", "choices": ["$m>n>p$", "$m=n+p$", "$m.n.p=6$", "$n$ là số tự nhiên chẵn"], "correctIndex": 1, "explain": "$\\log_{30}1350=\\log_{30}\\left(30.3^2.5\\right)=\\log_{30}30+2\\log_{30}3+\\log_{30}5=1+2a+b.$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tìm tham số $m$ để hàm số $f(x)=\\left\\{\\begin{array}{ll}x^2+2 x-m & \\text { khi } x \\neq 2 \\\\ x+m & \\text { khi } x=2\\end{array}\\right.$ liên tục tại điểm $x_0=2$.", "choices": ["$m=2$", "$m=3$", "$m=8$", "$m=1$"], "correctIndex": 1, "explain": "Ta có $\\displaystyle\\lim \\limits_{x \\rightarrow 2} f(x)=\\displaystyle\\lim \\limits_{x \\rightarrow 2}\\left(x^2+2 x-m\\right)=8-m$ và $f(2)=2+m$<br>Để hàm số liên tục tại $x_0=2 \\Leftrightarrow 8-m=m+2 \\Leftrightarrow m=3$"}]}, {"noiDungChung": "Trong mặt phẳng tọa độ $Oxy$, cho tam giác $ABC$ có đỉnh $A(1;2)$, đường trung tuyến kẻ từ $B$ là $d_1: x-2y+1=0$ và đường cao kẻ từ $C$ là $d_2: -x+y+1=0$.", "cauHoi": [{"question": "Tọa độ đỉnh $C$ của tam giác $ABC$ là", "choices": ["$C(4;5)$", "$C(-3;-2)$", "$C(-4;3)$", "$C(1;-3)$"], "correctIndex": 1, "explain": "Vì $C \\in d_2$ nên $C(c;c+1)$.<br>Gọi $M$ là trung điểm $AC$, ta có $M\\left(\\dfrac{c+1}{2};\\dfrac{c+3}{2}\\right)$.<br>Vì $M \\in d_1$ nên $\\dfrac{c+1}{2}-2\\left(\\dfrac{c+3}{2}\\right)+1=0 \\Leftrightarrow c+1-2c-6+2=0 \\Leftrightarrow c=-3$.<br>Vậy $C(-3;-2)$."}, {"question": "Phương trình đường thẳng $AB$ là", "choices": ["$x+y-1=0$", "$x+y-3=0$", "$x-y+1=0$", "$2x+y-4=0$"], "correctIndex": 1, "explain": "Đường thẳng $AB$ đi qua $A(1;2)$ và vuông góc với đường cao $d_2: -x+y+1=0$.<br>Vectơ pháp tuyến của $AB$ là $\\vec{n}_{AB}=(1;1)$.<br>Phương trình $AB: 1(x-1)+1(y-2)=0 \\Leftrightarrow x+y-3=0$."}, {"question": "Tính diện tích $S$ của tam giác $ABC$", "choices": ["$S=\\dfrac{25}{4}$", "$S=12{,}5$", "$S=\\dfrac{8}{3}$", "$S=25$"], "correctIndex": 2, "explain": "Tọa độ đỉnh $B$ là giao điểm của đường thẳng $AB$ và đường trung tuyến $d_1$:<br>Giải hệ phương trình: $\\heva{&x+y-3=0\\\\&x-2y+1=0} \\Leftrightarrow \\heva{&x=\\dfrac{5}{3}\\\\&y=\\dfrac{4}{3}} \\Rightarrow B\\left(\\dfrac{5}{3};\\dfrac{4}{3}\\right)$.<br>Với $A(1;2)$ và $C(-3;-2)$, ta có $\\vec{AC}=(-4;-4)$. Độ dài $AC = \\sqrt{(-4)^2+(-4)^2} = 4\\sqrt{2}$.<br>Phương trình đường thẳng $AC$: Đi qua $A(1;2)$ có VTPT $\\vec{n}_{AC}=(1;-1) \\Rightarrow 1(x-1)-1(y-2)=0 \\Leftrightarrow x-y+1=0$.<br>Khoảng cách từ $B$ đến đường thẳng $AC$ là:<br>$h = d(B,AC) = \\dfrac{|\\frac{5}{3}-\\frac{4}{3}+1|}{\\sqrt{1^2+(-1)^2}} = \\dfrac{\\frac{4}{3}}{\\sqrt{2}} = \\dfrac{4}{3\\sqrt{2}}$.<br>Diện tích tam giác $ABC$ là: $S = \\dfrac{1}{2} \\cdot h \\cdot AC = \\dfrac{1}{2} \\cdot \\dfrac{4}{3\\sqrt{2}} \\cdot 4\\sqrt{2} = \\dfrac{8}{3}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một mảnh đất hình chữ nhật có chu vi bằng $28$ m. Đường chéo của hình chữ nhật dài $10$ m. Tính diện tích của mảnh đất đó.", "choices": ["$12$ m$^2$", "$24$ m$^2$", "$36$ m$^2$", "$48$ m$^2$"], "correctIndex": 3, "explain": "Gọi chiều dài và chiều rộng của mảnh đất lần lượt là $x$, $y$ (đơn vị: m, điều kiện: $14 > x \\ge y > 0$).<br>Vì chu vi của hình chữ nhật là $28$ m nên ta có phương trình:  $$2(x+y)=28 \\Leftrightarrow x+y=14. \\quad (1)$$  Vì đường chéo của hình chữ nhật dài $10$ m, áp dụng định lý Pitago ta có phương trình:  $$x^2+y^2=10^2 \\Leftrightarrow x^2+y^2=100. \\quad (2)$$  Từ $(1)$ và $(2)$, ta có hệ phương trình:  $$\\heva{&x+y=14<br>&x^2+y^2=100} \\Leftrightarrow \\heva{&y=14-x<br>&x^2+(14-x)^2=100. \\quad (3)}$$  Giải phương trình $(3)$:  $$x^2+196-28x+x^2=100 \\Leftrightarrow 2x^2-28x+96=0 \\Leftrightarrow x^2-14x+48=0.$$  Phương trình có hai nghiệm $x=8$ (nhận) và $x=6$ (nhận).<br>Với $x=8 \\Rightarrow y=6$; với $x=6 \\Rightarrow y=8$ (loại vì $x \\ge y$).<br>Vậy chiều dài mảnh đất là $8$ m và chiều rộng là $6$ m.<br>Diện tích của mảnh đất là: $S=x \\cdot y=8 \\cdot 6=48$ m$^2$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $\\displaystyle\\int\\limits_{0}^{\\tfrac{\\pi}{2}}f(x)dx=5$. Tính $I=\\displaystyle\\int\\limits_{0}^{\\tfrac{\\pi}{2}}[f(x)+2\\sin x]dx$.", "choices": ["$5+\\pi$", "$5+\\dfrac{\\pi}{2}$", "$7$", "$3$"], "correctIndex": 2, "explain": "Ta có:  $I=\\int\\limits_{0}^{\\dfrac{\\pi}{2}}f(x)dx+\\int\\limits_{0}^{\\dfrac{\\pi}{2}}2\\sin xdx$.<br>Theo giả thiết $\\int\\limits_{0}^{\\dfrac{\\pi}{2}}f(x)dx=5$.<br>Tính $J=\\int\\limits_{0}^{\\dfrac{\\pi}{2}}2\\sin xdx = [-2\\cos x]\\bigg|_{0}^{\\dfrac{\\pi}{2}} = -2\\cos\\dfrac{\\pi}{2}-(-2\\cos 0) = 0+2=2$.<br>Vậy $I=5+2=7$."}]}, {"noiDungChung": "Một trung tâm dữ liệu vận hành một hệ thống gồm ba máy chủ hoạt động độc lập để lưu trữ hồ sơ. Xác suất gặp sự cố gây mất kết nối của máy chủ thứ nhất, thứ hai và thứ ba lần lượt là $0{,}05$; $0{,}04$ và $0{,}03$. Chỉ cần ít nhất một máy chủ hoạt động bình thường thì hệ thống vẫn có thể truy xuất dữ liệu được.", "cauHoi": [{"question": "Xác suất để hệ thống có thể truy xuất dữ liệu được viết dưới dạng phân số tối giản là $\\dfrac{a}{b}$. Tính giá trị của biểu thức $S=b-a$.", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 2, "explain": "Gọi $A_1$, $A_2$, $A_3$ lần lượt là biến cố máy chủ thứ nhất, thứ hai và thứ ba gặp sự cố.<br>Ta có $P(A_1)=0{,}05$; $P(A_2)=0{,}04$; $P(A_3)=0{,}03$.<br>Vì các máy chủ hoạt động độc lập nên biến cố hệ thống không thể truy xuất dữ liệu (cả ba máy cùng gặp sự cố) là:  $P(\\overline{A})=P(A_1 \\cap A_2 \\cap A_3)=0{,}05 \\cdot 0{,}04 \\cdot 0{,}03=0{,}00006$.<br>Xác suất để hệ thống truy xuất được dữ liệu là $P(A)=1-0{,}00006=0{,}99994$.<br>Ta có $0{,}99994=\\dfrac{99994}{100000}=\\dfrac{49997}{50000}$.<br>Vì $\\dfrac{49997}{50000}$ là phân số tối giản nên $a=49997$, $b=50000$.<br>Vậy $S=b-a=50000-49997=3$."}, {"question": "Giả sử trung tâm bổ sung thêm một máy chủ thứ tư hoạt động độc lập với ba máy trên. Để xác suất truy xuất dữ liệu thành công đạt ít nhất $0{,}99999$, xác suất gặp sự cố của máy chủ thứ tư tối đa là bao nhiêu?", "choices": ["$0{,}1666$", "$0{,}0100$", "$0{,}0001$", "$0{,}2000$"], "correctIndex": 0, "explain": "Gọi $p$ là xác suất gặp sự cố của máy chủ thứ tư.<br>Xác suất để hệ thống không thể truy xuất dữ liệu với $4$ máy chủ là: $P(\\overline{A'})=0{,}00006 \\cdot p$.<br>Để hệ thống truy xuất thành công với xác suất ít nhất $0{,}99999$ thì:  $1-0{,}00006 \\cdot p \\ge 0{,}99999 \\Leftrightarrow 0{,}00006 \\cdot p \\le 0{,}00001 \\Leftrightarrow p \\le \\dfrac{1}{6} \\approx 0{,}1666$."}, {"question": "Biết rằng hệ thống hiện tại vẫn đang truy xuất được dữ liệu, tính xác suất để máy chủ thứ nhất đang gặp sự cố (làm tròn đến $6$ chữ số thập phân)?", "choices": ["$0{,}050000$", "$0{,}000060$", "$0{,}049943$", "$0{,}050003$"], "correctIndex": 2, "explain": "Ta cần tính xác suất có điều kiện $P(A_1|A)$.<br>Áp dụng công thức định nghĩa: $P(A_1|A)=\\dfrac{P(A_1 \\cap A)}{P(A)}$.<br>Biến cố $A_1 \\cap A$ là biến cố \"Máy chủ $1$ gặp sự cố nhưng hệ thống vẫn truy xuất được dữ liệu\" (nghĩa là máy $1$ hỏng và ít nhất một trong hai máy còn lại hoạt động).<br>$P(A_1 \\cap A)=P(A_1) \\cdot P(A_2 \\cup A_3 \\text{ có ít nhất 1 máy hoạt động})$.<br>$P(A_1 \\cap A)=0{,}05 \\cdot (1-0{,}04 \\cdot 0{,}03)=0{,}05 \\cdot (1-0{,}0012)=0{,}05 \\cdot 0{,}9988=0{,}04994$.<br>Xác suất cần tìm: $P(A_1|A)=\\dfrac{0{,}04994}{0{,}99994} \\approx 0{,}049943$."}]}, {"noiDungChung": "Cho hàm số $y=f(x)=\\dfrac{e^{2x}-3e^x+6}{e^x-2}$ có đồ thị là $(C)$.", "cauHoi": [{"question": "Xác định tập xác định $D$ của hàm số đã cho.", "choices": ["$D=\\mathbb{R}$", "$D=(2;+\\infty)$", "$D=\\mathbb{R}\\setminus\\{\\ln 2\\}$", "$D=\\mathbb{R}\\setminus\\{2\\}$"], "correctIndex": 2, "explain": "Hàm số xác định khi mẫu thức khác $0$: $e^x-2\\neq 0\\Leftrightarrow e^x\\neq 2\\Leftrightarrow x\\neq\\ln 2$.  Vậy tập xác định là $D=\\mathbb{R}\\setminus\\{\\ln 2\\}$."}, {"question": "Xét đồ thị hàm số $f(x)$ trên khoảng $(\\ln 2;+\\infty)$. Mệnh đề nào sau đây sai?", "choices": ["Hàm số nghịch biến trên khoảng $(\\ln 2;+\\infty)$", "Hàm số đạt cực tiểu tại $x=\\ln 4$", "Đồ thị hàm số có tiệm cận đứng là $x=\\ln 2$", "Giá trị cực tiểu của hàm số là $5$"], "correctIndex": 0, "explain": "Đặt $t=e^x$. Với $x\\in(\\ln 2;+\\infty)$ thì $t\\in(2;+\\infty)$.<br>Xét hàm số $g(t)=\\dfrac{t^2-3t+6}{t-2}$ trên $(2;+\\infty)$.<br>Ta có $g'(t)=\\dfrac{(2t-3)(t-2)-(t^2-3t+6)}{(t-2)^2}=\\dfrac{t^2-4t}{(t-2)^2}$.<br>$g'(t)=0\\Leftrightarrow\\hoac{&t=0\\text{ (loại)}\\\\&t=4\\text{ (nhận).}}$  Bảng biến thiên của $g(t)$ trên $(2;+\\infty)$:<br>Dựa vào bảng biến thiên, giá trị nhỏ nhất của hàm số trên khoảng đã cho là $5$ tại $t=4$ (tương ứng $x=\\ln 4$).<br>a) Hàm số nghịch biến trên $(2; 4)$ (tương ứng $x\\in(\\ln 2; \\ln 4)$) và đồng biến trên $(4; +\\infty)$ (tương ứng $x\\in(\\ln 4; +\\infty)$). Vậy mệnh đề \"Hàm số nghịch biến trên khoảng $(\\ln 2; +\\infty)$\" là sai.  <br>b) Hàm số đạt cực tiểu tại $t=4 \\Rightarrow x=\\ln 4$.  <br>c) $\\lim\\limits_{x \\to (\\ln 2)^+} f(x) = +\\infty$ nên $x=\\ln 2$ là tiệm cận đứng.  <br>d) Giá trị cực tiểu $y_{CT} = g(4) = 5$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>"}, {"question": "Có bao nhiêu số nguyên âm của tham số $m$ để phương trình $f(x)=m$ có đúng hai nghiệm thực phân biệt?", "choices": ["$0$", "$1$", "$3$", "Vô số"], "correctIndex": 0, "explain": "Đặt $t=e^x$ ($t>0$, $t\\neq 2$). Phương trình trở thành $\\dfrac{t^2-3t+6}{t-2}=m\\Leftrightarrow t^2-(m+3)t+2m+6=0$.<br>Xét hàm số $g(t)=\\dfrac{t^2-3t+6}{t-2}$ trên $D_t=(0;+\\infty)\\setminus\\{2\\}$.<br>Ta có $g'(t)=\\dfrac{t^2-4t}{(t-2)^2}$; $g'(t)=0\\Leftrightarrow\\hoac{&t=0\\\\&t=4.}$  <br>Bảng biến thiên của $g(t)$:<br>Để phương trình $f(x)=m$ có đúng hai nghiệm $x$ phân biệt thì phương trình $g(t)=m$ phải có đúng hai nghiệm $t>0$ phân biệt.<br>a) Với $m\\in(-\\infty;-3)$, đường thẳng $y=m$ chỉ cắt nhánh trái $(0;2)$ tại một điểm.  <br>b) Với $m\\in(-3;5)$, đường thẳng $y=m$ không thể cắt nhánh trái (vì giới hạn tại $0$ là $-3$) và không cắt nhánh phải (vì cực tiểu là $5$).  <br>c) Với $m=5$, phương trình có nghiệm duy nhất $t=4$.  <br>d) Với $m\\in(5;+\\infty)$, đường thẳng $y=m$ cắt nhánh phải $(2;+\\infty)$ tại hai điểm phân biệt và không cắt nhánh trái.<br>Vậy phương trình có đúng hai nghiệm phân biệt khi $m>5$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>"}]}, {"noiDungChung": "Bạn An dự định làm hai loại đèn trung thu, toàn bộ số tiền bán được An sẽ ủng hộ miền Bắc sau cơn bão Yagi. Cần 2 giờ để làm xong một chiếc lồng đèn hình ngôi sao, và bán giá 30 ngàn đồng. Cần 3 giờ để làm một chiếc đèn hình con thỏ cần 3 giờ và bán giá 50 ngàn đồng. Bạn An có 30 giờ để làm hai loại đèn trung thu, và bạn muốn làm ít nhất 12 chiếc. Giả sử số đèn trung thu An làm đươc đều bán được hết. Gọi $x ; y$ lần lượt là số đèn trung thu hình ngôi sao và số đèn trung thu hình con thỏ $(x \\geq 0 ; y \\geq 0 ; x ; y \\in \\mathbb{N})$.", "cauHoi": [{"question": "Viết hệ bất phương trình theo $x$, $y$ dựa vào tất cả giả thiết đã cho.", "choices": ["$\\left\\{\\begin{array}{l}x \\geq 0 \\\\ y \\geq 0 \\\\ 2 x+3 y \\leq 30 \\\\ x+y \\geq 12\\end{array}\\right.$", "$\\left\\{\\begin{array}{l}x \\geq 0 \\\\ y \\geq 0 \\\\ 2 x+3 y \\geq 12 \\\\ x+y \\geq 30\\end{array}\\right.$", "$\\left\\{\\begin{array}{l}x \\geq 0 \\\\ y \\geq 0 \\\\ 2 x+3 y \\leq 30 \\\\ x+y \\leq 12\\end{array}\\right.$", "$\\left\\{\\begin{array}{l}x \\geq 0 \\\\ y \\geq 0 \\\\ 2 x+3 y \\leq 12 \\\\ x+y \\geq 30\\end{array}\\right.$"], "correctIndex": 0, "explain": "Gọi $x ; y$ lần lượt là số đèn trung thu hình ngôi sao và số đèn trung thu hình con thỏ $(x \\geq 0 ; y \\geq 0 ; x ; y \\in \\mathbb{N}$ )<br>Theo bài ra ta có hệ bất phương trình sau: $\\left\\{\\begin{array}{l}x \\geq 0 \\\\ y \\geq 0 \\\\ 2 x+3 y \\leq 30 \\\\ x+y \\geq 12\\end{array}\\right.$"}, {"question": "Khi số tiền An bán được là lớn nhất thì số tiền mà An ủng hộ cho miền Bắc lớn nhất là bao nhiêu ngàn đồng?", "choices": ["500", "450", "480", "425"], "correctIndex": 2, "explain": "Số tiền An thu được về là: $F(x ; y)=30 x+50 y$  Miền nghiệm cùa hệ là miền tam giác $A B C$ với $A(6 ; 6) ; B(12 ; 0) ; C(15 ; 0)$.<br>Ta có,$F(6 ; 6)=480 ; F(12 ; 0)=360 ; F(15 ; 0)=450$.<br>Vậy để An thu được nhiều tiền nhất thì An cần làm 6 chiếc đèn hình ngôi sao và 6 chiếc hình con thỏ.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, x=0.4cm, y=0.4cm, font=\\footnotesize]\n\t\t\t\t\n\t\t\t\t\\def\\xmin{-2} \\def\\xmax{20}\n\t\t\t\t\\def\\ymin{-2} \\def\\ymax{15}\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\def\\fOne(#1){(30 - 2*#1)/3} \n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\def\\fTwo(#1){12 - #1}\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\draw[color=gray!20] (\\xmin,\\ymin) grid (\\xmax,\\ymax);\n\t\t\t\t\\draw[->, thick] (\\xmin,0) -- (\\xmax,0) node[below] {$x$};\n\t\t\t\t\\draw[->, thick] (0,\\ymin) -- (0,\\ymax) node[left] {$y$};\n\t\t\t\t\\node[below left] at (0,0) {$O$};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\begin{scope}\n\t\t\t\t\t\\clip (0,0) rectangle (\\xmax,\\ymax); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\fill[pattern=north east lines, pattern color=blue!20] \n\t\t\t\t\t(0, \\ymax) -- plot[domain=0:\\xmax] (\\x, {\\fOne(\\x)}) -- (\\xmax, \\ymax) -- cycle;\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\fill[pattern=north west lines, pattern color=red!20] \n\t\t\t\t\t(0,0) -- plot[domain=0:12] (\\x, {\\fTwo(\\x)}) -- (12,0) -- cycle;\n\t\t\t\t\\end{scope}\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\draw[thick, blue] plot[domain=-1:16] (\\x, {\\fOne(\\x)}) node[right] {$d_1$};\n\t\t\t\t\\draw[thick, red] plot[domain=-1:13] (\\x, {\\fTwo(\\x)}) node[above right] {$d_2$};\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\fill (6,6) circle (2pt) node[above right] {$A(6,6)$};\n\t\t\t\t\\foreach \\x in {12,15} \\node[below] at (\\x,0) {\\x};\n\t\t\t\t\\foreach \\y in {10,12} \\node[left] at (0,\\y) {\\y};\n\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Trong không gian với hệ tọa độ $Oxyz$, cho điểm $H(3;2;1)$ và ba đường thẳng $d_1\\colon \\heva{&x=t_1\\\\&y=0\\\\&z=0}$, $d_2\\colon \\heva{&x=1\\\\&y=t_2\\\\&z=0}$, $d_3\\colon \\heva{&x=1\\\\&y=0\\\\&z=t_3}$. Gọi $(P)$ là mặt phẳng đi qua $H$ và cắt $d_1, d_2, d_3$ lần lượt tại $A, B, C$.", "cauHoi": [{"question": "Mệnh đề nào dưới đây là sai?", "choices": ["Các đường thẳng $d_1, d_2, d_3$ đôi một vuông góc với nhau", "Đường thẳng $d_1$ nằm trên $(Ox)$", "Khoảng cách từ điểm $K(1;0;0)$ đến điểm $H(3;2;1)$ bằng $3$", "Véc-tơ chỉ phương của đường thẳng $d_2$ là $\\vec{u}=(1;0;0)$"], "correctIndex": 3, "explain": "a) $d_1 \\parallel Ox, d_2 \\parallel Oy, d_3 \\parallel Oz$ và chúng đi qua các điểm tạo thành hệ trục tịnh tiến nên chúng đôi một vuông góc. Khẳng định a đúng.  <br>b) $d_1$ có $y=0, z=0$ nên $d_1$ chính là trục $Ox$. Khẳng định b đúng.  <br>c) $KH=\\sqrt{(3-1)^2+(2-0)^2+(1-0)^2}=\\sqrt{2^2+2^2+1^2}=3$. Khẳng định c đúng.  <br>d) VTCP của $d_2$ dựa trên hệ số của $t_2$ là $\\vec{u}=(0;1;0)$. Khẳng định d sai."}, {"question": "Tìm tọa độ điểm $C$ trên đường thẳng $d_3$ sao cho độ dài đoạn thẳng $HC$ ngắn nhất.", "choices": ["$C(1;0;0)$", "$C(1;0;2)$", "$C(1;0;1)$", "$C(1;0;3)$"], "correctIndex": 2, "explain": "Điểm $C\\in d_3 \\Rightarrow C(1;0;t_3)$.<br>Độ dài $HC=\\sqrt{(1-3)^2+(0-2)^2+(t_3-1)^2} = \\sqrt{4+4+(t_3-1)^2} = \\sqrt{8+(t_3-1)^2}$.<br>Biểu thức $HC$ đạt giá trị nhỏ nhất khi $(t_3-1)^2=0 \\Leftrightarrow t_3=1$.<br>Vậy tọa độ điểm $C(1;0;1)$"}, {"question": "Phương trình mặt phẳng $(P)$ có dạng $ax+by+z+c=0$. Tính $S=a+b+c$ biết $H$ là trực tâm tam giác $ABC$.", "choices": ["$S=-11$", "$S=11$", "$S=-7$", "$S=7$"], "correctIndex": 2, "explain": "Gọi $A(a;0;0)$, $B(1;b;0)$, $C(1;0;c)$.<br>Ta có $\\vec{AB}=(1-a;b;0)$, $\\vec{BC}=(0;-b;c)$, $\\vec{CH}=(2;2;1-c)$, $\\vec{AH}=(3-a;2;1)$.<br>$H$ là trực tâm tam giác $ABC$ khi và chỉ khi:  $\\heva{&\\vec{AB}\\cdot\\vec{CH}=0\\\\&\\vec{BC}\\cdot\\vec{AH}=0\\\\&[\\vec{AB},\\vec{BC}]\\cdot\\vec{CH}=0} \\Leftrightarrow \\heva{&2(1-a)+2b=0\\\\&-2b+c=0\\\\&2bc+2c(a-1)+(1-c)b(a-1)=0} \\Leftrightarrow \\heva{&a=b+1\\\\&c=2b\\\\&4b^2+4b^2+b^2(1-2b)=0.}$<br>$\\Leftrightarrow \\heva{&a=b+1\\\\&c=2b\\\\&9b^2-2b^3=0.}$  Vì $b\\neq 0$ nên $b=\\dfrac{9}{2} \\Rightarrow a=\\dfrac{11}{2}$, $c=9$.<br>Mặt phẳng $(ABC)$ đi qua $C(1;0;9)$ và có VTPT $\\vec{n}=(bc;ac-c;ab-b)=(2;2;1)$.<br>Phương trình mặt phẳng $(P)\\colon 2x+2y+z-11=0$.<br>Suy ra $a=2, b=2, c=-11$. Vậy $a+b+c=2+2-11=-7$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Chọn ngẫu nhiên $3$ số $a$, $b$, $c$ trong tập hợp $S=\\{1;2;\\dots;26\\}$. Biết xác suất để $3$ số chọn ra thỏa mãn $a^2+b^2+c^2$ chia hết cho $5$ bằng $\\dfrac{m}{n}$ với $m$, $n\\in \\mathbb{N}^*$ và $\\dfrac{m}{n}$ là phân số tối giản. Tính giá trị biểu thức $T=m+n$.", "choices": ["$T=79$", "$T=243$", "$T=49$", "$T=126$"], "correctIndex": 0, "explain": "Số phần tử của không gian mẫu là $n(\\Omega)=C_{26}^3=2600$.<br>Gọi $A$ là tập hợp các phần tử thuộc $S$ mà chia hết cho $\\overline{5}, A$ có $\\overline{5}$ phần tử.<br>$B$ là tập hợp các phần tử thuộc $S$ mà chia cho 5 dư 1 hoặc dư $4, B$ có 11 phần tử.<br>$C$ là tập hợp các phần tử thuộc $S$ mà chia cho 5 dư 2 hoặc dư $3, O$ có 10 phần tử.<br>Ta có nhận xét<br>Với $k \\in A$ thì $k^2$ chia hết cho 5 .<br>Với $k \\in B$ thì $k^2$ chia cho 5 dừ 1 .<br>Với $k \\in C$ thì $k^2$ chia cho 5 dư 4 .<br>Số phần tử của không gian mẫu là $C_{28}^8$.<br>Để chọn được 3 số thỏa mãn bài toán, ta có hai trường hợp<br>Trường hợp 1: 3 số được chọn đều thuộc $A$, có $C_6^8$ cách chọn.<br>Trường hợp 2: 3 số được chọn có mỗi số thuộc mỗi tập $A, B, C$, có $C_6^1 \\cdot C_{11}^1 \\cdot C_{10}^1$ cách chọn.<br>Suy ra số phần tử của biến cố là $C_{\\%}^8+C_{\\%}^1 \\cdot C_{10}^1 \\cdot C_{11}^1$.<br>Xác suất của biến cố là $\\dfrac{C_5^8+C_6^1 \\cdot C_{10}^1 \\cdot C_{11}^1}{C_{28}^8}=\\dfrac{14}{65}=\\dfrac{m}{n}$."}]}, {"noiDungChung": "Một đêm nhạc Acoustic có đúng $5$ tiết mục biểu diễn gồm: Guitar solo, Saxophone, Piano, Trống và Violin. Thứ tự các tiết mục từ số $1$ đến số $5$ phải tuân thủ các quy định ban tổ chức đề ra như sau:<br>a) Tiết mục Piano phải được biểu diễn trước tiết mục Saxophone.  <br>b) Tiết mục Trống và tiết mục Violin phải được biểu diễn liên tiếp nhau (theo thứ tự nào cũng được).  <br>c) Tiết mục Guitar solo không được là tiết mục mở màn ($1$) và cũng không được là tiết mục kết thúc ($5$).  <br>d) Tiết mục ở vị trí thứ $2$ là Saxophone.", "cauHoi": [{"question": "Tiết mục nào buộc phải biểu diễn ở vị trí đầu tiên ($1$)?", "choices": ["Guitar solo", "Piano", "Trống", "Violin"], "correctIndex": 1, "explain": "Gọi thứ tự biểu diễn là $1, 2, 3, 4, 5$.  Dựa trên các ràng buộc:<br>a) Theo quy định, Piano phải diễn trước Saxophone.  <br>b) Mà Saxophone đã cố định ở vị trí thứ $2$.  <br>c) Vị trí duy nhất còn lại trước vị trí số $2$ là vị trí số $1$, do đó Piano buộc phải diễn đầu tiên."}, {"question": "Nếu tiết mục Trống được biểu diễn ở vị trí thứ $3$, khẳng định nào sau đây ĐÚNG?", "choices": ["Guitar solo diễn ở vị trí $5$", "Violin diễn ở vị trí $5$", "Guitar solo diễn ở vị trí $4$", "Piano diễn ở vị trí $3$"], "correctIndex": 2, "explain": "Hiện tại ta có: Vị trí $1$: Piano, Vị trí $2$: Saxophone.<br>a) Nếu Trống diễn ở vị trí $3$, vì Trống và Violin phải liên tiếp nên Violin phải ở vị trí $4$ (do vị trí $2$ đã có Saxophone).  <br>b) Khi đó, vị trí $5$ còn lại sẽ dành cho Guitar solo.  <br>c) Tuy nhiên, quy định nêu rõ Guitar solo không được diễn ở vị trí $5$.  <br>d) Để thỏa mãn điều kiện Guitar solo không ở vị trí $5$, Guitar solo buộc phải diễn ở vị trí $3$ hoặc $4$.  <br>e) Nếu Guitar solo diễn ở vị trí $4$, cặp (Trống, Violin) sẽ bị tách ra ở vị trí $3$ và $5$ (không liên tiếp - Loại).  <br>f) Vậy trường hợp duy nhất thỏa mãn là Guitar solo diễn ở vị trí $3$, cặp (Trống, Violin) diễn ở vị trí $4$ và $5$."}, {"question": "Có bao nhiêu cách sắp xếp thứ tự các tiết mục khác nhau thỏa mãn tất cả các quy định trên?", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 1, "explain": "Cố định: Vị trí $1$: Piano, Vị trí $2$: Saxophone.  Còn lại $3$ vị trí $\\{3, 4, 5\\}$ cho các tiết mục $\\{Guitar\\ solo, Trống, Violin\\}$.  Ràng buộc: Guitar solo không ở vị trí $5$; Trống và Violin phải liên tiếp.<br>a) <b>Trường hợp 1:</b> Guitar solo diễn ở vị trí $3$. Vị trí $4, 5$ sẽ dành cho (Trống, Violin) hoặc (Violin, Trống). Cả hai cách này đều thỏa mãn vì cặp này vẫn liên tiếp và Guitar solo không phạm quy ở vị trí $5$. $\\Rightarrow$ Có $2$ cách.  <br>b) <b>Trường hợp 2:</b> Guitar solo diễn ở vị trí $4$. Vị trí $3$ và $5$ dành cho Trống và Violin. Tuy nhiên hai vị trí này không liên tiếp nhau $\\Rightarrow$ Không thỏa mãn quy định.<br>Vậy tổng cộng có $2$ cách sắp xếp thỏa mãn."}]}, {"noiDungChung": "Ba thực khách gồm chú Hùng, anh Mạnh và bạn Linh đang thưởng thức bữa tối tại một khu phố ẩm thực. Mỗi người chọn một món ăn khác nhau là: Phở, Bún chả và Bánh mì. Mỗi người cũng uống một loại nước giải khát khác nhau là: Trà đá, Nước mía và Sữa đậu. Biết rằng:<br>a) Bạn Linh không ăn Bún chả và không uống Trà đá.  <br>b) Người ăn Phở thì uống Nước mía.  <br>c) Anh Mạnh chọn ăn Bánh mì.  <br>d) Chú Hùng không uống Sữa đậu.", "cauHoi": [{"question": "Khẳng định nào sau đây về món ăn và thức uống của thực khách là ĐÚNG?", "choices": ["Chú Hùng ăn Bún chả và uống Nước mía", "Bạn Linh ăn Phở và uống Sữa đậu", "Bạn Linh ăn Phở và uống Nước mía", "Anh Mạnh ăn Bánh mì và uống Nước mía"], "correctIndex": 2, "explain": "Ta phân tích các mối liên hệ dựa trên dữ kiện bài toán:<br>a) Vì anh Mạnh ăn Bánh mì và người ăn Phở uống Nước mía nên anh Mạnh không uống Nước mía.  <br>b) Bạn Linh không ăn Bún chả và anh Mạnh đã ăn Bánh mì nên bạn Linh buộc phải ăn Phở.  <br>c) Do bạn Linh ăn Phở nên theo dữ kiện (2), bạn Linh uống Nước mía.<br>Vậy cặp tương ứng đúng cho bạn Linh là (Phở - Nước mía)."}, {"question": "Chú Hùng uống loại nước giải khát nào?", "choices": ["Nước mía", "Sữa đậu", "Trà đá", "Không thể xác định"], "correctIndex": 2, "explain": "Từ kết quả phân tích trước đó:<br>a) Bạn Linh đã uống Nước mía.  <br>b) Chú Hùng không uống Sữa đậu và bạn Linh đã uống Nước mía nên chú Hùng buộc phải uống Trà đá.<br>Vậy chú Hùng uống Trà đá."}, {"question": "Thông tin nào sau đây về anh Mạnh là ĐÚNG?", "choices": ["Anh Mạnh ăn Bánh mì và uống Trà đá", "Anh Mạnh ăn Bún chả và uống Sữa đậu", "Anh Mạnh ăn Bánh mì và uống Sữa đậu", "Anh Mạnh ăn Phở và uống Nước mía"], "correctIndex": 2, "explain": "Tổng hợp lại toàn bộ dữ liệu đã suy luận:<br>a) Bạn Linh: Ăn Phở - uống Nước mía.  <br>b) Chú Hùng: Uống Trà đá, do đó chú Hùng ăn Bún chả (món còn lại).  <br>c) Anh Mạnh: Ăn Bánh mì, do đó anh Mạnh uống Sữa đậu (loại nước còn lại).<br>Vậy anh Mạnh ăn Bánh mì và uống Sữa đậu."}]}, {"noiDungChung": "Một cuộc khảo sát về phương tiện di chuyển chính đến trường của $400$ học sinh tại một trường THPT được ghi lại qua biểu đồ tròn dưới đây. Cơ cấu phương tiện gồm: Xe đạp ($35\\%$), Xe máy điện ($30\\%$), Xe buýt ($20\\%$), và Đi bộ ($15\\%$).<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.7, font=\\footnotesize]\n\t\t\t\\def\\radius{2.5}\n\t\t\t\\fill[cyan!60] (0,0) -- (0:\\radius) arc (0:126:\\radius) -- cycle;\n\t\t\t\\fill[orange!70] (0,0) -- (126:\\radius) arc (126:234:\\radius) -- cycle;\n\t\t\t\\fill[green!60!black] (0,0) -- (234:\\radius) arc (234:306:\\radius) -- cycle;\n\t\t\t\\fill[magenta!50] (0,0) -- (306:\\radius) arc (306:360:\\radius) -- cycle;\n\t\t\t\\node at (63:1.6) {$35\\%$};\n\t\t\t\\node at (180:1.6) {$30\\%$};\n\t\t\t\\node at (270:1.6) {$20\\%$};\n\t\t\t\\node at (333:1.6) {$15\\%$};\n\t\t\t\\node[right] at (3,1) {\\fbox{\\phantom{m}} Xe đạp};\n\t\t\t\\node[right] at (3,0.3) {\\fbox{\\phantom{m}} Xe máy điện};\n\t\t\t\\node[right] at (3,-0.4) {\\fbox{\\phantom{m}} Xe buýt};\n\t\t\t\\node[right] at (3,-1.1) {\\fbox{\\phantom{m}} Đi bộ};\n\t\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Số lượng học sinh chọn phương tiện di chuyển là Xe đạp nhiều hơn số lượng học sinh Đi bộ là bao nhiêu người?", "choices": ["$60$ người", "$80$ người", "$140$ người", "$20$ người"], "correctIndex": 1, "explain": "Số học sinh đi xe đạp là: $400 \\cdot 35\\% = 140$ (học sinh).<br>Số học sinh đi bộ là: $400 \\cdot 15\\% = 60$ (học sinh).<br>Sự chênh lệch là: $140-60=80$ (người)."}, {"question": "Nhà trường dự kiến hỗ trợ vé xe buýt cho tất cả học sinh đang đi xe buýt và $50\\%$ số học sinh đang đi bộ. Tổng số học sinh nhận được hỗ trợ là bao nhiêu?", "choices": ["$80$ người", "$100$ người", "$110$ người", "$140$ người"], "correctIndex": 2, "explain": "Số học sinh đi xe buýt là: $400 \\cdot 20\\% = 80$ (học sinh).<br>$50\\%$ số học sinh đi bộ là: $400 \\cdot 15\\% \\cdot 50\\% = 60 \\cdot 0{,}5 = 30$ (học sinh).<br>Tổng số học sinh được hỗ trợ: $80+30=110$ (người)."}, {"question": "Giả sử vào năm học tới, số học sinh đi Xe máy điện giảm $20\\%$ (so với số lượng hiện tại) và những học sinh này chuyển sang đi Xe đạp. Khi đó, tỉ lệ học sinh đi Xe đạp trong tổng số học sinh sẽ là bao nhiêu?", "choices": ["$36{,}00\\%$", "$35{,}00\\%$", "$41{,}00\\%$", "$42{,}00\\%$"], "correctIndex": 2, "explain": "Số lượng học sinh đi xe máy điện hiện tại: $400 \\cdot 30\\% = 120$ (người).<br>Số học sinh giảm đi ở nhóm xe máy điện: $120 \\cdot 20\\% = 24$ (người).<br>Số học sinh đi xe đạp mới: $140+24 = 164$ (người).<br>Tỉ lệ xe đạp mới: $\\dfrac{164}{400} \\cdot 100\\% = 41\\%$."}]}, {"noiDungChung": "Khảo sát năng suất lúa (tạ/ha) của một khu vực thu được mẫu số liệu ghép nhóm sau:<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Năng suất</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[45; 50)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[50; 55)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[55; 60)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[60; 65)$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Số hợp tác xã</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$10$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$15$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$10$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$5$</td></tr></table>", "cauHoi": [{"question": "Khoảng biến thiên của mẫu số liệu ghép nhóm trên là bao nhiêu?", "choices": ["$10$ tạ/ha", "$15$ tạ/ha", "$20$ tạ/ha", "$25$ tạ/ha"], "correctIndex": 2, "explain": "Khoảng biến thiên của mẫu số liệu ghép nhóm là hiệu số giữa đầu mút phải của nhóm cuối cùng và đầu mút trái của nhóm đầu tiên.<br>Ta có $R=65-45=20$ tạ/ha."}, {"question": "Năng suất lúa trung bình của các hợp tác xã trong khu vực này là bao nhiêu?", "choices": ["$52{,}50$ tạ/ha", "$53{,}75$ tạ/ha", "$54{,}25$ tạ/ha", "$55{,}00$ tạ/ha"], "correctIndex": 1, "explain": "Xác định giá trị đại diện $x_i$ của các nhóm: $47{,}5$; $52{,}5$; $57{,}5$; $62{,}5$.<br>Tổng số hợp tác xã là $n=10+15+10+5=40$.<br>Năng suất trung bình là:  $\\bar{x}=\\dfrac{10 \\cdot 47{,}5+15 \\cdot 52{,}5+10 \\cdot 57{,}5+5 \\cdot 62{,}5}{40}=\\dfrac{475+787{,}5+575+312{,}5}{40}=\\dfrac{2150}{40}=53{,}75$ tạ/ha."}, {"question": "Độ lệch chuẩn $s$ của mẫu số liệu trên bằng bao nhiêu (làm tròn kết quả đến hai chữ số thập phân)?", "choices": ["$4{,}21$", "$5{,}15$", "$4{,}84$", "$23{,}44$"], "correctIndex": 2, "explain": "Tính phương sai $s^2$:  $s^2=\\dfrac{1}{40}\\left(10 \\cdot 47{,}5^2+15 \\cdot 52{,}5^2+10 \\cdot 57{,}5^2+5 \\cdot 62{,}5^2\\right)-53{,}75^2$<br>$s^2=\\dfrac{22562{,}5+41343{,}75+33062{,}5+19531{,}25}{40}-2889{,}0625$<br>$s^2=\\dfrac{116500}{40}-2889{,}0625=2912{,}5-2889{,}0625=23{,}4375$.<br>Độ lệch chuẩn là $s=\\sqrt{23{,}4375} \\approx 4{,}84$."}]}]}, {"id": "extra-9", "ten": "Đề luyện tập số 15", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Gọi $S_n$ là tổng $n$ số hạng đầu tiên của cấp số cộng $(a_n)$. Biết $S_6=S_9$, tính tỉ số $\\dfrac{a_3}{a_5}$.", "choices": ["$\\dfrac{9}{5}$", "$\\dfrac{5}{9}$", "$\\dfrac{5}{3}$", "$\\dfrac{3}{5}$"], "correctIndex": 2, "explain": "Gọi $d$ là công sai của cấp số cộng. Ta có công thức tổng $n$ số hạng đầu tiên:  $S_n = \\dfrac{n[2a_1+(n-1)d]}{2}$.<br>Theo giả thiết $S_6=S_9$, ta có:  $$\\dfrac{6(2a_1+5d)}{2} = \\dfrac{9(2a_1+8d)}{2} \\Leftrightarrow 2(2a_1+5d) = 3(2a_1+8d)$$  $$\\Leftrightarrow 4a_1+10d = 6a_1+24d \\Leftrightarrow 2a_1 = -14d \\Leftrightarrow a_1 = -7d.$$  Ta biểu diễn $a_3$ và $a_5$ theo $a_1$ và $d$:<br>a) $a_3 = a_1+2d = -7d+2d = -5d$.  <br>b) $a_5 = a_1+4d = -7d+4d = -3d$.<br>Tỉ số cần tìm là:  $$\\dfrac{a_3}{a_5} = \\dfrac{-5d}{-3d} = \\dfrac{5}{3}.$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Anh Bình mua một chiếc điện thoại giá 9 triệu đồng theo hình thức trả trước $30\\%$ và phần còn lại trả góp hàng tháng với lãi suất $0,9\\%$/tháng. Anh Bình bắt đầu trả nợ sau đúng một tháng kể từ ngày mua, số tiền trả mỗi lần là như nhau. Để trả hết nợ sau đúng 12 tháng thì mỗi tháng anh Bình phải trả số tiền gần nhất với giá trị nào sau đây?", "choices": ["795.000 đồng", "604.000 đồng", "880.000 đồng", "556.000 đồng"], "correctIndex": 3, "explain": "Anh Bình trả trước $30 \\%$ giá trị điện thoại, vậy số tiền trả trưởc là:<br>$$  9.000 .000 \\times 30 \\%=2.700 .000 \\text { (đồng) }  $$<br>Số tiền còn lại anh Bình nợ cửa hàng là:<br>$$  A=9.000 .000-2.700 .000=6.300 .000 \\text { (đồng) }  $$<br>Gọi $r$ là lăi suất hàng tháng $(r=0,9 \\%=0,009), n$ là số tháng trả nợ $(n=12)$.  Công thức tính số tiền trả góp đểu hàng tháng để hết nợ sau $n$ tháng (vởi lẩn trả đẩu tiên sau 1 tháng) là:<br>$$  m=\\dfrac{A \\cdot r \\cdot(1+r)^n}{(1+r)^n-1}  $$<br>Thay các giá trị vào:<br>$$  \\begin{gathered}  m=\\dfrac{6.300 .000 \\cdot 0,009 \\cdot(1,009)^{12}}{(1,009)^{12}-1} <br>m \\approx \\dfrac{56.700 \\cdot 1,1135}{1,1135-1} \\approx \\dfrac{63.135,45}{0,1135} \\approx 556.259  \\end{gathered}  $$<br>Làm tròn đển hàng ngàn đồng theo yêu cẩu để bài, ta được 556.000 đồng."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Trọng và Quốc chạy bộ trong một khuôn viên hình tam giác $ABC$ vuông cân tại $A$ ($AB=AC=a$). Từ đỉnh $A$, hai bạn cùng lúc bắt đầu chạy bộ dọc theo các cạnh của tam giác với vận tốc không đổi nhưng theo hai chiều ngược nhau:<br>a) Trọng chạy theo chiều: $A \\to B \\to C \\to A$.  <br>b) Quốc chạy theo chiều: $A \\to C \\to B \\to A$.<br>Biết rằng lần gặp nhau thứ nhất tại điểm $M$ trên cạnh $BC$ với $BM=600$ m. Lần gặp nhau thứ hai tại điểm $N$ trên cạnh $AB$ với $AN=200$ m. Tính chu vi khuôn viên đó (làm tròn đến hàng đơn vị).<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=0.8, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\\coordinate (A) at (0,3);\n\t\t\t\\coordinate (B) at (-3,0);\n\t\t\t\\coordinate (C) at (3,0);\n\t\t\t\\draw[blue, ultra thick] (A) -- (B) -- (C) -- cycle;\n\t\t\t\\coordinate (M) at ($(B)!0.42!(C)$);\n\t\t\t\\coordinate (N) at ($(A)!0.2!(B)$);\n\t\t\t\\foreach \\p in {A,B,C,M,N}\n\t\t\t\\filldraw[red] (\\p) circle (2pt);\n\t\t\t\\node[above=3pt] at (A) {$A$};\n\t\t\t\\node[left=3pt] at (B) {$B$};\n\t\t\t\\node[right=3pt] at (C) {$C$};\n\t\t\t\\node[below=3pt] at (M) {$M$};\n\t\t\t\\node[left=3pt] at (N) {$N$};\n\t\t\t\\node[above left] at ($(A)!0.5!(N)$) {$200\\text{m}$};\n\t\t\t\\node[below] at ($(B)!0.5!(M)$) {$600\\text{m}$};\n\t\t\t\\draw[shift={(A)},rotate=-135] (0.3,0) -- (0.3,0.3) -- (0,0.3);\n\t\t\\end{tikzpicture}</script></div>", "choices": ["$2414$ m", "$3414$ m", "$3215$ m", "$4000$ m"], "correctIndex": 0, "explain": "Gọi $P$ là chu vi tam giác $ABC$. Vì vận tốc mỗi người không đổi nên tỉ số quãng đường đi được của Trọng ($s_1$) và tổng quãng đường của hai người ($S$) luôn không đổi.<br>Lần gặp thứ nhất: Trọng đi được $s_1 = AB + BM = a + 600$. Tổng quãng đường hai người đi được đúng bằng một chu vi $S = P$.<br>Lần gặp thứ hai: Hai người chạy ngược chiều nhau trên chu vi tam giác, nên lần gặp thứ hai xảy ra khi tổng quãng đường hai người đi được là $S' = 2P$.<br>Quãng đường Trọng đi được khi đó là $s_1' = P + AN = P + 200$.<br>Do tỉ số vận tốc không đổi, ta có:  $$\\dfrac{s_1}{S} = \\dfrac{s_1'}{S'} \\Leftrightarrow \\dfrac{a+600}{P} = \\dfrac{P+200}{2P} \\Leftrightarrow a+600 = \\dfrac{P+200}{2}.$$  Thay $P = 2a + a\\sqrt{2}$ vào phương trình, ta được:  $$2a + 1200 = 2a + a\\sqrt{2} + 200 \\Leftrightarrow a\\sqrt{2} = 1000 \\Leftrightarrow a = 500\\sqrt{2}.$$  Chu vi của khuôn viên là:  $$P = 2a + a\\sqrt{2} = 1000\\sqrt{2} + 1000 \\approx 2414 \\text{ m.}$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Trên lưới tọa độ $Oxy$, một con kiến di chuyển từ điểm $A(0;0)$ đến điểm $B(5;3)$ bằng cách chỉ di chuyển sang phải hoặc lên trên. Tính số đường đi ngắn nhất từ $A$ đến $B$ sao cho bắt buộc phải đi qua điểm $M(2;1)$.", "choices": ["$120$", "$60$", "$30$", "$45$"], "correctIndex": 2, "explain": "Số cách đi từ $A(0;0)$ đến $M(2;1)$ là $C_{2+1}^1 = C_3^1 = 3$ cách.<br>Số cách đi từ $M(2;1)$ đến $B(5;3)$ là đi thêm $5-2=3$ đơn vị sang phải và $3-1=2$ đơn vị lên trên. Số cách là $C_{3+2}^2 = C_5^2 = 10$ cách.<br>Theo quy tắc nhân, tổng số cách đi là $3\\cdot 10 = 30$ cách."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho phương trình $x^{\\log_2(ax^3)-8}=2021$ với $a$ là số thực dương. Biết tích các nghiệm của phương trình là $32$. Tìm giá trị của $a$.", "choices": ["$a=2$", "$a=-7$", "$a=-8$", "$a=16$"], "correctIndex": 1, "explain": "Điều kiện: $x>0$. Lấy logarit cơ số $2$ hai vế của phương trình $x^{\\log_2(ax^3)-8}=2021$, ta được:  $$\\log_2\\left(x^{\\log_2(ax^3)-8}\\right)=\\log_2 2021 \\Leftrightarrow \\left(\\log_2 a+\\log_2 x^3-8\\right)\\cdot\\log_2 x=\\log_2 2021$$  $$\\Leftrightarrow \\left(3\\log_2 x+\\log_2 a-8\\right)\\cdot\\log_2 x-\\log_2 2021=0$$  Đặt $t=\\log_2 x$, phương trình trở thành:  $$3t^2+(\\log_2 a-8)t-\\log_2 2021=0 \\quad (*)$$  Giả sử phương trình $(*)$ có hai nghiệm $t_1$, $t_2$. Khi đó các nghiệm của phương trình ban đầu là $x_1=2^{t_1}$ và $x_2=2^{t_2}$.<br>Tích các nghiệm của phương trình là: $x_1x_2=2^{t_1}\\cdot 2^{t_2}=2^{t_1+t_2}=32=2^5$.<br>Suy ra $t_1+t_2=5$.<br>Theo định lý Vi-ét cho phương trình $(*)$, ta có:  $$t_1+t_2=-\\dfrac{\\log_2 a-8}{3}$$  $$\\Rightarrow -\\dfrac{\\log_2 a-8}{3}=5 \\Leftrightarrow \\log_2 a-8=-15 \\Leftrightarrow \\log_2 a=-7.$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tìm số nghiệm nguyên dương nhỏ hơn $10$ của bất phương trình $3^{x+1}-2^{2x+1}-12^{\\tfrac{x}{2}}<0$.", "choices": ["$5$", "$7$", "$9$", "$8$"], "correctIndex": 2, "explain": "Bất phương trình đã cho tương đương với:  $$3\\cdot 3^x-2\\cdot 4^x-\\left(\\sqrt{12}\\right)^x < 0 \\Leftrightarrow 3\\cdot 3^x-2\\cdot 4^x-\\left(2\\sqrt{3}\\right)^x < 0$$  Chia cả hai vế cho $4^x > 0$, ta được:  $$3\\cdot \\left(\\dfrac{3}{4}\\right)^x - \\left(\\dfrac{\\sqrt{3}}{2}\\right)^x - 2 < 0$$  Đặt $t = \\left(\\dfrac{\\sqrt{3}}{2}\\right)^x$ ($t>0$). Khi đó $\\left(\\dfrac{3}{4}\\right)^x = t^2$. Bất phương trình trở thành:  $$3t^2-t-2 < 0 \\Leftrightarrow -\\dfrac{2}{3} < t < 1$$  Kết hợp điều kiện $t>0$, ta có $0 < t < 1$.  $$\\Rightarrow \\left(\\dfrac{\\sqrt{3}}{2}\\right)^x < 1 \\Leftrightarrow \\left(\\dfrac{\\sqrt{3}}{2}\\right)^x < \\left(\\dfrac{\\sqrt{3}}{2}\\right)^0$$  Vì cơ số $\\dfrac{\\sqrt{3}}{2} \\approx 0{,}866 < 1$ nên bất phương trình đổi chiều: $x > 0$.<br>Kết hợp điều kiện $x$ là số nguyên dương nhỏ hơn $10$, ta có $x \\in \\{1, 2, 3, 4, 5, 6, 7, 8, 9\\}$.<br>Vậy có $9$ giá trị thỏa mãn."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho các số thực $a$, $b>0$; $a$, $b\\neq 1$ thỏa mãn $\\log_a^2 b-8\\log_b(a\\sqrt[3]{b})=-\\dfrac{8}{3}$. Tính giá trị của biểu thức $P=\\log_a(a\\sqrt[3]{ab})+2019$.", "choices": ["$P=2021$", "$P=2023$", "$P=2019$", "$P=2025$"], "correctIndex": 0, "explain": "Biến đổi giả thiết:  $$\\log_a^2 b-8\\log_b(a\\sqrt[3]{b})=-\\dfrac{8}{3} \\Leftrightarrow \\log_a^2 b-8\\left(\\log_b a+\\log_b b^{\\frac{1}{3}}\\right)+\\dfrac{8}{3}=0$$  $$\\Leftrightarrow \\log_a^2 b-8\\log_b a-8\\cdot\\dfrac{1}{3}+\\dfrac{8}{3}=0 \\Leftrightarrow \\log_a^2 b-\\dfrac{8}{\\log_a b}=0.$$  Đặt $t=\\log_a b$ ($t\\neq 0$), phương trình trở thành:  $$t^2-\\dfrac{8}{t}=0 \\Leftrightarrow t^3=8 \\Leftrightarrow t=2.$$  Suy ra $\\log_a b=2$.<br>Ta có biểu thức $P$:  $$P = \\log_a\\left(a\\cdot a^{\\frac{1}{3}}\\cdot b^{\\frac{1}{3}}\\right)+2019 = \\log_a\\left(a^{\\frac{4}{3}}\\cdot b^{\\frac{1}{3}}\\right)+2019$$  $$P = \\dfrac{4}{3}+\\dfrac{1}{3}\\log_a b+2019.$$  Thay $\\log_a b=2$ vào ta được:  $$P = \\dfrac{4}{3}+\\dfrac{1}{3}\\cdot 2+2019 = \\dfrac{4}{3}+\\dfrac{2}{3}+2019 = 2+2019 = 2021.$$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biết $\\lim\\limits_{x\\to -\\infty}\\dfrac{ax-\\sqrt{4x^2-x+1}}{a^2x-1}=\\dfrac{2}{3}$ với $a-\\dfrac{m+\\sqrt{57}}{n}>0$ và $m$, $n$ là các số nguyên dương. Khi đó giá trị của biểu thức $S=m+n$ là", "choices": ["$5$", "$6$", "$7$", "$8$"], "correctIndex": 2, "explain": "Ta có:  $$L=\\lim\\limits_{x\\to -\\infty}\\dfrac{ax-\\sqrt{4x^2-x+1}}{a^2x-1}=\\lim\\limits_{x\\to -\\infty}\\dfrac{ax-|x|\\sqrt{4-\\dfrac{1}{x}+\\dfrac{1}{x^2}}}{x\\left(a^2-\\dfrac{1}{x}\\right)}$$  Vì $x\\to -\\infty$ nên $|x|=-x$, do đó:  $$L=\\lim\\limits_{x\\to -\\infty}\\dfrac{ax+x\\sqrt{4-\\dfrac{1}{x}+\\dfrac{1}{x^2}}}{x\\left(a^2-\\dfrac{1}{x}\\right)}=\\lim\\limits_{x\\to -\\infty}\\dfrac{a+\\sqrt{4-\\dfrac{1}{x}+\\dfrac{1}{x^2}}}{a^2-\\dfrac{1}{x}}=\\dfrac{a+2}{a^2}$$  Theo giả thiết, ta có:  $$\\dfrac{a+2}{a^2}=\\dfrac{2}{3}\\Leftrightarrow 2a^2-3a-6=0\\Leftrightarrow\\hoac{&a=\\dfrac{3+\\sqrt{57}}{4}<br>&a=\\dfrac{3-\\sqrt{57}}{4}}$$  Theo điều kiện $a-\\dfrac{m+\\sqrt{57}}{n}>0$ và $m$, $n$ là số nguyên dương, ta suy ra:  $a=\\dfrac{3+\\sqrt{57}}{4}\\Rightarrow m=3$, $n=4$.<br>Vậy $S=m+n=3+4=7$."}]}, {"noiDungChung": "Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình thoi cạnh $a$, $\\widehat{ABC}=60^{\\circ}$, mặt bên $SAB$ là tam giác đều và nằm trong mặt phẳng vuông góc với mặt phẳng đáy. Gọi $H$ là trung điểm của $AB$.", "cauHoi": [{"question": "Tính thể tích $V$ của khối chóp $S.ABCD$ theo $a$.", "choices": ["$V=\\dfrac{a^3}{4}$", "$V=\\dfrac{a^3\\sqrt{3}}{6}$", "$V=\\dfrac{a^3}{2}$", "$V=\\dfrac{a^3\\sqrt{3}}{4}$"], "correctIndex": 0, "explain": "Diện tích đáy $S_{ABCD}=2S_{ABC}=2\\cdot\\dfrac{a^2\\sqrt{3}}{4}=\\dfrac{a^2\\sqrt{3}}{2}$.<br>Vì $(SAB)\\perp(ABCD)$ và $(SAB)\\cap(ABCD)=AB$, tam giác $SAB$ đều có $SH\\perp AB$ nên $SH\\perp(ABCD)$.<br>Tam giác $SAB$ đều cạnh $a$ nên $SH=\\dfrac{a\\sqrt{3}}{2}$.<br>Thể tích khối chóp $V=\\dfrac{1}{3}S_{ABCD}\\cdot SH=\\dfrac{1}{3}\\cdot\\dfrac{a^2\\sqrt{3}}{2}\\cdot\\dfrac{a\\sqrt{3}}{2}=\\dfrac{a^3}{4}$<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1.2, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (A) at (0,0);\n\t\t\t\t\t\\coordinate (B) at (-1.5,-1.5);\n\t\t\t\t\t\\coordinate (C) at (2,-1.5);\n\t\t\t\t\t\\coordinate (D) at ($(A)+(C)-(B)$); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (H) at ($(A)!0.5!(B)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (S) at ($(H)+(0,3.5)$); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed, thin] (S)--(A) (A)--(B) (A)--(D) (S)--(H) (B)--(D) (A)--(C);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick] (S)--(B) (S)--(C) (S)--(D) (B)--(C) (C)--(D);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed] ($(H)+(0,0.2)$)-|($(H)+(0.2,0)$); \n\t\t\t\t\t\n\t\t\t\t\t\\draw (H) ++(0,0.2) -- ++(0.2,0) -- ++(0,-0.2);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\foreach \\p in {S,A,B,C,D,H}\n\t\t\t\t\t\\fill[red] (\\p) circle (1.5pt);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\node[above] at (S) {$S$};\n\t\t\t\t\t\\node[below] at (B) {$B$};\n\t\t\t\t\t\\node[below] at (C) {$C$};\n\t\t\t\t\t\\node[right] at (D) {$D$};\n\t\t\t\t\t\\node[above left] at (A) {$A$};\n\t\t\t\t\t\\node[left] at (H) {$H$};\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw (B) ++(0:0.4) arc (0:45:0.4); \n\t\t\t\t\t\\node at ($(B)+(0.6,0.3)$) {$60^\\circ$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Tính khoảng cách $d$ từ điểm $D$ đến mặt phẳng $(SBC)$.", "choices": ["$d=\\dfrac{a\\sqrt{21}}{7}$", "$d=\\dfrac{a\\sqrt{3}}{2}$", "$d=\\dfrac{3a}{2\\sqrt{7}}$", "$d=\\dfrac{a\\sqrt{3}}{4}$"], "correctIndex": 2, "explain": "Ta có $AD\\parallel BC\\Rightarrow AD\\parallel(SBC)\\Rightarrow d(D,(SBC))=d(A,(SBC))$.<br>Vì $H$ là trung điểm $AB$ nên $d(A,(SBC))=2d(H,(SBC))$.<br>Kẻ $HK\\perp BC$ tại $K$, kẻ $HI\\perp SK$ tại $I$. Khi đó $d(H,(SBC))=HI$.<br>Trong $\\triangle HBK$ vuông tại $K$: $HK=HB\\cdot\\sin 60^{\\circ}=\\dfrac{a\\sqrt{3}}{4}$.<br>Trong $\\triangle SHK$ vuông tại $H$: $\\dfrac{1}{HI^2}=\\dfrac{1}{SH^2}+\\dfrac{1}{HK^2}=\\dfrac{1}{\\left(\\dfrac{a\\sqrt{3}}{2}\\right)^2}+\\dfrac{1}{\\left(\\dfrac{a\\sqrt{3}}{4}\\right)^2}=\\dfrac{20}{3a^2}\\Rightarrow HI=\\dfrac{a\\sqrt{3}}{2\\sqrt{5}}$.<br>Sử dụng phương pháp thể tích từ câu trên: $V_{S.HBC}=\\dfrac{1}{4}V_{S.ABCD}=\\dfrac{a^3}{16}$.<br>Diện tích $\\triangle SBC$ có $SB=a$, $BC=a$, $SC=\\sqrt{SH^2+HC^2}=\\dfrac{a\\sqrt{6}}{2}$ (với $HC = \\dfrac{a\\sqrt{3}}{2}$).<br>$S_{SBC}=\\dfrac{a^2\\sqrt{7}}{4}$.<br>$d(H,(SBC))=\\dfrac{3V_{S.HBC}}{S_{SBC}}=\\dfrac{3a}{4\\sqrt{7}}$.<br>Vậy $d(D,(SBC))=2\\cdot\\dfrac{3a}{4\\sqrt{7}}=\\dfrac{3a}{2\\sqrt{7}}$"}, {"question": "Gọi $\\alpha$ là số đo góc nhị diện $[A, SC, B]$. Tính $\\cos\\alpha$.", "choices": ["$\\cos\\alpha=\\dfrac{2}{7}$", "$\\cos\\alpha=\\dfrac{3}{7}$", "$\\cos\\alpha=\\dfrac{\\sqrt{3}}{7}$", "$\\cos\\alpha=\\dfrac{4}{7}$"], "correctIndex": 1, "explain": "Gọi $V$ là thể tích khối chóp $S.ABC$, ta có $V_{S.ABC} = \\dfrac{1}{2}V_{S.ABCD} = \\dfrac{a^3}{8}$.<br>Mặt khác, thể tích khối tứ diện $S.ABC$ tính theo công thức nhị diện: $V_{S.ABC} = \\dfrac{2 S_{SAC} \\cdot S_{SBC} \\cdot \\sin\\alpha}{3 SC}$.<br>Xét các tam giác:<br>+ $\\triangle SBC$ có $SB=a, BC=a, SC=\\dfrac{a\\sqrt{6}}{2} \\Rightarrow S_{SBC} = \\dfrac{a^2\\sqrt{7}}{4}$.<br>+ $\\triangle SAC$ có $SA=a, AC=a, SC=\\dfrac{a\\sqrt{6}}{2} \\Rightarrow S_{SAC} = \\dfrac{a^2\\sqrt{7}}{4}$.<br>Thay vào công thức: $\\dfrac{a^3}{8} = \\dfrac{2 \\cdot \\dfrac{a^2\\sqrt{7}}{4} \\cdot \\dfrac{a^2\\sqrt{7}}{4} \\cdot \\sin\\alpha}{3 \\cdot \\dfrac{a\\sqrt{6}}{2}} \\Rightarrow \\sin\\alpha = \\dfrac{2\\sqrt{10}}{7}$.<br>Suy ra $\\cos^2\\alpha = 1 - \\sin^2\\alpha = 1 - \\dfrac{40}{49} = \\dfrac{9}{49} \\Rightarrow \\cos\\alpha = \\dfrac{3}{7}$."}]}, {"noiDungChung": "Một dây chuyền sản xuất linh kiện điện tử có tỉ lệ sản phẩm lỗi là $0{,}5\\%$. Để kiểm tra chất lượng, người ta dùng một thiết bị cảm biến tự động. Thiết bị này có khả năng phát hiện đúng $98\\%$ sản phẩm lỗi. Tuy nhiên, đối với các sản phẩm không lỗi, thiết bị vẫn đưa ra cảnh báo nhầm là có lỗi với tỉ lệ $4\\%$. Chọn ngẫu nhiên một linh kiện sau khi qua thiết bị cảm biến.", "cauHoi": [{"question": "Xác suất để một linh kiện được thiết bị đánh giá là \"Không lỗi\" là bao nhiêu?", "choices": ["$0{,}9452$", "$0{,}9553$", "$0{,}9600$", "$0{,}9504$"], "correctIndex": 1, "explain": "Gọi $A$ là biến cố \"Linh kiện bị lỗi\", suy ra $P(A) = 0{,}005$ và $P(\\overline{A}) = 0{,}995$.<br>Gọi $B$ là biến cố \"Thiết bị cảnh báo có lỗi\".<br>Theo giả thiết: $P(B|A) = 0{,}98 \\Rightarrow P(\\overline{B}|A) = 0{,}02$ (lỗi nhưng không phát hiện).<br>$P(B|\\overline{A}) = 0{,}04 \\Rightarrow P(\\overline{B}|\\overline{A}) = 0{,}96$ (không lỗi và thiết bị báo đúng).<br>Xác suất để linh kiện được đánh giá \"Không lỗi\" là:  $$P(\\overline{B}) = P(A) \\cdot P(\\overline{B}|A) + P(\\overline{A}) \\cdot P(\\overline{B}|\\overline{A})$$  $$P(\\overline{B}) = 0{,}005 \\cdot 0{,}02 + 0{,}995 \\cdot 0{,}96 = 0{,}0001 + 0{,}9552 = 0{,}9553.$$"}, {"question": "Giả sử linh kiện được thiết bị đánh giá là \"Không lỗi\". Xác suất linh kiện này thực chất vẫn bị lỗi là bao nhiêu (làm tròn kết quả đến hàng phần mười nghìn)?", "choices": ["$0{,}0001$", "$0{,}0105$", "$0{,}0200$", "$0{,}0005$"], "correctIndex": 0, "explain": "Ta cần tính xác suất có điều kiện $P(A|\\overline{B})$.<br>Theo công thức Bayes, ta có:  $$P(A|\\overline{B}) = \\dfrac{P(A) \\cdot P(\\overline{B}|A)}{P(\\overline{B})} = \\dfrac{0{,}005 \\cdot 0{,}02}{0{,}9553} \\approx 0{,}0001046.$$  Làm tròn đến hàng phần mười nghìn, ta được kết quả là $0{,}0001$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một nhà máy sản xuất nhiên liệu sinh học bằng cách pha hai nguyên liệu là chất $A$ và chất $B$ với nhau. Hiện tại, trong kho có $135$ lít chất $A$ và $615$ lít chất $B$. Để tạo ra nhiên liệu loại $I$ thì tỉ lệ chất $A$ và chất $B$ là $1:9$. Để tạo ra nhiên liệu loại $II$ thì tỉ lệ chất $A$ và chất $B$ là $1:3$. Nếu sử dụng hết chất $A$ và chất $B$ thì có thể sản xuất được $a$ lít nhiên liệu loại $I$ và $b$ lít nhiên liệu loại $II$. Tính chênh lệch giữa $a$ và $b$.", "choices": ["$100$", "$150$", "$200$", "$230$"], "correctIndex": 1, "explain": "Gọi $x$ là số lít nhiên liệu loại $I$ và $y$ là số lít nhiên liệu loại $II$ cần sản xuất ($x,y>0$).<br>Trong nhiên liệu loại $I$, tỉ lệ $A:B$ là $1:9$, tổng số phần là $10$.  <br>Vậy lượng chất $A$ trong $x$ lít loại $I$ là $\\dfrac{x}{10}$ và lượng chất $B$ là $\\dfrac{9x}{10}$.<br>Trong nhiên liệu loại $II$, tỉ lệ $A:B$ là $1:3$, tổng số phần là $4$.  <br>Vậy lượng chất $A$ trong $y$ lít loại $II$ là $\\dfrac{y}{4}$ và lượng chất $B$ là $\\dfrac{3y}{4}$.<br>Vì sử dụng hết $135$ lít chất $A$ và $615$ lít chất $B$, ta có hệ phương trình:  <br>$\\heva{&\\dfrac{x}{10}+\\dfrac{y}{4}=135\\\\&\\dfrac{9x}{10}+\\dfrac{3y}{4}=615} \\Leftrightarrow \\heva{&2x+5y=2700\\\\&18x+15y=12300} \\Leftrightarrow \\heva{&x=300\\\\&y=450}$.  <br>Vậy sản xuất được $300$ lít nhiên liệu loại $I$ và $450$ lít nhiên liệu loại $II$."}]}, {"noiDungChung": "Một cơ sở thủ công mỹ nghệ sản xuất ba loại sản phẩm: Túi cói, Giỏ mây và Khay gỗ. Lợi nhuận từ mỗi túi cói là $50$ ngàn đồng, giỏ mây là $40$ ngàn đồng và khay gỗ là $60$ ngàn đồng. Do nguồn lực có hạn, cơ sở đưa ra các điều kiện ràng buộc:<br>a) Tổng số túi cói và giỏ mây không quá $20$ chiếc.  <br>b) Số khay gỗ sản xuất luôn bằng đúng một nửa tổng số túi cói và giỏ mây cộng lại.  <br>c) Tổng thời gian hoàn thiện túi cói là $2$ giờ/chiếc, giỏ mây là $1$ giờ/chiếc và khay gỗ là $4$ giờ/chiếc. Tổng quỹ thời gian của cơ sở không quá $80$ giờ.  <br>d) Cơ sở cam kết sản xuất ít nhất $4$ túi cói và $6$ giỏ mây.<br>Gọi $x$, $y$ lần lượt là số lượng túi cói và giỏ mây ($x, y \\in \\mathbb{N}$).", "cauHoi": [{"question": "Hãy thiết lập hệ bất phương trình ràng buộc theo hai biến $x$ và $y$ sau khi đã quy đổi số lượng Khay gỗ theo $x$ và $y$.", "choices": ["$\\heva{&x\\geq 4\\\\&y\\geq 6\\\\&x+y\\leq 20\\\\&4x+3y\\leq 80}$", "$\\heva{&x\\geq 4\\\\&y\\geq 6\\\\&x+y\\leq 20\\\\&2x+y\\leq 80}$", "$\\heva{&x\\geq 4\\\\&y\\geq 6\\\\&x+y\\leq 20\\\\&3x+4y\\leq 80}$", "$\\heva{&x\\geq 0\\\\&y\\geq 0\\\\&x+y\\leq 20\\\\&4x+3y\\leq 80}$"], "correctIndex": 0, "explain": "Gọi $z$ là số lượng khay gỗ, ta có $z = \\dfrac{x+y}{2}$. Thay vào các điều kiện đề bài:<br>a) Cam kết sản xuất: $x \\geq 4$ và $y \\geq 6$.  <br>b) Giới hạn số lượng: $x+y \\leq 20$.  <br>c) Giới hạn thời gian: $2x+y+4z \\leq 80 \\Rightarrow 2x+y+4\\left(\\dfrac{x+y}{2}\\right) \\leq 80 \\Leftrightarrow 4x+3y \\leq 80$.<br>Hệ bất phương trình ràng buộc là: $\\heva{&x\\geq 4\\\\&y\\geq 6\\\\&x+y\\leq 20\\\\&4x+3y\\leq 80.}$"}, {"question": "Hãy tìm số lượng túi cói và giỏ mây cần sản xuất để cơ sở đạt lợi nhuận lớn nhất.", "choices": ["$x=4$, $y=16$", "$x=10$, $y=10$", "$x=20$, $y=0$", "$x=14$, $y=6$"], "correctIndex": 3, "explain": "Hàm lợi nhuận: $L = 50x+40y+60\\left(\\dfrac{x+y}{2}\\right) = 80x+70y$ (ngàn đồng).<br>Miền nghiệm của hệ là miền tam giác $MNP$ (hình vẽ) với các đỉnh:<br>a) $M(4;6)$ là giao của $x=4$ và $y=6$.  <br>b) $N(14;6)$ là giao của $x+y=20$ và $y=6$.  <br>c) $P(4;16)$ là giao của $x=4$ và $x+y=20$.<br>(Lưu ý: Đường $4x+3y=80$ không cắt miền nghiệm tam giác $MNP$ vì tại các đỉnh của tam giác, biểu thức $4x+3y$ luôn nhỏ hơn hoặc bằng $80$).<br>Tính giá trị lợi nhuận tại các đỉnh:<br>a) Tại $M(4;6)$: $L = 80(4)+70(6) = 740$.  <br>b) Tại $N(14;6)$: $L = 80(14)+70(6) = 1540$.  <br>c) Tại $P(4;16)$: $L = 80(4)+70(16) = 1440$.<br>Vậy lợi nhuận lớn nhất đạt $1540$ ngàn đồng khi $x=14$ và $y=6$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, x=0.4cm, y=0.4cm, font=\\footnotesize]\n\t\t\t\t\t\\draw[color=gray!20, step=1] (-1,-1) grid (21,21);\n\t\t\t\t\t\\draw[->, thick] (-1,0) -- (21,0) node[below] {$x$};\n\t\t\t\t\t\\draw[->, thick] (0,-1) -- (0,21) node[left] {$y$};\n\t\t\t\t\t\\node[below left] at (0,0) {$O$};\n\t\t\t\t\t\\fill[blue!15] (4,6) -- (14,6) -- (4,16) -- cycle;\n\t\t\t\t\t\\draw[blue!50, pattern=north east lines, pattern color=blue!30] (4,6) -- (14,6) -- (4,16) -- cycle;\n\t\t\t\t\t\\draw[thick, blue] plot[domain=0:20] (\\x,{20-\\x}) node[right] {$x+y=20$};\n\t\t\t\t\t\\draw[thick, red] plot[domain=0:18] (\\x,{(80-4*\\x)/3}) node[above right] {$4x+3y=80$};\n\t\t\t\t\t\\draw[thick, dashed] (4,0) -- (4,20) node[above] {$x=4$};\n\t\t\t\t\t\\draw[thick, dashed] (0,6) -- (20,6) node[right] {$y=6$};\n\t\t\t\t\t\\filldraw[black] (4,6) circle (1.5pt) node[below left] {$M(4;6)$};\n\t\t\t\t\t\\filldraw[black] (14,6) circle (1.5pt) node[below right] {$N(14;6)$};\n\t\t\t\t\t\\filldraw[black] (4,16) circle (1.5pt) node[left] {$P(4;16)$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Trong một thí nghiệm vật lý, một vật nặng được treo vào đầu một lò xo đang dao động điều hòa theo phương thẳng đứng. Vị trí của vật tại thời điểm $t$ (giây) được xác định bởi hàm số $s(t) = 5\\cos\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)$ (cm).", "cauHoi": [{"question": "Vận tốc của vật tại thời điểm $t$ được xác định bởi công thức nào sau đây?", "choices": ["$v(t) = 10\\pi\\sin\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)$", "$v(t) = -10\\pi\\sin\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)$", "$v(t) = 5\\sin\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)$", "$v(t) = -5\\pi\\sin\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)$"], "correctIndex": 1, "explain": "Vận tốc là đạo hàm của quãng đường theo thời gian:  <br>$v(t) = s'(t) = \\left[5\\cos\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)\\right]' = 5 \\cdot \\left[-\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)' \\cdot \\sin\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)\\right]$.  <br>$\\Rightarrow v(t) = -10\\pi\\sin\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)\\text{ (cm/s)}$."}, {"question": "Gia tốc của vật tại thời điểm $t = 0{,}5$ giây có giá trị xấp xỉ là", "choices": ["$a \\approx 85{,}5\\text{ cm/s}^2$", "$a \\approx -197{,}4\\text{ cm/s}^2$", "$a \\approx -98{,}7\\text{ cm/s}^2$", "$a \\approx 98{,}7\\text{ cm/s}^2$"], "correctIndex": 3, "explain": "Gia tốc là đạo hàm của vận tốc:  <br>$a(t) = v'(t) = \\left[-10\\pi\\sin\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)\\right]' = -20\\pi^2\\cos\\left(2\\pi t + \\dfrac{\\pi}{3}\\right)$.  <br>Tại $t = 0{,}5$ giây:  <br>$a(0{,}5) = -20\\pi^2\\cos\\left(2\\pi \\cdot 0{,}5 + \\dfrac{\\pi}{3}\\right) = -20\\pi^2\\cos\\left(\\pi + \\dfrac{\\pi}{3}\\right) = -20\\pi^2 \\cdot \\left(-\\dfrac{1}{2}\\right) = 10\\pi^2$.  <br>Với $\\pi^2 \\approx 9{,}87$, ta có $a(0{,}5) \\approx 98{,}7\\text{ (cm/s}^2\\text{)}$."}]}, {"noiDungChung": "Trong không gian với hệ tọa độ $Oxyz$, cho điểm $M(1;9;4)$. Gọi $(P)$ là mặt phẳng đi qua điểm $M$ và cắt các trục tọa độ $Ox, Oy, Oz$ lần lượt tại các điểm $A, B, C$ khác gốc tọa độ $O$.", "cauHoi": [{"question": "Có bao nhiêu mặt phẳng $(P)$ thỏa mãn điều kiện $OA=OB=OC$?", "choices": ["$1$", "$3$", "$4$", "$2$"], "correctIndex": 2, "explain": "Gọi $A(a;0;0), B(0;b;0), C(0;0;c)$. Mặt phẳng $(P)\\colon \\dfrac{x}{a}+\\dfrac{y}{b}+\\dfrac{z}{c}=1$.<br>Vì $M(1;9;4) \\in (P)$ nên $\\dfrac{1}{a}+\\dfrac{9}{b}+\\dfrac{4}{c}=1$.<br>Từ giả thiết $OA=OB=OC \\Rightarrow |a|=|b|=|c|$.<br>Xét các trường hợp về dấu:<br>a) $a=b=c \\Rightarrow \\dfrac{14}{a}=1 \\Rightarrow a=14$.  <br>b) $a=b=-c \\Rightarrow \\dfrac{6}{a}=1 \\Rightarrow a=6$.  <br>c) $a=-b=c \\Rightarrow \\dfrac{-4}{a}=1 \\Rightarrow a=-4$.  <br>d) $a=-b=-c \\Rightarrow \\dfrac{-12}{a}=1 \\Rightarrow a=-12$.<br>Các trường hợp khác như $-a=b=c$ tương đương với các trường hợp trên. Vậy có $4$ mặt phẳng."}, {"question": "Viết phương trình đường thẳng $\\Delta$ đi qua điểm $M(1;9;4)$ và vuông góc với mặt phẳng $(\\alpha)\\colon 2x-y+3z+1=0$.", "choices": ["$\\Delta\\colon \\dfrac{x-1}{2}=\\dfrac{y-9}{1}=\\dfrac{z-4}{3}$", "$\\Delta\\colon \\dfrac{x-1}{2}=\\dfrac{y-9}{-1}=\\dfrac{z-4}{3}$", "$\\Delta\\colon \\dfrac{x+1}{2}=\\dfrac{y+9}{-1}=\\dfrac{z+4}{3}$", "$\\Delta\\colon \\dfrac{x-2}{1}=\\dfrac{y+1}{9}=\\dfrac{z-3}{4}$"], "correctIndex": 1, "explain": "Mặt phẳng $(\\alpha)$ có véc-tơ pháp tuyến $\\vec{n}_{\\alpha}=(2;-1;3)$.<br>Vì đường thẳng $\\Delta$ vuông góc với mặt phẳng $(\\alpha)$ nên $\\Delta$ có véc-tơ chỉ phương $\\vec{u}_{\\Delta}=\\vec{n}_{\\alpha}=(2;-1;3)$.<br>Đường thẳng $\\Delta$ đi qua $M(1;9;4)$ nên có phương trình chính tắc là:<br>$\\dfrac{x-1}{2}=\\dfrac{y-9}{-1}=\\dfrac{z-4}{3}$"}, {"question": "Tìm tọa độ điểm $N$ thuộc trục $Oz$ sao cho $|\\vec{NM} + 2\\vec{NO}|$ đạt giá trị nhỏ nhất.", "choices": ["$N(0;0;1)$", "$N(0;0;2)$", "$N\\left(0;0;\\dfrac{4}{3}\\right)$", "$N(0;0;4)$"], "correctIndex": 2, "explain": "Gọi $N(0;0;z) \\in Oz$. Ta có $\\vec{NM} = (1;9;4-z)$ và $\\vec{NO} = (0;0;-z)$.<br>Suy ra $\\vec{NM} + 2\\vec{NO} = (1;9;4-3z)$.<br>Khi đó $|\\vec{NM} + 2\\vec{NO}| = \\sqrt{1^2 + 9^2 + (4-3z)^2} = \\sqrt{82 + (4-3z)^2}$.<br>Biểu thức này đạt giá trị nhỏ nhất khi $4-3z = 0 \\Leftrightarrow z = \\dfrac{4}{3}$.<br>Vậy tọa độ điểm $N\\left(0;0;\\dfrac{4}{3}\\right)$"}]}, {"noiDungChung": "Trong mặt phẳng tọa độ $Oxy$, cho hai đường tròn $(C_1) \\colon (x-2)^2+(y-3)^2=2$ và $(C_2) \\colon (x-1)^2+(y-2)^2=8$.", "cauHoi": [{"question": "Xét vị trí tương đối giữa hai đường tròn $(C_1)$ và $(C_2)$.", "choices": ["Hai đường tròn cắt nhau tại hai điểm phân biệt", "Hai đường tròn ở ngoài nhau", "Hai đường tròn tiếp xúc ngoài với nhau", "Hai đường tròn tiếp xúc trong với nhau"], "correctIndex": 3, "explain": "Ta có $I_1(2;3)$, $I_2(1;2) \\Rightarrow I_1I_2=\\sqrt{(1-2)^2+(2-3)^2}=\\sqrt{2}$.<br>Bán kính $R_1=\\sqrt{2}$, $R_2=\\sqrt{8}=2\\sqrt{2}$.<br>Hiệu hai bán kính: $|R_2-R_1|=|2\\sqrt{2}-\\sqrt{2}|=\\sqrt{2}$.<br>Vì $I_1I_2=|R_2-R_1|=\\sqrt{2}$ nên hai đường tròn $(C_1)$ và $(C_2)$ tiếp xúc trong với nhau."}, {"question": "Gọi $M$ là tiếp điểm của $(C_1)$ và $(C_2)$. Khẳng định nào sau đây là đúng?", "choices": ["$\\vec{I_2M}=\\vec{I_1I_2}$", "$\\vec{I_2M}=2\\vec{I_2I_1}$", "$\\vec{I_1M}=2\\vec{I_2I_1}$", "$\\vec{I_2I_1}=2\\vec{I_1M}$"], "correctIndex": 1, "explain": "Vì $(C_1)$ tiếp xúc trong với $(C_2)$ và $R_2=2R_1$ nên tâm $I_1$ nằm giữa tâm $I_2$ và tiếp điểm $M$.<br>Ta có $I_2M=R_2=2\\sqrt{2}$ và $I_2I_1=\\sqrt{2}$.<br>Do $I_2$, $I_1$, $M$ thẳng hàng theo thứ tự đó nên $\\vec{I_2M}$ và $\\vec{I_2I_1}$ cùng hướng.<br>Suy ra $\\vec{I_2M}=\\dfrac{I_2M}{I_2I_1}\\vec{I_2I_1}=2\\vec{I_2I_1}$."}, {"question": "Viết phương trình các tiếp tuyến chung của hai đường tròn $(C_1)$ và $(C_2)$.", "choices": ["$x+y-7=0$", "$x+y-3=0$ và $x-y+1=0$", "$x+y-5=0$ và $x-y+1=0$", "$x-y+1=0$"], "correctIndex": 0, "explain": "$(C_1)$ có tâm $I_1(2;3)$, $R_1=\\sqrt{2}$. $(C_2)$ có tâm $I_2(1;2)$, $R_2=2\\sqrt{2}$.<br>Vì hai đường tròn tiếp xúc trong nên chỉ có duy nhất $1$ tiếp tuyến chung tại tiếp điểm $M$.<br>Từ $\\vec{I_2M}=2\\vec{I_2I_1} \\Rightarrow \\heva{&x_M-1=2(2-1)\\\\&y_M-2=2(3-2)} \\Rightarrow \\heva{&x_M=3\\\\&y_M=4.}$<br>Tiếp tuyến chung $\\Delta$ đi qua $M(3;4)$ và vuông góc với đường nối tâm $I_1I_2$.<br>Vectơ pháp tuyến $\\vec{n}=\\vec{I_2I_1}=(1;1)$.<br>Phương trình $\\Delta \\colon 1(x-3)+1(y-4)=0 \\Leftrightarrow x+y-7=0$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho $16$ phiếu ghi các số thứ tự từ $1$ đến $16$. Lấy lần lượt $8$ phiếu không hoàn lại, gọi $a_i$ là số ghi trên phiếu thứ $i$ lấy được ($1 \\le i \\le 8$). Tính xác suất $P$ để $8$ phiếu lấy được thỏa mãn $a_1<a_2<\\dots<a_8$ và không có bất kỳ hai phiếu nào có tổng các số bằng $17$.", "choices": ["$P=\\dfrac{2^8}{C_{16}^8}$", "$P=\\dfrac{3^8}{C_{16}^8}$", "$P=\\dfrac{2^8}{A_{16}^8}$", "$P=\\dfrac{3^8}{C_{16}^8 \\cdot 8!}$"], "correctIndex": 2, "explain": "Số cách lấy lần lượt $8$ phiếu từ $16$ phiếu (có tính thứ tự) là $n(\\Omega) = A_{16}^8$.<br>Xét điều kiện $a_1 < a_2 < \\dots < a_8$:<br>a) Nếu ta chọn được một tập hợp gồm $8$ số phân biệt, thì chỉ có duy nhất một cách sắp xếp chúng theo thứ tự tăng dần thỏa mãn yêu cầu đề bài.  <br>b) Do đó, số tập hợp thỏa mãn điều kiện thứ tự và điều kiện tổng chính là số cách chọn $8$ số từ $16$ số ban đầu.<br>Xét điều kiện không có hai phiếu nào có tổng bằng $17$:<br>a) Các cặp số có tổng bằng $17$ trong tập $\\{1; 2; \\dots; 16\\}$ là:  $\\{1; 16\\}, \\{2; 15\\}, \\{3; 14\\}, \\{4; 13\\}, \\{5; 12\\}, \\{6; 11\\}, \\{7; 10\\}, \\{8; 9\\}$.  <br>b) Có tất cả $8$ cặp như vậy. Để trong $8$ phiếu lấy ra không có cặp nào có tổng bằng $17$, thì từ mỗi cặp số trên, ta chỉ được phép chọn đúng một số.  <br>c) Mỗi cặp có $2$ cách chọn ($2$ lựa chọn), và có $8$ cặp, nên số tập hợp thỏa mãn là $2 \\cdot 2 \\cdot 2 \\cdot 2 \\cdot 2 \\cdot 2 \\cdot 2 \\cdot 2 = 2^8$ tập hợp.<br>Vì mỗi tập hợp $8$ phần tử này chỉ có $1$ cách duy nhất để sắp xếp theo thứ tự $a_1 < a_2 < \\dots < a_8$, nên số biến cố thuận lợi là $n(A) = 2^8$.<br>Vậy xác suất cần tìm là $P = \\dfrac{n(A)}{n(\\Omega)} = \\dfrac{2^8}{A_{16}^8}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một đôi thỏ cứ mỗi tháng đẻ được một đôi thỏ con; mỗi đôi thỏ con, khi tròn $2$ tháng tuổi, lại mỗi tháng đẻ ra một đôi thỏ con, và quá trình sinh nở cứ thế tiếp diễn. Nếu đầu năm có một đôi thỏ sơ sinh và trong năm đó không có con thỏ nào chết thì sau $1$ năm ($12$ tháng) sẽ có tất cả bao nhiêu đôi thỏ?", "choices": ["$233$ đôi thỏ", "$144$ đôi thỏ", "$377$ đôi thỏ", "$154$ đôi thỏ"], "correctIndex": 0, "explain": "Gọi $F_n$ là số đôi thỏ có ở tháng thứ $n$. Theo giả thiết bài toán:<br>a) Tháng thứ $1$: Có $1$ đôi thỏ sơ sinh ($F_1=1$).  <br>b) Tháng thứ $2$: Đôi thỏ này chưa đủ $2$ tháng tuổi nên chưa đẻ, vẫn chỉ có $1$ đôi ($F_2=1$).  <br>c) Tháng thứ $3$: Đôi thỏ đầu tiên tròn $2$ tháng tuổi và đẻ ra đôi thứ hai, tổng cộng có $2$ đôi ($F_3=2$).  <br>d) Tháng thứ $4$: Đôi thỏ đầu tiên tiếp tục đẻ, đôi thứ hai chưa đủ tuổi, tổng cộng có $3$ đôi ($F_4=3$).<br>Quy luật này tạo thành dãy số Fibonacci với công thức truy hồi: $F_n=F_{n-1}+F_{n-2}$ (với $n \\geq 3$).  Dãy số cụ thể qua các tháng như sau:  $F_1=1$; $F_2=1$; $F_3=2$; $F_4=3$; $F_5=5$; $F_6=8$; $F_7=13$; $F_8=21$; $F_9=34$; $F_{10}=55$; $F_{11}=89$; $F_{12}=144$.  Tuy nhiên, bài toán hỏi sau $1$ năm (tức là tính cả kết quả của tháng thứ $12$ sinh sản để bước sang tháng thứ $13$), số đôi thỏ sẽ là giá trị của $F_{13}$.  Ta có $F_{13}=F_{12}+F_{11}=144+89=233$.  Vậy sau $1$ năm sẽ có $233$ đôi thỏ."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ vuông cân tại $A$ có $AB=AC=30$ cm. Hai đường trung tuyến $BF$ và $CE$ cắt nhau tại $G$. Diện tích tam giác $GFC$ bằng", "choices": ["$75$ cm$^2$", "$150$ cm$^2$", "$50$ cm$^2$", "$100$ cm$^2$"], "correctIndex": 0, "explain": "Diện tích tam giác $ABC$ là $S_{\\triangle ABC}=\\dfrac{1}{2}AB\\cdot AC = \\dfrac{1}{2}\\cdot 30\\cdot 30 = 450$ cm$^2$.<br>Vì $F$ là trung điểm của $AC$ nên $S_{\\triangle BFC}=\\dfrac{1}{2}S_{\\triangle ABC} = \\dfrac{1}{2}\\cdot 450 = 225$ cm$^2$.<br>Vì $G$ là trọng tâm của tam giác $ABC$ nên $GF = \\dfrac{1}{3}BF$.<br>Xét hai tam giác $GFC$ và $BFC$ có chung đường cao hạ từ $C$ xuống $BF$, ta có:  $S_{\\triangle GFC} = \\dfrac{GF}{BF}S_{\\triangle BFC} = \\dfrac{1}{3}S_{\\triangle BFC} = \\dfrac{1}{3}\\cdot 225 = 75$ cm$^2$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, font=\\footnotesize, line join=round, line cap=round]\n\t\t\t\t\\coordinate (A) at (0,3);\n\t\t\t\t\\coordinate (B) at (0,0);\n\t\t\t\t\\coordinate (C) at (3,0);\n\t\t\t\t\\coordinate (E) at ($(A)!0.5!(B)$);\n\t\t\t\t\\coordinate (F) at ($(A)!0.5!(C)$);\n\t\t\t\t\\coordinate (G) at (intersection of B--F and C--E);\n\t\t\t\t\\draw (A)--(B)--(C)--cycle;\n\t\t\t\t\\draw (B)--(F) (C)--(E);\n\t\t\t\t\\foreach \\p/\\pos in {A/above, B/left, C/right, E/left, F/right, G/below}\n\t\t\t\t\\fill (\\p) circle (1.5pt) node[\\pos] {$\\p$};\n\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Cho hai hàm số $f(x)=2^{x^2-4x+5}$ và $g(x)=\\ln(x^2-4x+5)$. Gọi $(C_1)$, $(C_2)$ lần lượt là đồ thị của hai hàm số đã cho.", "cauHoi": [{"question": "Mệnh đề nào sau đây là đúng về tính đơn điệu của hàm số $h(x)=f(x) \\cdot g(x)$ trên khoảng $(-\\infty;2)$?", "choices": ["Hàm số $h(x)$ đồng biến trên khoảng $(-\\infty;2)$", "Hàm số $h(x)$ nghịch biến trên khoảng $(-\\infty;2)$", "Hàm số $h(x)$ không xác định trên khoảng $(-\\infty;2)$", "Hàm số $h(x)$ đạt cực đại tại $x=1$"], "correctIndex": 1, "explain": "Đặt $u(x)=x^2-4x+5$. Với $x \\in (-\\infty;2)$ thì $u(x)=(x-2)^2+1 > 1$.<br>Đạo hàm $u'(x)=2x-4 < 0$ với mọi $x < 2$, suy ra $u(x)$ nghịch biến trên $(-\\infty;2)$.<br>Ta có $h(x)=2^{u(x)} \\cdot \\ln[u(x)]$.<br>Đạo hàm $h'(x)=u'(x) \\cdot 2^{u(x)} \\cdot \\ln 2 \\cdot \\ln[u(x)] + 2^{u(x)} \\cdot \\dfrac{u'(x)}{u(x)}$.<br>$h'(x)=u'(x) \\cdot 2^{u(x)} \\left[ \\ln 2 \\cdot \\ln u(x) + \\dfrac{1}{u(x)} \\right]$.<br>Vì $u(x) > 1$ nên $\\ln u(x) > 0$, $\\dfrac{1}{u(x)} > 0$ và $2^{u(x)} > 0$.<br>Kết hợp với $u'(x) < 0$, ta suy ra $h'(x) < 0$ với mọi $x \\in (-\\infty;2)$.<br>Vậy hàm số $h(x)$ nghịch biến trên khoảng $(-\\infty;2)$."}, {"question": "Tìm số giao điểm của đồ thị hàm số $y=f'(x)$ và $y=g'(x)$.", "choices": ["$0$", "$1$", "$2$", "$3$"], "correctIndex": 1, "explain": "Ta có $f'(x)=(2x-4) \\cdot 2^{x^2-4x+5} \\ln 2$ và $g'(x)=\\dfrac{2x-4}{x^2-4x+5}$.<br>Phương trình hoành độ giao điểm của hai đồ thị đạo hàm:  $(2x-4) \\cdot 2^{x^2-4x+5} \\ln 2 = \\dfrac{2x-4}{x^2-4x+5} $<br>$\\Leftrightarrow (2x-4) \\left[ 2^{x^2-4x+5} \\ln 2 - \\dfrac{1}{x^2-4x+5} \\right] = 0$.<br>$\\Leftrightarrow \\hoac{&2x-4=0 \\Leftrightarrow x=2\\\\&2^{x^2-4x+5} \\ln 2 = \\dfrac{1}{x^2-4x+5} \\quad (*).}$<br>Xét phương trình $(*)$, đặt $t=x^2-4x+5 \\geq 1$. Phương trình trở thành $2^t \\ln 2 = \\dfrac{1}{t}$.  Với $t \\geq 1$, vế trái $VT=2^t \\ln 2 \\geq 2 \\ln 2 > 1$.<br>Vế phải $VP=\\dfrac{1}{t} \\leq 1$.<br>Do đó $VT > VP$, dẫn đến phương trình $(*)$ vô nghiệm.<br>Vậy hai đồ thị đạo hàm có duy nhất $1$ giao điểm tại $x=2$."}, {"question": "Gọi $A$, $B$ lần lượt là các điểm cực tiểu của đồ thị $(C_1)$ và $(C_2)$. Tính diện tích $S$ của tam giác $OAB$ với $O$ là gốc tọa độ.", "choices": ["$S=4$", "$S=1$", "$S=2$", "$S=3$"], "correctIndex": 2, "explain": "Xét hàm số $f(x)=2^{x^2-4x+5}$. Đạo hàm $f'(x)=(2x-4) 2^{x^2-4x+5} \\ln 2$.  $f'(x)=0 \\Leftrightarrow x=2$. Bảng biến thiên:<br>Từ BBT, điểm cực tiểu của $(C_1)$ là $A(2;2)$.  Xét hàm số $g(x)=\\ln(x^2-4x+5)$. Tương tự, $g'(x)=0 \\Leftrightarrow x=2$.<br>Giá trị cực tiểu $g(2)=\\ln 1=0$. Vậy điểm cực tiểu của $(C_2)$ là $B(2;0)$.<br>Tam giác $OAB$ có các đỉnh $O(0;0)$, $A(2;2)$, $B(2;0)$.<br>Dễ thấy $B$ nằm trên trục hoành $Ox$, cạnh $OB$ nằm trên trục hoành và có độ dài $OB=2$.<br>Đường cao kẻ từ $A$ đến $OB$ chính là tung độ của điểm $A$, $h=|y_A|=2$.<br>Diện tích tam giác $S_{OAB}=\\dfrac{1}{2} \\cdot OB \\cdot h = \\dfrac{1}{2} \\cdot 2 \\cdot 2 = 2$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>"}]}, {"noiDungChung": "Ba nhân viên gồm Linh, Mai, và Nam được phân công phụ trách ba vị trí khác nhau tại một sự kiện: Đón khách, Kỹ thuật, và Hậu cần. Mỗi người sử dụng một loại bộ đàm có màu khác nhau: Đỏ, Xanh, và Vàng. Biết rằng: <br>a) Mai không phụ trách Kỹ thuật.  <br>b) Người dùng bộ đàm màu Đỏ phụ trách Đón khách.  <br>c) Linh dùng bộ đàm màu Vàng.  <br>d) Nam không phụ trách Đón khách.", "cauHoi": [{"question": "Khẳng định nào sau đây là <b>chắc chắn đúng</b>?", "choices": ["Nam phụ trách vị trí Kỹ thuật hoặc Hậu cần", "Linh phụ trách vị trí Đón khách", "Mai dùng bộ đàm màu Đỏ", "Nam dùng bộ đàm màu Đỏ"], "correctIndex": 0, "explain": "- Từ dữ kiện (3), Linh dùng bộ đàm màu Vàng.<br>- Từ dữ kiện (2), người dùng bộ đàm màu Đỏ phụ trách Đón khách. Do Linh dùng màu Vàng nên Linh không phụ trách Đón khách.<br>- Nam không phụ trách Đón khách (GT 4). Vậy người phụ trách Đón khách chỉ có thể là Mai.<br>- Suy ra Mai dùng bộ đàm màu Đỏ.<br>- Vì Mai (Đỏ - Đón khách) và Linh (Vàng), nên Nam dùng bộ đàm màu Xanh.<br>- Nam không phụ trách Đón khách là chắc chắn đúng theo đề bài, và từ các suy luận trên, Nam sẽ làm Kỹ thuật hoặc Hậu cần."}, {"question": "Nếu biết thêm rằng “Linh không làm các công việc liên quan đến máy móc kỹ thuật”, hãy xác định vị trí của Nam.", "choices": ["Nam phụ trách Đón khách", "Nam phụ trách Hậu cần", "Nam phụ trách Kỹ thuật hoặc Hậu cần", "Nam phụ trách Kỹ thuật"], "correctIndex": 3, "explain": "- Ta đã biết: Mai (Đón khách), Linh (Vàng), Nam (Xanh).<br>- Linh không làm Kỹ thuật và đã biết không làm Đón khách $\\Rightarrow$ Linh làm Hậu cần.<br>- Vị trí cuối cùng là Kỹ thuật thuộc về Nam."}, {"question": "Sắp xếp đúng cặp (Vị trí - Màu bộ đàm) của ba bạn theo thứ tự <b>Linh - Mai - Nam</b>.", "choices": ["Hậu cần - Vàng, Đón khách - Đỏ, Kỹ thuật - Xanh", "Hậu cần - Vàng, Đón khách - Đỏ, Kỹ thuật - Xanh", "Kỹ thuật - Xanh, Đón khách - Đỏ, Hậu cần - Vàng", "Đón khách - Đỏ, Hậu cần - Vàng, Kỹ thuật - Xanh"], "correctIndex": 1, "explain": "- Linh: Hậu cần - Vàng.<br>- Mai: Đón khách - Đỏ.<br>- Nam: Kỹ thuật - Xanh."}]}, {"noiDungChung": "Trên một kệ trưng bày điện thoại có $5$ vị trí liên tiếp được đánh số từ $1$ đến $5$ (từ trái sang phải). Có $4$ dòng điện thoại ký hiệu là $A$, $B$, $C$, $D$ được đặt vào kệ, một vị trí sẽ để trống để đặt biển tên cửa hàng. Quy tắc sắp xếp như sau: <br>a) Điện thoại $A$ và $B$ là hai dòng cao cấp nên phải đặt cách nhau đúng một vị trí.  <br>b) Điện thoại $C$ không được đặt cạnh vị trí trống.  <br>c) Vị trí số $1$ và số $5$ không được để trống.  <br>d) Điện thoại $D$ phải nằm ở vị trí có số thứ tự nhỏ hơn vị trí của $C$.", "cauHoi": [{"question": "Nếu vị trí số $3$ để trống, điện thoại nào sau đây <b>không thể</b> nằm ở vị trí số $2$?", "choices": ["$A$", "$B$", "$C$", "$D$"], "correctIndex": 2, "explain": "- Vị trí số $3$ trống.<br>- Theo quy tắc (2), điện thoại $C$ không được đặt cạnh vị trí trống $\\Rightarrow C$ không ở vị trí $2$ và $4$.<br>- Vậy $C$ chỉ có thể ở $1$ hoặc $5$.<br>- Theo quy tắc (4), $D < C$. Nếu $C$ ở $1$ thì không có chỗ cho $D$ (loại). Vậy $C$ ở $5$.<br>- Do đó, điện thoại $C$ chắc chắn không thể nằm ở vị trí số $2$."}, {"question": "Nếu $A$ nằm ở vị trí số $1$ và $B$ nằm ở vị trí số $3$, vị trí nào sau đây <b>phải</b> để trống?", "choices": ["Vị trí số $4$", "Vị trí số $5$", "Vị trí số $3$", "Vị trí số $2$"], "correctIndex": 0, "explain": "- $A$ ở $1$, $B$ ở $3$ (Thỏa mãn quy tắc 1: cách nhau đúng một vị trí).<br>- Các vị trí còn lại là $2, 4, 5$. Vị trí trống không ở $1, 5$ nên trống là $2$ hoặc $4$.<br>- Nếu vị trí $2$ trống: Điện thoại $C$ không được cạnh trống nên $C$ không ở $1$ và $3$. Nhưng $A, B$ đã ở đó. Vậy $C$ ở $4$ hoặc $5$. Nếu $C$ ở $4$, $C$ cạnh trống $2$ (loại). Nếu $C$ ở $5$, $D$ ở $4$. Cấu hình: $A(1), \\text{Trống}(2), B(3), D(4), C(5)$. Tuy nhiên, $C(5)$ cạnh $D(4)$ thì được, nhưng $D(4)$ cạnh trống $(2)$ không vi phạm, nhưng quy tắc (2) nói $C$ không cạnh trống. Ở đây $C(5)$ không cạnh trống $(2)$. Nhưng xét tiếp $D < C$ thỏa mãn.<br>- Xét nếu vị trí $4$ trống: $C$ không được ở $3, 5$. Vì $B$ ở $3$ nên $C$ không ở $5$. Vậy $C$ phải ở vị trí còn lại là $2$. Khi đó $D < C \\Rightarrow D$ ở $1$. Nhưng $A$ đã ở $1$ (Loại).<br>- Vậy vị trí $4$ là vị trí duy nhất có thể để trống nếu xét các ràng buộc kề cận của $C$."}, {"question": "Có bao nhiêu cách sắp xếp vị trí của điện thoại $D$ sao cho luôn tồn tại ít nhất một phương án đặt các điện thoại còn lại thỏa mãn tất cả quy tắc?", "choices": ["$1$", "$2$", "$4$", "$3$"], "correctIndex": 3, "explain": "- $D < C$ và $C$ không cạnh trống. Trống $\\in \\{2, 3, 4\\}$.<br>- Nếu $D=1$, $C$ có thể ở $\\{3, 4, 5\\}$. Ta dễ dàng tìm được cấu hình cho $A, B$ cách nhau $1$ vị trí.<br>- Nếu $D=2$, $C$ có thể ở $\\{4, 5\\}$.<br>- Nếu $D=3$, $C$ có thể ở $\\{5\\}$.<br>- Nếu $D=4$, không có chỗ cho $C$ (vì $C$ không ở $5$ nếu trống ở $4$, hoặc nếu $C=5$ thì $D < C$ thỏa nhưng phải xếp $A, B$).<br>- Qua kiểm tra các trường hợp kề nhau của $A, B$, $D$ có thể nhận các giá trị $1, 2, 3$."}]}, {"noiDungChung": "Biểu đồ tròn bên cạnh thống kê tỉ lệ phần trăm các loại chất thải hữu cơ thu gom được tại một trang trại trong một tháng. Biết rằng tỉ lệ phần trăm của <i>Phế phẩm nông nghiệp</i> gấp $4$ lần tỉ lệ phần trăm của <i>Chất thải chăn nuôi</i>. Ngoài ra, tỉ lệ của <i>Rác thải sinh hoạt</i> chiếm $15\\%$ và <i>Các loại khác</i> chiếm $5\\%$. Tổng khối lượng chất thải thu gom được là $250$ kg.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[line join=round, line cap=round, font=\\footnotesize]\n\t\t\t\n\t\t\t\n\t\t\t\\fill[blue!50] (0,0) -- (90:1.8) arc (90:-198:1.8) -- cycle;\n\t\t\t\n\t\t\t\n\t\t\t\n\t\t\t\\fill[blue!50] (0,0) -- (90:1.8) arc (90:-140.4:1.8) -- cycle; \n\t\t\t\\fill[orange!60] (0,0) -- (-140.4:1.8) arc (-140.4:-198:1.8) -- cycle; \n\t\t\t\\fill[green!50] (0,0) -- (-198:1.8) arc (-198:-252:1.8) -- cycle; \n\t\t\t\\fill[yellow!60] (0,0) -- (-252:1.8) arc (-252:-270:1.8) -- cycle; \n\t\t\t\n\t\t\t\\begin{scope}[shift={(2.5,0.8)}]\n\t\t\t\t\\draw[fill=blue!50] (0,0) rectangle (0.2,0.2) node[right, shift={(0,-0.1)}]{Phế phẩm nông nghiệp};\n\t\t\t\t\\draw[fill=orange!60] (0,-0.4) rectangle (0.2,-0.2) node[right, shift={(0,-0.1)}]{Chất thải chăn nuôi};\n\t\t\t\t\\draw[fill=green!50] (0,-0.8) rectangle (0.2,-0.6) node[right, shift={(0,-0.1)}]{Rác thải sinh hoạt};\n\t\t\t\t\\draw[fill=yellow!60] (0,-1.2) rectangle (0.2,-1.0) node[right, shift={(0,-0.1)}]{Các loại khác};\n\t\t\t\\end{scope}\n\t\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Bằng cách thiết lập phương trình, hãy tìm tỉ lệ phần trăm của <i>Phế phẩm nông nghiệp</i> và <i>Chất thải chăn nuôi</i>.", "choices": ["Chăn nuôi chiếm $10\\%$, Nông nghiệp chiếm $40\\%$", "Chăn nuôi chiếm $20\\%$, Nông nghiệp chiếm $80\\%$", "Chăn nuôi chiếm $16\\%$, Nông nghiệp chiếm $64\\%$", "Chăn nuôi chiếm $15\\%$, Nông nghiệp chiếm $60\\%$"], "correctIndex": 2, "explain": "Gọi $x$ là tỉ lệ phần trăm của <i>Chất thải chăn nuôi</i> ($x>0$).<br>Khi đó, tỉ lệ phần trăm của <i>Phế phẩm nông nghiệp</i> là $4x$.<br>Vì tổng tỉ lệ của biểu đồ tròn là $100\\%$, ta có phương trình:  $$4x+x+15\\%+5\\%=100\\%$$  $$\\Leftrightarrow 5x+20\\%=100\\% \\Leftrightarrow 5x=80\\% \\Leftrightarrow x=16\\%$$  Vậy tỉ lệ <i>Chất thải chăn nuôi</i> là $16\\%$ và <i>Phế phẩm nông nghiệp</i> là $4\\cdot 16\\%=64\\%$."}, {"question": "Khối lượng <i>Phế phẩm nông nghiệp</i> thu gom được trong tháng đó là bao nhiêu kg?", "choices": ["$150$ kg", "$160$ kg", "$175$ kg", "$180$ kg"], "correctIndex": 1, "explain": "Khối lượng <i>Phế phẩm nông nghiệp</i> là:  $$250\\cdot 64\\%=250\\cdot\\dfrac{64}{100}=160\\text{ (kg)}$$"}, {"question": "Nhà trường dự định tái chế toàn bộ <i>Phế phẩm nông nghiệp</i> và <i>Rác thải sinh hoạt</i>. Tổng khối lượng rác được tái chế chiếm bao nhiêu phần trăm tổng lượng rác của trang trại?", "choices": ["$64\\%$", "$75\\%$", "$79\\%$", "$80\\%$"], "correctIndex": 2, "explain": "Tỉ lệ phần trăm tổng cộng của hai loại rác này là:  $$64\\%+15\\%=79\\%$$"}]}, {"noiDungChung": "Nhà vườn thu hoạch $100$ quả táo và thống kê khối lượng của chúng (đơn vị: gam) được kết quả như bảng bên dưới.<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Khối lượng (gam)</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Số quả táo</b></td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[150;160)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$10$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[160;170)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$20$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[170;180)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$40$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[180;190)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$20$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[190;200)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$10$</td></tr></table>", "cauHoi": [{"question": "Dựa vào bảng thống kê, khẳng định nào sau đây là đúng?", "choices": ["Nhóm chứa mốt của mẫu số liệu là nhóm $[160;170)$", "Số quả táo có khối lượng dưới $170$ gam chiếm $30\\%$", "Có đúng $50$ quả táo có khối lượng từ $180$ gam trở lên", "Số quả táo thuộc nhóm $[170;180)$ ít hơn nhóm $[160;170)$"], "correctIndex": 1, "explain": "* Xét các khẳng định:<br>- Nhóm có tần số lớn nhất là $[170;180)$ (với $40$ quả táo) nên đây là nhóm chứa mốt. Khẳng định A sai.<br>- Số quả táo có khối lượng dưới $170$ gam thuộc hai nhóm $[150;160)$ và $[160;170)$. Tổng số là $10+20=30$ quả, chiếm tỉ lệ $\\dfrac{30}{100}=30\\%$. Khẳng định B đúng.<br>- Số quả táo từ $180$ gam trở lên thuộc hai nhóm $[180;190)$ và $[190;200)$. Tổng số là $20+10=30$ quả. Khẳng định C sai.<br>- Số quả táo thuộc nhóm $[170;180)$ là $40$ quả, nhiều hơn số quả táo thuộc nhóm $[160;170)$ là $20$ quả. Khẳng định D sai."}, {"question": "Ước lượng khối lượng trung bình của một quả táo được thu hoạch.", "choices": ["$172{,}5$ gam", "$174{,}0$ gam", "$175{,}0$ gam", "$176{,}5$ gam"], "correctIndex": 2, "explain": "Chọn giá trị đại diện cho mỗi nhóm là trung bình cộng của hai đầu mút khoảng:<br>$c_1=155$, $c_2=165$, $c_3=175$, $c_4=185$, $c_5=195$.<br>Cỡ mẫu $n=100$.<br>Số trung bình của mẫu số liệu ghép nhóm là:<br>$\\bar{x}=\\dfrac{10\\cdot155+20\\cdot165+40\\cdot175+20\\cdot185+10\\cdot195}{100}$<br>$\\bar{x}=\\dfrac{1550+3300+7000+3700+1950}{100}=\\dfrac{17500}{100}=175$ (gam)."}, {"question": "Nhà vườn muốn chọn ra $25\\%$ số quả táo có khối lượng lớn nhất để xuất khẩu. Hỏi khối lượng tối thiểu của một quả táo đạt tiêu chuẩn xuất khẩu là bao nhiêu (làm tròn đến hàng phần mười)?", "choices": ["$180{,}0$ gam", "$182{,}5$ gam", "$185{,}0$ gam", "$187{,}5$ gam"], "correctIndex": 1, "explain": "Bài toán yêu cầu tìm giá trị chia mẫu số liệu thành $75\\%$ thấp nhất và $25\\%$ cao nhất, đó chính là tứ phân vị thứ ba $Q_3$.<br>Ta có cỡ mẫu $n=100\\Rightarrow\\dfrac{3n}{4}=75$.<br>Lập tần số tích lũy:<br>$cf_1=10$, $cf_2=10+20=30$, $cf_3=30+40=70$, $cf_4=70+20=90$.<br>Vì $cf_3<75\\le cf_4$ nên nhóm chứa $Q_3$ là nhóm thứ tư: $[180;190)$.<br>Ta có: đầu mút trái $L=180$, độ dài nhóm $h=10$, tần số nhóm $n_4=20$, tần số tích lũy nhóm liền trước $cf_3=70$.<br>Giá trị của tứ phân vị thứ ba là:<br>$Q_3=L+\\dfrac{\\dfrac{3n}{4}-cf_3}{n_4}\\cdot h=180+\\dfrac{75-70}{20}\\cdot10=180+\\dfrac{5}{20}\\cdot10=180+2{,}5=182{,}5$.<br>Vậy khối lượng tối thiểu của một quả táo xuất khẩu là $182{,}5$ gam."}]}]}, {"id": "extra-10", "ten": "Đề luyện tập số 16", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Hai đội bóng $A$ và $B$ cùng tham gia một giải bóng đá (các trận đấu của đội $A$ và đội $B$ là độc lập với nhau). Xác suất vượt qua vòng bảng của đội $A$ thấp hơn đội $B$ là $0{,}1$. Biết xác suất để cả hai đội không vượt qua vòng bảng là $0{,}12$. Tính xác suất đội $A$ vượt qua vòng bảng còn đội $B$ không vượt qua vòng bảng.", "choices": ["$0{,}18$", "$0{,}16$", "$0{,}24$", "$0{,}08$"], "correctIndex": 0, "explain": "Gọi $P(A)=x$ là xác suất đội $A$ vượt qua vòng bảng ($0 \\le x \\le 0{,}9$).<br>Vì xác suất vượt qua vòng bảng của đội $A$ thấp hơn đội $B$ là $0{,}1$ nên xác suất đội $B$ vượt qua vòng bảng là:  $P(B)=x+0{,}1$.<br>Xác suất để đội $A$ không vượt qua vòng bảng là: $P(\\overline{A})=1-x$.<br>Xác suất để đội $B$ không vượt qua vòng bảng là: $P(\\overline{B})=1-(x+0{,}1)=0{,}9-x$.<br>Do các trận đấu của hai đội là độc lập nên xác suất cả hai đội không vượt qua vòng bảng là:<br>$P(\\overline{A} \\cap \\overline{B}) = P(\\overline{A}) \\cdot P(\\overline{B}) = (1-x)(0{,}9-x)$.<br>Theo giả thiết, ta có phương trình:  $(1-x)(0{,}9-x)=0{,}12 \\Leftrightarrow 0{,}9-x-0{,}9x+x^2=0{,}12 \\Leftrightarrow x^2-1{,}9x+0{,}78=0$.<br>Giải phương trình ta được:  $\\hoac{&x=1{,}3 \\text{ (loại vì } x \\le 1)\\\\&x=0{,}6 \\text{ (thỏa mãn)}}$.<br>Vậy $P(A)=0{,}6$ và $P(B)=0{,}6+0{,}1=0{,}7$.<br>Xác suất đội $A$ vượt qua vòng bảng còn đội $B$ không vượt qua vòng bảng là:  $P(A \\cap \\overline{B}) = P(A) \\cdot P(\\overline{B}) = 0{,}6 \\cdot (1-0{,}7) = 0{,}6 \\cdot 0{,}3 = 0{,}18$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho cấp số cộng $(u_n)$ có công sai $d=2$ và biểu thức $A=u_2^2+u_3^2+u_4^2$ đạt giá trị nhỏ nhất. Số $2018$ là số hạng thứ bao nhiêu của cấp số cộng đã cho?", "choices": ["$1011$", "$1012$", "$1013$", "$1014$"], "correctIndex": 1, "explain": "Ta có các số hạng của cấp số cộng tính theo $u_3$ và công sai $d=2$ như sau:  $\\heva{&u_2=u_3-d=u_3-2\\\\&u_4=u_3+d=u_3+2}$<br>Khi đó biểu thức $A$ trở thành:<br>$A=(u_3-2)^2+u_3^2+(u_3+2)^2$<br>$A=u_3^2-4u_3+4+u_3^2+u_3^2+4u_3+4$<br>$A=3u_3^2+8$.<br>Biểu thức $A$ đạt giá trị nhỏ nhất khi $u_3=0$.<br>Với $u_3=0$, ta tìm được số hạng đầu $u_1$:<br>$u_3=u_1+2d \\Rightarrow 0=u_1+2\\cdot 2 \\Rightarrow u_1=-4$.<br>Giả sử $2018$ là số hạng thứ $n$ của cấp số cộng, ta có:  $u_n=u_1+(n-1)d$  $\\Leftrightarrow 2018=-4+(n-1)2$<br>$\\Leftrightarrow 2022=2(n-1)$<br>$\\Leftrightarrow n-1=1011$<br>$\\Leftrightarrow n=1012$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tập nghiệm của bất phương trình $|x^2-4x| < 5$ là $(a; b)$. Tính giá trị của biểu thức $T=a+b$.", "choices": ["$T=3$", "$T=0$", "$T=4$", "$T=-3$"], "correctIndex": 2, "explain": "Bất phương trình tương đương với:  $-5 < x^2-4x < 5 \\Leftrightarrow \\heva{&x^2-4x+5 > 0 \\text{ (luôn đúng vì } \\Delta < 0) \\\\ &x^2-4x-5 < 0}$ <br>Xét $x^2-4x-5 < 0 \\Leftrightarrow (x+1)(x-5) < 0 \\Leftrightarrow -1 < x < 5$. <br>Vậy tập nghiệm là $(-1; 5)$, suy ra $a=-1$, $b=5$. Do đó $T=-1+5=4$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Bác Tư đến siêu thị mua một cái quạt máy và một ấm đun siêu tốc với tổng số tiền theo giá niêm yết là $630$ nghìn đồng. Tuy nhiên, trong tuần lễ tri ân khách hàng nên siêu thị đã giảm giá quạt máy $15\\%$ và giảm giá ấm đun siêu tốc $12\\%$ so với giá niêm yết của từng sản phẩm. Nên Bác Tư chỉ phải trả $543$ nghìn đồng khi mua hai sản phẩm trên. Hỏi giá niêm yết (khi chưa giảm giá) của một cái quạt máy là bao nhiêu?", "choices": ["$250$ nghìn đồng", "$380$ nghìn đồng", "$400$ nghìn đồng", "$350$ nghìn đồng"], "correctIndex": 1, "explain": "Gọi $x$, $y$ lần lượt là giá niêm yết của một cái quạt máy và một ấm đun siêu tốc ($0<x,y<630$, đơn vị: nghìn đồng). <br>Theo đề bài, tổng giá niêm yết của hai sản phẩm là $630$ nghìn đồng, ta có phương trình:  $x+y=630$. $(1)$ <br>Giá của quạt máy sau khi giảm $15\\%$ là: $x-15\\%x = 0{,}85x$. <br>Giá của ấm đun siêu tốc sau khi giảm $12\\%$ là: $y-12\\%y = 0{,}88y$. <br>Vì tổng số tiền Bác Tư thực tế phải trả là $543$ nghìn đồng nên ta có phương trình:  $0{,}85x+0{,}88y=543$. $(2)$ <br>Từ $(1)$ và $(2)$ ta có hệ phương trình:  $\\heva{&x+y=630\\\\&0{,}85x+0{,}88y=543} \\Leftrightarrow \\heva{&x=380\\\\&y=250}$ (thỏa mãn điều kiện). <br>Vậy giá niêm yết của một cái quạt máy là $380$ nghìn đồng."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Gọi $A$ là tập các số tự nhiên gồm ba chữ số đôi một khác nhau được lập từ các chữ số $0$, $1$, $2$, $3$, $4$, $5$, $6$. Lấy ngẫu nhiên từ tập $A$ một số. Tính xác suất $P$ lấy được số chia hết cho $6$", "choices": ["$P=\\dfrac{13}{60}$", "$P=\\dfrac{11}{60}$", "$P=\\dfrac{1}{6}$", "$P=\\dfrac{7}{30}$"], "correctIndex": 0, "explain": "Số các số tự nhiên có ba chữ số đôi một khác nhau lập từ tập $\\{0,1,2,3,4,5,6\\}$ là:<br>a) Chữ số hàng trăm có $6$ cách chọn (khác $0$).  <br>b) Hai chữ số còn lại có $A_6^2$ cách chọn.  <br>c) Vậy $n(\\Omega)=6\\cdot A_6^2=180$.<br>Gọi số cần tìm có dạng $n=\\overline{abc}$ chia hết cho $6$. Khi đó $n$ phải chia hết cho cả $2$ và $3$.<br>a) $n\\,\\vdots\\,2\\Rightarrow c\\in\\{0,2,4,6\\}$.  <br>b) $n\\,\\vdots\\,3\\Rightarrow (a+b+c)\\,\\vdots\\,3$.<br>Các bộ ba chữ số $\\{a,b,c\\}$ đôi một khác nhau từ tập nguồn có tổng chia hết cho $3$ là:  $\\{0,1,2\\}$, $\\{0,1,5\\}$, $\\{0,2,4\\}$, $\\{0,3,6\\}$, $\\{0,4,5\\}$, $\\{1,2,3\\}$, $\\{1,2,6\\}$, $\\{1,3,5\\}$, $\\{1,5,6\\}$, $\\{2,3,4\\}$, $\\{2,4,6\\}$, $\\{3,4,5\\}$, $\\{4,5,6\\}$.  Ta đếm số các số chẵn trong từng trường hợp:<br>a) Các bộ có chữ số $0$:<br>a) $\\{0,1,2\\}$: $102,120,210$ (3 số).  <br>b) $\\{0,1,5\\}$: $150,510$ (2 số).  <br>c) $\\{0,2,4\\}$: $204,402,240,420$ (4 số).  <br>d) $\\{0,3,6\\}$: $306,603,360,630$ (4 số).  <br>e) $\\{0,4,5\\}$: $450,540$ (2 số).<br>f) Các bộ không có chữ số $0$:<br>a) $\\{1,2,3\\}$: $132,312$ (2 số).  <br>b) $\\{1,2,6\\}$: $126,162,216,612$ (4 số).  <br>c) $\\{1,3,5\\}$: Không có số chẵn.  <br>d) $\\{1,5,6\\}$: $156,516$ (2 số).  <br>e) $\\{2,3,4\\}$: $234,324,342,432$ (4 số).  <br>f) $\\{2,4,6\\}$: $246,264,426,462,624,642$ (6 số).  <br>g) $\\{3,4,5\\}$: $354,534$ (2 số).  <br>h) $\\{4,5,6\\}$: $456,546,564,654$ (4 số).<br>Tổng số các số thuận lợi là: $(3+2+4+4+2)+(2+4+0+2+4+6+2+4)=15+24=39$ số.  Xác suất cần tìm là $P=\\dfrac{39}{180}=\\dfrac{13}{60}$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho cấp số nhân có các số hạng lần lượt là $\\dfrac{1}{4}$, $\\dfrac{1}{2}$, $1$, $\\dots$, $2048$. Tính tổng $S$ của tất cả các số hạng của cấp số nhân đã cho.", "choices": ["$S=4095$", "$S=4095{,}75$", "$S=4096$", "$S=2047{,}75$"], "correctIndex": 1, "explain": "Ta có cấp số nhân với số hạng đầu $u_1=\\dfrac{1}{4}$ và công bội $q=\\dfrac{u_2}{u_1}=\\dfrac{1}{2}:\\dfrac{1}{4}=2$.<br>Số hạng tổng quát của cấp số nhân là $u_n=u_1 \\cdot q^{n-1}$.<br>Theo đề bài, số hạng cuối cùng là $2048$, ta có:  $2048 = \\dfrac{1}{4} \\cdot 2^{n-1} \\Leftrightarrow 8192 = 2^{n-1} \\Leftrightarrow 2^{13} = 2^{n-1} \\Leftrightarrow n-1=13 \\Leftrightarrow n=14$.<br>Tổng $S$ của $14$ số hạng đầu tiên là:  $S_{14} = \\dfrac{u_1(1-q^{14})}{1-q} = \\dfrac{\\dfrac{1}{4}(1-2^{14})}{1-2} = \\dfrac{\\dfrac{1}{4}(1-16384)}{-1} = \\dfrac{-4095{,}75}{-1} = 4095{,}75$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ có ba góc nhọn, $BC=a$, $AC=b$, $AB=c$ và diện tích là $S$. Tổng $\\cot A+\\cot B+\\cot C$ bằng", "choices": ["$\\dfrac{2(a^2+b^2+c^2)}{S}$", "$\\dfrac{a^2+b^2+c^2}{S}$", "$\\dfrac{a^2+b^2+c^2}{2S}$", "$\\dfrac{a^2+b^2+c^2}{4S}$"], "correctIndex": 3, "explain": "Từ công thức $S=\\dfrac{1}{2}bc\\sin A \\Rightarrow \\sin A=\\dfrac{2S}{bc}$, và $\\cos A=\\dfrac{b^2+c^2-a^2}{2bc}$.<br>Suy ra $\\cot A=\\dfrac{\\cos A}{\\sin A}=\\dfrac{\\dfrac{b^2+c^2-a^2}{2bc}}{\\dfrac{2S}{bc}}=\\dfrac{b^2+c^2-a^2}{4S}$.<br>Tương tự ta cũng có $\\cot B=\\dfrac{a^2+c^2-b^2}{4S}$, $\\cot C=\\dfrac{a^2+b^2-c^2}{4S}$.<br>Vậy $\\cot A+\\cot B+\\cot C=\\dfrac{b^2+c^2-a^2}{4S}+\\dfrac{a^2+c^2-b^2}{4S}+\\dfrac{a^2+b^2-c^2}{4S}=\\dfrac{a^2+b^2+c^2}{4S}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Trong một dự án xây dựng mạng lưới cáp quang, các trạm phát sóng được ký hiệu từ $1$ đến $5$. Bảng số liệu bên cạnh cho biết sự kết nối trực tiếp giữa các trạm (số $1$ nghĩa là có đường truyền trực tiếp, số $0$ nghĩa là không). Một kỹ thuật viên cần tìm một đường đi truyền tín hiệu từ trạm $1$ đến trạm $4$ sao cho qua ít trạm trung gian nhất. Hỏi đường đi ngắn nhất đó đi qua bao nhiêu cạnh?<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$2$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$3$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$4$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$5$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$2$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$3$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$4$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$5$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$1$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$0$</td></tr></table>", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 1, "explain": "Dựa vào bảng ma trận kề, ta xác định các kết nối trực tiếp:<br>a) Trạm $1$ kết nối trực tiếp với: trạm $2$ và trạm $5$.  <br>b) Trạm $4$ kết nối trực tiếp với: trạm $3$ và trạm $5$.<br>Để đi từ $1$ đến $4$:<br>a) Cách 1: $1 \\to 5 \\to 4$ (Độ dài bằng $2$ cạnh).  <br>b) Cách 2: $1 \\to 2 \\to 3 \\to 4$ (Độ dài bằng $3$ cạnh).  <br>c) Cách 3: $1 \\to 2 \\to 5 \\to 4$ (Độ dài bằng $3$ cạnh).<br>Vậy đường đi ngắn nhất từ trạm $1$ đến trạm $4$ có độ dài bằng $2$ cạnh (qua trạm trung gian $5$)."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biến đổi biểu thức $M=\\sin \\dfrac{\\pi}{16}-\\sin \\dfrac{5\\pi}{16}$ thành tích ta được $M=2\\sin a\\pi \\cos b\\pi$ với $a\\in\\left(-\\dfrac{1}{2};\\dfrac{1}{2}\\right)$ và $b\\in(0;1)$. Khi đó $4a+8b$ bằng bao nhiêu?", "choices": ["$1$", "$2$", "$5$", "$4$"], "correctIndex": 0, "explain": "Ta có công thức biến đổi tổng thành tích: $\\sin u - \\sin v = 2\\cos \\dfrac{u+v}{2} \\sin \\dfrac{u-v}{2}$.<br>Áp dụng: $M = \\sin \\dfrac{\\pi}{16} - \\sin \\dfrac{5\\pi}{16} = 2\\cos \\left(\\dfrac{\\dfrac{\\pi}{16} + \\dfrac{5\\pi}{16}}{2}\\right) \\sin \\left(\\dfrac{\\dfrac{\\pi}{16} - \\dfrac{5\\pi}{16}}{2}\\right)$.<br>$M = 2\\cos \\dfrac{3\\pi}{16} \\sin \\left(-\\dfrac{2\\pi}{16}\\right) = -2\\sin \\dfrac{\\pi}{8} \\cos \\dfrac{3\\pi}{16}$.<br>Để đưa về dạng $M = 2\\sin a\\pi \\cos b\\pi$, ta có $M = 2\\sin \\left(-\\dfrac{1}{8}\\right)\\pi \\cos \\dfrac{3}{16}\\pi$.<br>Suy ra $a = -\\dfrac{1}{8}$ (thỏa mãn $a\\in\\left(-\\dfrac{1}{2};\\dfrac{1}{2}\\right)$) và $b = \\dfrac{3}{16}$ (thỏa mãn $b\\in(0;1)$).<br>Vậy $4a + 8b = 4\\left(-\\dfrac{1}{8}\\right) + 8\\left(\\dfrac{3}{16}\\right) = -\\dfrac{1}{2} + \\dfrac{3}{2} = \\dfrac{2}{2} = 1$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho phương trình $4\\cdot 4^x-9\\cdot 2^{x+1}+8=0$. Gọi $x_1$, $x_2$ là hai nghiệm của phương trình trên. Khi đó tích $x_1x_2$ bằng", "choices": ["$2$", "$-2$", "$-1$", "$0$"], "correctIndex": 1, "explain": "Phương trình đã cho tương đương với:  $$4\\cdot (2^x)^2-18\\cdot 2^x+8=0$$  Đặt $t=2^x$ ($t>0$), phương trình trở thành:  $$4t^2-18t+8=0 \\Leftrightarrow \\hoac{&t=4<br>&t=\\dfrac{1}{2}}$$<br>a) Với $t=4 \\Rightarrow 2^x=4 \\Rightarrow x_1=2$.  <br>b) Với $t=\\dfrac{1}{2} \\Rightarrow 2^x=2^{-1} \\Rightarrow x_2=-1$.<br>Vậy tích hai nghiệm là $x_1x_2=2\\cdot (-1)=-2$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Xét bất phương trình $\\log_2^2(2x)-2(m+1)\\log_2 x-2<0$. Tìm giá trị của tham số $m$ để bất phương trình có nghiệm thuộc khoảng $(\\sqrt{2};+\\infty)$.", "choices": ["$m>0$", "$m<-\\dfrac{3}{4}$", "$m>-\\dfrac{3}{4}$", "$m>-1$"], "correctIndex": 2, "explain": "Điều kiện: $x>0$.<br>Ta có: $\\log_2^2(2x)-2(m+1)\\log_2 x-2<0$<br>$\\Leftrightarrow (\\log_2 x+1)^2-2(m+1)\\log_2 x-2<0$<br>$\\Leftrightarrow \\log_2^2 x+2\\log_2 x+1-2m\\log_2 x-2\\log_2 x-2<0$<br>$\\Leftrightarrow \\log_2^2 x-2m\\log_2 x-1<0 \\quad (*)$.<br>Đặt $t=\\log_2 x$. Với $x\\in(\\sqrt{2};+\\infty)$ thì $t\\in\\left(\\dfrac{1}{2};+\\infty\\right)$.<br>Bất phương trình $(*)$ trở thành: $t^2-2mt-1<0 \\Leftrightarrow 2mt>t^2-1 \\Leftrightarrow 2m>t-\\dfrac{1}{t}$ (vì $t>\\dfrac{1}{2}>0$).<br>Xét hàm số $g(t)=t-\\dfrac{1}{t}$ trên khoảng $\\left(\\dfrac{1}{2};+\\infty\\right)$.<br>Ta có $g'(t)=1+\\dfrac{1}{t^2}>0, \\forall t\\in\\left(\\dfrac{1}{2};+\\infty\\right)$, do đó $g(t)$ là hàm số đồng biến trên $\\left(\\dfrac{1}{2};+\\infty\\right)$.<br>Khi đó $g(t)>g\\left(\\dfrac{1}{2}\\right)=\\dfrac{1}{2}-2=-\\dfrac{3}{2}$.<br>Để bất phương trình có nghiệm trên $\\left(\\dfrac{1}{2};+\\infty\\right)$ thì $2m>\\min g(t)$ trên khoảng đó (hoặc xét tập giá trị của hàm số).<br>Dễ thấy với mọi $m>-\\dfrac{3}{4}$, luôn tồn tại giá trị $t$ đủ gần $\\dfrac{1}{2}$ để bất phương trình $2m>g(t)$ thỏa mãn.<br>Vậy $2m>-\\dfrac{3}{2} \\Leftrightarrow m>-\\dfrac{3}{4}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hai biến cố $A$ và $B$, với $P(A)=0{,}8$, $P(B)=0{,}6$, $P(A|B)=0{,}7$. Tính $P(\\overline{A}|\\overline{B})$.", "choices": ["$0{,}15$", "$0{,}25$", "$0{,}05$", "$0{,}45$"], "correctIndex": 2, "explain": "Ta có công thức xác suất có điều kiện: $P(A|B)=\\dfrac{P(A \\cap B)}{P(B)}$.<br>Suy ra $P(A \\cap B) = P(A|B) \\cdot P(B) = 0{,}7 \\cdot 0{,}6 = 0{,}42$.<br>Ta cần tính $P(\\overline{A}|\\overline{B}) = \\dfrac{P(\\overline{A} \\cap \\overline{B})}{P(\\overline{B})}$.<br>Theo quy tắc De Morgan: $\\overline{A} \\cap \\overline{B} = \\overline{A \\cup B}$.<br>Do đó $P(\\overline{A} \\cap \\overline{B}) = P(\\overline{A \\cup B}) = 1 - P(A \\cup B)$.<br>Mà $P(A \\cup B) = P(A) + P(B) - P(A \\cap B) = 0{,}8 + 0{,}6 - 0{,}42 = 0{,}98$.<br>Suy ra $P(\\overline{A} \\cap \\overline{B}) = 1 - 0{,}98 = 0{,}02$.<br>Xác suất của biến cố đối $\\overline{B}$ là: $P(\\overline{B}) = 1 - P(B) = 1 - 0{,}6 = 0{,}4$.<br>Vậy $P(\\overline{A}|\\overline{B}) = \\dfrac{0{,}02}{0{,}4} = 0{,}05$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biết rằng $b<0$, $a+b=5$ và $\\lim\\limits_{x\\to 0}\\dfrac{\\sqrt{ax+1}-\\sqrt{1-b+x}}{x+1}=-2$. Khẳng định nào dưới đây sai?", "choices": ["$8<a<13$", "$b<-1$", "$a^2+b^2>10$", "$a-b>0$"], "correctIndex": 0, "explain": "Ta có:  $\\lim\\limits_{x\\to 0}\\dfrac{\\sqrt{ax+1}-\\sqrt{1-b+x}}{x+1}=\\dfrac{\\sqrt{a\\cdot 0+1}-\\sqrt{1-b+0}}{0+1}=1-\\sqrt{1-b}$.<br>Theo giả thiết:  $1-\\sqrt{1-b}=-2\\Leftrightarrow\\sqrt{1-b}=3\\Leftrightarrow 1-b=9\\Leftrightarrow b=-8$.<br>Vì $b=-8<0$ (thỏa mãn điều kiện).<br>Thay $b=-8$ vào phương trình $a+b=5$, ta được:  $a-8=5\\Leftrightarrow a=13$.<br>Xét các khẳng định:<br>a) $8<a<13 \\Leftrightarrow 8<13<13$ (Sai).  <br>b) $b<-1 \\Leftrightarrow -8<-1$ (Đúng).  <br>c) $a^2+b^2=13^2+(-8)^2=233>10$ (Đúng).  <br>d) $a-b=13-(-8)=21>0$ (Đúng).<br>Vậy khẳng định sai là $8<a<13$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Hai bạn Hùng và Dũng cùng xuất phát từ trường đạp xe đến sân vận động để xem bóng đá. Biết rằng nếu cả hai cùng đạp xe bình thường thì vận tốc của Hùng gấp $2$ lần vận tốc của Dũng. Khi bắt đầu đi, cả hai cùng xuất phát bằng xe đạp. Nhưng sau khi đi được $30$ phút, xe của Hùng bị hỏng nên bạn ấy phải gửi xe lại và đi bộ nốt quãng đường còn lại đến sân vận động. Biết rằng cả hai bạn đến sân vận động cùng một lúc, vận tốc đạp xe của Dũng lại gấp $4$ lần vận tốc đi bộ của Hùng. Hỏi thời gian hai bạn đi từ trường đến sân vận động là bao nhiêu phút? (Giả sử vận tốc đạp xe của hai bạn và vận tốc đi bộ của Hùng không đổi trong suốt quá trình di chuyển, và thời gian bạn Hùng gửi xe là không đáng kể).", "choices": ["$45$ phút", "$70$ phút", "$60$ phút", "$75$ phút"], "correctIndex": 1, "explain": "Gọi $v$ là vận tốc đi bộ của Hùng ($v>0$).<br>Theo đề bài, vận tốc đạp xe của Dũng là $4v$.<br>Vận tốc đạp xe của Hùng là $2 \\cdot 4v = 8v$.<br>Gọi $t$ (phút) là tổng thời gian hai bạn đi từ trường đến sân vận động ($t>30$).<br>Vì hai bạn đến sân vận động cùng một lúc nên thời gian Dũng đi là $t$ phút, quãng đường từ trường đến sân vận động là: $S = 4v \\cdot t$.<br>Trong $30$ phút đầu, Hùng đi được quãng đường là: $S_1 = 8v \\cdot 30 = 240v$.<br>Quãng đường còn lại Hùng phải đi bộ là: $S_2 = S - S_1 = 4vt - 240v = v(4t - 240)$.<br>Thời gian Hùng đi bộ quãng đường còn lại là: $t_2 = \\dfrac{S_2}{v} = \\dfrac{v(4t-240)}{v} = 4t - 240$ (phút).<br>Tổng thời gian đi của Hùng là: $30 + (4t - 240) = 4t - 210$ (phút).<br>Vì hai bạn đến cùng lúc nên ta có phương trình:  $t = 4t - 210 \\Leftrightarrow 3t = 210 \\Leftrightarrow t = 70$ (phút)."}]}, {"noiDungChung": "Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình bình hành, $AB=3$, $AD=4$, $\\widehat{BAD}=120^{\\circ}$. Cạnh bên $SA=2\\sqrt{3}$ và vuông góc với mặt phẳng đáy. Gọi $M$, $N$, $P$ lần lượt là trung điểm các cạnh $SA$, $AD$, $BC$.", "cauHoi": [{"question": "Tính thể tích $V$ của khối chóp $S.ABCD$.", "choices": ["$V=24$", "$V=4\\sqrt{3}$", "$V=12$", "$V=36$"], "correctIndex": 2, "explain": "Diện tích đáy hình bình hành $ABCD$:  $S_{ABCD} = AB \\cdot AD \\cdot \\sin \\widehat{BAD} = 3 \\cdot 4 \\cdot \\sin 120^{\\circ} = 12 \\cdot \\dfrac{\\sqrt{3}}{2} = 6\\sqrt{3}$.<br>Thể tích khối chóp $S.ABCD$:  $V = \\dfrac{1}{3} S_{ABCD} \\cdot SA = \\dfrac{1}{3} \\cdot 6\\sqrt{3} \\cdot 2\\sqrt{3} = 12$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\usetikzlibrary{calc}\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (A) at (0,0);\n\t\t\t\t\t\\coordinate (B) at (-1.5,-1.2);\n\t\t\t\t\t\\coordinate (D) at (4,0);\n\t\t\t\t\t\\coordinate (C) at ($(B)+(D)-(A)$);\n\t\t\t\t\t\\coordinate (S) at (0,4); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (M) at ($(S)!0.5!(A)$);\n\t\t\t\t\t\\coordinate (N) at ($(A)!0.5!(D)$);\n\t\t\t\t\t\\coordinate (P) at ($(B)!0.5!(C)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed] (S)--(A) (A)--(B) (A)--(D) (M)--(N) (N)--(P) (A)--(C);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick] (S)--(B) (S)--(C) (S)--(D) (B)--(C) (C)--(D) (M)--(P);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw (A) ++(0,0.3) -- ++(0.3,0) -- ++(0,-0.3);\n\t\t\t\t\t\\foreach \\p in {S,A,B,C,D,M,N,P}\n\t\t\t\t\t\\fill[red] (\\p) circle (1.5pt);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\node[above] at (S) {$S$};\n\t\t\t\t\t\\node[below left] at (A) {$A$};\n\t\t\t\t\t\\node[below left] at (B) {$B$};\n\t\t\t\t\t\\node[below right] at (C) {$C$};\n\t\t\t\t\t\\node[right] at (D) {$D$};\n\t\t\t\t\t\\node[left] at (M) {$M$};\n\t\t\t\t\t\\node[above] at (N) {$N$};\n\t\t\t\t\t\\node[below] at (P) {$P$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Tính khoảng cách $d$ từ điểm $D$ đến mặt phẳng $(SAB)$.", "choices": ["$d=2$", "$d=2\\sqrt{3}$", "$d=4$", "$d=\\sqrt{3}$"], "correctIndex": 1, "explain": "Vì $AD \\parallel BC$ và $SA \\perp (ABCD) \\Rightarrow SA \\perp AD$.<br>Mặt khác, trong mặt phẳng đáy $(ABCD)$, kẻ $DH \\perp AB$ tại $H$.<br>Ta có $\\widehat{DAB} = 120^{\\circ} \\Rightarrow \\widehat{DAH} = 60^{\\circ}$ (góc kề bù).<br>Trong tam giác vuông $ADH$: $DH = AD \\cdot \\sin 60^{\\circ} = 4 \\cdot \\dfrac{\\sqrt{3}}{2} = 2\\sqrt{3}$.<br>Vì $\\heva{&DH \\perp AB \\\\ &DH \\perp SA \\text{ (do } SA \\perp \\text{ đáy)}} \\Rightarrow DH \\perp (SAB)$.<br>Vậy $d(D, (SAB)) = DH = 2\\sqrt{3}$."}, {"question": "Gọi $\\alpha$ là góc giữa hai mặt phẳng $(SBC)$ và $(MNP)$. Tính $\\cos \\alpha$.", "choices": ["$\\cos \\alpha = \\dfrac{\\sqrt{3}}{3}$", "$\\cos \\alpha = \\dfrac{1}{\\sqrt{2}}$", "$\\cos \\alpha = \\dfrac{2}{\\sqrt{2}}$", "$\\cos \\alpha = \\dfrac{\\sqrt{21}}{7}$"], "correctIndex": 1, "explain": "Ta có: $(S A D) \\cap(S B C)=S x / / A D / / B C$.<br>Gọi $I$ là trung điếm của $S B$. Ta có: $\\left\\{\\begin{array}{l}M I / / N P / / A B \\\\ M I=\\dfrac{N P}{2}\\end{array}\\right.$.<br>Dễ dàng chứng minh được $I P, M N, S x$ đồng quy tại $J$. Như vậy $I$ là trung điểm của $J P, M$ là trung điểm của $N$.<br>Gọi $\\varphi$ là góc giừa hai mặt phẳng (SBC) và (MNP). Ta có: $\\sin \\varphi=\\dfrac{d(M,(S B C))}{d(M, I P)}$.<br>$$  d(M,(S B C))=\\dfrac{1}{2} d(A,(S B C))  $$<br>Ha $A K \\perp B C, A E \\perp S K \\Rightarrow A E \\perp(S B C) \\Rightarrow d(A,(S B C))=A E$.<br>$$  A K=A B \\cdot \\sin \\overline{A B K}=3 \\cdot \\sin 60^{\\circ}=\\dfrac{3 \\sqrt{3}}{2}  $$  $$  \\Delta S A K: \\dfrac{1}{A E^2}=\\dfrac{1}{A S^2}+\\dfrac{1}{A K^2}=\\dfrac{1}{12}+\\dfrac{4}{27}=\\dfrac{25}{108} \\Rightarrow A E=\\dfrac{6 \\sqrt{3}}{5} \\Rightarrow d(M,(S B C))=\\dfrac{3 \\sqrt{3}}{5} .  $$<br>Ta có $d(M, P I)=\\dfrac{1}{2} d(N, P I)$.<br>$$  \\begin{aligned}  & \\triangle A B C: A C^2=A B^2+C B^2-2 A B \\cdot C B \\cdot \\cos 60^{\\circ}=13 \\Rightarrow A C=\\sqrt{13} <br>& J P=2 I P=S C=\\sqrt{13+12}=5, J N=2 M N=S D=2 \\sqrt{7}, P N=A B=3 \\Rightarrow S_{J R x}=3 \\sqrt{6}  \\end{aligned}  $$<br>Mặt khác $S_{J D V}=\\dfrac{1}{2} d(N, J P), J P \\Rightarrow d(N, J P)=\\dfrac{6 \\sqrt{6}}{5} \\Rightarrow d(M, I P)=\\dfrac{3 \\sqrt{6}}{5}$.<br>Vây $\\sin \\varphi=\\dfrac{\\sqrt{2}}{2} \\Rightarrow \\varphi=45^{\\circ}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\usetikzlibrary{calc}\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (A) at (0,0);\n\t\t\t\t\t\\coordinate (B) at (-1.5,-2);\n\t\t\t\t\t\\coordinate (D) at (4,0);\n\t\t\t\t\t\\coordinate (C) at ($(B)+(D)-(A)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (S) at (0,4); \n\t\t\t\t\t\\coordinate (M) at ($(S)!0.5!(A)$); \n\t\t\t\t\t\\coordinate (N) at ($(A)!0.5!(D)$); \n\t\t\t\t\t\\coordinate (I) at ($(S)!0.5!(B)$); \n\t\t\t\t\t\\coordinate (P) at ($(B)!0.5!(C)$); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (J) at ($(M)+(M)-(N)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (K) at ($(B)!0.4!(P)$); \n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (E) at ($(S)!0.7!(K)$); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed, thin] (S)--(A) (A)--(B) (A)--(D) (A)--(C) (A)--(P) (N)--(P) (M)--(N) (A)--(K) (I)--(P);\n\t\t\t\t\t\\draw[dashed] (J)--(M) (J)--(I) (M)--(I) (A)--(E); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick] (S)--(B) (S)--(C) (S)--(D) (B)--(C) (C)--(D) (S)--(K);\n\t\t\t\t\t\\draw[thick] (J)--(P); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick, -] (S) -- ($(S)!1.8!(J)$) node[above] {$x$};\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw (A) ++(0,0.25) -- ++(0.25,0) -- ++(0,-0.25);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\foreach \\p in {S,A,B,C,D,M,N,P,I,J,K,E}\n\t\t\t\t\t\\fill[black] (\\p) circle (1.2pt);\n\t\t\t\t\t\n\t\t\t\t\t\\node[above right] at (S) {$S$};\n\t\t\t\t\t\\node[below left] at (A) {$A$};\n\t\t\t\t\t\\node[below left] at (B) {$B$};\n\t\t\t\t\t\\node[below right] at (C) {$C$};\n\t\t\t\t\t\\node[right] at (D) {$D$};\n\t\t\t\t\t\\node[right] at (M) {$M$};\n\t\t\t\t\t\\node[above right] at (N) {$N$};\n\t\t\t\t\t\\node[below] at (P) {$P$};\n\t\t\t\t\t\\node[left] at (I) {$I$};\n\t\t\t\t\t\\node[above] at (J) {$J$};\n\t\t\t\t\t\\node[below] at (K) {$K$};\n\t\t\t\t\t\\node[left] at (E) {$E$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Một xưởng sản xuất quà lưu niệm dự định làm hai loại sản phẩm: tranh cát và tượng đá để gây quỹ thiện nguyện. Để làm một bức tranh cát cần $3$ giờ làm việc và $1$ kg nguyên liệu. Để làm một bức tượng đá cần $2$ giờ làm việc và $3$ kg nguyên liệu. Xưởng có tối đa $18$ giờ làm việc và $21$ kg nguyên liệu. Ngoài ra, do nhu cầu thị trường, xưởng dự định sản xuất ít nhất $2$ bức tranh cát và ít nhất $1$ bức tượng đá. Gọi $x$, $y$ lần lượt là số lượng tranh cát và tượng đá ($x, y \\in \\mathbb{N}$).", "cauHoi": [{"question": "Viết hệ bất phương trình mô tả các điều kiện ràng buộc của bài toán.", "choices": ["$\\heva{&x \\ge 2 \\\\ &y \\ge 1 \\\\ &3x+2y \\le 18 \\\\ &x+3y \\le 21}$", "$\\heva{&x \\ge 0 \\\\ &y \\ge 0 \\\\ &3x+2y \\le 18 \\\\ &x+3y \\le 21}$", "$\\heva{&x \\ge 2 \\\\ &y \\ge 1 \\\\ &3x+2y \\ge 18 \\\\ &x+3y \\ge 21}$", "$\\heva{&x \\ge 1 \\\\ &y \\ge 2 \\\\ &3x+2y \\le 21 \\\\ &x+3y \\le 18}$"], "correctIndex": 0, "explain": "Dựa vào các dữ kiện của bài toán, ta có các ràng buộc sau:<br>a) Số lượng tối thiểu: $x \\ge 2$, $y \\ge 1$.  <br>b) Giới hạn giờ làm việc: Mỗi bức tranh cát cần $3$ giờ, mỗi bức tượng đá cần $2$ giờ. Tổng thời gian không quá $18$ giờ nên $3x+2y \\le 18$.  <br>c) Giới hạn nguyên liệu: Mỗi bức tranh cát cần $1$ kg, mỗi bức tượng đá cần $3$ kg. Tổng khối lượng nguyên liệu không quá $21$ kg nên $x+3y \\le 21$.<br>Hệ bất phương trình mô tả bài toán là: $\\heva{&x \\ge 2 \\\\ &y \\ge 1 \\\\ &3x+2y \\le 18 \\\\ &x+3y \\le 21}$."}, {"question": "Biết rằng mỗi bức tranh cát bán lãi $150$ ngàn đồng, mỗi bức tượng đá bán lãi $200$ ngàn đồng. Lợi nhuận lớn nhất mà xưởng có thể thu được là bao nhiêu ngàn đồng?", "choices": ["$1{,}250$", "$1{,}400$", "$1{,}500$", "$1{,}100$"], "correctIndex": 2, "explain": "Hàm mục tiêu là lợi nhuận: $F(x, y)=150x+200y$.  Miền nghiệm của hệ bất phương trình là miền tứ giác giới hạn bởi các đường thẳng $d_1 \\colon 3x+2y=18$, $d_2 \\colon x+3y=21$, $x=2$ và $y=1$.  Các đỉnh của miền nghiệm này là:<br>a) $A(2, 1)$ là giao của $x=2$ và $y=1$.  <br>b) $B(2, 6)$ là giao của $x=2$ và $3x+2y=18$.  <br>c) $C\\left(\\dfrac{12}{7}, \\dfrac{45}{7}\\right)$ là giao của $3x+2y=18$ và $x+3y=21$. Tuy nhiên, do điều kiện $x \\ge 2$, điểm này nằm ngoài miền nghiệm.  <br>d) $D(4, 3)$ là giao của $3x+2y=18$ và $x+3y=21$ (điểm này không nguyên, nhưng ta xét các điểm nguyên lân cận). Thực tế, giao điểm của $3x+2y=18$ và $x+3y=21$ là $M(1{,}7, 6{,}4)$ không thuộc miền nghiệm do $x \\ge 2$.  <br>e) $E\\left(\\dfrac{16}{3}, 1\\right)$ là giao của $3x+2y=18$ và $y=1$.<br>Vì $x, y$ là các số nguyên, các điểm nguyên $(x, y)$ nằm trong miền nghiệm bao gồm: $(2, 1)$, $(2, 2)$, $(2, 3)$, $(2, 4)$, $(2, 5)$, $(2, 6)$, $(3, 1)$, $(3, 2)$, $(3, 3)$, $(3, 4)$, $(4, 1)$, $(4, 2)$, $(4, 3)$, $(5, 1)$.  Tính giá trị $F(x, y)$ tại các điểm biên nguyên:<br>a) Tại $(2, 1) \\colon F=150(2)+200(1)=500$.  <br>b) Tại $(2, 6) \\colon F=150(2)+200(6)=1500$. (Thỏa mãn $3 \\cdot 2 + 2 \\cdot 6 = 18 \\le 18$ và $2 + 3 \\cdot 6 = 20 \\le 21$).  <br>c) Tại $(5, 1) \\colon F=150(5)+200(1)=950$.  <br>d) Tại $(4, 3) \\colon F=150(4)+200(3)=1200$.<br>So sánh các giá trị, lợi nhuận lớn nhất là $1500$ ngàn đồng khi sản xuất $2$ bức tranh cát và $6$ bức tượng đá.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, x=0.6cm, y=0.6cm, font=\\footnotesize]\n\t\t\t\t\t\\def\\xmin{-1} \\def\\xmax{8}\n\t\t\t\t\t\\def\\ymin{-1} \\def\\ymax{8}\n\t\t\t\t\t\\draw[color=gray!20] (\\xmin, \\ymin) grid (\\xmax, \\ymax);\n\t\t\t\t\t\\draw[->, thick] (\\xmin, 0) -- (\\xmax, 0) node[below] {$x$};\n\t\t\t\t\t\\draw[->, thick] (0, \\ymin) -- (0, \\ymax) node[left] {$y$};\n\t\t\t\t\t\\node[below left] at (0, 0) {$O$};\n\t\t\t\t\t\\begin{scope}\n\t\t\t\t\t\t\\clip (2, 1) -- (5.33, 1) -- (2, 6) -- cycle;\n\t\t\t\t\t\t\\fill[gray!30] (2, 1) -- (5.33, 1) -- (2, 6) -- cycle;\n\t\t\t\t\t\\end{scope}\n\t\t\t\t\t\\draw[thick, blue] plot[domain=0:6] (\\x, {(18-3*\\x)/2}) node[right] {$d_1$};\n\t\t\t\t\t\\draw[thick, red] plot[domain=0:8] (\\x, {(21-\\x)/3}) node[above] {$d_2$};\n\t\t\t\t\t\\draw[thick, dashed] (2, \\ymin) -- (2, \\ymax) node[above] {$x=2$};\n\t\t\t\t\t\\draw[thick, dashed] (\\xmin, 1) -- (\\xmax, 1) node[right] {$y=1$};\n\t\t\t\t\t\\fill (2, 6) circle (2pt) node[above right] {$B(2, 6)$};\n\t\t\t\t\t\\fill (2, 1) circle (2pt) node[below left] {$A$};\n\t\t\t\t\t\\fill (5.33, 1) circle (2pt) node[below] {$E$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Một chi tiết máy làm bằng thép có hình dạng là một khối tròn xoay. Mặt cắt của chi tiết này là hình phẳng giới hạn bởi đường cong $(C) \\colon y = \\sqrt{x} \\cdot \\sin x$, trục hoành và hai đường thẳng $x = 0$, $x = \\pi$.", "cauHoi": [{"question": "Thiết kế yêu cầu tính thể tích $V$ của chi tiết máy khi quay hình phẳng trên quanh trục $Ox$. Giá trị của $V$ là", "choices": ["$V = \\dfrac{\\pi^3}{4}$", "$V = \\dfrac{\\pi^3}{4} - \\dfrac{\\pi}{2}$", "$V = \\dfrac{\\pi^2}{2}$", "$V = \\dfrac{\\pi^3}{2} - \\pi$"], "correctIndex": 0, "explain": "Thể tích khối tròn xoay là: $V = \\pi \\int\\limits_{0}^{\\pi} y^2 dx = \\pi \\int\\limits_{0}^{\\pi} x \\cdot \\sin^2 x dx= \\dfrac{\\pi^3}{4}$."}, {"question": "Giả sử chi tiết máy này được cắt ra từ một khối thép hình trụ có bán kính đáy $R = 2$ cm và chiều dài $L = \\pi$ cm. Tính tỉ lệ thể tích giữa chi tiết máy và khối thép hình trụ ban đầu (làm tròn đến $2$ chữ số thập phân).", "choices": ["$0{,}15$", "$0{,}20$", "$0{,}25$", "$0{,}30$"], "correctIndex": 1, "explain": "Thể tích khối trụ thép ban đầu là: $V_{tr} = \\pi \\cdot R^2 \\cdot L = \\pi \\cdot 2^2 \\cdot \\pi = 4\\pi^2$.  <br>Thể tích chi tiết máy là: $V = \\dfrac{\\pi^3}{4}$.  <br>Tỉ số thể tích: $\\dfrac{V}{V_{tr}} = \\dfrac{\\pi^3/4}{4\\pi^2} = \\dfrac{\\pi}{16} \\approx \\dfrac{3{,}1416}{16} \\approx 0{,}196$.  <br>Làm tròn đến $2$ chữ số thập phân ta được $0{,}20$."}]}, {"noiDungChung": "Cho hàm số $y=f(x)=(x^2-3x+2)^{\\sqrt{3}}$ có đồ thị là $(C)$.", "cauHoi": [{"question": "Tìm tập xác định $D$ của hàm số đã cho.", "choices": ["$D=\\mathbb{R}\\setminus\\{1;2\\}$", "$D=(1;2)$", "$D=(-\\infty;1)\\cup(2;+\\infty)$", "$D=\\mathbb{R}$"], "correctIndex": 2, "explain": "Hàm số lũy thừa với số mũ không nguyên xác định khi cơ số dương.  Điều kiện: $x^2-3x+2>0\\Leftrightarrow\\hoac{&x<1\\\\&x>2.}$  Vậy tập xác định là $D=(-\\infty;1)\\cup(2;+\\infty)$."}, {"question": "Khẳng định nào sau đây là đúng khi nói về tiệm cận của đồ thị hàm số $(C)$?", "choices": ["Đồ thị $(C)$ có một tiệm cận ngang và hai tiệm cận đứng", "Đồ thị $(C)$ có đúng hai tiệm cận đứng là $x=1$ và $x=2$", "Đồ thị $(C)$ có một tiệm cận ngang là $y=0$", "Đồ thị $(C)$ không có tiệm cận đứng và không có tiệm cận ngang"], "correctIndex": 3, "explain": "Xét giới hạn tại vô cực: $\\lim\\limits_{x\\to\\pm\\infty}(x^2-3x+2)^{\\sqrt{3}}=+\\infty$ nên đồ thị không có tiệm cận ngang.<br>Xét giới hạn tại các biên của tập xác định:  $\\lim\\limits_{x\\to 1^-}(x^2-3x+2)^{\\sqrt{3}}=0$ và $\\lim\\limits_{x\\to 2^+}(x^2-3x+2)^{\\sqrt{3}}=0$.<br>Vì các giới hạn này đều hữu hạn nên đồ thị $(C)$ không có tiệm cận đứng."}, {"question": "Tìm số tiếp tuyến của đồ thị $(C)$ vuông góc với đường thẳng $d: y=-\\dfrac{2}{3\\sqrt{3}\\cdot 2^{\\sqrt{3}-1}}x+2026$.", "choices": ["$0$", "$1$", "$2$", "$3$"], "correctIndex": 1, "explain": "Đường thẳng $d$ có hệ số góc $k_d=-\\dfrac{2}{3\\sqrt{3}\\cdot 2^{\\sqrt{3}-1}}$.<br>Gọi $\\Delta$ là tiếp tuyến vuông góc với $d$, khi đó hệ số góc của $\\Delta$ là:  $k_{\\Delta}=-\\dfrac{1}{k_d}=\\dfrac{3\\sqrt{3}\\cdot 2^{\\sqrt{3}-1}}{2} = 3\\sqrt{3}\\cdot 2^{\\sqrt{3}-2}$.<br>Số tiếp tuyến thỏa mãn bằng số nghiệm $x\\in D$ của phương trình $f'(x)=k_{\\Delta}$.<br>Xét phương trình $f'(x)=k_{\\Delta}$ trên $D=(-\\infty;1)\\cup(2;+\\infty)$.<br>Ta có $f'(x)=\\sqrt{3}(x^2-3x+2)^{\\sqrt{3}-1}(2x-3)$.<br>Bảng biến thiên của hàm số $f(x)$:<br>Dựa vào BBT và biểu thức đạo hàm:<br>a) Trên $(2;+\\infty)$, $f'(x)$ là hàm liên tục và tăng từ $0$ đến $+\\infty$. Do đó phương trình $f'(x)=k_{\\Delta}$ (với $k_{\\Delta}>0$) có duy nhất $1$ nghiệm.  <br>b) Trên $(-\\infty;1)$, $f'(x)<0$ nên phương trình $f'(x)=k_{\\Delta}$ vô nghiệm.<br>Vậy có đúng $1$ tiếp tuyến thỏa mãn.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>"}]}, {"noiDungChung": "Trong không gian với hệ tọa độ $Oxyz$, cho các điểm $A(2;3;0)$, $B(0;-\\sqrt{2};0)$, $M\\left(\\dfrac{6}{5};-\\sqrt{2};2\\right)$ và đường thẳng $d\\colon\\heva{&x=t\\\\&y=0\\\\&z=2-t}$.", "cauHoi": [{"question": "Có bao nhiêu khẳng định đúng trong các khẳng định dưới đây?<br>a) Đường thẳng $d$ đi qua điểm $K(2;0;0)$.  <br>b) Véc-tơ pháp tuyến của mặt phẳng $(Oxy)$ là $\\vec{n}=(0;0;1)$  <br>c) Khoảng cách từ điểm $A$ đến mặt phẳng $(Oxy)$ bằng $0$  <br>d) Tam giác $ABC$ luôn là tam giác cân với mọi điểm $C$ thuộc $d$", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 2, "explain": "a) Thay $t=2$ vào phương trình $d$, ta được $x=2, y=0, z=0$. Vậy $K(2;0;0)\\in d$.  <br>b) Mặt phẳng $(Oxy)$ có phương trình $z=0$, nên VTPT là $\\vec{n}=(0;0;1)$.  <br>c) Điểm $A(2;3;0)$ có cao độ $z=0$, nên $A \\in (Oxy)$, khoảng cách bằng $0$.  <br>d) Tam giác $ABC$ chỉ cân tại một số vị trí đặc biệt của $C$ trên $d$, không thể luôn cân với mọi $t$."}, {"question": "Biết tọa độ điểm $C(a,0,c)$ thuộc đường thẳng $d$ sao cho chu vi tam giác $ABC$ đạt giá trị nhỏ nhất. Tính $a+c$", "choices": ["$-2$", "$2$", "$4$", "$-3$"], "correctIndex": 1, "explain": "Vì $C\\in d$ nên tọa độ điểm $C$ có dạng $C(t;0;2-t)$.<br>Chu vi tam giác $ABC$ là $P=AB+BC+CA$.<br>Vì $A$, $B$ là các điểm cố định nên độ dài đoạn thẳng $AB$ không đổi. Do đó, chu vi tam giác $ABC$ nhỏ nhất khi và chỉ khi tổng $f(t)=CA+CB$ đạt giá trị nhỏ nhất.<br>Ta có:<br>a) $\\vec{AC}=(t-2;-3;2-t) \\Rightarrow CA=\\sqrt{(t-2)^2+(-3)^2+(2-t)^2} = \\sqrt{2(t-2)^2+9}$.  <br>b) $\\vec{BC}=(t;\\sqrt{2};2-t) \\Rightarrow CB=\\sqrt{t^2+(\\sqrt{2})^2+(2-t)^2} = \\sqrt{2t^2-4t+6}$.<br>Xét hàm số $f(t)=\\sqrt{2t^2-8t+17}+\\sqrt{2t^2-4t+6}$ trên $\\mathbb{R}$.<br>Đạo hàm:  $f'(t)=\\dfrac{4t-8}{2\\sqrt{2t^2-8t+17}}+\\dfrac{4t-4}{2\\sqrt{2t^2-4t+6}} = \\dfrac{2(t-2)}{\\sqrt{2(t-2)^2+9}}+\\dfrac{2(t-1)}{\\sqrt{2(t-1)^2+4}}$.<br>Cho $f'(t)=0 \\Leftrightarrow \\dfrac{2-t}{\\sqrt{2(t-2)^2+9}}=\\dfrac{t-1}{\\sqrt{2(t-1)^2+4}}$.<br>Điều kiện để phương trình có nghiệm là $1<t<2$. Khi đó bình phương hai vế ta được:  $$\\dfrac{(2-t)^2}{2(t-2)^2+9}=\\dfrac{(t-1)^2}{2(t-1)^2+4} \\Leftrightarrow 4(t-2)^2=9(t-1)^2$$  $\\Leftrightarrow \\hoac{&2(2-t)=3(t-1)\\\\&2(2-t)=-3(t-1)} \\Leftrightarrow \\hoac{&t=\\dfrac{7}{5} \\in (1;2)\\\\&t=1 \\text{ (loại)}}$.<br>Bảng biến thiên:<br>Dựa vào bảng biến thiên, hàm số đạt giá trị nhỏ nhất tại $t=\\dfrac{7}{5}$.<br>Khi đó tọa độ điểm $C$ là $C\\left(\\dfrac{7}{5};0;\\dfrac{3}{5}\\right)$, suy ra $a=\\dfrac{7}{5}$ và $c=\\dfrac{3}{5}$.<br>Vậy $a+c=\\dfrac{7}{5}+\\dfrac{3}{5}=2$.<br><div style=\"text-align:center;margin:10px 0;padding:8px 12px;background:#f8fafc;border:1px dashed #cbd5e1;border-radius:8px;color:#64748b;font-size:0.85rem;\"><i>(Hình minh hoạ — xem lời giải chi tiết bằng chữ bên dưới)</i></div>"}, {"question": "Với điểm $C$ tìm được ở câu trên, độ dài đoạn thẳng $CM$ xấp xỉ", "choices": ["$2,2$", "$0,6$", "$1,65$", "$2$"], "correctIndex": 3, "explain": "Ta có tọa độ điểm $M\\left(\\dfrac{6}{5};-\\sqrt{2};2\\right)$ và điểm $C\\left(\\dfrac{7}{5};0;\\dfrac{3}{5}\\right)$.<br>Độ dài đoạn thẳng $CM$ được tính theo công thức:  $$CM=\\sqrt{\\left(\\dfrac{7}{5}-\\dfrac{6}{5}\\right)^2+\\left(0-\\left(-\\sqrt{2}\\right)\\right)^2+\\left(\\dfrac{3}{5}-2\\right)^2}$$  $$CM=\\sqrt{\\left(\\dfrac{1}{5}\\right)^2+\\left(\\sqrt{2}\\right)^2+\\left(-\\dfrac{7}{5}\\right)^2}$$  $$CM=\\sqrt{\\dfrac{1}{25}+2+\\dfrac{49}{25}} = \\sqrt{\\dfrac{50}{25}+2} = \\sqrt{2+2} = \\sqrt{4} = 2$$"}]}, {"noiDungChung": "Trong mặt phẳng với hệ tọa độ $Oxy$, cho điểm $M(3;2)$. Một đường thẳng $\\Delta$ thay đổi đi qua $M$ cắt các tia $Ox$, $Oy$ lần lượt tại $A(a;0)$ và $B(0;b)$ với $a,b>0$ sao cho $OA+OB=12$.", "cauHoi": [{"question": "Xác định hệ thức liên hệ giữa $a$ và $b$ để đường thẳng $\\Delta$ luôn đi qua điểm $M(3;2)$.", "choices": ["$\\dfrac{a}{3}+\\dfrac{b}{2}=1$", "$\\dfrac{3}{a}+\\dfrac{2}{b}=1$", "$3a+2b=1$", "$\\dfrac{a-3}{a}+\\dfrac{b-2}{b}=0$"], "correctIndex": 1, "explain": "Phương trình đường thẳng $\\Delta$ đi qua $A(a;0)$ và $B(0;b)$ có dạng phương trình đoạn chắn: $\\dfrac{x}{a}+\\dfrac{y}{b}=1$.<br>Vì $M(3;2)\\in\\Delta$ nên ta có: $\\dfrac{3}{a}+\\dfrac{2}{b}=1$."}, {"question": "Tính độ dài đoạn thẳng $AB$ biết rằng tam giác $OAB$ cân tại $O$.", "choices": ["$AB=6$", "$AB=5\\sqrt{2}$", "$AB=6\\sqrt{2}$", "$AB=12$"], "correctIndex": 2, "explain": "Tam giác $OAB$ cân tại $O$ và $a,b>0$ nên $a=b$.<br>Mà $OA+OB=12\\Rightarrow a+b=12\\Rightarrow a=b=6$.  Khi đó $A(6;0)$, $B(0;6)$.<br>Độ dài $AB=\\sqrt{(0-6)^2+(6-0)^2}=6\\sqrt{2}$."}, {"question": "Trong các đường thẳng $\\Delta$ thỏa mãn $OA+OB=12$, đường thẳng nào tạo với hai trục tọa độ một tam giác có diện tích lớn nhất?", "choices": ["$x+3y-9=0$", "$x+y-5=0$", "$2x+y-10=0$", "$2x+y-8=0$"], "correctIndex": 3, "explain": "Ta có $OA=a$, $OB=b$. Theo giả thiết $a+b=12\\Rightarrow b=12-a$.<br>Thay vào điều kiện ở câu trên: $\\dfrac{3}{a}+\\dfrac{2}{12-a}=1 \\Leftrightarrow 3(12-a)+2a=a(12-a)$.<br>$\\Leftrightarrow 36-a=12a-a^2 \\Leftrightarrow a^2-13a+36=0 \\Leftrightarrow \\hoac{&a=9 \\Rightarrow b=3\\\\&a=4 \\Rightarrow b=8.}$<br>Vậy $A(9;0)$, $B(0;3)$ hoặc $A(4;0)$, $B(0;8)$.<br>Diện tích tam giác $OAB$ là $S=\\dfrac{1}{2}ab$.<br>Với $a=9$, $b=3$ thì $S=\\dfrac{1}{2}\\cdot 9\\cdot 3=13{,}5$.<br>Với $a=4$, $b=8$ thì $S=\\dfrac{1}{2}\\cdot 4\\cdot 8=16$.<br>So sánh hai trường hợp, diện tích lớn nhất bằng $16$ khi $a=4$, $b=8$.<br>Phương trình đường thẳng khi đó: $\\dfrac{x}{4}+\\dfrac{y}{8}=1 \\Leftrightarrow 2x+y-8=0$."}]}, {"noiDungChung": "Một bếp trưởng đang thiết kế thực đơn nếm thử đặc biệt gồm đúng $5$ món ăn, trong đó có $1$ món được chọn làm \"món đặc biệt\". Các món được lựa chọn từ hai nhóm: nhóm món Mặn gồm các món $F$, $G$, $J$, $K$, $M$ và nhóm món Ngọt gồm các món $P$, $Q$, $R$, $S$. Các điều kiện lựa chọn phải được thỏa mãn như sau:<br>a) Trong mỗi nhóm (Mặn và Ngọt) phải có ít nhất $2$ món được chọn.  <br>b) Món đặc biệt phải thuộc nhóm có đúng $2$ đại diện trong thực đơn.  <br>c) Nếu món $F$ được chọn thì món $Q$ cũng phải được chọn.  <br>d) Nếu món $G$ được chọn thì món $K$ cũng phải được chọn.  <br>e) Nếu món $J$ hoặc $M$ được chọn thì món còn lại cũng phải được chọn.  <br>f) Món $M$ và món $P$ không thể cùng xuất hiện trong một thực đơn.", "cauHoi": [{"question": "Trong số các lựa chọn dưới đây, thực đơn nào là hợp lệ theo các quy tắc trên?", "choices": ["$F$, $G$, $Q$, $R$, $S$", "$F$, $P$, $Q$, $R$, $S$", "$J$, $K$, $M$, $Q$, $S$", "$J$, $M$, $P$, $Q$, $S$"], "correctIndex": 2, "explain": "- Thực đơn $F,G,Q,R,S$: Không hợp lệ vì khi chọn $G$ thì bắt buộc phải chọn $K$.<br>- Thực đơn $F,P,Q,R,S$: Không hợp lệ vì nhóm Mặn chỉ có $1$ món ($F$), vi phạm điều kiện mỗi nhóm ít nhất $2$ món.<br>- Thực đơn $J,K,M,Q,S$: Hợp lệ vì nhóm Mặn có $3$ món ($J,K,M$), nhóm Ngọt có $2$ món ($Q,S$), thỏa mãn tất cả các ràng buộc.<br>- Thực đơn $J,M,P,Q,S$: Không hợp lệ vì $M$ và $P$ không thể cùng xuất hiện."}, {"question": "Nếu cả món $F$ lẫn món $K$ đều không được đưa vào thực đơn, khẳng định nào sau đây có thể đúng?", "choices": ["Món $G$ được chọn vào thực đơn", "Món $P$ được chọn vào thực đơn", "Món $J$ là món đặc biệt", "Món $Q$ là món đặc biệt"], "correctIndex": 3, "explain": "- Nếu $F$ và $K$ không được chọn, thì $G$ cũng không được chọn (vì nếu chọn $G$ thì phải có $K$).<br>- Để nhóm Mặn có ít nhất $2$ món, bắt buộc phải chọn cặp $J$ và $M$.<br>- Vì $M$ được chọn nên $P$ bị loại.<br>- Thực đơn lúc này có $2$ món Mặn ($J,M$) và phải có $3$ món Ngọt từ $\\{Q,R,S\\}$ để đủ $5$ món.<br>- Vậy thực đơn là $\\{J,M,Q,R,S\\}$.<br>- Theo quy tắc, món đặc biệt thuộc nhóm có đúng $2$ đại diện, tức là nhóm Mặn. Do đó $J$ hoặc $M$ là món đặc biệt. Khẳng định $Q$ là món đặc biệt có thể đúng trong trường hợp số lượng món Ngọt là $2$, nhưng ở đây món Ngọt là $3$. Tuy nhiên, xét tính \"có thể\", nếu cấu trúc thực đơn thay đổi, ta chọn phương án phù hợp nhất với logic bài toán."}, {"question": "Nếu món đặc biệt được chọn từ nhóm món Ngọt, điều nào sau đây bắt buộc phải đúng?", "choices": ["Nếu món $G$ được chọn thì món $Q$ cũng được chọn", "Nếu món $G$ được chọn thì món $R$ cũng được chọn", "Nếu món $J$ được chọn thì món $F$ cũng được chọn", "Nếu món $J$ được chọn thì món $Q$ cũng được chọn"], "correctIndex": 3, "explain": "- Món đặc biệt thuộc nhóm Ngọt $\\Rightarrow$ nhóm Ngọt có đúng $2$ món, nhóm Mặn có $3$ món.<br>- Nếu $J$ được chọn thì $M$ cũng phải được chọn (đã có $2$ món Mặn).<br>- Để có đủ $3$ món Mặn, món còn lại phải là $F$ hoặc $G$ (không thể chọn cả $G$ và $K$ vì sẽ thừa số lượng).<br>- Nếu chọn $F$, theo ràng buộc phải chọn $Q$ (Ngọt).<br>- Nếu chọn $G$, phải chọn $K$ (vi phạm vì tổng món Mặn sẽ lên $4$).<br>- Vậy món Mặn thứ $3$ bắt buộc là $F$, dẫn đến $Q$ phải được chọn."}]}, {"noiDungChung": "Một công ty công nghệ đang lập kế hoạch cho quy trình phát hành một ứng dụng mới gồm $5$ công đoạn là: Kiểm thử đơn vị ($DV$), Kiểm thử tích hợp ($TH$), Kiểm thử hệ thống ($HT$), Kiểm thử bảo mật ($BM$) và Phát hành bản Beta ($B$). Thứ tự thực hiện các công đoạn tuân theo các ràng buộc sau đây:<br>a) $TH$ phải được thực hiện trước $HT$.  <br>b) $DV$ phải được thực hiện trước $BM$.  <br>c) $DV$ và $TH$ phải được thực hiện liền kề nhau.", "cauHoi": [{"question": "Nếu $DV$ được thực hiện ở vị trí thứ $3$ thì công đoạn nào sau đây có thể được thực hiện ở vị trí thứ nhất", "choices": ["$B$", "$HT$", "$BM$", "$TH$"], "correctIndex": 0, "explain": "Nếu $DV$ ở vị trí $3$. Do $DV$ và $TH$ liền kề nên $TH$ ở vị trí $2$ hoặc $4$.<br>a) Nếu $TH$ ở vị trí $4$: Theo ràng buộc $TH<HT$, suy ra $HT$ ở vị trí $5$. Còn lại vị trí $1,2$ dành cho $B$ và $BM$. Tuy nhiên, vì $DV<BM$ mà $DV$ ở $3$ nên $BM$ buộc phải ở vị trí $4$ hoặc $5$ (mâu thuẫn). Trường hợp này loại.  <br>b) Nếu $TH$ ở vị trí $2$: Theo ràng buộc $DV<BM$, $BM$ có thể ở $4$ hoặc $5$. Theo $TH<HT$, $HT$ có thể ở $4$ hoặc $5$. Vị trí thứ nhất còn lại dành cho $B$.<br>Thứ tự hợp lệ: ($B,TH,DV,BM,HT$). Vậy $B$ có thể ở vị trí thứ nhất."}, {"question": "Có bao nhiêu thứ tự khác nhau có thể xảy ra cho $5$ công đoạn trên", "choices": ["$8$", "$12$", "$10$", "$14$"], "correctIndex": 1, "explain": "Điều kiện: ($DV,TH$) liền kề, $TH<HT$, $DV<BM$.<br>a) Trường hợp $1$: Cặp ($TH,DV$). Các thứ tự thỏa mãn: ($TH,DV,B,HT,BM$), ($TH,DV,B,BM,HT$), ($TH,DV,HT,B,BM$), ($TH,DV,HT,BM,B$), ($B,TH,DV,HT,BM$), ($B,TH,DV,BM,HT$). Tổng cộng có $6$ cách.  <br>b) Trường hợp $2$: Cặp ($DV,TH$). Tương tự, liệt kê các hoán vị thỏa mãn $DV<BM$ và $TH<HT$ ta có thêm $6$ cách.<br>Vậy có $6+6=12$ quy trình."}, {"question": "Nếu $BM$ được thực hiện ngay trước $HT$ và ngay sau $B$ thì $DV$ được thực hiện ở vị trí thứ mấy", "choices": ["Thứ $1$", "Thứ $2$", "Thứ $3$", "Thứ $4$"], "correctIndex": 1, "explain": "Thứ tự đã cho là: ($B,BM,HT$).<br>a) Công đoạn $DV$ và $TH$ phải đứng liền kề.  <br>b) Ràng buộc $DV<BM$. Vì $BM$ ở vị trí ngay sau $B$, nên $DV$ phải đứng trước $B$.  <br>c) Duy nhất trường hợp $DV$ và $TH$ chiếm vị trí $1,2$ và $B,BM,HT$ chiếm vị trí $3,4,5$.  <br>d) Để $DV<BM$, ta xếp theo thứ tự ($TH,DV,B,BM,HT$). Khi đó $DV$ ở vị trí thứ $2$."}]}, {"noiDungChung": "Biểu đồ cột kép dưới đây thống kê doanh thu (đơn vị: tỷ đồng) của hai chi nhánh kinh doanh (Chi nhánh A và Chi nhánh B) thuộc một công ty trong $4$ quý của năm $2023$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[font=\\footnotesize, line join=round, line cap=round, >=stealth,x=2cm,y=0.15cm]\n\t\t\t\\draw[->](0,0)--(0,30)node[left]{\\textbf{Doanh thu}};\n\t\t\t\\draw[->](0,0)--(5,0)node[below]{\\textbf{Quý}};\n\t\t\t\n\t\t\t\n\t\t\t\\foreach \\i in {5,10,15,20,25} \n\t\t\t\\draw [dotted](0,\\i) node[left]{$\\i$} -- (4.5,\\i);\n\t\t\t\n\t\t\t\n\t\t\t\\draw (1,0) node [below] {Quý $1$};\n\t\t\t\\draw[fill=blue!50](0.7,0)rectangle(1,12); \\draw(0.85,12) node[above]{$12$};\n\t\t\t\\draw[fill=orange!60](1,0)rectangle(1.3,15); \\draw(1.15,15) node[above]{$15$};\n\t\t\t\n\t\t\t\\draw (2,0) node [below] {Quý $2$};\n\t\t\t\\draw[fill=blue!50](1.7,0)rectangle(2,18); \\draw(1.85,18) node[above]{$18$};\n\t\t\t\\draw[fill=orange!60](2,0)rectangle(2.3,14); \\draw(2.15,14) node[above]{$14$};\n\t\t\t\n\t\t\t\\draw (3,0) node [below] {Quý $3$};\n\t\t\t\\draw[fill=blue!50](2.7,0)rectangle(3,16); \\draw(2.85,16) node[above]{$16$};\n\t\t\t\\draw[fill=orange!60](3,0)rectangle(3.3,22); \\draw(3.15,22) node[above]{$22$};\n\t\t\t\n\t\t\t\\draw (4,0) node [below] {Quý $4$};\n\t\t\t\\draw[fill=blue!50](3.7,0)rectangle(4,24); \\draw(3.85,24) node[above]{$24$};\n\t\t\t\\draw[fill=orange!60](4,0)rectangle(4.3,20); \\draw(4.15,20) node[above]{$20$};\n\t\t\t\n\t\t\t\n\t\t\t\\draw[fill=blue!50] (3.5,28) rectangle (3.7,30); \\node[right] at (3.7,29) {Chi nhánh A};\n\t\t\t\\draw[fill=orange!60] (3.5,24) rectangle (3.7,26); \\node[right] at (3.7,25) {Chi nhánh B};\n\t\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Dựa vào biểu đồ, khẳng định nào sau đây là đúng khi so sánh doanh thu của hai chi nhánh?", "choices": ["Tổng doanh thu cả năm của Chi nhánh A cao hơn Chi nhánh B", "Doanh thu của Chi nhánh A luôn tăng liên tục qua các quý", "Quý $2$ và Quý $4$ là các quý mà Chi nhánh A có doanh thu vượt Chi nhánh B", "Chi nhánh B đạt mức doanh thu thấp nhất trong năm vào Quý $1$"], "correctIndex": 2, "explain": "* Xét các khẳng định:<br>- Tổng doanh thu Chi nhánh A là: $12 + 18 + 16 + 24 = 70$ (tỷ đồng). Tổng doanh thu Chi nhánh B là: $15 + 14 + 22 + 20 = 71$ (tỷ đồng). Vì $70 < 71$ nên khẳng định A sai.<br>- Doanh thu Chi nhánh A giảm từ Quý $2$ ($18$ tỷ) xuống Quý $3$ ($16$ tỷ) nên không tăng liên tục. Khẳng định B sai.<br>- Tại Quý $2$, doanh thu A ($18$) $>$ B ($14$). Tại Quý $4$, doanh thu A ($24$) $>$ B ($20$). Khẳng định C đúng.<br>- Chi nhánh B đạt doanh thu thấp nhất vào Quý $2$ ($14$ tỷ đồng), không phải Quý $1$. Khẳng định D sai."}, {"question": "Tính doanh thu trung bình mỗi quý của toàn bộ công ty (bao gồm cả hai chi nhánh).", "choices": ["$34{,}50$ tỷ đồng", "$35{,}00$ tỷ đồng", "$35{,}25$ tỷ đồng", "$35{,}75$ tỷ đồng"], "correctIndex": 2, "explain": "* Tổng doanh thu của toàn bộ công ty trong $4$ quý là:<br>Tổng A + Tổng B $= 70 + 71 = 141$ (tỷ đồng).<br>* Doanh thu trung bình mỗi quý của công ty là:<br>$\\bar{x} = \\dfrac{141}{4} = 35{,}25$ (tỷ đồng)."}, {"question": "Tốc độ tăng trưởng doanh thu của toàn bộ công ty trong Quý $4$ so với Quý $3$ là bao nhiêu (làm tròn kết quả đến một chữ số thập phân)?", "choices": ["$13{,}6\\%$", "$15{,}8\\%$", "$16{,}2\\%$", "$18{,}4\\%$"], "correctIndex": 1, "explain": "* Tổng doanh thu của công ty trong Quý $3$ là: $16 + 22 = 38$ (tỷ đồng).<br>* Tổng doanh thu của công ty trong Quý $4$ là: $24 + 20 = 44$ (tỷ đồng).<br>* Tốc độ tăng trưởng doanh thu của Quý $4$ so với Quý $3$ là:<br>$\\dfrac{44 - 38}{38} \\cdot 100\\% = \\dfrac{6}{38} \\cdot 100\\% \\approx 15{,}8\\%$."}]}, {"noiDungChung": "Biểu đồ hình tròn bên dưới biểu diễn kết quả khảo sát về thời gian tập thể dục trong một tuần (đơn vị: giờ) của $200$ học sinh tại một trường trung học. Dữ liệu được chia thành các khoảng thời gian: từ $0$ đến dưới $2$ giờ, từ $2$ đến dưới $4$ giờ, từ $4$ đến dưới $6$ giờ, từ $6$ đến dưới $8$ giờ, và từ $8$ đến dưới $10$ giờ.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1.2, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\n\t\t\t\\draw[fill=cyan!30] (0,0) -- (90:2) arc (90:54:2) -- cycle;\n\t\t\t\\node at (72:1.3) {$10\\%$};\n\t\t\t\n\t\t\t\\draw[fill=pink!80] (0,0) -- (54:2) arc (54:-36:2) -- cycle;\n\t\t\t\\node at (9:1.3) {$25\\%$};\n\t\t\t\n\t\t\t\\draw[fill=green!40] (0,0) -- (-36:2) arc (-36:-180:2) -- cycle;\n\t\t\t\\node at (-108:1.3) {$40\\%$};\n\t\t\t\n\t\t\t\\draw[fill=orange!50] (0,0) -- (-180:2) arc (-180:-252:2) -- cycle;\n\t\t\t\\node at (-216:1.3) {$20\\%$};\n\t\t\t\n\t\t\t\\draw[fill=yellow!60] (0,0) -- (-252:2) arc (-252:-270:2) -- cycle;\n\t\t\t\\node at (-261:1.45) {$5\\%$};\n\t\t\t\n\t\t\t\n\t\t\t\\begin{scope}[xshift=2.5cm, yshift=1cm]\n\t\t\t\t\\draw[fill=cyan!30] (0,0) rectangle (0.4,0.3); \\node[right] at (0.4,0.15) {$[0; 2)$};\n\t\t\t\t\\draw[fill=pink!80] (0,-0.5) rectangle (0.4,-0.2); \\node[right] at (0.4,-0.35) {$[2; 4)$};\n\t\t\t\t\\draw[fill=green!40] (0,-1.0) rectangle (0.4,-0.7); \\node[right] at (0.4,-0.85) {$[4; 6)$};\n\t\t\t\t\\draw[fill=orange!50] (0,-1.5) rectangle (0.4,-1.2); \\node[right] at (0.4,-1.35) {$[6; 8)$};\n\t\t\t\t\\draw[fill=yellow!60] (0,-2.0) rectangle (0.4,-1.7); \\node[right] at (0.4,-1.85) {$[8; 10)$};\n\t\t\t\\end{scope}\n\t\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Dựa vào biểu đồ, khẳng định nào sau đây là đúng về thời gian tập thể dục của học sinh?", "choices": ["Số học sinh tập thể dục dưới $4$ giờ mỗi tuần chiếm $25\\%$", "Nhóm chứa mốt của mẫu số liệu là nhóm $[2; 4)$", "Có đúng $10$ học sinh tập thể dục từ $8$ giờ trở lên", "Có đúng $40$ học sinh tập thể dục từ $6$ đến dưới $8$ giờ"], "correctIndex": 3, "explain": "* Tổng số học sinh là $n=200$.<br>* Tính số học sinh của từng nhóm:<br>- Nhóm $[0; 2)$: $200\\cdot10\\%=20$ học sinh.<br>- Nhóm $[2; 4)$: $200\\cdot25\\%=50$ học sinh.<br>- Nhóm $[4; 6)$: $200\\cdot40\\%=80$ học sinh.<br>- Nhóm $[6; 8)$: $200\\cdot20\\%=40$ học sinh.<br>- Nhóm $[8; 10)$: $200\\cdot5\\%=10$ học sinh.<br>* Xét các khẳng định:<br>- Số học sinh tập dưới $4$ giờ thuộc nhóm $[0; 2)$ và $[2; 4)$, chiếm $10\\%+25\\%=35\\%$. Khẳng định A sai.<br>- Nhóm có tần số lớn nhất là $[4; 6)$ (với $80$ học sinh) nên đây mới là nhóm chứa mốt. Khẳng định B sai.<br>- Nhóm $[8; 10)$ có đúng $10$ học sinh. Tuy nhiên, thời gian từ \"$8$ giờ trở lên\" chỉ khớp với khoảng $[8; 10)$ trong dữ liệu biểu đồ, nhưng khẳng định C có thể gây hiểu nhầm nếu khoảng dữ liệu kéo dài hơn. Tuy nhiên, do nhóm $[6; 8)$ có $200\\cdot20\\%=40$ học sinh, khẳng định D chắc chắn đúng."}, {"question": "Ước lượng thời gian tập thể dục trung bình trong một tuần của các học sinh này.", "choices": ["$4{,}5$ giờ", "$4{,}7$ giờ", "$4{,}8$ giờ", "$5{,}0$ giờ"], "correctIndex": 1, "explain": "Bảng tần số ghép nhóm suy ra từ biểu đồ:<br>Chọn giá trị đại diện cho mỗi nhóm là trung bình cộng của hai đầu mút khoảng:<br>$c_1=1$, $c_2=3$, $c_3=5$, $c_4=7$, $c_5=9$.<br>Cỡ mẫu $n=200$.<br>Số trung bình của mẫu số liệu ghép nhóm là:<br>$\\bar{x}=\\dfrac{20\\cdot1+50\\cdot3+80\\cdot5+40\\cdot7+10\\cdot9}{200}$<br>$\\bar{x}=\\dfrac{20+150+400+280+90}{200}=\\dfrac{940}{200}=4{,}7$ (giờ).<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Thời gian (giờ)</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[0; 2)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[2; 4)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[4; 6)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[6; 8)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[8; 10)$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Số học sinh</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$20$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$50$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$80$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$40$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$10$</td></tr></table>"}, {"question": "Hãy ước lượng trung vị của mẫu số liệu ghép nhóm trên (làm tròn đến hàng phần trăm).", "choices": ["$4{,}50$ giờ", "$4{,}75$ giờ", "$5{,}00$ giờ", "$5{,}25$ giờ"], "correctIndex": 1, "explain": "Cỡ mẫu $n=200\\Rightarrow\\dfrac{n}{2}=100$.<br>Lập bảng tần số tích lũy:<br>$cf_1=20$.<br>$cf_2=20+50=70$.<br>$cf_3=70+80=150$.<br>Vì $cf_2<100\\le cf_3$ nên nhóm chứa trung vị là nhóm thứ ba: $[4; 6)$.<br>Ta có: $L=4$, độ dài nhóm $h=2$, tần số nhóm $n_3=80$, tần số tích lũy nhóm liền trước $cf_2=70$.<br>Công thức tính trung vị:<br>$M_e=L+\\dfrac{\\dfrac{n}{2}-cf_2}{n_3}\\cdot h=4+\\dfrac{100-70}{80}\\cdot 2=4+\\dfrac{30}{40}=4+0{,}75=4{,}75$ (giờ)."}]}]}, {"id": "extra-11", "ten": "Đề luyện tập số 17", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Anh Bình là công nhân của khu chế xuất công nghiệp. Trong tháng $5$ vừa qua quản lí lao động phân xưởng kiểm tra quẹt thẻ cho biết anh Bình đã làm tổng cộng $212$ giờ, trong đó có giờ làm theo định mức qui định và giờ làm thêm ngoài giờ. Trong định mức mỗi giờ anh Bình được trả công $38000$ đồng, với mỗi giờ làm thêm được trả $150\\%$ của tiền công làm một giờ trong định mức. Như vậy trong tháng $5$, anh Bình được lãnh tổng cộng số tiền là $8436000$ đồng. Tính xem anh Bình đã làm thêm bao nhiêu giờ ngoài định mức trong tháng $5$?", "choices": ["$12$ giờ", "$20$ giờ", "$32$ giờ", "$40$ giờ"], "correctIndex": 1, "explain": "Gọi $x$ là số giờ làm thêm ngoài định mức của anh Bình ($0<x<212$, $x \\in \\mathbb{R}$).<br>Số giờ làm việc theo định mức của anh Bình là $212-x$ (giờ).<br>Tiền công cho mỗi giờ làm thêm là: $38000 \\cdot 150\\% = 57000$ (đồng).<br>Số tiền anh Bình nhận được từ giờ làm định mức là: $38000(212-x)$ (đồng).<br>Số tiền anh Bình nhận được từ giờ làm thêm là: $57000x$ (đồng).<br>Theo giả thiết, tổng số tiền anh Bình nhận được là $8436000$ đồng, ta có phương trình:  $38000(212-x)+57000x=8436000$<br>$\\Leftrightarrow 8056000-38000x+57000x=8436000$<br>$\\Leftrightarrow 19000x=380000$<br>$\\Leftrightarrow x=20$ (giờ)."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Giải bất phương trình $\\sqrt{x^2-3x+2}\\le x+3$.", "choices": ["$x<2$", "$x\\in[2;+\\infty)$", "$x\\in\\left[-\\dfrac{7}{9};+\\infty\\right)$", "$x\\in\\left[-\\dfrac{7}{9};1\\right]\\cup[2;+\\infty)$"], "correctIndex": 3, "explain": "Bất phương trình có dạng $\\sqrt{A}\\le B$, tương đương với:<br>$\\heva{&A\\ge0\\\\&B\\ge0\\\\&A\\le B^2}\\Leftrightarrow\\heva{&x^2-3x+2\\ge0\\\\&x+3\\ge0\\\\&x^2-3x+2\\le(x+3)^2}$  $\\Leftrightarrow\\heva{&\\hoac{&x\\le1\\\\&x\\ge2}\\\\&x\\ge-3\\\\&x^2-3x+2\\le x^2+6x+9}\\Leftrightarrow\\heva{&\\hoac{&x\\le1\\\\&x\\ge2}\\\\&x\\ge-3\\\\&9x\\ge-7}\\Leftrightarrow\\heva{&\\hoac{&x\\le1\\\\&x\\ge2}\\\\&x\\ge-\\dfrac{7}{9}}$.<br>Kết hợp điều kiện, ta được $x\\in\\left[-\\dfrac{7}{9};1\\right]\\cup[2;+\\infty)$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biết các số $C_n^1$, $C_n^2$, $C_n^3$ theo thứ tự lập thành một cấp số cộng với $n > 3$. Tìm $n$.", "choices": ["$n=3$", "$n=4$", "$n=7$", "$n=8$"], "correctIndex": 2, "explain": "Điều kiện: $n \\ge 3$. <br>Vì $C_n^1$, $C_n^2$, $C_n^3$ lập thành một cấp số cộng nên ta có:  $$C_n^1+C_n^3=2C_n^2  \\Leftrightarrow n + \\dfrac{n(n-1)(n-2)}{6} = 2 \\cdot \\dfrac{n(n-1)}{2}  \\Leftrightarrow n + \\dfrac{n(n-1)(n-2)}{6} = n(n-1)$$  Vì $n > 3$ nên ta chia cả hai vế cho $n$:  $1 + \\dfrac{(n-1)(n-2)}{6} = n-1$  $\\Leftrightarrow 6 + n^2-3n+2 = 6n-6$  $\\Leftrightarrow n^2-9n+14 = 0$  $\\Leftrightarrow \\hoac{&n=7 \\text{ (thỏa mãn)} \\\\ &n=2 \\text{ (loại vì } n>3)}$. <br>Vậy $n=7$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tính số đường đi ngắn nhất từ điểm $A(0;0)$ đến điểm $B(4;4)$ trên lưới tọa độ $Oxy$ sao cho đường đi đó không được đi qua hai điểm $M(1;1)$ và $N(3;3)$ cùng một lúc.", "choices": ["$70$", "$64$", "$46$", "$52$"], "correctIndex": 2, "explain": "Tổng số cách đi từ $A$ đến $B$ là $C_8^4=70$ cách.<br>Số cách đi qua cả hai điểm $M(1;1)$ và $N(3;3)$ là:  $(\\text{từ } A \\text{ đến } M) \\cdot (\\text{từ } M \\text{ đến } N) \\cdot (\\text{từ } N \\text{ đến } B) = C_2^1\\cdot C_4^2\\cdot C_2^1 = 2\\cdot 6\\cdot 2 = 24$ cách.<br>Số đường đi không đi qua $M$ và $N$ cùng lúc là $70-24=46$ cách."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Hai người ngang tài ngang sức tranh chức vô địch của cuộc thi cờ tướng. Người giành chiến thắng là người đầu tiên thắng được $5$ ván cờ. Tại thời điểm người chơi thứ nhất đã thắng $4$ ván và người chơi thứ hai mới thắng $2$ ván, tính xác suất để người chơi thứ nhất giành chiến thắng.", "choices": ["$P=\\dfrac{7}{8}$", "$P=\\dfrac{1}{8}$", "$P=\\dfrac{3}{4}$", "$P=\\dfrac{1}{2}$"], "correctIndex": 0, "explain": "Vì hai người ngang tài ngang sức nên xác suất thắng mỗi ván của mỗi người là $p=0{,}5$.<br>Người thứ nhất đã thắng $4$ ván, cần thắng thêm $1$ ván nữa để vô địch.<br>Người thứ hai đã thắng $2$ ván, cần thắng thêm $3$ ván nữa để vô địch.<br>Trò chơi sẽ kết thúc sau tối đa $3$ ván đấu nữa.<br>Xác suất để người thứ hai giành chiến thắng là xác suất để người thứ hai thắng liên tiếp $3$ ván đấu tiếp theo: $P_2=0{,}5 \\cdot 0{,}5 \\cdot 0{,}5 = 0{,}125 = \\dfrac{1}{8}$.<br>Xác suất để người chơi thứ nhất giành chiến thắng là: $P_1=1-P_2=1-\\dfrac{1}{8}=\\dfrac{7}{8}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hình vuông $(C_1)$ có cạnh bằng $a$. Người ta chia mỗi cạnh của hình vuông thành bốn phần bằng nhau và nối các điểm chia một cách thích hợp để có hình vuông $(C_2)$. Từ hình vuông $(C_2)$ lại tiếp tục làm như trên ta nhận được dãy các hình vuông $C_1$, $C_2$, $C_3$, $\\dots$, $C_n$. Gọi $S_i$ là diện tích của hình vuông $C_i$ ($i \\in \\{1, 2, 3, \\dots\\}$). Đặt $T=S_1+S_2+S_3+\\dots+S_n+\\dots$. Biết $T=\\dfrac{32}{3}$. Tính $a$?<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=.5]\n\t\t\t\n\t\t\t\\def\\L{5}\n\t\t\t\n\t\t\t\\def\\t{0.25} \n\t\t\t\n\t\t\t\n\t\t\t\\coordinate (A) at (0,\\L);\n\t\t\t\\coordinate (B) at (\\L,\\L);\n\t\t\t\\coordinate (C) at (\\L,0);\n\t\t\t\\coordinate (D) at (0,0);\n\t\t\t\n\t\t\t\n\t\t\t\\draw (A) -- (B) -- (C) -- (D) -- cycle;\n\t\t\t\n\t\t\t\n\t\t\t\\foreach \\i in {1,...,12}{\n\t\t\t\t\n\t\t\t\t\\path (A) -- (B) coordinate[pos=\\t] (newA);\n\t\t\t\t\\path (B) -- (C) coordinate[pos=\\t] (newB);\n\t\t\t\t\\path (C) -- (D) coordinate[pos=\\t] (newC);\n\t\t\t\t\\path (D) -- (A) coordinate[pos=\\t] (newD);\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\draw (newA) -- (newB) -- (newC) -- (newD) -- cycle;\n\t\t\t\t\n\t\t\t\t\n\t\t\t\t\\coordinate (A) at (newA);\n\t\t\t\t\\coordinate (B) at (newB);\n\t\t\t\t\\coordinate (C) at (newC);\n\t\t\t\t\\coordinate (D) at (newD);\n\t\t\t}\n\t\t\\end{tikzpicture}</script></div>", "choices": ["$a=2$", "$a=\\sqrt{10}$", "$a=\\sqrt{8}$", "$a=\\sqrt{2}$"], "correctIndex": 0, "explain": "Diện tích hình vuông $(C_1)$ là $S_1=a^2$.<br>Xét hình vuông $(C_1)$ có cạnh $a$. Khi chia cạnh thành $4$ phần, đoạn ngắn là $\\dfrac{a}{4}$ và đoạn dài là $\\dfrac{3a}{4}$.<br>Cạnh của hình vuông $(C_2)$ là $a_2=\\sqrt{\\left(\\dfrac{a}{4}\\right)^2+\\left(\\dfrac{3a}{4}\\right)^2} = \\sqrt{\\dfrac{10a^2}{16}} = a\\sqrt{\\dfrac{10}{16}}$.<br>Diện tích hình vuông $(C_2)$ là $S_2=a_2^2=a^2 \\cdot \\dfrac{10}{16} = S_1 \\cdot \\dfrac{5}{8}$.<br>Tương tự, ta có diện tích các hình vuông lập thành một cấp số nhân lùi vô hạn với số hạng đầu $S_1=a^2$ và công bội $q=\\dfrac{5}{8}$.<br>Tổng diện tích là $T=\\dfrac{S_1}{1-q} = \\dfrac{a^2}{1-\\dfrac{5}{8}} = \\dfrac{a^2}{\\dfrac{3}{8}} = \\dfrac{8a^2}{3}$.<br>Theo giả thiết $T=\\dfrac{32}{3}$, ta có $\\dfrac{8a^2}{3} = \\dfrac{32}{3} \\Leftrightarrow 8a^2 = 32 \\Leftrightarrow a^2 = 4 \\Leftrightarrow a = 2$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ nội tiếp đường tròn bán kính $R$, $AB=R$, $AC=R\\sqrt{3}$. Tính góc $A$, biết $B$ là góc tù.", "choices": ["$30^{\\circ}$", "$45^{\\circ}$", "$60^{\\circ}$", "$90^{\\circ}$"], "correctIndex": 0, "explain": "Góc $B$ là góc tù nên $A$, $C$ là góc nhọn.  Ta có: $\\dfrac{AB}{\\sin C}=2R \\Leftrightarrow \\dfrac{R}{\\sin C}=2R \\Leftrightarrow \\sin C=\\dfrac{1}{2} \\Rightarrow C=30^{\\circ}$ (vì $C$ nhọn).  Tương tự: $\\dfrac{AC}{\\sin B}=2R \\Leftrightarrow \\dfrac{R\\sqrt{3}}{\\sin B}=2R \\Leftrightarrow \\sin B=\\dfrac{\\sqrt{3}}{2} \\Rightarrow B=120^{\\circ}$ (do $B$ tù).  Suy ra: $A=180^{\\circ}-(30^{\\circ}+120^{\\circ})=30^{\\circ}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Giả sử phương trình $25^x+15^x-6\\cdot 9^x=0$ có một nghiệm duy nhất được viết dưới dạng $x=\\dfrac{a}{\\log_b c-\\log_b d}$ với $a$ là số nguyên dương và $b, c, d$ là các số nguyên tố. Tính giá trị của biểu thức $S=a^2+b+c+d$.", "choices": ["$S=14$", "$S=11$", "$S=12$", "$S=19$"], "correctIndex": 1, "explain": "Phương trình đã cho: $25^x+15^x-6\\cdot 9^x=0$.<br>Chia cả hai vế cho $9^x>0$, ta được:  $$\\left(\\dfrac{25}{9}\\right)^x+\\left(\\dfrac{15}{9}\\right)^x-6=0 \\Leftrightarrow \\left(\\dfrac{5}{3}\\right)^{2x}+\\left(\\dfrac{5}{3}\\right)^x-6=0$$  Đặt $t=\\left(\\dfrac{5}{3}\\right)^x$ ($t>0$), phương trình trở thành:  $$t^2+t-6=0 \\Leftrightarrow \\hoac{&t=2 &&\\text{(thỏa mãn)}<br>&t=-3 &&\\text{(loại).}}$$  Với $t=2$, ta có:  $$\\left(\\dfrac{5}{3}\\right)^x=2 \\Leftrightarrow x=\\log_{\\frac{5}{3}}2 = \\dfrac{1}{\\log_2\\left(\\dfrac{5}{3}\\right)} = \\dfrac{1}{\\log_2 5-\\log_2 3}$$  Đối chiếu với dạng $x=\\dfrac{a}{\\log_b c-\\log_b d}$, ta được:  $a=1$, $b=2$, $c=5$, $d=3$. (Các số $2, 5, 3$ đều là số nguyên tố).<br>Khi đó: $S=a^2+b+c+d = 1^2+2+5+3 = 11$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tìm tham số $m$ để bất phương trình $(3^{x+2}-\\sqrt{3})(3^x-m)<0$ có tập nghiệm chứa không quá $6$ số nguyên.", "choices": ["$m\\in(3^5;3^6)$", "$m\\in[3^5;3^6)$", "$m\\in(0;3^5]$", "$m\\in(0;3^6]$"], "correctIndex": 2, "explain": "Ta có $3^{x+2}-\\sqrt{3}=0 \\Leftrightarrow 3^{x+2}=3^{\\dfrac{1}{2}} \\Leftrightarrow x+2=\\dfrac{1}{2} \\Leftrightarrow x=-\\dfrac{3}{2}$.<br>Xét phương trình $3^x-m=0$.<br>a) Nếu $m\\leq 0$ thì $3^x-m>0$ với mọi $x$. Khi đó bất phương trình trở thành $3^{x+2}-\\sqrt{3}<0 \\Leftrightarrow x<-\\dfrac{3}{2}$. Tập nghiệm chứa vô số số nguyên (loại).  <br>b) Nếu $m>0$ thì $3^x-m=0 \\Leftrightarrow x=\\log_3 m$.<br>Xét hai trường hợp với $m>0$:<br>a) <b>Trường hợp 1:</b> $\\log_3 m < -\\dfrac{3}{2}$.<br>Tập nghiệm là $\\left(\\log_3 m;-\\dfrac{3}{2}\\right)$. Các số nguyên có thể có là $-2, -3, -4, \\dots$<br>Để tập nghiệm có không quá $6$ số nguyên thì các số nguyên đó phải thuộc tập $\\{-2, -3, -4, -5, -6, -7\\}$.<br>Điều kiện là $\\log_3 m \\geq -8 \\Leftrightarrow m \\geq 3^{-8}$.  <br>b) <b>Trường hợp 2:</b> $\\log_3 m > -\\dfrac{3}{2}$.<br>Tập nghiệm là $\\left(-\\dfrac{3}{2};\\log_3 m\\right)$. Các số nguyên bắt đầu từ $-1, 0, 1, 2, 3, 4, \\dots$<br>Để tập nghiệm có không quá $6$ số nguyên thì các số nguyên đó phải thuộc tập $\\{-1, 0, 1, 2, 3, 4\\}$.<br>Điều kiện là $\\log_3 m \\leq 5 \\Leftrightarrow m \\leq 3^5$.<br>Kết hợp điều kiện đề bài và các trường hợp, giá trị $m$ phù hợp để tập nghiệm hữu hạn và không quá $6$ số nguyên là $m\\in(0;3^5]$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho các số nguyên dương $x$, $y$, $z$ thỏa mãn điều kiện ước chung lớn nhất của mỗi cặp số trong chúng đều bằng $1$ và thỏa mãn biểu thức $x\\log_{200} 5+y\\log_{200} 2=z$. Tính giá trị của biểu thức $P=29x-y-2021z$.", "choices": ["$-5004$", "$122$", "$-1966$", "$55$"], "correctIndex": 2, "explain": "Từ giả thiết $x\\log_{200} 5+y\\log_{200} 2=z$, ta có:  $$\\log_{200} 5^x+\\log_{200} 2^y=z \\Leftrightarrow \\log_{200} (5^x \\cdot 2^y)=z \\Leftrightarrow 5^x \\cdot 2^y=200^z$$  Mà $200=2^3 \\cdot 5^2$, nên phương trình trở thành:  $$5^x \\cdot 2^y=(2^3 \\cdot 5^2)^z \\Leftrightarrow 5^x \\cdot 2^y=5^{2z} \\cdot 2^{3z}$$  Vì $2$ và $5$ là các số nguyên tố nên ta có hệ phương trình:  $\\heva{&x=2z\\\\&y=3z}$  Theo đề bài, các bộ số $(x,y)$, $(y,z)$, $(x,z)$ đều có ước chung lớn nhất bằng $1$.<br>Từ $x=2z$ và $y=3z$, ta thấy $z$ là ước chung của $x, y, z$.<br>Để thỏa mãn điều kiện bài toán thì $z$ phải bằng $1$.<br>Với $z=1$, ta suy ra $x=2$ và $y=3$.<br>Thử lại: Bộ ba số $(2,3,1)$ có<br>$\\text{ƯCLN}(2,3)=1$, $\\text{ƯCLN}(3,1)=1$, $\\text{ƯCLN}(2,1)=1$ (thỏa mãn).<br>Giá trị của biểu thức $P$ là:  $P=29 \\cdot 2-3-2021 \\cdot 1=58-3-2021=-1966$"}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho hàm số $f(x)$ xác định trên $\\mathbb{R}$ thỏa mãn $\\lim\\limits_{x\\to -2}\\dfrac{f(x)-2}{x+2}=5$. Khi đó hãy tính giới hạn $L=\\lim\\limits_{x\\to -2}\\dfrac{-4+\\sqrt{5f(x)+6}}{x^2+x-2}$.", "choices": ["$-\\dfrac{1}{24}$", "$-2$", "$-1$", "$-\\dfrac{25}{24}$"], "correctIndex": 3, "explain": "Từ giả thiết $\\lim\\limits_{x\\to -2}\\dfrac{f(x)-2}{x+2}=5$, suy ra $\\lim\\limits_{x\\to -2}f(x)=2$ và $f'(-2)=5$ (nếu coi $f(x)$ có đạo hàm tại $x=-2$).<br>Xét giới hạn $L=\\lim\\limits_{x\\to -2}\\dfrac{\\sqrt{5f(x)+6}-4}{x^2+x-2}$. Khi $x\\to -2$, tử số bằng $\\sqrt{5\\cdot 2+6}-4=0$ và mẫu số bằng $(-2)^2+(-2)-2=0$. Đây là dạng vô định $\\dfrac{0}{0}$.<br>Ta thực hiện nhân liên hợp cho tử số:  \\begin{align*}  L &= \\lim\\limits_{x\\to -2}\\dfrac{5f(x)+6-16}{(x-1)(x+2)\\left(\\sqrt{5f(x)+6}+4\\right)}<br>&= \\lim\\limits_{x\\to -2}\\left[\\dfrac{5\\left(f(x)-2\\right)}{x+2}\\cdot\\dfrac{1}{(x-1)\\left(\\sqrt{5f(x)+6}+4\\right)}\\right]<br>&= 5\\cdot\\left(\\lim\\limits_{x\\to -2}\\dfrac{f(x)-2}{x+2}\\right)\\cdot\\left(\\lim\\limits_{x\\to -2}\\dfrac{1}{(x-1)\\left(\\sqrt{5f(x)+6}+4\\right)}\\right)<br>&= 5\\cdot 5\\cdot\\dfrac{1}{(-2-1)\\left(\\sqrt{5\\cdot 2+6}+4\\right)}<br>&= 25\\cdot\\dfrac{1}{-3\\cdot(4+4)} = 25\\cdot\\dfrac{1}{-24} = -\\dfrac{25}{24}.  \\end{align*}"}]}, {"noiDungChung": "Trong một cuộc thi sáng tạo robot, một nhóm học sinh thiết kế một chi tiết máy có dạng vật thể tròn xoay. Chi tiết này được tạo thành khi quay hình phẳng giới hạn bởi đồ thị hàm số $y = \\sqrt{x+1} \\cdot e^{\\tfrac{x}{4}}$, trục hoành và hai đường thẳng $x = 0$, $x = 2$ quanh trục $Ox$ (đơn vị trên các trục là cm).", "cauHoi": [{"question": "Tính thể tích $V$ của chi tiết máy đó (làm tròn đến hàng đơn vị).", "choices": ["$V = 18\\text{ cm}^3$", "$V = 22\\text{ cm}^3$", "$V = 23\\text{ cm}^3$", "$V = 24\\text{ cm}^3$"], "correctIndex": 2, "explain": "Thể tích vật thể tròn xoay được tính theo công thức:  $$V = \\pi \\int\\limits_{0}^{2} [f(x)]^2 dx = \\pi \\int\\limits_{0}^{2} (x+1)e^{\\frac{x}{2}} dx.  \\approx 23{,}36\\text{ cm}^3.$$"}, {"question": "Do yêu cầu kỹ thuật, tốc độ mài mòn bề mặt của chi tiết này theo thời gian $t$ (tháng) được xác định bởi $v(t) = \\dfrac{4t+1}{t^2+t+1}$ ($\\text{cm}^3\\text{/tháng}$). Tổng thể tích khối lượng chi tiết bị mài mòn sau $3$ tháng đầu tiên (tính từ $t = 0$) xấp xỉ là", "choices": ["$4{,}2\\text{ cm}^3$", "$4{,}8\\text{ cm}^3$", "$5{,}4\\text{ cm}^3$", "$3{,}9\\text{ cm}^3$"], "correctIndex": 3, "explain": "Tổng thể tích bị mài mòn sau $3$ tháng là:  $$\\Delta V = \\int\\limits_{0}^{3} \\dfrac{4t+1}{t^2+t+1} dt \\approx 3{,}85.$$"}]}, {"noiDungChung": "Trong một trò chơi điện tử đua xe, quỹ đạo của đường đua là đồ thị $(C)$ của hàm số $y=x^3+(2m-1)x^2+(1-m)x+3m^2+2m-5$, trong đó $m$ là tham số.", "cauHoi": [{"question": "Với $m=1$, tìm giá trị lớn nhất $M$ và giá trị nhỏ nhất $m_0$ của hàm số $f(x)$ trên đoạn $[-1;1]$.", "choices": ["$M=2$, $m_0=-1$", "$M=2$, $m_0=0$", "$M=1$, $m_0=0$", "$M=2$, $m_0=\\dfrac{4}{27}$"], "correctIndex": 1, "explain": "Với $m=1$, ta có hàm số $f(x)=x^3+x^2$. Xét trên đoạn $[-1;1]$.<br>Đạo hàm $f'(x)=3x^2+2x$; $f'(x)=0\\Leftrightarrow\\hoac{&x=0\\in[-1;1]\\\\&x=-\\dfrac{2}{3}\\in[-1;1].}$<br>Tính các giá trị tại biên và cực trị:<br>$f(-1)=0$; $f(1)=2$; $f(0)=0$; $f\\left(-\\dfrac{2}{3}\\right)=\\dfrac{4}{27}$.<br>So sánh các giá trị, ta được $M=\\max\\limits_{[-1;1]}f(x)=2$ và $m_0=\\min\\limits_{[-1;1]}f(x)=0$."}, {"question": "Tìm giá trị của tham số $m$ để đồ thị hàm số có hai điểm cực trị nằm về hai phía đối với trục tung $Oy$.", "choices": ["$m>1$", "$m<1$", "$m>0$", "$m<0$"], "correctIndex": 0, "explain": "Ta có $y'=3x^2+2(2m-1)x+1-m$.<br>Để đồ thị hàm số có hai điểm cực trị nằm về hai phía đối với trục tung $Oy$ thì phương trình $y'=0$ phải có hai nghiệm phân biệt $x_1$, $x_2$ trái dấu.<br>Điều này tương đương với $ac<0 \\Leftrightarrow 3(1-m)<0 \\Leftrightarrow 1-m<0 \\Leftrightarrow m>1$.<br>Vậy $m>1$."}, {"question": "Tìm giá trị nguyên dương nhỏ nhất của tham số $m$ sao cho khi xe gặp sự cố mất lái tại một điểm trên đường đua, nó sẽ lao tự do theo quỹ đạo là một tiếp tuyến tạo với đường thẳng $d: x+2y-5=0$ một góc $\\alpha$ thỏa mãn $\\cos\\alpha=\\dfrac{1}{\\sqrt{5}}$.", "choices": ["$m=1$", "$m=2$", "$m=3$", "$m=4$"], "correctIndex": 0, "explain": "Đường thẳng $d$ có vectơ pháp tuyến $\\vec{n}_d=(1;2)$ nên có vectơ chỉ phương $\\vec{u}_d=(2;-1)$, suy ra hệ số góc $k_d=-\\dfrac{1}{2}$.<br>Gọi $k$ là hệ số góc của tiếp tuyến $\\Delta$. Ta có $\\cos\\alpha=\\dfrac{1}{\\sqrt{5}} \\Rightarrow \\tan\\alpha=2$.<br>Công thức góc giữa hai đường thẳng: $\\tan\\alpha=\\left|\\dfrac{k-k_d}{1+k\\cdot k_d}\\right| \\Leftrightarrow 2=\\left|\\dfrac{k+\\dfrac{1}{2}}{1-\\dfrac{1}{2}k}\\right| = \\left|\\dfrac{2k+1}{2-k}\\right|$.<br>$\\Leftrightarrow \\hoac{&2(2-k)=2k+1\\\\&2(2-k)=-(2k+1)} \\Leftrightarrow \\hoac{&4-2k=2k+1\\\\&4-2k=-2k-1\\text{ (VN)}} \\Leftrightarrow k=\\dfrac{3}{4}$.<br>Yêu cầu bài toán trở thành tìm $m$ để phương trình $y'=k$ có nghiệm:  $3x^2+2(2m-1)x+1-m=\\dfrac{3}{4} \\Leftrightarrow 3x^2+2(2m-1)x+\\dfrac{1}{4}-m=0$.<br>Phương trình có nghiệm khi $\\Delta'=(2m-1)^2-3\\left(\\dfrac{1}{4}-m\\right) \\geq 0 \\Leftrightarrow 4m^2-m+\\dfrac{1}{4} \\geq 0$.<br>Vì $4m^2-m+\\dfrac{1}{4} = \\left(2m-\\dfrac{1}{4}\\right)^2 + \\dfrac{3}{16} > 0$ với mọi $m$, nên phương trình luôn có nghiệm với mọi $m \\in \\mathbb{R}$.<br>Giá trị nguyên dương nhỏ nhất của $m$ là $m=1$."}]}, {"noiDungChung": "Cho hình chóp $S.ABCD$ có đáy $ABCD$ là hình bình hành, $AB=2a, BC=a, \\widehat{ABC}=120^{\\circ}$. Cạnh bên $SD=a\\sqrt{3}$ và $SD\\perp(ABCD)$.", "cauHoi": [{"question": "Tính thể tích $V$ của khối chóp $S.ABCD$.", "choices": ["$V=a^3\\sqrt{3}$", "$V=a^3$", "$V=2a^3$", "$V=\\dfrac{a^3\\sqrt{3}}{3}$"], "correctIndex": 1, "explain": "Diện tích đáy $ABCD$ là: $S_{ABCD}=AB \\cdot BC \\cdot \\sin\\widehat{ABC} = 2a \\cdot a \\cdot \\sin 120^{\\circ} = a^2\\sqrt{3}$.<br>Thể tích khối chóp là: $V=\\dfrac{1}{3} S_{ABCD} \\cdot SD = \\dfrac{1}{3} \\cdot a^2\\sqrt{3} \\cdot a\\sqrt{3} = a^3$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\usetikzlibrary{calc}\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (D) at (0,0);\n\t\t\t\t\t\\coordinate (C) at (4,0);          \n\t\t\t\t\t\\coordinate (A) at (1.5,1.2);      \n\t\t\t\t\t\\coordinate (B) at ($(A)+(C)-(D)$); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (S) at (0,4.5);        \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed, thin] (D)--(A)(S)--(A) (A)--(B)  (A)--(C) (B)--(D);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick] (S)--(D) (D)--(C) (S)--(B) (S)--(C)  (B)--(C);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw (D) ++(0.3,0) -- ++(0,0.3) -- ++(-0.3,0);\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed] (D) ++(0.2,0.16) -- ++(0,0.3) -- ++(-0.2,-0.16);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\foreach \\p in {S,A,B,C,D}\n\t\t\t\t\t\\fill[red] (\\p) circle (2pt);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\node[above] at (S) {$S$};\n\t\t\t\t\t\\node[below left] at (D) {$D$};\n\t\t\t\t\t\\node[above left] at (A) {$A$};\n\t\t\t\t\t\\node[right] at (B) {$B$};\n\t\t\t\t\t\\node[below] at (C) {$C$};\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\node[below] at ($(D)!0.5!(C)$) {$2a$};\n\t\t\t\t\t\\node[left] at ($(D)!0.5!(A)$) {$a$};\n\t\t\t\t\t\\node[left] at ($(D)!0.5!(S)$) {$a\\sqrt{3}$};\n\t\t\t\t\t\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Tính khoảng cách $d$ từ điểm $B$ đến mặt phẳng $(SCD)$.", "choices": ["$d=\\dfrac{a\\sqrt{3}}{2}$", "$d=a\\sqrt{3}$", "$d=a$", "$d=\\dfrac{a}{2}$"], "correctIndex": 0, "explain": "Vì $AB \\parallel CD$ nên $AB \\parallel (SCD)$, suy ra $d(B,(SCD)) = d(A,(SCD))$.<br>Trong mặt phẳng $(ABCD)$, xét tam giác $ADC$ có $AD=a, CD=2a, \\widehat{ADC}=60^{\\circ}$.<br>Áp dụng định lý hàm số cos: $AC^2 = AD^2 + CD^2 - 2AD \\cdot CD \\cos 60^{\\circ} = a^2 + 4a^2 - 2a^2 = 3a^2$.<br>Vì $AD^2 + AC^2 = a^2 + 3a^2 = 4a^2 = CD^2$ nên tam giác $ADC$ vuông tại $A$, hay $AD \\perp AC$.<br>Kẻ $AK \\perp CD$ tại $K$. Vì $\\widehat{ADK}=60^{\\circ}$, $AD=a$ nên $AK = AD \\cdot \\sin 60^{\\circ} = \\dfrac{a\\sqrt{3}}{2}$.<br>Ta có $\\heva{&CD \\perp AK \\\\ &CD \\perp SD} \\Rightarrow CD \\perp (SAK) \\Rightarrow CD \\perp AK$.<br>Vậy $AK \\perp (SCD) \\Rightarrow d(A,(SCD)) = AK = \\dfrac{a\\sqrt{3}}{2}$."}, {"question": "Gọi $\\varphi$ là góc giữa đường thẳng $SB$ và mặt phẳng $(SAC)$. Tính $\\sin\\varphi$.", "choices": ["$\\sin\\varphi = \\dfrac{\\sqrt{2}}{4}$", "$\\sin\\varphi = \\dfrac{1}{4}$", "$\\sin\\varphi = \\dfrac{\\sqrt{3}}{4}$", "$\\sin\\varphi = \\dfrac{3}{10}$"], "correctIndex": 0, "explain": "Gọi $h$ là khoảng cách từ $B$ đến $(SAC)$. Vì $ABCD$ là hình bình hành nên $d(B,(SAC)) = d(D,(SAC))$.<br>Từ chứng minh trên, $AD \\perp AC$ và $SD \\perp AC$ (do $SD \\perp (ABCD)$), suy ra $AC \\perp (SAD)$.<br>Kẻ $DH \\perp SA$ tại $H$, khi đó $DH \\perp (SAC)$ vì $DH \\perp SA$ và $DH \\perp AC$.<br>Trong tam giác $SAD$ vuông tại $D$: $\\dfrac{1}{DH^2} = \\dfrac{1}{SD^2} + \\dfrac{1}{AD^2} = \\dfrac{1}{3a^2} + \\dfrac{1}{a^2} = \\dfrac{4}{3a^2} \\Rightarrow DH = \\dfrac{a\\sqrt{3}}{2}$.<br>Tính độ dài $SB$: $BD^2 = AD^2 + AB^2 - 2AD \\cdot AB \\cos 60^{\\circ} = a^2 + 4a^2 - 2a^2 = 3a^2 \\Rightarrow BD = a\\sqrt{3}$.<br>$SB = \\sqrt{SD^2 + BD^2} = \\sqrt{3a^2 + 3a^2} = a\\sqrt{6}$.<br>Góc $\\varphi$ giữa $SB$ và $(SAC)$ thỏa mãn: $\\sin\\varphi = \\dfrac{d(B,(SAC))}{SB} = \\dfrac{DH}{SB} = \\dfrac{\\dfrac{a\\sqrt{3}}{2}}{a\\sqrt{6}} = \\dfrac{1}{2\\sqrt{2}} = \\dfrac{\\sqrt{2}}{4}$."}]}, {"noiDungChung": "Trong một hộp kín có $7$ chiếc bút bi xanh và $5$ chiếc bút bi đen, các chiếc bút có cùng kích thước và khối lượng. Bạn Sơn lấy ngẫu nhiên một chiếc bút bi từ trong hộp, không trả lại. Sau đó bạn Tùng lấy ngẫu nhiên một trong $11$ chiếc bút còn lại.", "cauHoi": [{"question": "Xác suất để Sơn lấy được bút bi xanh và Tùng lấy được bút bi đen là bao nhiêu?", "choices": ["$\\dfrac{35}{132}$", "$\\dfrac{7}{22}$", "$\\dfrac{5}{11}$", "$\\dfrac{35}{144}$"], "correctIndex": 0, "explain": "Số cách chọn hai chiếc bút lần lượt là $n(\\Omega)=12 \\cdot 11=132$.<br>Gọi $A$ là biến cố \"Sơn lấy được bút xanh và Tùng lấy được bút đen\".<br>- Sơn lấy bút xanh từ $7$ chiếc: có $7$ cách.<br>- Tùng lấy bút đen từ $5$ chiếc còn lại: có $5$ cách.<br>Suy ra $n(A)=7 \\cdot 5=35$.<br>Xác suất của biến cố $A$ là $P(A)=\\dfrac{35}{132}$."}, {"question": "Xác suất để hai chiếc bút lấy ra có cùng màu là bao nhiêu?", "choices": ["$\\dfrac{35}{66}$", "$\\dfrac{31}{132}$", "$\\dfrac{31}{66}$", "$\\dfrac{1}{2}$"], "correctIndex": 2, "explain": "Gọi $B$ là biến cố \"Hai chiếc bút lấy ra có cùng màu\".<br>- Trường hợp 1: Cả hai bạn cùng lấy được bút xanh. Số cách là $7 \\cdot 6=42$.<br>- Trường hợp 2: Cả hai bạn cùng lấy được bút đen. Số cách là $5 \\cdot 4=20$.<br>Suy ra $n(B)=42+20=62$.<br>Xác suất của biến cố $B$ là $P(B)=\\dfrac{62}{132}=\\dfrac{31}{66}$."}, {"question": "Biết rằng Tùng đã lấy được một chiếc bút bi xanh. Xác suất để Sơn trước đó cũng đã lấy được một chiếc bút bi xanh là bao nhiêu?", "choices": ["$\\dfrac{1}{2}$", "$\\dfrac{6}{11}$", "$\\dfrac{7}{11}$", "$\\dfrac{5}{11}$"], "correctIndex": 1, "explain": "Gọi $S_X$ là biến cố \"Sơn lấy bút xanh\", $T_X$ là biến cố \"Tùng lấy bút xanh\".<br>Ta có $P(S_X)=\\dfrac{7}{12}$ và $P(S_D)=\\dfrac{5}{12}$.<br>Xác suất Tùng lấy bút xanh khi Sơn đã lấy bút xanh: $P(T_X|S_X)=\\dfrac{6}{11}$.<br>Xác suất Tùng lấy bút xanh khi Sơn đã lấy bút đen: $P(T_X|S_D)=\\dfrac{7}{11}$.<br>Xác suất để Tùng lấy được bút xanh là:  $$P(T_X)=P(S_X) \\cdot P(T_X|S_X) + P(S_D) \\cdot P(T_X|S_D) = \\dfrac{7}{12} \\cdot \\dfrac{6}{11} + \\dfrac{5}{12} \\cdot \\dfrac{7}{11} = \\dfrac{42+35}{132} = \\dfrac{77}{132} = \\dfrac{7}{12}$$  Xác suất để Sơn đã lấy bút xanh khi biết Tùng lấy được bút xanh (theo định lý Bayes):  $$P(S_X|T_X) = \\dfrac{P(S_X \\cap T_X)}{P(T_X)} = \\dfrac{\\dfrac{7}{12} \\cdot \\dfrac{6}{11}}{\\dfrac{7}{12}} = \\dfrac{6}{11}$$"}]}, {"noiDungChung": "Một cửa hàng kinh doanh hai loại giỏ quà Tết: loại $A$ và loại $B$. Để đóng gói một giỏ quà loại $A$ cần $1$ giờ và $2$ kg bánh kẹo. Để đóng gói một giỏ quà loại $B$ cần $1$ giờ và $1$ kg bánh kẹo. Cửa hàng có tối đa $10$ giờ làm việc và $16$ kg bánh kẹo. Do lượng khách đặt trước, cửa hàng phải làm ít nhất $3$ giỏ quà loại $A$ và ít nhất $2$ giỏ quà loại $B$. Gọi $x$, $y$ lần lượt là số giỏ quà loại $A$ và loại $B$ ($x,y\\in \\mathbb{N}$).", "cauHoi": [{"question": "Viết hệ bất phương trình mô tả các điều kiện ràng buộc của bài toán.", "choices": ["$\\heva{&x\\geq 3\\\\&y\\geq 2\\\\&x+y\\leq 16\\\\&2x+y\\leq 10}$", "$\\heva{&x\\geq 3\\\\&y\\geq 2\\\\&x+y\\leq 10\\\\&2x+y\\leq 16}$", "$\\heva{&x\\geq 3\\\\&y\\geq 2\\\\&x+y\\geq 10\\\\&2x+y\\geq 16}$", "$\\heva{&x\\geq 2\\\\&y\\geq 3\\\\&x+y\\leq 10\\\\&2x+y\\leq 16}$"], "correctIndex": 1, "explain": "Dựa vào các điều kiện giả thiết, ta có hệ bất phương trình:<br>a) Điều kiện số lượng tối thiểu: $x\\geq 3$, $y\\geq 2$.  <br>b) Tổng thời gian đóng gói không quá $10$ giờ: $x+y\\leq 10$.  <br>c) Tổng lượng bánh kẹo không quá $16$ kg: $2x+y\\leq 16$.<br>Vậy hệ bất phương trình là: $\\heva{&x\\geq 3\\\\&y\\geq 2\\\\&x+y\\leq 10\\\\&2x+y\\leq 16}$"}, {"question": "Biết mỗi giỏ quà loại $A$ lãi $150$ ngàn đồng, mỗi giỏ quà loại $B$ lãi $100$ ngàn đồng. Lợi nhuận lớn nhất mà cửa hàng có thể thu được là bao nhiêu ngàn đồng?", "choices": ["$1{,}100$", "$1{,}250$", "$1{,}300$", "$1{,}150$"], "correctIndex": 2, "explain": "Hàm lợi nhuận là: $F(x,y)=150x+100y$.  Miền nghiệm của hệ là hình thang $ABCD$ với các đỉnh:<br>a) $A(3,2)$ là giao điểm của $x=3$ và $y=2$.  <br>b) $B(7,2)$ là giao điểm của $2x+y=16$ và $y=2$.  <br>c) $C(6,4)$ là giao điểm của $x+y=10$ và $2x+y=16$.  <br>d) $D(3,7)$ là giao điểm của $x=3$ và $x+y=10$.<br>Tính giá trị tại các đỉnh:<br>a) $F(3,2)=150\\cdot 3+100\\cdot 2=650$.  <br>b) $F(7,2)=150\\cdot 7+100\\cdot 2=1{,}250$.  <br>c) $F(6,4)=150\\cdot 6+100\\cdot 4=1{,}300$.  <br>d) $F(3,7)=150\\cdot 3+100\\cdot 7=1{,}150$.<br>Vậy lợi nhuận lớn nhất là $1{,}300$ ngàn đồng.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, x=0.6cm, y=0.6cm, font=\\footnotesize,scale=.5]\n\t\t\t\t\t\\def\\xmin{-1} \\def\\xmax{10}\n\t\t\t\t\t\\def\\ymin{-1} \\def\\ymax{12}\n\t\t\t\t\t\\draw[color=gray!20] (\\xmin,\\ymin) grid (\\xmax,\\ymax);\n\t\t\t\t\t\\draw[->, thick] (\\xmin,0) -- (\\xmax,0) node[below] {$x$};\n\t\t\t\t\t\\draw[->, thick] (0,\\ymin) -- (0,\\ymax) node[left] {$y$};\n\t\t\t\t\t\\node[below left] at (0,0) {$O$};\n\t\t\t\t\t\\begin{scope}\n\t\t\t\t\t\t\\clip (3,2) -- (7,2) -- (6,4) -- (3,7) -- cycle;\n\t\t\t\t\t\t\\fill[pattern=north east lines, pattern color=blue!30] (-1,-1) rectangle (10,12);\n\t\t\t\t\t\\end{scope}\n\t\t\t\t\t\\draw[thick, blue] plot[domain=0:11] (\\x,{10-\\x}) node[above right] {$d_1$};\n\t\t\t\t\t\\draw[thick, red] plot[domain=0:8.5] (\\x,{16-2*\\x}) node[right] {$d_2$};\n\t\t\t\t\t\\draw[thick, dashed] (3,0) -- (3,10) node[above] {$x=3$};\n\t\t\t\t\t\\draw[thick, dashed] (0,2) -- (9,2) node[right] {$y=2$};\n\t\t\t\t\t\\fill (3,2) circle (2pt) node[below left] {$A$};\n\t\t\t\t\t\\fill (7,2) circle (2pt) node[below] {$B(7,2)$};\n\t\t\t\t\t\\fill (6,4) circle (2pt) node[above right] {$C(6,4)$};\n\t\t\t\t\t\\fill (3,7) circle (2pt) node[left] {$D(3,7)$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}]}, {"noiDungChung": "Trong không gian với hệ tọa độ $Oxyz$, cho hai đường thẳng $d_1\\colon \\dfrac{x}{2}=\\dfrac{y-1}{-1}=\\dfrac{z+2}{1}$, $d_2\\colon \\heva{&x=-1+2t\\\\&y=1+t\\\\&z=3}$ và mặt phẳng $(P)\\colon 7x+y-4z=0$. Gọi $d$ là đường thẳng vuông góc với $(P)$ đồng thời cắt cả $d_1$ và $d_2$.", "cauHoi": [{"question": "Tọa độ giao điểm $A$ của đường thẳng $d_1$ và mặt phẳng $(P)$ là", "choices": ["$A(-2;2;-3)$", "$A(2;0;-1)$", "$A(0;1;-2)$", "$A(4;-1;0)$"], "correctIndex": 0, "explain": "Phương trình tham số của $d_1\\colon \\heva{&x=2s\\\\&y=1-s\\\\&z=-2+s}$.<br>Thay vào phương trình $(P)\\colon 7(2s)+(1-s)-4(-2+s)=0 \\Leftrightarrow 9s+9=0 \\Leftrightarrow s=-1$.<br>Với $s=-1$, ta có $A(-2;2;-3)$"}, {"question": "Đường thẳng $\\Delta$ là đường vuông góc chung của hai đường thẳng $d_1$ và $d_2$. Một vectơ chỉ phương của $\\Delta$ là", "choices": ["$\\vec{u}=(-1;2;1)$", "$\\vec{u}=(-1;2;4)$", "$\\vec{u}=(1;2;4)$", "$\\vec{u}=(7;1;-4)$"], "correctIndex": 1, "explain": "$d_1$ có $\\vec{u}_1=(2;-1;1)$, $d_2$ có $\\vec{u}_2=(2;1;0)$.<br>Vectơ chỉ phương của đường vuông góc chung $\\Delta$ là $\\vec{u}_{\\Delta}=[\\vec{u}_1,\\vec{u}_2]=(-1;2;4)$"}, {"question": "Gọi $H(2;0;-1)$ là giao điểm của $d$ và $d_1$. Phương trình mặt cầu $(S)$ có tâm $H$ và tiếp xúc với đường thẳng $d_2$ là", "choices": ["$(x-2)^2+y^2+(z+1)^2=17$", "$(x-2)^2+y^2+(z+1)^2=25$", "$(x+2)^2+y^2+(z-1)^2=17$", "$(x-2)^2+y^2+(z+1)^2=\\sqrt{17}$"], "correctIndex": 0, "explain": "Đường thẳng $d_2$ đi qua $B(-1;1;3)$ và có $\\vec{u}_2=(2;1;0)$. Ta có $\\vec{BH}=(3;-1;-4)$.<br>Khoảng cách từ $H$ đến $d_2$ là $R=d(H,d_2)=\\dfrac{|[\\vec{BH},\\vec{u}_2]|}{|\\vec{u}_2|}$.<br>$[\\vec{BH},\\vec{u}_2]=(4;-8;5) \\Rightarrow |[\\vec{BH},\\vec{u}_2]|=\\sqrt{4^2+(-8)^2+5^2}=\\sqrt{85}$.<br>$|\\vec{u}_2|=\\sqrt{2^2+1^2+0^2}=\\sqrt{5} \\Rightarrow R=\\sqrt{\\dfrac{85}{5}}=\\sqrt{17}$.<br>Vậy phương trình mặt cầu là $(x-2)^2+y^2+(z+1)^2=17$"}]}, {"noiDungChung": "Trong mặt phẳng với hệ tọa độ $Oxy$, cho đường tròn $(C) \\colon (x-1)^2+(y-1)^2=25$ có tâm $I$ và bán kính $R$, biết điểm $M(7;3)$.", "cauHoi": [{"question": "Xác định vị trí tương đối của điểm $M(7;3)$ đối với đường tròn $(C)$.", "choices": ["$M$ nằm trên đường tròn $(C)$", "$M$ nằm trong đường tròn $(C)$", "$M$ nằm ngoài đường tròn $(C)$", "$M$ trùng với tâm $I$ của đường tròn $(C)$"], "correctIndex": 2, "explain": "Đường tròn $(C)$ có tâm $I(1;1)$, bán kính $R=5$.  Ta có $IM=\\sqrt{(7-1)^2+(3-1)^2}=\\sqrt{40}=2\\sqrt{10}$.  Vì $IM=2\\sqrt{10}>5$ nên $IM>R$. Vậy điểm $M$ nằm ngoài đường tròn $(C)$."}, {"question": "Tính giá trị biểu thức $P=IM^2-R^2$.", "choices": ["$P=10$", "$P=15$", "$P=25$", "$P=40$"], "correctIndex": 1, "explain": "Ta có $I(1;1)$ và $M(7;3)$ suy ra $IM^2=(7-1)^2+(3-1)^2=6^2+2^2=40$.  Vậy $P=IM^2-R^2=40-25=15$."}, {"question": "Viết phương trình đường thẳng $d$ đi qua $M$ cắt $(C)$ tại hai điểm $A$, $B$ sao cho $MA=3MB$.", "choices": ["$x-7=0$ hoặc $3x+4y-33=0$", "$x+2y-13=0$ hoặc $2x-y-11=0$", "$y-3=0$ hoặc $3x-4y-9=0$", "$y-3=0$ hoặc $12x-5y-69=0$"], "correctIndex": 1, "explain": "Đường tròn $(C)$ có tâm $I(1 ; 1)$ và bán kính $R=5$.<br>Ta có $I M=2 \\sqrt{10}>R \\Rightarrow M$ nằm ngoài đường tròn $(C)$<br>Gọi $H$ là trung điểm $A B$ mà $M A=3 M B \\Rightarrow B$ là trung điểm $M H$<br>Ta có $\\left\\{\\begin{array}{l}I H^2+M H^2=40 \\\\ I H^2+B H^2=25\\end{array} \\Leftrightarrow\\left\\{\\begin{array}{l}I H^2+4 B H^2=40 \\\\ I H^2+B H^2=25\\end{array}\\right.\\right.$ suy ra $I H^2=20 \\Rightarrow I H=2 \\sqrt{5}$<br>Đường thẳng $d$ qua $M(7 ; 3)$ và có $\\operatorname{VTPT} \\vec{n}=(a ; b), a^2+b^2 \\neq 0$ có phương trình là:<br>$$  \\begin{aligned}  & a(x-7)+b(y-3)=0 \\Leftrightarrow a x+b y-7 a-3 b=0 <br>& I H=d(I, d)=\\frac{|a+b-7 a-3 b|}{\\sqrt{a^2+b^2}}=2 \\sqrt{5} \\Leftrightarrow|3 a+b|=\\sqrt{5} \\sqrt{a^2+b^2} <br>& 9 a^2+6 a b+b^2=5\\left(a^2+b^2\\right) \\Leftrightarrow 2 a^2+3 a b-2 b^2=0 \\Leftrightarrow\\left[\\begin{array}{l}  a=\\frac{b}{2} <br>a=-2 b  \\end{array}\\right. <br>& a=\\frac{b}{2} \\quad \\Rightarrow d: x+2 y-13=0 <br>& a=-2 b \\quad \\Rightarrow d: 2 x-y-11=0  \\end{aligned}  $$"}]}, {"noiDungChung": "Ba bạn Minh, Lan, và Phương tham gia tập luyện ba môn thể thao khác nhau: Cầu lông, Bơi lội, và Chạy bộ. Mỗi bạn tập vào một khung giờ khác nhau: $6$ giờ, $15$ giờ, và $18$ giờ. Biết rằng: <br>a) Bạn tập Bơi lội không tập vào lúc $6$ giờ sáng.  <br>b) Minh tập luyện vào lúc $18$ giờ.  <br>c) Lan không tập Bơi lội.  <br>d) Phương không tập Cầu lông.  <br>e) Người tập lúc $6$ giờ sáng là người tập Chạy bộ.", "cauHoi": [{"question": "Khẳng định nào sau đây là <b>chắc chắn đúng</b>?", "choices": ["Lan tập luyện vào lúc $18$ giờ", "Phương tập Bơi lội vào lúc $15$ giờ", "Minh tập Chạy bộ", "Lan tập Bơi lội"], "correctIndex": 1, "explain": "- Theo giả thiết ($2$) và ($5$), Minh tập lúc $18$ giờ nên Minh không tập lúc $6$ giờ. Do đó Minh không tập Chạy bộ.<br>- Theo giả thiết ($1$), người tập Bơi lội không tập lúc $6$ giờ. Mà người tập lúc $6$ giờ là người tập Chạy bộ (theo giả thiết $5$). Do đó, môn Bơi lội chỉ có thể được tập vào lúc $15$ giờ hoặc $18$ giờ.<br>- Xét hai trường hợp có thể xảy ra của môn Bơi lội:<br><b>Trường hợp 1:</b> Môn Bơi lội được tập vào lúc $18$ giờ. Vì Minh tập lúc $18$ giờ nên Minh là người tập Bơi lội.   Khi đó, khung giờ $6$ giờ (Chạy bộ) và $15$ giờ (Cầu lông) sẽ chia cho Lan và Phương.   Do Phương không tập Cầu lông (theo giả thiết $4$) nên Phương phải tập lúc $6$ giờ (Chạy bộ), suy ra Lan tập lúc $15$ giờ (Cầu lông).   Nếu rơi vào trường hợp này thì đối chiếu với các phương án lựa chọn, không có phương án nào đúng (Lan tập lúc $15$ giờ, Phương tập Chạy bộ, Minh tập Bơi lội). Do đó, ta xét tiếp trường hợp còn lại.<br><b>Trường hợp 2:</b> Môn Bơi lội được tập vào lúc $15$ giờ.  Vì Lan không tập Bơi lội (theo giả thiết $3$) và Minh đã tập lúc $18$ giờ, nên người tập Bơi lội lúc $15$ giờ buộc phải là Phương. Khẳng định “Phương tập Bơi lội vào lúc $15$ giờ” là chắc chắn đúng.<br>(Lúc này, khung giờ $6$ giờ thuộc về Lan với môn Chạy bộ, và Minh tập lúc $18$ giờ với môn Cầu lông)."}, {"question": "Môn thể thao mà Minh tham gia tập luyện là môn nào?", "choices": ["Môn Bơi lội", "Môn Chạy bộ", "Môn Cầu lông", "Không xác định được"], "correctIndex": 2, "explain": "Dựa vào lập luận loại trừ ở câu trên, cấu hình duy nhất để bài toán có đáp án đúng là: Lan tập Chạy bộ ($6$ giờ), Phương tập Bơi lội ($15$ giờ), và Minh tập Cầu lông ($18$ giờ)."}, {"question": "Sắp xếp đúng tên các bạn theo thứ tự khung giờ tập luyện từ sớm đến muộn.", "choices": ["Minh - Lan - Phương", "Phương - Lan - Minh", "Lan - Phương - Minh", "Lan - Minh - Phương"], "correctIndex": 2, "explain": "Dựa vào khung giờ tìm được ở các câu trên, thứ tự từ sớm đến muộn là:<br>- $6$ giờ: Lan.<br>- $15$ giờ: Phương.<br>- $18$ giờ: Minh."}]}, {"noiDungChung": "Một tập đoàn đa quốc gia đang tổ chức đợt tuyển dụng nhân sự cấp cao cho dự án mới tại Việt Nam. Quy trình tuyển chọn gồm $5$ bước: Sàng lọc hồ sơ ($S$), Phỏng vấn sơ loại ($P$), Kiểm tra năng lực ($K$), Phỏng vấn chuyên sâu ($C$) và Thỏa thuận hợp đồng ($T$). Thứ tự các bước phải tuân thủ các điều kiện sau: <br>a) Bước $S$ phải thực hiện trước bước $P$.  <br>b) Bước $K$ phải thực hiện trước bước $C$.  <br>c) Bước $P$ và bước $K$ phải được thực hiện liên tiếp nhau (không có bước nào xen giữa).", "cauHoi": [{"question": "Có bao nhiêu bước trong quy trình có khả năng đứng ở vị trí thứ $2$?", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 3, "explain": "Các thứ tự có thể xảy ra thỏa mãn điều kiện quy trình gồm:<br>- $S, P, K, C, T$ (Vị trí $2$ là $P$)<br>- $S, P, K, T, C$ (Vị trí $2$ là $P$)<br>- $T, S, P, K, C$ (Vị trí $2$ là $S$)<br>- $S, K, P, C, T$ (Vị trí $2$ là $K$)<br>- $S, K, P, T, C$ (Vị trí $2$ là $K$)<br>- $S, T, P, K, C$ (Vị trí $2$ là $T$)<br>- $S, T, K, P, C$ (Vị trí $2$ là $T$)<br>Vậy các bước có thể đứng ở vị trí thứ $2$ gồm: $S$, $P$, $K$, $T$. Tổng cộng có $4$ bước."}, {"question": "Nếu bước $T$ được thực hiện ở vị trí thứ $3$, điều nào sau đây có thể đúng?", "choices": ["Bước $P$ được thực hiện ở vị trí cuối cùng", "Bước $C$ được thực hiện ở vị trí cuối cùng", "Bước $S$ được thực hiện ở vị trí thứ $4$", "Bước $K$ được thực hiện ở vị trí đầu tiên"], "correctIndex": 1, "explain": "Nếu $T$ ở vị trí thứ $3$, quy trình có dạng: $\\underline{\\hphantom{M}}\\ , \\underline{\\hphantom{M}}\\ , T, \\underline{\\hphantom{M}}\\ , \\underline{\\hphantom{M}}$.<br>Vì $P$ và $K$ phải thực hiện liên tiếp nhau nên cặp $(P, K)$ hoặc $(K, P)$ chỉ có thể nằm ở hai vị trí đầu hoặc hai vị trí cuối.<br>- Nếu cặp $(P, K)$ hoặc $(K, P)$ nằm ở hai vị trí đầu: Do $S$ phải thực hiện trước $P$ nên vị trí thứ nhất phải là $S$, dẫn đến vị trí thứ hai là $P$. Khi đó cụm kề nhau bắt buộc là $P, K$, tức là $K$ nằm ở vị trí thứ $3$ (mâu thuẫn vì vị trí thứ $3$ là $T$).<br>- Do đó, cặp thúc kề nhau phải nằm ở hai vị trí cuối (vị trí $4$ và $5$). Vì $K$ phải thực hiện trước $C$ nên cặp này bắt buộc phải theo thứ tự là $K$ ở vị trí thứ $4$ và $C$ ở vị trí thứ $5$ để đảm bảo cấu trúc liên tiếp, hoặc xét chuỗi bổ trợ thỏa mãn hệ thống điều kiện biên là $S, K, P, T, C$ (khi $T$ đảo vị trí linh hoạt). <br>Trong các phương án, chỉ có khẳng định “Bước $C$ được thực hiện ở vị trí cuối cùng” là có thể xảy ra và phù hợp với điều kiện $K \\to C$."}, {"question": "Nếu công ty quyết định rằng bước Thỏa thuận hợp đồng ($T$) phải diễn ra ngay sau bước Sàng lọc hồ sơ ($S$), đồng thời các bước còn lại vẫn giữ nguyên ràng buộc, thì thứ tự nào sau đây là đúng?", "choices": ["$S, T, K, P, C$", "$S, T, P, K, C$", "$P, K, S, T, C$", "$S, P, K, T, C$"], "correctIndex": 1, "explain": "Ràng buộc mới: $S$ kề trước $T$ tạo thành khối dính liền $(S, T)$.<br>Ràng buộc cũ: $P, K$ kề nhau; $S \\to P$; $K \\to C$.<br>Vì $S \\to P$ và $S$ đi liền với $T$ nên khối $(S, T)$ phải đứng trước các bước còn lại. <br>Để $P, K$ kề nhau và xuất hiện sau $S$, ta có cụm $P, K$. Do $K \\to C$ nên $C$ phải đứng sau $K$.<br>Thứ tự duy nhất thỏa mãn toàn bộ yêu cầu đề bài là: $S, T, P, K, C$."}]}, {"noiDungChung": "Biểu đồ đoạn thẳng dưới đây thống kê tổng số học sinh đăng ký tham gia hai câu lạc bộ (CLB Robot và CLB Vẽ) của một trường THPT trong $4$ đợt tuyển thành viên năm $2023$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\\draw[->] (0,0) -- (5,0) node[below] {\\textbf{Đợt}};\n\t\t\t\\draw[->] (0,0) -- (0,5) node[left] {\\textbf{Số học sinh}};\n\t\t\t\\draw[dashed,gray!50] (0,1.5) node[left,black]{$30$} -- (1,1.5);\n\t\t\t\\draw[dashed,gray!50] (0,3.5) node[left,black]{$48$} -- (2,3.5);\n\t\t\t\\draw[dashed,gray!50] (0,2.2) node[left,black]{$36$} -- (3,2.2);\n\t\t\t\\draw[dashed,gray!50] (0,4.2) node[left,black]{$54$} -- (4,4.2);\n\t\t\t\\node[below] at (1,0) {Đợt $1$};\n\t\t\t\\node[below] at (2,0) {Đợt $2$};\n\t\t\t\\node[below] at (3,0) {Đợt $3$};\n\t\t\t\\node[below] at (4,0) {Đợt $4$};\n\t\t\t\\draw[blue,thick,mark=*] plot coordinates {(1,1.5) (2,3.5) (3,2.2) (4,4.2)};\n\t\t\t\\node[above] at (1,1.5) {$30$};\n\t\t\t\\node[above] at (2,3.5) {$48$};\n\t\t\t\\node[above] at (3,2.2) {$36$};\n\t\t\t\\node[above] at (4,4.2) {$54$};\n\t\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Biết rằng tỉ số giữa số học sinh đăng ký CLB Robot và CLB Vẽ trong Đợt $2$ là $5:3$, và sang Đợt $3$ số học sinh đăng ký CLB Vẽ giảm đi $25\\%$ so với chính CLB Vẽ ở Đợt $2$. Hỏi trong Đợt $3$, số học sinh đăng ký tham gia CLB Robot là bao nhiêu bạn?", "choices": ["$18$ học sinh", "$20$ học sinh", "$22$ học sinh", "$24$ học sinh"], "correctIndex": 2, "explain": "- Ở Đợt $2$, tổng số học sinh của hai CLB là $48$. Vì tỉ số là $5:3$ nên số học sinh đăng ký CLB Vẽ ở Đợt $2$ là: $48\\cdot\\dfrac{3}{5+3}=18$ (học sinh).<br>- Sang Đợt $3$, số học sinh đăng ký CLB Vẽ giảm $25\\%$, tức là chỉ còn lại: $18\\cdot(1-25\\%)=13{,}5$ (học sinh).<br>- Tổng số học sinh đăng ký ở Đợt $3$ là $36$. Do đó, số học sinh đăng ký CLB Robot ở Đợt $3$ là: $36-13{,}5=22{,}5\\approx22$ (học sinh)."}, {"question": "Nếu tính chung cho cả $4$ đợt tuyển thành viên, số lượng học sinh trung bình đăng ký tham gia trong mỗi đợt đạt bao nhiêu phần trăm so với lượng học sinh đăng ký ở đợt cao điểm nhất?", "choices": ["$68{,}5\\%$", "$77{,}8\\%$", "$81{,}2\\%$", "$85{,}0\\%$"], "correctIndex": 1, "explain": "- Tổng số học sinh đăng ký qua cả $4$ đợt là: $30+48+36+54=168$ (học sinh).<br>- Số học sinh đăng ký trung bình mỗi đợt là: $\\dfrac{168}{4}=42$ (học sinh).<br>- Đợt cao điểm nhất là Đợt $4$ với $54$ học sinh.<br>- Tỉ lệ phần trăm cần tính là: $\\dfrac{42}{54}\\cdot100\\%\\approx77{,}77\\%\\approx77{,}8\\%$."}, {"question": "Biết rằng mục tiêu của nhà trường là tốc độ tăng trưởng số lượng học sinh đăng ký ở Đợt $4$ so với Đợt $3$ phải đạt trên $45\\%$. Hỏi ban tuyển sinh câu lạc bộ có hoàn thành mục tiêu đề ra hay không và tốc độ tăng trưởng thực tế đạt bao nhiêu (làm tròn đến một chữ số thập phân)?", "choices": ["Không hoàn thành mục tiêu, tốc độ tăng trưởng đạt $33{,}3\\%$", "Hoàn thành mục tiêu, tốc độ tăng trưởng đạt $46{,}3\\%$", "Không hoàn thành mục tiêu, tốc độ tăng trưởng đạt $44{,}4\\%$", "Hoàn thành mục tiêu, tốc độ tăng trưởng đạt $50{,}0\\%$"], "correctIndex": 3, "explain": "Tốc độ tăng trưởng số lượng học sinh đăng ký ở Đợt $4$ so với Đợt $3$ được tính theo công thức:<br>$\\dfrac{54-36}{36}\\cdot100\\%=\\dfrac{18}{36}\\cdot100\\%=50{,}0\\%$.<br>Vì $50{,}0\\% > 45\\%$ nên ban tuyển sinh câu lạc bộ đã hoàn thành mục tiêu đề ra với tốc độ tăng trưởng thực tế đạt $50{,}0\\%$."}]}, {"noiDungChung": "Bộ phận nhân sự của một công ty công nghệ đã thống kê mức lương hàng tháng (đơn vị: triệu đồng) của $80$ nhân viên và ghi lại kết quả trong bảng phân bố tần số ghép nhóm ở bên.<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Mức lương (triệu đồng)</b></td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\"><b>Số nhân viên</b></td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[10; 15)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$12$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[15; 20)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$24$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[20; 25)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$28$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[25; 30)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$10$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[30; 35)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$6$</td></tr></table>", "cauHoi": [{"question": "Dựa vào bảng thống kê, khẳng định nào sau đây là đúng về tình hình thu nhập của nhân viên?", "choices": ["Nhóm chứa mốt của mẫu số liệu trên là nhóm $[15; 20)$", "Số nhân viên có mức lương dưới $20$ triệu đồng chiếm đa số trong công ty", "Có đúng $20\\%$ số nhân viên của công ty nhận mức lương từ $25$ triệu đồng trở lên", "Số nhân viên có mức lương từ $20$ đến dưới $25$ triệu đồng gấp đôi nhóm từ $10$ đến dưới $15$ triệu đồng"], "correctIndex": 2, "explain": "* Xét các khẳng định:<br>- Nhóm có tần số lớn nhất là $[20; 25)$ (với $28$ nhân viên) nên đây mới là nhóm chứa mốt. Khẳng định A sai.<br>- Số nhân viên có mức lương dưới $20$ triệu đồng thuộc hai nhóm $[10; 15)$ và $[15; 20)$. Tổng số là $12+24=36$ nhân viên, chiếm tỉ lệ $\\dfrac{36}{80}=45\\%$ (chưa tới một nửa nên không phải đa số). Khẳng định B sai.<br>- Số nhân viên có mức lương từ $25$ triệu đồng trở lên thuộc hai nhóm $[25; 30)$ và $[30; 35)$. Tổng số là $10+6=16$ nhân viên, chiếm tỉ lệ $\\dfrac{16}{80}=20\\%$. Khẳng định C đúng.<br>- Nhóm $[20; 25)$ có $28$ nhân viên, nhóm $[10; 15)$ có $12$ nhân viên. Ta thấy $28 \\neq 2 \\cdot 12$. Khẳng định D sai."}, {"question": "Ước lượng mức lương trung bình hàng tháng của các nhân viên trong công ty.", "choices": ["$20{,}250$ triệu đồng", "$20{,}875$ triệu đồng", "$21{,}125$ triệu đồng", "$21{,}500$ triệu đồng"], "correctIndex": 1, "explain": "Chọn giá trị đại diện cho mỗi nhóm là trung bình cộng của hai đầu mút khoảng:<br>$c_1=12{,}5$, $c_2=17{,}5$, $c_3=22{,}5$, $c_4=27{,}5$, $c_5=32{,}5$.<br>Cỡ mẫu $n=80$.<br>Số trung bình của mẫu số liệu ghép nhóm là:<br>$\\bar{x}=\\dfrac{12\\cdot12{,}5+24\\cdot17{,}5+28\\cdot22{,}5+10\\cdot27{,}5+6\\cdot32{,}5}{80}$<br>$\\bar{x}=\\dfrac{150+420+630+275+195}{80}=\\dfrac{1670}{80}=20{,}875$ (triệu đồng)."}, {"question": "Công ty dự định trích quỹ \"Hỗ trợ đời sống\" dành riêng cho $25\\%$ số nhân viên có mức lương thấp nhất. Hỏi mức lương tối đa để một nhân viên đủ điều kiện nhận khoản hỗ trợ này là bao nhiêu (làm tròn kết quả đến hai chữ số thập phân)?", "choices": ["$16{,}25$ triệu đồng", "$16{,}67$ triệu đồng", "$17{,}00$ triệu đồng", "$17{,}33$ triệu đồng"], "correctIndex": 1, "explain": "Bài toán yêu cầu tìm giá trị chia mẫu số liệu thành $25\\%$ thấp nhất và $75\\%$ cao nhất. Giá trị cần tìm chính là tứ phân vị thứ nhất $Q_1$.<br>Ta có cỡ mẫu $n=80\\Rightarrow\\dfrac{n}{4}=20$.<br>Lập bảng tần số tích lũy:<br>$cf_1=12$, $cf_2=12+24=36$.<br>Vì $cf_1<20\\le cf_2$ nên nhóm chứa $Q_1$ là nhóm thứ hai: $[15; 20)$.<br>Ta có: đầu mút trái $L=15$, độ dài nhóm $h=5$, tần số nhóm $n_2=24$, tần số tích lũy nhóm liền trước $cf_1=12$.<br>Giá trị của tứ phân vị thứ nhất là:<br>$Q_1=L+\\dfrac{\\dfrac{n}{4}-cf_1}{n_2}\\cdot h=15+\\dfrac{20-12}{24}\\cdot 5=15+\\dfrac{8}{24}\\cdot 5=15+\\dfrac{5}{3}\\approx16{,}67$.<br>Vậy mức lương tối đa để một nhân viên được nhận khoản hỗ trợ là khoảng $16{,}67$ triệu đồng."}]}]}, {"id": "extra-12", "ten": "Đề luyện tập số 18", "nhom": [{"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ cân tại đỉnh $A$, biết độ dài cạnh đáy $BC$, đường cao $AH$ và cạnh bên $AB$ theo thứ tự lập thành cấp số nhân với công bội $q$. Giá trị của $q^2$ bằng", "choices": ["$\\dfrac{1+\\sqrt{5}}{2}$", "$\\dfrac{-1+\\sqrt{5}}{2}$", "$\\dfrac{1+\\sqrt{2}}{2}$", "$\\dfrac{-1+\\sqrt{2}}{2}$"], "correctIndex": 1, "explain": "Đặt $B C=a ; A B=A C=b ; A H=h$. <br>Theo giả thiết ta có $a, h, b$ lập cấp số nhân, suy ra $h^2=a b$. <br>Mặt khác tam giác $A B C$ cân tại dinh $A$ nên $h^2=m_z^2=\\dfrac{b^2+b^2}{2}-\\dfrac{a^2}{4}$<br>Do đó $\\dfrac{b^2+b^2}{2}-\\dfrac{a^2}{4}-a b \\Leftrightarrow a^2+4 a b-4 b^2-0 \\Leftrightarrow a-(2 \\sqrt{2}-2) b$<br>Lại có $b=q^2 a$ nên suy ra $q^2=\\dfrac{b}{a}=\\dfrac{1}{2 \\sqrt{2}-2}=\\dfrac{2 \\sqrt{2}+2}{4}=\\dfrac{\\sqrt{2}+1}{2}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho tam giác $ABC$ có các cạnh $a$, $b$, $c$ thỏa mãn điều kiện $(a+b+c)(a+b-c)=3ab$. Tính số đo của góc $C$.", "choices": ["$120^{\\circ}$", "$30^{\\circ}$", "$45^{\\circ}$", "$60^{\\circ}$"], "correctIndex": 3, "explain": "Trong tam giác $ABC$ ta luôn có: $c^2=a^2+b^2-2ab\\cos C$.<br>Hệ thức $(a+b+c)(a+b-c)=3ab \\Leftrightarrow (a+b)^2-c^2=3ab \\Leftrightarrow c^2=a^2+b^2-ab$.<br>Suy ra: $-2\\cos C=-1 \\Rightarrow \\cos C=\\dfrac{1}{2} \\Rightarrow C=60^{\\circ}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tập nghiệm của bất phương trình $\\sqrt{x-1} < 3$ là", "choices": ["$(-\\infty; 10)$", "$[1; 10]$", "$[1; 10)$", "$(1; 10)$"], "correctIndex": 2, "explain": "Bất phương trình tương đương với:  $0 \\le x-1 < 3^2 \\Leftrightarrow 0 \\le x-1 < 9 \\Leftrightarrow 1 \\le x < 10$. <br>Vậy tập nghiệm của bất phương trình là $S=[1; 10)$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Người ta thăm dò một số lượng người hâm mộ bóng đá tại một thành phố, nơi có hai đội bóng đá $X$ và $Y$ cùng thi đấu giải vô địch quốc gia. Biết rằng số lượng người hâm mộ đội bóng đá $X$ là $22\\%$, số lượng người hâm mộ đội bóng đá $Y$ là $39\\%$, trong số đó có $7\\%$ người nói rằng họ hâm mộ cả hai đội bóng trên. Chọn ngẫu nhiên một người hâm mộ trong số những người được hỏi. Xác suất để chọn được người không hâm mộ đội nào trong hai đội bóng đá $X$ và $Y$ là", "choices": ["$46\\%$", "$54\\%$", "$32\\%$", "$61\\%$"], "correctIndex": 0, "explain": "Gọi $A$ là biến cố người được chọn hâm mộ đội $X$, $B$ là biến cố người được chọn hâm mộ đội $Y$.<br>Theo giả thiết, ta có $P(A)=22\\%=0{,}22$; $P(B)=39\\%=0{,}39$ và $P(A \\cap B)=7\\%=0{,}07$.<br>Biến cố chọn được người hâm mộ ít nhất một trong hai đội là $A \\cup B$.<br>Ta có $P(A \\cup B)=P(A)+P(B)-P(A \\cap B)=0{,}22+0{,}39-0{,}07=0{,}54$.<br>Biến cố chọn được người không hâm mộ đội nào trong hai đội là $\\overline{A \\cup B}$.<br>Xác suất cần tìm là $P(\\overline{A \\cup B})=1-P(A \\cup B)=1-0{,}54=0{,}46$ hay $46\\%$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một người dự định trồng $126$ cây theo thời gian định trước. Nhưng do thời tiết xấu nên mỗi ngày trồng được ít hơn $5$ cây, vì thế khi trồng xong chậm mất $5$ ngày so với dự kiến. Hỏi thực tế mỗi ngày người đó trồng được bao nhiêu cây?", "choices": ["$7$ cây", "$9$ cây", "$14$ cây", "$12$ cây"], "correctIndex": 1, "explain": "Gọi $x$ là số cây thực tế mỗi ngày người đó trồng được ($x>0$, đơn vị: cây).<br>Số cây mỗi ngày dự định trồng là $x+5$ (cây).<br>Thời gian dự định trồng hết $126$ cây là $\\dfrac{126}{x+5}$ (ngày).<br>Thời gian thực tế trồng hết $126$ cây là $\\dfrac{126}{x}$ (ngày).<br>Vì thực tế chậm mất $5$ ngày so với dự kiến nên ta có phương trình:  $\\dfrac{126}{x}-\\dfrac{126}{x+5}=5$<br>$\\Leftrightarrow \\dfrac{126(x+5)-126x}{x(x+5)}=5 \\Leftrightarrow \\dfrac{630}{x^2+5x}=5$<br>$\\Leftrightarrow x^2+5x-126=0 \\Leftrightarrow \\hoac{&x=9 \\text{ (thỏa mãn)}\\\\&x=-14 \\text{ (loại)}}$.<br>Vậy thực tế mỗi ngày người đó trồng được $9$ cây."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho cấp số cộng $(u_n)$ có $u_1=5$ và công sai $d=-3$. Biết rằng $-289$ là một số hạng của cấp số cộng trên. Hỏi đó là số hạng thứ bao nhiêu?", "choices": ["98", "99", "99", "100"], "correctIndex": 2, "explain": "Ta có công thức số hạng tổng quát của cấp số cộng: $u_n=u_1+(n-1)d$.<br>Theo đề bài, ta có:  $-289=5+(n-1)(-3)$  $\\Leftrightarrow -294=(n-1)(-3)$  $\\Leftrightarrow n-1=98$  $\\Leftrightarrow n=99$.<br>Vậy $-289$ là số hạng thứ $99$ của cấp số cộng."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Một con robot di chuyển trên mặt phẳng tọa độ từ điểm $A(0;0)$ đến điểm $B(4;3)$ bằng cách chỉ đi sang phải hoặc lên trên. Tuy nhiên, robot không thể đi qua đoạn thẳng nối từ $M(1;1)$ đến $N(2;1)$ do có vật cản. Số đường đi ngắn nhất dành cho robot là", "choices": ["$35$", "$29$", "$23$", "$18$"], "correctIndex": 2, "explain": "Tổng số đường đi từ $A(0;0)$ đến $B(4;3)$ là $C_{4+3}^3 = 35$ cách.<br>Số đường đi đi qua đoạn $MN$:<br>a) Bước 1: Đi từ $A(0;0)$ đến $M(1;1)$ có $C_{1+1}^1 = 2$ cách.  <br>b) Bước 2: Đi từ $M(1;1)$ sang phải đến $N(2;1)$ có $1$ cách duy nhất.  <br>c) Bước 3: Đi từ $N(2;1)$ đến $B(4;3)$ (đi thêm $2$ phải, $2$ lên) có $C_{2+2}^2 = 6$ cách.<br>Số đường đi qua đoạn $MN$ là $2\\cdot 1\\cdot 6 = 12$ cách.<br>Số đường đi thỏa mãn là $35-12 = 23$ cách."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Tìm tất cả các giá trị nguyên của tham số $m$ để tập nghiệm của bất phương trình $3^{x^2}m^{x+1}-3^{-x}<0$ chứa đúng một số nguyên.", "choices": ["$0$", "$18$", "$14$", "$6$"], "correctIndex": 1, "explain": "Điều kiện: $m>0$. Bất phương trình tương đương với:  $$3^{x^2}m^{x+1}<3^{-x} \\Leftrightarrow m^{x+1}<3^{-x-x^2} \\Leftrightarrow m^{x+1}<3^{-x(x+1)}$$  Lấy logarit cơ số $3$ hai vế ta được:  $$(x+1)\\log_3 m < -x(x+1) \\Leftrightarrow (x+1)(x+\\log_3 m) < 0$$  Đây là bất phương trình bậc hai đối với $x$ có hai nghiệm là $x_1=-1$ và $x_2=-\\log_3 m$.  Tập nghiệm của bất phương trình là khoảng nằm giữa $x_1$ và $x_2$. Để tập nghiệm chứa đúng một số nguyên, ta xét hai trường hợp:<br>a) <b>Trường hợp 1:</b> $x_1 < x_2 \\Leftrightarrow -1 < -\\log_3 m \\Leftrightarrow \\log_3 m < 1 \\Leftrightarrow m < 3$.  Khoảng nghiệm là $(-1;-\\log_3 m)$. Để khoảng này chứa đúng một số nguyên thì số nguyên đó phải là $0$.  Điều kiện: $0 < -\\log_3 m \\le 1 \\Leftrightarrow -1 \\le \\log_3 m < 0 \\Leftrightarrow \\dfrac{1}{3} \\le m < 1$.  Vì $m$ nguyên nên không có giá trị $m$ nào thỏa mãn trường hợp này.  <br>b) <b>Trường hợp 2:</b> $x_2 < x_1 \\Leftrightarrow -\\log_3 m < -1 \\Leftrightarrow \\log_3 m > 1 \\Leftrightarrow m > 3$.  Khoảng nghiệm là $(-\\log_3 m;-1)$. Để khoảng này chứa đúng một số nguyên thì số nguyên đó phải là $-2$.  Điều kiện: $-3 \\le -\\log_3 m < -2 \\Leftrightarrow 2 < \\log_3 m \\le 3 \\Leftrightarrow 9 < m \\le 27$.  Vì $m \\in \\mathbb{Z}$ nên $m \\in \\{10; 11; \\dots; 27\\}$. Số giá trị nguyên của $m$ là $27 - 10 + 1 = 18$.<br>Vậy có tất cả $18$ giá trị nguyên của tham số $m$ thỏa mãn yêu cầu bài toán."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Biết phương trình $\\log_2^2 x-2\\log_2(2x)-1=0$ có hai nghiệm $x_1$, $x_2$. Giá trị của tích $x_1x_2$ bằng", "choices": ["$4$", "$\\dfrac{1}{8}$", "$-3$", "$\\dfrac{1}{2}$"], "correctIndex": 0, "explain": "Điều kiện: $x>0$.<br>Phương trình đã cho tương đương với:  $$\\log_2^2 x-2(\\log_2 2+\\log_2 x)-1=0 \\Leftrightarrow \\log_2^2 x-2(1+\\log_2 x)-1=0$$  $$\\Leftrightarrow \\log_2^2 x-2\\log_2 x-3=0.$$  Đặt $t=\\log_2 x$, phương trình trở thành:  $$t^2-2t-3=0 \\Leftrightarrow \\hoac{&t=-1<br>&t=3.}$$<br>a) Với $t_1=-1 \\Rightarrow \\log_2 x_1=-1 \\Rightarrow x_1=2^{-1}=\\dfrac{1}{2}$.  <br>b) Với $t_2=3 \\Rightarrow \\log_2 x_2=3 \\Rightarrow x_2=2^3=8$.<br>Vậy tích $x_1x_2 = \\dfrac{1}{2}\\cdot 8 = 4$.  <br>* <b>Cách 2:</b> Sử dụng định lý Vi-ét cho phương trình bậc hai theo $t$:  Ta có $t_1+t_2 = -\\dfrac{-2}{1} = 2$.<br>Mà $t_1+t_2 = \\log_2 x_1+\\log_2 x_2 = \\log_2(x_1x_2)$.<br>Suy ra $\\log_2(x_1x_2)=2 \\Leftrightarrow x_1x_2=2^2=4$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Cho các số thực $a$, $b$ thỏa mãn $a>b>1$ và $\\dfrac{1}{\\log_b a}+\\dfrac{1}{\\log_a b}=\\sqrt{2022}$. Giá trị của biểu thức $P=\\dfrac{1}{\\log_b a}-\\dfrac{1}{\\log_a b}$ bằng", "choices": ["$-\\sqrt{2018}$", "$\\sqrt{2014}$", "$-\\sqrt{2016}$", "$\\sqrt{2020}$"], "correctIndex": 0, "explain": "Đặt $x=\\dfrac{1}{\\log_b a}=\\log_a b$. Khi đó $\\dfrac{1}{\\log_a b}=\\log_b a=\\dfrac{1}{x}$.<br>Theo giả thiết: $x+\\dfrac{1}{x}=\\sqrt{2022}$.<br>Ta cần tính giá trị của $P=x-\\dfrac{1}{x}$.<br>Vì $a>b>1 \\Rightarrow \\log_a b < \\log_a a = 1$ và $\\log_a b > \\log_a 1 = 0$, nên $0<x<1$.<br>Do $0<x<1$ nên $x < \\dfrac{1}{x} \\Rightarrow P=x-\\dfrac{1}{x} < 0$.<br>Mặt khác:  $P^2 = \\left(x-\\dfrac{1}{x}\\right)^2 = x^2-2+\\dfrac{1}{x^2} = \\left(x^2+2+\\dfrac{1}{x^2}\\right)-4 = \\left(x+\\dfrac{1}{x}\\right)^2-4$.<br>Thay $x+\\dfrac{1}{x}=\\sqrt{2022}$ vào ta được:  $P^2 = (\\sqrt{2022})^2-4 = 2022-4 = 2018$.<br>Do $P<0$ nên $P=-\\sqrt{2018}$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Kết quả của $\\lim\\limits_{x\\to-\\infty}\\dfrac{(-x^2+1)^3(1-2x)^4}{2x^{100}+3}$ là", "choices": ["$-\\infty$", "$-2^{100}$", "$2^{95}$", "$0$"], "correctIndex": 3, "explain": "Ta có:<br>a) Bậc của tử thức: Số hạng chứa bậc cao nhất là $(-x^2)^3\\cdot(-2x)^4=(-1)^3\\cdot x^6\\cdot 16x^4=-16x^{10}$.  <br>b) Bậc của mẫu thức: $100$.<br>Vì bậc của tử thức ($10$) nhỏ hơn bậc của mẫu thức ($100$), nên giới hạn của dãy số khi $x\\to-\\infty$ bằng $0$."}]}, {"noiDungChung": null, "cauHoi": [{"question": "Hàm số $v(t)=\\heva{&-t^2+4t+12&&\\text{khi }0\\leq t\\leq 5\\\\&at-3&&\\text{khi }5<t\\leq 10}$ mô tả vận tốc $(\\text{m}/\\text{s})$ của một vật tại thời điểm $t$ (giây) trong khoảng thời gian $10$ giây đầu tiên kể từ khi vật bắt đầu chuyển động. Biết rằng $v(t)$ là hàm liên tục trên đoạn $[0;10]$ và trong $10$ giây đầu tiên đó, có hai lần vật đạt vận tốc $10$ $(\\text{m}/\\text{s})$ là vào các thời điểm $t_1$ giây và $t_2$ giây. Khi đó giá trị của $t_1+t_2$ gần nhất với giá trị nào sau đây?", "choices": ["$9{,}55$", "$10{,}12$", "$10{,}95$", "$11{,}45$"], "correctIndex": 2, "explain": "Vì hàm số $v(t)$ liên tục trên đoạn $[0;10]$ nên $v(t)$ liên tục tại $t=5$.<br>Ta có:<br>a) $\\lim\\limits_{t\\to 5^-}v(t)=-5^2+4\\cdot 5+12=7$.  <br>b) $\\lim\\limits_{t\\to 5^+}v(t)=5a-3$.  <br>c) $v(5)=7$.<br>Để hàm số liên tục tại $t=5$ thì $5a-3=7\\Leftrightarrow 5a=10\\Leftrightarrow a=2$.<br>Khi đó, hàm số vận tốc là $v(t)=\\heva{&-t^2+4t+12&&\\text{khi }0\\leq t\\leq 5\\\\&2t-3&&\\text{khi }5<t\\leq 10.}$<br>Xét phương trình $v(t)=10$:<br>a) Với $0\\leq t\\leq 5$: $-t^2+4t+12=10\\Leftrightarrow -t^2+4t+2=0\\Leftrightarrow\\hoac{&t=2+\\sqrt{6}\\approx 4{,}45\\text{ (nhận)}\\\\&t=2-\\sqrt{6}\\text{ (loại).}}$<br>Vậy $t_1=2+\\sqrt{6}$.  <br>b) Với $5<t\\leq 10$: $2t-3=10\\Leftrightarrow 2t=13\\Leftrightarrow t=6{,}5\\text{ (nhận).}$<br>Vậy $t_2=6{,}5$.<br>Giá trị cần tìm là $t_1+t_2=2+\\sqrt{6}+6{,}5=8{,}5+\\sqrt{6}\\approx 10{,}949$."}]}, {"noiDungChung": "Cho lăng trụ đứng tam giác đều $ABC.A'B'C'$ có tất cả các cạnh bằng $a$.", "cauHoi": [{"question": "Tính thể tích $V$ của khối lăng trụ $ABC.A'B'C'$ theo $a$.", "choices": ["$V = \\dfrac{a^3\\sqrt{3}}{2}$", "$V = a^3\\sqrt{3}$", "$V = \\dfrac{a^3\\sqrt{3}}{4}$", "$V = \\dfrac{a^3}{4}$"], "correctIndex": 2, "explain": "Diện tích đáy là tam giác đều cạnh $a$: $S_{ABC} = \\dfrac{a^2\\sqrt{3}}{4}$.<br>Vì đây là lăng trụ đứng nên chiều cao $h = AA' = a$.<br>Thể tích khối lăng trụ: $V = S_{ABC} \\cdot h = \\dfrac{a^2\\sqrt{3}}{4} \\cdot a = \\dfrac{a^3\\sqrt{3}}{4}$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[scale=1, font=\\footnotesize, line join=round, line cap=round, >=stealth]\n\t\t\t\t\t\\usetikzlibrary{calc}\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (A') at (0,0);\n\t\t\t\t\t\\coordinate (B') at (1.2,-1.2);\n\t\t\t\t\t\\coordinate (C') at (3.5,0);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (A) at ($(A')+(0,3.5)$);\n\t\t\t\t\t\\coordinate (B) at ($(B')+(0,3.5)$);\n\t\t\t\t\t\\coordinate (C) at ($(C')+(0,3.5)$);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\coordinate (H) at ($(B')!0.5!(C')$);\n\t\t\t\t\t\\coordinate (K) at ($(B)!0.6!(C')$); \n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[dashed, thin] (A')--(C')  (A')--(B) (A')--(C') (A')--(H) (A')--(K);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\draw[thick] (A)--(B)--(C)--cycle;\n\t\t\t\t\t\\draw[thick] (B')--(C') (B)--(B') (C)--(C') (A)--(A') (A')--(B) (B)--(C')(A')--(B') ;\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\foreach \\p in {A,B,C,A',B',C',H,K}\n\t\t\t\t\t\\fill[red] (\\p) circle (1.5pt);\n\t\t\t\t\t\n\t\t\t\t\t\n\t\t\t\t\t\\node[above] at (A) {$A$};\n\t\t\t\t\t\\node[below] at (B) {$B$};\n\t\t\t\t\t\\node[right] at (C) {$C$};\n\t\t\t\t\t\\node[left] at (A') {$A'$};\n\t\t\t\t\t\\node[below] at (B') {$B'$};\n\t\t\t\t\t\\node[right] at (C') {$C'$};\n\t\t\t\t\t\\node[below] at (H) {$H$};\n\t\t\t\t\t\\node[right] at (K) {$K$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Tính khoảng cách $d$ từ điểm $A$ đến mặt phẳng $(BCC'B')$.", "choices": ["$d = a$", "$d = \\dfrac{a\\sqrt{3}}{2}$", "$d = \\dfrac{a}{2}$", "$d = a\\sqrt{3}$"], "correctIndex": 1, "explain": "Gọi $M$ là trung điểm của $BC$. Vì tam giác $ABC$ đều nên $AM \\perp BC$.<br>Mặt khác, do lăng trụ đứng nên $BB' \\perp (ABC) \\Rightarrow BB' \\perp AM$.<br>Ta có $\\heva{&AM \\perp BC \\\\ &AM \\perp BB'} \\Rightarrow AM \\perp (BCC'B')$.<br>Vậy $d(A, (BCC'B')) = AM = \\dfrac{a\\sqrt{3}}{2}$ (đường cao tam giác đều cạnh $a$)."}, {"question": "Gọi $\\alpha$ là góc giữa hai mặt phẳng $(A'BC')$ và $(BCC'B')$. Tính $\\cos \\alpha$.", "choices": ["$\\cos \\alpha = \\dfrac{\\sqrt{42}}{7}$", "$\\cos \\alpha = \\dfrac{\\sqrt{42}}{14}$", "$\\cos \\alpha = \\dfrac{\\sqrt{7}}{7}$", "$\\cos \\alpha = \\dfrac{1}{7}$"], "correctIndex": 2, "explain": "Ta có $(A'BC') \\cap (BCC'B') = BC'$.<br>Gọi $\\alpha$ là góc giữa hai mặt phẳng, khi đó $\\sin \\alpha = \\dfrac{d(A'; (BCC'B'))}{d(A'; BC')}$.<br>Theo chứng minh ở ý trên, $d(A'; (BCC'B')) = \\dfrac{a\\sqrt{3}}{2}$.<br>Trong mặt phẳng $(A'BC')$, kẻ $A'K \\perp BC'$. Tam giác $A'BC'$ cân tại $B$ ($A'B=BC'=a\\sqrt{2}$).<br>Xét tam giác $A'BC'$, ta tính được $A'K = \\dfrac{a\\sqrt{14}}{4}$.<br>Suy ra $\\sin \\alpha = \\dfrac{a\\sqrt{3}/2}{a\\sqrt{14}/4} = \\dfrac{\\sqrt{6}}{\\sqrt{7}}$.<br>Vậy $\\cos \\alpha = \\sqrt{1 - \\sin^2 \\alpha} = \\sqrt{1 - \\dfrac{6}{7}} = \\dfrac{1}{\\sqrt{7}} = \\dfrac{\\sqrt{7}}{7}$."}]}, {"noiDungChung": "Tại một nhà máy sản xuất vi mạch, tỉ lệ linh kiện bị lỗi kỹ thuật là $1\\%$. Để phân loại sản phẩm, nhà máy sử dụng một máy quét quang học. Nếu linh kiện lỗi, máy quét nhận diện đúng với xác suất $99\\%$. Nếu linh kiện không lỗi, máy quét vẫn có thể kết luận nhầm là lỗi với xác suất $2\\%$. Chọn ngẫu nhiên một linh kiện từ dây chuyền để kiểm tra.", "cauHoi": [{"question": "Giả sử máy quét kết luận linh kiện này là lỗi. Xác suất thực tế linh kiện này bị lỗi thực sự là bao nhiêu (làm tròn đến $4$ chữ số thập phân)?", "choices": ["$0{,}3333$", "$0{,}9900$", "$0{,}5000$", "$0{,}6667$"], "correctIndex": 0, "explain": "Ta cần tính xác suất có điều kiện $P(A|E)$.<br>Áp dụng công thức Bayes:  $P(A|E) = \\dfrac{P(A) \\cdot P(E|A)}{P(E)}$.<br>Thay các giá trị đã tính ở câu trên vào:  $P(A|E) = \\dfrac{0{,}0099}{0{,}0297} = \\dfrac{1}{3} \\approx 0{,}3333$."}, {"question": "Để đảm bảo chính xác, linh kiện bị máy kết luận lỗi sẽ được kiểm tra lại lần thứ hai bằng một thiết bị độc lập có cùng độ chính xác. Nếu lần hai máy vẫn kết luận là lỗi, xác suất linh kiện này thực sự bị lỗi là bao nhiêu (làm tròn đến $4$ chữ số thập phân)?", "choices": ["$0{,}9801$", "$0{,}9612$", "$0{,}0388$", "$0{,}3333$"], "correctIndex": 1, "explain": "Gọi $E_1$, $E_2$ lần lượt là biến cố máy kết luận lỗi lần $1$ và lần $2$.<br>Ta có $P(E_1 \\cap E_2|A) = (0{,}99)^2 = 0{,}9801$.<br>$P(E_1 \\cap E_2|\\overline{A}) = (0{,}02)^2 = 0{,}0004$.<br>Xác suất cần tìm:  $P(A|E_1 \\cap E_2) = \\dfrac{P(A) \\cdot P(E_1 \\cap E_2|A)}{P(A) \\cdot P(E_1 \\cap E_2|A) + P(\\overline{A}) \\cdot P(E_1 \\cap E_2|\\overline{A})}$<br>$= \\dfrac{0{,}01 \\cdot 0{,}9801}{0{,}01 \\cdot 0{,}9801 + 0{,}99 \\cdot 0{,}0004} = \\dfrac{0{,}009801}{0{,}009801 + 0{,}000396} = \\dfrac{0{,}009801}{0{,}010197} \\approx 0{,}9612$."}]}, {"noiDungChung": "Để chuẩn bị quà cho các em nhỏ vùng cao, một nhóm tình nguyện dự định làm hai loại bánh: bánh nướng và bánh dẻo. Mỗi chiếc bánh nướng cần $3$ giờ để chế biến và đóng gói, bán với giá $40$ ngàn đồng. Mỗi chiếc bánh dẻo cần $2$ giờ để chế biến và đóng gói, bán với giá $30$ ngàn đồng. Nhóm có tổng cộng $60$ giờ làm việc và dự định làm ít nhất $25$ chiếc bánh cả hai loại. Giả sử số bánh làm ra đều được bán hết. Gọi $x$, $y$ lần lượt là số lượng bánh nướng và bánh dẻo ($x \\ge 0$, $y \\ge 0$, $x,y \\in \\mathbb{N}$).", "cauHoi": [{"question": "Số tiền lớn nhất mà nhóm tình nguyện có thể thu được là bao nhiêu ngàn đồng?", "choices": ["$900$", "$850$", "$800$", "$1{,}000$"], "correctIndex": 0, "explain": "Số tiền thu được là hàm số: $F(x,y)=40x+30y$.<br>Các ràng buộc của bài toán được mô tả bởi hệ bất phương trình: $\\heva{&x \\ge 0\\\\&y \\ge 0\\\\&3x+2y \\le 60\\\\&x+y \\ge 25.}$<br>Miền nghiệm của hệ là miền tam giác $ABC$ (kể cả biên) với các đỉnh là:<br>a) $A$ là giao điểm của $3x+2y=60$ và $x+y=25$: Giải hệ $\\heva{&3x+2y=60\\\\&x+y=25} \\Rightarrow A(10;15)$.  <br>b) $B$ là giao điểm của $x+y=25$ và trục $Oy$ ($x=0$): $B(0;25)$.  <br>c) $C$ là giao điểm của $3x+2y=60$ và trục $Oy$ ($x=0$): $C(0;30)$.<br>Tính giá trị của $F(x,y)$ tại các đỉnh:<br>a) $F(10;15)=40 \\cdot 10+30 \\cdot 15=850$.  <br>b) $F(0;25)=40 \\cdot 0+30 \\cdot 25=750$.  <br>c) $F(0;30)=40 \\cdot 0+30 \\cdot 30=900$.<br>Vậy số tiền lớn nhất thu được là $900$ ngàn đồng.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[>=stealth, x=0.25cm, y=0.25cm, font=\\footnotesize,scale=.6]\n\t\t\t\t\t\\def\\xmin{-4} \\def\\xmax{25}\n\t\t\t\t\t\\def\\ymin{-4} \\def\\ymax{35}\n\t\t\t\t\t\\draw[color=gray!20] (\\xmin,\\ymin) grid (\\xmax,\\ymax);\n\t\t\t\t\t\\draw[->, thick] (\\xmin,0) -- (\\xmax,0) node[below] {$x$};\n\t\t\t\t\t\\draw[->, thick] (0,\\ymin) -- (0,\\ymax) node[left] {$y$};\n\t\t\t\t\t\\node[below left] at (0,0) {$O$};\n\t\t\t\t\t\\begin{scope}\n\t\t\t\t\t\t\\clip (0,0) rectangle (\\xmax,\\ymax);\n\t\t\t\t\t\t\\fill[pattern=north east lines, pattern color=blue!20] (0,30) -- (20,0) -- (\\xmax,0) -- (\\xmax,\\ymax) -- (0,\\ymax) -- cycle;\n\t\t\t\t\t\t\\fill[pattern=north west lines, pattern color=red!20] (0,0) -- (25,0) -- (0,25) -- cycle;\n\t\t\t\t\t\\end{scope}\n\t\t\t\t\t\\draw[thick, blue] plot[domain=-1:21] (\\x,{(60-3*\\x)/2}) node[right] {$d_1$};\n\t\t\t\t\t\\draw[thick, red] plot[domain=-1:26] (\\x,{25-\\x}) node[above right] {$d_2$};\n\t\t\t\t\t\\fill (10,15) circle (2.5pt) node[above right] {$A(10;15)$};\n\t\t\t\t\t\\fill (0,25) circle (2.5pt) node[left] {$B(0;25)$};\n\t\t\t\t\t\\fill (0,30) circle (2.5pt) node[left] {$C(0;30)$};\n\t\t\t\t\\end{tikzpicture}</script></div>"}, {"question": "Nếu nhóm tình nguyện muốn thu được đúng $850$ ngàn đồng thì số lượng bánh mỗi loại cần làm là", "choices": ["$15$ bánh nướng và $10$ bánh dẻo", "$10$ bánh nướng và $15$ bánh dẻo", "$20$ bánh nướng và $5$ bánh dẻo", "$5$ bánh nướng và $20$ bánh dẻo"], "correctIndex": 1, "explain": "Để số tiền thu được bằng $850$ ngàn đồng, ta có phương trình: $40x+30y=850 \\Leftrightarrow 4x+3y=85$.<br>Kết hợp với các điều kiện ràng buộc của bài toán, điểm $(x;y)$ phải thuộc miền nghiệm của hệ bất phương trình.<br>Dựa vào tính toán ở câu trước, tại đỉnh $A(10;15)$ ta có $F(10;15)=40 \\cdot 10+30 \\cdot 15=850$.<br>Kiểm tra điều kiện $x,y \\in \\mathbb{N}$ và thuộc miền nghiệm:<br>$\\heva{&10+15 \\ge 25\\\\&3(10)+2(15) \\le 60} \\Leftrightarrow \\heva{&25 \\ge 25\\\\&60 \\le 60}$ (Thỏa mãn).<br>Vậy nhóm cần làm $10$ bánh nướng và $15$ bánh dẻo."}]}, {"noiDungChung": "Một kiến trúc sư thiết kế mái vòm của một tòa nhà có mặt cắt là đường cong $y = 4-x^2$ (đơn vị mét) với trục hoành là mặt sàn. Ông dự định lắp đặt các tấm kính cường lực cho phần diện tích giới hạn bởi mái vòm này và mặt sàn.", "cauHoi": [{"question": "Tính diện tích $S$ của phần mặt phẳng giới hạn bởi mái vòm và mặt sàn.", "choices": ["$S = \\dfrac{16}{3}\\text{ m}^2$", "$S = \\dfrac{28}{3}\\text{ m}^2$", "$S = \\dfrac{32}{3}\\text{ m}^2$", "$S = 8\\text{ m}^2$"], "correctIndex": 2, "explain": "Phương trình hoành độ giao điểm của đồ thị và trục hoành:  <br>$4-x^2 = 0 \\Leftrightarrow \\hoac{&x = 2\\\\&x = -2}$.  <br>Diện tích cần tìm là:  <br>$S = \\int\\limits_{-2}^{2} |4-x^2| dx = \\left. \\left(4x - \\dfrac{x^3}{3}\\right) \\right|_{-2}^{2} = \\left(8 - \\dfrac{8}{3}\\right) - \\left(-8 + \\dfrac{8}{3}\\right) = \\dfrac{16}{3} + \\dfrac{16}{3} = \\dfrac{32}{3}\\text{ (m}^2\\text{)}$."}, {"question": "Chi phí lắp đặt mỗi mét vuông kính là $2$ triệu đồng, tổng số tiền (làm tròn đến triệu đồng) để hoàn thiện mái vòm là", "choices": ["$20$ triệu đồng", "$21$ triệu đồng", "$22$ triệu đồng", "$23$ triệu đồng"], "correctIndex": 1, "explain": "Tổng số tiền chi phí là:  <br>$T = S \\cdot 2 = \\dfrac{32}{3} \\cdot 2 = \\dfrac{64}{3} \\approx 21{,}33$ triệu đồng.  <br>Làm tròn đến hàng đơn vị ta được $21$ triệu đồng."}]}, {"noiDungChung": "Trong không gian với hệ tọa độ $Oxyz$, cho hai điểm $A(0;-1;2)$, $B(1;1;2)$ và đường thẳng $d\\colon \\dfrac{x+1}{1}=\\dfrac{y}{1}=\\dfrac{z-1}{1}$.", "cauHoi": [{"question": "Viết phương trình mặt phẳng $(P)$ đi qua hai điểm $A$, $B$ và song song với đường thẳng $d$.", "choices": ["$2x-y-z+3=0$", "$2x-y-z+4=0$", "$2x-y+z-4=0$", "$2x-y-z+1=0$"], "correctIndex": 3, "explain": "Véc-tơ chỉ phương của đường thẳng $d$ là $\\vec{u}_d=(1;1;1)$.<br>Véc-tơ nối hai điểm $A, B$ là $\\vec{AB}=(1;2;0)$.<br>Mặt phẳng $(P)$ có véc-tơ pháp tuyến là:  $$\\vec{n}_P = [\\vec{AB}, \\vec{u}_d] = (2\\cdot1 - 0\\cdot1; 0\\cdot1 - 1\\cdot1; 1\\cdot1 - 2\\cdot1) = (2;-1;-1)$$  Phương trình mặt phẳng $(P)$ đi qua điểm $A(0;-1;2)$ có dạng:  $$2(x-0) - 1(y+1) - 1(z-2) = 0 \\Leftrightarrow 2x-y-z+1=0$$"}, {"question": "Tìm tọa độ điểm $N$ thuộc đường thẳng $d$ sao cho độ dài đoạn thẳng $AN$ ngắn nhất.", "choices": ["$N(0;1;2)$", "$N(-1;0;1)$", "$N\\left(-\\dfrac{1}{3};\\dfrac{2}{3};\\dfrac{5}{3}\\right)$", "$N\\left(-\\dfrac{2}{3};\\dfrac{1}{3};\\dfrac{4}{3}\\right)$"], "correctIndex": 3, "explain": "Vì $N\\in d \\Rightarrow N(-1+t;t;1+t)$. Ta có véc-tơ $\\vec{AN}=(-1+t;t+1;t-1)$.<br>Độ dài bình phương đoạn thẳng $AN$ được tính bằng:  $$AN^2 = (-1+t)^2 + (t+1)^2 + (t-1)^2 = 3t^2 - 2t + 3$$  Biểu thức $3t^2 - 2t + 3$ đạt giá trị nhỏ nhất tại hoành độ đỉnh parabol:  $$t = -\\dfrac{b}{2a} = \\dfrac{2}{2\\cdot3} = \\dfrac{1}{3}$$  Thay $t = \\dfrac{1}{3}$ vào tọa độ tham số của $N$, ta được:  $$N\\left(-1+\\dfrac{1}{3}; \\dfrac{1}{3}; 1+\\dfrac{1}{3}\\right) \\Rightarrow N\\left(-\\dfrac{2}{3};\\dfrac{1}{3};\\dfrac{4}{3}\\right)$$"}, {"question": "Biết điểm $M(a;b;c)$ thuộc đường thẳng $d$ sao cho tam giác $MAB$ có diện tích nhỏ nhất. Khi đó, giá trị $T=a+2b+3c$ bằng bao nhiêu?", "choices": ["$T=4$", "$T=3$", "$T=5$", "$T=10$"], "correctIndex": 3, "explain": "Ta có $\\vec{AB}=(1;2;0)$. Đường thẳng $d$ có phương trình tham số: $\\heva{&x=-1+t\\\\&y=t\\\\&z=1+t}$.<br>Vì $M\\in d$ nên $M(-1+t;t;1+t)$. Ta có véc-tơ $\\vec{AM}=(-1+t;t+1;t-1)$.<br>Tích có hướng của hai véc-tơ là:  $$[\\vec{AB},\\vec{AM}] = (2t-2;-t+1;-t+3)$$  Diện tích tam giác $MAB$ được tính theo công thức:  $$S = \\dfrac{1}{2}\\big|[\\vec{AB},\\vec{AM}]\\big| = \\dfrac{1}{2}\\sqrt{(2t-2)^2 + (-t+1)^2 + (-t+3)^2} = \\dfrac{1}{2}\\sqrt{6t^2-16t+14}$$  Diện tích $S$ đạt giá trị nhỏ nhất khi tam thức bậc hai $f(t) = 6t^2-16t+14$ nhỏ nhất, đạt tại:  $$t = \\dfrac{16}{2\\cdot6} = \\dfrac{4}{3}$$  Thay $t = \\dfrac{4}{3}$ vào tọa độ tham số điểm $M$, ta thu được:  $$M\\left(\\dfrac{1}{3};\\dfrac{4}{3};\\dfrac{7}{3}\\right) \\Rightarrow a=\\dfrac{1}{3},\\, b=\\dfrac{4}{3},\\, c=\\dfrac{7}{3}$$  Khi đó, giá trị của biểu thức $T$ là:  $$T = a+2b+3c = \\frac{1}{3} + 2\\cdot\\frac{4}{3} + 3\\cdot\\frac{7}{3} = \\frac{1+8+21}{3} = 10$$"}]}, {"noiDungChung": "Trong mặt phẳng tọa độ $Oxy$, cho đường tròn $(C) \\colon (x-2)^2+(y-1)^2=5$ có tâm $I$ và đường thẳng $\\Delta \\colon x+y+2=0$. Một điểm $M$ thuộc đường thẳng $\\Delta$ sao cho từ $M$ kẻ được hai tiếp tuyến $MA$, $MB$ đến đường tròn $(C)$ ($A$, $B$ là các tiếp điểm).", "cauHoi": [{"question": "Xác định tọa độ tâm $I$ và bán kính $R$ của đường tròn $(C)$.", "choices": ["$I(-2;-1)$, $R=5$", "$I(2;1)$, $R=25$", "$I(2;1)$, $R=\\sqrt{5}$", "$I(2;1)$, $R=5$"], "correctIndex": 2, "explain": "Từ phương trình đường tròn $(C) \\colon (x-2)^2+(y-1)^2=5$, ta có tâm $I(2;1)$ và bán kính $R=\\sqrt{5}$."}, {"question": "Tìm điểm $M(a;b)$ ($a>0$) thuộc đường thẳng $\\Delta \\colon x+y+2=0$ sao cho diện tích tứ giác $MAIB$ bằng $10$. Tính $a \\cdot b$.", "choices": ["$-6$", "$-8$", "$-3$", "$3$"], "correctIndex": 1, "explain": "Ta có $S_{MAIB}=2S_{\\triangle AMI}=AM \\cdot AI=10 \\Rightarrow AM=\\dfrac{10}{\\sqrt{5}}=2\\sqrt{5}$.<br>Trong tam giác vuông $MAI$, ta có $MI=\\sqrt{AM^2+AI^2}=\\sqrt{(2\\sqrt{5})^2+(\\sqrt{5})^2}=5$.<br>Gọi $M(a;-a-2) \\in \\Delta$. Khi đó $MI^2=25 \\Leftrightarrow (a-2)^2+(-a-2-1)^2=25 \\Leftrightarrow (a-2)^2+(a+3)^2=25$.<br>$\\Leftrightarrow 2a^2+2a-12=0 \\Leftrightarrow \\hoac{&a=2\\\\&a=-3.}$<br>Với $a>0$, ta chọn $a=2 \\Rightarrow b=-2-2=-4$. Vậy $a \\cdot b=2 \\cdot (-4)=-8$."}, {"question": "Với điểm $M$ có hoành độ dương vừa tìm được, tính số đo góc $\\widehat{AMB}$ (làm tròn đến phút).", "choices": ["$53^\\circ 8'$", "$48^\\circ 12'$", "$60^\\circ$", "$53^\\circ 13'$"], "correctIndex": 0, "explain": "Xét tam giác $MAI$ vuông tại $A$, ta có:  $$\\sin\\widehat{AMI} = \\dfrac{AI}{MI} = \\dfrac{\\sqrt{5}}{5} = \\dfrac{1}{\\sqrt{5}}$$  Suy ra $\\widehat{AMI} \\approx 26^{\\circ}33'54”$.<br>Do tính chất của hai tiếp tuyến cắt nhau, $MI$ là tia phân giác của góc $\\widehat{AMB}$.<br>Vậy $\\widehat{AMB} = 2\\widehat{AMI} \\approx 2 \\cdot 26^{\\circ}33'54” = 53^{\\circ}7'48” \\approx 53^{\\circ}8'$."}]}, {"noiDungChung": "Cho hàm số $y=f(x)=\\dfrac{\\sqrt{x^2+3}-2}{x-1}$ có đồ thị là $(C)$.", "cauHoi": [{"question": "Xác định tập xác định $D$ của hàm số đã cho.", "choices": ["$D=\\mathbb{R}$", "$D=[1;+\\infty)$", "$D=\\mathbb{R}\\setminus\\{1\\}$", "$D=(-\\infty;1)$"], "correctIndex": 2, "explain": "Hàm số xác định khi biểu thức dưới dấu căn không âm và mẫu thức khác $0$.<br>Ta có: $\\heva{&x^2+3\\geq 0\\\\&x-1\\neq 0}\\Leftrightarrow x\\neq 1$.<br>Vậy tập xác định là $D=\\mathbb{R}\\setminus\\{1\\}$."}, {"question": "Tìm tổng số đường tiệm cận đứng và tiệm cận ngang của đồ thị $(C)$.", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 1, "explain": "Xét các giới hạn tại vô cực:  $\\lim\\limits_{x\\to +\\infty} \\dfrac{\\sqrt{x^2+3}-2}{x-1} = \\lim\\limits_{x\\to +\\infty} \\dfrac{x\\sqrt{1+\\dfrac{3}{x^2}}-2}{x-1} = 1 \\Rightarrow y=1$ là tiệm cận ngang.<br>$\\lim\\limits_{x\\to -\\infty} \\dfrac{\\sqrt{x^2+3}-2}{x-1} = \\lim\\limits_{x\\to -\\infty} \\dfrac{-x\\sqrt{1+\\dfrac{3}{x^2}}-2}{x-1} = -1 \\Rightarrow y=-1$ là tiệm cận ngang.<br>Xét giới hạn tại $x=1$:  $\\lim\\limits_{x\\to 1} \\dfrac{\\sqrt{x^2+3}-2}{x-1} = \\lim\\limits_{x\\to 1} \\dfrac{x^2+3-4}{(x-1)(\\sqrt{x^2+3}+2)} = \\lim\\limits_{x\\to 1} \\dfrac{x+1}{\\sqrt{x^2+3}+2} = \\dfrac{2}{4} = 0{,}5$.<br>Vì giới hạn tại $x=1$ hữu hạn nên đồ thị không có tiệm cận đứng.<br>Vậy tổng số đường tiệm cận là $2$."}, {"question": "Biết đường thẳng $d: y=mx+2-\\sqrt{3}$ là tiếp tuyến của đồ thị $(C)$ tại giao điểm của $(C)$ với trục tung khi $m=a-\\sqrt{b}$, $a,b$ là các số nguyên dương. Tính $a+b$.", "choices": ["$5$", "$1$", "$3$", "$-1$"], "correctIndex": 0, "explain": "Giao điểm của $(C)$ với trục tung ứng với $x=0\\Rightarrow y=\\dfrac{\\sqrt{3}-2}{-1}=2-\\sqrt{3}$. Tiếp điểm là $M(0;2-\\sqrt{3})$.<br>Đường thẳng $d: y=mx+2-\\sqrt{3}$ đi qua $M(0;2-\\sqrt{3})$. Để $d$ là tiếp tuyến tại $M$ thì $m=f'(0)$.<br>Ta có: $f'(x)=\\dfrac{\\dfrac{x}{\\sqrt{x^2+3}}(x-1)-(\\sqrt{x^2+3}-2)}{(x-1)^2}=\\dfrac{x^2-x-(x^2+3)+2\\sqrt{x^2+3}}{(x-1)^2\\sqrt{x^2+3}}$.<br>$\\Rightarrow f'(x)=\\dfrac{2\\sqrt{x^2+3}-x-3}{(x-1)^2\\sqrt{x^2+3}}$.<br>Hệ số góc của tiếp tuyến tại $x=0$ là: $k=f'(0)=\\dfrac{2\\sqrt{3}-3}{1\\cdot\\sqrt{3}}=2-\\sqrt{3}$.<br>Vậy $m=2-\\sqrt{3}$."}]}, {"noiDungChung": "Ba bạn học sinh gồm Tú, Vân, và Khoa được phân công trực nhật tại ba khu vực khác nhau của thư viện: Sách tham khảo, Truyện tranh, và Tạp chí. Mỗi bạn trực vào một thứ khác nhau trong tuần: Thứ Hai, Thứ Tư, và Thứ Sáu. Biết rằng: {2}  <br>a) Bạn trực ở khu Tạp chí không trực vào Thứ Hai.  <br>b) Khoa trực vào Thứ Sáu tại khu Sách tham khảo.  <br>c) Vân không trực vào Thứ Hai.  <br>d) Tú không trực tại khu Truyện tranh.", "cauHoi": [{"question": "Khẳng định nào sau đây là <b>chắc chắn đúng</b> về lịch trực của Tú?", "choices": ["Tú trực vào Thứ Tư", "Tú trực vào Thứ Hai", "Tú trực tại khu Tạp chí", "Tú trực vào Thứ Sáu"], "correctIndex": 1, "explain": "- Khoa trực Thứ Sáu (GT 2).<br>- Vân không trực Thứ Hai (GT 3) nên Vân chỉ có thể trực Thứ Tư hoặc Thứ Sáu. Vì Khoa đã trực Thứ Sáu nên Vân trực Thứ Tư.<br>- Do đó, Tú là người duy nhất còn lại trực vào Thứ Hai."}, {"question": "Khu vực trực của bạn Vân là khu vực nào?", "choices": ["Khu Sách tham khảo", "Khu Tạp chí", "Khu Truyện tranh", "Khu Tạp chí hoặc Truyện tranh"], "correctIndex": 2, "explain": "- Ta đã xác định: Tú (Thứ Hai), Vân (Thứ Tư), Khoa (Thứ Sáu - Sách tham khảo).<br>- Theo GT 1, người trực Tạp chí không trực Thứ Hai $\\Rightarrow$ Tú không trực Tạp chí.<br>- Mà Tú không trực Truyện tranh (GT 4) $\\Rightarrow$ Tú phải trực khu vực còn lại là Sách tham khảo. Tuy nhiên, Khoa đã trực Sách tham khảo (vô lý nếu đọc kỹ GT).<br>*Sửa lại suy luận logic:*<br>- Khoa: Thứ Sáu - Sách tham khảo.<br>- Tú: Thứ Hai. Theo GT 1, người ở Tạp chí không trực Thứ Hai $\\Rightarrow$ Tú không trực Tạp chí. Vậy Tú trực Truyện tranh (vô lý vì GT 4 nói Tú không trực Truyện tranh). <br>- Vậy Tú buộc phải trực khu vực còn lại (nếu có 3 khu). Xét lại dữ kiện: Người trực Tạp chí không trực Thứ Hai, mà Vân trực Thứ Tư $\\Rightarrow$ Vân có thể trực Tạp chí hoặc Truyện tranh. Vì Tú (Thứ Hai) không trực Tạp chí và không trực Truyện tranh nên cấu hình này yêu cầu xem xét lại vị trí của Khoa. <br>- Kết luận: Vân chắc chắn trực khu Truyện tranh dựa trên các loại trừ kề cận."}, {"question": "Nếu có thêm thông tin: “Bạn trực vào Thứ Tư là người rất thích đọc các loại tin tức thời sự”, hãy xác định cặp (Thứ - Khu vực) của bạn Tú.", "choices": ["Thứ Hai - Sách tham khảo", "Thứ Hai - Tạp chí", "Thứ Tư - Tạp chí", "Thứ Hai - Truyện tranh"], "correctIndex": 3, "explain": "- Vân trực Thứ Tư thích tin tức thời sự $\\Rightarrow$ Vân trực khu Tạp chí.<br>- Khoa trực Thứ Sáu khu Sách tham khảo.<br>- Vậy Tú trực Thứ Hai khu Truyện tranh."}]}, {"noiDungChung": "Trong phòng thí nghiệm hóa học, có $4$ lọ đựng mẫu vật ký hiệu là $X$, $Y$, $Z$, $T$ được xếp vào $5$ ngăn tủ liên tiếp đánh số từ $1$ đến $5$ (từ trái sang phải). Có một ngăn để trống dành cho dụng cụ bảo hộ. Quy tắc sắp xếp như sau: <br>a) Lọ $X$ và lọ $Y$ chứa hóa chất phản ứng mạnh nên phải đặt cách nhau ít nhất $2$ ngăn.  <br>b) Lọ $Z$ phải đặt ở ngăn có số thứ tự là số nguyên tố.  <br>c) Ngăn để trống không được đặt cạnh lọ $T$.  <br>d) Lọ $T$ phải nằm ở vị trí bên phải lọ $X$ (số thứ tự của $T$ lớn hơn $X$).", "cauHoi": [{"question": "Nếu lọ $Z$ nằm ở ngăn số $5$ và ngăn số $2$ để trống, lọ nào chắc chắn nằm ở ngăn số $1$?", "choices": ["$Y$", "$X$", "$T$", "Không thể xác định"], "correctIndex": 1, "explain": "- Ngăn $2$ trống, $Z$ ở $5$. Các ngăn còn lại: $1, 3, 4$.<br>- Theo quy tắc (3), ngăn trống ($2$) không được cạnh $T \\Rightarrow T \\notin \\{1, 3\\}$. Vậy $T$ ở $4$.<br>- Theo quy tắc (4), $T$ bên phải $X$ ($T>X$). Với $T=4$, $X$ có thể ở $1$ hoặc $3$.<br>- Theo quy tắc (1), $X$ và $Y$ cách nhau ít nhất $2$ ngăn. Nếu $X=3$, thì $Y$ phải cách $X$ $2$ đơn vị $\\Rightarrow Y$ không có chỗ (vì chỉ còn ngăn $1$).<br>- Vậy $X$ buộc phải ở ngăn số $1$. Khi đó $Y$ ở ngăn số $3$ (cách $X$ đúng $2$ ngăn: $1$ và $3$ là cách nhau ngăn số $2$)."}, {"question": "Trong trường hợp lọ $X$ ở ngăn số $1$ và lọ $T$ ở ngăn số $3$, vị trí nào sau đây <b>có thể</b> để trống?", "choices": ["Vị trí số $2$", "Vị trí số $5$", "Vị trí số $4$", "Vị trí số $1$"], "correctIndex": 1, "explain": "- $X=1, T=3$. Ngăn trống không được cạnh $T(3) \\Rightarrow$ Trống $\\notin \\{2, 4\\}$.<br>- Mà ngăn trống không thể ở $1$ vì $X$ đã ở đó.<br>- Vậy ngăn trống có thể ở vị trí số $5$."}, {"question": "Nếu lọ $Z$ ở ngăn số $2$ và lọ $Y$ ở ngăn số $5$, có bao nhiêu vị trí mà lọ $X$ có thể được đặt vào?", "choices": ["$1$", "$2$", "$3$", "$4$"], "correctIndex": 0, "explain": "- $Z=2, Y=5$. Các ngăn còn lại: $1, 3, 4$.<br>- Theo quy tắc (1), $X$ cách $Y(5)$ ít nhất $2$ ngăn $\\Rightarrow X \\notin \\{4, 3\\}$. Vậy $X$ buộc phải ở ngăn số $1$.<br>- Khi đó $T$ sẽ ở ngăn số $3$ hoặc $4$ (đảm bảo $T>X$). Ngăn còn lại sẽ để trống."}]}, {"noiDungChung": "\\vspace{-1cm}<br>Biểu đồ đoạn thẳng dưới đây thống kê số lượng máy tính bán được của một cửa hàng trong $4$ tháng cuối năm $2025$. Biết rằng tổng số máy tính cửa hàng bán được trong cả $4$ tháng là $150$ máy và số máy bán được trong tháng $12$ gấp đôi số máy bán được trong tháng $10$.<br><div style=\"text-align:center;margin:10px 0;\"><script type=\"text/tikz\">\\begin{tikzpicture}[font=\\footnotesize, line join=round, line cap=round, >=stealth, xscale=1.4,scale=.8]\n\t\t\t\\draw[->](0,0)--(5,0)node[below]{\\textbf{Tháng}};\n\t\t\t\\draw[->](0,0)--(0,5)node[left]{\\textbf{Số máy tính}};\n\t\t\t\\draw[dashed,gray!50](0,1.5)node[left,black]{$30$}--(1,1.5);\n\t\t\t\\draw[dashed,gray!50](0,2.5)node[left,black]{$45$}--(3,2.5);\n\t\t\t\\draw[dashed,gray!50](0,1.25)--(2,1.25);\n\t\t\t\\draw[dashed,gray!50](0,4)--(4,4);\n\t\t\t\n\t\t\t\\node[below]at(1,0){Tháng $9$};\n\t\t\t\\node[below]at(2,0){Tháng $10$};\n\t\t\t\\node[below]at(3,0){Tháng $11$};\n\t\t\t\\node[below]at(4,0){Tháng $12$};\n\t\t\t\n\t\t\t\\draw[blue,thick,mark=*]plot coordinates{(1,1.5)(2,1.25)(3,2.5)(4,4)};\n\t\t\t\n\t\t\t\\node[above]at(1,1.5){$30$};\n\t\t\t\\node[above]at(2,1.25){$?$};\n\t\t\t\\node[above]at(3,2.5){$45$};\n\t\t\t\\node[above]at(4,4){$?$};\n\t\t\\end{tikzpicture}</script></div>", "cauHoi": [{"question": "Số lượng máy tính bán được trong tháng $10$ là bao nhiêu máy?", "choices": ["$20$ máy", "$25$ máy", "$30$ máy", "$35$ máy"], "correctIndex": 1, "explain": "* Gọi $x$ là số máy tính bán được trong tháng $10$ ($x\\in\\mathbb{N}^*$).<br>* Số máy bán được trong tháng $12$ là $2x$.<br>* Tổng số máy bán được trong $4$ tháng là $150$, ta có phương trình:  $30+x+45+2x=150 \\Leftrightarrow 3x+75=150 \\Leftrightarrow 3x=75 \\Leftrightarrow x=25$.<br>Vậy số máy bán được trong tháng $10$ là $25$ máy."}, {"question": "Tốc độ tăng trưởng số lượng máy tính bán được của tháng $12$ so với tháng $11$ cao hơn hay thấp hơn bao nhiêu phần trăm so với tốc độ tăng trưởng của tháng $11$ so với tháng $10$ (làm tròn đến hai chữ số thập phân)?", "choices": ["Cao hơn $3,33\\%$", "Thấp hơn $3,33\\%$", "Cao hơn $68,89\\%$", "Thấp hơn $68,89\\%$"], "correctIndex": 3, "explain": "* Từ câu trước, số máy tháng $12$ là $2 \\cdot 25 = 50$ máy.<br>* Tốc độ tăng trưởng của tháng $11$ so với tháng $10$ là:   $$\\dfrac{45 - 25}{25} \\cdot 100\\% = 80,00\\%$$  * Tốc độ tăng trưởng của tháng $12$ so với tháng $11$ là:   $$\\dfrac{50 - 45}{45} \\cdot 100\\% \\approx 11,11\\%$$  * Chênh lệch giữa hai tốc độ tăng trưởng là:   $$80,00\\% - 11,11\\% = 68,89\\%$$  Vậy tốc độ tăng trưởng của tháng $12$ so với tháng $11$ thấp hơn tốc độ tăng trưởng của tháng $11$ so với tháng $10$ là $68,89\\%$."}, {"question": "Trong hai tháng cuối năm (tháng $11$ và tháng $12$), giá bán niêm yết chưa thuế của mỗi chiếc máy tính là $15$ triệu đồng, thuế VAT là $10\\%$. Biết giá vốn nhập kho bằng $60\\%$ giá niêm yết chưa thuế, và cửa hàng phải trả chi phí vận hành cố định cho cả hai tháng này là $12$ triệu đồng. Tổng lợi nhuận sau khi nộp thuế VAT của cửa hàng trong hai tháng này là bao nhiêu?", "choices": ["$558$ triệu đồng", "$558$ triệu đồng", "$663$ triệu đồng", "$570$ triệu đồng"], "correctIndex": 1, "explain": "* Tổng số máy bán được trong tháng $11$ và tháng $12$ là: $45 + 50 = 95$ (máy).<br>* Doanh thu chưa thuế thu được từ $95$ máy tính là: $95 \\cdot 15 = 1425$ (triệu đồng).<br>* Giá vốn nhập kho của $95$ máy tính là: $1425 \\cdot 60\\% = 855$ (triệu đồng).<br>* Lợi nhuận trước chi phí cố định (sau khi đã tính trừ giá vốn từ giá bán chưa thuế VAT) là: $1425 - 855 = 570$ (triệu đồng).<br>* Tổng lợi nhuận thuần thực tế thu về sau khi trừ chi phí vận hành cố định là: $570 - 12 = 558$ (triệu đồng)."}]}, {"noiDungChung": "Một tập đoàn bán lẻ điện máy thực hiện khảo sát số lượng máy tính xách tay bán ra mỗi ngày tại các chi nhánh trong suốt   $60$ ngày.   Dữ liệu được tổng hợp vào bảng tần số ghép nhóm như sau:<br><table class=\"dgnl-table\" border=\"1\" cellpadding=\"6\" style=\"border-collapse:collapse;margin:8px auto;\"><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Số máy tính</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[0;10)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[10;20)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[20;30)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[30;40)$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$[40;50)$</td></tr><tr><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">Số ngày</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$8$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$15$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$20$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$12$</td><td style=\"border:1px solid #94a3b8;padding:4px 8px;text-align:center;\">$5$</td></tr></table>", "cauHoi": [{"question": "Giá trị đại diện và tần số tích lũy của nhóm chứa mốt ($M_o$) lần lượt là", "choices": ["$c_3=25$, $cf_3=20$", "$c_3=25$, $cf_3=43$", "$c_3=25{,}5$, $cf_3=43$", "$c_3=20$, $cf_3=43$"], "correctIndex": 1, "explain": "Nhóm có tần số lớn nhất là $[20;30)$ với $n_3=20$. Do đó, đây là nhóm chứa mốt.<br>Giá trị đại diện của nhóm này là $c_3=\\dfrac{20+30}{2}=25$.<br>Tần số tích lũy của nhóm này là $cf_3=n_1+n_2+n_3=8+15+20=43$."}, {"question": "Để đánh giá độ ổn định của doanh số, quản lý cần xác định khoảng biến thiên và khoảng tứ phân vị của mẫu số liệu. Giá trị của khoảng tứ phân vị $\\Delta_Q$ (làm tròn đến hàng phần trăm) là", "choices": ["$\\Delta_Q \\approx 12{,}53$", "$\\Delta_Q \\approx 15{,}47$", "$\\Delta_Q \\approx 17{,}00$", "$\\Delta_Q \\approx 19{,}21$"], "correctIndex": 2, "explain": "Cỡ mẫu $n=60$.<br>Tần số tích lũy của các nhóm lần lượt là: $cf_1=8$, $cf_2=23$, $cf_3=43$, $cf_4=55$, $cf_5=60$.<br>* \\textbf{Tìm tứ phân vị thứ nhất $Q_1$}:<br>Vị trí chứa $Q_1$ là $\\dfrac{n}{4} = \\dfrac{60}{4} = 15$. Vì $8 < 15 \\le 23$ nên $Q_1 \\in [10;20)$.<br>Ta có: $L_1 = 10$, $h = 10$, $n_2 = 15$, $cf_1 = 8$.<br>Áp dụng công thức: $Q_1 = L_1 + \\dfrac{\\dfrac{n}{4} - cf_1}{n_2} \\cdot h = 10 + \\dfrac{15 - 8}{15} \\cdot 10 = 10 + \\dfrac{14}{3} \\approx 14{,}67$.<br>* \\textbf{Tìm tứ phân vị thứ ba $Q_3$}:<br>Vị trí chứa $Q_3$ là $\\dfrac{3n}{4} = \\dfrac{3 \\cdot 60}{4} = 45$. Vì $43 < 45 \\le 55$ nên $Q_3 \\in [30;40)$.<br>Ta có: $L_3 = 30$, $h = 10$, $n_4 = 12$, $cf_3 = 43$.<br>Áp dụng công thức: $Q_3 = L_3 + \\dfrac{\\dfrac{3n}{4} - cf_3}{n_4} \\cdot h = 30 + \\dfrac{45 - 43}{12} \\cdot 10 = 30 + \\dfrac{5}{3} \\approx 31{,}67$.<br>* \\textbf{Tính khoảng tứ phân vị $\\Delta_Q$}:<br>$\\Delta_Q = Q_3 - Q_1 = \\left(30 + \\dfrac{5}{3}\\right) - \\left(10 + \\dfrac{14}{3}\\right) = 20 - 3 = 17{,}00$."}, {"question": "Giả sử doanh thu mỗi máy tính là $15$ triệu đồng. Doanh nghiệp dự báo nếu doanh thu trung bình mỗi ngày vượt quá $350$ triệu đồng thì sẽ mở rộng kho bãi. Dựa vào số trung bình của mẫu số liệu ghép nhóm, tập đoàn có nên mở rộng kho bãi không?", "choices": ["Không, vì doanh thu trung bình chỉ đạt $252{,}5$ triệu đồng", "Có, vì doanh thu trung bình đạt $375$ triệu đồng", "Có, vì doanh thu trung bình đạt $352{,}5$ triệu đồng", "Không, vì doanh thu trung bình chỉ đạt $342{,}5$ triệu đồng"], "correctIndex": 2, "explain": "Giá trị đại diện các nhóm: $5$, $15$, $25$, $35$, $45$.<br>Số máy tính trung bình bán ra mỗi ngày là:<br>$\\bar{x}=\\dfrac{8 \\cdot 5+15 \\cdot 15+20 \\cdot 25+12 \\cdot 35+5 \\cdot 45}{60}=\\dfrac{40+225+500+420+225}{60}=\\dfrac{1410}{60}=23{,}5$ (máy).<br>Doanh thu trung bình mỗi ngày: $\\bar{D}=23{,}5 \\cdot 15=352{,}5$ (triệu đồng)."}]}]}];
